-- @stmt 旧模块 VIEW MTC_VIEW_Document
CREATE VIEW "MTC_VIEW_Document" ("ObjType", "DocEntry", "DocNum", "CANCELED", "CardCode", "DocDate", "LineNum", "ItemCode", "OcrCode", "OcrCode2", "OcrCode3", "OcrCode4", "OcrCode5", "Project", "BaseType", "BaseEntry", "BaseRef", "BaseLine", "U_BusiType", "U_YWLX", "Comments", "TransId", "TransCode", "AcctCode", "CogsAcct", "U_SupNum") AS (((((((((((((SELECT
	 T0."ObjType",
	 T0."DocEntry",
	 T0."DocNum" ,
	 T0."CANCELED",
	 T0."CardCode" ,
	 T0."DocDate",
	 T1."LineNum" ,
	 T1."ItemCode",
	 T1."OcrCode" ,
	 T1."OcrCode2",
	 T1."OcrCode3" ,
	 T1."OcrCode4",
	 T1."OcrCode5" ,
	 T1."Project" ,
	 TO_CHAR(T1."BaseType"),
	 T1."BaseEntry",
	 TO_CHAR(T1."BaseRef"),
	 T1."BaseLine" ,
	 '' AS "U_BusiType" ,
	 '' AS "U_YWLX" ,
	 T0."Comments" ,
	 T0."TransId" ,
	 '' AS "TransCode",
	 T1."AcctCode",
	 T1."CogsAcct",
	 T0."U_SupNum" 
													FROM "ORDR" T0 JOIN "RDR1" T1 ON T0."DocEntry"=T1."DocEntry" 
													WHERE 1=1) UNION ALL (SELECT
	 T0."ObjType",
	 T0."DocEntry",
	 T0."DocNum" ,
	 T0."CANCELED",
	 T0."CardCode" ,
	 T0."DocDate",
	 T1."LineNum" ,
	 T1."ItemCode",
	 T1."OcrCode" ,
	 T1."OcrCode2",
	 T1."OcrCode3" ,
	 T1."OcrCode4",
	 T1."OcrCode5" ,
	 T1."Project" ,
	 TO_CHAR(T1."BaseType"),
	 T1."BaseEntry",
	 TO_CHAR(T1."BaseRef"),
	 T1."BaseLine" ,
	 '' AS "U_BusiType" ,
	 '' AS "U_YWLX" ,
