-- @stmt 旧模块 VIEW MTC_VIEW_ProductDetail
CREATE VIEW "MTC_VIEW_ProductDetail" AS (((((((((SELECT
	 1 AS "ID" ,
	 '主件' AS "Type" ,
	 '生产收货' AS "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry" ,
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 (T5."SumStock"+T5."PriceDiff"+T5."VarVal") "Amt" 
									FROM OIGN T0 JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."BaseRef",
	 0) 
									AND T1."BaseType" = '202' 
									AND T1."BaseLine" IS NULL 
									LEFT JOIN OIVL T5 ON T5."TransType" = T0."ObjType" 
									AND T5."CreatedBy" = T0."DocEntry" 
									AND T1."LineNum" = T5."DocLineNum") UNION ALL (SELECT
	 2 AS "ID" ,
	 '子件' AS "Type" ,
	 '生产发料' "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry" ,
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 -T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 (T5."SumStock"+T5."PriceDiff"+T5."VarVal") "Amt" 
									FROM OIGE T0 JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."BaseRef",
	 0) 
									AND T1."BaseType" = '202' 
									AND T1."BaseLine" IS NOT NULL JOIN OIVL T5 ON T5."TransType" = T0."ObjType" 
									AND T5."CreatedBy" = T0."DocEntry" 
									AND T1."LineNum" = T5."DocLineNum")) UNION ALL (SELECT
	 1 AS "ID" ,
	 '子件' AS "Type" ,
	 '子件退货' "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry" ,
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 (T5."SumStock"+T5."PriceDiff"+ T5."VarVal") 
								FROM OIGN T0 JOIN IGN1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."BaseRef",
	 0) 
								AND T1."BaseType" = '202' 
								AND T1."BaseLine" IS NOT NULL JOIN OIVL T5 ON T5."TransType" = T0."ObjType" 
								AND T5."CreatedBy" = T0."DocEntry" 
								AND T1."LineNum" = T5."DocLineNum")) UNION ALL (SELECT
	 2 AS "ID" ,
	 '主件' AS "Type" ,
	 '分拆发货' "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry",
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 -T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 (T5."SumStock"+T5."PriceDiff"+ T5."VarVal") 
							FROM OIGE T0 JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."BaseRef",
	 0) 
							AND T1."BaseType" = '202' 
							AND T1."BaseLine" IS NULL JOIN OIVL T5 ON T5."TransType" = T0."ObjType" 
							AND T5."CreatedBy" = T0."DocEntry" 
							AND T1."LineNum" = T5."DocLineNum")) UNION ALL (SELECT
	 2 AS "ID" ,
	 '子件' AS "Type" ,
	 '费用' "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry" ,
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 -T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 -T1."LineTotal" AS "Amt" 
						FROM OIGE T0 JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."BaseRef",
	 0) 
						AND T1."BaseType" = '202' 
						AND T1."BaseLine" IS NOT NULL JOIN OITM T3 ON T1."ItemCode"=T3."ItemCode" 
						WHERE 1=1 
						AND T3."InvntItem" = 'N')) UNION ALL (SELECT
	 3 AS "ID" ,
	 '子件' AS "Type" ,
	 '委外费用收货' "BusiType" ,
	 T0."ObjType",
	 T3."DocEntry" AS "OWOREntry",
	 T3."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 CASE WHEN T0."CANCELED"='C' 
					THEN 1 
					ELSE -1 
					END*(T1."Quantity"-IFNULL(T4."RpdQty",
	 0)) AS "Quantity" ,
	 T1."unitMsr" ,
	 T1."Price" AS "Price" ,
	 CASE WHEN T0."CANCELED"='C' 
					THEN 1 
					ELSE -1 
					END*(T1."LineTotal"-IFNULL(T4."RpdTotal",
	 0)) AS "LineTotal" 
					FROM OPDN T0 JOIN PDN1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN (SELECT
	 "ObjType",
	 "DocEntry",
	 "BaseRef",
	 SUM("Quantity") AS "Quantity" 
						FROM IGN1 
						GROUP BY "ObjType",
	 "DocEntry",
	 "BaseRef") T2 ON T1."U_BaseType"=T2."ObjType" 
					AND T1."U_BaseEntry"=T2."DocEntry" 
					AND T1."U_OWORNum"=IFNULL(T2."BaseRef",
	 0) JOIN OWOR T3 ON T3."DocNum" = IFNULL(T2."BaseRef",
	 0) 
					LEFT JOIN (SELECT
	 D."BaseType",
	 D."BaseEntry",
	 D."BaseLine",
	 SUM(D."Quantity") AS "RpdQty",
	 SUM(D."LineTotal") AS "RpdTotal" 
						FROM ORPD M JOIN "RPD1" D ON M."DocEntry"=D."DocEntry" 
						WHERE M."CANCELED"='N' 
						GROUP BY D."BaseType",
	 D."BaseEntry",
	 D."BaseLine" ) T4 ON T1."ObjType"=T4."BaseType" 
					AND T1."DocEntry"=T4."BaseEntry" 
					AND T1."LineNum"=T4."BaseLine")) UNION ALL (SELECT
	 4 AS "ID" ,
	 '子件' AS "Type" ,
	 '委外费用发票暂估差异' "BusiType" ,
	 T0."ObjType",
	 T13."DocEntry" AS "OWOREntry",
	 T13."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum1" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 0 AS "Quantity" ,
	 T1."unitMsr" ,
	 T1."Price" AS "Price" ,
	 CASE WHEN T0."CANCELED"='C' 
				THEN 1 
				ELSE -1 
				END*(T1."LineTotal"-T1."Quantity"*T2."Price") AS "LineTotal" 
				FROM "OPCH" T0 
				INNER JOIN "PCH1" T1 ON T0."DocEntry"=T1."DocEntry" JOIN (SELECT
	 M."ObjType",
	 D."DocEntry",
	 M."DocNum",
	 D."LineNum",
	 D."U_BaseType",
	 D."U_BaseEntry",
	 D."U_OWORNum" ,
	 CASE WHEN IFNULL(D."U_InitPrice",
	 0)<>0 
					THEN D."U_InitPrice" 
					ELSE D."Price" 
					END AS "Price" ,
	 M2."U_OldSysNo" "OPOROldSN",
	 M."U_OldSysNo" "OPDNOldSN" 
					FROM "OPDN" M JOIN "PDN1" D ON M."DocEntry"=D."DocEntry" 
					LEFT JOIN "POR1" D2 ON D."BaseEntry" =D2."DocEntry" 
					AND D."BaseLine" =D2."LineNum" 
					AND D."BaseType"=D2."ObjType" 
					LEFT JOIN "OPOR" M2 ON D2."DocEntry" =M2."DocEntry" ) T2 ON T1."BaseType"=T2."ObjType" 
				AND T1."BaseEntry"=T2."DocEntry" 
				AND T1."BaseLine"=T2."LineNum" JOIN (SELECT
	 "ObjType",
	 "DocEntry",
	 "BaseRef",
	 SUM("Quantity") AS "Quantity" 
					FROM IGN1 
					GROUP BY "ObjType",
	 "DocEntry",
	 "BaseRef") T12 ON T2."U_BaseType"=T12."ObjType" 
				AND T2."U_BaseEntry"=T12."DocEntry" 
				AND T2."U_OWORNum"=IFNULL(T12."BaseRef",
	 0) JOIN OWOR T13 ON T13."DocNum" = IFNULL(T12."BaseRef",
	 0) 
				WHERE 1=0 
				AND T0."CANCELED"='N')) UNION ALL (SELECT
	 9 AS "ID" ,
	 '日记账分录' AS "Type" ,
	 '日记账分录' "BusiType" ,
	 '30',
	 T0."DocEntry" AS "OWOREntry" ,
	 T0."DocNum" AS "OWORNum" ,
	 '' AS "U_TrsName",
	 T0."TransId",
	 T0."TransId" AS "DocNum1" ,
	 0 as "LineNum",
	 0 AS "BaseLine",
	 T0."CreateDate",
	 T2."RefDate" ,
	 T0."ItemCode" ,
	 T0."Warehouse" ,
	 T0."PlannedQty" ,
	 '' AS "unit" ,
	 0 AS "Price" ,
	 -T3."Amt" AS "Amt" 
			FROM OWOR T0 JOIN OJDT T2 ON T0."TransId"=T2."TransId" JOIN (SELECT
	 "TransId",
	 SUM("Debit"-"Credit") AS "Amt" 
				FROM "JDT1" 
				WHERE "Account"='500101' 
				GROUP BY "TransId") T3 ON T2."TransId"=T3."TransId" 
			WHERE 1=1)) UNION ALL (SELECT
	 10 AS "ID" ,
	 '主件' AS "Type" ,
	 '生产退货' AS "BusiType" ,
	 T0."ObjType",
	 T2."DocEntry" AS "OWOREntry" ,
	 T2."DocNum" AS "OWORNum" ,
	 T0."U_TrsName",
	 T0."DocEntry",
	 T0."DocNum" AS "DocNum" ,
	 T1."LineNum",
	 T1."BaseLine",
	 T0."CreateDate",
	 T0."DocDate" ,
	 T1."ItemCode" ,
	 T1."WhsCode" ,
	 -1*T1."Quantity" ,
	 T1."unitMsr" ,
	 T1."StockPrice" AS "Price" ,
	 -1*(T5."SumStock"+T5."PriceDiff"+T5."VarVal") "Amt" 
		FROM OIGE T0 JOIN IGE1 T1 ON T0."DocEntry" = T1."DocEntry" JOIN OWOR T2 ON T2."DocNum" = IFNULL(T1."U_OWORNum",
	 0) 
		AND T1."U_OWORType" = '202' 
		AND T1."BaseLine" IS NULL 
		LEFT JOIN OIVL T5 ON T5."TransType" = T0."ObjType" 
		AND T5."CreatedBy" = T0."DocEntry" 
		AND T1."LineNum" = T5."DocLineNum" 
		WHERE T0."U_Type"='OWOR1'))

@@
-- @stmt 旧模块 VIEW MTC_VIEW_ProductDetail_MTCOWOR
CREATE VIEW "MTC_VIEW_ProductDetail_MTCOWOR" AS SELECT
	 CASE WHEN T14."DocEntry" IS NULL 
THEN '子件' 
ELSE '主件' 
END AS "Type",
	 T0."TransType",
	 T9."DocName",
	 T4."U_TrsName",
	 T0."CreatedBy",
	 T0."BASE_REF",
	 T0."DocLineNum",
	 T0."DocDate",
	 T10."Code" AS "BusiType",
	 T10."Name" AS "BusiTypeN",
	 T11."Code" AS "TransCode",
	 T11."Name" AS "TransName",
	 T0."ItemCode",
	 T2."ItemName",
	 T2."ItmsGrpCod",
	 T0."InQty"-T0."OutQty" AS "Quantity",
	 T4."U_OWORType" AS "BaseType",
	 COALESCE(T13."DocEntry",
	 T14."DocEntry") AS "BaseEntry",
	 T12."LineId" AS "BaseLine",
	 COALESCE(T13."U_ItemCode",
	 T14."U_ItemCode") AS "MainItemCode",
	 T4."AcctCode" AS "AcctCode",
	 T52."AcctName" AS "AcctName" 
FROM OIVL T0 
LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode" JOIN ( SELECT
	 M."ObjType",
	 M."DocEntry",
	 D."LineNum",
	 D."AcctCode",
	 M."U_TrsName",
	 D."U_OWORType",
	 D."U_MTCOWORNum",
	 D."U_MTCOWORLineNum" 
	FROM IGN1 D JOIN OIGN M ON M."DocEntry"=D."DocEntry" 
	UNION ALL SELECT
	 M."ObjType",
	 M."DocEntry",
	 D."LineNum",
	 D."AcctCode",
	 M."U_TrsName",
	 D."U_OWORType",
	 D."U_MTCOWORNum",
	 D."U_MTCOWORLineNum" 
	FROM IGE1 D JOIN OIGE M ON M."DocEntry"=D."DocEntry" ) T4 ON T0."TransType"=T4."ObjType" 
AND T0."CreatedBy"=T4."DocEntry" 
AND T0."DocLineNum"=T4."LineNum" 
LEFT JOIN "MTC_DocType" T9 ON TO_CHAR(T0."TransType")=T9."ObjType" 
LEFT JOIN "@U_CIOTRN" T10 ON T4."U_TrsName"=T10."Code" 
LEFT JOIN "@MTC_COST_IOTYPE" T11 ON T10."U_IOType"=T11."Code" 
LEFT JOIN "@MTC_WOR1" T12 ON T4."U_OWORType"=T12."Object" 
AND T4."U_MTCOWORNum"=TO_CHAR(T12."DocEntry") 
AND T4."U_MTCOWORLineNum"=TO_CHAR(T12."LineId") 
LEFT JOIN "@MTC_OWOR" T13 ON T12."DocEntry"=T13."DocEntry" 
LEFT JOIN "@MTC_OWOR" T14 ON T4."U_OWORType"=T14."Object" 
AND T4."U_MTCOWORNum"=TO_CHAR(T14."DocEntry") 
AND IFNULL(T4."U_MTCOWORLineNum",
	 '')='' 
LEFT JOIN OACT T52 ON T4."AcctCode"=T52."AcctCode" 
WHERE 1=1 
AND T4."U_OWORType"='MTC_OWOR'

@@
-- @stmt 旧模块 VIEW MTC_VW_DOCLINE
CREATE VIEW "MTC_VW_DOCLINE" AS SELECT
	 L0."LogEntry",
	 T0."DocDate",
	 L0."DocType" "ObjType",
	 L0."DocEntry",
	 "DocLine" "LineNum",
	 L0."ItemCode",
	 L0."ItemName",
	 T0."LocCode",
	 L1."MdAbsEntry" "BatchEntry" ,
	 TN."DistNumber" "BatchNumber" ,
	 IFNULL(TL."Quantity",
	 L1."Quantity") "Quantity" ,
	 WH."WhsCode",
	 WH."WhsName" ,
	 BN."AbsEntry" "BinEntry",
	 BN."BinCode" 
FROM OIVL T0 JOIN OITL L0 ON T0."TransType"=L0."DocType" 
AND T0."CreatedBy"=L0."DocEntry" 
AND T0."DocLineNum"=L0."DocLine" 
AND T0."LocCode"=L0."LocCode" JOIN ITL1 L1 ON L1."LogEntry" = L0."LogEntry" JOIN OWHS WH ON WH."WhsCode" = T0."LocCode" 
LEFT JOIN OBTL TL ON TL."ITLEntry" = L1."LogEntry" 
AND L1."MdAbsEntry" = TL."SnBMDAbs" --库位交易日志
JOIN OBTN TN ON TN."AbsEntry" = IFNULL(TL."SnBMDAbs",
	 L1."MdAbsEntry") --批次表
 
LEFT JOIN OBIN BN ON BN."AbsEntry" = TL."BinAbs" ORDER BY L0."DocType" ,
	 L0."DocEntry",
	 L0."DocLine"

@@
-- @stmt 旧模块 FUNCTION MTC_COST_FC_DOCDETAIL
CREATE FUNCTION MTC_COST_FC_DOCDETAIL
(	
	 BPLId 	INT
	,FcCode NVARCHAR(50)
	,ItemCode NVARCHAR(50) DEFAULT ''
)
RETURNS TABLE (
	 "BPLId"			INT
	,"ObjType"			NVARCHAR(50)
	,"DocEntry"			INT
	,"DocNum"			INT
	,"CardCode"			NVARCHAR(50)
	,"CardName"			NVARCHAR(50)
	,"LineNum"			INT
	,"FcCode"			NVARCHAR(7)
	,"DocDate"			DATE
	,"CostCode"			NVARCHAR(50)		--归入成本计价类型
	,"TransCode"		NVARCHAR(50)		--实际交易类型
	,"BaseType"			NVARCHAR(50)
	,"BaseEntry"		INT
	,"BaseNum"			NVARCHAR(50)
	,"BaseLine"			INT
	,"ItemCode"			NVARCHAR(100)
	,"ItemName"			NVARCHAR(254)
	,"EvalSystem"		NVARCHAR(50)
	,"ItmsGrpCod"		NVARCHAR(100)
	,"CalType"			NVARCHAR(100)	--成本计价类型
	,"Quantity"			DECIMAL(19,6)
	,"Amount"			DECIMAL(19,6)
	,"Price"			DECIMAL(19,6)
	,"WhsCode"			NVARCHAR(50)
	,"WorType"			NVARCHAR(50)
	,"WorEntry"			INT
	,"WorNum"			NVARCHAR(50)
	,"WorLineNum"		INT
	,"CJCode"			NVARCHAR(50)
	,"CJName"			NVARCHAR(50)
	,"OcrCode1"			NVARCHAR(50)
	,"OcrCode2"			NVARCHAR(50)
	,"OcrCode3"			NVARCHAR(50)
	,"OcrCode4"			NVARCHAR(50)
	,"OcrCode5"			NVARCHAR(50)
	,"User"				NVARCHAR(100)
	,"TransId"			INT
	,"Comments"			NVARCHAR(500)
)
LANGUAGE SQLSCRIPT
AS

BEGIN
	
	/* 
	 * created BY Chris.li 2024.11.23
	 * 获取成本计算的所有出入库的单据
	 * SELECT * FROM "MTC_COST_FC_DOCDETAIL"(0,'2024-01');
     * 数量Quantity和金额Amount展示形式 入库表示正数  出库表示负数
	*/
	
	TMP_DETAIL=
	--20 采购收货单
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType") AS "BaseType",T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "OPDN" T0
	JOIN "PDN1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--21 采购退货单
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType") AS "BaseType",T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "ORPD" T0
	JOIN "RPD1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--18  应付发票
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType"),T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "OPCH" T0
	JOIN "PCH1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--19 应付贷项凭证
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType"),T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "ORPC" T0
	JOIN "RPC1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--59  库存收货&生产收货
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",T0."U_TrsName" AS "TransCode",
	 CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN '202' WHEN T1."BaseType"=-1 AND T1."U_OWORType"='MTC_OWOR' THEN 'MTC_OWOR' ELSE TO_CHAR(T1."BaseType") END AS "BaseType",
	 COALESCE(T4."DocEntry",T1."BaseEntry",T1."U_MTCOWORNum") AS "BaseEntry",
	 TO_CHAR(COALESCE(T4."DocNum",T1."BaseRef",T1."U_MTCOWORNum")) AS "BaseNum",
	 CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN T1."U_OWORLineNum" WHEN T1."BaseType"=-1 AND T1."U_OWORType"='MTC_OWOR' THEN T1."U_MTCOWORLineNum" ELSE T1."BaseLine" END
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,T1."Quantity" AS "Quantity",T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "OIGN" T0
	JOIN "IGN1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN OWOR T4 ON CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN '202' ELSE T1."BaseType" END='202'
				AND CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN T1."U_OWORNum" ELSE T1."BaseRef" END=T4."DocNum"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--60 库存发货&生产发货
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",T0."U_TrsName" AS "TransCode",
	 CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN '202' WHEN T1."BaseType"=-1 AND T1."U_OWORType"='MTC_OWOR' THEN 'MTC_OWOR' ELSE TO_CHAR(T1."BaseType") END AS "BaseType",
	 COALESCE(T4."DocEntry",T1."BaseEntry",T1."U_MTCOWORNum") AS "BaseEntry",
	 TO_CHAR(COALESCE(T4."DocNum",T1."BaseRef",T1."U_MTCOWORNum")) AS "BaseNum",
	 CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN T1."U_OWORLineNum" WHEN T1."BaseType"=-1 AND T1."U_OWORType"='MTC_OWOR' THEN T1."U_MTCOWORLineNum" ELSE T1."BaseLine" END
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,-1*T1."Quantity" AS "Quantity",-1*T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "OIGE" T0
	JOIN "IGE1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN OWOR T4 ON CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN '202' ELSE T1."BaseType" END='202'
				AND CASE WHEN T1."BaseType"=-1 AND T1."U_OWORType"='202' THEN T1."U_OWORNum" ELSE T1."BaseRef" END=T4."DocNum"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	
	--15  销售交货
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType"),T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "ODLN" T0
	JOIN "DLN1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	--16 销售退货
	UNION ALL
	SELECT T0."BPLId",T0."ObjType",T0."DocEntry",T0."DocNum",T0."CardCode",T0."CardName",T1."LineNum",LEFT(T0."DocDate",7) AS "FcCode"
	,T0."DocDate",'' AS "CostCode",'' AS "TransCode",TO_CHAR(T1."BaseType"),T1."BaseEntry",T1."BaseRef" AS "BaseNum",T1."BaseLine"
	,T1."ItemCode",T1."Dscription" AS "ItemName",T2."EvalSystem",T2."ItmsGrpCod",T3."U_ItemGrpType" AS "CalType"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."Quantity" AS "Quantity"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."LineTotal" AS "Amount",T1."Price",T1."WhsCode"
	,NULL AS "WorType",NULL AS "WorEntry",NULL AS "WorNum",NULL AS "WorLineNum"
	,NULL AS "CJCode",NULL AS "CJName"
	,T1."OcrCode" AS "OcrCode1",T1."OcrCode2",T1."OcrCode3",T1."OcrCode4",T1."OcrCode5"
	,T0."UserSign" AS "User",T0."TransId",T0."Comments"
	FROM "ORDN" T0
	JOIN "RDN1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	JOIN "OITB" T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	WHERE 1=1
	AND LEFT(T0."DocDate",7) = :FcCode
	AND (T1."ItemCode" = :ItemCode OR :ItemCode = '')
	
	;
	
	return
	
	SELECT "BPLId"
	,"ObjType"
	,"DocEntry"
	,"DocNum"
	,"CardCode"
	,"CardName"
	,"LineNum"
	,"FcCode"
	,"DocDate"
	,"CostCode"		--归入成本计价类型
	,"TransCode"		--实际交易类型
	,"BaseType"
	,"BaseEntry"
	,"BaseNum"
	,"BaseLine"
	,"ItemCode"
	,"ItemName"
	,"EvalSystem"
	,"ItmsGrpCod"
	,"CalType"	--成本计价类型
	,"Quantity"
	,"Amount"
	,"Price"
	,"WhsCode"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"WorLineNum"
	,"CJCode"
	,"CJName"
	,"OcrCode1"
	,"OcrCode2"
	,"OcrCode3"
	,"OcrCode4"
	,"OcrCode5"
	,"User"
	,"TransId"
	,"Comments"
	FROM :TMP_DETAIL;
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PERIOD_CALC
CREATE PROCEDURE "MTC_COST_PERIOD_CALC" (
      IN iv_FcCode NVARCHAR(50)
  )
  LANGUAGE SQLSCRIPT
  SQL SECURITY INVOKER
  AS
  BEGIN
      DECLARE lv_level     INTEGER := 1;
      DECLARE lv_max_level INTEGER := 1;
      DECLARE lv_count     INTEGER := 0;
  
      -- 清除当期明细旧数据
      DELETE FROM "MTC_COST_ROLLUP_DETAIL" WHERE "FcCode" = :iv_FcCode;
  
      -- 获取最大物料等级
      SELECT COALESCE(MAX("iLevel"), 1) INTO lv_max_level
      FROM "U_COILV" WHERE "FcCode" = :iv_FcCode;
  
      -- =====================================================
      -- 收发存数量+金额基准
      -- =====================================================
      lt_invnt =
          SELECT
              T0."FcCode",
              T0."ItemCode",
              T0."ItemName",
              IFNULL(T0."QC_Qty",    0)  AS "OpenQty",
              IFNULL(T0."QC_Amount", 0)  AS "OpenAmount",
              IFNULL(T1."In_Qty",    0)  AS "InQty",
              IFNULL(T1."In_Amount", 0)  AS "InAmount",
              IFNULL(T1."Out_Qty",   0)  AS "OutQty",
              IFNULL(T0."QC_Qty",    0)
                  + IFNULL(T1."In_Qty",  0)
                  - IFNULL(T1."Out_Qty", 0) AS "CloseQty"
          FROM "MTC_COST_0301_INVNT" T0
          LEFT JOIN (
              SELECT
                  T1."FcCode",
                  T1."ItemCode",
                  SUM(CASE WHEN T2."U_IOType" = 'I' THEN  T1."Quantity" ELSE 0 END) AS "In_Qty",
                  SUM(CASE WHEN T2."U_IOType" = 'I' THEN  T1."Amount"   ELSE 0 END) AS "In_Amount",
                  SUM(CASE WHEN T2."U_IOType" = 'O' THEN -1 * T1."Quantity" ELSE 0 END) AS "Out_Qty"
              FROM "MTC_COST_0302_INVNTDETAIL1" T1
              JOIN "@MTC_COST_IOTYPE" T2 ON T1."TransCode" = T2."Code"
              WHERE T1."FcCode" = :iv_FcCode
              GROUP BY T1."FcCode", T1."ItemCode"
          ) T1 ON T0."FcCode" = T1."FcCode" AND T0."ItemCode" = T1."ItemCode"
          WHERE T0."FcCode"   = :iv_FcCode
            AND T0."CostCode" = '20';
  
      -- 按物料汇总工单工费
      lt_item_cost =
          SELECT
              S."FcCode",
              S."ItemCode",
              MAX(S."ItemName")             AS "ItemName",
              COALESCE(MAX(LV."iLevel"), 1) AS "iLevel",
              SUM(S."2ManExp")              AS "ManExp",
              SUM(S."3LabAmount")           AS "LabAmount",
              SUM(S."4WWExp")               AS "WWExp"
          FROM "MTC_COST_0321_OWOR_SUM" S
          LEFT JOIN "U_COILV" LV
              ON S."ItemCode" = LV."ItemCode" AND S."FcCode" = LV."FcCode"
          WHERE S."FcCode" = :iv_FcCode
          GROUP BY S."FcCode", S."ItemCode";
  
      -- BOM关系：子物料投入金额
      lt_bom =
          SELECT
              S."FcCode",
              S."ItemCode"                  AS "ParentItem",
              D."ItemCode"                  AS "ChildItem",
              SUM(IFNULL(D."Amount", 0))    AS "ChildAmount",
              COALESCE(MAX(LV."iLevel"), 1) AS "ChildLevel"
          FROM "MTC_COST_0321_OWOR_SUM" S
          INNER JOIN "MTC_COST_0321_OWOR1_REG" D
              ON S."WorEntry" = D."WorEntry" AND S."FcCode" = D."FcCode"
          LEFT JOIN "U_COILV" LV
              ON D."ItemCode" = LV."ItemCode" AND S."FcCode" = LV."FcCode"
          WHERE S."FcCode" = :iv_FcCode
          GROUP BY S."FcCode", S."ItemCode", D."ItemCode";
  
      -- =====================================================
      -- 无工单物料：整理成中间表再UPDATE
      -- =====================================================
      lt_no_order =
          SELECT
              IV."FcCode",
              IV."ItemCode",
              IV."OpenQty",
              IV."OpenAmount",
              IV."InQty",
              IV."InAmount",
              IV."OutQty",
              IV."CloseQty",
              -- 加权平均单位成本分母
              IV."OpenQty" + IV."InQty"                                AS "TotalQty",
              -- 加权平均单位成本分子
              IFNULL(ST."OpenMaterial", 0) + IV."InAmount"             AS "TotalMaterial",
              IFNULL(ST."OpenAmount",   0) + IV."InAmount"             AS "TotalAmount",
              -- 加权平均单位成本
              CASE WHEN (IV."OpenQty" + IV."InQty") > 0
                   THEN (IFNULL(ST."OpenAmount", 0) + IV."InAmount")
                      / (IV."OpenQty" + IV."InQty")
                   ELSE 0 END                                          AS "AvgUnitCost",
              -- 出库金额
              CASE WHEN (IV."OpenQty" + IV."InQty") > 0
                   THEN (IFNULL(ST."OpenAmount", 0) + IV."InAmount")
                      / (IV."OpenQty" + IV."InQty") * IV."OutQty"
                   ELSE 0 END                                          AS "OutAmount",
              -- 期末金额
              CASE WHEN (IV."OpenQty" + IV."InQty") > 0
                   THEN (IFNULL(ST."OpenAmount", 0) + IV."InAmount")
                      - (IFNULL(ST."OpenAmount", 0) + IV."InAmount")
                      / (IV."OpenQty" + IV."InQty") * IV."OutQty"
                   ELSE IFNULL(ST."OpenAmount", 0) + IV."InAmount" END AS "CloseAmount"
          FROM :lt_invnt IV
          LEFT JOIN "MTC_COST_STOCK" ST
              ON ST."ItemCode" = IV."ItemCode" AND ST."FcCode" = IV."FcCode"
          WHERE IV."ItemCode" NOT IN (SELECT "ItemCode" FROM :lt_item_cost);
  
      -- 无工单物料 UPDATE
      UPDATE "MTC_COST_STOCK" T
      SET
          T."InQty"          = IFNULL((SELECT S."InQty"      FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."InMaterial"     = IFNULL((SELECT S."InAmount"   FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."InManExp"       = 0,
          T."InLabAmount"    = 0,
          T."InWWExp"        = 0,
          T."InAmount"       = IFNULL((SELECT S."InAmount"   FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."OutQty"         = IFNULL((SELECT S."OutQty"     FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."OutMaterial"    = IFNULL((SELECT S."OutAmount"  FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."OutManExp"      = 0,
          T."OutLabAmount"   = 0,
          T."OutWWExp"       = 0,
          T."OutAmount"      = IFNULL((SELECT S."OutAmount"  FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."CloseQty"       = IFNULL((SELECT S."CloseQty"   FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), T."OpenQty"),
          T."CloseMaterial"  = IFNULL((SELECT S."CloseAmount" FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), T."OpenAmount"),
          T."CloseManExp"    = 0,
          T."CloseLabAmount" = 0,
          T."CloseWWExp"     = 0,
          T."CloseAmount"    = IFNULL((SELECT S."CloseAmount" FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), T."OpenAmount"),
          T."UnitMaterial"   = IFNULL((SELECT S."AvgUnitCost" FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."UnitManExp"     = 0,
          T."UnitLabAmount"  = 0,
          T."UnitWWExp"      = 0,
          T."UnitCost"       = IFNULL((SELECT S."AvgUnitCost" FROM :lt_no_order S WHERE S."ItemCode" = T."ItemCode"), 0),
          T."PrcMaterial"    = 1,
          T."PrcManExp"      = 0,
          T."PrcLabAmount"   = 0,
          T."PrcWWExp"       = 0,
          T."Status"         = 'C'
      WHERE T."FcCode"   = :iv_FcCode
        AND T."ItemCode" IN (SELECT "ItemCode" FROM :lt_no_order);
  
      -- =====================================================
      -- 逐级计算（有工单物料）
      -- =====================================================
      WHILE :lv_level <= :lv_max_level DO
  
          SELECT COUNT(*) INTO lv_count
          FROM :lt_item_cost WHERE "iLevel" = :lv_level;
  
          IF :lv_count > 0 THEN
  
              -- 写入明细表
              INSERT INTO "MTC_COST_ROLLUP_DETAIL"
              (
                  "FcCode", "ParentItem", "ParentLevel", "ChildItem", "ChildLevel",
                  "ChildAmount", "ChildUnitCost", "ChildUnitMaterial", "ChildUnitManExp",
                  "ChildUnitLabAmt", "ChildUnitWWExp",
                  "SplitMaterial", "SplitManExp", "SplitLabAmount", "SplitWWExp",
                  "SplitTotal", "MaterialPct"
              )
              SELECT
                  BR."FcCode",
                  BR."ParentItem",
                  :lv_level,
                  BR."ChildItem",
                  BR."ChildLevel",
                  BR."ChildAmount",
                  IFNULL(ST."UnitCost",      0),
                  IFNULL(ST."UnitMaterial",  0),
                  IFNULL(ST."UnitManExp",    0),
                  IFNULL(ST."UnitLabAmount", 0),
                  IFNULL(ST."UnitWWExp",     0),
                  BR."ChildAmount" * IFNULL(ST."PrcMaterial",  1),
                  BR."ChildAmount" * IFNULL(ST."PrcManExp",    0),
                  BR."ChildAmount" * IFNULL(ST."PrcLabAmount", 0),
                  BR."ChildAmount" * IFNULL(ST."PrcWWExp",     0),
                  BR."ChildAmount",
                  ROUND(IFNULL(ST."PrcMaterial", 1) * 100.0, 2)
              FROM :lt_bom BR
              LEFT JOIN "MTC_COST_STOCK" ST
                  ON BR."ChildItem" = ST."ItemCode"
                  AND BR."FcCode"   = ST."FcCode"
              WHERE BR."ParentItem" IN (
                  SELECT "ItemCode" FROM :lt_item_cost WHERE "iLevel" = :lv_level
              );
  
              -- 汇总子料真实成本分类
              lt_child_cost =
                  SELECT
                      BR."FcCode",
                      BR."ParentItem",
                      SUM(BR."ChildAmount" * IFNULL(ST."PrcMaterial",  1)) AS "ChildMaterialTotal",
                      SUM(BR."ChildAmount" * IFNULL(ST."PrcManExp",    0)) AS "ChildManExpTotal",
                      SUM(BR."ChildAmount" * IFNULL(ST."PrcLabAmount", 0)) AS "ChildLabTotal",
                      SUM(BR."ChildAmount" * IFNULL(ST."PrcWWExp",     0)) AS "ChildWWExpTotal"
                  FROM :lt_bom BR
                  LEFT JOIN "MTC_COST_STOCK" ST
                      ON BR."ChildItem" = ST."ItemCode"
                      AND BR."FcCode"   = ST."FcCode"
                  WHERE BR."ParentItem" IN (
                      SELECT "ItemCode" FROM :lt_item_cost WHERE "iLevel" = :lv_level
                  )
                  GROUP BY BR."FcCode", BR."ParentItem";
  
              -- 构建入库+出库数据
              lt_level_in =
                  SELECT
                      IC."FcCode",
                      IC."ItemCode",
                      IC."ItemName",
                      IC."iLevel",
                      IFNULL(IV."OpenQty",            0)                             AS "OpenQty",
                      IFNULL(IV."InQty",              0)                             AS "InQty",
                      IFNULL(IV."OutQty",             0)                             AS "OutQty",
                      IFNULL(IV."CloseQty",           0)                             AS "CloseQty",
                      IFNULL(CC."ChildMaterialTotal", 0)                             AS "InMaterial",
                      IFNULL(CC."ChildManExpTotal",   0) + IFNULL(IC."ManExp",    0) AS "InManExp",
                      IFNULL(CC."ChildLabTotal",      0) + IFNULL(IC."LabAmount", 0) AS "InLabAmount",
                      IFNULL(CC."ChildWWExpTotal",    0) + IFNULL(IC."WWExp",     0) AS "InWWExp",
                      IFNULL(IV."OpenQty", 0) + IFNULL(IV."InQty", 0)               AS "TotalInQty"
                  FROM :lt_item_cost IC
                  LEFT JOIN :lt_child_cost CC
                      ON IC."ItemCode" = CC."ParentItem" AND IC."FcCode" = CC."FcCode"
                  LEFT JOIN :lt_invnt IV
                      ON IC."ItemCode" = IV."ItemCode"   AND IC."FcCode" = IV."FcCode"
                  WHERE IC."iLevel" = :lv_level;
  
              -- MERGE 写入
              MERGE INTO "MTC_COST_STOCK" T
              USING (
                  SELECT
                      S."FcCode",
                      S."ItemCode",
                      S."ItemName",
                      S."iLevel",
                      S."OpenQty",
                      S."InQty",
                      S."OutQty",
                      S."CloseQty",
                      S."InMaterial",
                      S."InManExp",
                      S."InLabAmount",
                      S."InWWExp",
                      S."TotalInQty",
                      CASE WHEN S."TotalInQty" > 0
                           THEN (IFNULL(T2."OpenMaterial",  0) + S."InMaterial")  / S."TotalInQty"
                           ELSE 0 END AS "AvgUnitMaterial",
                      CASE WHEN S."TotalInQty" > 0
                           THEN (IFNULL(T2."OpenManExp",    0) + S."InManExp")    / S."TotalInQty"
                           ELSE 0 END AS "AvgUnitManExp",
                      CASE WHEN S."TotalInQty" > 0
                           THEN (IFNULL(T2."OpenLabAmount", 0) + S."InLabAmount") / S."TotalInQty"
                           ELSE 0 END AS "AvgUnitLabAmount",
                      CASE WHEN S."TotalInQty" > 0
                           THEN (IFNULL(T2."OpenWWExp",     0) + S."InWWExp")     / S."TotalInQty"
                           ELSE 0 END AS "AvgUnitWWExp",
                      CASE WHEN S."TotalInQty" > 0
                           THEN (IFNULL(T2."OpenAmount",    0) + S."InMaterial"
                                 + S."InManExp" + S."InLabAmount" + S."InWWExp") / S."TotalInQty"
                           ELSE 0 END AS "AvgUnitCost"
                  FROM :lt_level_in S
                  LEFT JOIN "MTC_COST_STOCK" T2
                      ON T2."ItemCode" = S."ItemCode" AND T2."FcCode" = S."FcCode"
              ) S
              ON T."FcCode" = S."FcCode" AND T."ItemCode" = S."ItemCode"
              WHEN MATCHED THEN UPDATE SET
                  T."ItemName"       = S."ItemName",
                  T."iLevel"         = S."iLevel",
                  T."OpenQty"        = S."OpenQty",
                  T."InQty"          = S."InQty",
                  T."InMaterial"     = S."InMaterial",
                  T."InManExp"       = S."InManExp",
                  T."InLabAmount"    = S."InLabAmount",
                  T."InWWExp"        = S."InWWExp",
                  T."InAmount"       = S."InMaterial" + S."InManExp" + S."InLabAmount" + S."InWWExp",
                  T."OutQty"         = S."OutQty",
                  T."OutMaterial"    = S."AvgUnitMaterial"  * S."OutQty",
                  T."OutManExp"      = S."AvgUnitManExp"    * S."OutQty",
                  T."OutLabAmount"   = S."AvgUnitLabAmount" * S."OutQty",
                  T."OutWWExp"       = S."AvgUnitWWExp"     * S."OutQty",
                  T."OutAmount"      = S."AvgUnitCost"      * S."OutQty",
                  T."CloseQty"       = S."CloseQty",
                  T."CloseMaterial"  = IFNULL(T."OpenMaterial",  0) + S."InMaterial"
                                     - S."AvgUnitMaterial"  * S."OutQty",
                  T."CloseManExp"    = IFNULL(T."OpenManExp",    0) + S."InManExp"
                                     - S."AvgUnitManExp"    * S."OutQty",
                  T."CloseLabAmount" = IFNULL(T."OpenLabAmount", 0) + S."InLabAmount"
                                     - S."AvgUnitLabAmount" * S."OutQty",
                  T."CloseWWExp"     = IFNULL(T."OpenWWExp",     0) + S."InWWExp"
                                     - S."AvgUnitWWExp"     * S."OutQty",
                  T."CloseAmount"    = IFNULL(T."OpenAmount",    0) + S."InMaterial"
                                     + S."InManExp" + S."InLabAmount" + S."InWWExp"
                                     - S."AvgUnitCost"      * S."OutQty",
                  T."Status"         = 'C'
              WHEN NOT MATCHED THEN INSERT (
                  "FcCode", "ItemCode", "ItemName", "iLevel",
                  "OpenQty", "OpenMaterial", "OpenManExp", "OpenLabAmount", "OpenWWExp", "OpenAmount",
                  "InQty",  "InMaterial",  "InManExp",  "InLabAmount",  "InWWExp",  "InAmount",
                  "OutQty", "OutMaterial", "OutManExp", "OutLabAmount", "OutWWExp", "OutAmount",
                  "CloseQty", "CloseMaterial", "CloseManExp", "CloseLabAmount", "CloseWWExp", "CloseAmount",
                  "Status"
              ) VALUES (
                  S."FcCode", S."ItemCode", S."ItemName", S."iLevel",
                  S."OpenQty", 0, 0, 0, 0, 0,
                  S."InQty",  S."InMaterial",  S."InManExp",  S."InLabAmount",  S."InWWExp",
                  S."InMaterial" + S."InManExp" + S."InLabAmount" + S."InWWExp",
                  S."OutQty",
                  S."AvgUnitMaterial"  * S."OutQty",
                  S."AvgUnitManExp"    * S."OutQty",
                  S."AvgUnitLabAmount" * S."OutQty",
                  S."AvgUnitWWExp"     * S."OutQty",
                  S."AvgUnitCost"      * S."OutQty",
                  S."CloseQty",
                  S."InMaterial"  - S."AvgUnitMaterial"  * S."OutQty",
                  S."InManExp"    - S."AvgUnitManExp"    * S."OutQty",
                  S."InLabAmount" - S."AvgUnitLabAmount" * S."OutQty",
                  S."InWWExp"     - S."AvgUnitWWExp"     * S."OutQty",
                  S."InMaterial" + S."InManExp" + S."InLabAmount" + S."InWWExp"
                  - S."AvgUnitCost" * S."OutQty",
                  'C'
              );
  
              -- 计算单位成本
              UPDATE "MTC_COST_STOCK"
              SET
                  "UnitMaterial"  = CASE WHEN "CloseQty" > 0 THEN "CloseMaterial"  / "CloseQty" ELSE 0 END,
                  "UnitManExp"    = CASE WHEN "CloseQty" > 0 THEN "CloseManExp"    / "CloseQty" ELSE 0 END,
                  "UnitLabAmount" = CASE WHEN "CloseQty" > 0 THEN "CloseLabAmount" / "CloseQty" ELSE 0 END,
                  "UnitWWExp"     = CASE WHEN "CloseQty" > 0 THEN "CloseWWExp"     / "CloseQty" ELSE 0 END,
                  "UnitCost"      = CASE WHEN "CloseQty" > 0 THEN "CloseAmount"    / "CloseQty" ELSE 0 END
              WHERE "FcCode"   = :iv_FcCode
                AND "iLevel"   = :lv_level
                AND "CloseQty" > 0;
  
              -- 每级计算完立即更新 Prc
              UPDATE "MTC_COST_STOCK"
              SET
                  "PrcMaterial"  = "CloseMaterial"  / NULLIF("CloseAmount", 0),
                  "PrcManExp"    = "CloseManExp"     / NULLIF("CloseAmount", 0),
                  "PrcLabAmount" = "CloseLabAmount"  / NULLIF("CloseAmount", 0),
                  "PrcWWExp"     = "CloseWWExp"      / NULLIF("CloseAmount", 0)
              WHERE "FcCode"      = :iv_FcCode
                AND "iLevel"      = :lv_level
                AND "CloseAmount" > 0;
  
              -- 兜底
              UPDATE "MTC_COST_STOCK"
              SET
                  "PrcMaterial"  = CASE WHEN "iLevel" = 1 THEN 1 ELSE 0 END,
                  "PrcManExp"    = 0,
                  "PrcLabAmount" = 0,
                  "PrcWWExp"     = 0
              WHERE "FcCode"      = :iv_FcCode
                AND "iLevel"      = :lv_level
                AND "CloseAmount" = 0;
  
          END IF;
  
          lv_level := :lv_level + 1;
  
      END WHILE;
  
      -- 最终差值法修正 PrcMaterial
      UPDATE "MTC_COST_STOCK"
      SET
          "PrcMaterial" = 1 - IFNULL("PrcManExp",    0)
                            - IFNULL("PrcLabAmount",  0)
                            - IFNULL("PrcWWExp",      0)
      WHERE "FcCode" = :iv_FcCode;
  
  END;

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PERIOD_FORWARD
CREATE PROCEDURE "MTC_COST_PERIOD_FORWARD" (
    IN iv_FromFcCode NVARCHAR(50),
    IN iv_ToFcCode   NVARCHAR(50)
)
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
AS
BEGIN
	DELETE FROM MTC_COST_STOCK WHERE "FcCode"=:iv_ToFcCode;
    MERGE INTO "MTC_COST_STOCK" T
    USING (
        SELECT 
            :iv_ToFcCode        AS "FcCode",
            "ItemCode",
            "ItemName",
            "iLevel",
            "CloseQty"          AS "OpenQty",
            "CloseMaterial"     AS "OpenMaterial",
            "CloseManExp"       AS "OpenManExp",
            "CloseLabAmount"    AS "OpenLabAmount",
            "CloseWWExp"        AS "OpenWWExp",
            "CloseAmount"       AS "OpenAmount"
        FROM "MTC_COST_STOCK"
        WHERE "FcCode" = :iv_FromFcCode
          AND "Status" = 'C'
          AND "CloseQty" > 0
    ) S
    ON T."FcCode" = S."FcCode" AND T."ItemCode" = S."ItemCode"
    WHEN MATCHED THEN UPDATE SET
        T."OpenQty"         = S."OpenQty",
        T."OpenMaterial"    = S."OpenMaterial",
        T."OpenManExp"      = S."OpenManExp",
        T."OpenLabAmount"   = S."OpenLabAmount",
        T."OpenWWExp"       = S."OpenWWExp",
        T."OpenAmount"      = S."OpenAmount"
    WHEN NOT MATCHED THEN INSERT (
        "FcCode", "ItemCode", "ItemName", "iLevel",
        "OpenQty", "OpenMaterial", "OpenManExp", "OpenLabAmount", "OpenWWExp", "OpenAmount"
    ) VALUES (
        S."FcCode", S."ItemCode", S."ItemName", S."iLevel",
        S."OpenQty", S."OpenMaterial", S."OpenManExp", S."OpenLabAmount", S."OpenWWExp", S."OpenAmount"
    );
END;

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0106_OWORLIST
CREATE PROCEDURE "MTC_COST_PROC_0106_OWORLIST"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取物料等级 到 明细到静态表 MTC_COST_0105_ITEM
     * CALL "MTC_COST_PROC_0321_OWOR"(0,'2024-01','manager');
    */

	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
	
	DELETE FROM MTC_COST_0106_OWORLIST WHERE "FcCode" = :FcCode;
	DELETE FROM MTC_COST_0106_OWORLIST1 WHERE "FcCode" = :FcCode;
	
	INSERT INTO MTC_COST_0106_OWORLIST(
	 "BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"iLevel"
	,"Quantity"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'202' AS "DocType"
	,P0."U_OrdType" AS "WorType"
	,P0."DocEntry" AS "WorEntry"
	,P0."DocNum" AS "WorNum"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P2."iLevel"
	,P0."PlannedQty" AS "Quantity"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OWOR" P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P0."ItemCode"=P2."ItemCode"
	WHERE 1=1 AND P0."Status"<>'C'
	;
	
	INSERT INTO MTC_COST_0106_OWORLIST1(
	"BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"LineNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"iLevel"
	,"Quantity"
	,"CreateDate"
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'202' AS "DocType"
	,P0."U_OrdType" AS "WorType"
	,P0."DocEntry" AS "WorEntry"
	,P0."DocNum" AS "WorNum"
	,P3."LineNum"
	,P3."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P2."iLevel"
	,P3."PlannedQty"    --领料数量
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OWOR P0
	JOIN WOR1 P3 ON P0."DocEntry"=P3."DocEntry"
	LEFT JOIN OITM P1 ON P3."ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P3."ItemCode"=P2."ItemCode"
	;
	
	
	INSERT INTO MTC_COST_0106_OWORLIST(
	 "BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"iLevel"
	,"Quantity"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."Object" AS "DocType"
	,P0."U_OrdType" AS "WorType"
	,P0."DocEntry" AS "WorEntry"
	,P0."DocNum" AS "WorNum"
	,P1."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P2."iLevel"
	,P0."U_PlannedQty" AS "Quantity"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OWOR" P0
	LEFT JOIN OITM P1 ON P0."U_ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P0."U_ItemCode"=P2."ItemCode"
	WHERE 1=1 AND P0."U_Status"<>'C'
	;
	
	INSERT INTO MTC_COST_0106_OWORLIST1(
	"BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"LineNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"iLevel"
	,"Quantity"
	,"CreateDate"
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."Object" AS "DocType"
	,P0."U_OrdType" AS "WorType"
	,P0."DocEntry" AS "WorEntry"
	,P0."DocNum" AS "WorNum"
	,P3."LineId"
	,P1."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P2."iLevel"
	,P3."U_PlannedQty"    --领料数量
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OWOR" P0
	JOIN "@MTC_WOR1" P3 ON P0."DocEntry"=P3."DocEntry"
	LEFT JOIN OITM P1 ON P3."U_ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P3."U_ItemCode"=P2."ItemCode"
	;
	
	SELECT 0 AS "代码",'获取生产订单结构'||:FcCode||',成功！' AS "信息" FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0201_DOCDETAIL
CREATE PROCEDURE "MTC_COST_PROC_0201_DOCDETAIL"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取出入库明细到静态表 MTC_COST_0201_DOCDETAL
     * CALL "MTC_COST_PROC_20_DOCDETAIL"(0,'2024-01','manager');
    */
	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM MTC_COST_0201_DOCDETAL WHERE "FcCode" = :FcCode;
	
	UPDATE PCH1 SET "BaseRef"=NULL WHERE "BaseRef"='';
	
	INSERT INTO MTC_COST_0201_DOCDETAL("BPLId"
	,"ObjType"
	,"DocEntry"
	,"DocNum"
	,"CardCode"
	,"CardName"
	,"LineNum"
	,"FcCode"
	,"DocDate"
	,"CostCode"		--归入成本计价类型
	,"TransCode"		--实际交易类型
	,"BaseType"
	,"BaseEntry"
	,"BaseNum"
	,"BaseLine"
	,"ItemCode"
	,"ItemName"
	,"EvalSystem"
	,"ItmsGrpCod"
	,"CalType"	--成本计价类型
	,"Quantity"
	,"Amount"
	,"Price"
	,"WhsCode"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"WorLineNum"
	,"CJCode"
	,"CJName"
	,"OcrCode1"
	,"OcrCode2"
	,"OcrCode3"
	,"OcrCode4"
	,"OcrCode5"
	,"User"
	,"TransId"
	,"Comments"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT "BPLId"
	,"ObjType"
	,"DocEntry"
	,"DocNum"
	,"CardCode"
	,"CardName"
	,"LineNum"
	,"FcCode"
	,"DocDate"
	,"CostCode"		--归入成本计价类型
	,"TransCode"		--实际交易类型
	,"BaseType"
	,"BaseEntry"
	,"BaseNum"
	,"BaseLine"
	,"ItemCode"
	,"ItemName"
	,"EvalSystem"
	,"ItmsGrpCod"
	,"CalType"	--成本计价类型
	,"Quantity"
	,"Amount"
	,"Price"
	,"WhsCode"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"WorLineNum"
	,"CJCode"
	,"CJName"
	,"OcrCode1"
	,"OcrCode2"
	,"OcrCode3"
	,"OcrCode4"
	,"OcrCode5"
	,"User"
	,"TransId"
	,"Comments"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "MTC_COST_FC_DOCDETAIL"(:BPLId,:FcCode);
	
	SELECT 0 AS "代码",'收集出入库信息'||:FcCode||',成功！' AS "信息" FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0301_INVNT
CREATE PROCEDURE "MTC_COST_PROC_0301_INVNT"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	DECLARE LastFcCode NVARCHAR(30);	--上期
	SELECT "Code" INTO LastFcCode
	FROM "OFPR" WHERE "Code" IN (SELECT MAX("Code") AS "Code" FROM "OFPR" WHERE "Code"<:FcCode);
	
	/* created by chri.li 2024.11.23
     * 仅入库数据明细到静态表 MTC_COST_0302_INVNTDETAIL1
     * CALL "MTC_COST_PROC_0301_INVNT"(0,'2024-01','manager');
    */
	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
	
	DELETE FROM MTC_COST_0301_INVNT WHERE "FcCode" = :FcCode;
	
	--写入期初数据（开账期初数据，初始化时使用）
	INSERT INTO MTC_COST_0301_INVNT(
	 "BPLId"
	 ,"FcCode"
	 ,"CalType"
	 ,"CostCode"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"QM_Qty"
	 ,"QM_Price"
	 ,"QM_Amount"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId
	,:FcCode
	,T."U_ItemProp"
	,T1."CostTypeCode" AS "CostCode"
	,T."ItemCode"
	,T."ItemName"
	,T."ItmsGrpCod"
	,P1."iLevel"
	,IFNULL(P0."QC_Qty",0)		AS "QC_Qty"
	,IFNULL(P0."QC_Price",0)		AS "QC_Price"
	,IFNULL(P0."QC_Amount",0)		AS "QC_Amount"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OITM T
	LEFT JOIN MTC_COST_0101_COSTTYPE T1 ON 1=1
	LEFT JOIN (SELECT * FROM MTC_COST_INVNT_QC WHERE "FcCode"=:FcCode
			) P0 ON T."ItemCode"=P0."ItemCode"
	LEFT JOIN U_COILV P1 ON T."ItemCode"=P1."ItemCode"
	WHERE 1=1 AND P1."FcCode"='2024-11'
	AND P1."FcCode"=:FcCode
	;
	
	--写入期初数据(正常期间的)
	INSERT INTO MTC_COST_0301_INVNT(
	 "BPLId"
	 ,"FcCode"
	 ,"CalType"
	 ,"CostCode"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"QC_Qty"
	 ,"QC_Price"
	 ,"QC_Amount"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT 0 AS "BPLId"
	,T0."FcCode"
	,P0."CalType"
	,T1."CostTypeCode" AS "CostCode"
	,T0."ItemCode"
	,T0."ItemName"
	,T2."ItmsGrpCod"
	,T0."iLevel"
	,IFNULL(P0."QM_Qty",0)		AS "QC_Qty"
	,IFNULL(P0."QM_Price",0)		AS "QC_Price"
	,IFNULL(P0."QM_Amount",0)		AS "QC_Amount"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM U_COILV T0
	LEFT JOIN MTC_COST_0101_COSTTYPE T1 ON 1=1
	LEFT JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "FcCode"=:LastFcCode
			) P0 ON T0."ItemCode"=P0."ItemCode" AND T1."CostTypeCode"=P0."CostCode"
	JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	WHERE 1=1
	AND T0."FcCode"=:FcCode
	AND T0."FcCode">='2024-12'
	;
	
	UPDATE T0 SET T0."QC_Qty"=T1."OIVLQty"
	FROM "MTC_COST_0301_INVNT" T0
	LEFT JOIN (SELECT "ItemCode",SUM("InQty"-"OutQty") AS "OIVLQty"
				FROM "OIVL" WHERE "DocDate"<='2025-03-31'
				GROUP BY "ItemCode"
			) T1 ON T0."ItemCode"=T1."ItemCode"
	WHERE 1=1
	AND T0."FcCode"=:FcCode
	AND T0."FcCode"='2025-04'
	AND T0."ItemCode" IN
	('072000285-B3',
	'012000633',
	'072000284-B3',
	'031100175',
	'070600046',
	'070600048',
	'070600051',
	'091300008',
	'031100144',
	'071100018',
	'141300006',
	'012000098',
	'132000095',
	'012000632',
	'012000634',
	'012000631',
	'082000043',
	'012000093',
	'131300005',
	'042000032',
	'011100388',
	'012000697',
	'012000698',
	'102000794',
	'012000097');
	
	UPDATE MTC_COST_0301_INVNT SET "QC_Qty"=8,"QC_Price"=ROUND("QC_Amount"/8,6) WHERE "FcCode"=:FcCode AND "FcCode"='2025-04' AND "ItemCode"='071100055';
	UPDATE MTC_COST_0301_INVNT SET "QC_Qty"=88,"QC_Price"=ROUND("QC_Amount"/8,6) WHERE "FcCode"=:FcCode AND "FcCode"='2025-04' AND "ItemCode"='071100054';
	
	
	
	SELECT 0 AS "代码",'建立库存结构'||:FcCode||',成功！' AS "信息" FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0303_INVNTDETAIL2
CREATE PROCEDURE "MTC_COST_PROC_0303_INVNTDETAIL2"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 为拉取数据到明细表的明细执行（包括①在"MTC_COST_PROC_0302_INVNTDETAIL1"中执行，②在"MTC_COST_PROC_CAL_1001_CHECK"中执行）
     * CALL "MTC_COST_PROC_0303_INVNTDETAIL2"(0,'2024-01','manager');
     * 写入：
       1.拉取除18、19的库存明细
       2.拉取18的交易明细
       3.拉取19的交易明细
       4.拉取MTC_OMRV的交易明细（需要计入当期成本计算）(类型是:WW委外发票差异，ProCost的)
    */
    
    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM MTC_COST_0302_INVNTDETAIL1 WHERE "FcCode" = :FcCode;
	DELETE FROM MTC_COST_0303_INVNTLIST WHERE "FcCode" = :FcCode;
	
	INSERT INTO MTC_COST_0302_INVNTDETAIL1(
	 "BPLId"
	 ,"FcCode"
	 ,"ObjType"
	 ,"DocEntry"
	 ,"DocNum"
	 ,"LineNum" 
	 ,"DocDate" 
	 ,"CostCode"   --归入成本计价类型
	 ,"TransCode"   --实际交易类型
	 ,"BaseType"
	 ,"BaseEntry"
	 ,"BaseNum"
	 ,"BaseLine"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"CalType" --成本计价类型
	 ,"Quantity"
	 ,"Amount"
	 ,"VarVal"
	 ,"Price"
	 ,"OcrCode1"
	 ,"WhsCode"
	 ,"BusiType"
	 ,"BusiTypeN"
	 ,"PriceMemo","AcctCode","CogsAcct"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."TransType" AS "ObjType"
	,P0."CreatedBy" AS "DocEntry"
	,P0."BASE_REF" AS "DocNum"
	,P0."DocLineNum" AS "LineNum"
	,P0."DocDate"
	,P5."CostTypeCode" AS "CostCode"   --归入成本计价类型
	,P8."TransCode"   --实际交易类型
	,P8."BaseType"
	,P8."BaseEntry"
	,TO_CHAR(IFNULL(P8."BaseRef",'')) AS "BaseNum"
	,P8."BaseLine"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P3."iLevel"
	,P1."U_ItemProp" AS "CalType" --成本计价类型
	,P0."InQty"-P0."OutQty" AS "Quantity"
	,CASE WHEN P0."TransType" IN ('20','21') THEN P9."Amount" 
		ELSE P0."SumStock" END AS "Amount"
	,P0."VarVal"
	,0		------------2024.1.18注释掉
	,P8."OcrCode"
	,P0."LocCode"
	,P8."U_BusiType" AS "BusiType"
	,P8."U_YWLX" AS "BusiTypeN"
	,'从MTC_COST_PROC_0302_INVNTDETAIL1中抽取'
	,P8."AcctCode",P8."CogsAcct"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OIVL P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND P0."ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	LEFT JOIN (SELECT T0."ObjType",T0."DocEntry",T0."LineNum",T0."OcrCode"
				,T0."BaseType",T0."BaseEntry",T0."BaseRef",T0."BaseLine"
				,T0."TransCode",T0."U_BusiType",T0."U_YWLX",T0."AcctCode",T0."CogsAcct"
				FROM "MTC_VIEW_Document" T0
		) P8 ON TO_CHAR(P0."TransType")=P8."ObjType" AND TO_CHAR(P0."CreatedBy")=P8."DocEntry" AND TO_CHAR(P0."DocLineNum")=P8."LineNum"
	LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
				,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
				 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."Price"*D."Quantity" END AS "Amount"
				FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
				UNION ALL
				SELECT M."ObjType",M."DocEntry",D."LineNum"
				,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
				 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
				FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
			) P9 ON TO_CHAR(P0."TransType")=P9."ObjType" AND P0."CreatedBy"=P9."DocEntry" AND P0."DocLineNum"=P9."LineNum"
	WHERE 1=1
	AND P0."LocCode"<>'S300' --排除报废库
    AND P0."TransType"<>'67'	--排除67转储单
	AND P0."TransType" NOT IN ('18','19')
	AND LEFT(P0."DocDate",7)=:FcCode;
	
	--18
	INSERT INTO MTC_COST_0302_INVNTDETAIL1(
	 "BPLId"
	 ,"FcCode"
	 ,"ObjType"
	 ,"DocEntry"
	 ,"DocNum"
	 ,"LineNum" 
	 ,"DocDate" 
	 ,"CostCode"   --归入成本计价类型
	 ,"TransCode"   --实际交易类型
	 ,"BaseType"
	 ,"BaseEntry"
	 ,"BaseNum"
	 ,"BaseLine"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"CalType" --成本计价类型
	 ,"Quantity"
	 ,"Amount"
	 ,"VarVal"
	 ,"Price"
	 ,"OcrCode1"
	 ,"WhsCode"
	 ,"BusiType"
	 ,"BusiTypeN"
	 ,"PriceMemo","AcctCode","CogsAcct"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."TransType" AS "ObjType"
	,P0."CreatedBy" AS "DocEntry"
	,P0."BASE_REF" AS "DocNum"
	,P0."DocLineNum" AS "LineNum"
	,P0."DocDate"
	,P5."CostTypeCode" AS "CostCode"   --归入成本计价类型
	,P8."TransCode"   --实际交易类型
	,P8."BaseType"
	,P8."BaseEntry"
	,TO_CHAR(P8."BaseRef") AS "BaseNum"
	,P8."BaseLine"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P3."iLevel"
	,P1."U_ItemProp" AS "CalType" --成本计价类型
	,P0."InQty"-P0."OutQty" AS "Quantity"
	,P9."Amount" AS "Amount"
	,P0."VarVal"
	,0		------------2024.1.18注释掉
	,P8."OcrCode"
	,P0."LocCode"
	,P8."U_BusiType" AS "BusiType"
	,P8."U_YWLX" AS "BusiTypeN"
	,'从MTC_COST_PROC_0302_INVNTDETAIL1中抽取'
	,P8."AcctCode",P8."CogsAcct"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OIVL P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND P0."ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	LEFT JOIN (SELECT T0."ObjType",T0."DocEntry",T0."LineNum",T0."OcrCode"
				,T0."BaseType",T0."BaseEntry",T0."BaseRef",T0."BaseLine"
				,T0."TransCode",T0."U_BusiType",T0."U_YWLX",T0."AcctCode",T0."CogsAcct"
				FROM "MTC_VIEW_Document" T0
		) P8 ON TO_CHAR(P0."TransType")=P8."ObjType" AND TO_CHAR(P0."CreatedBy")=P8."DocEntry" AND TO_CHAR(P0."DocLineNum")=P8."LineNum"
	LEFT JOIN 
		(
		--18-正常单
		SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
			,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE T1."LineTotal"-T1."Quantity"*IFNULL(T2."Price",0) END AS "Amount"
			FROM OPCH T0
			JOIN PCH1 T1 ON T0."DocEntry"=T1."DocEntry"
			LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
						,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
						 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."Price"*D."Quantity" END AS "Amount"
						 ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
						FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
						UNION ALL
						SELECT M."ObjType",M."DocEntry",D."LineNum"
						,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
						 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
						  ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
						FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
					) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
		where T0."CANCELED" IN ('N','Y')
		
		UNION ALL
		--18-取消单（CANCELED='C'）
		SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
			,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE -1*T2."Amount" END AS "Amount"
			FROM OPCH T0
			JOIN PCH1 T1 ON T0."DocEntry"=T1."DocEntry"
			LEFT JOIN (
			
						--18-正常单
						SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
							,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE T1."LineTotal"-T1."Quantity"*IFNULL(T2."Price",0) END AS "Amount"
							FROM OPCH T0
							JOIN PCH1 T1 ON T0."DocEntry"=T1."DocEntry"
							LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
										,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
										 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."Price"*D."Quantity" END AS "Amount"
										 ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
										FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
										UNION ALL
										SELECT M."ObjType",M."DocEntry",D."LineNum"
										,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
										 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
										  ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
										FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
									) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
						where T0."CANCELED" IN ('N','Y')
			
			
					) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
		where T0."CANCELED" IN ('C')
		
		) P9 ON TO_CHAR(P0."TransType")=P9."ObjType" AND P0."CreatedBy"=P9."DocEntry" AND P0."DocLineNum"=P9."LineNum"
	WHERE 1=1
	AND P0."TransType" IN ('18')
	AND LEFT(P0."DocDate",7)=:FcCode;
	
	
	--19
	INSERT INTO MTC_COST_0302_INVNTDETAIL1(
	 "BPLId"
	 ,"FcCode"
	 ,"ObjType"
	 ,"DocEntry"
	 ,"DocNum"
	 ,"LineNum" 
	 ,"DocDate" 
	 ,"CostCode"   --归入成本计价类型
	 ,"TransCode"   --实际交易类型
	 ,"BaseType"
	 ,"BaseEntry"
	 ,"BaseNum"
	 ,"BaseLine"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"CalType" --成本计价类型
	 ,"Quantity"
	 ,"Amount"
	 ,"VarVal"
	 ,"Price"
	 ,"OcrCode1"
	 ,"WhsCode"
	 ,"BusiType"
	 ,"BusiTypeN"
	 ,"PriceMemo","AcctCode","CogsAcct"
	 ,"IsUpdatePrice"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."TransType" AS "ObjType"
	,P0."CreatedBy" AS "DocEntry"
	,P0."BASE_REF" AS "DocNum"
	,P0."DocLineNum" AS "LineNum"
	,P0."DocDate"
	,P5."CostTypeCode" AS "CostCode"   --归入成本计价类型
	,P8."TransCode"   --实际交易类型
	,P8."BaseType"
	,P8."BaseEntry"
	,TO_CHAR(P8."BaseRef") AS "BaseNum"
	,P8."BaseLine"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P3."iLevel"
	,P1."U_ItemProp" AS "CalType" --成本计价类型
	,P0."InQty"-P0."OutQty" AS "Quantity"
	,P9."Amount" AS "Amount"
	,P0."VarVal"
	,0		------------2024.1.18注释掉
	,P8."OcrCode"
	,P0."LocCode"
	,P8."U_BusiType" AS "BusiType"
	,P8."U_YWLX" AS "BusiTypeN"
	,'从MTC_COST_PROC_0302_INVNTDETAIL1中抽取'
	,P8."AcctCode",P8."CogsAcct"
	,NULL AS "IsUpdatePrice"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OIVL P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND P0."ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	LEFT JOIN (SELECT T0."ObjType",T0."DocEntry",T0."LineNum",T0."OcrCode"
				,T0."BaseType",T0."BaseEntry",T0."BaseRef",T0."BaseLine"
				,T0."TransCode",T0."U_BusiType",T0."U_YWLX",T0."AcctCode",T0."CogsAcct"
				FROM "MTC_VIEW_Document" T0
		) P8 ON TO_CHAR(P0."TransType")=P8."ObjType" AND TO_CHAR(P0."CreatedBy")=P8."DocEntry" AND TO_CHAR(P0."DocLineNum")=P8."LineNum"
	LEFT JOIN 
		(
		--正常单
		SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
			,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE -1*(T1."LineTotal"-T1."Quantity"*IFNULL(T2."Price",0)) END AS "Amount"
			FROM ORPC T0
			JOIN RPC1 T1 ON T0."DocEntry"=T1."DocEntry"
			LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
						,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
						 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."Price"*D."Quantity" END AS "Amount"
						,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
						FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
						UNION ALL
						SELECT M."ObjType",M."DocEntry",D."LineNum"
						,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
						 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
						,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
						FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
					) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
		where T0."CANCELED" IN ('N','Y')
		
		UNION ALL
		--19-取消单（CANCELED='C'）
		SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
			,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE 1*T2."Amount" END AS "Amount"
			FROM ORPC T0
			JOIN RPC1 T1 ON T0."DocEntry"=T1."DocEntry"
			LEFT JOIN (
			
						--19-取消单
						SELECT T1."ObjType",T1."DocEntry",T1."LineNum"
							,CASE WHEN T2."DocEntry" IS NULL THEN 0 ELSE T1."LineTotal"-T1."Quantity"*IFNULL(T2."Price",0) END AS "Amount"
							FROM ORPC T0
							JOIN RPC1 T1 ON T0."DocEntry"=T1."DocEntry"
							LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
										,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
										 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."Price"*D."Quantity" END AS "Amount"
										 ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
										FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
										UNION ALL
										SELECT M."ObjType",M."DocEntry",D."LineNum"
										,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
										 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
										  ,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0) ELSE D."Price" END AS "Price"
										FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
									) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
						where T0."CANCELED" IN ('N','Y')
			
					) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
		where T0."CANCELED" IN ('C')
		) P9 ON TO_CHAR(P0."TransType")=P9."ObjType" AND P0."CreatedBy"=P9."DocEntry" AND P0."DocLineNum"=P9."LineNum"
	WHERE 1=1
	AND P0."TransType" IN ('19')
	--AND P0."BASE_REF" NOT IN (547,548)
	AND LEFT(P0."DocDate",7)=:FcCode;
	
	
	--"@MTC_OMRV"
	INSERT INTO MTC_COST_0302_INVNTDETAIL1(
	 "BPLId"
	 ,"FcCode"
	 ,"ObjType"
	 ,"DocEntry"
	 ,"DocNum"
	 ,"LineNum" 
	 ,"DocDate" 
	 ,"CostCode"   --归入成本计价类型
	 ,"TransCode"   --实际交易类型
	 ,"BaseType"
	 ,"BaseEntry"
	 ,"BaseNum"
	 ,"BaseLine"
	 ,"ItemCode"
	 ,"ItemName"
	 ,"ItmsGrpCod"
	 ,"iLevel"
	 ,"CalType" --成本计价类型
	 ,"Quantity"
	 ,"Amount"
	 ,"VarVal"
	 ,"Price"
	 ,"OcrCode1"
	 ,"WhsCode"
	 ,"BusiType"
	 ,"BusiTypeN"
	 ,"PriceMemo","AcctCode","CogsAcct"
	 ,"IsUpdatePrice"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T0."Object" AS "ObjType"
	,T1."DocEntry" AS "DocEntry"
	,T0."DocNum" AS "DocNum"
	,T1."LineId" AS "LineNum"
	,T0."U_DocDate"
	,'20' AS "CostCode"   --归入成本计价类型
	,'I11' AS "TransCode"   --实际交易类型
	,T1."U_BaseType"
	,T1."U_BaseEntry"
	,TO_CHAR(T1."U_BaseNum")
	,T1."U_BaseLine"
	,T1."U_ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P3."iLevel"
	,'02' AS "CalType" --成本计价类型
	,0 AS "Quantity"
	,T1."U_Amount" AS "Amount"
	,0 AS "VarVal"
	,0		------------2024.1.18注释掉
	,NULL AS "OcrCode"
	,NULL AS "LocCode"
	,'' AS "BusiType"
	,'' AS "BusiTypeN"
	,'从MTC_COST_PROC_0302_INVNTDETAIL1中抽取2'
	,NULL AS "AcctCode",NULL AS "CogsAcct"
	,CASE WHEN T1."U_CalType"='InvntCost' THEN 'NoCost' ELSE NULL END  AS "IsUpdatePrice" --'NoCost'时，不参与当期成本计算
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OMRV" T0
	JOIN "@MTC_OMRV1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN OITM P1 ON T1."U_ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND T1."U_ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	WHERE 1=1
	AND T0."U_BaseType" IN ('WW','MRV1') ---CL要改为按当期发生额
	AND LEFT(T0."U_DocDate",7)=:FcCode;
	
	SELECT 0 AS "代码",'写入库存明细'||:FcCode||',成功！' AS "信息" FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0302_INVNTDETAIL1
CREATE PROCEDURE "MTC_COST_PROC_0302_INVNTDETAIL1"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 仅入库数据明细到静态表 MTC_COST_0302_INVNTDETAIL1
     * CALL "MTC_COST_PROC_0302_INVNTDETAIL1"(0,'2024-01','manager');
    */
    
    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
  	
  	--拉取库存交易明细
    CALL "MTC_COST_PROC_0303_INVNTDETAIL2"(:BPLId,:FcCode,:UserCode);
  	
  	
	
	--初始化数量，将库存数量写入收发存表MTC_COST_0303_INVNT
	/*
		321 生产成品入库
        322 包装成品入库
        232 委外加工入库

    */
	UPDATE T0 SET 
	 T0."In_Qty"=IFNULL(T1."In_Qty",0)
	,T0."Out_Qty"=IFNULL(T1."Out_Qty",0)
	,T0."QM_Qty"=IFNULL(T0."QC_Qty",0)+IFNULL(T1."In_Qty",0)-IFNULL(T1."Out_Qty",0)
	FROM "MTC_COST_0301_INVNT" T0
	LEFT JOIN (
			SELECT T1."FcCode",T1."ItemCode"
			,SUM(CASE WHEN T2."U_IOType"='I' THEN T1."Quantity" ELSE 0 END) AS "In_Qty"
			,SUM(CASE WHEN T2."U_IOType"='O' THEN -1*T1."Quantity" ELSE 0 END) AS "Out_Qty"
			FROM "MTC_COST_0302_INVNTDETAIL1" T1
			JOIN "@MTC_COST_IOTYPE" T2 ON T1."TransCode"=T2."Code"
			WHERE 1=1
			GROUP BY T1."FcCode",T1."ItemCode"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	WHERE 1=1 AND T0."FcCode"=:FcCode;	
	
	
	--SELECT '1',* FROM MTC_COST_0302_INVNTDETAIL1 WHERE "ItemCode"='FH0100402' ;
	
	
	UPDATE MTC_COST_0302_INVNTDETAIL1 SET "IsUpdatePrice"='NoCost'
	WHERE "FcCode"=:FcCode AND IFNULL("Quantity",0)<>0  AND "BusiType" IN ('305','311','207'); --报废出入库
	
	UPDATE MTC_COST_0302_INVNTDETAIL1 SET "IsUpdatePrice"='P'
	WHERE "FcCode"=:FcCode AND "TransCode" IN ('I01','I06','I11')
	AND IFNULL("IsUpdatePrice",'')<>'NoCost'
	; --采购
	
	--作为入库加权的一部分（采购的加权入口）MTC_COST_0303_INVNTLIST
	INSERT INTO MTC_COST_0303_INVNTLIST(
	"BPLId","FcCode","CalType","ItemCode","ItemName","ItmsGrpCod","iLevel"
	,"ObjType","TransCode","SourceMemo"
	,"Qty","Price","Amt")
	SELECT :BPLId,"FcCode","CalType","ItemCode","ItemName","ItmsGrpCod","iLevel"
	,"ObjType","TransCode",'采购金额-'||"ObjType"||'-'||"DocEntry"||'-'||"LineNum"
	,("Quantity") AS "In_Qty",("Amount")/NULLIF(("Quantity"),0),("Amount") AS "In_Amount"
	FROM "MTC_COST_0302_INVNTDETAIL1" 
	WHERE "TransCode" IN ('I01','I06','I11')		--入库数量 
	AND "FcCode"=:FcCode
	AND IFNULL("IsUpdatePrice",'')<>'NoCost'
	--GROUP BY "FcCode","CalType","ItemCode","ItemName","ItmsGrpCod","iLevel","ObjType"
	;
	
	/*
	UPDATE T0 SET T0."Amount"=T0."Quantity"*T1."Price",T0."Price"=T1."Price"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
    JOIN MTC_COST_0210_QCPRICE T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T0."CostCode"='20'
	AND T0."ObjType" IN ('59','16')
	AND T0."TransCode" IN ('59-304','59-204')
	AND T0."FcCode"='2024-12'
	;	*/
	
	--UPDATE MTC_COST_0302_INVNTDETAIL1 SET "Amount"="Quantity"*"Price" WHERE "ItemCode"='102000904' AND "ObjType"='59';
	
	--SELECT '2',* FROM MTC_COST_0302_INVNTDETAIL1 WHERE "ItemCode"='FH0627201' ;
	--SELECT * FROM MTC_COST_0301_INVNT WHERE "ItemCode"='FH0627201';
	--将采购入库单价写到
	UPDATE T0
	SET T0."In_Amount"=T1."In_Amount",T0."In_Price"=T1."In_Amount"/NULLIF(T1."In_Qty",0)
	,T0."Price"=(IFNULL(T0."QC_Amount",0)+IFNULL(T1."In_Amount",0))
				/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."In_Qty",0)),0)
	,"PriceMemo"=IFNULL("PriceMemo",'')||'->'||'从MTC_COST_PROC_0302_INVNTDETAIL1写入Step1001采购写入,单价,'
	||TO_CHAR((IFNULL(T0."QC_Amount",0)+IFNULL(T1."In_Amount",0))/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."In_Qty",0)),0))
	FROM MTC_COST_0301_INVNT T0
	LEFT JOIN (SELECT "FcCode","ItemCode","CostCode"
			,SUM("Quantity") AS "In_Qty",SUM(ROUND("Amount",2)) AS "In_Amount"
			FROM "MTC_COST_0302_INVNTDETAIL1" 
			WHERE "TransCode" IN ('I01','I06','I11')		--入库数量
			AND IFNULL("IsUpdatePrice",'')<>'NoCost'
			--AND "TransCode" IN ('20-101','59-321','59-322','59-323')
			GROUP BY "FcCode","ItemCode","CostCode"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode" AND T0."CostCode"=T1."CostCode" 
	WHERE T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode;
	
	
	
	--SELECT '3',* FROM MTC_COST_0302_INVNTDETAIL1 WHERE "ItemCode"='FH0627201' ;
	--SELECT * FROM MTC_COST_0301_INVNT WHERE "ItemCode"='FH0627201';
	
	--计算外购品的加权出库单价
	/*
	UPDATE T0 SET T0."Price"=T1."Price"
	FROM "MTC_COST_0301_INVNT" T0
	JOIN (SELECT "FcCode","ItemCode","CostCode"
		  ,SUM(IFNULL(T0."QC_Qty",0)+IFNULL(T0."In_Qty",0)) AS "Qty"
		  ,SUM(IFNULL(T0."QC_Amount",0)+IFNULL(T0."In_Amount",0)) AS "Amount"
		  ,SUM(IFNULL(T0."QC_Amount",0)+IFNULL(T0."In_Amount",0))/NULLIF(SUM(IFNULL(T0."QC_Qty",0)+IFNULL(T0."In_Qty",0)),0) AS "Price"
		  FROM "MTC_COST_0301_INVNT" T0 GROUP BY "FcCode","ItemCode","CostCode"
		  ) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode" AND T0."CostCode"=T1."CostCode"
	WHERE T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode
	--AND T0."CalType"='01'
	;
	*/
		
	--SELECT '4',* FROM MTC_COST_0302_INVNTDETAIL1 WHERE "ItemCode"='FH0100402' ;
	--写原材料出库数据MTC_COST_0302_INVNTDETAIL1
	--59-203,60-203
	UPDATE T0
	SET T0."Amount"=ROUND(T0."Quantity"*IFNULL(T1."Price",0),2),T0."Price"=IFNULL(T1."Price",0)
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0302_INVNTDETAIL1中写入Step1002当期(上期+本期采购),单价为:'||TO_CHAR(IFNULL(T1."Price",0))
	,T0."IsUpdatePrice"='N'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN MTC_COST_0301_INVNT T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode" AND T0."CostCode"=T1."CostCode"
	WHERE 1=1
	AND IFNULL(T0."IsUpdatePrice",'')<>'NoCost'
	AND T0."ObjType" IN ('60','59')
	AND T0."TransCode" IN ('I04','O04','O07','O08','O05','I10','O10')  --'I07','I08'返工（生产返工、委外返工） ,'I05','O05'转换出入库
	AND T0."CostCode"='20'	--材料
	AND IFNULL(T1."Price",0)<>0 --2026.2.8增加此条件
	AND T0."FcCode"=:FcCode;
	
	--根据期初维护的价格写入价格为0的
	UPDATE T0
	SET T0."Amount"=ROUND(T0."Quantity"*IFNULL(T1."U_Price",0),2),T0."Price"=IFNULL(T1."U_Price",0)
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0302_INVNTDETAIL1中写入Step1003期初价格为0'
	,T0."IsUpdatePrice"='N'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT T1."U_ItemCode",T1."U_Price",T1."U_IsY"
			FROM "@MTC_COST_QCPRICE" T0
			JOIN "@MTC_COST_QCPRICE1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."Canceled"='N' AND T0."U_FcCode"=:FcCode
		) T1 ON T0."ItemCode"=T1."U_ItemCode"
	WHERE 1=1
	AND IFNULL(T0."IsUpdatePrice",'')<>'NoCost'
	AND T0."ObjType" IN ('60','59')
	AND T0."TransCode" IN ('I04','O04','O07','O08','O05','I10')  --'I07','I08'返工（生产返工、委外返工） ,'I05','O05'转换出入库
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode
	AND ((IFNULL(T1."U_Price",0)<>0 AND IFNULL(T0."Price",0)=0) OR T1."U_IsY"='Y');
	
	--I05转换入库
	UPDATE T0
	SET 
	 T0."Amount"=-1*IFNULL(T1."Amount",0)
	,T0."Price"=-1*IFNULL(T1."Amount",0)/T0."Quantity"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0302_INVNTDETAIL1中转换出入库写入'
	,T0."IsUpdatePrice"='I05'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT T0."BaseType",T0."BaseEntry",T0."BaseLine",T0."Amount"
			FROM "MTC_COST_0302_INVNTDETAIL1" T0
			WHERE T0."TransCode"='O05' AND T0."FcCode"=:FcCode
		) T1 ON T0."BaseType"=T1."BaseType" AND T0."BaseEntry"=T1."BaseEntry" AND T0."BaseLine"=T1."BaseLine"
	WHERE 1=1
	AND IFNULL(T0."IsUpdatePrice",'')<>'NoCost'
	AND T0."ObjType" IN ('60','59')
	AND T0."TransCode" IN ('I05')  --'I05','O05'转换出入库
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode;
	
	
	
	--更新出库的加权价
	UPDATE T0 SET 
	T0."Price"=
	CASE WHEN IFNULL(T0."QC_Qty",0)+IFNULL(T1."Qty",0)=0
	THEN T0."Price"
	ELSE ROUND((IFNULL(T0."QC_Amount",0)+IFNULL(T1."Amt",0))/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."Qty",0)),0),6) END
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0302_INVNTDETAIL1写入Step1009加权计算写入'
	FROM MTC_COST_0301_INVNT T0
	LEFT JOIN (SELECT "FcCode","ItemCode","CostCode",SUM("Quantity") AS "Qty",SUM("Amount") AS "Amt"
			FROM "MTC_COST_0302_INVNTDETAIL1" 
			WHERE IFNULL("IsUpdatePrice",'')<>'' --已经被初始过价格的
			GROUP BY "FcCode","ItemCode","CostCode"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode" AND T0."CostCode"=T1."CostCode" 
	WHERE 1=1
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode;
	
	
	
	/*
	
	--将出库数写到
	UPDATE T0 SET T0."Out_Qty"=T1."Out_Qty",T0."Out_Amount"=T1."Out_Amount"
	FROM MTC_COST_0301_INVNT T0
	JOIN (SELECT "FcCode","ItemCode","CostCode",-1*SUM("Quantity") AS "Out_Qty",-1*SUM("Amount") AS "Out_Amount"
			FROM "MTC_COST_0302_INVNTDETAIL1" 
			WHERE "ObjType" IN ('60')		--出库数量
			GROUP BY "FcCode","ItemCode","CostCode"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode" AND T0."CostCode"=T1."CostCode" 
	WHERE 1=1
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode
	AND T0."CalType"='01';
	
	
	--将期末数写到
	UPDATE T0 SET T0."QM_Qty"=IFNULL(T0."QC_Qty",0)+IFNULL(T0."In_Qty",0)-IFNULL(T0."Out_Qty",0)
	,T0."QM_Amount"=IFNULL(T0."QC_Amount",0)+IFNULL(T0."In_Amount",0)-IFNULL(T0."Out_Amount",0)
	FROM MTC_COST_0301_INVNT T0
	WHERE 1=1
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode;*/
	
	SELECT 0 AS "代码",'写入库存明细'||:FcCode||',成功！' AS "信息" FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0306_WW
CREATE PROCEDURE "MTC_COST_PROC_0306_WW"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 费用归集表 MTC_COST_0312_PRODUCTEXP_PRC
     * CALL "MTC_COST_PROC_0312_PRODUCTEXP_PRC"(0,'2024-01','manager');
    */
    --w委外

    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;

    DELETE FROM MTC_COST_0321_OWOR2 WHERE "FcCode"=:FcCode AND "CostCode"='20';
    
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"IgeQty"  
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T0."DocType"
	,T0."WorType"
	,T0."WorEntry"
	,T0."WorNum"
	,'20' AS "CostCode"
	,'委外费用' AS "ExpType"
	,-1*"Detail_Qty" AS "IgeQty"
	,-1*ROUND(T1."Detail_Amt",2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0321_OWOR T0
	JOIN (
			SELECT "OWOREntry"
  			,SUM(-1*"Quantity") AS "Detail_Qty"
  			,SUM(-1*ROUND("Amt",2)) AS "Detail_Amt"
  			FROM "MTC_VIEW_ProductDetail" T0
  			WHERE "Type" = '子件' AND LEFT(T0."DocDate",7)=:FcCode
  			AND "ID" IN (3,4)
  			GROUP BY "OWOREntry"
			) T1 ON T0."WorEntry"=T1."OWOREntry"
	WHERE 1=1
	AND T0."DocType"='202'
	AND T0."FcCode"=:FcCode
	;
	
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"IgeQty"  
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T."DocType"
	,T."WorType"
	,T."WorEntry"
	,T."WorNum"
	,'20' AS "CostCode"
	,'委外费用' AS "ExpType"
	,IFNULL(T1."U_Quantity",0) AS "IgeQty"	--订单数量
	,ROUND(-1*T1."U_Amount",2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OMRV" T0
	JOIN "@MTC_OMRV1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN OITM P1 ON T1."U_ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND T1."U_ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	JOIN (SELECT ROW_NUMBER() OVER (PARTITION BY "DocType","WorEntry" ORDER BY "FcCode" DESC) AS "ID"
				,"DocType","WorType","WorEntry","WorNum"
				FROM MTC_COST_0321_OWOR
			   WHERE "FcCode"<=:FcCode
		) T ON T1."U_BaseType"=T."DocType" AND T1."U_BaseEntry"=T."WorEntry" AND T."ID"=1
	WHERE 1=1
	AND T0."Canceled"='N'
	AND T0."U_BaseType"='ProWW'
	AND LEFT(T0."U_DocDate",7)=:FcCode;
	
	
	UPDATE T0 SET T0."4WWExp"=IFNULL(T1."Amount",0),T0."Amount"=IFNULL(T0."1Material",0)+IFNULL(T1."Amount",0)
	FROM MTC_COST_0321_OWOR T0
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry",-1*SUM(ROUND("Amount",2)) AS "Amount"
		FROM MTC_COST_0321_OWOR2 WHERE "CostCode"='20' GROUP BY "DocType","WorEntry"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."WorEntry"=T1."WorEntry" AND T0."DocType"=T1."DocType"
	WHERE 1=1
	AND T0."FcCode"=:FcCode;
	
	SELECT '委外费用计算成功' FROM DUMMY;
	

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0311_PRODUCTEXP_ADD
CREATE PROCEDURE "MTC_COST_PROC_0311_PRODUCTEXP_ADD"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 费用归集表 MTC_COST_0311_PRODUCTEXP_ADD
     * CALL "MTC_COST_PROC_0311_PRODUCTEXP_ADD"(0,'2024-01','manager');
     * 由这几部分构成：
       1.人工费用、制造费用：日记账分录计入人工费用和制造费用的
       2.公摊材料费用：计入当期制造费用5101的物料消耗（其他领用）
       3.委外发票差异：委外费用发票差异计入的当期制造费用
	   4.生成分录计入的科目：人工费用500102 制造费用500103
    */
	
    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM MTC_COST_0311_PRODUCTEXP_ADD WHERE "FcCode" = :FcCode;
	
	INSERT INTO MTC_COST_0311_PRODUCTEXP_ADD("BPLId"
	,"FcCode"
	,"ExpType"	--费用类型
	,"ExpCode" --费用大类编码
	,"ExpName" --费用大类名称
	,"AcctCode" --科目编码
	,"AcctName" --科目名称
	,"OcrCode"
	,"OcrName"
	,"IsCal" --是否计入 Y/N
	,"Amount"	--计入金额
	,"Memo"		--备注	
	,"CalAcctCode"	--计入的科目编码
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,CASE WHEN T2."AcctCode"='500102' THEN '人工费用' ELSE '制造费用' END AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T2."AcctCode"
	,T2."AcctName"
	,T3."PrcCode"
	,T3."PrcName"
	,'Y' AS "IsCal"
	,SUM(T1."Debit"-T1."Credit") AS "Amount"
	,'' AS "Memo"
	,CASE WHEN T2."AcctCode"='500102' THEN '500102' ELSE '500103' END AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OJDT T0
	JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
	JOIN OACT T2 ON T1."Account"=T2."AcctCode"
	LEFT JOIN OPRC T3 ON T1."ProfitCode"=T3."PrcCode"
	WHERE 1=1 
	AND LEFT(T0."RefDate",7)=:FcCode
	AND (T1."Account"='500102' OR LEFT(T1."Account",4)='5101')
	AND IFNULL(T0."TransCode",'') IN ('','YF01','PP03','MR11','MR02','MR03','MR12') --后期需要改为排除
	GROUP BY T2."AcctCode"
	,T2."AcctName"
	,T3."PrcCode"
	,T3."PrcName"
	
	--增加关单差异
	UNION ALL
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'制造费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T2."AcctCode"
	,T2."AcctName"
	,T3."PrcCode"
	,T3."PrcName"
	,'Y' AS "IsCal"
	,SUM(T1."Debit"-T1."Credit") AS "Amount"
	,'' AS "Memo"
	,CASE WHEN T2."AcctCode"='500102' THEN '500102' ELSE '500103' END AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM OBTF T0
	JOIN "BTF1" T1 ON T0."TransId"=T1."TransId" AND T0."BatchNum"=T1."BatchNum"
	JOIN OACT T2 ON T1."Account"=T2."AcctCode"
	LEFT JOIN OPRC T3 ON T1."ProfitCode"=T3."PrcCode"
	WHERE 1=1
	AND T0."BtfStatus"='O'
	AND LEFT(T0."RefDate",7)=:FcCode
	AND LEFT(T1."Account",4)='5101'
	AND IFNULL(T0."TransCode",'') IN ('JZ01','JZ03') 
	GROUP BY T2."AcctCode"
	,T2."AcctName"
	,T3."PrcCode"
	,T3."PrcName"
	
	UNION ALL
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'公摊材料费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T5."AcctCode"
	,T5."AcctName"
	,T0."OcrCode1"
	,P1."PrcName"
	,'Y' AS "IsCal"
	,-1*SUM(ROUND("Amount",2)) AS "Amount"
	,'' AS "Memo"
	,'500103' AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN (
				SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGN1
					UNION ALL
				SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGE1
				) T4 ON T0."ObjType"=T4."ObjType" AND T0."DocEntry"=T4."DocEntry" AND T0."LineNum"=T4."LineNum"
	LEFT JOIN OPRC P1 ON T0."OcrCode1"=P1."PrcCode"
	LEFT JOIN OACT T5 ON T4."AcctCode"=T5."AcctCode"
	WHERE T0."FcCode"=:FcCode
	AND T0."CostCode"='20'
	AND T0."ObjType" IN ('59','60')
	AND (T0."TransCode" IN ('I04','O04','I10','O10'))	--I04 O04其他出入库 'I10','O10'盘点出入库
	AND LEFT(T4."AcctCode",4) IN ('5101')
	GROUP BY "OcrCode1",P1."PrcName",T5."AcctCode"
	,T5."AcctName"
	
	UNION ALL
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'公摊材料费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T5."AcctCode"
	,T5."AcctName"||'(生产试打)'
	,T0."OcrCode1"
	,P1."PrcName"
	,'Y' AS "IsCal"
	,CASE WHEN T0."OcrCode1"='P016' THEN 32710.04 WHEN T0."OcrCode1"='P006' THEN 0 END AS "Amount"
	---1*SUM(ROUND("Amount",2)) AS "Amount"
	,'' AS "Memo"
	,'500103' AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN OPRC P1 ON T0."OcrCode1"=P1."PrcCode"
	LEFT JOIN OACT T5 ON T5."AcctCode"='510109'
	LEFT JOIN OWOR T6 ON T0."BaseType"='202' AND T0."BaseEntry"=T6."DocEntry"
	WHERE 1=0
	AND T0."FcCode"=:FcCode
	AND T0."CostCode"='20'
	AND T0."ObjType" IN ('59','60')
	AND T6."U_OrdType"='40'
	GROUP BY "OcrCode1",P1."PrcName",T5."AcctCode"
	,T5."AcctName"
	;
	--这个还需要再议 重新写
	INSERT INTO MTC_COST_0311_PRODUCTEXP_ADD("BPLId"
	,"FcCode"
	,"ExpType"	--费用类型
	,"ExpCode" --费用大类编码
	,"ExpName" --费用大类名称
	,"AcctCode" --科目编码
	,"AcctName" --科目名称
	,"OcrCode"
	,"OcrName"
	,"IsCal" --是否计入 Y/N
	,"Amount"	--计入金额
	,"Memo"		--备注	
	,"CalAcctCode"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'库存重估-委外工单差异' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,NULL
	,NULL
	,NULL AS "OcrCode1"
	,NULL AS "PrcName"
	,'Y' AS "IsCal"
	,SUM(ROUND(-1*T1."U_Amount",2)) AS "Amount"
	,'' AS "Memo"
	,'500103' AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OMRV" T0
	JOIN "@MTC_OMRV1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN OITM P1 ON T1."U_ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND T1."U_ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	WHERE 1=1
	AND T0."Canceled"='N'
	AND T0."U_BaseType"='ProWW'
	AND IFNULL(T1."U_BaseType",'')<>'202'
	AND LEFT(T0."U_DocDate",7)=:FcCode;
	
	
	--这个还需要再议 重新写
	INSERT INTO MTC_COST_0311_PRODUCTEXP_ADD("BPLId"
	,"FcCode"
	,"ExpType"	--费用类型
	,"ExpCode" --费用大类编码
	,"ExpName" --费用大类名称
	,"AcctCode" --科目编码
	,"AcctName" --科目名称
	,"OcrCode"
	,"OcrName"
	,"IsCal" --是否计入 Y/N
	,"Amount"	--计入金额
	,"Memo"		--备注	
	,"CalAcctCode"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,CASE WHEN IFNULL(T1."U_CalType",'')='ProCost' THEN '库存重估-手工重估（当期成本）'
		  WHEN IFNULL(T1."U_CalType",'')='InvntCost' THEN '库存重估-手工重估（结存）'
		  ELSE '其他' END
		 AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T1."U_AcctCode"
	,T1."U_AcctName"
	,NULL AS "OcrCode1"
	,NULL AS "PrcName"
	,'Y' AS "IsCal"
	,SUM(ROUND(-1*T1."U_Amount",2)) AS "Amount"
	,'' AS "Memo"
	,'500103' AS "CalAcctCode"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OMRV" T0
	JOIN "@MTC_OMRV1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN OITM P1 ON T1."U_ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	LEFT JOIN U_COILV P3 ON P3."FcCode"=:FcCode AND T1."U_ItemCode"=P3."ItemCode"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	WHERE 1=1
	AND T0."Canceled"='N'
	AND T0."U_BaseType" IN ('MRV1','MRV2')
	--AND IFNULL(T1."U_CalType",'')='ProCost' chris.li 20250905去掉，期末结存的也需要放入制造费用
	AND LEFT(T0."U_DocDate",7)=:FcCode
	GROUP BY T1."U_AcctCode",T1."U_AcctName"
	,CASE WHEN IFNULL(T1."U_CalType",'')='ProCost' THEN '库存重估-手工重估（当期成本）'
		  WHEN IFNULL(T1."U_CalType",'')='InvntCost' THEN '库存重估-手工重估（结存）'
		  ELSE '其他' END
	;
	
	
	SELECT  "FcCode" AS "期间",
	"ExpType" AS "费用类型",
	"ExpCode" AS "费用编码",
	"ExpName" AS "费用名称",
	"AcctCode" AS "科目编码",
	"AcctName" AS "科目名称",
	"OcrCode" AS "部门编码",
	"OcrName" AS "部门名称",
	"IsCal" AS "计入成本计算",
	"Amount" AS "金额",
	"Memo" AS "备注",
	"CalAcctCode" AS "计入科目",
	"CreateDate" AS "创建日期",
	"Creator" AS "创建人"
	FROM MTC_COST_0311_PRODUCTEXP_ADD WHERE "FcCode"=:FcCode;
	

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0312_PRODUCTEXP_PRC
CREATE PROCEDURE "MTC_COST_PROC_0312_PRODUCTEXP_PRC"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 费用归集表 MTC_COST_0312_PRODUCTEXP_PRC
     * CALL "MTC_COST_PROC_0312_PRODUCTEXP_PRC"(0,'2024-01','manager');
    */
    
    --CALL "MTC_COST_PROC_0312_PRODUCTEXP_PRC"(0,:FcCode,'manager');
    
    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM MTC_COST_0312_PRODUCTEXP_PRC WHERE "FcCode" = :FcCode;
	DELETE FROM MTC_COST_0321_OWOR2 WHERE "FcCode" = :FcCode;
	
	--------------------------------------制造费用---------------------------------------------
	INSERT INTO MTC_COST_0312_PRODUCTEXP_PRC("BPLId"
	,"FcCode"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"ExpCode"  --费用大类编码
	,"ExpName" --费用大类名称
	,"ItemCode" 
	,"CJCode" 	--车间编码（All-所有车间）
	,"IgnQty"  --入库数量
	,"Time"	  --单位工时
	,"TimeTotal" --总单位工时
	,"Prc"
	,"ExpAmt"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'30' AS "CostCode"
	,'制造费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T0."ItemCode"		--产成品的物料
	,'制造车间' AS "CJCode"
	,0 AS "IgnQty"
	,T1."Time" AS "Time"	  --单位工时
	,T1."TimeTotal" AS "TimeTotal"
	,T1."Prc" AS "Prc"
	,T1."ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OITM" T0
	LEFT JOIN 
	(
		SELECT T1."ItemCode",T1."Time",T3."ItmsGrpCod",(T1."Time"*T2."IgnQty") AS "TimeTotal"
		,(T1."Time"*T2."IgnQty")/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0) AS "Prc"
		,ROUND((T1."Time"*T2."IgnQty")*T4."ExpAmount"/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0),2) AS "ExpAmt"
		FROM (SELECT T1."U_ItemCode" AS "ItemCode",MAX(T1."U_Time") AS "Time" 
					FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry"
					WHERE T0."U_FcCode"=:FcCode GROUP BY T1."U_ItemCode"
				) T1
		JOIN (SELECT T0."ItemCode",-1*SUM(T0."Amount") AS "Amount",SUM(T0."IgnQty") AS "IgnQty"
				FROM MTC_COST_0321_OWOR T0 -- ON T1."FcCode"=T0."FcCode" AND T1."WorEntry"=T0."WorEntry"
				WHERE T0."FcCode"=:FcCode
				AND T0."WorType" IN ('10','20','30','40')
				--AND T0."ItemCode"='102000552'
				GROUP BY T0."ItemCode"
				) T2 ON T1."ItemCode"=T2."ItemCode"
		JOIN OITM T3 ON T1."ItemCode"=T3."ItemCode"
		LEFT JOIN (SELECT "FcCode",SUM("Amount") AS "ExpAmount"
					FROM "MTC_COST_0311_PRODUCTEXP_ADD"
					WHERE "FcCode"=:FcCode
					AND ("ExpType" IN ('制造费用','公摊材料费用') OR "ExpType" LIKE '库存重估%') AND IFNULL("OcrCode",'')<>'P017'
					GROUP BY "FcCode"
				) T4 ON 1=1
		WHERE T3."ItmsGrpCod" IN ('102','103')
	) T1 ON T0."ItemCode"=T1."ItemCode"	
	;
	
	
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T1."DocType"
	,T1."WorType"
	,T1."WorEntry"
	,T1."WorNum"
	,'30' AS "CostCode"
	,'制造费用' AS "ExpType"
	,ROUND(-1*T0."ExpAmt"*T2."IgnQty"/NULLIF(SUM(T2."IgnQty") OVER (PARTITION BY T1."ItemCode",T1."FcCode"),0),2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0312_PRODUCTEXP_PRC T0
	JOIN MTC_COST_0321_OWOR T1 ON T0."ItemCode"=T1."ItemCode" AND T0."FcCode"=T1."FcCode"
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry",SUM("IgnQty") AS "IgnQty"
			FROM MTC_COST_0321_OWOR
			WHERE "FcCode"=:FcCode
			GROUP BY "WorEntry","DocType"
			) T2 ON T1."FcCode"=T2."FcCode" AND T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry"
	WHERE T0."FcCode"=:FcCode
	AND T1."WorType" IN ('10','20','30','40')
	AND T0."ExpType"='制造费用' AND T0."CJCode"='制造车间'		
	;
	
	
	---------P017包装车间的领用
	INSERT INTO MTC_COST_0312_PRODUCTEXP_PRC("BPLId"
	,"FcCode"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"ExpCode"  --费用大类编码
	,"ExpName" --费用大类名称
	,"ItemCode" 
	,"CJCode" 	--车间编码（All-所有车间）
	,"IgnQty"  --入库数量
	,"Time"	  --单位工时
	,"TimeTotal" --总单位工时
	,"Prc"
	,"ExpAmt"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'30' AS "CostCode"
	,'制造费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T0."ItemCode"		--产成品的物料
	,'包装车间' AS "CJCode"
	,0 AS "IgnQty"
	,T1."Time" AS "Time"	  --单位工时
	,T1."TimeTotal" AS "TimeTotal"
	,T1."Prc" AS "Prc"
	,T1."ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OITM" T0
	LEFT JOIN 
	(
		SELECT T1."ItemCode",T1."Time",T3."ItmsGrpCod",(T1."Time"*T2."IgnQty") AS "TimeTotal"
		,(T1."Time"*T2."IgnQty")/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0) AS "Prc"
		,ROUND((T1."Time"*T2."IgnQty")*T4."ExpAmount"/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0),2) AS "ExpAmt"
		FROM (SELECT T1."U_ItemCode" AS "ItemCode",MAX(T1."U_Time") AS "Time" 
					FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry"
					WHERE T0."U_FcCode"=:FcCode GROUP BY T1."U_ItemCode"
				) T1
		JOIN (SELECT T0."ItemCode",-1*SUM(T0."Amount") AS "Amount",SUM(T0."IgnQty") AS "IgnQty"
				FROM MTC_COST_0321_OWOR T0 -- ON T1."FcCode"=T0."FcCode" AND T1."WorEntry"=T0."WorEntry"
				WHERE T0."FcCode"=:FcCode
				AND T0."WorType" IN ('10','20','30','40')
				--AND T0."ItemCode"='102000552'
				GROUP BY T0."ItemCode"
				) T2 ON T1."ItemCode"=T2."ItemCode"
		JOIN OITM T3 ON T1."ItemCode"=T3."ItemCode"
		LEFT JOIN (SELECT "FcCode",SUM("Amount") AS "ExpAmount"
					FROM "MTC_COST_0311_PRODUCTEXP_ADD"
					WHERE "FcCode"=:FcCode
					AND "ExpType" IN ('制造费用','公摊材料费用') AND IFNULL("OcrCode",'')='P017'
					GROUP BY "FcCode"
				) T4 ON 1=1
		WHERE T3."ItmsGrpCod" IN ('101')
	) T1 ON T0."ItemCode"=T1."ItemCode"	
	;
	
	
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T1."DocType"
	,T1."WorType"
	,T1."WorEntry"
	,T1."WorNum"
	,'30' AS "CostCode"
	,'制造费用' AS "ExpType"
	,ROUND(-1*T0."ExpAmt"*T2."IgnQty"/NULLIF(SUM(T2."IgnQty") OVER (PARTITION BY T1."ItemCode",T1."FcCode"),0),2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0312_PRODUCTEXP_PRC T0
	JOIN MTC_COST_0321_OWOR T1 ON T0."ItemCode"=T1."ItemCode" AND T0."FcCode"=T1."FcCode"
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry",SUM("IgnQty") AS "IgnQty"
			FROM MTC_COST_0321_OWOR
			WHERE "FcCode"=:FcCode
			GROUP BY "DocType","WorEntry"
			) T2 ON T1."FcCode"=T2."FcCode" AND T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry"
	WHERE T0."FcCode"=:FcCode
	AND T1."WorType" IN ('10','20','30','40')
	AND T0."ExpType"='制造费用' AND "CJCode"='包装车间'		
	;
	
	
	--------------------------------------人工费用（制造车间）---------------------------------------------
	INSERT INTO MTC_COST_0312_PRODUCTEXP_PRC("BPLId"
	,"FcCode"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"ExpCode"  --费用大类编码
	,"ExpName" --费用大类名称
	,"ItemCode" 
	,"CJCode" 	--车间编码（All-所有车间）
	,"IgnQty"  --入库数量
	,"Time"	  --单位工时
	,"TimeTotal" --总单位工时
	,"Prc"
	,"ExpAmt"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'40' AS "CostCode"
	,'人工费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T0."ItemCode"		--产成品的物料
	,'制造车间' AS "CJCode"
	,0 AS "IgnQty"
	,T1."Time" AS "Time"	  --单位工时
	,T1."TimeTotal" AS "TimeTotal"
	,T1."Prc" AS "Prc"
	,T1."ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OITM" T0
	LEFT JOIN 
	(
		SELECT T1."ItemCode",T1."Time",T3."ItmsGrpCod",(T1."Time"*T2."IgnQty") AS "TimeTotal"
		,(T1."Time"*T2."IgnQty")/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0) AS "Prc"
		,ROUND((T1."Time"*T2."IgnQty")*T4."ExpAmount"/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0),2) AS "ExpAmt"
		FROM (SELECT T1."U_ItemCode" AS "ItemCode",MAX(T1."U_Time") AS "Time" 
					FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry"
					WHERE T0."U_FcCode"=:FcCode GROUP BY T1."U_ItemCode"
				) T1
		JOIN (SELECT T0."ItemCode",-1*SUM(T0."Amount") AS "Amount",SUM(T0."IgnQty") AS "IgnQty"
				FROM MTC_COST_0321_OWOR T0 -- ON T1."FcCode"=T0."FcCode" AND T1."WorEntry"=T0."WorEntry"
				WHERE T0."FcCode"=:FcCode
				AND T0."WorType" IN ('10','20','30','40')
				--AND T0."ItemCode"='102000552'
				GROUP BY T0."ItemCode"
				) T2 ON T1."ItemCode"=T2."ItemCode"
		JOIN OITM T3 ON T1."ItemCode"=T3."ItemCode"
		LEFT JOIN (SELECT "FcCode",SUM("Amount") AS "ExpAmount"
					FROM "MTC_COST_0311_PRODUCTEXP_ADD"
					WHERE "FcCode"=:FcCode 
					AND "ExpType"='人工费用' AND IFNULL("OcrCode",'')<>'P017'
					GROUP BY "FcCode"
				) T4 ON 1=1
		WHERE T3."ItmsGrpCod" IN ('102','103')
	) T1 ON T0."ItemCode"=T1."ItemCode"
	
	;
	
	
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T1."DocType"
	,T1."WorType"
	,T1."WorEntry"
	,T1."WorNum"
	,'40' AS "CostCode"
	,'人工费用' AS "ExpType"
	,ROUND(-1*T0."ExpAmt"*T2."IgnQty"/NULLIF(SUM(T2."IgnQty") OVER (PARTITION BY T1."ItemCode",T1."FcCode"),0),2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0312_PRODUCTEXP_PRC T0
	JOIN MTC_COST_0321_OWOR T1 ON T0."ItemCode"=T1."ItemCode" AND T0."FcCode"=T1."FcCode"
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry",SUM("IgnQty") AS "IgnQty"
			FROM MTC_COST_0321_OWOR
			WHERE "FcCode"=:FcCode
			GROUP BY "DocType","WorEntry"
			) T2 ON T1."FcCode"=T2."FcCode" AND T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry"
	WHERE T0."FcCode"=:FcCode
	AND T1."WorType" IN ('10','20','30','40')
	AND T0."ExpType"='人工费用' AND T0."CJCode"='制造车间'
	;
	
	
	
	--------------------------------------人工费用（包装车间）---------------------------------------------
	INSERT INTO MTC_COST_0312_PRODUCTEXP_PRC("BPLId"
	,"FcCode"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"ExpCode"  --费用大类编码
	,"ExpName" --费用大类名称
	,"ItemCode" 
	,"CJCode" 	--车间编码（All-所有车间）
	,"IgnQty"  --入库数量
	,"Time"	  --单位工时
	,"TimeTotal" --总单位工时
	,"Prc"
	,"ExpAmt"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'40' AS "CostCode"
	,'人工费用' AS "ExpType"
	,NULL AS "ExpCode"
	,NULL AS "ExpName"
	,T0."ItemCode"		--产成品的物料
	,'包装车间' AS "CJCode"
	,0 AS "IgnQty"
	,T1."Time" AS "Time"	  --单位工时
	,T1."TimeTotal" AS "TimeTotal"
	,T1."Prc" AS "Prc"
	,T1."ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OITM" T0
	LEFT JOIN 
	(
		SELECT T1."ItemCode",T1."Time",T3."ItmsGrpCod",(T1."Time"*T2."IgnQty") AS "TimeTotal"
		,(T1."Time"*T2."IgnQty")/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0) AS "Prc"
		,ROUND((T1."Time"*T2."IgnQty")*T4."ExpAmount"/NULLIF(SUM(T1."Time"*T2."IgnQty") OVER (),0),2) AS "ExpAmt"
		FROM (SELECT T1."U_ItemCode" AS "ItemCode",MAX(T1."U_Time") AS "Time" 
					FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry"
					WHERE T0."U_FcCode"=:FcCode GROUP BY T1."U_ItemCode"
				) T1
		JOIN (SELECT T0."ItemCode",-1*SUM(T0."Amount") AS "Amount",SUM(T0."IgnQty") AS "IgnQty"
				FROM MTC_COST_0321_OWOR T0 -- ON T1."FcCode"=T0."FcCode" AND T1."WorEntry"=T0."WorEntry"
				WHERE T0."FcCode"=:FcCode
				AND T0."WorType" IN ('10','20','30','40')
				--AND T0."ItemCode"='102000552'
				GROUP BY T0."ItemCode"
				) T2 ON T1."ItemCode"=T2."ItemCode"
		JOIN OITM T3 ON T1."ItemCode"=T3."ItemCode"
		LEFT JOIN (SELECT "FcCode",SUM("Amount") AS "ExpAmount"
					FROM "MTC_COST_0311_PRODUCTEXP_ADD"
					WHERE "FcCode"=:FcCode 
					AND "ExpType"='人工费用' AND IFNULL("OcrCode",'')='P017'
					GROUP BY "FcCode"
				) T4 ON 1=1
		WHERE T3."ItmsGrpCod" IN ('101')
	) T1 ON T0."ItemCode"=T1."ItemCode"
	
	;
	
	
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T1."DocType"
	,T1."WorType"
	,T1."WorEntry"
	,T1."WorNum"
	,'40' AS "CostCode"
	,'人工费用' AS "ExpType"
	,ROUND(-1*T0."ExpAmt"*T2."IgnQty"/NULLIF(SUM(T2."IgnQty") OVER (PARTITION BY T1."ItemCode",T1."FcCode"),0),2) AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0312_PRODUCTEXP_PRC T0
	JOIN MTC_COST_0321_OWOR T1 ON T0."ItemCode"=T1."ItemCode" AND T0."FcCode"=T1."FcCode"
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry",SUM("IgnQty") AS "IgnQty"
			FROM MTC_COST_0321_OWOR
			WHERE "FcCode"=:FcCode
			GROUP BY "DocType","WorEntry"
			) T2 ON T1."FcCode"=T2."FcCode" AND T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry"
	WHERE T0."FcCode"=:FcCode
	AND T1."WorType" IN ('10','20','30','40')
	AND T0."ExpType"='人工费用' AND T0."CJCode"='包装车间'
	;
	
	--检查费用尾差
	TMP_DIFF=SELECT T0."ExpType",T0."CJCode",SUM(T0."分摊前") AS "分摊前",SUM(T0."分摊后") AS "分摊后"
	,SUM(IFNULL(T0."分摊前",0)-IFNULL(T0."分摊后",0)) AS"Diff"
	FROM (
		SELECT
		    CASE
		        WHEN "ExpType" IN ('制造费用','公摊材料费用') OR "ExpType" LIKE '库存重估%' THEN '制造费用'
		        WHEN "ExpType" = '人工费用' THEN '人工费用'
		    END AS "ExpType",
		    CASE
		        WHEN IFNULL("OcrCode",'') = 'P017' THEN '包装车间'
		        ELSE '制造车间'
		    END AS "CJCode",
		    CAST(SUM("Amount") AS DECIMAL(19,6)) AS "分摊前",
		    CAST(0.000000 AS DECIMAL(19,6)) AS "分摊后"
		FROM "MTC_COST_0311_PRODUCTEXP_ADD"
		WHERE "FcCode" = :FcCode
		GROUP BY
		    CASE
		        WHEN "ExpType" IN ('制造费用','公摊材料费用') OR "ExpType" LIKE '库存重估%' THEN '制造费用'
		        WHEN "ExpType" = '人工费用' THEN '人工费用'
		    END,
		    CASE
		        WHEN IFNULL("OcrCode",'') = 'P017' THEN '包装车间'
		        ELSE '制造车间'
		    END
		UNION ALL
		SELECT
		    "ExpType",
		    "CJCode",
		    CAST(0.000000 AS DECIMAL(19,6)) AS "分摊前",
		    CAST(SUM("ExpAmt") AS DECIMAL(19,6)) AS "分摊后"
		FROM MTC_COST_0312_PRODUCTEXP_PRC
		WHERE "FcCode" = :FcCode
		GROUP BY "CostCode", "ExpType", "CJCode"
	) T0 GROUP BY T0."ExpType",T0."CJCode";
	
	--差异
	SELECT '分摊前的差异',* FROM :TMP_DIFF;
	
	--处理尾差
	UPDATE T0 SET T0."ExpAmt"=T0."ExpAmt"+IFNULL(T1."Diff",0)
	FROM MTC_COST_0312_PRODUCTEXP_PRC T0
	JOIN :TMP_DIFF T1 ON T0."ExpType"=T1."ExpType" AND T0."CJCode"=T1."CJCode"
	JOIN (SELECT "ID","ExpType","CJCode","ExpAmt","ItemCode"
				,ROW_NUMBER() OVER (PARTITION BY "ExpType","CJCode" ORDER BY "ExpAmt" DESC) AS "NUMID"
				FROM MTC_COST_0312_PRODUCTEXP_PRC
				WHERE "FcCode" = :FcCode
			) T2 ON T0."ID"=T2."ID"
	WHERE T0."FcCode" = :FcCode
	AND T2.NUMID=1;
	
	--
	SELECT '检查分摊后的差异',T0."ExpType",T0."CJCode",SUM(T0."分摊前") AS "分摊前",SUM(T0."分摊后") AS "分摊后"
	,SUM(IFNULL(T0."分摊前",0)-IFNULL(T0."分摊后",0)) AS"Diff"
	FROM (
		SELECT
		    CASE
		        WHEN "ExpType" IN ('制造费用','公摊材料费用') OR "ExpType" LIKE '库存重估%' THEN '制造费用'
		        WHEN "ExpType" = '人工费用' THEN '人工费用'
		    END AS "ExpType",
		    CASE
		        WHEN IFNULL("OcrCode",'') = 'P017' THEN '包装车间'
		        ELSE '制造车间'
		    END AS "CJCode",
		    CAST(SUM("Amount") AS DECIMAL(19,6)) AS "分摊前",
		    CAST(0.000000 AS DECIMAL(19,6)) AS "分摊后"
		FROM "MTC_COST_0311_PRODUCTEXP_ADD"
		WHERE "FcCode" = :FcCode
		GROUP BY
		    CASE
		        WHEN "ExpType" IN ('制造费用','公摊材料费用') OR "ExpType" LIKE '库存重估%' THEN '制造费用'
		        WHEN "ExpType" = '人工费用' THEN '人工费用'
		    END,
		    CASE
		        WHEN IFNULL("OcrCode",'') = 'P017' THEN '包装车间'
		        ELSE '制造车间'
		    END
		UNION ALL
		SELECT
		    "ExpType",
		    "CJCode",
		    CAST(0.000000 AS DECIMAL(19,6)) AS "分摊前",
		    CAST(SUM("ExpAmt") AS DECIMAL(19,6)) AS "分摊后"
		FROM MTC_COST_0312_PRODUCTEXP_PRC
		WHERE "FcCode" = :FcCode
		GROUP BY "CostCode", "ExpType", "CJCode"
	) T0 GROUP BY T0."ExpType",T0."CJCode";
	
	--
	UPDATE T0 SET T0."3LabAmount"=IFNULL(T1."3LabAmount",0)
	,T0."2ManExp"=IFNULL(T1."2ManExp",0)
	,T0."Amount"=IFNULL(T0."1Material",0)+IFNULL(T1."Amount",0)
	FROM MTC_COST_0321_OWOR T0
	JOIN (SELECT MAX("FcCode") AS "FcCode","DocType","WorEntry"
		,-1*SUM("Amount") AS "Amount"
		,-1*SUM(CASE WHEN "CostCode"='30' THEN "Amount" ELSE 0 END) AS "3LabAmount"
		,-1*SUM(CASE WHEN "CostCode"='40' THEN "Amount" ELSE 0 END) AS "2ManExp"
		FROM MTC_COST_0321_OWOR2 GROUP BY "DocType","WorEntry"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
	WHERE 1=1
	AND T0."FcCode"=:FcCode;
	
	SELECT "BPLId",
	"FcCode",
	"WorType",
	"WorEntry",
	"WorNum",
	"CostCode",
	"ExpType",
	-1*"Amount" AS "分摊金额",
	"CreateDate",
	"Creator",
	"IgeQty",
	"DocType"
	FROM "MTC_COST_0321_OWOR2" WHERE "FcCode"=:FcCode AND IFNULL("Amount",0)<>0;

	
	

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0321_OWOR
CREATE PROCEDURE "MTC_COST_PROC_0321_OWOR"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取物料等级 到 明细到静态表 MTC_COST_0105_ITEM
     * CALL "MTC_COST_PROC_0321_OWOR"(0,'2024-01','manager');
    */
	DECLARE LastFcCode NVARCHAR(30);	--上期
	SELECT "Code" INTO LastFcCode
	FROM "OFPR" WHERE "Code" IN (SELECT MAX("Code") AS "Code" FROM "OFPR" WHERE "Code"<:FcCode);
	
	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM MTC_COST_0321_OWOR WHERE "FcCode" = :FcCode;
	DELETE FROM MTC_COST_0321_OWOR1 WHERE "FcCode" = :FcCode;
	
	--1.1OWOR
	INSERT INTO MTC_COST_0321_OWOR(
	 "BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"WorQty"
	,"Quantity"
	,"StdPrice"
	,"StdAmount"
	,"IgnQty"		--完工入库数量
	,"Amount"
	,"1Material"
	,"2ManExp"
	,"3LabAmount"
	--,"5ClosedAmt"
	,"CostMemo"
	,"iLevel"
	,"Memo"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'202' AS "DocType"
	,P."U_OrdType" AS "WorType"
	,P."DocEntry" AS "WorEntry"
	,P."DocNum" AS "WorNum"
	,P1."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P."PlannedQty" AS "WorQty"
	,P."PlannedQty" AS "Quantity"
	,0 AS "StdPrice"
	,0 AS "StdAmount"
	,IFNULL(P0."IgnQty",0)    --完工入库数量
	,0 AS "Amount"
	,0 AS "1Material"
	,0 AS "2ManExp"
	,0 AS "3LabAmount"
	--,IFNULL(P3."关单差异",0) AS "5ClosedAmt"
	,'' AS "CostMemo"
	,P2."iLevel"
	,'' AS "Memo"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "OWOR" P
	LEFT JOIN
	(
			SELECT T1."U_OrdType" AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum"
			,T1."ItemCode",T1."PlannedQty" AS "Quantity",SUM(T0."Quantity") AS "IgnQty"
			FROM "MTC_COST_0201_DOCDETAL" T0
			JOIN "OWOR" T1 ON T0."BaseType"='202' AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine" IS NULL
			LEFT JOIN "@U_CIOTRN" T2 ON T0."TransCode"=T2."Code"
			JOIN OWHS T9 ON T0."WhsCode"=T9."WhsCode"
			WHERE 1=1
			AND T9."U_IsCost"='Y'
			AND T2."U_TransType" IN ('B01')		--B01工单产出类
			AND T0."FcCode"=:FcCode
			GROUP BY T1."U_OrdType",T1."DocEntry",T1."DocNum",T1."ItemCode",T1."PlannedQty"
		) P0 ON P."DocEntry"=P0."WorEntry"
	--LEFT JOIN (SELECT * FROM MTC_COST_0322_OWOR_ZCP
	--			WHERE "期间"=:LastFcCode AND "DocType"='202'
	--	) P3 ON P."DocEntry"=P3."WorEntry"
	LEFT JOIN OITM P1 ON P."ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P."ItemCode"=P2."ItemCode"
	WHERE P."Status"<>'C'
	;
	
	--1.2OWOR
	INSERT INTO MTC_COST_0321_OWOR1(
	"BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"LineNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"IgeQty"
	,"Price"	
	,"Amount"
	,"CreateDate"
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,'202' AS "ObjType"
	,P0."WorType"
	,P0."WorEntry"
	,P0."WorNum"
	,P0."LineNum"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P0."IgeQty"    --完工入库数量
	,0 AS "Price"
	,0 AS "Amount"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM (
			SELECT T1."U_OrdType" AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum"
			,T0."ItemCode",T0."BaseLine" AS "LineNum",SUM(T0."Quantity") AS "IgeQty"
			FROM "MTC_COST_0201_DOCDETAL" T0
			JOIN "OWOR" T1 ON T0."BaseType"='202' AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine" IS NOT NULL
			LEFT JOIN "@U_CIOTRN" T2 ON T0."TransCode"=T2."Code"
			JOIN OWHS T9 ON T0."WhsCode"=T9."WhsCode"
			WHERE 1=1
			AND T9."U_IsCost"='Y'
			AND T2."U_TransType" IN ('B03')		--B01工单投入类
			AND T0."FcCode"=:FcCode
			GROUP BY T1."U_OrdType",T1."DocEntry",T1."DocNum",T0."ItemCode",T0."BaseLine"
		) P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	;
	
	--2.1"@MTC_OWOR" 返工工单
	INSERT INTO MTC_COST_0321_OWOR(
	 "BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"WorQty"
	,"Quantity"
	,"StdPrice"
	,"StdAmount"
	,"IgnQty"		--完工入库数量
	,"Amount"
	,"1Material"
	,"2ManExp"
	,"3LabAmount"
	--,"5ClosedAmt"
	,"CostMemo"
	,"iLevel"
	,"Memo"
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P."Object" AS "DocType"
	,P."U_OrdType" AS "WorType"
	,P."DocEntry" AS "WorEntry"
	,P."DocNum" AS "WorNum"
	,P1."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P."U_PlannedQty" AS "WorQty"
	,P."U_PlannedQty" AS "Quantity"
	,0 AS "StdPrice"
	,0 AS "StdAmount"
	,IFNULL(P0."IgnQty",0)    --完工入库数量
	,0 AS "Amount"
	,0 AS "1Material"
	,0 AS "2ManExp"
	,0 AS "3LabAmount"
	--,IFNULL(P3."关单差异",0) AS "5ClosedAmt"
	,'' AS "CostMemo"
	,P2."iLevel"
	,'' AS "Memo"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM "@MTC_OWOR" P
	LEFT JOIN
	(
			SELECT T1."U_OrdType" AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum"
			,T1."U_ItemCode" AS "ItemCode",T1."U_PlannedQty" AS "Quantity",SUM(T0."Quantity") AS "IgnQty"
			FROM "MTC_COST_0201_DOCDETAL" T0
			JOIN "@MTC_OWOR" T1 ON T0."BaseType"=T1."Object" AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine" IS NULL
			LEFT JOIN "@U_CIOTRN" T2 ON T0."TransCode"=T2."Code"
			JOIN OWHS T9 ON T0."WhsCode"=T9."WhsCode"
			WHERE 1=1
			AND T9."U_IsCost"='Y'
			AND T2."U_TransType" IN ('B01')		--B01工单产出类
			AND T0."FcCode"=:FcCode
			GROUP BY T1."U_OrdType",T1."DocEntry",T1."DocNum",T1."U_ItemCode",T1."U_PlannedQty"
		) P0 ON P."DocEntry"=P0."WorEntry"
	--LEFT JOIN (SELECT * FROM MTC_COST_0322_OWOR_ZCP
	--			WHERE "期间"=:LastFcCode AND "DocType"='MTC_OWOR'
	--	) P3 ON P."DocEntry"=P3."WorEntry"
	LEFT JOIN OITM P1 ON P."U_ItemCode"=P1."ItemCode"
	LEFT JOIN U_COILV P2 ON P2."FcCode"=:FcCode AND P."U_ItemCode"=P2."ItemCode"
	WHERE P."U_Status"<>'C'
	;

	--2.2 "@MTC_OWOR"返工工单
	INSERT INTO MTC_COST_0321_OWOR1(
	"BPLId"
	,"FcCode"
	,"DocType"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"LineNum"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"IgeQty"
	,"Price"	
	,"Amount"
	,"CreateDate"
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,P0."ObjType"
	,P0."WorType"
	,P0."WorEntry"
	,P0."WorNum"
	,P0."LineNum"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,P0."IgeQty"    --完工入库数量
	,0 AS "Price"
	,0 AS "Amount"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM (
			SELECT T1."Object" AS "ObjType",T1."U_OrdType" AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum"
			,T0."ItemCode",T0."BaseLine" AS "LineNum",SUM(T0."Quantity") AS "IgeQty"
			FROM "MTC_COST_0201_DOCDETAL" T0
			JOIN "@MTC_OWOR" T1 ON T0."BaseType"=T1."Object" AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine" IS NOT NULL
			LEFT JOIN "@U_CIOTRN" T2 ON T0."TransCode"=T2."Code"
			JOIN OWHS T9 ON T0."WhsCode"=T9."WhsCode"
			WHERE 1=1
			AND T9."U_IsCost"='Y'
			AND T2."U_TransType" IN ('B03')		--B01工单投入类
			AND T0."FcCode"=:FcCode
			GROUP BY T1."Object",T1."U_OrdType",T1."DocEntry",T1."DocNum",T0."ItemCode",T0."BaseLine"
		) P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	;
	
	SELECT '成功' FROM DUMMY;
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0402_CAL_OWOR
CREATE PROCEDURE "MTC_COST_PROC_0402_CAL_OWOR"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50),IN iLevel INT,IN WorNum NVARCHAR(30) DEFAULT '')
LANGUAGE SQLSCRIPT
AS
BEGIN

	--除掉30类型的返工单的
	DELETE FROM MTC_COST_0321_OWOR_SUM WHERE "iLevel"=:iLevel AND "FcCode"=:FcCode AND ("WorNum" = :WorNum OR :WorNum='') AND "WorType"<>'30';
	DELETE FROM MTC_COST_0321_OWOR1_REG WHERE "iLevel"=:iLevel AND "FcCode"=:FcCode AND ("WorNum" = :WorNum OR :WorNum='') AND "WorType"<>'30';
	
	
	INSERT INTO MTC_COST_0321_OWOR_SUM(
	"BPLId", "FcCode","DocType","WorType", "WorEntry", "WorNum",
	"DocDate","CloseDate","Status",
	"ItemCode","ItemName","ItmsGrpCod","iLevel"
	,"WorQty","Ign_SUM","Amount_SUM","1Material_SUM","2ManExp_SUM","3LabAmount_SUM","4WWExp_SUM","CloseDifAmt"
	,"IgnQty","Price","Amount","1Material","2ManExp","3LabAmount","4WWExp"
	,"CreateDate", "Creator")
	SELECT 0,T0."FcCode",T0."DocType",T9."U_OrdType",T0."WorEntry",T0."WorNum"
	,T9."PostDate",T9."CloseDate",T9."Status"
	,T0."ItemCode" AS "物料编码",T7."ItemName",T8."ItmsGrpNam",T2."iLevel" AS "物料等级"
	,T0."Quantity" AS "生产订单数量",T3."IgnQty" AS "Ign_SUM"
	,ROUND(IFNULL(T3."Amount",0),2) AS "Amount_SUM"
	,ROUND(T3."1Material",2) AS "1Material_SUM" --实际投料总额(累计投料)
	,ROUND(T3."2ManExp",2) AS "2ManExp_SUM",ROUND(T3."3LabAmount",2) AS "3LabAmount_SUM"
	,ROUND(T3."4WWExp",2) AS "4WWExp_SUM",ROUND(T3."5ClosedAmt",2) AS "CloseDifAmt"
	,T0."IgnQty" AS "IgnQty"
	--当订单数量大于完工入库数量的时候，则是未完工，取实际折算半成品的数量，否则是实际的金额
	,(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END
			+IFNULL(T0."2ManExp",0)+IFNULL(T0."3LabAmount",0)+IFNULL(T0."4WWExp",0))/NULLIF(T0."IgnQty",0)
			AS "Price"
	,ROUND(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END
		+IFNULL(T0."2ManExp",0)+IFNULL(T0."3LabAmount",0)+IFNULL(T0."4WWExp",0),2) AS "Amount"	
	,ROUND(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END,2)
		AS "计入完工材料"	--理论完工总额（计入已完工生产成本）
	,ROUND(T0."2ManExp",2),ROUND(T0."3LabAmount",2),ROUND(T0."4WWExp",2)
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
				SELECT :FcCode AS "FcCode",T1."DocType",T1."WorEntry",-1*SUM(T1."IgeQty") AS "IgeQty"
				--累计截止到现在的数据：SUM(单个完工产品成本=单位材料成本(领料金额/领料数量)*按照实际完工量计算出的理论用料)
				--按照实际完工量计算出的理论用料=实际入库数量*生产订单的计划用量比（材料计划用量/产成品计划完工数量）
				,SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
						THEN -1*T1."Amount"/NULLIF(T0."IgnQty_SUM",0)*T0."IgnQty" ELSE
					  (-1*T1."Amount")/NULLIF((-1*T1."IgeQty"),0)*T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Amount"	--按领料比例折算的金额（当领料数量少于入库数量比的时候，先取实际投料的金额）
				,SUM(-1*T1."Amount") AS "ActAmount"
				FROM 	
					(
						SELECT T1."DocType",T1."WorEntry",T1."ItemCode",T1."Amount",T1."IgeQty",T2."Wor1Qty",T2."OworQty"
						FROM 
						(SELECT T1."DocType",T1."WorEntry",T1."ItemCode",SUM(T1."Amount") AS "Amount",SUM(T1."IgeQty") AS "IgeQty"
							FROM MTC_COST_0321_OWOR1 T1
							WHERE T1."FcCode"<=:FcCode GROUP BY T1."DocType",T1."WorEntry",T1."ItemCode") T1
						LEFT JOIN (SELECT M."DocType",D."WorEntry",D."ItemCode",SUM(D."Quantity") AS "Wor1Qty",M."Quantity" AS "OworQty"
										FROM MTC_COST_0106_OWORLIST1 D
										JOIN MTC_COST_0106_OWORLIST M ON M."FcCode"=D."FcCode" AND M."DocType"=D."DocType" AND D."WorEntry"=M."WorEntry"
										WHERE 1=1 AND M."FcCode"=:FcCode GROUP BY M."DocType",D."WorEntry",D."ItemCode",M."Quantity"
									) T2 ON T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry" AND T1."ItemCode"=T2."ItemCode"
					) T1
				JOIN (SELECT "DocType","WorEntry",SUM("IgnQty") AS "IgnQty_SUM"
					 ,SUM(CASE WHEN "FcCode"=:FcCode THEN "IgnQty" ELSE 0 END) AS "IgnQty"
					FROM MTC_COST_0321_OWOR WHERE "FcCode"<=:FcCode GROUP BY "DocType","WorEntry") T0 ON T1."DocType"=T0."DocType" AND T1."WorEntry"=T0."WorEntry"
				WHERE 1=1 GROUP BY T1."DocType",T1."WorEntry"
			) T1 ON  T0."FcCode"=T1."FcCode" AND T1."DocType"=T0."DocType" AND T0."WorEntry"=T1."WorEntry"
		--累计【制造费用+人工费用+委外费用】
		LEFT JOIN (
				SELECT T0."BPLId",:FcCode AS "FcCode",T0."DocType",T0."WorEntry"
				,SUM(T0."Amount") AS "Amount"
				--,SUM((-1*T2."Amount")/(-1*NULLIF(T2."IgeQty",0))*T0."IgnQty") AS "Amount"
				,SUM("4WWExp") AS "4WWExp"
				,SUM("3LabAmount") AS "3LabAmount"
				,SUM("2ManExp") AS "2ManExp"
				,SUM("1Material") AS "1Material"
				,SUM("IgnQty") AS "IgnQty"
				,SUM("5ClosedAmt") AS "5ClosedAmt"
				FROM MTC_COST_0321_OWOR T0
				WHERE T0."FcCode"<=:FcCode GROUP BY T0."BPLId",T0."DocType",T0."WorEntry"
			) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."DocType"=T3."DocType" AND T0."WorEntry"=T3."WorEntry"
		JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
		JOIN OITM T7 ON T0."ItemCode"=T7."ItemCode"
		JOIN OITB T8 ON T7."ItmsGrpCod"=T8."ItmsGrpCod"
		JOIN (SELECT '202' AS "DocType","DocEntry","DocNum","U_OrdType","PostDate","CloseDate","Status" FROM OWOR
				UNION ALL
			 SELECT "Object" AS "DocType","DocEntry","DocNum","U_OrdType","U_PostDate","U_CloseDate","U_Status" FROM "@MTC_OWOR" 
			) T9 ON T0."DocType"=T9."DocType" AND T0."WorEntry"=T9."DocEntry"
		WHERE T2."iLevel"=:iLevel AND T0."FcCode"=:FcCode AND (T0."WorNum" = :WorNum OR :WorNum='')
		AND T0."WorType"<>'30'
		;
		
		--写入在产品结转明细表
		INSERT INTO "MTC_COST_0321_OWOR1_REG"(
		"BPLId","FcCode","iLevel","DocType","WorType","WorEntry","WorNum",
		"LineNum","ItemCode","ItemName","ItmsGrpCod",
		"IgeQty","Price","Amount",
		"CreateDate","Creator"
		)
		SELECT 0 AS "BPLId",:FcCode AS "FcCode",T."iLevel",T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",
		0 AS "LineNum",T1."ItemCode",T7."ItemName",T7."ItmsGrpCod",
		-1*SUM(T1."IgeQty") AS "IgeQty",0 AS "Price",
		--累计截止到现在的数据：SUM(单个完工产品成本=单位材料成本(领料金额/领料数量)*按照实际完工量计算出的理论用料)
		--按照实际完工量计算出的理论用料=实际入库数量*生产订单的计划用量比（材料计划用量/产成品计划完工数量）
		SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
				THEN -1*T1."Amount"/NULLIF(T0."IgnQty_SUM",0)*T0."IgnQty" ELSE
			  (-1*T1."Amount")/NULLIF((-1*T1."IgeQty"),0)*T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Amount",	--按领料比例折算的金额（当领料数量少于入库数量比的时候，先取实际投料的金额）
		--,SUM(-1*T1."Amount") AS "ActAmount"
		CURRENT_TIMESTAMP,:UserCode
		FROM MTC_COST_0321_OWOR T 
		JOIN
			(
				SELECT T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode",T1."Amount",T1."IgeQty",T2."Wor1Qty",T2."OworQty"
				FROM 
				(SELECT T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode",SUM(T1."Amount") AS "Amount",SUM(T1."IgeQty") AS "IgeQty"
					FROM MTC_COST_0321_OWOR1 T1
					WHERE T1."FcCode"<=:FcCode GROUP BY T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode"
				) T1
				LEFT JOIN (SELECT M."DocType",D."WorEntry",D."ItemCode",SUM(D."Quantity") AS "Wor1Qty",M."Quantity" AS "OworQty"
								FROM MTC_COST_0106_OWORLIST1 D
								JOIN MTC_COST_0106_OWORLIST M ON M."FcCode"=D."FcCode" AND M."DocType"=D."DocType" AND D."WorEntry"=M."WorEntry"
								WHERE 1=1 AND M."FcCode"=:FcCode GROUP BY M."DocType",D."WorEntry",D."ItemCode",M."Quantity"
							) T2 ON T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry" AND T1."ItemCode"=T2."ItemCode"
			) T1 ON T."DocType"=T1."DocType" AND T."WorEntry"=T1."WorEntry"
		JOIN (SELECT "DocType","WorEntry",SUM("IgnQty") AS "IgnQty_SUM"
			 ,SUM(CASE WHEN "FcCode"=:FcCode THEN "IgnQty" ELSE 0 END) AS "IgnQty"
			FROM MTC_COST_0321_OWOR WHERE "FcCode"<=:FcCode GROUP BY "DocType","WorEntry"
			) T0 ON T1."DocType"=T0."DocType" AND T1."WorEntry"=T0."WorEntry"
		JOIN U_COILV T2 ON T."FcCode"=T2."FcCode" AND T."ItemCode"=T2."ItemCode"
		JOIN OITM T7 ON T1."ItemCode"=T7."ItemCode"
		WHERE 1=1 AND T2."iLevel"=:iLevel AND T."FcCode"=:FcCode AND (T."WorNum" = :WorNum OR :WorNum='')
		AND T."WorType"<>'30'
		GROUP BY T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T."iLevel",
		T1."ItemCode",T7."ItemName",T7."ItmsGrpCod";
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0402_CAL_OWOR_30
CREATE PROCEDURE "MTC_COST_PROC_0402_CAL_OWOR_30"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50),IN iLevel INT,IN WorNum NVARCHAR(30) DEFAULT '')
LANGUAGE SQLSCRIPT
AS
BEGIN
	--返工单
	DELETE FROM MTC_COST_0321_OWOR_SUM WHERE "iLevel"=:iLevel AND "FcCode"=:FcCode AND ("WorNum" = :WorNum OR :WorNum='') AND "WorType"='30';
	DELETE FROM MTC_COST_0321_OWOR1_REG WHERE "iLevel"=:iLevel AND "FcCode"=:FcCode AND ("WorNum" = :WorNum OR :WorNum='') AND "WorType"='30';
	
	
	INSERT INTO MTC_COST_0321_OWOR_SUM(
	"BPLId", "FcCode","DocType","WorType", "WorEntry", "WorNum",
	"DocDate","CloseDate","Status",
	"ItemCode","ItemName","ItmsGrpCod","iLevel"
	,"WorQty","Ign_SUM","Amount_SUM","1Material_SUM","2ManExp_SUM","3LabAmount_SUM","4WWExp_SUM","CloseDifAmt"
	,"IgnQty","Price","Amount","1Material","2ManExp","3LabAmount","4WWExp"
	,"CreateDate", "Creator")
	SELECT 0,T0."FcCode",T0."DocType",T9."U_OrdType",T0."WorEntry",T0."WorNum"
	,T9."PostDate",T9."CloseDate",T9."Status"
	,T0."ItemCode" AS "物料编码",T7."ItemName",T8."ItmsGrpNam",T2."iLevel" AS "物料等级"
	,T0."Quantity" AS "生产订单数量",T3."IgnQty" AS "Ign_SUM"
	,ROUND(IFNULL(T3."Amount",0),2) AS "Amount_SUM"
	,ROUND(T3."1Material",2) AS "1Material_SUM" --实际投料总额(累计投料)
	,ROUND(T3."2ManExp",2) AS "2ManExp_SUM",ROUND(T3."3LabAmount",2) AS "3LabAmount_SUM"
	,ROUND(T3."4WWExp",2) AS "4WWExp_SUM",ROUND(T3."5ClosedAmt",2) AS "CloseDifAmt"
	,T0."IgnQty" AS "IgnQty"
	--当订单数量大于完工入库数量的时候，则是未完工，取实际折算半成品的数量，否则是实际的金额
	,(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END
			+IFNULL(T0."2ManExp",0)+IFNULL(T0."3LabAmount",0)+IFNULL(T0."4WWExp",0))/NULLIF(T0."IgnQty",0)
			AS "Price"
	,ROUND(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END
		+IFNULL(T0."2ManExp",0)+IFNULL(T0."3LabAmount",0)+IFNULL(T0."4WWExp",0),2) AS "Amount"	
	,ROUND(CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END,2)
		AS "计入完工材料"	--理论完工总额（计入已完工生产成本）
	,ROUND(T0."2ManExp",2),ROUND(T0."3LabAmount",2),ROUND(T0."4WWExp",2)
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
				SELECT :FcCode AS "FcCode",T1."DocType",T1."WorEntry",-1*SUM(T1."IgeQty") AS "IgeQty"
				--累计截止到现在的数据：SUM(单个完工产品成本=单位材料成本(领料金额/领料数量)*按照实际完工量计算出的理论用料)
				--按照实际完工量计算出的理论用料=实际入库数量*生产订单的计划用量比（材料计划用量/产成品计划完工数量）
				,SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
						THEN -1*T1."Amount"/NULLIF(T0."IgnQty_SUM",0)*T0."IgnQty" ELSE
					  (-1*T1."Amount")/NULLIF((-1*T1."IgeQty"),0)*T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Amount"	--按领料比例折算的金额（当领料数量少于入库数量比的时候，先取实际投料的金额）
				,SUM(-1*T1."Amount") AS "ActAmount"
				FROM 	
					(
						SELECT T1."DocType",T1."WorEntry",T1."ItemCode",T1."Amount",T1."IgeQty",T2."Wor1Qty",T2."OworQty"
						FROM 
						(SELECT T1."DocType",T1."WorEntry",T1."ItemCode",SUM(T1."Amount") AS "Amount",SUM(T1."IgeQty") AS "IgeQty"
							FROM MTC_COST_0321_OWOR1 T1
							WHERE T1."FcCode"<=:FcCode GROUP BY T1."DocType",T1."WorEntry",T1."ItemCode") T1
						LEFT JOIN (SELECT M."DocType",D."WorEntry",D."ItemCode",SUM(D."Quantity") AS "Wor1Qty",M."Quantity" AS "OworQty"
										FROM MTC_COST_0106_OWORLIST1 D
										JOIN MTC_COST_0106_OWORLIST M ON M."FcCode"=D."FcCode" AND M."DocType"=D."DocType" AND D."WorEntry"=M."WorEntry"
										WHERE 1=1 AND M."FcCode"=:FcCode GROUP BY M."DocType",D."WorEntry",D."ItemCode",M."Quantity"
									) T2 ON T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry" AND T1."ItemCode"=T2."ItemCode"
					) T1
				JOIN (SELECT "DocType","WorEntry",SUM("IgnQty") AS "IgnQty_SUM"
					 ,SUM(CASE WHEN "FcCode"=:FcCode THEN "IgnQty" ELSE 0 END) AS "IgnQty"
					FROM MTC_COST_0321_OWOR WHERE "FcCode"<=:FcCode GROUP BY "DocType","WorEntry") T0 ON T1."DocType"=T0."DocType" AND T1."WorEntry"=T0."WorEntry"
				WHERE 1=1 GROUP BY T1."DocType",T1."WorEntry"
			) T1 ON  T0."FcCode"=T1."FcCode" AND T1."DocType"=T0."DocType" AND T0."WorEntry"=T1."WorEntry"
		--累计【制造费用+人工费用+委外费用】
		LEFT JOIN (
				SELECT T0."BPLId",:FcCode AS "FcCode",T0."DocType",T0."WorEntry"
				,SUM(T0."Amount") AS "Amount"
				--,SUM((-1*T2."Amount")/(-1*NULLIF(T2."IgeQty",0))*T0."IgnQty") AS "Amount"
				,SUM("4WWExp") AS "4WWExp"
				,SUM("3LabAmount") AS "3LabAmount"
				,SUM("2ManExp") AS "2ManExp"
				,SUM("1Material") AS "1Material"
				,SUM("IgnQty") AS "IgnQty"
				,SUM("5ClosedAmt") AS "5ClosedAmt"
				FROM MTC_COST_0321_OWOR T0
				WHERE T0."FcCode"<=:FcCode GROUP BY T0."BPLId",T0."DocType",T0."WorEntry"
			) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."DocType"=T3."DocType" AND T0."WorEntry"=T3."WorEntry"
		JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
		JOIN OITM T7 ON T0."ItemCode"=T7."ItemCode"
		JOIN OITB T8 ON T7."ItmsGrpCod"=T8."ItmsGrpCod"
		JOIN (SELECT '202' AS "DocType","DocEntry","DocNum","U_OrdType","PostDate","CloseDate","Status" FROM OWOR
				UNION ALL
			 SELECT "Object" AS "DocType","DocEntry","DocNum","U_OrdType","U_PostDate","U_CloseDate","U_Status" FROM "@MTC_OWOR" 
			) T9 ON T0."DocType"=T9."DocType" AND T0."WorEntry"=T9."DocEntry"
		WHERE T2."iLevel"=:iLevel AND T0."FcCode"=:FcCode AND (T0."WorNum" = :WorNum OR :WorNum='')
		AND T0."WorType"='30'
		;
		
		--写入在产品结转明细表
		INSERT INTO "MTC_COST_0321_OWOR1_REG"(
		"BPLId","FcCode","iLevel","DocType","WorType","WorEntry","WorNum",
		"LineNum","ItemCode","ItemName","ItmsGrpCod",
		"IgeQty","Price","Amount",
		"CreateDate","Creator"
		)
		SELECT 0 AS "BPLId",:FcCode AS "FcCode",T."iLevel",T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",
		0 AS "LineNum",T1."ItemCode",T7."ItemName",T7."ItmsGrpCod",
		-1*SUM(T1."IgeQty") AS "IgeQty",0 AS "Price",
		--累计截止到现在的数据：SUM(单个完工产品成本=单位材料成本(领料金额/领料数量)*按照实际完工量计算出的理论用料)
		--按照实际完工量计算出的理论用料=实际入库数量*生产订单的计划用量比（材料计划用量/产成品计划完工数量）
		SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
				THEN -1*T1."Amount"/NULLIF(T0."IgnQty_SUM",0)*T0."IgnQty" ELSE
			  (-1*T1."Amount")/NULLIF((-1*T1."IgeQty"),0)*T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Amount",	--按领料比例折算的金额（当领料数量少于入库数量比的时候，先取实际投料的金额）
		--,SUM(-1*T1."Amount") AS "ActAmount"
		CURRENT_TIMESTAMP,:UserCode
		FROM MTC_COST_0321_OWOR T 
		JOIN
			(
				SELECT T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode",T1."Amount",T1."IgeQty",T2."Wor1Qty",T2."OworQty"
				FROM 
				(SELECT T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode",SUM(T1."Amount") AS "Amount",SUM(T1."IgeQty") AS "IgeQty"
					FROM MTC_COST_0321_OWOR1 T1
					WHERE T1."FcCode"<=:FcCode GROUP BY T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T1."ItemCode"
				) T1
				LEFT JOIN (SELECT M."DocType",D."WorEntry",D."ItemCode",SUM(D."Quantity") AS "Wor1Qty",M."Quantity" AS "OworQty"
								FROM MTC_COST_0106_OWORLIST1 D
								JOIN MTC_COST_0106_OWORLIST M ON M."FcCode"=D."FcCode" AND M."DocType"=D."DocType" AND D."WorEntry"=M."WorEntry"
								WHERE 1=1 AND M."FcCode"=:FcCode GROUP BY M."DocType",D."WorEntry",D."ItemCode",M."Quantity"
							) T2 ON T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry" AND T1."ItemCode"=T2."ItemCode"
			) T1 ON T."DocType"=T1."DocType" AND T."WorEntry"=T1."WorEntry"
		JOIN (SELECT "DocType","WorEntry",SUM("IgnQty") AS "IgnQty_SUM"
			 ,SUM(CASE WHEN "FcCode"=:FcCode THEN "IgnQty" ELSE 0 END) AS "IgnQty"
			FROM MTC_COST_0321_OWOR WHERE "FcCode"<=:FcCode GROUP BY "DocType","WorEntry"
			) T0 ON T1."DocType"=T0."DocType" AND T1."WorEntry"=T0."WorEntry"
		JOIN U_COILV T2 ON T."FcCode"=T2."FcCode" AND T."ItemCode"=T2."ItemCode"
		JOIN OITM T7 ON T1."ItemCode"=T7."ItemCode"
		WHERE 1=1 AND T2."iLevel"=:iLevel AND T."FcCode"=:FcCode AND (T."WorNum" = :WorNum OR :WorNum='')
		AND T."WorType"='30'
		GROUP BY T1."DocType",T1."WorType",T1."WorEntry",T1."WorNum",T."iLevel",
		T1."ItemCode",T7."ItemName",T7."ItmsGrpCod";
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0401_CAL
CREATE PROCEDURE "MTC_COST_PROC_0401_CAL"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取物料等级 到 明细到静态表 MTC_COST_0105_ITEM
     * CALL "MTC_COST_PROC_0401_CAL"(0,'2024-01','manager');
    */
    
    DECLARE CNT INT = 0;
    DECLARE ILEVEL INT = 1;
    DECLARE MAXLEVEL INT = 0;
    
    
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
    
    DELETE FROM MTC_COST_0303_INVNTLIST WHERE "FcCode"=:FcCode AND "ObjType" NOT IN ('20','21');
    
    --SELECT * FROM MTC_COST_0301_INVNT WHERE "CostCode"='20' AND "ItemCode"='FH1360401';
	/* 2026.2.8去掉
	 --O07、O08返工领料，如果一定要写返工领料 需要先写入到MTC_COST_0302_INVNTDETAIL1
   	UPDATE T1 SET T1."Price"=T3."Price",T1."Amount"=T1."IgeQty"*T3."Price"
   	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Step0000写入'
   	,T1."IsUpdatePrice"='0000'
	FROM MTC_COST_0321_OWOR1 T1
	JOIN U_COILV T2 ON T1."ItemCode"=T2."ItemCode" AND T1."FcCode"=T2."FcCode"
	JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "CostCode"='20'
		) T3 ON T1."ItemCode"=T3."ItemCode" AND T1."FcCode"=T3."FcCode"
	WHERE 1=1
	AND T1."FcCode"=:FcCode
	AND T1."DocType"='MTC_OWOR'
	--WHERE T2."ItmsGrpCod"='103'
	--AND T2."ItemCode"='102000866'	
	;
	*/
	
	--chris.li 2026.9.9 
	
		--取消的交货单取原始单据的成本,DLN01是取消上期的，DLN02是取消本期的
		UPDATE T0 SET T0."Amount"=-1*T1."Amount",T0."Price"=T1."Price"
	   	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.8091取消交货单写入'
	   	,T0."IsUpdatePrice"='DLN01'
		FROM "MTC_COST_0302_INVNTDETAIL1" T0
		--取消关联的源单
		JOIN "MTC_COST_0302_INVNTDETAIL1" T1 ON T0."BaseType"=T1."ObjType" AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine"=T1."LineNum"
		WHERE 1=1
		AND T0."ObjType"='15'
		AND T0."FcCode"=:FcCode
		AND T1."FcCode"<:FcCode --取上期的
		--AND IFNULL(T0."IsUpdatePrice",'')<>'DLN01'
		;
		
		
		--取消的销售退货单取原始单据的成本,RD01是取消上期的，RD02是取消本期的
		UPDATE T0 SET T0."Amount"=-1*T1."Amount",T0."Price"=T1."Price"
	   	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.8092取消退货单写入'
	   	,T0."IsUpdatePrice"='RDN01'
		FROM "MTC_COST_0302_INVNTDETAIL1" T0
		--取消关联的源单
		JOIN "MTC_COST_0302_INVNTDETAIL1" T1 ON T0."BaseType"=T1."ObjType" AND T0."BaseEntry"=T1."DocEntry" AND T0."BaseLine"=T1."LineNum"
		WHERE 1=1
		AND T0."ObjType"='16'
		AND T0."FcCode"=:FcCode
		AND T1."FcCode"<:FcCode --取上期的
		--AND IFNULL(T0."IsUpdatePrice",'')<>'RDN01'
		;
	
	--2026.1.8增加退料的写入
    UPDATE T1 
	SET T1."Amount"=ROUND(T1."Quantity"*IFNULL(T2."Price",0),2),T1."Price"=IFNULL(T2."Price",0)
	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.TL44写入,退料'
	,T1."IsUpdatePrice"='TL44'
    FROM MTC_COST_0302_INVNTDETAIL1 T1
    JOIN (SELECT "BaseType","BaseEntry","BaseLine",SUM("Amount")/NULLIF(SUM("Quantity"),0) AS "Price"
    		FROM MTC_COST_0302_INVNTDETAIL1 WHERE "ObjType"='60'
    		GROUP BY "BaseType","BaseEntry","BaseLine"
    	) T2 ON T1."BaseType"=T2."BaseType" AND T1."BaseEntry"=T2."BaseEntry" AND T1."BaseLine"=T2."BaseLine"
    WHERE 1=1
	AND IFNULL(T1."IsUpdatePrice",'')<>'NoCost'
	AND T1."ObjType" IN ('59')
	AND T1."TransCode" IN ('O03','O07')  --O03 生产发料  O07生产返工领料 2026.2.8增加O07
	AND T1."BusiType"='304' --生产退料
	AND T1."CostCode"='20'	--材料
	AND T1."FcCode"=:FcCode
	AND ((IFNULL(T2."Price",0)<>0 AND IFNULL(T1."Price",0)=0));
	
	--20251204增加只有生产退料
	--根据期初维护的价格写入价格为0的
	UPDATE T0
	SET T0."Amount"=ROUND(T0."Quantity"*IFNULL(T1."U_Price",0),2),T0."Price"=IFNULL(T1."U_Price",0)
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Step43写入,退料'
	,T0."IsUpdatePrice"='304'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT T1."U_ItemCode",T1."U_Price",T1."U_IsY"
			FROM "@MTC_COST_QCPRICE" T0
			JOIN "@MTC_COST_QCPRICE1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."Canceled"='N' AND T0."U_FcCode"=:FcCode
		) T1 ON T0."ItemCode"=T1."U_ItemCode"
	WHERE 1=1
	AND IFNULL(T0."IsUpdatePrice",'')<>'NoCost'
	AND T0."ObjType" IN ('60','59')
	AND T0."TransCode" IN ('O03','O07') -- 2026.2.8增加O07生产返工
	AND T0."BusiType"='304' --生产退料
	AND T0."CostCode"='20'	--材料
	AND T0."FcCode"=:FcCode
	AND ((IFNULL(T1."U_Price",0)<>0 AND IFNULL(T0."Price",0)=0));
	
    
	--更新写入价格至MTC_COST_0302_INVNTDETAIL1
	UPDATE T0 SET T0."Amount"=ROUND(T0."Quantity"*CASE WHEN IFNULL(T1."Price",0)=0 THEN T9."Price" ELSE T1."Price" END,2)
	,T0."Price"=CASE WHEN IFNULL(T1."Price",0)=0 THEN T9."Price" ELSE T1."Price" END
   	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Step1201写入(O03、O09)'
   	,T0."IsUpdatePrice"='PP00'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN MTC_COST_0301_INVNT T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	LEFT JOIN (SELECT "FcCode","ItemCode",SUM("Amount")/NULLIF(SUM("Quantity"),0) AS "Price" FROM MTC_COST_0302_INVNTDETAIL1
				WHERE "Quantity">0
				GROUP BY "FcCode","ItemCode"
				) T9 ON T0."FcCode"=T9."FcCode" AND T0."ItemCode"=T9."ItemCode"
	WHERE T1."CostCode"='20'
	AND T0."TransCode" IN ('O03','O09','O07','O08')  --O03 生产发料 O09委外出库  O07生产返工领料  O08委外返工领料  2026.2.8增加O07、O08
	AND T0."FcCode"=:FcCode
	AND T2."iLevel"=0
	AND IFNULL(T0."IsUpdatePrice",'')=''
	;
	/*
	 --写入生产订单明细 2026.2.8注释掉
   	UPDATE T1 SET T1."Price"=T3."Price",T1."Amount"=T1."IgeQty"*T3."Price"
   	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Step1001写入'
   	,T1."IsUpdatePrice"='1001'
	FROM MTC_COST_0321_OWOR1 T1
	JOIN U_COILV T2 ON T1."ItemCode"=T2."ItemCode" AND T1."FcCode"=T2."FcCode"
	JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "CostCode"='20'
		) T3 ON T1."ItemCode"=T3."ItemCode" AND T1."FcCode"=T3."FcCode"
	WHERE 1=1
	AND T1."FcCode"=:FcCode
	AND T2."iLevel"=0
	--WHERE T2."ItmsGrpCod"='103'
	--AND T2."ItemCode"='102000866'	
	;*/
	
	 --写入生产订单明细 2026.2.8修改从出入库明细里取
   	UPDATE T1 SET 
   	 T1."Price"=T3."IgeAmt"/NULLIF(T1."IgeQty",0)
   	,T1."Amount"=T3."IgeAmt"
   	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Step1001写入new Line=119'
   	,T1."IsUpdatePrice"='1001'
	FROM MTC_COST_0321_OWOR1 T1
	JOIN U_COILV T2 ON T1."ItemCode"=T2."ItemCode" AND T1."FcCode"=T2."FcCode"
	JOIN (SELECT "FcCode","BaseType","BaseEntry","BaseLine","ItemCode",SUM(ROUND("Amount",2)) AS "IgeAmt"
			FROM MTC_COST_0302_INVNTDETAIL1
			WHERE "TransCode" IN ('O03','O07','O08','O09') --O03 生产发料 O09委外出库  O07生产返工领料  O08委外返工领料  2026.2.8增加O07、O08
			GROUP BY "FcCode","BaseType","BaseEntry","BaseLine","ItemCode"
		) T3 ON T1."ItemCode"=T3."ItemCode" AND T1."FcCode"=T3."FcCode" AND T1."DocType"=T3."BaseType"
				AND T1."WorEntry"=T3."BaseEntry" AND T1."LineNum"=T3."BaseLine"
	WHERE 1=1
	AND T1."FcCode"=:FcCode
	AND T2."iLevel"=0
	--WHERE T2."ItmsGrpCod"='103'
	--AND T2."ItemCode"='102000866'	
	;
	
	/* 还需要等待确认
	--期初的写入生产退料
	UPDATE T0 SET T0."Amount"=T0."Quantity"*T1."Price",T0."Price"=T1."Price"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN MTC_COST_0301_INVNT T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T1."CostCode"='20'
	AND T0."TransCode" IN ('59-303','59-304','59-305','59-203')
	AND T0."FcCode"=:FcCode 
	--AND T2."iLevel"=0 AND T0."ItemCode"='122000002'
   ;*/
    
    ----------------------------------------------------iLevel = 0 -------------------------------------------
	
    --写入当月成本只当月的MTC_COST_0321_OWOR
	 UPDATE T0 SET T0."Amount"=(IFNULL(T1."Amount",0)+IFNULL(T3."Amount",0))
	,T0."1Material"=T1."Amount"
	,T0."2ManExp"=T3."2ManExp"
	,T0."3LabAmount"=T3."3LabAmount"
	,T0."4WWExp"=T3."4ExpAmt"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Level0写入'
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
			SELECT T1."BPLId",:FcCode AS "FcCode",T1."DocType",T1."WorEntry",SUM(T1."IgeQty") AS "IgeQty"
			,-1*SUM(ROUND(T1."Amount",2)) AS "Amount"
			--,SUM(T1."Amount"/NULLIF(T1."IgeQty",0)*T0."IgnQty") AS "Amount"
			FROM MTC_COST_0321_OWOR1 T1
			JOIN MTC_COST_0321_OWOR T0 ON T0."DocType"=T1."DocType" AND T1."WorEntry"=T0."WorEntry" AND T0."FcCode"=T1."FcCode"
			WHERE T1."FcCode"=:FcCode GROUP BY T1."BPLId",T1."DocType",T1."WorEntry"
		) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
	--制造费用+人工费用+委外费用
	LEFT JOIN (
			SELECT T2."BPLId",:FcCode AS "FcCode",T0."DocType",T2."WorEntry"
			,-1*SUM(ROUND(T2."Amount",2)) AS "Amount"
			,-1*SUM(CASE WHEN T2."CostCode"='20' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "4ExpAmt" --20委外
			,-1*SUM(CASE WHEN T2."CostCode"='30' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "3LabAmount"	--30制造费用
			,-1*SUM(CASE WHEN T2."CostCode"='40' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "2ManExp"	--40人工费用
			FROM MTC_COST_0321_OWOR2 T2
			JOIN MTC_COST_0321_OWOR T0 ON T2."FcCode"=T0."FcCode" AND T0."DocType"=T2."DocType" AND T2."WorEntry"=T0."WorEntry"
			WHERE T2."FcCode"=:FcCode GROUP BY T2."BPLId",T0."DocType",T2."WorEntry"
		) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."DocType"=T3."DocType" AND T0."WorEntry"=T3."WorEntry"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
	WHERE T2."iLevel"=0
	AND T0."FcCode"=:FcCode;
	
	--SELECT "Price",* FROM "MTC_COST_0301_INVNT" WHERE "ItemCode"='102001308-B0.1';
	CALL MTC_COST_PROC_0402_CAL_OWOR(:BPLId,:FcCode,:UserCode,0,'');
	--CALL MTC_COST_PROC_0402_CAL_OWOR_WW(:BPLId,:FcCode,:UserCode,0,'');
	
	--SELECT "Price",* FROM "MTC_COST_0301_INVNT" WHERE "ItemCode"='102001308-B0.1';
	--iLevel = 1的入库明细
	--更新生产订单完工的金额至59、16
	UPDATE T0 SET T0."Amount"=ROUND(T0."Quantity"*T1."Price",2),T0."Price"=T1."Price"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Level0.00写入'
	,T0."IsUpdatePrice"='IN01'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT "FcCode","WorEntry","ItemCode","Price","DocType" FROM "MTC_COST_0321_OWOR_SUM"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
			AND T0."BaseType"=T1."DocType" AND T0."BaseEntry"=T1."WorEntry" AND T0."BaseLine" IS NULL
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T0."CostCode"='20'
	AND T0."TransCode" IN ('I03','I07','I08','I09')
	--AND IFNULL(T0."TransCode",'') NOT IN ('59-305','59-211')	--305生产报废不参与
	AND T0."FcCode"=:FcCode
	AND T2."iLevel"=0
	AND IFNULL(T0."IsUpdatePrice",'')=''
	;
	
	
	
	/*
	--对生产退货60-I03
	UPDATE T0 SET T0."Amount"=T0."Quantity"*T1."Price",T0."Price"=T1."Price"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Level0.21写入'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT "FcCode","ItemCode",SUM("Amount")/NULLIF(SUM("Quantity"),0) AS "Price"
			FROM MTC_COST_0302_INVNTDETAIL1 WHERE "CostCode"='20' AND "ObjType"='59' AND "TransCode"='I03'
			GROUP BY "FcCode","ItemCode") T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T0."CostCode"='20'
	AND T0."ObjType"='60'
	AND T0."TransCode" IN ('I03')
	AND T0."FcCode"=:FcCode
	AND T2."iLevel"=0
	AND IFNULL(T0."IsUpdatePrice",'')=''
	;*/
	
	--iLevel = 1的入库列表（包含59、16）
	INSERT INTO MTC_COST_0303_INVNTLIST(
	"BPLId","FcCode","ItemCode","ItemName"
	,"ObjType","TransCode","SourceMemo"
	,"Qty","Price","Amt")
	SELECT 0,T0."FcCode",T0."ItemCode",T0."ItemName"
	,T0."ObjType",T0."TransCode",'生产入库金额iLevel=0'
	,SUM(T0."Quantity") AS "In_Qty",SUM(T0."Amount")/NULLIF(SUM(T0."Quantity"),0),SUM(T0."Amount") AS "In_Amount"
	FROM "MTC_COST_0302_INVNTDETAIL1" T0
	JOIN U_COILV T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	WHERE 1=1
	AND T0."TransCode" IN ('I03','I07','I08','I09')
	AND T0."FcCode"=:FcCode
	AND T1."iLevel"=0
	GROUP BY T0."FcCode",T0."ItemCode",T0."ItemName",T0."CostCode",T0."ObjType",T0."TransCode";
	
	--更新价格至MTC_COST_0301_INVNT
    UPDATE T0 SET T0."Price"=ROUND((IFNULL(T0."QC_Amount",0)+IFNULL(T1."Amt",0))/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."Qty",0)),0),6)
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Level0.11写入'
	FROM "MTC_COST_0301_INVNT" T0
    LEFT JOIN (SELECT "BPLId","FcCode","ItemCode",SUM("Qty") AS "Qty",SUM("Amt") AS "Amt"
    		FROM "MTC_COST_0303_INVNTLIST"
    		WHERE "TransCode" IN ('I01','I03','I07','I08','I09')
    		GROUP BY "BPLId","FcCode","ItemCode"
    	) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
    WHERE T0."CostCode"='20'
	AND T2."iLevel"=0
	AND T0."FcCode"=:FcCode	--20材料
    ;
    
    --补充
	 UPDATE T0 SET T0."Price"=
	 CASE WHEN IFNULL(T0."QC_Qty",0)+IFNULL(T1."Qty",0)=0
	 THEN ROUND((IFNULL(T0."QC_Amount",0)+IFNULL(T1."IN_Amount",0))/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."IN_QTY",0)),0),6)
	 ELSE ROUND((IFNULL(T0."QC_Amount",0)+IFNULL(T1."Amt",0))/NULLIF((IFNULL(T0."QC_Qty",0)+IFNULL(T1."Qty",0)),0),6) END
    ,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Level0.12写入'
	FROM "MTC_COST_0301_INVNT" T0
    LEFT JOIN (SELECT "BPLId","FcCode","ItemCode",SUM("Quantity") AS "Qty",SUM(ROUND("Amount",2)) AS "Amt"
    		,SUM(CASE WHEN T2."U_IOType"='I' THEN T1."Quantity" ELSE 0 END) AS "IN_QTY"
    		,SUM(CASE WHEN T2."U_IOType"='I' THEN ROUND(T1."Amount",2) ELSE 0 END) AS "IN_Amount"
    		FROM "MTC_COST_0302_INVNTDETAIL1" T1
			LEFT JOIN "@MTC_COST_IOTYPE" T2 ON T1."TransCode"=T2."Code"
    		WHERE 1=1 AND IFNULL("IsUpdatePrice",'')<>''
    		--AND "TransCode" IN ('I01','I03','I07','I08','I09')
    		GROUP BY "BPLId","FcCode","ItemCode"
    	) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
    WHERE T0."CostCode"='20'
	AND T2."iLevel"=0
	AND T0."FcCode"=:FcCode	--20材料
    ;
    --更新写入价格至MTC_COST_0302_INVNTDETAIL1
	UPDATE T0 SET T0."Amount"=ROUND(T0."Quantity"*T1."Price",2),T0."Price"=T1."Price"
   	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.iLevel0写入(O03、O09)'
   	,T0."IsUpdatePrice"='PP01'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN MTC_COST_0301_INVNT T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T1."CostCode"='20'
	AND T0."TransCode" IN ('O03','O09','O07','O08')  --O03 生产发料 O09委外出库  O07生产返工领料  O08委外返工领料  2026.2.8增加O07、O08
	AND T0."FcCode"=:FcCode
	AND T2."iLevel"=0
	AND IFNULL(T0."IsUpdatePrice",'')=''
	;
	/*
    --将价格写入下一环节的生产订单
	UPDATE T1 
	SET  T1."Price"=T4."Price",T1."Amount"=T1."IgeQty"*T4."Price"
   	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.iLevel0.01写入'
	FROM MTC_COST_0321_OWOR1 T1
	JOIN U_COILV T3 ON T1."ItemCode"=T3."ItemCode" AND T1."FcCode"=T3."FcCode"		--子件
	JOIN MTC_COST_0301_INVNT T4 ON T1."ItemCode"=T4."ItemCode" AND T1."FcCode"=T4."FcCode"
	WHERE 1=1 AND T4."CostCode"='20'
	--AND T2."iLevel"=2
	AND T3."iLevel"=0
	AND T1."FcCode"=:FcCode
	AND IFNULL(T1."IsUpdatePrice",'')=''
	;
	*/
	
	 --写入生产订单明细 2026.2.8修改从出入库明细里取
   	UPDATE T1 SET 
   	 T1."Price"=T3."IgeAmt"/NULLIF(T1."IgeQty",0)
   	,T1."Amount"=T3."IgeAmt"
   	,T1."PriceMemo"=IFNULL(T1."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.iLevel0.01写入new Line=308'
   	--,T1."IsUpdatePrice"='1001'
	FROM MTC_COST_0321_OWOR1 T1
	JOIN U_COILV T2 ON T1."ItemCode"=T2."ItemCode" AND T1."FcCode"=T2."FcCode"
	JOIN (SELECT "FcCode","BaseType","BaseEntry","BaseLine","ItemCode",SUM(ROUND("Amount",2)) AS "IgeAmt"
			FROM MTC_COST_0302_INVNTDETAIL1
			WHERE "TransCode" IN ('O03','O07','O08','O09') --O03 生产发料 O09委外出库  O07生产返工领料  O08委外返工领料  2026.2.8增加O07、O08
			GROUP BY "FcCode","BaseType","BaseEntry","BaseLine","ItemCode"
		) T3 ON T1."ItemCode"=T3."ItemCode" AND T1."FcCode"=T3."FcCode" AND T1."DocType"=T3."BaseType"
				AND T1."WorEntry"=T3."BaseEntry" AND T1."LineNum"=T3."BaseLine"
	WHERE 1=1
	AND T1."FcCode"=:FcCode
	AND T2."iLevel"=0
	AND IFNULL(T1."IsUpdatePrice",'')=''
	--WHERE T2."ItmsGrpCod"='103'
	--AND T2."ItemCode"='102000866'	
	;
	
    ----------------------------------------------------iLevel = 1 -------------------------------------------
	--1.计算成本


	  --写入当月成本只当月的MTC_COST_0321_OWOR
	 UPDATE T0 SET T0."Amount"=(IFNULL(T1."Amount",0)+IFNULL(T3."Amount",0))
	,T0."1Material"=T1."Amount"
	,T0."2ManExp"=T3."2ManExp"
	,T0."3LabAmount"=T3."3LabAmount"
	,T0."4WWExp"=T3."4ExpAmt"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Level0—1写入'
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
			SELECT T1."BPLId",:FcCode AS "FcCode",T1."DocType",T1."WorEntry",SUM(T1."IgeQty") AS "IgeQty"
			,-1*SUM(ROUND(T1."Amount",2)) AS "Amount"
			--,SUM(T1."Amount"/NULLIF(T1."IgeQty",0)*T0."IgnQty") AS "Amount"
			FROM MTC_COST_0321_OWOR1 T1
			JOIN MTC_COST_0321_OWOR T0 ON T0."DocType"=T1."DocType" AND T1."WorEntry"=T0."WorEntry" AND T0."FcCode"=T1."FcCode"
			WHERE T1."FcCode"=:FcCode GROUP BY T1."BPLId",T1."DocType",T1."WorEntry"
		) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
	--制造费用+人工费用+委外费用
	LEFT JOIN (
			SELECT T2."BPLId",:FcCode AS "FcCode",T0."DocType",T2."WorEntry"
			,-1*SUM(ROUND(T2."Amount",2)) AS "Amount"
			,-1*SUM(CASE WHEN T2."CostCode"='20' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "4ExpAmt" --20委外
			,-1*SUM(CASE WHEN T2."CostCode"='30' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "3LabAmount"	--30制造费用
			,-1*SUM(CASE WHEN T2."CostCode"='40' THEN ROUND(T2."Amount",2) ELSE 0 END) AS "2ManExp"	--40人工费用
			FROM MTC_COST_0321_OWOR2 T2
			JOIN MTC_COST_0321_OWOR T0 ON T2."FcCode"=T0."FcCode" AND T0."DocType"=T2."DocType" AND T2."WorEntry"=T0."WorEntry"
			WHERE T2."FcCode"=:FcCode GROUP BY T2."BPLId",T0."DocType",T2."WorEntry"
		) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."DocType"=T3."DocType" AND T0."WorEntry"=T3."WorEntry"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
	WHERE T2."iLevel"=0
	AND T0."DocType"='MTC_OWOR'
	AND T0."FcCode"=:FcCode;

	CALL MTC_COST_PROC_0402_CAL_OWOR(:BPLId,:FcCode,:UserCode,0,'');
	
	
    --写入当月成本只当月的MTC_COST_0321_OWOR
	 UPDATE T0 SET T0."Amount"=(IFNULL(T1."Amount",0)+IFNULL(T3."Amount",0))
	,T0."1Material"=T1."Amount"
	,T0."2ManExp"=T3."2ManExp"
	,T0."3LabAmount"=T3."3LabAmount"
	,T0."4WWExp"=T3."4ExpAmt"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->'||'从MTC_COST_PROC_0401_CAL.Level1写入'
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
			SELECT T1."BPLId",:FcCode AS "FcCode",T1."DocType",T1."WorEntry",SUM(T1."IgeQty") AS "IgeQty"
			,-1*SUM(T1."Amount") AS "Amount"
			--,SUM(T1."Amount"/NULLIF(T1."IgeQty",0)*T0."IgnQty") AS "Amount"
			FROM MTC_COST_0321_OWOR1 T1
			JOIN MTC_COST_0321_OWOR T0 ON T0."DocType"=T1."DocType" AND T1."WorEntry"=T0."WorEntry" AND T0."FcCode"=T1."FcCode"
			WHERE T1."FcCode"=:FcCode GROUP BY T1."BPLId",T1."DocType",T1."WorEntry"
		) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
	--制造费用+人工费用+委外费用
	LEFT JOIN (
			SELECT T2."BPLId",:FcCode AS "FcCode",T0."DocType",T2."WorEntry"
			,-1*SUM(T2."Amount") AS "Amount"
			,-1*SUM(CASE WHEN T2."CostCode"='20' THEN T2."Amount" ELSE 0 END) AS "4ExpAmt" --20委外
			,-1*SUM(CASE WHEN T2."CostCode"='30' THEN T2."Amount" ELSE 0 END) AS "3LabAmount"	--30制造费用
			,-1*SUM(CASE WHEN T2."CostCode"='40' THEN T2."Amount" ELSE 0 END) AS "2ManExp"	--40人工费用
			FROM MTC_COST_0321_OWOR2 T2
			JOIN MTC_COST_0321_OWOR T0 ON T2."FcCode"=T0."FcCode" AND T0."DocType"=T2."DocType" AND T2."WorEntry"=T0."WorEntry"
			WHERE T2."FcCode"=:FcCode GROUP BY T2."BPLId",T0."DocType",T2."WorEntry"
		) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."DocType"=T3."DocType" AND T0."WorEntry"=T3."WorEntry"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
	WHERE T2."iLevel"=1
	AND T0."FcCode"=:FcCode;
	
	--2.写入考虑了前期已投入的成品写入MTC_COST_0321_OWOR_SUM
	CALL MTC_COST_PROC_0402_CAL_OWOR(:BPLId,:FcCode,:UserCode,1,'');
	--CALL MTC_COST_PROC_0402_CAL_OWOR_WW(:BPLId,:FcCode,:UserCode,1,'');
	
	--iLevel = 1的生产入库明细
	UPDATE T0 SET T0."Amount"=ROUND(T0."Quantity"*T1."Price",2),T0."Price"=T1."Price"
	,T0."PriceMemo"=IFNULL(T0."PriceMemo",'')||'->从MTC_COST_PROC_0401_CAL.Level1.11写入('||T1."Price"||')'
	,T0."IsUpdatePrice"='IN01'
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	JOIN (SELECT "FcCode","WorEntry","ItemCode","Price","DocType" FROM "MTC_COST_0321_OWOR_SUM"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."ItemCode"=T1."ItemCode"
			AND T0."BaseType"=T1."DocType" AND T0."BaseEntry"=T1."WorEntry" AND T0."BaseLine" IS NULL
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode" 
	WHERE T0."CostCode"='20'
	AND T0."TransCode" IN ('I03','I07','I08','I09')
	AND T0."FcCode"=:FcCode
	AND T2."iLevel"=1
	;	
	
