			JOIN (SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T0."U_OcrCode" FROM ODLN T0
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
