				"U_AcctCode","U_AcctName","StockAcctCode","StockAcctName","U_Debit","U_Credit",
				"CostPrice","CostAmt","VatSum",
				"U_Currency","U_Point","U_FCDebit","U_FCCredit",
				"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
				"WhsCode"
			)
			SELECT :FcCode,T90."TrnsCode",T90."TrnsCodDsc",T90."TrnsCodDsc" AS "U_Type",
			T1."ObjType",T1."DocEntry",T1."DocNum",T1."LineNum",T1."DocDate",
			T1."ObjType" AS "BaseType",T1."DocEntry" AS "BaseEntry",T1."DocNum" AS "BaseNum",T1."LineNum" AS "BaseLine",
			T1."ItemCode",NULL,NULL,NULL,
			T1."Quantity",CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END AS "Price",
			ROUND((ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2) AS "Amount",CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END AS "Price",
			ROUND((ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2) AS "Amount",0 AS "U_GTotalFc",T90."TrnsCodDsc" AS "U_LineMemo",
			T9."AcctCode",T9."AcctName",T10."AcctCode" AS "U_StockCode",T10."AcctName" AS "U_StockName",
			0.00 AS "U_Debit",0.00 AS "U_Credit",
			0,0,0 AS "VatSum",NULL,NULL,NULL,NULL,
			NULL "Project",NULL "OcrCode1",NULL,NULL,NULL,NULL,
			T."WhsCode"			
			FROM (SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_InitPrice",T0."DocDate"
						,T1."OpenQty" AS "Quantity",T1."ItemCode"
						FROM ODLN T0
						JOIN DLN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					   UNION ALL
					   SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_InitPrice",T0."DocDate"
					   ,-1*T1."OpenQty" AS "Quantity",T1."ItemCode"
					   FROM ORDN T0
						JOIN RDN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					) T1
			LEFT JOIN (SELECT * FROM MTC_COST_0302_INVNTDETAIL1 WHERE "CostCode"='20') T ON T1."ObjType"=T."ObjType" AND T1."DocEntry"=T."DocEntry" AND T1."LineNum"=T."LineNum"
			LEFT JOIN OACT T9 ON CASE WHEN T1."U_CustType"='国内客户' THEN '640101' WHEN  T1."U_CustType"='国外客户' THEN '640103' END=T9."AcctCode"
			LEFT JOIN OACT T10 ON T10."AcctCode"='140601'
			JOIN OTRC T90 ON T90."TrnsCode"='AR03'	--主营业务成本结转（内贸）
			WHERE 1=1
			AND T1."U_CustType"='国内客户'
			
			;
			
			
			-----------------------暂估销售成本结转（扣除样品）-------------------
			INSERT INTO MTC_COST_0801_TOOJDT(
			"BPLId",
			"FcCode",
			"TransCode",
			"TransName",
			"RefDate",
			"Memo",
			"Line_ID",
			"AcctCode",
			"AcctName",
			"Debit",
			"Credit",
			"ProfitCode",
			"OcrName1",
			"LineMemo",
			"CreateDate",
			"Creator"
			)
			SELECT 0,:FcCode,'AR04','主营业务成本暂估计提-国际',:edate,'主营业务成本暂估计提-国际',0
			,T9."AcctCode",T9."AcctName",ROUND(SUM(ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2),0.00,NULL,NULL
			,'主营业务成本暂估计提-国际'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM (SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T1."LineNum",T1."U_InitPrice",T0."DocDate"
						,T1."OpenQty" AS "Quantity"
						FROM ODLN T0
						JOIN DLN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					   UNION ALL
					   SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T1."LineNum",T1."U_InitPrice",T0."DocDate"
					   ,-1*T1."OpenQty" AS "Quantity"
					   FROM ORDN T0
						JOIN RDN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					) T1
			LEFT JOIN (SELECT * FROM MTC_COST_0302_INVNTDETAIL1 WHERE "CostCode"='20') T ON T1."ObjType"=T."ObjType" AND T1."DocEntry"=T."DocEntry" AND T1."LineNum"=T."LineNum"
			LEFT JOIN OACT T9 ON CASE WHEN T1."U_CustType"='国内客户' THEN '640101' WHEN  T1."U_CustType"='国外客户' THEN '640103' END=T9."AcctCode"
			WHERE 1=1
			AND T1."U_CustType"='国外客户'
			GROUP BY T9."AcctCode",T9."AcctName"
			
			UNION ALL
			
			SELECT 0,:FcCode,'AR04','主营业务成本暂估计提-国际',:edate,'主营业务成本暂估计提-国际',0
			,T9."AcctCode",T9."AcctName"
			,0.00,ROUND(SUM(ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2),NULL,NULL
			,'主营业务成本暂估计提-国际'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM (SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T1."LineNum",T1."U_InitPrice",T0."DocDate"
						,T1."OpenQty" AS "Quantity"
						FROM ODLN T0
						JOIN DLN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					   UNION ALL
					   SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T1."LineNum",T1."U_InitPrice",T0."DocDate"
					   ,-1*T1."OpenQty" AS "Quantity"
					   FROM ORDN T0
						JOIN RDN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					) T1
			LEFT JOIN (SELECT * FROM MTC_COST_0302_INVNTDETAIL1 WHERE "CostCode"='20') T ON T1."ObjType"=T."ObjType" AND T1."DocEntry"=T."DocEntry" AND T1."LineNum"=T."LineNum"
			LEFT JOIN OACT T9 ON T9."AcctCode"='140601'
			WHERE 1=1
			AND T1."U_CustType"='国外客户'
			GROUP BY T9."AcctCode",T9."AcctName"
			;
			
			INSERT INTO "MTC_COST_0802_OJDTBASEDETAIL"
			("FcCode","TransCode","TransName","U_Type",
				"U_ObjType","U_DocEntry","U_DocNum","U_LineNum","DocDate",
				"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
				"U_ItemCode","U_ItemName","U_CardCode","U_CardName",
				"U_Quantity","U_Price","U_LineTotal",
				"U_PriceAfVAT","U_GTotal","U_GTotalFc","U_LineMemo",
				"U_AcctCode","U_AcctName","StockAcctCode","StockAcctName","U_Debit","U_Credit",
				"CostPrice","CostAmt","VatSum",
				"U_Currency","U_Point","U_FCDebit","U_FCCredit",
				"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
				"WhsCode"
			)
			SELECT :FcCode,T90."TrnsCode",T90."TrnsCodDsc",T90."TrnsCodDsc" AS "U_Type",
			T1."ObjType",T1."DocEntry",T1."DocNum",T1."LineNum",T1."DocDate",
			T1."ObjType" AS "BaseType",T1."DocEntry" AS "BaseEntry",T1."DocNum" AS "BaseNum",T1."LineNum" AS "BaseLine",
			T1."ItemCode",NULL,NULL,NULL,
			T1."Quantity",CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END AS "Price",
			ROUND((ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2) AS "Amount",CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END AS "Price",
			ROUND((ROUND(T1."Quantity"*CASE WHEN T1."DocDate"<='2024-12-31' THEN T1."U_InitPrice" ELSE T."Price" END,2)),2) AS "Amount",0 AS "U_GTotalFc",T90."TrnsCodDsc" AS "U_LineMemo",
			T9."AcctCode",T9."AcctName",T10."AcctCode" AS "U_StockCode",T10."AcctName" AS "U_StockName",
			0.00 AS "U_Debit",0.00 AS "U_Credit",
			0,0,0 AS "VatSum",NULL,NULL,NULL,NULL,
			NULL "Project",NULL "OcrCode1",NULL,NULL,NULL,NULL,
			T."WhsCode"			
			FROM (SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_InitPrice",T0."DocDate"
						,T1."OpenQty" AS "Quantity",T1."ItemCode"
						FROM ODLN T0
						JOIN DLN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					   UNION ALL
					   SELECT T91."U_CustType",T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_InitPrice",T0."DocDate"
					   ,-1*T1."OpenQty" AS "Quantity",T1."ItemCode"
					   FROM ORDN T0
						JOIN RDN1 T1 ON T0."DocEntry"=T1."DocEntry"
						JOIN (SELECT DISTINCT"Name","U_CustType","U_BusiType" FROM "@MTC_SALORDTYPE"
								) T91 ON T0."U_SalOrdType"=T91."Name"
						WHERE IFNULL(T91."U_BusiType",'')<>'样品销售'
						AND T0."DocDate"<=:edate
						AND T0."CANCELED"='N'
						AND T1."LineStatus"='O'
					) T1
			LEFT JOIN (SELECT * FROM MTC_COST_0302_INVNTDETAIL1 WHERE "CostCode"='20') T ON T1."ObjType"=T."ObjType" AND T1."DocEntry"=T."DocEntry" AND T1."LineNum"=T."LineNum"
			LEFT JOIN OACT T9 ON CASE WHEN T1."U_CustType"='国内客户' THEN '640101' WHEN  T1."U_CustType"='国外客户' THEN '640103' END=T9."AcctCode"
			LEFT JOIN OACT T10 ON T10."AcctCode"='140601'
			JOIN OTRC T90 ON T90."TrnsCode"='AR04'	--主营业务成本结转（内贸）
			WHERE 1=1
			AND T1."U_CustType"='国外客户'
			
			;
			-----------------------PP04结转制造费用-------------------
			PP04=
			SELECT T0."AcctCode",SUM(T0."Debit"-T0."Credit") AS "Amount"
			FROM
			 (SELECT "AcctCode","Debit","Credit"
			  FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode" IN ('YF01','IO01','MR02') AND "AcctCode" LIKE '5101%'
			 --扣除制造费用结转的分录
				UNION ALL
			  SELECT T1."Account",T1."Debit",T1."Credit" FROM "OJDT" T0
			  JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			  WHERE 1=1
			  AND IFNULL(T0."TransCode",'')<>'PP04'
			  AND LEFT(T0."RefDate",7)=:FcCode AND T1."Account" LIKE '5101%'
			  
			  --在产品的结转差异
			  	UNION ALL
			  	
				SELECT T2."AcctCode",IFNULL(T1."Debit",0),IFNULL(T1."Credit",0)   ---金额
			    FROM OBTF T0
			    JOIN BTF1 T1 ON T0."TransId" = T1."TransId" AND T0."BatchNum" = T1."BatchNum"
			    JOIN OACT T2 ON T1."Account" = T2."AcctCode"
			    WHERE T0."BtfStatus"='O'
			    AND LEFT(T0."RefDate",7)=:FcCode
				AND LEFT("AcctCode",4) IN ('5101')
				--排除结转制造费用的分录
				AND T0."TransCode" IN ('JZ01','JZ03')
			  ) T0
			 GROUP BY T0."AcctCode"
				;
			
	
			INSERT INTO MTC_COST_0801_TOOJDT(
			"BPLId",
			"FcCode",
			"TransCode",
			"TransName",
			"RefDate",
			"Memo",
			"Line_ID",
			"AcctCode",
			"AcctName",
			"Debit",
			"Credit",
			"ProfitCode",
			"OcrName1",
			"LineMemo",
			"CreateDate",
			"Creator"
			)
			
			SELECT 0,:FcCode,'PP04','制造费用结转',:edate,'制造费用结转',0
			,T1."AcctCode",T1."AcctName",SUM(ROUND(T0."Amount",2)) AS "Debit",0.00 AS "Credit",NULL,NULL
			,'制造费用结转'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM :PP04 T0
			LEFT JOIN OACT T1 ON T1."AcctCode"='500103'
			WHERE 1=1
			GROUP BY T1."AcctCode",T1."AcctName"
			UNION ALL
			SELECT 0,:FcCode,'PP04','制造费用结转',:edate,'制造费用结转',0
			,T1."AcctCode",T1."AcctName",0.00 AS "Debit",ROUND(T0."Amount",2) AS "Credit",NULL,NULL
			,'制造费用结转'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM :PP04 T0
			LEFT JOIN OACT T1 ON T0."AcctCode"=T1."AcctCode"
			WHERE 1=1;
			
	
		/*
			ZZF=
			SELECT T0."BPLId",
			T0."FcCode",
			T0."ObjType",
			T0."DocEntry",
			T0."DocNum",
			T0."LineNum",
			T0."DocDate",
			T0."CostCode",
			T0."TransCode",
			T0."BaseType",
			T0."BaseEntry",
			T0."BaseNum",
			T0."BaseLine",
			T0."ItemCode",
			T0."ItemName",
			T0."ItmsGrpCod",
			T0."Quantity",
			T1."Price",
			T0."Quantity"*T1."Price" AS "Amount",
			T0."CreateDate",
			T0."Creator",
			T0."WhsCode",
			T0."VarVal",
			T0."iLevel",
			T0."OcrCode1",
			T3."StockAct",
			T4."AcctCode",
			T6."U_TransType",		--B01工单产出类  B03工单投入类
			T6."Name" AS "TransName",
			T5."U_OrdType"
			FROM MTC_COST_0302_INVNTDETAIL1 T0
			LEFT JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "FcCode"=:FcCode AND "CostCode"='20') T1 ON T0."ItemCode"=T1."ItemCode"
			LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN (
				SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGN1
					UNION ALL
				SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGE1
				) T4 ON T0."ObjType"=T4."ObjType" AND T0."DocEntry"=T4."DocEntry" AND T0."LineNum"=T4."LineNum"
			LEFT JOIN OWOR T5 ON T0."BaseEntry"=T5."DocEntry"
			LEFT JOIN "@U_CIOTRN" T6 ON REPLACE(REPLACE(T0."TransCode",'59-',''),'60-','')=T6."Code"
			WHERE T0."FcCode" = :FcCode
			AND T0."CostCode"='20'
			AND T0."BaseType"<>'202'
			AND T0."ObjType"  IN ('59','60')
			AND T0."TransCode" NOT IN ('59-203','60-203')
			;
			
			INSERT INTO MTC_COST_0801_TOOJDT(
			"BPLId",
			"FcCode",
			"TransCode",
			"TransName",
			"RefDate",
			"Memo",
			"Line_ID",
			"AcctCode",
			"AcctName",
			"Debit",
			"Credit",
			"ProfitCode",
			"OcrName1",
			"LineMemo",
			"CreateDate",
			"Creator"
			)
			SELECT 0,:FcCode,'PP03','其他领用费用结转',:edate,'其他领用费用结转',0
			,T2."AcctCode",T2."AcctName",-1*ROUND(SUM(T1."Amount"),2),0.00,T1."OcrCode1",T3."PrcName"
			,'其他领用费用结转'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM :ZZF T1
			LEFT JOIN "OACT" T2 ON T1."AcctCode"=T2."AcctCode"
			LEFT JOIN "OPRC" T3 ON T1."OcrCode1"=T3."PrcCode"
			GROUP BY T2."AcctCode",T2."AcctName",T1."OcrCode1",T3."PrcName"
			
			UNION ALL
			SELECT 0,:FcCode,'PP03','其他领用费用结转',:edate,'其他领用费用结转',0
			,T2."AcctCode",T2."AcctName",0.00,-1*ROUND(SUM(T1."Amount"),2),NULL,NULL
			,'其他领用费用结转'
			,CURRENT_TIMESTAMP
			,:UserCode
			FROM :ZZF T1
			LEFT JOIN OACT T2 ON T1."StockAct"=T2."AcctCode"
			GROUP BY T2."AcctCode",T2."AcctName";
			*/
			
			
	
	
	SELECT * FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_CO_001GetItemLevel
CREATE PROCEDURE "MTC_CO_001GetItemLevel" --create by yingxian
(
IN FcCode NVARCHAR(20),
IN UserId INT DEFAULT 1
)
LANGUAGE SQLSCRIPT
AS
BEGIN 

  /*此存储过程用来提取物料的级别，包括半成品，产成品等
	CALL "MTC_CO_001GetItemLevel"('2024-12')
	*/
   DECLARE FLAG INT;
   DECLARE CNT INT;
   DECLARE CNTBOMLEVEL INT;
  
   DECLARE BeginDate DateTime;
   DECLARE EndDate DateTime;
   
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	
    --01.当前期间的日期范围
    SELECT T0."F_RefDate", T0."T_RefDate" INTO BeginDate,EndDate 
    FROM OFPR T0 WHERE T0."Code"= :FcCode;
  	
  	
 	--DROP TABLE #OITMLV;
    CREATE LOCAL TEMPORARY TABLE #OITMLV
	 (
	 "ItemCode" NVARCHAR(40),
	 "ItemName"  NVARCHAR(100),
	 "ItmsGrpCod" NVARCHAR(40),
	 "ItmsGrpNam" NVARCHAR(40),
	 "iLevel" INT
	 ) ;
  
   ----原材料级别
	INSERT INTO #OITMLV SELECT T0."ItemCode",
             T0."ItemName",
             T1."ItmsGrpCod",
             T1."ItmsGrpNam",
             -1 AS "iLevel"
      FROM OITM T0
      INNER JOIN OITB T1 ON T0."ItmsGrpCod" = T1."ItmsGrpCod";
     --WHERE T0."ItmsGrpCod"  IN (108);---(30,40,50) 



	--获取BOM情况
   Temp01=
        SELECT T0."Code" "Father", T1."Code" "Child",T2."ItmsGrpCod" 
        FROM OITT T0  INNER JOIN ITT1 T1 ON T0."Code" = T1."Father" 
        INNER JOIN OITM T2 ON T0."Code" = T2."ItemCode";
    
   CNT:=0;
   SELECT IFNULL((SELECT COUNT(1)
        FROM :Temp01 T0
       WHERE T0."Father"  = T0."Child"),0) INTO CNT FROM DUMMY;
    
 	--判断并修改0级原料
 	UPDATE #OITMLV SET "iLevel"=0 WHERE "ItemCode" NOT IN (SELECT "Father" FROM  :temp01) ;


    --F.3、判断#BOM的Father是否存在下一级别的配方,若存在，则循环#BOM通过当前ILevel+1确定Father的最终级别
    
    --判断是否存在下一级别
    
 	CNTBOMLEVEL:=1;
 --如果存在，则级别加1
    WHILE :CNTBOMLEVEL <9 DO
    		--更新物料等级
    		UPDATE #OITMLV SET "iLevel"=:CNTBOMLEVEL WHERE "ItemCode" IN (
	    		SELECT "Father" FROM (
				SELECT T0."Father",IFNULL(T1."iLevel",-1) "ILV" FROM :Temp01 T0 
	  			LEFT JOIN #OITMLV T1 ON T0."Child"=T1."ItemCode"
	    			LEFT  JOIN #OITMLV T2 ON T0."Father"=T2."ItemCode"
	    			WHERE IFNULL(T2."iLevel",-1) =-1 AND IFNULL(T1."iLevel",-1)<:CNTBOMLEVEL
	    			GROUP BY T0."Father",T1."iLevel"
	    			) A GROUP BY "Father"
	    			HAVING SUM(CASE WHEN "ILV"=-1 THEN 1 ELSE 0 END)=0
	    	);
	    	--等级+1
    		CNTBOMLEVEL:=(:CNTBOMLEVEL+1); 
    END WHILE;
  


   CNT:=0;
   SELECT IFNULL((SELECT COUNT(1)
        FROM #OITMLV T0
       WHERE T0."iLevel"  = -1),0) INTO CNT FROM DUMMY;
    

 	--最终的结果插入表中。
    DELETE FROM U_COILV WHERE  "FcCode"=:FcCode;

    --将原材料插入到系统中
    INSERT INTO U_COILV("FcCode","ItemCode","ItemName",
                        "ItmsGrpCod","ItmsGrpNam",
                        "iLevel","CalType","CreatedDate","CreatedTime")
    SELECT :FcCode, 
            T0."ItemCode",T0."ItemName",
            T0."ItmsGrpCod",T0."ItmsGrpNam",
            T0."iLevel",T1."U_ItemProp",CURRENT_Date,CURRENT_Time
    FROM #OITMLV T0
    JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode";
      
      
	DROP TABLE #OITMLV;
	
	UPDATE U_COILV SET "iLevel"=2 WHERE  "FcCode"=:FcCode AND "ItemCode" IN ('102000058','102000762'); 
	UPDATE U_COILV SET "iLevel"=3 WHERE  "FcCode"=:FcCode AND "ItemCode" IN ('FH1401101','FH1403501'); 
	
	--chris.li 2026.3.6增加
	--UPDATE U_COILV SET "iLevel"=3 WHERE  "FcCode"=:FcCode AND "ItemCode" IN ('102000319');
      
    SELECT T0."FcCode",T0."ItemCode" AS "物料号",  
           T0."ItemName" AS "物料名称",
           T0."ItmsGrpCod" AS "物料组编码",
           T0."ItmsGrpNam" AS "物料组名称",
            T0."iLevel" AS "级别",T0."CalType"
    FROM U_COILV T0
    WHERE T0."FcCode"=:FcCode 
    ORDER BY T0."iLevel" DESC,T0."ItemCode";
  
      
END;

@@
-- @stmt 旧模块 PROCEDURE MTC_PRT_CO4001
CREATE PROCEDURE "MTC_PRT_CO4001" (
   IN sFcCode NVARCHAR(50)
   ,IN eFcCode NVARCHAR(50)
   ,IN ItemCode NVARCHAR(100)
   ,IN WorType NVARCHAR(30)
   ,IN WorNum NVARCHAR(30)
   ,IN IsOnlyAmt NVARCHAR(10) DEFAULT 'N'		--仅显示有余额
   ,IN IsInsert NVARCHAR(10) DEFAULT 'N'	--是否写入静态表
   )
LANGUAGE SQLSCRIPT
AS
BEGIN
	--CALL "MTC_PRT_CO4001"('','2026-01','','Y');
		IF :IsInsert = 'N' THEN
			
			SELECT T0."期间",
			T0."DocType",
			T0."WorType",
			T0."工单类型",
			T0."订单日期",
			T0."订单关单日期",
			T0."订单状态",
			T0."订单号",
			T0."WorEntry",
			T0."WorNum",
			T0."CardCode",
			T0."CardName",
			T0."物料编码" ,
			T0."物料名称",
			T0."物料组",
			T0."订单数量",
			T0."当期入库数量",
			T0."完工入库单价",
			T0."当期入库成本金额",
			T0."当期成本合计",
			T0."当期材料金额",
			T0."当期人工费用",
			T0."当期制造费用",
			T0."当期委外费用",
			T0."累计入库数量",
			T0."累计成本合计",
			T0."累计材料",
			T0."累计人工费用",
			T0."累计制造费用",
			T0."累计委外费用",
			T0."累计完工材料合计",
			T0."累计材料总",
			T0."关单差异",
			--CASE WHEN T0."WorNum"='22' THEN 531099.66 ELSE T0."在产品新" END AS "在产品新",
			--累计领料IFNULL(T4."1Material",0)-已经进入完工材料IFNULL(T1."1Material",0)-关单差异IFNULL(T0."CloseDifAmt",0)
			T0."在产品新" AS "在产品金额",
			T0."在产品金额" AS "在产品金额（参考）",
			T0."库存科目",
			T0."物料等级",
			T0."老系统订单号",
			T0."创建时间",
			T0."创建人",T9."CloseDate" AS "实际关闭日期"
			FROM "MTC_COST_0322_OWOR_ZCP" T0
			LEFT JOIN
					(SELECT '202' AS "DocType","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName","CloseDate" FROM OWOR
						UNION ALL
					SELECT "Object","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName","U_CloseDate" FROM "@MTC_OWOR"
					) T9 ON T0."WorEntry"=T9."DocEntry" AND T0."DocType"=T9."DocType"
			WHERE T0."期间">=:sFcCode AND T0."期间"<=:eFcCode
			AND (T0."物料编码"=:ItemCode OR :ItemCode='')
			AND (T0."WorNum"=:WorNum OR :WorNum='')
			AND ((:WorType = '生产工单' AND T0."WorType" IN ('20','30','10'))
					OR (:WorType = '委外工单' AND T0."WorType"='50')
					OR :WorType = ''
				)
			AND IFNULL(T0."WorType",'')<>'40'
			AND ((:IsOnlyAmt = 'Y' AND (IFNULL(T0."在产品新",0)<>0 OR IFNULL("当期入库数量",0)<>0) OR LEFT(T0."订单关单日期",7) BETWEEN :sFcCode AND :eFcCode)
				  OR :IsOnlyAmt='N'
				)
			;
	    
		ELSEIF :IsInsert = 'Y' THEN 	
			
	  		IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:eFcCode) THEN
	  			SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
		  		RETURN;
		  	END IF;
		    DELETE FROM MTC_COST_0322_OWOR_ZCP WHERE "期间"=:eFcCode;
		    
		    INSERT INTO "MTC_COST_0322_OWOR_ZCP"( 
			"期间", "DocType","WorType", "工单类型", "订单日期",
			"订单关单日期", "订单状态", "订单号", "WorEntry", "WorNum",
			"CardCode", "CardName", "物料编码", "物料名称", "物料组",
			"订单数量", "当期入库数量", "完工入库单价", "当期入库成本金额", "当期成本合计",
			"当期材料金额", "当期人工费用", "当期制造费用", "当期委外费用",
			"累计入库数量", "累计成本合计", "累计材料", "累计人工费用", "累计制造费用",
			"累计委外费用", "累计完工材料合计", "关单差异", "在产品金额","累计材料总","在产品新",
			"库存科目", "物料等级", "老系统订单号", "创建时间", "创建人")
			SELECT  
			T0."FcCode" AS "期间",
			T0."DocType",
			T0."WorType",
			(CASE T0."WorType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' 
			WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END) AS "工单类型",
			T0."DocDate" AS "订单日期",
			CASE WHEN T0."WorType"='50' 
				 AND T0."Status"='L' 
				 AND TO_CHAR(T0."CloseDate",'YYYY-MM')>='2026-07' 
				 AND TO_CHAR(T0."CloseDate",'YYYY-MM')<=:eFcCode
				 THEN T0."CloseDate"
			WHEN T0."Status"='L' AND TO_CHAR(T0."CloseDate",'YYYY-MM')<=:eFcCode
				THEN T0."CloseDate"
				ELSE '' END AS "订单关单日期",
			CASE WHEN T0."Status"='R' THEN '已下达'
			WHEN T0."WorType"='50' AND TO_CHAR(T0."CloseDate",'YYYY-MM')<'2026-07' AND TO_CHAR(T0."CloseDate",'YYYY-MM')>:eFcCode THEN '已下达'
			WHEN T0."WorType"='50' AND TO_CHAR(T0."CloseDate",'YYYY-MM')>='2026-07' AND TO_CHAR(T0."CloseDate",'YYYY-MM')<=:eFcCode THEN '已结算'
			WHEN T0."Status"='L' AND TO_CHAR(T0."CloseDate",'YYYY-MM')>:eFcCode THEN '已下达'
			WHEN T0."Status"='L' AND TO_CHAR(T0."CloseDate",'YYYY-MM')<=:eFcCode THEN '已结算'
			WHEN T0."Status"='P' THEN '已计划' END  AS "订单状态",
			T9."U_SupNum" AS "订单号",
			T0."WorEntry" AS "生产订单号Entry",
			T0."WorNum",
			T9."U_CardCode",
			T10."CardName",
			T0."ItemCode" AS "物料编码" ,
			T0."ItemName" AS "物料名称",
			T0."ItmsGrpCod" AS "物料组",
			T0."WorQty" AS "订单数量",
			T0."IgnQty" AS "当期入库数量",
			TO_CHAR(CAST(T0."Price" AS DECIMAL(19,6))) AS "完工入库单价",
			T0."Amount" AS "当期入库成本金额",
			--T0."IgnQty"*T0."Price" AS "当期入库成本金额",
			T0."Amount" AS "当期成本合计",
			T0."1Material" AS "当期材料金额",
			T0."2ManExp" AS "当期人工费用",
			T0."3LabAmount" AS "当期制造费用",
			T0."4WWExp" AS "当期委外费用",
			T0."Ign_SUM" AS "累计入库数量",
			T0."Amount_SUM" AS "累计成本合计",
			T0."1Material_SUM" AS "累计材料",
			T0."2ManExp_SUM" AS "累计人工费用",
			T0."3LabAmount_SUM" AS "累计制造费用",
			T0."4WWExp_SUM" AS "累计委外费用",
			IFNULL(T1."1Material",0) AS "累计完工材料合计",
			IFNULL(T0."CloseDifAmt",0) AS "关单差异",
			IFNULL(T0."1Material_SUM",0)-IFNULL(T1."1Material",0)-IFNULL(T0."CloseDifAmt",0) AS "在产品金额",
			IFNULL(T4."1Material",0) AS "累计材料总",
			--累计领料减去已结转的完工材料-关单差异
			IFNULL(T4."1Material",0)-IFNULL(T1."1Material",0)-IFNULL(T0."CloseDifAmt",0) AS "在产品新",
			T3."StockAct" AS "库存科目",
			T0."iLevel" AS "物料等级",
			T9."U_OldSysNo" AS "老系统订单号",
			CURRENT_TIMESTAMP AS "创建时间",
			T0."Creator" AS "创建人"
			FROM MTC_COST_0321_OWOR_SUM T0
			LEFT JOIN (SELECT "WorEntry","DocType",SUM("1Material") AS "1Material" FROM MTC_COST_0321_OWOR_SUM WHERE "FcCode"<=:eFcCode 
						GROUP BY "WorEntry","DocType"
			            ) T1 ON T0."WorEntry"=T1."WorEntry" AND T0."DocType"=T1."DocType"
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROM OGAR WHERE "PeriodCat"=LEFT(:eFcCode,4) GROUP BY "ItmsGrpCod"
							) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN (SELECT "WorEntry","DocType",SUM(-1*"Amount") AS "1Material"
						FROM MTC_COST_0321_OWOR1 WHERE "FcCode"<=:eFcCode 
						GROUP BY "WorEntry","DocType"
			            ) T4 ON T0."WorEntry"=T4."WorEntry" AND T0."DocType"=T4."DocType"
			LEFT JOIN
					(SELECT '202' AS "DocType","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM OWOR
						UNION ALL
					SELECT "Object","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM "@MTC_OWOR"
					) T9 ON T0."WorEntry"=T9."DocEntry" AND T0."DocType"=T9."DocType"
			LEFT JOIN OCRD T10 ON T10."CardCode"=T9."U_CardCode"
			WHERE 1=1
			AND T0."FcCode" >= :eFcCode
			AND T0."FcCode" <= :eFcCode
			AND (T2."ItemCode"=:ItemCode OR :ItemCode='')
			ORDER BY T0."DocDate",CAST(T0."WorNum" AS INT);
			
			
			
			UPDATE "MTC_COST_0322_OWOR_ZCP" 
			SET "关单差异"="在产品新","在产品新"=0,"关单结算期间"=:eFcCode
			WHERE "WorType" IN ('10','20','30') AND "订单状态"='已结算' AND "期间"=:eFcCode
			AND IFNULL("在产品新",0)<>0
			AND TO_CHAR("订单关单日期",'YYYY-MM')=:eFcCode
			;
			
			
			UPDATE "MTC_COST_0322_OWOR_ZCP" 
			SET "关单差异"="在产品新","在产品新"=0,"关单结算期间"=:eFcCode
			WHERE "WorType" IN ('50') AND "订单状态"='已结算' AND "期间"=:eFcCode
			AND IFNULL("在产品新",0)<>0
			AND TO_CHAR("订单关单日期",'YYYY-MM')=:eFcCode
			AND TO_CHAR("订单关单日期",'YYYY-MM')>='2026-08'
			;
			
			UPDATE T0
			SET "5ClosedAmt"=IFNULL(T1."关单差异",0)
			FROM "MTC_COST_0321_OWOR" T0
			JOIN "MTC_COST_0322_OWOR_ZCP" T1 ON T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry" AND T0."FcCode"=T1."期间"
			WHERE 1=1
			AND T1."期间"=:eFcCode
			AND IFNULL(T1."关单差异",0)<>0
			AND T1."关单结算期间"=:eFcCode
			AND T1."订单状态"='已结算'
			;
			
			--UPDATE "MTC_COST_0322_OWOR_ZCP" SET "关单差异"="在产品新","在产品新"=0
			--WHERE "WorType" IN ('10','20','30') AND "订单状态"='已结算' AND "期间"='2026-04';
			/*
			UPDATE "MTC_COST_0322_OWOR_ZCP" SET "关单差异"="在产品新","在产品新"=0
			WHERE "WorType" IN ('10','20','30') AND "订单状态"='已结算' AND "期间" iN ('2026-06')
			AND :eFcCode='2026-06'
			;*/
		
			
			/*
		SELECT  
T0."FcCode" AS "期间",
T0."DocType",
(CASE T0."WorType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END) AS "工单类型",
T0."DocDate" AS "订单日期",
T0."CloseDate" AS "订单关单日期",
CASE WHEN T0."Status"='R' THEN '已下达' WHEN T0."Status"='L' THEN '已结算' WHEN T0."Status"='P' THEN '已计划' END  AS "订单状态",
T9."U_SupNum" AS "订单号",
T0."WorEntry" AS "生产订单号Entry",
T0."WorNum",
T9."U_CardCode",
T10."CardName",
T0."ItemCode" AS "物料编码" ,
T0."ItemName" AS "物料名称",
T0."ItmsGrpCod" AS "物料组",
T0."WorQty" AS "订单数量",
T0."IgnQty" AS "当期入库数量",
TO_CHAR(CAST(T0."Price" AS DECIMAL(19,6))) AS "完工入库单价",
T0."IgnQty"*T0."Price" AS "当期入库成本金额",
T0."Amount" AS "当期成本合计",
T0."1Material" AS "当期材料金额",
T0."2ManExp" AS "当期人工费用",
T0."3LabAmount" AS "当期制造费用",
T0."4WWExp" AS "当期委外费用",
T0."Ign_SUM" AS "累计入库数量",
T0."Amount_SUM" AS "累计成本合计",
T0."1Material_SUM" AS "累计材料",
T0."2ManExp_SUM" AS "累计人工费用",
T0."3LabAmount_SUM" AS "累计制造费用",
T0."4WWExp_SUM" AS "累计委外费用",
IFNULL(T1."1Material",0) AS "累计完工材料合计",
IFNULL(T0."CloseDifAmt",0) AS "关单差异",
IFNULL(T0."1Material_SUM",0)-IFNULL(T1."1Material",0)+IFNULL(T0."CloseDifAmt",0) AS "在产品金额",
T3."StockAct" AS "库存科目",
T0."iLevel" AS "物料等级",
T9."U_OldSysNo" AS "老系统订单号",
T0."CreateDate" AS "创建时间",
T0."Creator" AS "创建人"
FROM MTC_COST_0321_OWOR_SUM T0
LEFT JOIN (SELECT "WorEntry","DocType",SUM("1Material") AS "1Material" FROM MTC_COST_0321_OWOR_SUM WHERE "FcCode"<='[%0]' 
			GROUP BY "WorEntry","DocType"
            ) T1 ON T0."WorEntry"=T1."WorEntry" AND T0."DocType"=T1."DocType"
JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROM OGAR WHERE "PeriodCat"=LEFT('[%0]',4) GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
LEFT JOIN
		(SELECT '202' AS "DocType","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM OWOR
			UNION ALL
		SELECT "Object","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM "@MTC_OWOR"
		) T9 ON T0."WorEntry"=T9."DocEntry" AND T0."DocType"=T9."DocType"
LEFT JOIN OCRD T10 ON T10."CardCode"=T9."U_CardCode"
WHERE T0."FcCode" >= '[%0]'
AND T0."FcCode" <= '[%1]'
AND (T2."ItemCode"='[%2]' OR '[%2]'='')
ORDER BY T0."DocDate",CAST(T0."WorNum" AS INT)*/
		
		END IF;
END;

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO4011
CREATE PROCEDURE "MTC_RPT_CO4011"
(
  IN STYPE INT,	--0汇总  1明细
  IN FcCode NVARCHAR(30),
  IN WorType NVARCHAR(50),	--生产工单，委外工单
  IN ItemCode NVARCHAR(50),
  IN WorNum NVARCHAR(50),
  IN IsInsert NVARCHAR(10) DEFAULT 'N',
  IN JZCY NVARCHAR(10) DEFAULT 'N'		--是否结转差异
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	--在产品明细表（查看和写入）
	--CALL "MTC_RPT_CO4011"(0,'2026-04','生产工单','','','Y')
	
	IF :WorType = '生产工单' THEN 
		
		SELECT T0."DocType",T0."WorType"
		,T0."工单类型"
		,T0."订单状态"
		,T0."订单日期"
		,T0."订单关单日期"
		,T0."订单号"
		,T0."WorEntry",T0."WorNum"
		,T1."ItemCode" AS "材料编码",T1."ItemName" AS "材料名称",T1."Quantity" AS "材料数量"
		,T1."Amount" AS "材料金额",T1."Amount_SUM" AS "材料汇总"
		,T0."在产品新" AS "汇总表的在产品金额"
		,IFNULL(T1."Amount_SUM",0)-IFNULL(T0."在产品新",0) AS "差异"
		,T1."ActIgeQty" AS "实际领料数量"
		,T1."ActIgeAmt" AS "实际领料金额"
		,T1."AvgIgePrice" AS "领料平均单价"
		,T1."IgnQtyPrc" AS "入库倒冲数量"
		,T1."IgnAmtPrc" AS "入库倒冲金额"
		,T1."CalType" AS "计算方式"
		,T1."PriceMemo" AS "计算备注"
		FROM MTC_COST_0322_OWOR_ZCP T0
		LEFT JOIN (SELECT "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName","Quantity","Amount"
					,SUM("Amount") OVER (PARTITION BY "FcCode","DocType","WorEntry") AS "Amount_SUM"
					,"ActIgeQty","ActIgeAmt","CalType","PriceMemo"
					,"IgnQtyPrc","IgnAmtPrc","AvgIgePrice"
					FROM MTC_COST_0322_OWOR_ZCP1
				) T1 ON T0."期间"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
		WHERE T0."期间"=:FcCode
		AND T0."WorType" IN ('10','20','30')
		AND (T0."WorNum"=:WorNum OR WorNum='')
		AND (IFNULL(T1."Amount_SUM",0)<>0 OR IFNULL(T0."在产品新",0)<>0)
		ORDER BY T0."WorEntry"
		;

		IF :IsInsert = 'Y' THEN
			
			TMP_OWOR=
			SELECT T1."U_OrdType" AS "WorType",
			CASE T1."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' 
			WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END AS "工单类型"
			,T."订单状态"
			,T0."DocType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum",T5."ItemCode",T5."ItemName"
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 0
					ELSE T4."IgeQty"-T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" END AS "CL_ZCP_QTY"
			----计算的在产品（实际领料-）
			--1.当实际入库数量大于等于计划入库数量，在产品为0
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 0
					ELSE T4."IgeAmt"-T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty"*IFNULL(T4."IgePrice",0) END AS "CL_ZCP_AMT"
			
			,T4."IgeQty" AS "ActIgeQty"		--实际领料数量
			,T4."IgeAmt" AS "ActIgeAmt"		--实际领料金额

			,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" AS "IgnQtyPrc" --入库倒冲数量
			,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty"*IFNULL(T4."IgePrice",0) AS "IgnAmtPrc" --入库倒冲金额
			,IFNULL(T4."IgePrice",0) AS "AvgIgePrice"	--平均领料单价
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 'ZERO'
				ELSE 'ZCP' END 
				AS "CalType"	--计算类型 ZERO-0在产品 ZCP-按领料比例倒挤计算
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 
				THEN 'ZERO:实际已入库数量'||IFNULL(T0."IgnQty",0)||'减去计划入库数量'||IFNULL(T1."PlannedQty",0)||'>=0'
				ELSE 'ZCP:实际领料金额'||IFNULL(T4."IgeAmt",0)
					||'减去(实际已入库数量'||IFNULL(T0."IgnQty",0)||'*'
					||'子件计划数量'||T2."PlannedQty"||'/'
					||'订单主件计划数量'||T1."PlannedQty"||'*'
					||'材料平均单价'||IFNULL(T4."IgePrice",0)||')'
				END
				AS "PriceMemo"
			FROM MTC_COST_0322_OWOR_ZCP T
			JOIN (SELECT "DocType","WorEntry","ItemCode"
						,SUM("IgnQty") AS "IgnQty"
						FROM "MTC_COST_0321_OWOR" WHERE "FcCode"<=:FcCode
						--AND "WorNum"=4220
							GROUP BY "DocType","WorEntry","ItemCode"
					) T0 ON T."DocType"=T0."DocType" AND T."WorEntry"=T0."WorEntry"
			--订单主件计划数量
			LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","DocNum","PostDate","PlannedQty","U_CardCode","U_OrdType" FROM OWOR
						UNION ALL
					   SELECT "Object" AS "ObjType","DocEntry","DocNum","U_PostDate","U_PlannedQty","U_CardCode","U_OrdType" FROM "@MTC_OWOR"
					) T1 ON T0."WorEntry"=T1."DocEntry" AND T0."DocType"=T1."ObjType"
			--订单子件计划数量
			LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","ItemCode",SUM("PlannedQty") AS "PlannedQty" FROM WOR1 GROUP BY "DocEntry","ItemCode"
						UNION ALL
					   SELECT "Object" AS "ObjType","DocEntry","U_ItemCode",SUM("U_PlannedQty") AS "PlannedQty"
					   			FROM "@MTC_WOR1" GROUP BY "Object","DocEntry","U_ItemCode"
					) T2 ON T1."DocEntry"=T2."DocEntry" AND T0."DocType"=T2."ObjType"
			LEFT JOIN OCRD T3 ON T1."U_CardCode"=T3."CardCode"
			JOIN (SELECT "DocType","WorEntry","ItemCode"
						,SUM(-1*"IgeQty") AS "IgeQty" 
						,SUM(-1*"Amount") AS "IgeAmt"
						,SUM(-1*"Amount")/NULLIF(SUM(-1*"IgeQty"),0) AS "IgePrice"
						FROM "MTC_COST_0321_OWOR1" WHERE "FcCode"<=:FcCode
							GROUP BY "DocType","WorEntry","ItemCode" HAVING SUM(-1*"IgeQty")<>0
						) T4 ON T4."DocType"=T0."DocType" AND T4."WorEntry"=T1."DocEntry" AND T2."ItemCode"=T4."ItemCode" 
			LEFT JOIN OITM T5 ON T4."ItemCode"=T5."ItemCode"
			WHERE 1=1
			AND T."WorType" IN ('10','20','30')
			AND T."在产品新"<>0
			--AND T."订单状态"<>'已结算'
			AND T."期间"=:FcCode
			AND (T."WorNum"=:WorNum OR :WorNum='')
			--AND T1."U_OrdType"='50'
			;
			
			DELETE FROM "MTC_COST_0322_OWOR_ZCP1" WHERE "FcCode"=:FcCode AND "WorType" IN ('10','20','30'); 
			INSERT INTO "MTC_COST_0322_OWOR_ZCP1"(
			"FcCode","DocType","WorType","WorEntry","WorNum","iLevel",
		    "ItemCode","ItemName","ItmsGrpCod",
		    "Quantity","Amount","ActIgeQty","ActIgeAmt","IgnQtyPrc","IgnAmtPrc","AvgIgePrice",
		    "CalType","PriceMemo",
		    "CreateDate","Creator"
		    )
		    SELECT :FcCode,T0."DocType",T0."WorType",T0."WorEntry",T0."WorNum",NULL
		    ,T0."ItemCode",T0."ItemName",NULL
		    ,T0."CL_ZCP_QTY",T0."CL_ZCP_AMT",T0."ActIgeQty",T0."ActIgeAmt",T0."IgnQtyPrc",T0."IgnAmtPrc",T0."AvgIgePrice"
		    ,T0."CalType",T0."PriceMemo"
		    ,CURRENT_TIMESTAMP,:FcCode
		    FROM :TMP_OWOR T0
		    ORDER BY T0."WorEntry",T0."DocType"
		    ;
		    
		    /*
		    INSERT INTO "MTC_COST_0322_OWOR_ZCP1"(
			"FcCode","DocType","WorType","WorEntry","WorNum","iLevel",
		    "ItemCode","ItemName","ItmsGrpCod",
		    "Quantity","Amount","ActIgeQty","ActIgeAmt","IgnQtyPrc","IgnAmtPrc","AvgIgePrice",
		    "CalType","PriceMemo",
		    "CreateDate","Creator"
		    )
		    SELECT :FcCode,'202' AS "DocType",'10' AS "WorType",T0."DocEntry" AS "WorEntry",T0."DocNum" AS "WorNum",NULL
		    ,T1."ItemCode",T2."ItemName",NULL
		    ,T1."PlannedQty",478675.03 AS "CL_ZCP_AMT"
		    ,T1."PlannedQty" AS "ActIgeQty",478675.03 AS "ActIgeAmt",NULL AS "IgnQtyPrc",NULL AS "IgnAmtPrc",NULL AS "AvgIgePrice"
		    ,'ZCP' AS "CalType",NULL AS "PriceMemo"
		    ,CURRENT_TIMESTAMP,:FcCode
		    FROM "OWOR" T0 JOIN "WOR1" T1 ON T0."DocEntry"=T1."DocEntry"
		    JOIN OITM T2 ON T1."ItemCode"=T2."ItemCode"
		    WHERE T0."DocEntry"=308
		    ;*/
		    
		    
			--UPDATE "MTC_COST_0322_OWOR_ZCP1" SET "Amount"="Amount"+53893.65  
			--WHERE "FcCode"='2026-04' AND "WorEntry"='111' AND "DocType"='MTC_OWOR' AND "ItemCode"='102000086'
			--AND :FcCode='2026-04'
			--;

			TMP_DIFF=
		    SELECT T0."DocType"
			,T0."WorEntry",T0."WorNum"
			,T1."Amount_SUM" 	-- "在产品材料汇总"
			,T0."在产品新" -- "汇总表的在产品金额"
			,IFNULL(T1."Amount_SUM",0)-IFNULL(T0."在产品新",0) AS "DiffAmt"
			FROM MTC_COST_0322_OWOR_ZCP T0
			LEFT JOIN (SELECT "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName","Quantity","Amount"
						,SUM("Amount") OVER (PARTITION BY "FcCode","DocType","WorEntry") AS "Amount_SUM"
						,"ActIgeQty","ActIgeAmt","CalType","PriceMemo"
						,"IgnQtyPrc","IgnAmtPrc","AvgIgePrice"
						FROM MTC_COST_0322_OWOR_ZCP1
					) T1 ON T0."期间"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
			WHERE T0."期间"=:FcCode
			AND T0."WorType" IN ('10','20','30')
			AND (T0."WorNum"=:WorNum OR WorNum='')
			AND IFNULL(T1."Amount_SUM",0)-IFNULL(T0."在产品新",0)<>0
			GROUP BY T0."DocType"
			,T0."WorEntry",T0."WorNum"
			,T1."Amount_SUM" 	-- "在产品材料汇总"
			,T0."在产品新";
			
			
			IF :JZCY = 'Y' THEN
				UPDATE T2 SET T2."Amount"=T2."Amount"-T0."DiffAmt"
				FROM :TMP_DIFF T0
				JOIN (SELECT "DocType","WorEntry","WorNum","ItemCode","Amount"
						,ROW_NUMBER() OVER(PARTITION BY "FcCode","DocType","WorEntry" ORDER BY "Amount" DESC) AS "ID"
						FROM MTC_COST_0322_OWOR_ZCP1 WHERE "FcCode"=:FcCode
					) T1 ON T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry" AND T1."ID"=1
				JOIN MTC_COST_0322_OWOR_ZCP1 T2 ON T0."DocType"=T2."DocType" AND T0."WorEntry"=T2."WorEntry" 
													AND T1."ItemCode"=T2."ItemCode" AND T2."FcCode"=:FcCode
				WHERE T2."WorType" IN ('10','20','30')
				;
			END IF;
			
		END IF;
	
	ELSEIF :WorType='委外工单' THEN
	
			
		SELECT T0."DocType",T0."WorType"
		,T0."工单类型"
		,T0."订单状态"
		,T0."订单日期"
		,T0."订单关单日期"
		,T0."订单号"
		,T0."WorEntry",T0."WorNum"
		,T1."ItemCode" AS "材料编码",T1."ItemName" AS "材料名称",T1."Quantity" AS "材料数量"
		,T1."Amount" AS "材料金额",T1."Amount_SUM" AS "材料汇总"
		,T0."在产品新" AS "汇总表的在产品金额"
		,IFNULL(T1."Amount_SUM",0)-IFNULL(T0."在产品新",0) AS "差异"
		,T1."ActIgeQty" AS "实际领料数量"
		,T1."ActIgeAmt" AS "实际领料金额"
		,T1."AvgIgePrice" AS "领料平均单价"
		,T1."IgnQtyPrc" AS "入库倒冲数量"
		,T1."IgnAmtPrc" AS "入库倒冲金额"
		,T2."CardCode",T2."CardName"
		,T1."CalType" AS "计算方式"
		,T1."PriceMemo" AS "计算备注"
		FROM MTC_COST_0322_OWOR_ZCP T0
		LEFT JOIN (SELECT "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName","Quantity","Amount"
					,SUM("Amount") OVER (PARTITION BY "FcCode","DocType","WorEntry") AS "Amount_SUM"
					,"ActIgeQty","ActIgeAmt","CalType","PriceMemo"
					,"IgnQtyPrc","IgnAmtPrc","AvgIgePrice"
					FROM MTC_COST_0322_OWOR_ZCP1
				) T1 ON T0."期间"=T1."FcCode" AND T0."DocType"=T1."DocType" AND T0."WorEntry"=T1."WorEntry"
		LEFT JOIN OCRD T2 ON T0."CardCode"=T2."CardCode"
		WHERE T0."期间"=:FcCode
		AND T0."WorType" IN ('50')
		AND (T0."WorNum"=:WorNum OR WorNum='')
		AND (IFNULL(T1."Amount_SUM",0)<>0 OR IFNULL(T0."在产品新",0)<>0)
		ORDER BY T0."WorEntry"
		;

		IF :IsInsert = 'Y' THEN
			
			TMP_OWOR_50=
			SELECT T1."U_OrdType" AS "WorType",
			CASE T1."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' 
			WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END AS "工单类型"
			,T3."CardCode",T3."CardName"
			,T."订单状态"
			,T0."DocType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum",T5."ItemCode",T5."ItemName"
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 0
					ELSE T4."IgeQty"-T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" END AS "CL_ZCP_QTY"
			----计算的在产品（实际领料-）
			--1.当实际入库数量大于等于计划入库数量，在产品为0
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 0
					ELSE T4."IgeAmt"-T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty"*IFNULL(T4."IgePrice",0) END AS "CL_ZCP_AMT"
			
			,T4."IgeQty" AS "ActIgeQty"		--实际领料数量
			,T4."IgeAmt" AS "ActIgeAmt"		--实际领料金额

			,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" AS "IgnQtyPrc" --入库倒冲数量
			,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty"*IFNULL(T4."IgePrice",0) AS "IgnAmtPrc" --入库倒冲金额
			,IFNULL(T4."IgePrice",0) AS "AvgIgePrice"	--平均领料单价
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 THEN 'ZERO'
				ELSE 'ZCP' END 
				AS "CalType"	--计算类型 ZERO-0在产品 ZCP-按领料比例倒挤计算
			,CASE WHEN IFNULL(T0."IgnQty",0)-IFNULL(T1."PlannedQty",0)>=0 
				THEN 'ZERO:实际已入库数量'||IFNULL(T0."IgnQty",0)||'减去计划入库数量'||IFNULL(T1."PlannedQty",0)||'>=0'
				ELSE 'ZCP:实际领料金额'||IFNULL(T4."IgeAmt",0)
					||'减去(实际已入库数量'||IFNULL(T0."IgnQty",0)||'*'
					||'子件计划数量'||T2."PlannedQty"||'/'
					||'订单主件计划数量'||T1."PlannedQty"||'*'
					||'材料平均单价'||IFNULL(T4."IgePrice",0)||')'
				END
				AS "PriceMemo"
			FROM MTC_COST_0322_OWOR_ZCP T
			JOIN (SELECT "DocType","WorEntry","ItemCode"
						,SUM("IgnQty") AS "IgnQty"
						FROM "MTC_COST_0321_OWOR" WHERE "FcCode"<=:FcCode
						--AND "WorNum"=4220
							GROUP BY "DocType","WorEntry","ItemCode"
					) T0 ON T."DocType"=T0."DocType" AND T."WorEntry"=T0."WorEntry"
			--订单主件计划数量
			LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","DocNum","PostDate","PlannedQty","U_CardCode","U_OrdType" FROM OWOR
						UNION ALL
					   SELECT "Object" AS "ObjType","DocEntry","DocNum","U_PostDate","U_PlannedQty","U_CardCode","U_OrdType" FROM "@MTC_OWOR"
					) T1 ON T0."WorEntry"=T1."DocEntry" AND T0."DocType"=T1."ObjType"
			--订单子件计划数量
			LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","ItemCode",SUM("PlannedQty") AS "PlannedQty" FROM WOR1 GROUP BY "DocEntry","ItemCode"
						UNION ALL
					   SELECT "Object" AS "ObjType","DocEntry","U_ItemCode",SUM("U_PlannedQty") AS "PlannedQty"
					   			FROM "@MTC_WOR1" GROUP BY "Object","DocEntry","U_ItemCode"
					) T2 ON T1."DocEntry"=T2."DocEntry" AND T0."DocType"=T2."ObjType"
			LEFT JOIN OCRD T3 ON T1."U_CardCode"=T3."CardCode"
			JOIN (SELECT "DocType","WorEntry","ItemCode"
						,SUM(-1*"IgeQty") AS "IgeQty" 
						,SUM(-1*"Amount") AS "IgeAmt"
						,SUM(-1*"Amount")/NULLIF(SUM(-1*"IgeQty"),0) AS "IgePrice"
						FROM "MTC_COST_0321_OWOR1" WHERE "FcCode"<=:FcCode
							GROUP BY "DocType","WorEntry","ItemCode" HAVING SUM(-1*"IgeQty")<>0 OR SUM(-1*"Amount")<>0
						) T4 ON T4."DocType"=T0."DocType" AND T4."WorEntry"=T1."DocEntry" AND T2."ItemCode"=T4."ItemCode" 
			LEFT JOIN OITM T5 ON T4."ItemCode"=T5."ItemCode"
			WHERE 1=1
			AND T."WorType" IN ('50')
			AND T."订单状态"<>'已结算'
			--AND T."在产品新"<>0
			AND T."期间"=:FcCode
			AND (T."WorNum"=:WorNum OR :WorNum='')
			--AND T1."U_OrdType"='50'
			;
			
			DELETE FROM "MTC_COST_0322_OWOR_ZCP1" WHERE "FcCode"=:FcCode AND "WorType" IN ('50'); 
