-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0105_ITEM
CREATE PROCEDURE "MTC_COST_PROC_0105_ITEM"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取物料等级 到 明细到静态表 MTC_COST_0105_ITEM
     * CALL "MTC_COST_PROC_0105_ITEM"(0,'2024-01','manager');
    */
    
    DECLARE CNT INT = 0;
    DECLARE ILEVEL INT = 1;
    DECLARE MAXLEVEL INT = 0;
    
    BOM=
    SELECT T0."Code" AS "FatherCode",T1."Code" AS "ChildCode",:ILEVEL AS ILEVEL
    FROM "OITT" T0
    JOIN "ITT1" T1 ON T0."Code"=T1."Father"
    WHERE 1=1;
    
    SELECT COUNT(1) INTO CNT
    FROM :BOM T0
    JOIN :BOM T1 ON T0."FatherCode"=T1."ChildCode"
    WHERE T0."ILEVEL"=:ILEVEL;
    
    WHILE :CNT > 0 DO
    
    	BOM = 
    	SELECT * FROM :BOM
    	UNION ALL
	    SELECT T0."FatherCode",T1."ChildCode",:ILEVEL+1 AS ILEVEL
	    FROM :BOM T0
	    JOIN :BOM T1 ON T0."ChildCode"=T1."FatherCode"
	    WHERE 1=1 AND T0."ILEVEL"=:ILEVEL;
	    
	    ILEVEL := :ILEVEL + 1;
	    
    	SELECT COUNT(1) INTO CNT
		FROM :BOM T0
		JOIN :BOM T1 ON T0."FatherCode"=T1."ChildCode"
		WHERE T0."ILEVEL"=:ILEVEL;
    END WHILE;
    
    
	DELETE FROM MTC_COST_0105_ITEM WHERE "FcCode" = :FcCode;
	
	INSERT INTO MTC_COST_0105_ITEM(
	 "BPLId"
	,"FcCode"
	,"ItemCode"
	,"ItemName"
	,"ItmsGrpCod"
	,"Unit"
	,"CalType"
	,"CostCode"
	,"Level"			--层级 1最后（最高）层级-产成品   2以此减少
	,"CreateDate"		--创建时间
	,"Creator")
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T1."ItemCode"
	,T1."ItemName"
	,T1."ItmsGrpCod"
	,NULL AS "Unit"
	,NULL AS "U_CalType"
	,'A1' AS "CostCode"
	,MAX(T0."ILEVEL") AS "Level"
	,CURRENT_TIMESTAMP
	,:UserCode
	FROM :BOM T0
	JOIN OITM T1 ON T0."FatherCode"=T1."ItemCode"
	WHERE 1=1 GROUP BY T1."ItemCode",T1."ItemName",T1."ItmsGrpCod"
	;
	
	SELECT '写入物料成本计算等级成功！' FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0109_COSTTIME
CREATE PROCEDURE "MTC_COST_PROC_0109_COSTTIME"(IN DocEntry INT,IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN

	/* chris.li 
	   加载工时
	   CALL "MTC_COST_PROC_0109_COSTTIME"('3','1')
	*/
	
	DECLARE FcCode NVARCHAR(50);
	SELECT "U_FcCode" INTO FcCode FROM "@MTC_COST_TIME" WHERE "DocEntry"=:DocEntry;
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
	DELETE FROM "@MTC_COST_TIME1" WHERE "DocEntry"=:DocEntry;
	
	INSERT INTO "@MTC_COST_TIME1"(
	"DocEntry","LineId","VisOrder","Object"
	,"U_ItemCode","U_ItemName","U_Time","U_Memo")
	SELECT :DocEntry,ROW_NUMBER() OVER (ORDER BY T0."ItemCode") AS "LineId"
	,ROW_NUMBER() OVER (ORDER BY T0."ItemCode") AS "VisOrder",'MTC_COST_TIME'
	,T0."ItemCode",T0."ItemName",T0."Time",'来源'||T0."FcCode"
	FROM 
		(
		SELECT T0."ItemCode",T2."ItemName",MAX(IFNULL(T1."Time",0)) AS "Time",MAX(T1."FcCode") AS "FcCode"
		FROM "MTC_VIEW_Document" T0
		LEFT JOIN (SELECT T1."U_ItemCode" AS "ItemCode",T1."U_Time" AS "Time",T0."U_FcCode" AS "FcCode"
					,ROW_NUMBER() OVER (PARTITION BY T1."U_ItemCode" ORDER BY T0."U_FcCode" DESC,T1."LineId" DESC) AS "ID"
					FROM "@MTC_COST_TIME" T0
					JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry" 
				) T1 ON T0."ItemCode"=T1."ItemCode" AND T1."ID"=1
		JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
		WHERE LEFT(T0."DocDate",7)=:FcCode
		AND T0."ObjType" IN ('59','60')
		AND T0."TransCode" IN ('I03','I07')
		GROUP BY T0."ItemCode",T2."ItemName"
		) T0
	ORDER BY T0."ItemCode";
	
	SELECT '引入'||:FcCode||'成功' AS "信息" FROM DUMMY;

END

