-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_0401_CAL_QC
CREATE PROCEDURE "MTC_COST_PROC_0401_CAL_QC"(IN BPLId INT,IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	/* created by chri.li 2024.11.23
     * 抽取物料等级 到 明细到静态表 MTC_COST_0105_ITEM
     * CALL "MTC_COST_PROC_0401_CAL"(0,'2024-01','manager');
    */
    
    DECLARE CNT INT = 0;
    DECLARE ILEVEL INT = 1;
    DECLARE MAXLEVEL INT = 0;
    
    
	UPDATE T1 SET T1."Price"=T2."Price",T1."Amount"=T1."IgeQty"*T2."Price"
	FROM "MTC_COST_0321_OWOR1" T1
	JOIN (SELECT "U_Text1" AS "ItemCode",ROUND("U_Dec2"/NULLIF("U_Dec1",0),6) AS "Price"
			FROM "@MTC_IMPT1" WHERE "DocEntry"=1
		) T2 ON T1."ItemCode"=T2."ItemCode"
	WHERE T1."FcCode"='2024-11';
	
	--写入期初委外价格错误的
	INSERT INTO MTC_COST_0321_OWOR2("BPLId"
	,"FcCode"
	,"WorType"
	,"WorEntry"
	,"WorNum"
	,"CostCode"	--制造费用/人工费用
	,"ExpType"  --费用类型
	,"IgeQty"  
	,"Amount"
	,"CreateDate"   --创建时间
	,"Creator"
	)
	SELECT :BPLId AS "BPLId"
	,:FcCode AS "FcCode"
	,T0."WorType"
	,T0."WorEntry"
	,T0."WorNum"
	,'20' AS "CostCode"
	,'委外费用' AS "ExpType"
	,-1*T0."IgnQty" AS "IgeQty"
	,-1*T0."IgnQty"*T3."U_Dec1" AS "ExpAmt"
	,CURRENT_TIMESTAMP
	,'9999'	--特殊标识
	FROM MTC_COST_0321_OWOR T0
	LEFT JOIN (SELECT * FROm MTC_COST_0321_OWOR2 WHERE "FcCode"='2024-11') T1 ON T0."WorEntry"=T1."WorEntry" 
	JOIN OWOR T2 ON T0."WorNum"=T2."DocNum"
	LEFT JOIN (SELECT * FROM "@MTC_IMPT1" WHERE "DocEntry"=4) T3 ON T3."U_Text3"=T0."ItemCode" AND T3."U_Text2"=TO_ChAR(T2."DocEntry")
	WHERE 1=1
	AND T1."WorEntry" IS NULL
	AND T0."FcCode"='2024-11'
	;
	
	--委外(对期初的委外工单对应的材料进行更新价格)
	UPDATE T1 SET T1."Price"=T2."Price",T1."Amount"=T1."IgeQty"*T2."Price"
	FROM "MTC_COST_0321_OWOR1" T1
	JOIN OWOR T0 ON T1."WorEntry"=T0."DocEntry"
	JOIN (SELECT "U_Text1" AS "CardCode","U_Text4" AS "ItemCode"
			,ROUND("U_Dec2"/NULLIF("U_Dec1",0),6) AS "Price"
			FROM "@MTC_IMPT1" WHERE "DocEntry"=3
		) T2 ON T1."ItemCode"=T2."ItemCode" AND T0."U_CardCode"=T2."CardCode"
	WHERE T1."FcCode"='2024-11'
	AND T1."WorType"='50'
	--AND T1."ItemCode"='142000081'
	; 
    
    UPDATE T0 SET T0."Amount"=(IFNULL(T1."Amount",0)+IFNULL(T3."Amount",0))
	,T0."1Material"=T1."Amount"
	,T0."2ManExp"=T3."2ManExp"
	,T0."3LabAmount"=T3."3LabAmount"
	,T0."4WWExp"=T3."4ExpAmt"
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	LEFT JOIN (
			SELECT T1."BPLId",'2024-11' AS "FcCode",T1."WorEntry",SUM(T1."IgeQty") AS "IgeQty"
			,-1*SUM(T1."Amount") AS "Amount"
			--,SUM(T1."Amount"/NULLIF(T1."IgeQty",0)*T0."IgnQty") AS "Amount"
			FROM MTC_COST_0321_OWOR1 T1
			JOIN MTC_COST_0321_OWOR T0 ON  T1."WorEntry"=T0."WorEntry" AND T0."FcCode"=T1."FcCode"
			WHERE T1."FcCode"='2024-11' GROUP BY T1."BPLId",T1."WorEntry"
		) T1 ON T0."BPLId"=T1."BPLId" AND T0."FcCode"=T1."FcCode" AND T0."WorEntry"=T1."WorEntry"
	--制造费用+人工费用+委外费用
	LEFT JOIN (
			SELECT T2."BPLId",'2024-11' AS "FcCode",T2."WorEntry"
			,-1*SUM(T2."Amount") AS "Amount"
			,-1*SUM(CASE WHEN T2."CostCode"='20' THEN T2."Amount" ELSE 0 END) AS "4ExpAmt" --20委外
			,-1*SUM(CASE WHEN T2."CostCode"='30' THEN T2."Amount" ELSE 0 END) AS "3LabAmount"	--30制造费用
			,-1*SUM(CASE WHEN T2."CostCode"='40' THEN T2."Amount" ELSE 0 END) AS "2ManExp"	--40人工费用
			--,SUM(T2."Amount"/NULLIF(T2."IgeQty",0)*T0."IgnQty") AS "Amount"
			FROM MTC_COST_0321_OWOR2 T2
			JOIN MTC_COST_0321_OWOR T0 ON T2."FcCode"=T0."FcCode" AND T2."WorEntry"=T0."WorEntry"
			WHERE T2."FcCode"='2024-11' GROUP BY T2."BPLId",T2."WorEntry"
		) T3 ON T0."BPLId"=T3."BPLId" AND T0."FcCode"=T3."FcCode" AND T0."WorEntry"=T3."WorEntry"
	JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
	WHERE 1=1
	AND T0."FcCode"='2024-11';
    
    
	SELECT '写入物料成本计算等级成功！' FROM DUMMY;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_6101
CREATE PROCEDURE "MTC_COST_PROC_6101"
(
  UserCode NVARCHAR(50),
  FcCode NVARCHAR(50)
)
AS
BEGIN
 
		TMP=

		SELECT CASE WHEN T5."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END AS "Type"
		,T0."ObjType",'采购收货单' AS "DocName",T0."DocEntry",T0."DocNum",T1."LineNum",T0."CardCode",T0."CardName"
		,T0."DocDate",T5."ItemCode",T5."ItemName",T1."OpenQty"
		,T1."OpenQty"*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS "Amount"
		,CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS "Price"
		,T1."Quantity"-ifnull(T3."FPQTY",0)-ifnull(t4."CGTHQTY",0)-IFNULL(T9."RPDQty",0) AS "参考数量"
		--,T6."U_OldSysCode" AS "老系统编码"
		FROM OPDN T0
		INNER JOIN PDN1 T1 ON T1."DocEntry"=T0."DocEntry"
		LEFT JOIN (
		           ------应付发票数量----
		           SELECT T1."BaseEntry",T1."BaseType",T1."BaseLine",SUM(T1."Quantity") as "FPQTY"
		           FROM OPCH T0
		           INNER JOIN PCH1 T1 ON T1."DocEntry"=T0."DocEntry"
		           WHERE T0."isIns"='N' AND T0."CANCELED"='N'
		           GROUP BY T1."BaseEntry",T1."BaseType",T1."BaseLine" 
		           ) T3 ON T3."BaseEntry"=T1."DocEntry" AND T3."BaseType"=T0."ObjType" AND T3."BaseLine"=T1."LineNum"
		LEFT JOIN (
		           -----采购退货数量------
		           SELECT T1."BaseEntry",T1."BaseLine",T1."BaseType",SUM(T2."CGTHQTY") AS "CGTHQTY"
		           FROM OPRR T0
		           INNER JOIN PRR1 T1 ON T1."DocEntry"=T0."DocEntry"
		           left join (SELECT T1."BaseEntry",T1."BaseType",T1."BaseLine",sum(t1."Quantity") as "CGTHQTY"
		                      FROM ORPD T0
		                      INNER JOIN RPD1 T1 ON T1."DocEntry"=T0."DocEntry"
		                      where T0."CANCELED"='N'
		                      GROUP BY T1."BaseEntry",T1."BaseType",T1."BaseLine"
		                     ) T2 ON T2."BaseEntry"=T1."DocEntry" and T2."BaseType"=T0."ObjType" and T2."BaseLine"=T1."LineNum"
		           where T0."CANCELED"='N'
		           GROUP BY T1."BaseEntry",T1."BaseLine",T1."BaseType"
		           ) T4 ON T4."BaseEntry"=T1."DocEntry" and T4."BaseLine"=T1."LineNum" and T4."BaseType"=T1."ObjType"
		LEFT JOIN (
		           -----采购退货数量------
		           SELECT T1."BaseEntry",T1."BaseLine",T1."BaseType",SUM(T1."Quantity") AS "RPDQty"
		           FROM ORPD T0
		           INNER JOIN RPD1 T1 ON T1."DocEntry"=T0."DocEntry"
		           where T0."CANCELED"='N'
		           GROUP BY T1."BaseEntry",T1."BaseLine",T1."BaseType"
		           ) T9 ON T9."BaseEntry"=T1."DocEntry" and T9."BaseLine"=T1."LineNum" and T9."BaseType"=T1."ObjType"
		left join OITM T5 ON T5."ItemCode"=T1."ItemCode"  
		LEFT JOIN OCRD T6 ON T0."CardCode"=T6."CardCode"               
		WHERE T0."CANCELED"='N' 
		AND T1."OpenQty">0
		AND T1."LineStatus"='O'
		AND (LEFT(T0."DocDate",7)<=:FcCode)
		
		UNION ALL
		SELECT CASE WHEN T5."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END AS "Type"
		,T0."ObjType",'采购退货单' AS "DocName",T0."DocEntry",T0."DocNum",T1."LineNum",T0."CardCode",T0."CardName"
		,T0."DocDate",T5."ItemCode",T5."ItemName",-1*T1."OpenQty"
		,-1*T1."OpenQty"*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS "Amount"
		,CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS "Price"
		,-1*(IFNULL(T1."Quantity",0)-IFNULL(T3."FPQTY",0))
		FROM ORPD T0
		INNER JOIN RPD1 T1 ON T1."DocEntry"=T0."DocEntry"
		LEFT JOIN (
		           ------应付发票数量----
		           SELECT T1."BaseEntry",T1."BaseType",T1."BaseLine",SUM(T1."Quantity") as "FPQTY"
		           FROM ORPC T0
		           INNER JOIN RPC1 T1 ON T1."DocEntry"=T0."DocEntry"
		           WHERE 1=1 AND T0."CANCELED"='N'
		           GROUP BY T1."BaseEntry",T1."BaseType",T1."BaseLine" 
		           ) T3 ON T3."BaseEntry"=T1."DocEntry" AND T3."BaseType"=T0."ObjType" AND T3."BaseLine"=T1."LineNum"
		left join OITM T5 ON T5."ItemCode"=T1."ItemCode"     
		LEFT JOIN OCRD T6 ON T0."CardCode"=T6."CardCode"               
		WHERE T0."CANCELED"='N'
		AND T1."OpenQty">0
		AND T1."LineStatus"='O'
		AND (LEFT(T0."DocDate",7)<=:FcCode)
		ORDER BY "DocDate","CardCode";
		
		SELECT * FROM :TMP T0 
		ORDER BY T0."Type",T0."DocDate",T0."CardCode";
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_6101_1
CREATE PROCEDURE "MTC_COST_PROC_6101_1"
(
  UserCode NVARCHAR(50),
  FcCode NVARCHAR(50),
  STYPE NVARCHAR(30),    --SUM Detail ToOJDT 明细 
  CalType NVARCHAR(30),	--PUR1 材料计提   PUR4委外费用计提 CL_ZG WWExp_ZG
  IsOJDT NVARCHAR(10)
)
AS
BEGIN
	
	DECLARE MAXEntry INT;
	DECLARE TransCode NVARCHAR(30)=''; --交易代码
	DECLARE sdate DATE;
	DECLARE edate DATE;
	
	--SELECT '2024-01-01',"T_RefDate" INTO sdate,edate FROM "OFPR" WHERE "Code"=:FcCode;
	SELECT "F_RefDate","T_RefDate" INTO sdate,edate FROM "OFPR" WHERE "Code"=:FcCode;
	
  	

	TMP=
	SELECT CASE WHEN T1."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",T4."U_OldSysNo" AS "OPOROldSN",T0."U_OldSysNo" AS "OPDNOldSN"
	,T0."ObjType" AS "CalObjType",T0."DocEntry" AS "CalDocEntry",T0."DocNum" AS "CalDocNum",T1."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."Quantity" AS "Qty"
	,CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS "Price"
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END
			*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0
			THEN T1."Quantity"*T1."U_InitPrice" WHEN T1."U_IsPrice"='Y' THEN T1."Price"*T1."Quantity" ELSE T1."LineTotal" END,2) AS "Amt" --注释掉LineTotal OPDN.DocNum=2002有类似这样的情况
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."LineTotal",2) AS "LineTotal"
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."GTotal",2) AS "GTotal"
	FROM "OPDN" T0
	INNER JOIN "PDN1" T1 ON T0."DocEntry"=T1."DocEntry"
	INNER JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	LEFT JOIN "POR1" T3 ON T1."BaseEntry" =T3."DocEntry" AND T1."BaseLine" =T3."LineNum" AND T1."BaseType"=T3."ObjType"
	LEFT JOIN "OPOR" T4 ON T3."DocEntry" =T4."DocEntry"
	WHERE 1=1
	--AND (T0."CANCELED"='N' OR T0."DocNum" iN (9029,9760,13841))
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	
	UNION ALL
	SELECT CASE WHEN T1."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",T2."OPOROldSN",T2."OPDNOldSN"
	,T0."ObjType" AS "CalObjType",T0."DocEntry" AS "CalDocEntry",T0."DocNum" AS "CalDocNum",T1."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity" AS "Qty"
	,CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" WHEN T1."U_IsPrice"='Y' THEN T1."Price"*T1."Quantity" ELSE T1."LineTotal" END AS "Price"
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END
			*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0
			THEN T1."Quantity"*T1."U_InitPrice" ELSE T1."LineTotal" END,2) AS "Amt"
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."LineTotal",2) AS "LineTotal"
	,ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."GTotal",2) AS "GTotal"
	FROM "ORPD" T0
	INNER JOIN "RPD1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum"
			,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."U_InitPrice" ELSE D."Price" END AS "Price"
			,M2."U_OldSysNo" "OPOROldSN",M."U_OldSysNo" "OPDNOldSN"
			 FROM "OPDN" M
			 JOIN "PDN1" D ON M."DocEntry"=D."DocEntry"
			 LEFT JOIN "POR1" D2 ON D."BaseEntry" =D2."DocEntry" AND D."BaseLine" =D2."LineNum" AND D."BaseType"=D2."ObjType"
			 LEFT JOIN "OPOR" M2 ON D2."DocEntry" =M2."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	--AND T0."CANCELED"='N'
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	
	--针对来源于采购收货，才需要冲销暂估，需要按照采购收货的价格进行（冲暂估的金额，所以价格的取数要和采购收货单的一致）
	--发票取消的单据-视为无效，需要为0
	UNION ALL
	SELECT CASE WHEN T1."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END
	,T0."CardCode",T0."CardName",T0."DocDate",T2."OPOROldSN",T2."OPDNOldSN"
	,T2."ObjType" AS "CalObjType",T2."DocEntry" AS "CalDocEntry",T2."DocNum" AS "CalDocNum",T2."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE -1 END*T1."Quantity" AS "Qty"
	,T2."Price" AS "Price"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE -1 END
			*CASE WHEN T1."Quantity"=T2."Quantity" THEN T2."LineTotal"
				 ELSE T1."Quantity"*T2."Price" END,2) AS "Amt"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE -1 END*T1."LineTotal",2) AS "LineTotal"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE -1 END*T1."GTotal",2) AS "GTotal"
	FROM "OPCH" T0
	INNER JOIN "PCH1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum",D."Quantity",D."U_InitPrice"
			,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."U_InitPrice" ELSE D."Price" END AS "Price"
			,ROUND(CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."Quantity"*D."U_InitPrice" ELSE D."LineTotal" END,2) AS "LineTotal"
			,M2."U_OldSysNo" "OPOROldSN",M."U_OldSysNo" "OPDNOldSN"
			FROM "OPDN" M
			 JOIN "PDN1" D ON M."DocEntry"=D."DocEntry"
			 LEFT JOIN "POR1" D2 ON D."BaseEntry" =D2."DocEntry" AND D."BaseLine" =D2."LineNum" AND D."BaseType"=D2."ObjType"
			 LEFT JOIN "OPOR" M2 ON D2."DocEntry" =M2."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	--AND T0."CANCELED"='N'
	
	UNION ALL
	SELECT CASE WHEN T1."ItemCode"='X0510001' THEN '委外费用' ELSE '材料' END
	,T0."CardCode",T0."CardName",T0."DocDate",'' AS "OPOROldSN",'' AS "OPDNOldSN"
	,T2."ObjType" AS "CalObjType",T2."DocEntry" AS "CalDocEntry",T2."DocNum" AS "CalDocNum",T2."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE 1 END*T1."Quantity" AS "Qty"
	,T2."Price" AS "Price"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE 1 END
			*CASE WHEN T1."Quantity"=T2."Quantity" THEN T2."LineTotal"
				 ELSE T1."Quantity"*T2."Price" END,2) AS "Amt"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE 1 END*T1."LineTotal",2) AS "LineTotal"
	,ROUND(CASE WHEN T0."CANCELED"='Y' THEN 0 ELSE 1 END*T1."GTotal",2) AS "GTotal"
	FROM "ORPC" T0
	INNER JOIN "RPC1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum",D."Quantity",D."U_InitPrice"
			,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."U_InitPrice" ELSE D."Price" END AS "Price"
			,ROUND(CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."Quantity"*D."U_InitPrice" ELSE D."LineTotal" END,2) AS "LineTotal"
			 FROM "ORPD" M
			 JOIN "RPD1" D ON M."DocEntry"=D."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	--AND T0."CANCELED"='N'
	;
	
	IF :STYPE='SUM' THEN
		OPDN_SUM=
		SELECT T0."供应商编码",T0."供应商名称",SUM("计入暂估") AS "计入暂估"
			FROM (
			SELECT
			'采购收货' AS "类型"
			,T0."DocNum" AS "收退货Num"
			,T0."U_SupNum" AS "收退货单号"
			,T0."U_OldSysNo" AS "老系统单号"
			,T0."NumAtCard" AS "参考号"
			, T0."DocDate" AS "过账日期"
			, T0."DocCur" AS "币种"
			, T0."DocRate" AS "汇率"
			, T0."CardCode" AS "供应商编码"
			, T0."CardName" AS "供应商名称"
			, T1."ItemCode" AS "物料编号"
			, T1."Dscription" AS "物料名称"
			, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "数量"
			, T1."Price" AS "未税单价"
			, T1."PriceAfVAT" AS "含税单价"
			, T1."LineTotal" AS "未税金额（本币）"
			, T1."GTotal"  AS "含税金额（本币）"
			, T1."U_InitPrice" AS "初始单价(未税)"
			,  CAST(CAST(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END
				*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "暂估单价"
			, CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*
			  CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *
				ROUND(CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice" WHEN T1."U_IsPrice"='Y' THEN T1."Price"*T1."Quantity" ELSE T1."LineTotal" END
					,2) AS "计入暂估"
			, CASE when T1."LineStatus"='O' then N'未清' when T1."LineStatus"='C' then N'已清'  END  AS "行状态"
			, T0."TransId" AS "交易编码"
			, T1."AcctCode" AS "收入科目" 
			, T0."ObjType"  
			, T0."DocEntry"
			FROM OPDN T0  
			INNER JOIN PDN1 T1 ON T0."DocEntry" = T1."DocEntry" 
			LEFT JOIN "OCRD" T5 ON T0."CardCode"=T5."CardCode"
			LEFT JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
			--WHERE T0."CANCELED"='N'   
			
			UNION ALL 
			
			SELECT 
			'采购退货' AS "类型"
			,T0."DocNum" AS "收退货Num" /*退货*/
			,T0."U_SupNum" AS "收退货单号"
			,T0."U_OldSysNo" AS "老系统单号"
			,T0."NumAtCard" AS "参考号"
			, T0."DocDate" AS "过账日期"
			, T0."DocCur" AS "币种"
			, T0."DocRate" AS "汇率"
			, T0."CardCode" AS "供应商编码"
			, T0."CardName" AS "供应商名称"
			, T1."ItemCode" AS "物料编号"
			, T1."Dscription" AS "物料名称"
			, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "数量"
			, T1."Price" AS "未税单价"
			, T1."PriceAfVAT" AS "含税单价"
			, -1*T1."LineTotal" AS "未税金额（本币）"
			, -1*T1."GTotal"  AS "含税金额（本币）"
			, T1."U_InitPrice" AS "初始单价(未税)"
			, CAST(CAST(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END
				*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "暂估单价"
			, CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *
				ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice" WHEN T1."U_IsPrice"='Y' THEN T1."Price"*T1."Quantity" ELSE T1."LineTotal" END
					,2) AS "计入暂估"
			, CASE when T1."LineStatus"='O' then N'未清' when T1."LineStatus"='C' then N'已清'  END  AS "行状态"
			, T0."TransId" AS "交易编码"
			, T1."AcctCode" AS "收入科目" 
			, T0."ObjType"
			, T0."DocEntry"
			FROM ORPD T0  
			INNER JOIN RPD1 T1 ON T0."DocEntry" = T1."DocEntry" 
			LEFT JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
			--WHERE T0."CANCELED"='N'
			) T0
			WHERE  1=1 
			AND  (T0."过账日期">=:sdate)
			AND (T0."过账日期"<=:edate)
			GROUP BY T0."供应商编码",T0."供应商名称"
			;
			
		
		--取分录计提的数据
        OJDT_Amt=
        SELECT T2."CardCode" ,T2."CardName"
        ,SUM(CASE WHEN T0."TransCode" IN ('PUR1','PUR4') THEN T1."Debit"-T1."Credit" ELSE 0 END) AS "OJDT_OPDNAmt"
        ,SUM(CASE WHEN IFNULL(T0."TransCode",'') NOT IN ('PUR1','PUR4') THEN -1*(T1."Debit"-T1."Credit") ELSE 0 END) AS "OJDT_OPCHAmt"
		FROM OJDT T0
		JOIN JDT1 T1 ON T0."TransId"=T1."TransId"
		LEFT JOIN "OCRD" T2 ON T1."U_VendorCode"=T2."CardCode"
		WHERE 1=1
		AND T0."RefDate">=:sdate
		AND T0."RefDate"<=:edate
		AND T1."Account"='220202'
		GROUP BY T2."CardCode" ,T2."CardName";
		
		SELECT :FcCode AS "期间",T0."CardCode",T1."CardName",SUM("YW_OPDNAmt") AS "业务端计提"
		,SUM("OPDNAmt") AS "收退货金额"
		,SUM("OJDT_OPDNAmt") AS "分录计提金额"
		,IFNULL(SUM("YW_OPDNAmt"),0)-IFNULL(SUM("OPDNAmt"),0) AS "差异[业务端-收退货]"
		,IFNULL(SUM("YW_OPDNAmt"),0)-IFNULL(SUM("OJDT_OPDNAmt"),0) AS "差异[业务端计提-分录计提金额]"
		,SUM("YW_OPCHAmt") AS "业务端冲回"
		,SUM("OJDT_OPCHAmt") AS "分录暂估冲回"
		,IFNULL(SUM("YW_OPCHAmt"),0)-IFNULL(SUM("OJDT_OPCHAmt"),0) AS "差异[业务端冲回-分录暂估冲回]"
		FROM
			(
				SELECT 1 AS "ID",T0."CardCode",T0."CardName"
				,SUM(CASE WHEN T2."ItemCode"='X0510001' OR T2."InvntItem"='Y' THEN T0."Amt" ELSE 0 END) AS "YW_OPDNAmt"
				,0 AS "YW_OPCHAmt"
				,0 AS "OPDNAmt",0 AS "OJDT_OPDNAmt",0 AS "OJDT_OPCHAmt"
				FROM :TMP T0 
				JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
				LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
						) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
				LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
				WHERE T0."ObjType" IN (20,21)
				GROUP BY T0."CardCode",T0."CardName"
				
				UNION ALL
				SELECT 4 AS "ID",T0."CardCode",T0."CardName"
				,0.00 AS "YW_OPDNAmt",SUM(CASE WHEN T2."ItemCode"='X0510001' OR T2."InvntItem"='Y' THEN T0."Amt" ELSE 0 END) AS "YW_OPCHAmt"
				,0,0 AS "OJDT_PDAAmt",0 AS "OJDT_OPCHAmt"
				FROM :TMP T0 
				JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
				LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
				WHERE T0."ObjType" IN (18,19)
				GROUP BY T0."CardCode",T0."CardName"
				
				UNION ALL
				SELECT 2 AS "ID",T0."供应商编码",T0."供应商名称"
				,0,0,SUM("计入暂估") AS "计入暂估",0,0
				FROM :OPDN_SUM T0 GROUP BY T0."供应商编码",T0."供应商名称"
				
				UNION ALL
				SELECT 3 AS "ID",T0."CardCode",T0."CardName"
				,0,0,0,-1*SUM("OJDT_OPDNAmt"),SUM("OJDT_OPCHAmt")
				FROM :OJDT_Amt T0
				GROUP BY T0."CardCode",T0."CardName"
			) T0
		JOIN OCRD T1 ON T0."CardCode"=T1."CardCode"
		GROUP BY T0."CardCode",T1."CardName"
		ORDER BY T0."CardCode"
		;
			
		
		/*
		SELECT '当月应付暂估计提' AS "Memo",T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName"
		,SUM(T0."Amt") AS "Debit",0.00 AS "Credit"
		FROM :TMP T0 
		JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
		LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
		LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
		WHERE T0."ObjType" IN (20,21)
		GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName"
		
		UNION ALL
		SELECT '当月应付暂估计提' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName",0.00
		,SUM(T0."Amt") AS "Credit"
		FROM :TMP T0 
		LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
		WHERE T0."ObjType" IN (20,21)
		GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName"
		
		UNION ALL
		SELECT '当月冲销应付暂估' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName",0.00
		,SUM(T0."Amt") AS "Amt"
		FROM :TMP T0 
		LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
		WHERE T0."ObjType" IN (18,19)
		GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T0."CardCode",T0."CardName"
		
		;*/
		
	ELSEIF :STYPE = 'Detail' THEN
		
			SELECT T0."Type" AS "类型"
			,CASE WHEN T0."ObjType"='20' THEN '采购收货' WHEN T0."ObjType"='21' THEN '采购退货'
				 WHEN T0."ObjType"='18' THEN '应付发票' WHEN T0."ObjType"='19' THEN '应付贷项凭证' END AS "单据类型"
			,T0."CardCode" AS "供应商编码",T0."CardName" AS "供应商名称",T0."DocDate" AS "过账日期"
			,T0."OPOROldSN" AS "采购订单OldSN",T0."OPDNOldSN" AS "采购收货OldSN"
			,T0."ItemCode" AS "物料编码",T1."ItemName" AS "物料名称",T0."U_ItemCode" AS "委外物料编码"
			,T0."Qty" AS "数量"
			,T0."Price" AS "未税单价"
			,CASE WHEN T1."ItemCode"='X0510001' OR T1."InvntItem"='Y' THEN T0."Amt" ELSE 0 END AS "未税金额(计入暂估)"
			,T0."LineTotal" AS "参考未税金额"
			,T0."GTotal" AS "参考含税金额"
			,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
			,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
			,T3."StockAct"
			FROM :TMP T0
			LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T1."ItmsGrpCod"=T3."ItmsGrpCod"
			;
	
	ELSEIF :STYPE = 'ToOJDT' THEN 
		
		
		--PUR1 '当月应付暂估计提(材料)'
		IF :CalType = 'PUR1' THEN
			TMP_CL_JT=
			SELECT :FcCode AS "FcCode",1 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,SUM(T0."Amt") AS "Debit",0.00 AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR1'
			WHERE T0."ObjType" IN (20,21)
			AND T0."Type"='材料'
			AND T2."InvntItem"='Y'
			GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			SELECT :FcCode AS "FcCode",2 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName",0.00
			,SUM(T0."Amt") AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR1'
			WHERE T0."ObjType" IN (20,21)
			AND T0."Type"='材料'
			AND T2."InvntItem"='Y'
			GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			ORDER BY "ID","ObjType","AcctCode","CardCode"
			;
			
			IF :IsOJDT = 'N' THEN
				SELECT T0."FcCode",T0."ID",T0."TransCode",T0."TransName",T0."Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
				,T0."AcctCode",T0."AcctName",T0."Debit",T0."Credit"
				FROM :TMP_CL_JT T0
				ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode";
			ELSEIF :IsOJDT = 'Y' THEN
			
				IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
			  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
			  		RETURN;
			  	END IF;
			  	
				TransCode := 'PUR1'; --材料计提
				SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
				DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
				DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				
				INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
				,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
				SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',:edate,:FcCode
					,T0."TransCode",T0."Memo",'N',NULL
					FROM :TMP_CL_JT T0;
				
				INSERT INTO "@MTC_COST_OJDT1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_AcctCode","U_AcctName","U_VendorCode","U_VendorName","U_CardCode","U_CardName","U_FCCurrency"
					,"U_FCDebit","U_FCCredit","U_Debit","U_Credit"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
					,ROW_NUMBER() OVER (PARTITION BY "TransCode" ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode") AS "LineId","Memo"
					,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",NULL,NULL,'RMB' AS "FCCurrency"
					,0.00 AS "FCDebit",0.00 AS "FCCredit",ROUND(T0."Debit",2),ROUND(T0."Credit",2)
					FROM :TMP_CL_JT T0 
					WHERE 1=1
					AND (ABS(IFNULL(ROUND(T0."Debit",2),0))+ABS(IFNULL(ROUND(T0."Credit",2),0)))<>0
				;
				
				INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."ObjType",P0."DocEntry",P0."DocNum",P0."LineNum"
				,P0."CalObjType" AS "U_BaseType",P0."CalDocEntry" AS "U_BaseEntry",P0."CalDocNum" AS "U_BaseRef",P0."CalLineNum" AS "U_BaseLine"
				,P0."U_ItemCode",P0."U_ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				
				FROM (
						SELECT T11."TrnsCodDsc" AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode" AS "U_ItemCode",T2."ItemName" AS "U_ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode" AS "U_AcctCode",T4."AcctName" AS "U_AcctName"
						,T0."Amt" AS "U_Debit",0.00 AS "U_Credit",'D' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
								) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
						LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR1'
						WHERE T0."ObjType" IN (20,21)
						AND T0."Type"='材料'
						AND T2."InvntItem"='Y'
						
						UNION ALL
						SELECT T11."TrnsCodDsc" AS "U_Type",NULL AS "CardCode",NULL AS "CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode",T2."ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode",T4."AcctName"
						,0.00 AS "U_Debit",T0."Amt" AS "U_Credit",'C' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR1'
						WHERE T0."ObjType" IN (20,21)
						AND T0."Type"='材料'
						AND T2."InvntItem"='Y'
				) P0
			;
				
				SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
					,T0."U_TransCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName",T0."U_Memo" AS "Memo"
					,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName"
					,T1."U_VendorCode",T1."U_VendorName"
					,T1."U_FCCurrency" AS "FCCurrency"
					,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
					,T0."U_IsRev" AS "IsRev"		--是否需要冲销
					,TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
					,T1."U_CardCode" AS "U_CardCode"
					,T1."U_CardName" AS "U_CardName"
				FROM "@MTC_COST_OJDT" T0
				JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OTRC T11 ON T0."U_TransCode"=T11."TrnsCode"
				WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode
				AND (ABS(IFNULL(T1."U_Debit",0))+ABS(IFNULL(T1."U_Credit",0))+ABS(IFNULL(T1."U_FCDebit",0))+ABS(IFNULL(T1."U_FCCredit",0)))<>0
				;
			END IF;
			
		--PUR4 委外费用的计提
		ELSEIF :CalType = 'PUR4' THEN 
			TMP_WWExp_JT=
			SELECT :FcCode AS "FcCode",1 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,SUM(T0."Amt") AS "Debit",0.00 AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR4'
			WHERE T0."ObjType" IN (20,21)
			AND T0."Type"='委外费用'
			AND T2."InvntItem"='N'
			GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			SELECT :FcCode AS "FcCode",2 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName",0.00
			,SUM(T0."Amt") AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR4'
			WHERE T0."ObjType" IN (20,21)
			AND T0."Type"='委外费用'
			AND T2."InvntItem"='N'
			GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			ORDER BY "ID","ObjType","AcctCode","CardCode"
			;
			
			IF :IsOJDT = 'N' THEN
				SELECT T0."FcCode",T0."ID",T0."TransCode",T0."TransName",T0."Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
				,T0."AcctCode",T0."AcctName",T0."Debit",T0."Credit"
				FROM :TMP_CL_JT T0
				ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode";
			ELSEIF :IsOJDT = 'Y' THEN
				IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
			  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
			  		RETURN;
			  	END IF;
			  	
				TransCode := 'PUR4'; --委外费用计提
				SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
				DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
				DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				
				INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
				,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
				SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',:edate,:FcCode
					,T0."TransCode",T0."Memo",'N',NULL
					FROM :TMP_WWExp_JT T0;
				
				INSERT INTO "@MTC_COST_OJDT1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_AcctCode","U_AcctName","U_VendorCode","U_VendorName","U_CardCode","U_CardName","U_FCCurrency"
					,"U_FCDebit","U_FCCredit","U_Debit","U_Credit"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
					,ROW_NUMBER() OVER (PARTITION BY "TransCode" ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode") AS "LineId","Memo"
					,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",NULL,NULL,'RMB' AS "FCCurrency"
					,0.00 AS "FCDebit",0.00 AS "FCCredit",ROUND(T0."Debit",2),ROUND(T0."Credit",2)
					FROM :TMP_WWExp_JT T0 
					WHERE 1=1
					AND (ABS(IFNULL(ROUND(T0."Debit",2),0))+ABS(IFNULL(ROUND(T0."Credit",2),0)))<>0
				;
				
				INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."ObjType",P0."DocEntry",P0."DocNum",P0."LineNum"
				,P0."CalObjType" AS "U_BaseType",P0."CalDocEntry" AS "U_BaseEntry",P0."CalDocNum" AS "U_BaseRef",P0."CalLineNum" AS "U_BaseLine"
				,P0."U_ItemCode",P0."U_ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				
				FROM (
				
						SELECT T11."TrnsCodDsc" AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode" AS "U_ItemCode",T2."ItemName" AS "U_ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode" AS "U_AcctCode",T4."AcctName" AS "U_AcctName"
						,T0."Amt" AS "U_Debit",0.00 AS "U_Credit",'D' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
								) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
						LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR4'
						WHERE T0."ObjType" IN (20,21)
						AND T0."Type"='委外费用'
						AND T2."InvntItem"='N'
						
						UNION ALL
						SELECT T11."TrnsCodDsc" AS "U_Type",NULL AS "CardCode",NULL AS "CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode",T2."ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode",T4."AcctName"
						,0.00 AS "U_Debit",T0."Amt" AS "U_Credit",'C' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR4'
						WHERE T0."ObjType" IN (20,21)
						AND T0."Type"='委外费用'
						AND T2."InvntItem"='N'
				) P0
			;
				
				SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
					,T0."U_TransCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName",T0."U_Memo" AS "Memo"
					,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName"
					,T1."U_VendorCode",T1."U_VendorName"
					,T1."U_FCCurrency" AS "FCCurrency"
					,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
					,T0."U_IsRev" AS "IsRev"		--是否需要冲销
					,TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
					,T1."U_CardCode" AS "U_CardCode"
					,T1."U_CardName" AS "U_CardName"
				FROM "@MTC_COST_OJDT" T0
				JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OTRC T11 ON T0."U_TransCode"=T11."TrnsCode"
				WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode
				AND (ABS(IFNULL(T1."U_Debit",0))+ABS(IFNULL(T1."U_Credit",0))+ABS(IFNULL(T1."U_FCDebit",0))+ABS(IFNULL(T1."U_FCCredit",0)))<>0
				;
			END IF;
		
		--PUR5 系统自带生成的采购收货和采购退货的分录冲销 取OJDT
		ELSEIF :CalType = 'PUR5' THEN 
			--冲销系统分录
			TMP_CL_CXOJDT=
			SELECT :FcCode AS "FcCode",T2."AcctCode",T2."AcctName",T0."TransType",T7."DocName"
			,T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,-1*SUM(T1."Debit") AS "Debit"
			,-1*SUM(T1."Credit") AS "Credit"
			FROM "OJDT" T0
			JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
			LEFT JOIN "MTC_DocType" T7 ON T0."TransType" = T7."ObjType"
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR5'
			WHERE 1=1
			AND T0."TransType" IN ('20','21')
			AND (T0."RefDate" >= :sdate )
			AND (T0."RefDate" <= :edate)
			GROUP BY T2."AcctCode",T2."AcctName",T0."TransType",T7."DocName",T11."TrnsCode",T11."TrnsCodDsc"
			ORDER BY T2."AcctCode",T0."TransType";
			
			IF :IsOJDT = 'N' THEN
				SELECT T0."FcCode",T0."TransCode",T0."TransName",T0."Memo"
				,T0."AcctCode",T0."AcctName",T0."Debit",T0."Credit"
				FROM :TMP_CL_CXOJDT T0
				ORDER BY T0."AcctCode";
			ELSEIF :IsOJDT = 'Y' THEN
				IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
			  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
			  		RETURN;
			  	END IF;
			  	
				TransCode := 'PUR5'; --委外费用计提
				SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
				DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
				DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				
				INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
				,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
				SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',:edate,:FcCode
					,T0."TransCode",T0."Memo",'N',NULL
					FROM :TMP_CL_CXOJDT T0;
				
				INSERT INTO "@MTC_COST_OJDT1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_AcctCode","U_AcctName","U_FCCurrency"
					,"U_FCDebit","U_FCCredit","U_Debit","U_Credit"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
					,ROW_NUMBER() OVER (PARTITION BY "TransCode" ORDER BY T0."AcctCode") AS "LineId","Memo"
					,T0."AcctCode",T0."AcctName",'RMB' AS "FCCurrency"
					,0.00 AS "FCDebit",0.00 AS "FCCredit",ROUND(T0."Debit",2),ROUND(T0."Credit",2)
					FROM :TMP_CL_CXOJDT T0 
					WHERE 1=1
					AND (ABS(IFNULL(ROUND(T0."Debit",2),0))+ABS(IFNULL(ROUND(T0."Credit",2),0)))<>0
				;
				
				INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."ObjType",P0."DocEntry",P0."DocNum",P0."LineNum"
				,P0."CalObjType" AS "U_BaseType",P0."CalDocEntry" AS "U_BaseEntry",P0."CalDocNum" AS "U_BaseRef",P0."CalLineNum" AS "U_BaseLine"
				,P0."U_ItemCode",P0."U_ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				
				FROM (
						SELECT T11."TrnsCodDsc" AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,'30' AS "ObjType",T0."TransId" AS "DocEntry",T0."TransId" AS "DocNum",T1."Line_ID" AS "LineNum"
						,NULL AS"CalObjType",NULL AS "CalDocEntry",NULL AS "CalDocNum",NULL AS"CalLineNum"
						,NULL AS "U_ItemCode",NULL AS "U_ItemName"
						,0 AS "U_Quantity",0 AS "U_Price",0 AS "U_LineTotal",0 AS "U_PriceAfVAT",T1."Debit"-T1."Credit" AS "U_GTotal"
						,T2."AcctCode" AS "U_AcctCode",T2."AcctName" AS "U_AcctName"
						,T1."Debit" AS "U_Debit",T1."Credit" AS "U_Credit",CASE WHEN T1."Debit"<>0 THEN 'D' ELSE 'C' END AS "U_Point"
						
						FROM "OJDT" T0
						JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
						JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
						LEFT JOIN "MTC_DocType" T7 ON T0."TransType" = T7."ObjType"
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR5'
						WHERE 1=1
						AND T0."TransType" IN ('20','21')
						AND (T0."RefDate" >= :sdate )
						AND (T0."RefDate" <= :edate)
				) P0
			;
				
				SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
					,T0."U_TransCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName",T0."U_Memo" AS "Memo"
					,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName"
					,T1."U_VendorCode",T1."U_VendorName"
					,T1."U_FCCurrency" AS "FCCurrency"
					,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
					,T0."U_IsRev" AS "IsRev"		--是否需要冲销
					,TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
					,T1."U_CardCode" AS "U_CardCode"
					,T1."U_CardName" AS "U_CardName"
				FROM "@MTC_COST_OJDT" T0
				JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OTRC T11 ON T0."U_TransCode"=T11."TrnsCode"
				WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode
				AND (ABS(IFNULL(T1."U_Debit",0))+ABS(IFNULL(T1."U_Credit",0))+ABS(IFNULL(T1."U_FCDebit",0))+ABS(IFNULL(T1."U_FCCredit",0)))<>0
				;
			END IF;
		ELSEIF :CalType = 'PUR2' THEN
			TMP_CL_OPCH=
			SELECT :FcCode AS "FcCode",11 AS "ID"
			,T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'冲销系统应付发票' AS "LineMemo"
			,'材料' AS "Type",NULL AS "CardCode",NULL AS "CardName",T0."TransType" AS "ObjType"
			,T2."AcctCode",T2."AcctName"
			,-1*SUM(T1."Debit") AS "Debit"
			,-1*SUM(T1."Credit") AS "Credit"
			FROM "OJDT" T0
			JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
			WHERE 1=1
			AND T0."TransType" IN ('18','19')
			AND (T0."RefDate" >= :sdate )
			AND (T0."RefDate" <= :edate)
			AND (LEFT(T2."AcctCode",4) IN ('1403','1405','1409') OR T2."AcctCode"='220202')
			GROUP BY T2."AcctCode",T2."AcctName",T0."TransType",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			
			SELECT :FcCode AS "FcCode",21 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'发票库存影响差异' AS "LineMemo"
			,T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,SUM(T0."Amt"-T0."LineTotal") AS "Debit",0.00 AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
			WHERE T0."ObjType" IN (18,19)
			AND T0."Type"='材料'
			AND T2."InvntItem"='Y'
			GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			SELECT :FcCode AS "FcCode",31 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'当月发票冲回暂估' AS "LineMemo"
			,T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,-1*SUM(T0."Amt") AS "Debit",0.00
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
			WHERE T0."ObjType" IN (18,19)
			AND T0."Type"='材料'
			AND T2."InvntItem"='Y'
			GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			ORDER BY "ID","ObjType","AcctCode","CardCode"
			;
			
			IF :IsOJDT = 'N' THEN
				SELECT T0."FcCode",T0."ID",T0."TransCode",T0."TransName",T0."Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
				,T0."AcctCode",T0."AcctName",T0."Debit",T0."Credit"
				FROM :TMP_CL_OPCH T0
				ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode";
			ELSEIF :IsOJDT = 'Y' THEN
				TransCode := 'PUR2'; --材料计提
				SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
				DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
				DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				
				INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
				,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
				SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',:edate,:FcCode
					,T0."TransCode",T0."Memo",'N',NULL
					FROM :TMP_CL_OPCH T0;
				
				INSERT INTO "@MTC_COST_OJDT1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_AcctCode","U_AcctName","U_VendorCode","U_VendorName","U_CardCode","U_CardName","U_FCCurrency"
					,"U_FCDebit","U_FCCredit","U_Debit","U_Credit"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
					,ROW_NUMBER() OVER (PARTITION BY "TransCode" ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode") AS "LineId","LineMemo"
					,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",NULL,NULL,'RMB' AS "FCCurrency"
					,0.00 AS "FCDebit",0.00 AS "FCCredit",ROUND(T0."Debit",2),ROUND(T0."Credit",2)
					FROM :TMP_CL_OPCH T0 
					WHERE 1=1
					AND (ABS(IFNULL(ROUND(T0."Debit",2),0))+ABS(IFNULL(ROUND(T0."Credit",2),0)))<>0
				;
				
				INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."ObjType",P0."DocEntry",P0."DocNum",P0."LineNum"
				,P0."CalObjType" AS "U_BaseType",P0."CalDocEntry" AS "U_BaseEntry",P0."CalDocNum" AS "U_BaseRef",P0."CalLineNum" AS "U_BaseLine"
				,P0."U_ItemCode",P0."U_ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				
				FROM (
						SELECT '冲销系统应付发票' AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,'30' AS "ObjType",T0."TransId" AS "DocEntry",T0."TransId" AS "DocNum",T1."Line_ID" AS "LineNum"
						,NULL AS"CalObjType",NULL AS "CalDocEntry",NULL AS "CalDocNum",NULL AS"CalLineNum"
						,NULL AS "U_ItemCode",NULL AS "U_ItemName"
						,0 AS "U_Quantity",0 AS "U_Price",0 AS "U_LineTotal",0 AS "U_PriceAfVAT",T1."Debit"-T1."Credit" AS "U_GTotal"
						,T2."AcctCode" AS "U_AcctCode",T2."AcctName" AS "U_AcctName"
						,T1."Debit" AS "U_Debit",T1."Credit" AS "U_Credit",CASE WHEN T1."Debit"<>0 THEN 'D' ELSE 'C' END AS "U_Point"
						FROM "OJDT" T0
						JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
						JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
						WHERE 1=1
						AND T0."TransType" IN ('18','19')
						AND (T0."RefDate" >= :sdate )
						AND (T0."RefDate" <= :edate)
						AND (LEFT(T2."AcctCode",4) IN ('1403','1405','1409') OR T2."AcctCode"='220202')
						
						UNION ALL
						
						SELECT '发票库存影响差异' AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode" AS "U_ItemCode",T2."ItemName" AS "U_ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode" AS "U_AcctCode",T4."AcctName" AS "U_AcctName"
						,(T0."Amt"-T0."LineTotal") AS "Debit",0.00 AS "Credit",'D' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
								) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
						LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
						WHERE T0."ObjType" IN (18,19)
						AND T0."Type"='材料'
						AND T2."InvntItem"='Y'
						
						UNION ALL
						SELECT '当月发票冲回暂估' AS "U_Type",T0."CardCode",T0."CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode",T2."ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode",T4."AcctName"
						,-1*(T0."Amt") AS "Debit",0.00,'D' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR2'
						WHERE T0."ObjType" IN (18,19)
						AND T0."Type"='材料'
						AND T2."InvntItem"='Y'
				) P0
			;
				
				SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
					,T0."U_TransCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName",T0."U_Memo" AS "Memo"
					,T1."U_LineMemo" AS "LineMemo"
					,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName"
					,T1."U_VendorCode",T1."U_VendorName"
					,T1."U_FCCurrency" AS "FCCurrency"
					,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
					,T0."U_IsRev" AS "IsRev"		--是否需要冲销
					,TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
					,T1."U_CardCode" AS "U_CardCode"
					,T1."U_CardName" AS "U_CardName"
				FROM "@MTC_COST_OJDT" T0
				JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OTRC T11 ON T0."U_TransCode"=T11."TrnsCode"
				WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode
				AND (ABS(IFNULL(T1."U_Debit",0))+ABS(IFNULL(T1."U_Credit",0))+ABS(IFNULL(T1."U_FCDebit",0))+ABS(IFNULL(T1."U_FCCredit",0)))<>0
				;
				
				
			END IF;
		
		ELSEIF :CalType = 'PUR3' THEN
			TMP_WWExp_OPCH=
			SELECT :FcCode AS "FcCode",11 AS "ID"
			,T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'冲销系统应付发票' AS "LineMemo"
			,'材料' AS "Type",NULL AS "CardCode",NULL AS "CardName",T0."TransType" AS "ObjType"
			,T2."AcctCode",T2."AcctName"
			,-1*SUM(T1."Debit") AS "Debit"
			,-1*SUM(T1."Credit") AS "Credit"
			FROM "OJDT" T0
			JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
			WHERE 1=1
			AND T0."TransType" IN ('18','19')
			AND (T0."RefDate" >= :sdate )
			AND (T0."RefDate" <= :edate)
			AND (T2."AcctCode"='140802')
			GROUP BY T2."AcctCode",T2."AcctName",T0."TransType",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			
			SELECT :FcCode AS "FcCode",21 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'委外费用差异' AS "LineMemo"
			,T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,0.00 AS "Debit",-1*SUM(T0."Amt"-T0."LineTotal") AS "Credit"
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN OACT T4 ON T4."AcctCode"='140803'
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
			WHERE T0."ObjType" IN (18,19)
			AND T0."Type"='委外费用'
			GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			
			UNION ALL
			SELECT :FcCode AS "FcCode",31 AS "ID",T11."TrnsCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName"
			,T11."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
			,'当月发票冲回暂估' AS "LineMemo"
			,T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
			,T4."AcctCode",T4."AcctName"
			,-1*SUM(T0."Amt") AS "Debit",0.00
			FROM :TMP T0 
			JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
			LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
			LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
			WHERE T0."ObjType" IN (18,19)
			AND T0."Type"='委外费用'
			GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName",T11."TrnsCode",T11."TrnsCodDsc"
			ORDER BY "ID","ObjType","AcctCode","CardCode"
			;
			
			IF :IsOJDT = 'N' THEN
				SELECT T0."FcCode",T0."ID",T0."TransCode",T0."TransName",T0."Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
				,T0."AcctCode",T0."AcctName",T0."Debit",T0."Credit"
				FROM :TMP_WWExp_OPCH T0
				ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode";
			ELSEIF :IsOJDT = 'Y' THEN
				TransCode := 'PUR3'; --材料计提
				SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
				DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
				DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
				
				INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
				,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
				SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',:edate,:FcCode
					,T0."TransCode",T0."Memo",'N',NULL
					FROM :TMP_WWExp_OPCH T0;
				
				INSERT INTO "@MTC_COST_OJDT1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_AcctCode","U_AcctName","U_VendorCode","U_VendorName","U_CardCode","U_CardName","U_FCCurrency"
					,"U_FCDebit","U_FCCredit","U_Debit","U_Credit"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
					,ROW_NUMBER() OVER (PARTITION BY "TransCode" ORDER BY T0."ID",T0."ObjType",T0."AcctCode",T0."CardCode") AS "LineId","LineMemo"
					,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",NULL,NULL,'RMB' AS "FCCurrency"
					,0.00 AS "FCDebit",0.00 AS "FCCredit",ROUND(T0."Debit",2),ROUND(T0."Credit",2)
					FROM :TMP_WWExp_OPCH T0 
					WHERE 1=1
					AND (ABS(IFNULL(ROUND(T0."Debit",2),0))+ABS(IFNULL(ROUND(T0."Credit",2),0)))<>0
				;
				
				INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point"
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."ObjType",P0."DocEntry",P0."DocNum",P0."LineNum"
				,P0."CalObjType" AS "U_BaseType",P0."CalDocEntry" AS "U_BaseEntry",P0."CalDocNum" AS "U_BaseRef",P0."CalLineNum" AS "U_BaseLine"
				,P0."U_ItemCode",P0."U_ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				
				FROM (
						SELECT '冲销系统应付发票' AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,'30' AS "ObjType",T0."TransId" AS "DocEntry",T0."TransId" AS "DocNum",T1."Line_ID" AS "LineNum"
						,NULL AS "CalObjType",NULL AS "CalDocEntry",NULL AS "CalDocNum",NULL AS "CalLineNum"						
						,NULL AS "U_ItemCode",NULL AS "U_ItemName"
						,0 AS "U_Quantity",0 AS "U_Price",0 AS "U_LineTotal",0 AS "U_PriceAfVAT",-1*T1."Debit"+T1."Credit" AS "U_GTotal"
						,T2."AcctCode" AS "U_AcctCode",T2."AcctName" AS "U_AcctName"
						,-1*(T1."Debit") AS "U_Debit",-1*(T1."Credit") AS "U_Credit",CASE WHEN T1."Debit"<>0 THEN 'D' ELSE 'C' END AS "U_Point"
						FROM "OJDT" T0
						JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
						JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
						WHERE 1=1
						AND T0."TransType" IN ('18','19')
						AND (T0."RefDate" >= :sdate )
						AND (T0."RefDate" <= :edate)
						AND (T2."AcctCode"='140802')
						
						UNION ALL
						SELECT '委外费用差异' AS "U_Type",NULL AS "U_CardCode",NULL AS "U_CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode" AS "U_ItemCode",T2."ItemName" AS "U_ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "U_PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode" AS "U_AcctCode",T4."AcctName" AS "U_AcctName"
						,0.00 AS "U_Debit",-1*(T0."Amt"-T0."LineTotal") AS "U_Credit",'C' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN OACT T4 ON T4."AcctCode"='140803'
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
						WHERE T0."ObjType" IN (18,19)
						AND T0."Type"='委外费用'
					
						UNION ALL
						SELECT '当月发票冲回暂估' AS "U_Type",T0."CardCode",T0."CardName"
						,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
						,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
						,T2."ItemCode",T2."ItemName"
						,T0."Qty" AS "U_Quantity",T0."Price" AS "U_Price",T0."Amt" AS "U_LineTotal",0 AS "PriceAfVAT",T0."GTotal" AS "U_GTotal"
						,T4."AcctCode",T4."AcctName"
						,-1*(T0."Amt") AS "Debit",0.00,'D' AS "U_Point"
						FROM :TMP T0 
						JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
						LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
						LEFT JOIN OTRC T11 ON T11."TrnsCode"='PUR3'
						WHERE T0."ObjType" IN (18,19)
						AND T0."Type"='委外费用'
				) P0
			;
				SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
					,T0."U_TransCode" AS "TransCode",T11."TrnsCodDsc" AS "TransName",T0."U_Memo" AS "Memo"
					,T1."U_LineMemo" AS "LineMemo"
					,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName"
					,T1."U_VendorCode",T1."U_VendorName"
					,T1."U_FCCurrency" AS "FCCurrency"
					,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
					,T0."U_IsRev" AS "IsRev"		--是否需要冲销
					,TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
					,T1."U_CardCode" AS "U_CardCode"
					,T1."U_CardName" AS "U_CardName"
				FROM "@MTC_COST_OJDT" T0
				JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OTRC T11 ON T0."U_TransCode"=T11."TrnsCode"
				WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode
				AND (ABS(IFNULL(T1."U_Debit",0))+ABS(IFNULL(T1."U_Credit",0))+ABS(IFNULL(T1."U_FCDebit",0))+ABS(IFNULL(T1."U_FCCredit",0)))<>0
				;

				--发票暂估差异
				DELETE FROM "@MTC_OMRV" WHERE "U_DocDate"=:edate AND "U_BaseType"='WW';
				DELETE FROM "@MTC_OMRV1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_OMRV");
				
				INSERT INTO "@MTC_OMRV"("DocEntry","DocNum","Object","Canceled","U_DocDate"
				,"U_BaseType","U_Memo","U_Total")
				SELECT TOP 1 U_MTC_OMRV_S.NEXTVAL AS "DocEntry",U_MTC_OMRV_S.NEXTVAL AS "DocNum",'MTC_OMRV','N',:edate
					,'WW','系统自动生成委外发票差异' AS "Memo",T0."Total"
					FROM (SELECT SUM("Credit") AS "Total" FROM :TMP_WWExp_OPCH T0 WHERE "ID"=21) T0;
				
				INSERT INTO "@MTC_OMRV1"(
					"DocEntry","LineId","U_LineMemo"
					,"U_CalType","U_ItemCode","U_ItemName"
					,"U_Quantity","U_Price","U_Amount"
					,"U_BaseType","U_BaseEntry","U_BaseNum","U_BaseLine"
					,"U_StockCode","U_StockName","U_AcctCode","U_AcctName"
					)
				SELECT T1."DocEntry"
					,ROW_NUMBER() OVER (ORDER BY T0."ObjType",T0."DocEntry",T0."LineNum") AS "LineId"
					,'委外费用差异' AS "U_LineMemo",'ProCost' AS "U_CalType"
					,T2."ItemCode",T2."ItemName"
					,0 AS "U_Quantity",0 AS "U_Price",(T0."Amt"-T0."LineTotal") AS "U_Amount"
					,T0."ObjType" AS "U_BaseType",T0."DocEntry" AS "U_BaseEntry",T0."DocNum" AS "U_BaseNum",T0."LineNum" AS "U_BaseLine"
					,T4."AcctCode",T4."AcctName",T6."AcctCode",T6."AcctName"
					FROM :TMP T0
					LEFT JOIN (SELECT "DocEntry" FROM "@MTC_OMRV" WHERE "U_DocDate"=:edate AND "U_BaseType"='WW' AND "Canceled"='N') T1 ON 1=1
					JOIN "OITM" T2 ON T0."U_ItemCode"=T2."ItemCode"
					LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
						) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
					LEFT JOIN OACT T4 ON T3."StockAct"=T4."AcctCode"
					LEFT JOIN "@MTC_MRVTYPE" T5 ON T5."Code"='WW'
					LEFT JOIN OACT T6 ON T6."AcctCode"=T5."U_AcctCode"
					WHERE T0."ObjType" IN (18,19)
					AND T0."Type"='委外费用'
					AND T0."Amt"-T0."LineTotal"<>0
				;
				
				
			END IF;
		
		--CalType：PUR1\4\5结束
		END IF;
		
	--STYPE结束
	END IF;
	

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_6101_2
CREATE PROCEDURE "MTC_COST_PROC_6101_2"
(
  UserCode NVARCHAR(50),
  FcCode NVARCHAR(50),
  IsSum NVARCHAR(30)
)
AS
BEGIN
	
	DECLARE sdate DATE;
	DECLARE edate DATE;
	
	SELECT '2024-01-01',"T_RefDate" INTO sdate,edate FROM "OFPR" WHERE "Code"=:FcCode;
	--SELECT "F_RefDate","T_RefDate" INTO sdate,edate FROM "OFPR" WHERE "Code"=:FcCode;

	TMP=
	SELECT T0."U_SalOrdType" AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",T0."U_OldSysNo" AS "OPOROldSN",T0."U_OldSysNo" AS "OPDNOldSN"
	,T0."ObjType" AS "CalObjType",T0."DocEntry" AS "CalDocEntry",T0."DocNum" AS "CalDocNum",T1."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."Quantity" AS "Qty"
	,T1."U_InitPrice" AS "Price"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END
			*T1."Quantity"*T1."U_InitPrice" AS "Amt"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."LineTotal" AS "LineTotal"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."GTotal" AS "GTotal"
	FROM "ODLN" T0
	INNER JOIN "DLN1" T1 ON T0."DocEntry"=T1."DocEntry"
	INNER JOIN "OITM" T2 ON T1."ItemCode"=T2."ItemCode"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	
	UNION ALL
	SELECT T0."U_SalOrdType" AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",T2."OPOROldSN",T2."OPDNOldSN"
	,T0."ObjType" AS "CalObjType",T0."DocEntry" AS "CalDocEntry",T0."DocNum" AS "CalDocNum",T1."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity" AS "Qty"
	,T1."U_InitPrice" AS "Price"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END
			*T1."Quantity"*T1."U_InitPrice" AS "Amt"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."LineTotal" AS "LineTotal"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."GTotal" AS "GTotal"
	FROM "ORDN" T0
	INNER JOIN "RDN1" T1 ON T0."DocEntry"=T1."DocEntry"
	LEFT JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum"
			,CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN D."U_InitPrice" ELSE D."Price" END AS "Price"
			,M."U_OldSysNo" "OPOROldSN",M."U_OldSysNo" "OPDNOldSN"
			 FROM "ODLN" M
			 JOIN "DLN1" D ON M."DocEntry"=D."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	
	--针对来源于采购收货，才需要冲销暂估，需要按照采购收货的价格进行（冲暂估的金额，所以价格的取数要和采购收货单的一致）
	UNION ALL
	SELECT T0."U_SalOrdType" AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",T2."OPOROldSN",T2."OPDNOldSN"
	,T2."ObjType" AS "CalObjType",T2."DocEntry" AS "CalDocEntry",T2."DocNum" AS "CalDocNum",T2."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity" AS "Qty"
	,T2."Price" AS "Price"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END
			*T1."Quantity"*T2."Price" AS "Amt"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."LineTotal" AS "LineTotal"
	,CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."GTotal" AS "GTotal"
	FROM "OINV" T0
	INNER JOIN "INV1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum"
			,D."U_InitPrice" AS "Price"
			,M."U_OldSysNo" "OPOROldSN",M."U_OldSysNo" "OPDNOldSN"
			FROM "ODLN" M
			 JOIN "DLN1" D ON M."DocEntry"=D."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	AND T0."CANCELED"='N'
	
	UNION ALL
	SELECT T0."U_SalOrdType" AS "Type"
	,T0."CardCode",T0."CardName",T0."DocDate",'' AS "OPOROldSN",'' AS "OPDNOldSN"
	,T2."ObjType" AS "CalObjType",T2."DocEntry" AS "CalDocEntry",T2."DocNum" AS "CalDocNum",T2."LineNum" AS "CalLineNum"
	,T0."ObjType",T0."DocEntry",T0."DocNum",T1."LineNum",T1."U_ItemCode"
	,T1."ItemCode"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."Quantity" AS "Qty"
	,T2."Price" AS "Price"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END
			*T1."Quantity"*T2."Price" AS "Amt"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."LineTotal" AS "LineTotal"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END*T1."GTotal" AS "GTotal"
	FROM "ORIN" T0
	INNER JOIN "RIN1" T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN (SELECT M."ObjType",D."DocEntry",M."DocNum",D."LineNum"
			,D."U_InitPrice" AS "Price"
			 FROM "ORDN" M
			 JOIN "RDN1" D ON M."DocEntry"=D."DocEntry"
			 ) T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"
	WHERE 1=1
	AND T0."DocDate">=:sdate
	AND T0."DocDate"<=:edate
	AND T0."CANCELED"='N';
	
	IF :IsSum=0 THEN
		
		SELECT '当月应付暂估计提' AS "Memo",T0."Type",NULL AS "CardCode",NULL AS "CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName"
		,SUM(T0."Amt") AS "Debit",0.00 AS "Credit"
		FROM :TMP T0 
		JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
		LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=LEFT('2024-12',4) GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
		LEFT JOIN OACT T4 ON T4."AcctCode"=CASE WHEN T0."Type"='委外费用' THEN '140802' ELSE T3."StockAct" END
		WHERE T0."ObjType" IN (15,16)
		GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName"
		
		UNION ALL
		SELECT '当月应付暂估计提' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName",0.00
		,SUM(T0."Amt") AS "Credit"
		FROM :TMP T0 
		LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
		WHERE T0."ObjType" IN (20,21)
		GROUP BY T0."Type",T0."CardCode",T0."CardName",T0."ObjType",T4."AcctCode",T4."AcctName"
		
		UNION ALL
		SELECT '当月冲销应付暂估' AS "Memo",T0."Type",T0."CardCode",T0."CardName",T0."ObjType"
		,T4."AcctCode",T4."AcctName",0.00
		,SUM(T0."Amt") AS "Amt"
		FROM :TMP T0 
		LEFT JOIN OACT T4 ON T4."AcctCode"='220202'
		WHERE T0."ObjType" IN (18,19)
		GROUP BY T0."Type",T0."ObjType",T4."AcctCode",T4."AcctName",T0."CardCode",T0."CardName"
		
		;
		
	ELSE 
		SELECT T0."Type" AS "类型",T2."GroupCode"
		,CASE WHEN T0."ObjType"='15' THEN '销售交货' WHEN T0."ObjType"='16' THEN '销售退货'
			 WHEN T0."ObjType"='13' THEN '应收发票' WHEN T0."ObjType"='14' THEN '应收贷项凭证' END AS "单据类型"
		,T0."CardCode" AS "客户编码",T0."CardName" AS "客户名称",T0."DocDate" AS "过账日期"
		,T0."OPOROldSN" AS "采购订单OldSN",T0."OPDNOldSN" AS "采购收货OldSN"
		,T0."ItemCode" AS "物料编码",T1."ItemName" AS "物料名称",T0."U_ItemCode" AS "委外物料编码"
		,T0."Qty" AS "数量"
		,T0."Price" AS "未税成本单价"
		,T0."Amt" AS "未税成本金额"
		,T0."LineTotal" AS "参考未税金额"
		,T0."GTotal" AS "参考含税金额"
		,T0."CalObjType",T0."CalDocEntry",T0."CalDocNum",T0."CalLineNum"
		,T0."ObjType",T0."DocEntry",T0."DocNum",T0."LineNum"
		FROM :TMP T0
		LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
		LEFT JOIN OCRD T2 ON T0."CardCode"=T2."CardCode"
		;
	END IF;
	

END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1001_CHECK
CREATE PROCEDURE "MTC_COST_PROC_CAL_1001_CHECK"(IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50),IN IsInsert NVARCHAR(30) DEFAULT 'N')
LANGUAGE SQLSCRIPT
AS
BEGIN
	/*
		CALL "MTC_COST_PROC_CAL_1001_CHECK"('2025-01','1');
	*/
	
	
	DECLARE sdate DATE;
	DECLARE edate DATE;
	DECLARE LastFcCode NVARCHAR(30); --上一期间
	DECLARE MAXEntry INT;
	
	DECLARE CNT INT;
	
	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
  	
  	CREATE LOCAL TEMPORARY TABLE #LIST("RptCode" NVARCHAR(50),"RptName" NVARCHAR(50),"DocEntry" INT,"Result" NVARCHAR(10));
  	
  	--拉取库存交易明细
    CALL "MTC_COST_PROC_0303_INVNTDETAIL2"(0,:FcCode,:UserCode);
	
	
	SELECT "F_RefDate","T_RefDate" INTO sdate,edate FROM OFPR WHERE "Code"=:FcCode; 
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	/*
	--当采购退货的价格为空的时候，将上期的价格写入
	UPDATE T1 SET T1."U_InitPrice"=T2."Price"
	FROM ORPD T0
	JOIN RPD1 T1 ON T0."DocEntry"=T1."DocEntry"
	JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "CostCode"='20' AND "FcCode"=:LastFcCode) T2 ON T1."ItemCode"=T2."ItemCode"
	WHERE 1=1
	AND T0."DocDate">=:sdate AND T0."DocDate"<=:edate
	AND T1."Price"=0;
	
	
	TMP=
	SELECT 
	 P0."TransType" AS "ObjType"
	,P0."CreatedBy" AS "DocEntry"
	,P0."BASE_REF" AS "DocNum"
	,P0."DocLineNum" AS "LineNum"
	,P0."DocDate"
	,P5."CostTypeCode" AS "CostCode"   --归入成本计价类型
	,P8."TransCode"   --实际交易类型
	,P8."BaseType"
	,P8."BaseEntry"
	,CASE WHEN TO_CHAR(P8."BaseRef") IN ('') THEN NULL ELSE P8."BaseRef" END AS "BaseNum"
	,P8."BaseLine"
	,P0."ItemCode"
	,P1."ItemName"
	,P1."ItmsGrpCod"
	,NULL AS "iLevel"
	,P1."U_ItemProp" AS "CalType" --成本计价类型
	,P0."InQty"-P0."OutQty" AS "Quantity"
	,CASE WHEN P0."TransType" IN ('20','21') THEN P9."Amount" 
		ELSE P0."SumStock" END AS "Amount"
	FROM OIVL P0
	LEFT JOIN OITM P1 ON P0."ItemCode"=P1."ItemCode"
	LEFT JOIN OITB P2 ON P1."ItmsGrpCod"=P2."ItmsGrpCod"
	JOIN MTC_COST_0101_COSTTYPE P5 ON P5."CostTypeCode"='20'	--材料
	LEFT JOIN (SELECT T0."ObjType",T0."DocEntry",T0."LineNum",T0."OcrCode"
				,T0."BaseType",T0."BaseEntry",T0."BaseRef",T0."BaseLine"
				,T0."TransCode"
				FROM "MTC_VIEW_Document" T0
		) P8 ON TO_CHAR(P0."TransType")=P8."ObjType" AND TO_CHAR(P0."CreatedBy")=P8."DocEntry" AND TO_CHAR(P0."DocLineNum")=P8."LineNum"
	LEFT JOIN (SELECT M."ObjType",M."DocEntry",D."LineNum"
				,CASE WHEN M."CANCELED"='C' THEN -1 ELSE 1 END
				 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
				FROM OPDN M JOIN PDN1 D ON M."DocEntry"=D."DocEntry"
				UNION ALL
				SELECT M."ObjType",M."DocEntry",D."LineNum"
				,CASE WHEN M."CANCELED"='C' THEN 1 ELSE -1 END
				 *CASE WHEN IFNULL(D."U_InitPrice",0)<>0 THEN IFNULL(D."U_InitPrice",0)*D."Quantity" ELSE D."LineTotal" END AS "Amount"
				FROM ORPD M JOIN RPD1 D ON M."DocEntry"=D."DocEntry"
			) P9 ON TO_CHAR(P0."TransType")=P9."ObjType" AND P0."CreatedBy"=P9."DocEntry" AND P0."DocLineNum"=P9."LineNum"
	WHERE 1=1
	AND P0."DocDate">=:sdate AND P0."DocDate"<=:edate;
	*/
	
	--上期库存+本期入库
	Onhand_SUM=
	SELECT "ItemCode",SUM("Amount") AS "Amount",SUM("Qty") AS "Qty",SUM("Amount")/NULLIF(SUM("Qty"),0) AS "Price"
	FROM (
			SELECT "ItemCode","QM_Amount" AS "Amount","QM_Qty" AS "Qty" FROM MTC_COST_0301_INVNT T0
			WHERE T0."FcCode"=:LastFcCode AND "CostCode"='20'
			--当期入库
			UNION ALL
			SELECT "ItemCode","Amount","Quantity" FROM MTC_COST_0302_INVNTDETAIL1
			WHERE 1=1
			--AND "ObjType" IN ('20','21','18','19') 
			AND "ObjType" IN ('20') 
			AND "FcCode"=:FcCode
		) T0
	GROUP BY "ItemCode"	
	;
	
	--还需要对出入库处理
	TMP_SUM=
	SELECT T0."ItemCode",SUM("Quantity") AS "Quantity",T1."Price"
	,LEFT(STRING_AGG(T2."Name",','),250) AS "IOName"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN :Onhand_SUM T1 ON T0."ItemCode"=T1."ItemCode"
	LEFT JOIN "@MTC_COST_IOTYPE" T2 ON T0."TransCode"=T2."Code"
	WHERE T0."TransCode" IN ('I04','O04','I05','O06','I10','I07','I08')
	AND T0."FcCode"=:FcCode
	--AND T0."Quantity">0 --入库
	GROUP BY T0."ItemCode",T1."Price";
	
	SELECT COUNT(1) INTO CNT FROM "@MTC_COST_QCPRICE" WHERE "U_FcCode"=:FcCode; 
	
	--DELETE FROM "@MTC_COST_QCPRICE" WHERE "U_FcCode"=:FcCode;
	--DELETE FROM "@MTC_COST_QCPRICE1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_QCPRICE");
	
	IF :IsInsert = 'Y' OR :IsInsert = 'I' THEN 
		
		IF :IsInsert = 'I' OR :CNT = 0 THEN
	
			DELETE FROM "@MTC_COST_QCPRICE" WHERE "U_FcCode"=:FcCode;
			DELETE FROM "@MTC_COST_QCPRICE1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_QCPRICE");
			
			SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_QCPRICE";
			INSERT INTO "@MTC_COST_QCPRICE"("DocEntry","DocNum","Object","U_FcCode","U_Memo")
			SELECT TOP 1 :MAXEntry+1,:MAXEntry+1,'MTC_COST_QCPRICE',:FcCode,'' FROM :TMP_SUM;
		
			INSERT INTO "@MTC_COST_QCPRICE1"("DocEntry","LineId","U_ItemCode","U_ItemName","U_ItmsGrpCod","U_ItmsGrpNam"
			,"U_U_KeyItem","U_Price","U_iLevel","U_LineMemo")
			SELECT :MAXEntry+1
			,ROW_NUMBER() OVER (ORDER BY T0."ItemCode")
			,T1."ItemCode",T1."ItemName",T1."ItmsGrpCod",T2."ItmsGrpNam",T1."U_KeyItem"
			,CASE WHEN IFNULL(T0."Price",0)=0 THEN IFNULL(T5."Price",0) ELSE IFNULL(T0."Price",0) END AS "Price"
			--,CASE WHEN IFNULL(T0."Price",0)=0 THEN IFNULL(T5."U_Price",0) ELSE IFNULL(T0."Price",0) END AS "Price"
			,0,LEFT(IFNULL(T0."IOName",'')
			|| CASE WHEN IFNULL(T0."Price",0)=0 AND IFNULL(T5."U_FcCode",'')<>'' THEN ','||'上次期间:'||IFNULL(T5."U_FcCode",'') ELSE '' END,254)
			FROM :TMP_SUM T0
			JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
			JOIN OITB T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
			LEFT JOIN (SELECT ROW_NUMBER() OVER(PARTITION BY "ItemCode" ORDER BY "DocDate" DESC) AS "ID"
						,"ItemCode","Price","FcCode" AS "U_FcCode"
						FROM "MTC_COST_0302_INVNTDETAIL1" WHERE 1=1 AND "FcCode"<:FcCode
						--AND "ItemCode"='F01400701'
						AND IFNULL("Price",0)<>0
					) T5 ON T1."ItemCode"=T5."ItemCode" and T5."ID"=1
			/*
		LEFT JOIN (SELECT D."U_ItemCode",D."U_Price",D."DocEntry",M."U_FcCode"
						,ROW_NUMBER() OVER (PARTITION BY D."U_ItemCode" ORDER BY M."U_FcCode" DESC) AS "ID"
						FROM "@MTC_COST_QCPRICE" M
						JOIN "@MTC_COST_QCPRICE1" D ON M."DocEntry"=D."DocEntry"
						WHERE M."Canceled"='N' AND M."U_FcCode"<:FcCode
				) T5 ON T0."ItemCode"=T5."U_ItemCode" AND T5."ID"=1	*/		
			WHERE 1=1
			ORDER BY T0."ItemCode";
		END IF;
	END IF;
	
	--生成期初单价维护
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 2,'期初单价维护',"DocEntry",'Y'
	FROM "@MTC_COST_QCPRICE" WHERE "U_FcCode"=:FcCode;
	
	--3.期初库存检查
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 3,'上期期末库存核对',SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END)
	,CASE WHEN SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END) = 0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT "ItemCode","QM_Qty",0 AS "OnHand" FROM "MTC_COST_0301_INVNT" WHERE "FcCode"=:LastFcCode AND "CostCode"='20'
				
				UNION ALL
				SELECT "ItemCode",0 AS "QC_Qty",SUM("InQty"-"OutQty") AS "OnHand" FROM OIVL WHERE "DocDate"<:sdate GROUP BY "ItemCode"
			) T0 GROUP BY T0."ItemCode"
			HAVING SUM(T0."QM_Qty")-SUM(T0."OnHand")<>0
		) T1 ON 1=1
	;
	
	--4.生产试打的订单的领料类型，只能是
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 4,'生产试打的生产订单只能选择307试打领用和305生产报废',SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END)
	,CASE WHEN SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END) = 0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT T0."DocEntry" 
				FROM "OIGE" T0
				JOIN "IGE1" T1 ON T0."DocEntry"=T1."DocEntry"
				JOIN OWOR T2 ON T1."BaseType"='202' AND T1."BaseEntry"=T2."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode 
				AND T2."U_OrdType"='40'
				AND T0."U_TrsName" NOT IN ('307','305')
				UNION ALL
				SELECT T0."DocEntry" 
				FROM "OIGN" T0
				JOIN "IGN1" T1 ON T0."DocEntry"=T1."DocEntry"
				JOIN OWOR T2 ON T1."BaseType"='202' AND T1."BaseEntry"=T2."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode 
				AND T2."U_OrdType"='40'
				AND T0."U_TrsName" NOT IN ('307','305')
			) T0 GROUP BY T0."DocEntry"
		) T1 ON 1=1
	;
	
	--5.转换出入库一致
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 5,'转换出入库当期数量一致',SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END)
	,CASE WHEN SUM(CASE WHEN T1."Result">0 THEN 1 ELSE 0 END) = 0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT -1*T1."Quantity" AS "Quantity"
				FROM "OIGE" T0
				JOIN "IGE1" T1 ON T0."DocEntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode 
				AND T0."U_TrsName" IN ('204','205')
				UNION ALL
				SELECT T1."Quantity"
				FROM "OIGN" T0
				JOIN "IGN1" T1 ON T0."DocEntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode 
				AND T0."U_TrsName" IN ('204','205')
			) T0 HAVING SUM("Quantity")<>0
		) T1 ON 1=1
	;
	


	--6.报废仓的库存应该为0
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 6,'S300报废仓的库存为0',SUM(T1."Result")
	,CASE WHEN SUM(T1."Result")>0 THEN 'N' ELSE 'Y' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT "ItemCode",SUM("InQty"-"OutQty") AS "OnHand" FROM OIVL WHERE TO_CHAR("DocDate",'YYYY-MM')<=:FcCode AND "LocCode"='S300'
				GROUP BY "ItemCode" HAVING SUM("InQty"-"OutQty")<>0
			) T0
		) T1 ON 1=1
	;
	
	--7.检查截至到当月尚未关单的
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 7,'截至当月已完工但尚未关单的生产工单',SUM(T1."Result")
	,CASE WHEN SUM(T1."Result") > 0 THEN 'N' ELSE 'Y' END
	FROM DUMMY T0
	LEFT JOIN (	
			SELECT COUNT(1) AS "Result"
			FROM (
				SELECT '202' AS "WorType",T1."DocEntry",T1."DocNum",T1."PlannedQty",T0."WorQty",T0."DocDate"
				FROM (
					SELECT T0."OWORNum",SUM(T0."Quantity") AS "WorQty",MAX("DocDate") AS "DocDate"
					FROM "MTC_VIEW_ProductDetail" T0
					LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
					LEFT JOIN "OITB" T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
					WHERE 1=1
					--AND T0."OWORNum"=39517
					AND T0."Type"='主件'
					AND LEFT(T0."DocDate",7)<=:FcCode
					GROUP BY T0."OWORNum"
					) T0
				JOIN "OWOR" T1 ON T0."OWORNum"=T1."DocNum"
				WHERE T1."Status" IN ('P','R')
				AND T1."PlannedQty"-IFNULL(T0."WorQty",0)<=0 --实际完工数量大于等于计划数量
			
				UNION ALL
				SELECT T1."Object" AS "WorType",T1."DocEntry",T1."DocNum",T1."U_PlannedQty",T0."WorQty",T0."DocDate"
				FROM (
					SELECT T0."BaseEntry" AS "OWORNum",SUM(T0."Quantity") AS "WorQty",MAX("DocDate") AS "DocDate"
					FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
					LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
					LEFT JOIN "OITB" T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
					WHERE 1=1
					--AND T0."OWORNum"=39517
					AND T0."Type"='主件'
					AND LEFT(T0."DocDate",7)<=:FcCode
					GROUP BY T0."BaseEntry"
					) T0
				JOIN "@MTC_OWOR" T1 ON T0."OWORNum"=T1."DocNum"
				WHERE T1."U_Status" IN ('P','R')
				AND T1."U_PlannedQty"-IFNULL(T0."WorQty",0)<=0 --实际完工数量大于等于计划数量
			) P
		) T1 ON 1=1;
	
	--8.检查当月的生产工时为0
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 8,'检查当月的生产工时为0',SUM(T1."Result")
	,CASE WHEN SUM(T1."Result")>0 THEN 'N' ELSE 'Y' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT T0."ItemCode",T2."ItemName",T1."U_Time"
				FROM "MTC_VIEW_Document" T0
				JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
				LEFT JOIN (SELECT T1."U_ItemCode",T1."U_Time"
							FROM "@MTC_COST_TIME" T0
							JOIN "@MTC_COST_TIME1" T1 ON T0."DocEntry"=T1."DocEntry"
							WHERE 1=1
							AND T0."U_FcCode"=:FcCode
						   ) T1 ON T0."ItemCode"=T1."U_ItemCode"
				WHERE LEFT(T0."DocDate",7)=:FcCode
				AND IFNULL(T1."U_Time",0)=0
				AND T0."ObjType" IN ('59','60')
				AND T0."TransCode" IN ('I03','I07')
				GROUP BY T0."ItemCode",T2."ItemName",T1."U_Time"
			) T0
		) T1 ON 1=1
	;
	
	--9.当月入库次月领料
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 9,'当月入库次月领料',SUM(T1."Result")
	,CASE WHEN SUM(T1."Result")>0 THEN 'N' ELSE 'Y' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT A."OWORNum",A."OWOREntry"
				FROM (
					SELECT
					T0."OWORNum",T0."OWOREntry",T1."PlannedQty",T1."CmpltQty"
					,MAX(CASE WHEN T0."Type"='主件' THEN "DocDate" ELSE NULL END) AS "Main_DocDate"
					,MAX(CASE WHEN T0."Type"='子件' THEN "DocDate" ELSE NULL END) AS "Detail_DocDate"
					FROM "MTC_VIEW_ProductDetail" T0
					LEFT JOIN OWOR T1 ON T0."OWORNum"=T1."DocNum"
					WHERE 1=1 AND IFNULL(T1."PlannedQty",0)-IFNULL(T1."CmpltQty",0)<=0
					GROUP BY T0."OWORNum",T0."OWOREntry",T1."PlannedQty",T1."CmpltQty"
				) A 
				WHERE TO_CHAR(A."Main_DocDate",'YYYY-MM')<TO_CHAR(A."Detail_DocDate",'YYYY-MM')
				AND TO_CHAR(A."Main_DocDate",'YYYY-MM')<=:FcCode --当月入库
				AND TO_CHAR(A."Detail_DocDate",'YYYY-MM')>:FcCode --次月领料
				
				UNION ALL
				SELECT A."BaseEntry",A."BaseLine"
				FROM (
					SELECT
					T0."BaseEntry",T0."BaseLine"
					,MAX(CASE WHEN T0."Type"='主件' THEN "DocDate" ELSE NULL END) AS "Main_DocDate"
					,MAX(CASE WHEN T0."Type"='子件' THEN "DocDate" ELSE NULL END) AS "Detail_DocDate"
					FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
					GROUP BY T0."BaseType",T0."BaseEntry",T0."BaseLine"
				) A 
				WHERE TO_CHAR(A."Main_DocDate",'YYYY-MM')<TO_CHAR(A."Detail_DocDate",'YYYY-MM')
				AND TO_CHAR(A."Main_DocDate",'YYYY-MM')<=:FcCode --当月入库
				AND TO_CHAR(A."Detail_DocDate",'YYYY-MM')>:FcCode --次月领料
			) T0
		) T1 ON 1=1
	;
	
	--10.平台价维护
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 10,'平台价维护',T1."Result"
	,CASE WHEN T1."Result"=0 THEN 'N' ELSE 'Y' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT "DocEntry" FROM "@MTC_PTPRICE" WHERE "U_FcCode"=:FcCode
			) T0
		) T1 ON 1=1
	;
	
	
	--11.销售跨月做单
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 11,'销售跨月做单',T1."Result"
	,CASE WHEN T1."Result"=0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT DISTINCT '15.1交货引用交货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "DLN1" T1
				JOIN "ODLN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '15.2交货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "DLN1" T1
				JOIN "ODLN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '13.1应收发票引用交货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "INV1" T1
				JOIN "OINV" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '13.2应收发票引用发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "INV1" T1
				JOIN "OINV" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OINV" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '16.1销售退货引用交货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RDN1" T1
				JOIN "ORDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '16.2销售退货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RDN1" T1
				JOIN "ORDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.1应收贷项发票引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.2应收贷项发票引用应收贷项发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORIN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.3应收贷项发票引用应收发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OINV" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
			) T0
		) T1 ON 1=1
	;
	
	
	--12.采购跨月做单
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 12,'采购跨月做单',T1."Result"
	,CASE WHEN T1."Result"=0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(SELECT COUNT(1) AS "Result" FROM
			(
				SELECT DISTINCT '20.1收货引用收货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PDN1" T1
				JOIN "OPDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '20.2收货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PDN1" T1
				JOIN "OPDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '18.1应付发票引用收货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PCH1" T1
				JOIN "OPCH" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '18.2应付发票引用发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PCH1" T1
				JOIN "OPCH" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '21.1采购退货引用收货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPD1" T1
				JOIN "ORPD" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '21.2采购退货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPD1" T1
				JOIN "ORPD" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPD" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.1应付贷项发票引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPD" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.2应付贷项发票引用应付贷项发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPC" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.3应付贷项发票引用应付发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
			) T0
		) T1 ON 1=1
	;
	
	--13.生产订单，已关单，不能出入库
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 13,'生产订单(订单类型=202正常生产订单)的已在上月关单，但是本月仍有出入库',T1."Result"
	,CASE WHEN T1."Result"=0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(
			SELECT COUNT(1) AS "Result" 
			FROM ( 
				SELECT T0."Type",T0."ObjType",T0."OWOREntry",T0."OWORNum",T0."DocEntry",T0."DocNum"
				,T0."DocDate",T1."CloseDate",T0."ItemCode",T0."WhsCode",T0."Quantity"
				FROM "MTC_VIEW_ProductDetail" T0
				INNER JOIN "OWOR" T1 ON T0."OWOREntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode
				AND T1."Status"='L'
				AND LEFT(T1."CloseDate",7)<LEFT("DocDate",7)
				) P0
		) T1 ON 1=1;
		
	--14.生产订单，已关单，不能出入库
	INSERT INTO #LIST("RptCode","RptName","DocEntry","Result")
	SELECT 14,'生产订单(订单类型=MTC_OWOR返工单)的已在上月关单，但是本月仍有出入库',T1."Result"
	,CASE WHEN T1."Result"=0 THEN 'Y' ELSE 'N' END
	FROM DUMMY T0
	LEFT JOIN
		(
			SELECT COUNT(1) AS "Result" 
			FROM ( 
				SELECT T0."Type",T0."TransType",T0."BaseEntry",T0."CreatedBy",T0."BASE_REF"
				,T0."DocDate",T1."U_CloseDate",T0."ItemCode",T0."Quantity"
				FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
				INNER JOIN "@MTC_OWOR" T1 ON T0."BaseEntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode
				AND T1."U_Status"='L'
				AND LEFT(T1."U_CloseDate",7)<LEFT("DocDate",7)
				) P0
		) T1 ON 1=1;
	
	SELECT :FcCode AS "FcCode","RptCode","RptName","DocEntry","Result" FROM #LIST;
	
	DROP TABLE #LIST; 
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1001_CHECK_01
CREATE PROCEDURE "MTC_COST_PROC_CAL_1001_CHECK_01"(
 IN DocEntry INT
)
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	DECLARE FcCode NVARCHAR(30);
	DECLARE LastFcCode NVARCHAR(30);
	SELECT "U_FcCode" INTO FcCode FROM "@MTC_COST_QCPRICE" WHERE "DocEntry"=:DocEntry;
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	
	
  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
  		RETURN;
  	END IF;
	
	--更新期初单价，把入库单价更新进入
	--上期库存+本期入库
	Onhand_SUM=
	SELECT "ItemCode",SUM("Amount") AS "Amount",SUM("Qty") AS "Qty",SUM("Amount")/NULLIF(SUM("Qty"),0) AS "Price"
	FROM (
			SELECT "ItemCode","QM_Amount" AS "Amount","QM_Qty" AS "Qty" FROM MTC_COST_0301_INVNT T0
			WHERE T0."FcCode"=:LastFcCode AND "CostCode"='20'
			--当期入库
			UNION ALL
			SELECT "ItemCode","Amount","Quantity" FROM MTC_COST_0302_INVNTDETAIL1
			WHERE 1=1
			--AND "ObjType" IN ('20','21','18','19') 
			AND "ObjType" IN ('20','59') 
			AND "FcCode"=:FcCode
		) T0
	--WHERE T0."ItemCode"='102002076'
	GROUP BY "ItemCode"	
	;
	
	TMP=
	SELECT T2."DocEntry" AS "单号",T2."U_ItemCode" AS "物料编码",T2."U_ItemName" AS "物料名称"
	,T2."U_Price" AS "更改前单价"
	,T1."Price" AS "更改后单价"
	FROM :Onhand_SUM T1
	JOIN "@MTC_COST_QCPRICE1" T2 ON T1."ItemCode"=T2."U_ItemCode"
	WHERE T2."DocEntry"=:DocEntry
	and IFNULL(T2."U_Price",0)=0
	AND IFNULL(T1."Price",0)<>0
	;
	
	
	UPDATE T2 SET T2."U_Price"=T1."Price"
	,T2."U_LineMemo"='关联入库单价更新，原单价为'||T2."U_Price"
	FROM :Onhand_SUM T1
	JOIN "@MTC_COST_QCPRICE1" T2 ON T1."ItemCode"=T2."U_ItemCode"
	WHERE T2."DocEntry"=:DocEntry
	and IFNULL(T2."U_Price",0)=0
	AND IFNULL(T1."Price",0)<>0
	;
	
	
	SELECT '更改成功!' AS "Message",* FROM :TMP T0
	ORDER BY T0."物料编码";
	
	
	/*
	--还需要对出入库处理
	--TMP_SUM=
	SELECT T0."ItemCode",SUM("Quantity") AS "Quantity",T1."Price"
	,LEFT(STRING_AGG(T2."Name",','),250) AS "IOName"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN :Onhand_SUM T1 ON T0."ItemCode"=T1."ItemCode"
	LEFT JOIN "@MTC_COST_IOTYPE" T2 ON T0."TransCode"=T2."Code"
	WHERE T0."TransCode" IN ('I03','I04','O04','I05','O06','I10','I07','I08')
	AND T0."FcCode"='2025-10'
	AND T0."ItemCode"='102002076'
	--AND T0."Quantity">0 --入库
	GROUP BY T0."ItemCode",T1."Price";*/
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1001_CHECK_DETAIL
CREATE PROCEDURE "MTC_COST_PROC_CAL_1001_CHECK_DETAIL"(IN FcCode NVARCHAR(10),IN DocType NVARCHAR(30))
LANGUAGE SQLSCRIPT
AS
BEGIN
	
	--成本检查的明细表
	--6.6.报废仓的库存应该为0

	IF :DocType='4' THEN
		SELECT DISTINCT T0."ObjType",'发货单' AS "单据类型名称",T0."DocEntry" AS "单号Entry",T0."DocNum" AS "单号Num",T0."DocDate" AS "过账日期"
		FROM "OIGE" T0
		JOIN "IGE1" T1 ON T0."DocEntry"=T1."DocEntry"
		JOIN OWOR T2 ON T1."BaseType"='202' AND T1."BaseEntry"=T2."DocEntry"
		WHERE LEFT(T0."DocDate",7)=:FcCode 
		AND T2."U_OrdType"='40'
		AND T0."U_TrsName" NOT IN ('307','305')
		UNION ALL
		SELECT DISTINCT T0."ObjType",'发货单' AS "单据类型名称",T0."DocEntry" AS "单号Entry",T0."DocNum" AS "单号Num",T0."DocDate" AS "过账日期"
		FROM "OIGN" T0
		JOIN "IGN1" T1 ON T0."DocEntry"=T1."DocEntry"
		JOIN OWOR T2 ON T1."BaseType"='202' AND T1."BaseEntry"=T2."DocEntry"
		WHERE LEFT(T0."DocDate",7)=:FcCode 
		AND T2."U_OrdType"='40'
		AND T0."U_TrsName" NOT IN ('307','305');
	
	ELSEIF :DocType='6' THEN
		SELECT T0."ItemCode" AS "物料编码",T1."ItemName" AS "物料名称"
		,SUM(T0."InQty"-T0."OutQty") AS "库存"
		,T0."LocCode" AS "仓库"
		FROM OIVL T0 
		JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
		WHERE TO_CHAR(T0."DocDate",'YYYY-MM')<=:FcCode 
		AND T0."LocCode"='S300'
		GROUP BY T0."ItemCode",T1."ItemName",T0."LocCode"
		HAVING SUM(T0."InQty"-T0."OutQty")<>0;
	
	--7.检查截至到当月尚未关单的
	ELSEIF :DocType='7' THEN
		SELECT '生产工单202' AS "生产订单类型",T1."DocEntry" AS "内部单号",T1."DocNum" AS "订单号Num"
		,T1."U_SupNum" AS "生产订单补充代码"
		,T1."ItemCode" AS "主件编码",T1."ProdName" AS "主件名称"
		,CASE T1."Status" WHEN 'P' THEN '计划' WHEN 'R' THEN '已审批' END AS "订单状态" 
		,T1."PlannedQty" AS "计划数量",T0."WorQty" AS "实际入库数量",T0."DocDate" AS "最后入库日期"
		FROM (
			SELECT T0."OWORNum",SUM(T0."Quantity") AS "WorQty",MAX("DocDate") AS "DocDate"
			FROM "MTC_VIEW_ProductDetail" T0
			LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
			LEFT JOIN "OITB" T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
			WHERE 1=1
			--AND T0."OWORNum"=39517
			AND T0."Type"='主件'
			AND LEFT(T0."DocDate",7)<=:FcCode
			GROUP BY T0."OWORNum"
			) T0
		JOIN "OWOR" T1 ON T0."OWORNum"=T1."DocNum"
		WHERE T1."Status" IN ('P','R')
		AND T1."PlannedQty"-IFNULL(T0."WorQty",0)<=0 --实际完工数量大于等于计划数量
	
		UNION ALL
		SELECT '返工单MTC_OWOR' AS "WorType",T1."DocEntry",T1."DocNum"
		,T1."U_SupNum" AS "生产订单补充代码"
		,T1."U_ItemCode",T1."U_ProdName"
		,CASE T1."U_Status" WHEN 'P' THEN '计划' WHEN 'R' THEN '已审批' END AS "订单状态" 
		,T1."U_PlannedQty",T0."WorQty",T0."DocDate"
		FROM (
			SELECT T0."BaseEntry" AS "OWORNum",SUM(T0."Quantity") AS "WorQty",MAX("DocDate") AS "DocDate"
			FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
			LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
			LEFT JOIN "OITB" T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
			WHERE 1=1
			--AND T0."OWORNum"=39517
			AND T0."Type"='主件'
			AND LEFT(T0."DocDate",7)<=:FcCode
			GROUP BY T0."BaseEntry"
			) T0
		JOIN "@MTC_OWOR" T1 ON T0."OWORNum"=T1."DocNum"
		WHERE T1."U_Status" IN ('P','R')
		AND T1."U_PlannedQty"-IFNULL(T0."WorQty",0)<=0 --实际完工数量大于等于计划数量
		;
	ELSEIF :DocType = '9' THEN
				SELECT '生产订单',A."OWORNum",A."OWOREntry",A."Main_DocDate" AS "入库日期",A."Detail_DocDate" AS "领料日期"
				FROM (
					SELECT
					T0."OWORNum",T0."OWOREntry",T1."PlannedQty",T1."CmpltQty"
					,MAX(CASE WHEN T0."Type"='主件' THEN "DocDate" ELSE NULL END) AS "Main_DocDate"
					,MAX(CASE WHEN T0."Type"='子件' THEN "DocDate" ELSE NULL END) AS "Detail_DocDate"
					FROM "MTC_VIEW_ProductDetail" T0
					LEFT JOIN OWOR T1 ON T0."OWORNum"=T1."DocNum"
					WHERE 1=1 AND IFNULL(T1."PlannedQty",0)-IFNULL(T1."CmpltQty",0)<=0
					GROUP BY T0."OWORNum",T0."OWOREntry",T1."PlannedQty",T1."CmpltQty"
				) A 
				WHERE TO_CHAR(A."Main_DocDate",'YYYY-MM')<TO_CHAR(A."Detail_DocDate",'YYYY-MM')
				AND TO_CHAR(A."Main_DocDate",'YYYY-MM')<=:FcCode --当月入库
				AND TO_CHAR(A."Detail_DocDate",'YYYY-MM')>:FcCode --次月领料
				
				UNION ALL
				SELECT '返工单',A."BaseEntry",A."BaseLine",A."Main_DocDate" AS "入库日期",A."Detail_DocDate" AS "领料日期"
				FROM (
					SELECT
					T0."BaseEntry",T0."BaseLine"
					,MAX(CASE WHEN T0."Type"='主件' THEN "DocDate" ELSE NULL END) AS "Main_DocDate"
					,MAX(CASE WHEN T0."Type"='子件' THEN "DocDate" ELSE NULL END) AS "Detail_DocDate"
					FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
					GROUP BY T0."BaseType",T0."BaseEntry",T0."BaseLine"
				) A 
				WHERE TO_CHAR(A."Main_DocDate",'YYYY-MM')<TO_CHAR(A."Detail_DocDate",'YYYY-MM')
				AND TO_CHAR(A."Main_DocDate",'YYYY-MM')<=:FcCode --当月入库
				AND TO_CHAR(A."Detail_DocDate",'YYYY-MM')>:FcCode --次月领料
				;
	ELSEIF :DocType='11' THEN
		SELECT DISTINCT '15.1交货引用交货跨月' AS "类型",T0."DocDate" AS "目标单据日期",T2."DocDate" AS "引用源单日期"
				,T0."ObjType" AS "单据类型编码",T0."DocNum" AS "单号Num"
				FROM "DLN1" T1
				JOIN "ODLN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '15.2交货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "DLN1" T1
				JOIN "ODLN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '13.1应收发票引用交货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "INV1" T1
				JOIN "OINV" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '13.2应收发票引用发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "INV1" T1
				JOIN "OINV" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OINV" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '16.1销售退货引用交货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RDN1" T1
				JOIN "ORDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ODLN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '16.2销售退货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RDN1" T1
				JOIN "ORDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.1应收贷项发票引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.2应收贷项发票引用应收贷项发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORIN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '14.3应收贷项发票引用应收发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RIN1" T1
				JOIN "ORIN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OINV" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode;
	
	ELSEIF :DocType='12' THEN
		SELECT DISTINCT '20.1收货引用收货跨月' AS "类型",T0."DocDate" AS "目标单据日期",T2."DocDate" AS "引用源单日期",T0."ObjType" AS "单据类型编码",T0."DocNum" AS "单号Num"
				FROM "PDN1" T1
				JOIN "OPDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '20.2收货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PDN1" T1
				JOIN "OPDN" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '18.1应付发票引用收货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PCH1" T1
				JOIN "OPCH" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '18.2应付发票引用发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "PCH1" T1
				JOIN "OPCH" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '21.1采购退货引用收货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPD1" T1
				JOIN "ORPD" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPDN" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '21.2采购退货引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPD1" T1
				JOIN "ORPD" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPD" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.1应付贷项发票引用退货跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPD" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.2应付贷项发票引用应付贷项发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "ORPC" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode
				UNION ALL
				SELECT DISTINCT '19.3应付贷项发票引用应付发票跨月' AS "Type",T0."DocDate",T2."DocDate" AS "BaseDate",T0."ObjType",T0."DocNum"
				FROM "RPC1" T1
				JOIN "ORPC" T0 ON T0."DocEntry"=T1."DocEntry"	--本单
				JOIN "OPCH" T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry"	--引用原单
				WHERE 1=1 AND TO_CHAR(T0."DocDate",'YYYY-MM')>:FcCode
				AND TO_CHAR(T2."DocDate",'YYYY-MM')<=:FcCode;
	ELSEIF :DocType='13' THEN
		SELECT T0."Type"
				,CASE WHEN T0."ObjType"='59' THEN '其他收货单' WHEN T0."ObjType"='60' THEN '其他发货单' END AS "单据类型"
				,T0."OWOREntry",T0."OWORNum" AS "订单号Num",T0."DocEntry" AS "单号Entry",T0."DocNum" AS "单号Num"
				,T0."DocDate",T1."CloseDate",T0."ItemCode",T0."WhsCode",T0."Quantity"
				FROM "MTC_VIEW_ProductDetail" T0
				INNER JOIN "OWOR" T1 ON T0."OWOREntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode
				AND T1."Status"='L'
				AND LEFT(T1."CloseDate",7)<LEFT("DocDate",7);	
	ELSEIF :DocType='14' THEN
		SELECT T0."Type"
				,CASE WHEN T0."TransType"='59' THEN '其他收货单' WHEN T0."TransType"='60' THEN '其他发货单' END AS "单据类型"
				,T0."BaseEntry" AS "工单单号Num",T0."CreatedBy" AS "单号Entry",T0."BASE_REF" AS "单号Num"
				,T0."DocDate",T1."U_CloseDate",T0."ItemCode",T0."Quantity"
				FROM "MTC_VIEW_ProductDetail_MTCOWOR" T0
				INNER JOIN "@MTC_OWOR" T1 ON T0."BaseEntry"=T1."DocEntry"
				WHERE LEFT(T0."DocDate",7)=:FcCode
				AND T1."U_Status"='L'
				AND LEFT(T1."U_CloseDate",7)<LEFT("DocDate",7);
	END IF;


END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1004_CHECK
CREATE PROCEDURE "MTC_COST_PROC_CAL_1004_CHECK"(IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50),IN IsInsert NVARCHAR(30) DEFAULT 'N')
LANGUAGE SQLSCRIPT
AS
BEGIN

	SELECT T0."FcCode" AS "期间"
	,T0."DocType" AS "生产订单类型"
	,T0."WorType" AS "工单类型"
	,T0."WorEntry" AS "订单号Entry"
	,T0."WorNum" AS "订单号Num"
	,T0."LineNum" AS "行号"
	,T0."ItemCode" AS "材料编码"
	,T0."ItemName" AS "材料名称"
	,T0."IgeQty" AS "工单领料数量"
	,T0."Amount" AS "工单领料金额"
	,T1."IgeQty" AS "实际领料数量"
	,T1."IgeAmt" AS "实际领料金额"
	,IFNULL(T0."IgeQty",0)-IFNULL(T1."IgeQty",0) AS "数量差异"
	,IFNULL(T0."Amount",0)-IFNULL(T1."IgeAmt",0) AS "金额差异"
	FROM 
		(
		SELECT "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName","LineNum"
		,-1*SUM("IgeQty") AS "IgeQty",-1*SUM("Amount") AS "Amount"
		FROM "MTC_COST_0321_OWOR1"
		WHERE 1=1
		AND "FcCode"<=:FcCode
		--AND "WorEntry"=71907
		GROUP BY "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName","LineNum"
		) T0
	LEFT JOIN (
		SELECT "FcCode","BaseType","BaseEntry","BaseLine"
		,-1*SUM(CASE WHEN "TransCode" IN ('O03','O07','O08','O09') THEN "Quantity" ELSE 0 END) AS "IgeQty"
		,-1*SUM(CASE WHEN "TransCode" IN ('O03','O07','O08','O09') THEN "Amount" ELSE 0 END) AS "IgeAmt"
		,SUM(CASE WHEN "TransCode" IN ('I03','I07','I08','I09') THEN "Amount" ELSE 0 END) AS "IgnAmt"
		FROM "MTC_COST_0302_INVNTDETAIL1"
		WHERE 1=1
		AND "FcCode"<=:FcCode
		--AND "BaseEntry"=71907
		GROUP BY "FcCode","BaseType","BaseEntry","BaseLine"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."BaseType" AND T0."WorEntry"=T1."BaseEntry" AND T0."LineNum"=T1."BaseLine"
	WHERE T0."FcCode"=:FcCode
	AND T0."WorType"<>'40'
	AND (IFNULL(T0."IgeQty",0)-IFNULL(T1."IgeQty",0)<>0 OR IFNULL(T0."Amount",0)-IFNULL(T1."IgeAmt",0)<>0)
	;
		
END;

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1004_CHECK_LS
CREATE PROCEDURE "MTC_COST_PROC_CAL_1004_CHECK_LS"(IN FcCode NVARCHAR(10),IN UserCode NVARCHAR(50),IN IsInsert NVARCHAR(30) DEFAULT 'N')
LANGUAGE SQLSCRIPT
AS
BEGIN

	SELECT T0."FcCode" AS "期间"
	,T0."DocType" AS "生产订单类型"
	,T0."WorType" AS "工单类型"
	,T0."WorEntry" AS "订单号Entry"
	,T0."WorNum" AS "订单号Num"
	,T0."ItemCode" AS "物料编码"
	,T0."ItemName" AS "物料名称"
	,T0."IgnQty" AS "工单入库数量"
	,T0."Amount" AS "成本合计"
	,T0."1Material" AS "工单原材料金额"
	,T0."2ManExp" AS "工单人工费用"
	,T0."3LabAmount" AS "工单制造费用"
	,T0."4WWExp" AS "工单委外费用"
	,T1."IgnAmt" AS "实际入库金额明细"
	,IFNULL(T0."Amount",0)-IFNULL(T1."IgnAmt",0) AS "入库差异"
	,T1."IgeAmt" AS "实际发料金额明细"
	,IFNULL(T0."1Material",0)-IFNULL(T1."IgeAmt",0) AS "发料差异"
	FROM 
		(
		SELECT "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName"
		,SUM("IgnQty") AS "IgnQty",SUM("Amount") AS "Amount"
		,SUM("1Material") AS "1Material",SUM("2ManExp") AS "2ManExp",SUM("3LabAmount") AS "3LabAmount",SUM("4WWExp") AS "4WWExp"
		FROM "MTC_COST_0321_OWOR"
		WHERE 1=1
		AND "FcCode"<=:FcCode
		--AND "WorEntry"=49432
		GROUP BY "FcCode","DocType","WorType","WorEntry","WorNum","ItemCode","ItemName"
		) T0
	LEFT JOIN (
		SELECT "FcCode","BaseType","BaseEntry"
		,-1*SUM(CASE WHEN "TransCode" IN ('O03','O07','O08','O09') THEN "Amount" ELSE 0 END) AS "IgeAmt"
		,SUM(CASE WHEN "TransCode" IN ('I03','I07','I08','I09') THEN "Amount" ELSE 0 END) AS "IgnAmt"
		FROM "MTC_COST_0302_INVNTDETAIL1"
		WHERE 1=1
		AND "FcCode"<=:FcCode
		--AND "BaseEntry"=49432
		GROUP BY "FcCode","BaseType","BaseEntry"
		) T1 ON T0."FcCode"=T1."FcCode" AND T0."DocType"=T1."BaseType" AND T0."WorEntry"=T1."BaseEntry"
	WHERE T0."FcCode"=:FcCode
	AND T0."WorType"<>'40'
	AND ( IFNULL(T0."1Material",0)-IFNULL(T1."IgeAmt",0)<>0)
	;
		
END;

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_CAL_1005
CREATE PROCEDURE "MTC_COST_PROC_CAL_1005"(IN FcCode NVARCHAR(10))
LANGUAGE SQLSCRIPT
AS
BEGIN
		--CALL "MTC_COST_PROC_CAL_1005"('2026-04')
		TMP_LIST=
		SELECT T0."AcctCode",T0."AcctName"
		,T0."TransCode",T0."TrnsCodDsc"
		,SUM(T0."OJDTFSAmt") AS "OJDTFSAmt"
		,SUM(T0."JZAmount") AS "JZAmount"
		,SUM(T0."InvntFSAmt") AS "InvntFSAmt"
		,SUM(IFNULL(T0."OJDTFSAmt",0)+IFNULL(T0."JZAmount",0)-IFNULL(T0."InvntFSAmt",0)) AS "差异金额"
		FROM
		(
			SELECT T2."AcctCode",T2."AcctName"
			,CASE WHEN LEFT(T0."TransCode",3)='PUR' OR T0."TransType" IN (20,21,18,19) THEN 'PUR' ELSE T0."TransCode" END AS "TransCode"
			,CASE WHEN LEFT(T0."TransCode",3)='PUR' OR T0."TransType" IN (20,21,18,19) THEN '采购暂估' ELSE T3."TrnsCodDsc" END AS "TrnsCodDsc"
			,SUM(T1."Debit"-T1."Credit") AS "OJDTFSAmt"
			,0 AS "JZAmount"
			,0 AS "InvntFSAmt"
			FROM "OJDT" T0
			JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
			LEFT JOIN "OTRC" T3 ON T0."TransCode"=T3."TrnsCode"
			LEFT JOIN "MTC_DocType" T7 ON T0."TransType" = T7."ObjType"
			WHERE 1=1
			AND (TO_CHAR(T0."RefDate",'YYYY-MM') = :FcCode)
			AND LEFT(T2."AcctCode",4) IN ('1403','1404','1405','1406','1408','1409')
			AND LEFT(T2."AcctCode",6)<>'140801'
			GROUP BY T2."AcctCode",T2."AcctName"
			,CASE WHEN LEFT(T0."TransCode",3)='PUR' OR T0."TransType" IN (20,21,18,19) THEN 'PUR' ELSE T0."TransCode" END
			,CASE WHEN LEFT(T0."TransCode",3)='PUR' OR T0."TransType" IN (20,21,18,19) THEN '采购暂估' ELSE T3."TrnsCodDsc" END
			
			UNION ALL
			SELECT "AcctCode","AcctName",T0."TransCode",T6."TrnsCodDsc"
			,0
			,SUM("Debit"-"Credit") AS "JZAmount"
			,0
			FROM MTC_COST_0801_TOOJDT T0
			LEFT JOIN "OTRC" T6 ON T0."TransCode"=T6."TrnsCode"
			WHERE "FcCode"=:FcCode
			AND LEFT(T0."AcctCode",4) IN ('1403','1404','1405','1406','1408','1409')
			AND LEFT(T0."AcctCode",6)<>'140801'
			GROUP BY "AcctCode","AcctName",T0."TransCode",T6."TrnsCodDsc"
			
			UNION ALL
			SELECT 
				T3."StockAct"			"存货科目"
				,T5."AcctName"			"存货科目名称"
				,CASE WHEN LEFT(T4."U_TransCode",3)='PUR' THEN 'PUR' ELSE T6."TrnsCode" END AS			"交易代码"
				,CASE WHEN LEFT(T4."U_TransCode",3)='PUR' THEN '采购暂估' ELSE T6."TrnsCodDsc" END AS			"交易名称"
				,0.00
				,0.00
				,ROUND(SUM(T1."Amount"),2) 		"InvntFSAmt"
			FROM MTC_COST_0302_INVNTDETAIL1 T1
			LEFT JOIN OITM T2 ON T1."ItemCode"=T2."ItemCode"
			LEFT JOIN (
						SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" 
						FROm OGAR 
						WHERE "PeriodCat"=LEFT(:FcCode,4) 
						GROUP BY "ItmsGrpCod"
						) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN "@MTC_COST_IOTYPE" T4 ON T1."TransCode"=T4."Code"
			LEFT JOIN OACT T5 ON T5."AcctCode"=T3."StockAct"
			LEFT JOIN "OTRC" T6 ON T4."U_TransCode"=T6."TrnsCode"
			WHERE 1=1
			AND T1."FcCode"=:FcCode
			AND LEFT(T5."AcctCode",4) IN ('1403','1404','1405','1406','1408','1409')
			AND LEFT(T5."AcctCode",6)<>'140801'
			GROUP BY T3."StockAct",T5."AcctName",CASE WHEN LEFT(T4."U_TransCode",3)='PUR' THEN 'PUR' ELSE T6."TrnsCode" END
			,CASE WHEN LEFT(T4."U_TransCode",3)='PUR' THEN '采购暂估' ELSE T6."TrnsCodDsc" END
			
		) T0
		GROUP BY T0."AcctCode",T0."AcctName"
		,T0."TransCode",T0."TrnsCodDsc"
		ORDER BY T0."AcctCode",T0."TransCode"
		;
		
		SELECT '科目' AS "类型",T0."AcctCode",T0."AcctName" AS "科目名称"
		,T0."TransCode" AS "交易代码",T0."TrnsCodDsc" AS "交易类型"
		,(T0."OJDTFSAmt") AS "分录发生额"
		,(T0."JZAmount") AS "结转分录发生额"
		,(T0."InvntFSAmt") AS "业务发生额"
		,T0."差异金额"
		FROM :TMP_LIST T0
		
		UNION ALL 
		SELECT '合计' AS "类型",T0."AcctCode",T0."AcctName"|| '合计' AS "科目名称"
		,NULL AS "交易代码",NULL AS "交易类型"
		,SUM(T0."OJDTFSAmt") AS "分录发生额"
		,SUM(T0."JZAmount") AS "结转分录发生额"
		,SUM(T0."InvntFSAmt") AS "业务发生额"
		,SUM(IFNULL(T0."OJDTFSAmt",0)+IFNULL(T0."JZAmount",0)-IFNULL(T0."InvntFSAmt",0)) AS "差异金额"
		FROM :TMP_LIST T0 GROUP BY T0."AcctCode",T0."AcctName"
		ORDER BY "AcctCode"
		;
		
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_PROC_FI5009
CREATE PROCEDURE "MTC_COST_PROC_FI5009"
(
  IN sdate date,
  IN edate date,
  IN CardCode NVARCHAR(50),
  IN IsOnlyOpen	NVARCHAR(10) DEFAULT 'N'
)
AS
BEGIN

	SELECT *
	FROM (
	SELECT
	'采购收货单' AS "类型"
	,CASE WHEN T0."CANCELED"='C' THEN '抵销单' WHEN T0."CANCELED"='Y' THEN '已抵销' WHEN T1."LineStatus"='O' THEN '未清' WHEN T1."LineStatus"='C' THEN '已清' END AS "状态"
	,T0."DocNum" AS "收退货Num"
	,T0."U_SupNum" AS "收退货单号"
	,T0."U_OldSysNo" AS "老系统单号"
	,T0."NumAtCard" AS "参考号"
	, T0."DocDate" AS "过账日期"
	, T0."DocCur" AS "币种"
	, T0."DocRate" AS "汇率"
	, T3."Name" AS "单据类型"
	, T0."CardCode" AS "供应商编码"
	, T0."CardName" AS "供应商名称"
	, T1."ItemCode" AS "物料编号"
	, T1."U_ItemCode" AS "料号"
	, T1."Dscription" AS "物料名称"
	, T11."InvntryUom" AS "单位"
	, T1."U_Specs" AS "规格"
	, T7."BatchNumber" AS "批次"
	, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "数量"
	, T1."Price" AS "未税单价"
	, T1."PriceAfVAT" AS "含税单价"
	, CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."LineTotal" AS "未税金额（本币）"
	, CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END * T1."GTotal"  AS "含税金额（本币）"
	, T1."U_InitPrice" AS "初始单价(未税)"
	,  CAST(CAST(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END
		*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "暂估单价"
	,CASE WHEN T0."CANCELED"='C' THEN -1 ELSE 1 END *
	    CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *
		ROUND(CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice" 
				 WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
				 ELSE T1."LineTotal" END,2) AS "计入暂估"
	, CASE when T1."LineStatus"='O' then N'未清' when T1."LineStatus"='C' then N'已清'  END  AS "行状态"
	, T4."DocDate" AS "发票日期"
	, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T4."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "已开票数量"
	, T4."OPCHPrice" AS "已开票未税单价"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T4."LineTotal" AS "已开票未税金额(本币)"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T4."GTotal" AS "已开票含税金额(本币)"
	, T21."DocDate" AS "退货日期"
	, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T21."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "已退货数量"
	, T21."ORPDPrice" AS "已退货未税单价"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T21."LineTotal" AS "已退货未税金额(本币)"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END * T21."GTotal" AS "已退货含税金额(本币)"
	, T2."CanceledPDNQty" AS "取消数量"
	, CAST(CAST(
	    	CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END* --排除虚拟物料
			CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END *
			CASE WHEN T0."DocStatus"='C' AND T1."TargetType"=-1 THEN 0 ELSE 1 END *
			CASE WHEN T1."BaseType"='21' THEN 0 ELSE 1 END * T1."Quantity"
			-IFNULL(T4."Quantity",0)
			-IFNULL(T21."Quantity",0)
			-IFNULL(T2."CanceledPDNQty",0) AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "暂估剩余数量"
	,CASE WHEN (T1."Quantity"-IFNULL(T4."Quantity",0)-IFNULL(T21."Quantity",0)-IFNULL(T2."CanceledPDNQty",0))=0 THEN 0 ELSE 1 END
	*CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END
	*CASE WHEN T1."BaseType"='21' THEN 0 ELSE 1 END 
	*CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END --排除虚拟物料
	*CASE when IFNULL(T1."U_InitPrice",0)<>0 
		THEN ROUND((T1."Quantity"-IFNULL(T4."Quantity",0)-IFNULL(T21."Quantity",0)-IFNULL(T2."CanceledPDNQty",0))*T1."U_InitPrice",2)
		ELSE T1."LineTotal"-IFNULL(T4."LineTotal",0)-IFNULL(T21."LineTotal",0)-IFNULL(T2."CanceledPDNAmt",0)
		END AS "暂估剩余金额"
	, ROUND(CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END*CASE WHEN T1."BaseType"='21' THEN 0 ELSE 1 END 
	*(T1."Quantity"-IFNULL(T4."Quantity",0)-IFNULL(T21."Quantity",0)-IFNULL(T2."CanceledPDNQty",0))
	  *CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END --排除虚拟物料
		*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END
		   ,2) AS "暂估剩余金额(老)"
	--当月剩余金额：采购收货金额 - 抵销单的金额 - 采购退货金额 - 应付发票金额 （如果是收货单是抵销单C，则为0）
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END *
		CASE WHEN T1."BaseType"='21' THEN 0 ELSE 1 END *
	    CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *
		ROUND(CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice" 
				 WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
				 ELSE T1."LineTotal" END,2)
	   - IFNULL(T2."CanceledPDNAmt",0)	--抵销单的金额
	   - IFNULL(T21."RPDAmt",0)			--采购退货金额
	   - IFNULL(T4."LineTotal",0)		--应付发票
	  AS "当月剩余金额"
	, T0."TransId" AS "交易编码"
	, T1."AcctCode" AS "收入科目" 
	, T0."ObjType"  
	, T0."DocEntry"
	, T9."DocNum"  AS "采购订单号Num"
	, T9."U_SupNum"  AS "采购订单号"
	, T12."DocNum"  AS "采购申请单号Num"
	, T12."U_SupNum"  AS "采购申请单号" 
	,T8."Project" AS "项目"
	,T22."OcrName"  AS "部门" 
	, T4."U_CWNum" AS "财务凭证号"
	, T14."U_SupNum" AS "生产收/退货单号"  
	, T1."BaseType"
	,T1."BaseEntry"
	,T1."BaseLine"
	,T91."ItmsGrpNam"
	FROM OPDN T0  
	INNER JOIN PDN1 T1 ON T0."DocEntry" = T1."DocEntry" 
	LEFT JOIN (SELECT T1."BaseType",T1."BaseEntry",T1."BaseLine"
				,SUM(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity") AS "CanceledPDNQty"
				,SUM(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*
					CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END *
					ROUND(CASE WHEN IFNULL(T2."U_InitPrice",0)<>0 THEN T2."Quantity"*T2."U_InitPrice" 
							 WHEN T2."U_IsPrice"='Y' THEN T2."Quantity"*T2."Price"
							 ELSE T2."LineTotal" END,2)) AS "CanceledPDNAmt"	--抵销单的暂估金额
				FROM "OPDN" T0 JOIN PDN1 T1 ON T0."DocEntry"=T1."DocEntry"
				JOIN PDN1 T2 ON T1."BaseType"=T2."ObjType" AND T1."BaseEntry"=T2."DocEntry" AND T1."BaseLine"=T2."LineNum"	--原单
				JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
				WHERE T0."DocDate"<=:edate
				GROUP BY T1."BaseType",T1."BaseEntry",T1."BaseLine"
			) T2 ON T0."ObjType"=T2."BaseType" AND T0."DocEntry"=T2."BaseEntry" AND T1."LineNum"=T2."BaseLine"
--LEFT JOIN "MTC_VIEW_CUFD" T2 ON T2."TableID"='OPDN' AND T2."AliasID"='XSDDFL' AND T2."FldValue"=T0."U_XSDDFL"
	LEFT JOIN "@U_CIOTRN" T3 ON T0."U_TrsName"=T3."Code"
	LEFT JOIN (
				SELECT STRING_AGG(TO_CHAR(T0."DocDate",'YYYY.MM.DD'),',') AS "DocDate"
				,STRING_AGG(CAST(CAST(T1."Price" AS DECIMAL(19,6)) AS NVARCHAR(30)),',') AS "OPCHPrice",STRING_AGG(T2."U_CWNum",',') AS "U_CWNum"
				,T1."BaseEntry",T1."BaseLine",SUM(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END*T1."Quantity") AS "Quantity"
				,SUM(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END*T1."LineTotal") AS "LineTotal",SUM(T1."GTotal") AS "GTotal",SUM(T1."GTotalFC") AS "GTotalFC"
				FROM "OPCH" T0
				LEFT JOIN "PCH1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OJDT T2 ON T2."TransId"=T0."TransId"
				JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
				WHERE T0."CANCELED"='N'
				AND T0."DocDate"<=:edate
				GROUP BY T1."BaseEntry",T1."BaseLine"
			) T4 ON T4."BaseEntry"=T1."DocEntry" AND T4."BaseLine"=T1."LineNum"
	LEFT JOIN "OCRD" T5 ON T0."CardCode"=T5."CardCode"
	LEFT JOIN 
	(
			 SELECT "ObjType","DocEntry","LineNum","WhsCode" ,STRING_AGG("BatchNumber",',') AS "BatchNumber"
	         FROM "MTC_VW_DOCLINE"
	         GROUP BY "ObjType","DocEntry","LineNum","WhsCode"
	)T7 ON T7."ObjType"=T1."ObjType" and T7."DocEntry"=T1."DocEntry"  AND T7."LineNum"=T1."LineNum" and T7."WhsCode"=T1."WhsCode"
	LEFT JOIN "POR1" T8 ON T1."BaseEntry" =T8."DocEntry" AND T1."BaseLine" =T8."LineNum" 
	LEFT JOIN "OPOR" T9 ON T8."DocEntry" =T9."DocEntry" 
	LEFT JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
	LEFT JOIN OITB T91 ON T11."ItmsGrpCod"=T91."ItmsGrpCod"
	LEFT JOIN OPRQ T12 ON T12."DocEntry" =T8."BaseEntry"  
	LEFT JOIN OIGN T14 ON T14."DocEntry" =T1."U_BaseEntry" AND T1."U_BaseType" ='59' 
	LEFT JOIN (
				SELECT STRING_AGG(TO_CHAR(T0."DocDate",'YYYY.MM.DD'),',') AS "DocDate"
				,STRING_AGG(CAST(CAST(T1."Price" AS DECIMAL(19,6)) AS NVARCHAR(30)),',') AS "ORPDPrice"
				,STRING_AGG(T2."U_CWNum",',') AS "U_CWNum"
				,T1."BaseEntry",T1."BaseLine",SUM(T1."Quantity") AS "Quantity",SUM(T1."LineTotal") AS "LineTotal"
				,SUM(T1."GTotal") AS "GTotal",SUM(T1."GTotalFC") AS "GTotalFC"
				,SUM(CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END *
					ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice"
				 	WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
					ELSE T1."LineTotal" END,2)) AS "RPDAmt"
				FROM "ORPD" T0
				LEFT JOIN "RPD1" T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OJDT T2 ON T2."TransId"=T0."TransId"
				JOIN OITM T21 ON T1."ItemCode"=T21."ItemCode"
				WHERE T0."CANCELED"='N'
				AND T0."DocDate"<=:edate
				GROUP BY T1."BaseEntry",T1."BaseLine"
			) T21 ON T21."BaseEntry"=T1."DocEntry" AND T21."BaseLine"=T1."LineNum"
	LEFT JOIN OOCR T22 ON T22."OcrCode" = T8."OcrCode"  		
	WHERE 1=1 --AND T0."CANCELED"='N'
	AND  (T0."DocDate">=:sdate OR :sdate='17530101')
	AND (T0."DocDate"<=:edate OR :edate='17530101')  
	UNION ALL 
	
	SELECT 
	'采购退货' AS "类型"
	,CASE WHEN T0."CANCELED"='C' THEN '抵销单' WHEN T0."CANCELED"='Y' THEN '已抵销' WHEN T1."LineStatus"='O' THEN '未清' WHEN T1."LineStatus"='C' THEN '已清' END AS "状态"
	,T0."DocNum" AS "收退货Num" /*退货*/ 
	,T0."U_SupNum" AS "收退货单号"
	,T0."U_OldSysNo" AS "老系统单号"
	,T0."NumAtCard" AS "参考号"
	, T0."DocDate" AS "过账日期"
	, T0."DocCur" AS "币种"
	, T0."DocRate" AS "汇率"
	, T3."Name" AS "单据类型"
	, T0."CardCode" AS "供应商编码"
	, T0."CardName" AS "供应商名称"
	, T1."ItemCode" AS "物料编号"
	, T1."U_ItemCode" AS "料号"
	, T1."Dscription" AS "物料名称"
	, T21."InvntryUom" AS "单位"
	, T1."U_Specs" AS "规格"
	, T8."BatchNumber" AS "批次"
	, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "数量"
	, T1."Price" AS "未税单价"
	, T1."PriceAfVAT" AS "含税单价"
	, CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."LineTotal" AS "未税金额（本币）"
	, CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."GTotal"  AS "含税金额（本币）"
	, T1."U_InitPrice" AS "初始单价(未税)"
	, CAST(CAST(CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END
		*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "暂估单价"
	, CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END *
		ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice"
				 WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
				ELSE T1."LineTotal" END,2) AS "计入暂估"
	, CASE when T1."LineStatus"='O' then N'未清' when T1."LineStatus"='C' then N'已清'  END  AS "行状态"
	, T7."DocDate" AS "发票日期"
	, CAST(CAST(CASE WHEN T0."CANCELED"='C' THEN 0 ELSE -1 END*T7."Quantity" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "已开票数量"
	, T7."OPCHPrice" AS "已开票未税单价"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE -1 END*T7."LineTotal" AS "已开票未税金额(本币)"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE -1 END*T7."GTotal" AS "已开票含税金额(本币)"
	, NULL AS "退货日期"
	, CASE WHEN T0."CANCELED"='C' THEN 0 ELSE -1 END*CASE WHEN T1."BaseType"='20' THEN T1."Quantity" ELSE 0 END AS "已退货数量"
	, NULL AS "已开票未税单价"
	, NULL AS "已开票未税金额(本币)"
	, NULL AS "已开票含税金额(本币)"
	, -1*T2."CanceledPDNQty" AS "取消数量"
	, CAST(CAST(CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END* --排除虚拟物料
	      CASE WHEN T1."TargetType"='20' THEN 0 ELSE 1 END*	--目标是收货单
		  CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END*			--抵销单
		  CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END*	--来源是收货单
		  (-1*T1."Quantity"+IFNULL(T7."Quantity",0)+IFNULL(T2."CanceledPDNQty",0)
		) AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "剩余数量"
	
	, CASE WHEN (-1*T1."Quantity"+IFNULL(T7."Quantity",0)+IFNULL(T2."CanceledPDNQty",0))=0 THEN 0 ELSE 1 END
	  *CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END --抵销单
	  *CASE WHEN T1."TargetType"='20' THEN 0 ELSE 1 END --目标是收货单
	  *CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END	--来源是收货单
	  *CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END		--排除虚拟物料
		*CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END
		*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 
		THEN ROUND((-1*T1."Quantity"+IFNULL(T7."Quantity",0)+IFNULL(T2."CanceledPDNQty",0))*T1."U_InitPrice",2)
		ELSE -1*T1."LineTotal"+IFNULL(T7."LineTotal",0)+IFNULL(T2."CanceledPDNAmt",0) 
		END 
		    AS "暂估剩余金额"
	
	,ROUND((-1*T1."Quantity"+IFNULL(T7."Quantity",0)+IFNULL(T2."CanceledPDNQty",0))
	  *CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END --抵销单
	  *CASE WHEN T1."TargetType"='20' THEN 0 ELSE 1 END --目标是收货单
	  *CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END	--来源是收货单
	  *CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END		--排除虚拟物料
		*CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END
		*CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."U_InitPrice" ELSE T1."Price" END
		   ,2) AS "剩余金额（老）"
	--当月剩余金额：-1*采购退货金额 + 抵销单的金额 +  应付贷项发票金额 （如果是收货单是抵销单C，则为0）
	, -1*CASE WHEN T0."CANCELED"='C' THEN 0 ELSE 1 END *
		CASE WHEN T1."TargetType"='20' THEN 0 ELSE 1 END*
		CASE WHEN T1."BaseType"='20' THEN 0 ELSE 1 END* 
	    CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END * --排除虚拟物料
		ROUND(CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice" 
				 WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
				 ELSE T1."LineTotal" END,2) --采购退货金额
	   + IFNULL(T2."CanceledPDNAmt",0)	--抵销单的金额
	   + IFNULL(T7."LineTotal",0)		--应付贷项发票
	  AS "当月剩余金额"
	, T0."TransId" AS "交易编码"
	, T1."AcctCode" AS "收入科目" 
	, T0."ObjType"
	, T0."DocEntry"
	, T11."DocNum"  AS "采购收货单号Num"
	, T11."U_SupNum"  AS "采购收单号"
	, T13."DocNum"  AS "采购申请单号Num"
	, T13."U_SupNum"  AS "采购申请单号" 
	,T12."Project" AS "项目"
	,T16."OcrName"  AS "部门" 
	, T7."U_CWNum" AS "财务凭证号"
	, T15."U_SupNum" AS "生产收/退货单号" 
	, T1."BaseType"
	,T1."BaseEntry"
	,T1."BaseLine"
	,T22."ItmsGrpNam"
	FROM ORPD T0  
	INNER JOIN RPD1 T1 ON T0."DocEntry" = T1."DocEntry" 
	LEFT JOIN (SELECT T1."BaseType",T1."BaseEntry",T1."BaseLine"
				,SUM(CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END *CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*T1."Quantity") AS "CanceledPDNQty"
				,SUM(CASE WHEN T21."ItemCode"='X0510001' OR T21."InvntItem"='Y' THEN 1 ELSE 0 END *
						ROUND(CASE WHEN T0."CANCELED"='C' THEN 1 ELSE -1 END*
						CASE WHEN IFNULL(T1."U_InitPrice",0)<>0 THEN T1."Quantity"*T1."U_InitPrice"
								 WHEN T1."U_IsPrice"='Y' THEN T1."Quantity"*T1."Price"
								ELSE T1."LineTotal" END,2)) AS "CanceledPDNAmt"
				FROM "ORPD" T0 JOIN RPD1 T1 ON T0."DocEntry"=T1."DocEntry"
				JOIN OITM T21 ON T1."ItemCode"=T21."ItemCode"
				WHERE T0."DocDate"<=:edate
				GROUP BY T1."BaseType",T1."BaseEntry",T1."BaseLine"
			) T2 ON T0."ObjType"=T2."BaseType" AND T0."DocEntry"=T2."BaseEntry" AND T1."LineNum"=T2."BaseLine"
--LEFT JOIN "MTC_VIEW_CUFD" T2 ON T2."TableID"='ORDN' AND T2."AliasID"='XSDDFL' AND T2."FldValue"=T0."U_XSDDFL"
	LEFT JOIN "@U_CIOTRN" T3 ON T0."U_TrsName"=T3."Code"
	LEFT JOIN OPRC P1 ON T1."OcrCode"=P1."PrcCode"
	LEFT JOIN "OCRD" T5 ON T0."CardCode"=T5."CardCode"
	LEFT JOIN (
				SELECT STRING_AGG(TO_CHAR(T0."DocDate",'YYYY.MM.DD'),',') AS "DocDate"
				,STRING_AGG(CAST(CAST(T1."Price" AS DECIMAL(19,6)) AS NVARCHAR(30)),',') AS "OPCHPrice",STRING_AGG(T2."U_CWNum",',') AS "U_CWNum"
				,T1."BaseEntry",T1."BaseLine",SUM(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END*T1."Quantity") AS "Quantity"
				,SUM(CASE WHEN T11."ItemCode"='X0510001' OR T11."InvntItem"='Y' THEN 1 ELSE 0 END*T1."LineTotal") AS "LineTotal",SUM(T1."GTotal") AS "GTotal",SUM(T1."GTotalFC") AS "GTotalFC"
				FROM ORPC T0
				LEFT JOIN RPC1 T1 ON T0."DocEntry"=T1."DocEntry"
				LEFT JOIN OJDT T2 ON T2."TransId"=T0."TransId"
				JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
				WHERE T0."CANCELED"='N'
				AND T0."DocDate"<=:edate
				GROUP BY T1."BaseEntry",T1."BaseLine"
			) T7 ON T7."BaseEntry"=T1."DocEntry" AND T7."BaseLine"=T1."LineNum"
	
	LEFT JOIN 
	(
			 SELECT "ObjType","DocEntry","LineNum","WhsCode" ,STRING_AGG("BatchNumber",',') AS "BatchNumber"
	         FROM "MTC_VW_DOCLINE"
	         GROUP BY "ObjType","DocEntry","LineNum","WhsCode"
	) T8 ON T8."ObjType"=T1."ObjType" and T8."DocEntry"=T1."DocEntry"  AND T8."LineNum"=T1."LineNum" and T8."WhsCode"=T1."WhsCode"
	LEFT JOIN "PRR1" T9 ON T1."BaseEntry" =T9."DocEntry" AND T1."BaseLine" =T9."LineNum" 
	LEFT JOIN PDN1 T10 ON T9."BaseEntry" =T10."DocEntry" AND T9."BaseLine" =T10."LineNum"
	LEFT JOIN OPDN T11 ON T10."DocEntry" =T11."DocEntry" 
	LEFT JOIN OITM T21 ON T1."ItemCode"=T21."ItemCode"
	LEFT JOIN OITB T22 ON T21."ItmsGrpCod"=T22."ItmsGrpCod"
	LEFT JOIN PDN1 T14 ON T1."BaseEntry" =T14."DocEntry" AND T1."BaseLine" =T14."LineNum" AND T1."BaseType" ='20'
	LEFT JOIN POR1 T12 ON T14."BaseEntry" =T12."DocEntry" AND T14."BaseLine" =T12."LineNum" AND T14."BaseType" ='22'
	LEFT JOIN OPRQ T13 ON T13."DocEntry" =T12."BaseEntry" 
	LEFT JOIN OIGE T15 ON T15."DocEntry" =T1."U_BaseEntry" AND T1."U_BaseType" ='60'
	LEFT JOIN OOCR T16 ON T16."OcrCode" = T12."OcrCode"  
	WHERE 1=1 --AND T0."CANCELED"='N'
	AND  (T0."DocDate">=:sdate OR :sdate='17530101')
	AND (T0."DocDate"<=:edate OR :edate='17530101')
	) T0
	WHERE  1=1 
	AND (T0."供应商编码" LIKE '%'||:CardCode||'%' OR T0."供应商名称" LIKE '%'||:CardCode||'%' OR :CardCode='')
	AND ((:IsOnlyOpen='Y' AND IFNULL(1.00*T0."暂估剩余数量",'0')<>'0') OR :IsOnlyOpen='N')
	ORDER BY T0."类型",T0."收退货单号";
END

@@
-- @stmt 旧模块 PROCEDURE MTC_COST_ROLLUP_PROC
CREATE PROCEDURE "MTC_COST_ROLLUP_PROC" (
    IN iv_FcCode NVARCHAR(50)  -- 输入：核算期间代码
)
LANGUAGE SQLSCRIPT
SQL SECURITY INVOKER
AS
BEGIN
    -- 临时表：存放递归展开结果
    DECLARE lt_result TABLE (
        "FcCode"        NVARCHAR(50),
        "RootItem"      NVARCHAR(50),
        "RootLevel"     INTEGER,
        "CurrentItem"   NVARCHAR(50),
        "CurrentLevel"  INTEGER,
        "Depth"         INTEGER,
        "Material"      DECIMAL(19,6),
        "ManExp"        DECIMAL(19,6),
        "LabAmount"     DECIMAL(19,6),
        "WWExp"         DECIMAL(19,6)
    );
    
    DECLARE lv_depth INTEGER := 0;
    DECLARE lv_count INTEGER := 1;
    
    -- ========================================
    -- 第一层：所有工单的产出物料（作为根节点）
    -- ========================================
    INSERT INTO :lt_result
    SELECT 
        S."FcCode",
        S."ItemCode"    AS "RootItem",
        S."iLevel"      AS "RootLevel",
        S."ItemCode"    AS "CurrentItem",
        S."iLevel"      AS "CurrentLevel",
        0               AS "Depth",
        0               AS "Material",      -- 顶层材料由下层穿透汇上来
        S."2ManExp"     AS "ManExp",        -- 顶层本身的人工
        S."3LabAmount"  AS "LabAmount",     -- 顶层本身的制造费
        S."4WWExp"      AS "WWExp"          -- 顶层本身的委外费
    FROM "MTC_COST_0321_OWOR_SUM" S
    WHERE S."FcCode" = :iv_FcCode;
    
    -- ========================================
    -- 逐层展开（循环代替递归CTE，更可控）
    -- ========================================
    WHILE :lv_count > 0 AND :lv_depth < 10 DO
        lv_depth := :lv_depth + 1;
        
        INSERT INTO :lt_result
        SELECT 
            R."FcCode",
            R."RootItem",
            R."RootLevel",
            BR."ChildItem"      AS "CurrentItem",
            BR."ChildLevel"     AS "CurrentLevel",
            :lv_depth           AS "Depth",
            -- 材料：只有原材料(iLevel=1)才记录材料金额
            CASE WHEN BR."ChildLevel" = 1 
                 THEN BR."ChildMaterialAmt" 
                 ELSE 0 END     AS "Material",
            -- 人工：非原材料层取其工单的人工费
            CASE WHEN BR."ChildLevel" > 1 
                 THEN COALESCE(CS."2ManExp", 0) 
                 ELSE 0 END     AS "ManExp",
            -- 制造费
            CASE WHEN BR."ChildLevel" > 1 
                 THEN COALESCE(CS."3LabAmount", 0) 
                 ELSE 0 END     AS "LabAmount",
            -- 委外费
            CASE WHEN BR."ChildLevel" > 1 
                 THEN COALESCE(CS."4WWExp", 0) 
                 ELSE 0 END     AS "WWExp"
        FROM :lt_result R
        -- 关联BOM关系：当前物料作为父物料，找其子物料
        INNER JOIN (
            SELECT 
                S."FcCode",
                S."ItemCode"  AS "ParentItem",
                D."ItemCode"  AS "ChildItem",
                D."Amount"    AS "ChildMaterialAmt",
                COALESCE(LV."iLevel", 1) AS "ChildLevel"
            FROM "MTC_COST_0321_OWOR_SUM" S
            INNER JOIN "MTC_COST_0321_OWOR1" D
                ON S."WorEntry" = D."WorEntry"
                AND S."FcCode" = D."FcCode"
            LEFT JOIN "U_COILV" LV
                ON D."ItemCode" = LV."ItemCode"
            WHERE S."FcCode" = :iv_FcCode
        ) BR
            ON R."CurrentItem" = BR."ParentItem"
            AND R."FcCode" = BR."FcCode"
        -- 关联子物料的工单（获取其工费）
        LEFT JOIN "MTC_COST_0321_OWOR_SUM" CS
            ON BR."ChildItem" = CS."ItemCode"
            AND BR."FcCode" = CS."FcCode"
        WHERE R."Depth" = :lv_depth - 1    -- 只展开上一轮新增的记录
          AND R."CurrentLevel" > 1;         -- 原材料不再展开
        
        -- 检查本轮是否有新增（是否还需要继续展开）
        SELECT COUNT(*) INTO lv_count 
        FROM :lt_result 
        WHERE "Depth" = :lv_depth AND "CurrentLevel" > 1;
    END WHILE;
    
    -- ========================================
    -- 最终汇总：按根物料 + 核算期间 汇总
    -- ========================================
    SELECT 
        R."FcCode",
        R."RootItem"            AS "ItemCode",
        MAX(S."ItemName")       AS "ItemName",
        MAX(S."ItmsGrpCod")    AS "ItmsGrpCod",
        R."RootLevel"           AS "iLevel",
        
        -- 料工费卷积结果
        SUM(R."Material")       AS "Material_Rolled",   -- 材料费（穿透到原材料）
        SUM(R."ManExp")         AS "ManExp_Rolled",     -- 人工费（各层累加）
        SUM(R."LabAmount")      AS "LabAmount_Rolled",  -- 制造费（各层累加）
        SUM(R."WWExp")          AS "WWExp_Rolled",      -- 委外费（各层累加）
        SUM(R."Material") + SUM(R."ManExp") 
        + SUM(R."LabAmount") + SUM(R."WWExp") 
                                AS "TotalCost_Rolled",  -- 成本合计
        
        -- 对比原始成本（验证用）
        MAX(S."Amount")         AS "Amount_Original",   -- 原始合计
        MAX(S."1Material")      AS "Material_Original", -- 原始材料费
        MAX(S."2ManExp")        AS "ManExp_Original",   -- 原始人工费
        MAX(S."3LabAmount")     AS "LabAmount_Original",-- 原始制造费
        MAX(S."4WWExp")         AS "WWExp_Original",    -- 原始委外费
        
        -- 差异分析
        SUM(R."Material") + SUM(R."ManExp") 
        + SUM(R."LabAmount") + SUM(R."WWExp") 
        - MAX(S."Amount")       AS "CostDifference"     -- 卷积差异

    FROM :lt_result R
    LEFT JOIN "MTC_COST_0321_OWOR_SUM" S
        ON R."RootItem" = S."ItemCode" 
        AND R."FcCode" = S."FcCode"
    GROUP BY R."FcCode", R."RootItem", R."RootLevel"
    ORDER BY R."RootLevel" DESC, R."RootItem";

END;

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO3001
CREATE PROCEDURE "MTC_RPT_CO3001"
(
  UserId INT,
  FromFcCode NVARCHAR(30),
  ToFcCode NVARCHAR(30),
  ItemCode NVARCHAR(50),
  ItmsGrpCod INT
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	
	IF :FromFcCode <> :ToFcCode THEN
	
		TMP_Detail=
		SELECT :FromFcCode||'~'||:ToFcCode AS "FcCode",
		NULL AS "成本类型",
		T1."ItemCode",
		T1."ItemName" AS "物料名称",
		T1."InvntryUom" AS "单位",
		T0."QC_Qty" AS "期初数量",
		T0."QC_Price" AS "期初单价", 
		T0."QC_Amount" AS "期初金额",
		T0."In_Qty" AS "入库数量",
		T0."In_Price" AS "入库单价",
		T0."In_Amount" AS "入库金额",
		T0."Out_Qty" AS "出库数量",
		T0."Out_Price" AS "出库单价",
		T0."Out_Amount" AS "出库金额",
		T0."QM_Qty" AS "期末数量",
		T0."QM_Price" AS "期末单价",
		ROUND(T0."QM_Amount",2) AS "期末金额",
		T0."Price" AS "单价",
		NULL AS "创建时间",
		NULL AS "创建人",
		NULL AS "计算类型",
		NULL AS "计算级别",
		T2."ItmsGrpCod" AS "物料组编码" ,
		T2."ItmsGrpNam" AS "物料组名称",
		T4."AcctCode" AS "科目编码",
		T4."AcctName" AS "科目名称",
		NULL AS "价格更新来源"
		FROM 
			(SELECT "ItemCode",SUM("QC_Qty") AS "QC_Qty",SUM("QC_Price") AS "QC_Price",SUM("QC_Amount") AS "QC_Amount"
					,SUM("In_Qty") AS "In_Qty",SUM("In_Amount")/NULLIF(SUM("In_Qty"),0) AS "In_Price",SUM("In_Amount") AS "In_Amount"
					,SUM("Out_Qty") AS "Out_Qty",SUM("Out_Amount")/NULLIF(SUM("Out_Qty"),0) AS "Out_Price",SUM("Out_Amount") AS "Out_Amount"
					,SUM("QM_Qty") AS "QM_Qty",SUM("QM_Price") AS "QM_Price",SUM("QM_Amount") AS "QM_Amount",SUM("Price") AS "Price"
			 FROM 
				(SELECT "ItemCode","QC_Qty","QC_Price","QC_Amount"
					,"In_Qty",0 AS "In_Price","In_Amount"
					,"Out_Qty",0 AS "Out_Price","Out_Amount"
					,0 AS "QM_Qty",0 AS "QM_Price",0 AS "QM_Amount",0 AS "Price"
					FROM MTC_COST_0301_INVNT
					WHERE "FcCode"=:FromFcCode
					AND "CostCode"='20'
				 UNION ALL
				 SELECT  "ItemCode",0 AS "QC_Qty",0 AS "QC_Price",0 AS "QC_Amount"
					,"In_Qty",0 AS "In_Price","In_Amount"
					,"Out_Qty",0 AS "Out_Price","Out_Amount"
					,0 AS "QM_Qty",0 AS "QM_Price",0 AS "QM_Amount",0 AS "Price"
					FROM MTC_COST_0301_INVNT
					WHERE "FcCode">:FromFcCode
					AND "FcCode"<:ToFcCode
					AND "CostCode"='20'
				 UNION ALL
				 SELECT  "ItemCode",0 AS "QC_Qty",0 AS "QC_Price",0 AS "QC_Amount"
					,"In_Qty",0 AS "In_Price","In_Amount"
					,"Out_Qty",0 AS "Out_Price","Out_Amount"
					,"QM_Qty","QM_Price","QM_Amount","Price"
					FROM MTC_COST_0301_INVNT
					WHERE "FcCode"=:ToFcCode
					AND "CostCode"='20'
				) T0 GROUP BY "ItemCode"
			) T0
		JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
		LEFT JOIN OITB T2 ON T1."ItmsGrpCod"=T2."ItmsGrpCod"
		LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct",MAX("ShpdGdsAct") AS "ShpdGdsAct"
				FROM OGAR WHERE "PeriodCat"=LEFT(:ToFcCode,4) GROUP BY "ItmsGrpCod"
			) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
		LEFT JOIN "OACT" T4 ON T3."StockAct"=T4."AcctCode"
		WHERE 1=1
		AND (T1."ItemCode" = :ItemCode OR :ItemCode='')
		AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
		AND T1."InvntItem"='Y'
--AND (IFNULL(T0."QC_Qty",0)<>0 OR IFNULL(T0."In_Qty",0)<>0 OR IFNULL(T0."Out_Qty",0)<>0 OR IFNULL(T0."QM_Qty",0)<>0)
		ORDER BY T0."ItemCode";
	else
		TMP_Detail=
		SELECT :FromFcCode||'~'||:ToFcCode AS "FcCode",
		T0."CostCode" AS "成本类型",
		T0."ItemCode",
		T0."ItemName" AS "物料名称",
		T1."InvntryUom" AS "单位",
		T0."QC_Qty" AS "期初数量",
		T0."QC_Price" AS "期初单价", 
		T0."QC_Amount" AS "期初金额",
		T0."In_Qty" AS "入库数量",
		T0."In_Price" AS "入库单价",
		T0."In_Amount" AS "入库金额",
		T0."Out_Qty" AS "出库数量",
		T0."Out_Price" AS "出库单价",
		T0."Out_Amount" AS "出库金额",
		T0."QM_Qty" AS "期末数量",
		T0."QM_Price" AS "期末单价",
		ROUND(T0."QM_Amount",2) AS "期末金额",
		T0."Price" AS "单价",
		T0."CreateDate" AS "创建时间",
		T0."Creator" AS "创建人",
		T0."CalType" AS "计算类型",
		T0."iLevel" AS "计算级别",
		T0."ItmsGrpCod" AS "物料组编码" ,
		T2."ItmsGrpNam" AS "物料组名称",
		T4."AcctCode" AS "科目编码",
		T4."AcctName" AS "科目名称",
		T0."PriceMemo" AS "价格更新来源"
		FROM MTC_COST_0301_INVNT T0
		JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
		LEFT JOIN OITB T2 ON T0."ItmsGrpCod"=T2."ItmsGrpCod"
		LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct",MAX("ShpdGdsAct") AS "ShpdGdsAct"
				FROM OGAR WHERE "PeriodCat"=LEFT(:ToFcCode,4) GROUP BY "ItmsGrpCod"
			) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
		LEFT JOIN "OACT" T4 ON T3."StockAct"=T4."AcctCode"
		WHERE T0."FcCode" = :ToFcCode
		AND (T0."ItemCode" = :ItemCode OR :ItemCode='')
		AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
		AND T1."InvntItem"='Y'
		AND T0."CostCode"='20'
--AND (IFNULL(T0."QC_Qty",0)<>0 OR IFNULL(T0."In_Qty",0)<>0 OR IFNULL(T0."Out_Qty",0)<>0 OR IFNULL(T0."QM_Qty",0)<>0)
		ORDER BY T0."ItemCode";
	
	END IF;
	
	SELECT T0."FcCode",
	T0."成本类型",
	T0."ItemCode",
	T0."物料名称",
	T0."单位",
	CAST(CAST(T0."期初数量" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "期初数量",
	CAST(CAST(T0."期初单价" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "期初单价", 
	T0."期初金额",
	CAST(CAST(T0."入库数量" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "入库数量",
	CAST(CAST(T0."入库单价" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "入库单价",
	T0."入库金额",
	CAST(CAST(T0."出库数量" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "出库数量",
	CAST(CAST(T0."出库单价" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "出库单价",
	T0."出库金额" AS "出库金额",
	CAST(CAST(T0."期末数量" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "期末数量",
	CAST(CAST(T0."期末单价" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "期末单价",
	T0."期末金额",
	CAST(CAST(T0."单价" AS DECIMAL(19,6)) AS NVARCHAR(30)) AS "单价",
	T0."创建时间",
	T0."创建人",
	T0."计算类型",
	T0."计算级别",
	T0."物料组编码" ,
	T0."物料组名称",
	T0."科目编码",
	T0."科目名称",
	T0."价格更新来源",
	1 AS "ID",
	:FromFcCode AS "FromFcCode",
	:ToFcCode AS "ToFcCode"
	FROM :TMP_Detail T0
	
	UNION ALL
	SELECT T0."FcCode",
	NULL AS "成本类型",
	NULL AS "ItemCode",
	NULL AS "物料名称",
	NULL AS "单位",
	SUM(T0."期初数量"),
	NULL AS "期初单价", 
	SUM(T0."期初金额"),
	SUM(T0."入库数量"),
	NULL AS "入库单价",
	SUM(T0."入库金额"),
	SUM(T0."出库数量"),
	NULL AS "出库单价",
	SUM(T0."出库金额"),
	SUM(T0."期末数量"),
	NULL AS "期末单价",
	SUM(T0."期末金额"),
	NULL AS "单价",
	NULL AS "创建时间",
	NULL AS "创建人",
	NULL AS "计算类型",
	NULL AS "计算级别",
	T0."物料组编码" ,
	T0."物料组名称" || ' 合计',
	T0."科目编码",
	T0."科目名称" || ' 合计',
	NULL AS "价格更新来源",
	2 AS "ID",
	:FromFcCode AS "FromFcCode",
	:ToFcCode AS "ToFcCode"
	FROM :TMP_Detail T0
	GROUP BY T0."FcCode",T0."成本类型",T0."物料组编码",T0."物料组名称",T0."科目编码",	T0."科目名称"
	
	UNION ALL
	SELECT T0."FcCode",
	NULL AS "成本类型",
	NULL AS "ItemCode",
	NULL AS "物料名称",
	NULL AS "单位",
	SUM(T0."期初数量"),
	NULL AS "期初单价", 
	SUM(T0."期初金额"),
	SUM(T0."入库数量"),
	NULL AS "入库单价",
	SUM(T0."入库金额"),
	SUM(T0."出库数量"),
	NULL AS "出库单价",
	SUM(T0."出库金额"),
	SUM(T0."期末数量"),
	NULL AS "期末单价",
	SUM(T0."期末金额"),
	NULL AS "单价",
	NULL AS "创建时间",
	NULL AS "创建人",
	NULL AS "计算类型",
	NULL AS "计算级别",
	NULL AS "物料组编码" ,
	'合计',
	NULL AS "科目编码",
	NULL AS "科目名称",
	NULL AS "价格更新来源",
	3 AS "ID",
	:FromFcCode AS "FromFcCode",
	:ToFcCode AS "ToFcCode"
	FROM :TMP_Detail T0
	GROUP BY T0."FcCode",T0."成本类型"
	
	ORDER BY "ID","ItemCode"
	;
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO3002
CREATE Procedure "MTC_RPT_CO3002"
(
 IN SFcCode		NVARCHAR(30)
,IN EFcCode		NVARCHAR(30)
,IN ItemCode	NVARCHAR(50)
,IN ItmsGrpCod  INT DEFAULT 0
)
LANGUAGE SQLSCRIPT

AS	
BEGIN
	
	DECLARE sdate date;
	DECLARE edate date;
	
	SELECT "F_RefDate" INTO sdate FROM OFPR WHERE "Code"=:SFcCode;
	SELECT "T_RefDate" INTO edate FROM OFPR WHERE "Code"=:EFcCode;
	
	TMP_LIST=
	SELECT -1 AS "ID",
	T0."BPLId",
	:SFcCode AS "FcCode",
	T0."ItemCode",
	T0."ItemName",
	T5."ItmsGrpNam",
	'-1' AS "ObjType",
	'期初余额' AS "DocName",
	NULL AS "DocEntry",
	NULL AS "DocNum",
	NULL AS "LineNum",
	:sdate AS "DocDate",
	NULL AS "TransCode",
	NULL AS "BusiType",
	NULL AS "BusiTypeN",
	NULL AS "BaseType",
	NULL AS "BaseTypeN",
	NULL AS "BaseEntry",
	NULL AS "BaseNum",
	NULL AS "BaseLine",
	NULL AS "Quantity",
	NULL AS "Price",
	NULL AS "Amount",
	T0."QC_Qty" AS "BalQty",
	T0."QC_Amount" AS "Balance",
	T2."InvntryUom" AS "单位",
	NULL AS "部门编码",
	NULL AS "部门名称",
	T51."AcctCode" AS "库存科目编码",
	T51."AcctCode" AS "库存科目名称",
	NULL AS "其他领用科目编码",
	NULL AS "其他领用科目名称",
	NULL AS "仓库编码",
	NULL"CreateDate",
	NULL"Creator",
	NULL"iLevel",
	NULL AS "价格备注",
	NULL AS "价格标识"
	FROM MTC_COST_0301_INVNT T0
	LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"='2024' GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN OITB T5 ON T2."ItmsGrpCod"=T5."ItmsGrpCod"
	LEFT JOIN OACT T51 ON T3."StockAct"=T51."AcctCode"
	WHERE 1=1
	AND (T0."FcCode" = :SFcCode)
	AND (T0."ItemCode"=:ItemCode OR :ItemCode='')
	AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
	AND T0."CostCode"='20'
	
	UNION ALL
	SELECT ROW_NUMBER() OVER(PARTITION BY T0."ItemCode" ORDER BY T0."FcCode",T0."DocDate") AS "ID",
	T0."BPLId",
	T0."FcCode",
	T0."ItemCode",
	T0."ItemName",
	T5."ItmsGrpNam",
	T0."ObjType",
	T9."DocName",
	T0."DocEntry",
	T0."DocNum",
	T0."LineNum",
	T0."DocDate",
	T10."Code"||'-'||T10."Name" AS "TransCode",
	T0."BusiType",
	T0."BusiTypeN",
	T0."BaseType",
	T11."DocName" AS "BaseTypeN",
	T0."BaseEntry",
	T0."BaseNum",
	T0."BaseLine",
	T0."Quantity",
	CAST(CAST(T0."Price" AS DECIMAL(19,6)) AS NVARCHAR(50)) AS "Price",
	T0."Amount",
	T0."Quantity" AS "BalQty",
	T0."Amount" AS "Balance",
	T2."InvntryUom" AS "单位",
	T0."OcrCode1" AS "部门编码",
	P."PrcName" AS "部门名称",
	T3."StockAct" AS "库存科目编码",
	T51."AcctName" AS "库存科目名称",
	T4."AcctCode" AS "其他领用科目编码",
	T52."AcctName" AS "其他领用科目名称",
	T0."WhsCode" AS "仓库编码",
	T0."CreateDate",
	T0."Creator",
	T0."iLevel",
	T0."PriceMemo" AS "价格备注",
	T0."IsUpdatePrice" AS "价格标识"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "FcCode"='[%0]' AND "CostCode"='20') T1 ON T0."ItemCode"=T1."ItemCode"
	LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"='2024' GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN (
		SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGN1
			UNION ALL
		SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGE1
		) T4 ON T0."ObjType"=TO_CHAR(T4."ObjType") AND T0."DocEntry"=T4."DocEntry" AND T0."LineNum"=T4."LineNum"
	LEFT JOIN OITB T5 ON T2."ItmsGrpCod"=T5."ItmsGrpCod"
	LEFT JOIN "MTC_DocType" T9 ON T0."ObjType"=T9."ObjType"
	LEFT JOIN "MTC_DocType" T11 ON T0."BaseType"=T11."ObjType"
	LEFT JOIN "@MTC_COST_IOTYPE" T10 ON T0."TransCode"=T10."Code"
	LEFT JOIN OACT T51 ON T3."StockAct"=T51."AcctCode"
	LEFT JOIN OACT T52 ON T4."AcctCode"=T52."AcctCode"
	LEFT JOIN OPRC P ON T0."OcrCode1"=P."PrcCode"
	WHERE 1=1
	AND (T0."FcCode" >= :SFcCode OR :SFcCode='')
	AND (T0."FcCode" <= :EFcCode OR :EFcCode='')
	AND (T0."ItemCode"=:ItemCode OR :ItemCode='')
	AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
	AND T0."CostCode"='20'
	
	UNION ALL
	SELECT 99999999 AS "ID",
	T0."BPLId",
	:EFcCode AS "FcCode",
	T0."ItemCode",
	T0."ItemName",
	T5."ItmsGrpNam",
	'-1' AS "ObjType",
	'期末余额' AS "DocName",
	NULL AS "DocEntry",
	NULL AS "DocNum",
	NULL AS "LineNum",
	:edate AS "DocDate",
	NULL AS "TransCode",
	NULL AS "BusiType",
	NULL AS "BusiTypeN",
	NULL AS "BaseType",
	NULL AS "BaseTypeN",
	NULL AS "BaseEntry",
	NULL AS "BaseNum",
	NULL AS "BaseLine",
	NULL AS "Quantity",
	NULL AS "Price",
	NULL AS "Amount",
	T0."QM_Qty" AS "BalQty",
	T0."QM_Amount" AS "Balance",
	T2."InvntryUom" AS "单位",
	NULL AS "部门编码",
	NULL AS "部门名称",
	T51."AcctCode" AS "库存科目编码",
	T51."AcctCode" AS "库存科目名称",
	NULL AS "其他领用科目编码",
	NULL AS "其他领用科目名称",
	NULL AS "仓库编码",
	NULL"CreateDate",
	NULL"Creator",
	NULL"iLevel",
	NULL AS "价格备注",
	NULL AS "价格标识"
	FROM MTC_COST_0301_INVNT T0
	LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"='2024' GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN OITB T5 ON T2."ItmsGrpCod"=T5."ItmsGrpCod"
	LEFT JOIN OACT T51 ON T3."StockAct"=T51."AcctCode"
	WHERE 1=1
	AND (T0."FcCode" = :EFcCode)
	AND (T0."ItemCode"=:ItemCode OR :ItemCode='')
	AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
	AND T0."CostCode"='20'
	;
	
	SELECT 
	T0."FcCode",
	T0."ItemCode",
	T0."ItemName",
	T0."ItmsGrpNam",
	T0."DocDate",
	T0."ObjType",
	T0."DocName",
	T0."DocEntry",
	T0."DocNum",
	T0."LineNum",
	T0."TransCode",
	T0."BusiType",
	T0."BusiTypeN",
	T0."Quantity",
	T0."Price",
	T0."Amount",
	CASE WHEN T0."ID"=99999999 THEN "BalQty" ELSE SUM(T0."BalQty") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID") END AS "累计数量",
	TO_CHAR(CAST((SUM(T0."Balance") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID")/
	NULLIF(SUM(T0."BalQty") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID"),0)) AS DECIMAL(19,6)))
	 AS "累计成本单价",
	CASE WHEN T0."ID"=99999999 THEN "Balance" ELSE SUM(T0."Balance") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID") END AS "累计余额",
	T0."BaseType",
	T0."BaseTypeN",
	T0."BaseEntry",
	T0."BaseNum",
	T0."BaseLine",
	T2."ItemCode" AS "产成品的物料编码",
	T2."ProdName" AS "产成品的物料名称",
	T0."单位",
	T0."部门编码",
	T0."部门名称",
	T0."库存科目编码",
	T0."库存科目名称",
	T0."其他领用科目编码",
	T0."其他领用科目名称",
	T0."仓库编码",
	T0."CreateDate",
	T0."Creator",
	T0."iLevel",
	T0."价格备注",
	T0."价格标识",
	T1."U_SupNum" AS "业务单号"
	FROM :TMP_LIST T0
	LEFT JOIN (SELECT DISTINCT "ObjType","DocEntry","LineNum","U_SupNum" FROM "MTC_VIEW_Document") T1 ON T0."ObjType"=T1."ObjType" AND T0."DocEntry"=T1."DocEntry" AND T0."LineNum"=T1."LineNum"
	LEFT JOIN OWOR T2 ON T0."BaseType"='202' AND T0."BaseEntry"=T2."DocEntry"
	ORDER BY T0."ItemCode",T0."ID";
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO3004
CREATE Procedure "MTC_RPT_CO3004"
(
	IN FcCode		NVARCHAR(30)
)
LANGUAGE SQLSCRIPT

AS	
BEGIN


SELECT 
		T2."ItmsGrpCod"			"物料组编码"
		,T6."ItmsGrpNam"		"物料组名称"
		,T3."StockAct"			"存货科目"
		,T5."AcctName"			"存货科目名称"
		,T1."TransCode"			"交易代码"
		,T4."Name"				"交易名称"
		,ROUND(SUM(T1."Quantity"),2)		"发生数量"
		,ROUND(SUM(T1."Amount"),2) 		"发生金额"
		,T4."U_TransCode"
	FROM MTC_COST_0302_INVNTDETAIL1 T1
	LEFT JOIN OITM T2 ON T1."ItemCode"=T2."ItemCode"
	LEFT JOIN (
				SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" 
				FROm OGAR 
				WHERE "PeriodCat"='2025' 
				GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN "@MTC_COST_IOTYPE" T4 ON T1."TransCode"=T4."Code"
	LEFT JOIN OACT T5 ON T5."AcctCode"=T3."StockAct"
	LEFT JOIN OITB T6 ON T6."ItmsGrpCod"=T2."ItmsGrpCod"
	WHERE 1=1
	AND T1."FcCode"=:FcCode
	GROUP BY T2."ItmsGrpCod",T6."ItmsGrpNam",T3."StockAct",T5."AcctName",T1."TransCode"	,T4."Name",T4."U_TransCode"	
	ORDER BY T3."StockAct"
	;
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO3005
CREATE Procedure "MTC_RPT_CO3005"
(
 IN SFcCode		NVARCHAR(30)
,IN EFcCode		NVARCHAR(30)
,IN ItemCode	NVARCHAR(50)
,IN ItmsGrpCod  INT DEFAULT 0
,IN TransCode NVARCHAR(50)
,IN IOType NVARCHAR(10)
)
LANGUAGE SQLSCRIPT

AS	
BEGIN
	
	DECLARE sdate date;
	DECLARE edate date;
	
	SELECT "F_RefDate" INTO sdate FROM OFPR WHERE "Code"=:SFcCode;
	SELECT "T_RefDate" INTO edate FROM OFPR WHERE "Code"=:EFcCode;
	
	TMP_LIST=
	SELECT -1 AS "ID",
	T0."BPLId",
	:SFcCode AS "FcCode",
	T0."ItemCode",
	T0."ItemName",
	T5."ItmsGrpNam",
	'-1' AS "ObjType",
	'期初余额' AS "DocName",
	NULL AS "DocEntry",
	NULL AS "DocNum",
	NULL AS "DocSupNum",
	NULL AS "LineNum",
	:sdate AS "DocDate",
	NULL AS "TransCode",
	NULL AS "TransName",
	NULL AS "BusiType",
	NULL AS "BusiTypeN",
	NULL AS "BaseType",
	NULL AS "BaseTypeN",
	NULL AS "BaseEntry",
	NULL AS "BaseNum",
	NULL AS "BaseDocSupNum",
	NULL AS "BaseLine",
	NULL AS "Quantity",
	NULL AS "Price",
	NULL AS "Amount",
	T0."QC_Qty" AS "BalQty",
	T0."QC_Amount" AS "Balance",
	T2."InvntryUom" AS "单位",
	NULL AS "部门编码",
	NULL AS "部门名称",
	T51."AcctCode" AS "库存科目编码",
	T51."AcctCode" AS "库存科目名称",
	NULL AS "其他领用科目编码",
	NULL AS "其他领用科目名称",
	NULL AS "仓库编码",
	NULL"CreateDate",
	NULL"Creator",
	NULL"iLevel",
	NULL AS "价格备注",
	NULL AS "价格标识"
	FROM MTC_COST_0301_INVNT T0
	LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"='2024' GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN OITB T5 ON T2."ItmsGrpCod"=T5."ItmsGrpCod"
	LEFT JOIN OACT T51 ON T3."StockAct"=T51."AcctCode"
	WHERE 1=0
	AND (T0."FcCode" = :SFcCode)
	AND (T0."ItemCode"=:ItemCode OR :ItemCode='')
	AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
	AND T0."CostCode"='20'
	
	UNION ALL
	SELECT ROW_NUMBER() OVER(PARTITION BY T0."ItemCode" ORDER BY T0."FcCode",T0."DocDate") AS "ID",
	T0."BPLId",
	T0."FcCode",
	T0."ItemCode",
	T0."ItemName",
	T5."ItmsGrpNam",
	T0."ObjType",
	T9."DocName",
	T0."DocEntry",
	T0."DocNum",
	T0."DocSupNum",
	T0."LineNum",
	T0."DocDate",
	T10."Code" AS "TransCode",
	T10."Code"||'-'||T10."Name" AS "TransName",
	T0."BusiType",
	T0."BusiTypeN",
	T0."BaseType",
	T11."DocName" AS "BaseTypeN",
	T0."BaseEntry",
	T0."BaseNum",
	T0."BaseDocSupNum",
	T0."BaseLine",
	T0."Quantity",
	CAST(CAST(T0."Price" AS DECIMAL(19,6)) AS NVARCHAR(50)) AS "Price",
	T0."Amount",
	T0."Quantity" AS "BalQty",
	T0."Amount" AS "Balance",
	T2."InvntryUom" AS "单位",
	T0."OcrCode1" AS "部门编码",
	P."PrcName" AS "部门名称",
	T3."StockAct" AS "库存科目编码",
	T51."AcctName" AS "库存科目名称",
	T4."AcctCode" AS "其他领用科目编码",
	T52."AcctName" AS "其他领用科目名称",
	T0."WhsCode" AS "仓库编码",
	T0."CreateDate",
	T0."Creator",
	T0."iLevel",
	T0."PriceMemo" AS "价格备注",
	T0."IsUpdatePrice" AS "价格标识"
	FROM MTC_COST_0302_INVNTDETAIL1 T0
	LEFT JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "FcCode"='[%0]' AND "CostCode"='20') T1 ON T0."ItemCode"=T1."ItemCode"
	LEFT JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROm OGAR WHERE "PeriodCat"=:EFcCode GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN (
		SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGN1
			UNION ALL
		SELECT "ObjType","DocEntry","LineNum","AcctCode" FROM IGE1
		) T4 ON T0."ObjType"=TO_CHAR(T4."ObjType") AND T0."DocEntry"=T4."DocEntry" AND T0."LineNum"=T4."LineNum"
	LEFT JOIN OITB T5 ON T0."ItmsGrpCod"=T5."ItmsGrpCod"
	LEFT JOIN "MTC_DocType" T9 ON T0."ObjType"=T9."ObjType"
	LEFT JOIN "MTC_DocType" T11 ON T0."BaseType"=T11."ObjType"
	LEFT JOIN "@MTC_COST_IOTYPE" T10 ON T0."TransCode"=T10."Code"
	LEFT JOIN OACT T51 ON T3."StockAct"=T51."AcctCode"
	LEFT JOIN OACT T52 ON T4."AcctCode"=T52."AcctCode"
	LEFT JOIN OPRC P ON T0."OcrCode1"=P."PrcCode"
	WHERE 1=1
	AND (T0."FcCode" >= :SFcCode OR :SFcCode='')
	AND (T0."FcCode" <= :EFcCode OR :EFcCode='')
	AND (T0."ItemCode"=:ItemCode OR :ItemCode='')
	AND (T2."ItmsGrpCod"=:ItmsGrpCod OR :ItmsGrpCod=0)
	AND T0."CostCode"='20'
	
	;
	
	SELECT 
	T0."FcCode",
	T0."ItemCode",
	T0."ItemName",
	T0."ItmsGrpNam",
	T0."DocDate",
	T0."ObjType",
	T0."DocName",
	T0."DocEntry",
	T0."DocNum",
	T1."U_SupNum" AS "业务单号",
	T0."LineNum",
	T0."TransName",
	T0."BusiType",
	T0."BusiTypeN",
	T0."Quantity",
	T0."Price",
	T0."Amount",
	CASE WHEN T0."ID"=99999999 THEN "BalQty" ELSE SUM(T0."BalQty") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID") END AS "累计数量",
	TO_CHAR(CAST((SUM(T0."Balance") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID")/
	NULLIF(SUM(T0."BalQty") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID"),0)) AS DECIMAL(19,6)))
	 AS "累计成本单价",
	CASE WHEN T0."ID"=99999999 THEN "Balance" ELSE SUM(T0."Balance") OVER (PARTITION BY T0."ItemCode" ORDER BY T0."ID") END AS "累计余额",
	T0."BaseType",
	T0."BaseTypeN"||'-'||T2."U_OrdType",
	T0."BaseEntry",
	T0."BaseNum",
	T0."BaseLine",
	T2."ItemCode" AS "产成品的物料编码",
	T2."ItemName" AS "产成品的物料名称",
	T2."U_SupNum" AS "生产订单的业务单号",
	P1."OcrCode" AS "生产订单的部门编码",
	P1."OcrName" AS "生产订单的部门名称",
	T0."单位",
	T0."部门编码",
	T0."部门名称",
	T0."库存科目编码",
	T0."库存科目名称",
	T0."其他领用科目编码",
	T0."其他领用科目名称",
	T0."仓库编码",
	T0."CreateDate",
	T0."Creator",
	T0."iLevel",
	T0."价格备注",
	T0."价格标识",
	CASE WHEN T10."U_IOType"='I' THEN '入库' WHEN T10."U_IOType"='O' THEN '出库' END AS "出入库类型"
	FROM :TMP_LIST T0
	LEFT JOIN (SELECT DISTINCT "ObjType","DocEntry","LineNum","U_SupNum" FROM "MTC_VIEW_Document") T1 ON T0."ObjType"=T1."ObjType" AND T0."DocEntry"=T1."DocEntry" AND T0."LineNum"=T1."LineNum"
	LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","U_SupNum","U_OrdType","ItemCode","ProdName" AS "ItemName","OcrCode" FROM OWOR
				UNION ALL
			   SELECT "Object","DocEntry","U_SupNum","U_OrdType","U_ItemCode","U_ProdName","U_OcrCode" FROM "@MTC_OWOR"
			) T2 ON T0."BaseType"='202' AND T0."BaseEntry"=T2."DocEntry"
	LEFT JOIN "@MTC_COST_IOTYPE" T10 ON T0."TransCode"=T10."Code"
	LEFT JOIN OOCR P1 ON T2."OcrCode"=P1."OcrCode"
	WHERE 1=1
	AND (T0."TransCode"=:TransCode OR :TransCode='')
	AND (T10."U_IOType"=:IOType OR :IOType='')
	ORDER BY T0."ItemCode",T0."ID";
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO3006
CREATE PROCEDURE "MTC_RPT_CO3006" (
IN USERId INT
      ,IN sFcCode NVARCHAR(50)
      ,IN eFcCode NVARCHAR(50)
      ,IN ItemCode NVARCHAR(100)
  )
  LANGUAGE SQLSCRIPT
  SQL SECURITY INVOKER
  AS
  BEGIN

	SELECT
      -- 基本信息
      T."FcCode"                                          AS "期间",
      T."ItemCode"                                        AS "物料编号",
      T."ItemName"                                        AS "物料名称",
      T."iLevel"                                          AS "BOM层级",
      T."Status"                                          AS "状态",
  
      -- =====================================================
      -- 期初
      -- =====================================================
      T."OpenQty"                                         AS "期初数量",
      T."OpenMaterial"                                    AS "期初材料金额",
      T."OpenManExp"                                      AS "期初制造费用",
      T."OpenLabAmount"                                   AS "期初人工费用",
      T."OpenWWExp"                                       AS "期初外协费用",
      T."OpenAmount"                                      AS "期初合计",
      CASE WHEN T."OpenQty" > 0
           THEN ROUND(T."OpenAmount" / T."OpenQty", 6)
           ELSE 0 END                                     AS "期初单位成本",
  
      -- =====================================================
      -- 本期入库
      -- =====================================================
      T."InQty"                                           AS "入库数量",
      T."InMaterial"                                      AS "入库材料金额",
      T."InManExp"                                        AS "入库制造费用",
      T."InLabAmount"                                     AS "入库人工费用",
      T."InWWExp"                                         AS "入库外协费用",
      T."InAmount"                                        AS "入库合计",
      CASE WHEN T."InQty" > 0
           THEN ROUND(T."InAmount" / T."InQty", 6)
           ELSE 0 END                                     AS "入库单位成本",
  
      -- =====================================================
      -- 本期出库
      -- =====================================================
      T."OutQty"                                          AS "出库数量",
      T."OutMaterial"                                     AS "出库材料金额",
      T."OutManExp"                                       AS "出库制造费用",
      T."OutLabAmount"                                    AS "出库人工费用",
      T."OutWWExp"                                        AS "出库外协费用",
      T."OutAmount"                                       AS "出库合计",
      CASE WHEN T."OutQty" > 0
           THEN ROUND(T."OutAmount" / T."OutQty", 6)
           ELSE 0 END                                     AS "出库单位成本",
  
      -- =====================================================
      -- 期末
      -- =====================================================
      T."CloseQty"                                        AS "期末数量",
      T."CloseMaterial"                                   AS "期末材料金额",
      T."CloseManExp"                                     AS "期末制造费用",
      T."CloseLabAmount"                                  AS "期末人工费用",
      T."CloseWWExp"                                      AS "期末外协费用",
      T."CloseAmount"                                     AS "期末合计",
  
      -- =====================================================
      -- 期末单位成本
      -- =====================================================
      T."UnitMaterial"                                    AS "期末单位材料成本",
      T."UnitManExp"                                      AS "期末单位制造费用",
      T."UnitLabAmount"                                   AS "期末单位人工费用",
      T."UnitWWExp"                                       AS "期末单位外协费用",
      T."UnitCost"                                        AS "期末单位总成本",
  
      -- =====================================================
      -- 成本结构比例
      -- =====================================================
      ROUND(IFNULL(T."PrcMaterial",  0) * 100, 2)        AS "材料占比%",
      ROUND(IFNULL(T."PrcManExp",    0) * 100, 2)        AS "制造费用占比%",
      ROUND(IFNULL(T."PrcLabAmount", 0) * 100, 2)        AS "人工费用占比%",
      ROUND(IFNULL(T."PrcWWExp",     0) * 100, 2)        AS "外协费用占比%",
      ROUND((  IFNULL(T."PrcMaterial",  0)
             + IFNULL(T."PrcManExp",    0)
             + IFNULL(T."PrcLabAmount", 0)
             + IFNULL(T."PrcWWExp",     0)) * 100, 2)    AS "比例合计%",
  
      -- =====================================================
      -- 校验：数量平衡（应=0）
      -- =====================================================
      ROUND(T."OpenQty" + T."InQty" - T."OutQty" - T."CloseQty", 6)  AS "数量差异",
  
      -- 校验：金额平衡（应=0）
      ROUND(T."OpenAmount" + T."InAmount" - T."OutAmount" - T."CloseAmount", 2) AS "金额差异"
  
  FROM "MTC_COST_STOCK" T
  WHERE  1=1
  AND T."FcCode" >= :sFcCode     -- 替换为目标期间
  AND T."FcCode" <= :eFcCode     -- 替换为目标期间
    AND T."Status" = 'C'
    AND (T."ItemCode"=:ItemCode OR :ItemCode='')
  ORDER BY T."iLevel", T."ItemCode";
  
 END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO4003
CREATE PROCEDURE "MTC_RPT_CO4003"
(
  IN UserId INT,
  IN FcCode NVARCHAR(30),
  IN ItemCode NVARCHAR(50),
  IN WorNum NVARCHAR(50)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 

	SELECT T0."FcCode",T0."DocType"
	,CASE T9."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END 
		AS "工单类型"
	,T0."WorEntry",T0."WorNum"
	,T7."ItemCode",T7."ItemName" AS "产成品名称",T8."ItmsGrpNam" AS "产成品类型"
	,T0."Quantity"	AS "计划数量"
	,T0."IgnQty"	AS "入库数量"
	,T1."ItemCode"	AS "子件编码"
	,T11."ItemName" AS "子件名称"
	,T1."Qty"		AS "计入完工材料数量"
	,CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN IFNULL(T1."Amount",0) ELSE IFNULL(T1."ActAmount",0) END
		AS "计入完工材料金额"	--理论完工总额（计入已完工生产成本）

	,T1."IgeQty"	AS "领料数量"
	,T1."Amount"	AS "领料金额（在产品）"
	,T1."ActAmount" AS "实际领料金额"
	,CASE WHEN T0."Quantity"-IFNULL(T0."IgnQty",0)>0 THEN '在产品领料' ELSE '实际领料' END  AS "金额备注"
	,T0."2ManExp" AS "人工费用",T0."3LabAmount" AS "制造费用",T0."4WWExp" AS "委外费用"
	
	FROM MTC_COST_0321_OWOR T0
	--材料费用
	JOIN (
				SELECT :FcCode AS "FcCode",T1."DocType",T1."WorEntry",T1."WorNum",T1."ItemCode",-1*SUM(T1."IgeQty") AS "IgeQty"
				--累计截止到现在的数据：SUM(单个完工产品成本=单位材料成本(领料金额/领料数量)*按照实际完工量计算出的理论用料)
				--按照实际完工量计算出的理论用料=实际入库数量*生产订单的计划用量比（材料计划用量/产成品计划完工数量）
				,SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
						THEN -1*T1."Amount"/NULLIF(T0."IgnQty_SUM",0)*T0."IgnQty" ELSE
					  (-1*T1."Amount")/NULLIF((-1*T1."IgeQty"),0)*T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Amount"	--按领料比例折算的金额（当领料数量少于入库数量比的时候，先取实际投料的金额）
				,SUM(CASE WHEN (-1*IFNULL(T1."IgeQty",0))/NULLIF(IFNULL(T0."IgnQty_SUM",0),0)-T1."Wor1Qty"/T1."OworQty"<0
						THEN -1*IFNULL(T1."IgeQty",0) ELSE
					  T0."IgnQty"*T1."Wor1Qty"/T1."OworQty" END) AS "Qty"	--按领料比例折算的在产品领料数量
				,SUM(-1*T1."Amount") AS "ActAmount"
				FROM 	
					(
						SELECT T1."DocType",T1."WorEntry",T1."WorNum",T1."ItemCode",T1."Amount",T1."IgeQty",T2."Wor1Qty",T2."OworQty"
						FROM 
						(SELECT T1."DocType",T1."WorEntry",T1."WorNum",T1."ItemCode",SUM(T1."Amount") AS "Amount",SUM(T1."IgeQty") AS "IgeQty"
							FROM MTC_COST_0321_OWOR1 T1
							WHERE T1."FcCode"<=:FcCode GROUP BY T1."DocType",T1."WorEntry",T1."WorNum",T1."ItemCode"
						) T1
						LEFT JOIN (SELECT M."DocType",D."WorEntry",D."ItemCode",SUM(D."Quantity") AS "Wor1Qty",M."Quantity" AS "OworQty"
										FROM MTC_COST_0106_OWORLIST1 D
										JOIN MTC_COST_0106_OWORLIST M ON M."FcCode"=D."FcCode" AND M."DocType"=D."DocType" AND D."WorEntry"=M."WorEntry"
										WHERE 1=1 AND M."FcCode"=:FcCode GROUP BY M."DocType",D."WorEntry",D."ItemCode",M."Quantity"
									) T2 ON T1."DocType"=T2."DocType" AND T1."WorEntry"=T2."WorEntry" AND T1."ItemCode"=T2."ItemCode"
					) T1
				JOIN (SELECT "DocType","WorEntry",SUM("IgnQty") AS "IgnQty_SUM"
					 ,SUM(CASE WHEN "FcCode"=:FcCode THEN "IgnQty" ELSE 0 END) AS "IgnQty"
					FROM MTC_COST_0321_OWOR WHERE "FcCode"<=:FcCode GROUP BY "DocType","WorEntry"
					) T0 ON T1."DocType"=T0."DocType" AND T1."WorEntry"=T0."WorEntry"
				WHERE 1=1
				AND (T1."WorNum"=:WorNum OR :WorNum='')
				GROUP BY T1."DocType",T1."WorEntry",T1."WorNum",T1."ItemCode"
			) T1 ON  T0."FcCode"=T1."FcCode" AND T1."DocType"=T0."DocType" AND T0."WorEntry"=T1."WorEntry"
		JOIN U_COILV T2 ON T0."FcCode"=T2."FcCode" AND T0."ItemCode"=T2."ItemCode"
		JOIN OITM T7 ON T0."ItemCode"=T7."ItemCode"
		JOIN OITB T8 ON T7."ItmsGrpCod"=T8."ItmsGrpCod"
		JOIN (SELECT '202' AS "DocType","DocEntry","DocNum","U_OrdType","PostDate","CloseDate","Status" FROM OWOR
				UNION ALL
			 SELECT "Object" AS "DocType","DocEntry","DocNum","U_OrdType","U_PostDate","U_PostDate","U_Status" FROM "@MTC_OWOR" 
			) T9 ON T0."DocType"=T9."DocType" AND T0."WorEntry"=T9."DocEntry"
		JOIN OITM T11 ON T1."ItemCode"=T11."ItemCode"
		WHERE T9."U_OrdType" NOT IN ('40','50')	--排除试打、委外
			;
				
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO4004
CREATE PROCEDURE "MTC_RPT_CO4004"
(
  IN STYPE INT,	--0汇总  1明细
  IN FcCode NVARCHAR(30),
  IN ItemCode NVARCHAR(50)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 

	SELECT  
	T0."FcCode" AS "期间",
	T0."DocType",
	(CASE T0."WorType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END) AS "工单类型",
	T0."DocDate" AS "订单日期",
	T0."CloseDate" AS "订单关单日期",
	CASE WHEN T0."Status"='R' THEN '已下达' WHEN T0."Status"='L' THEN '已结算' WHEN T0."Status"='P' THEN '已计划' END  AS "订单状态",
	T9."U_SupNum" AS "订单号",
	T0."WorEntry" AS "生产订单号Entry",
	T0."WorNum",
	T10."CardCode",
	T10."CardName",
	T0."ItemCode" AS "物料编码" ,
	T0."ItemName" AS "物料名称",
	T0."ItmsGrpCod" AS "物料组",
	T0."WorQty" AS "订单数量",
	T0."IgnQty" AS "当期入库数量",
	TO_CHAR(CAST(T0."Price" AS DECIMAL(19,6))) AS "完工入库单价",
	T0."IgnQty"*T0."Price" AS "当期入库成本金额",
	T0."Amount" AS "当期成本合计",
	T0."1Material" AS "当期材料金额",
	T0."2ManExp" AS "当期人工费用",
	T0."3LabAmount" AS "当期制造费用",
	T0."4WWExp" AS "当期委外费用",
	IFNULL(T0."CloseDifAmt",0) AS "关单差异",
	T21."IgnQty" AS "财务入库数量",
	T21."IgnAmt" AS "财务入库金额",
	IFNULL(T0."Amount",0)-IFNULL(T21."IgnAmt",0) AS "差异[当期成本合计-财务入库金额]"
	FROM MTC_COST_0321_OWOR_SUM T0
	JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct" FROM OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
					) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN
			(SELECT '202' AS "DocType","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM OWOR
				UNION ALL
			SELECT "Object","DocEntry","DocNum","U_SupNum","U_OldSysNo","U_CardCode","U_CardName" FROM "@MTC_OWOR"
			) T9 ON T0."WorEntry"=T9."DocEntry" AND T0."DocType"=T9."DocType"
	LEFT JOIN OCRD T10 ON T10."CardCode"=T9."U_CardCode"
	LEFT JOIN (SELECT "BaseType","BaseEntry",SUM("Quantity") AS "IgnQty",SUM("Amount") AS "IgnAmt"
			   FROM MTC_COST_0302_INVNTDETAIL1 T0
			   JOIN "@U_CIOTRN" T6 ON T0."BusiType"=T6."Code"
			   WHERE "FcCode"=:FcCode AND "CostCode"='20' AND T6."U_TransType"='B01'
			   GROUP BY "BaseType","BaseEntry"
			) T21 ON T0."DocType"=T21."BaseType" AND T0."WorEntry"=T21."BaseEntry"
	WHERE T0."FcCode" = :FcCode
	AND IFNULL(T0."IgnQty",0)<>0
	;
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO4005
CREATE PROCEDURE "MTC_RPT_CO4005"
(
  IN STYPE INT,	--0汇总  1明细
  IN SFcCode NVARCHAR(30),
  IN EFcCode NVARCHAR(30)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 


	SELECT
	T0."期间",
	SUM(T0."当期成本合计") AS "当期成本合计",
	SUM(T0."当期材料金额") AS "当期材料金额",
	SUM(T0."当期人工费用") AS "当期人工费用",
	SUM(T0."当期制造费用") AS "当期制造费用",
	SUM(T0."生产成本合计") AS "生产成本合计",
	SUM(T0."生产成本-直接材料") AS "生产成本-直接材料",
	SUM(T0."生产成本-人工费用") AS "生产成本-人工费用",
	SUM(T0."生产成本-制造费用") AS "生产成本-制造费用",
	SUM(T0."生产成本-直接材料(入库结转)") AS "生产成本-直接材料(入库结转)",
	SUM(T0."生产成本-人工费用(入库结转)") AS "生产成本-人工费用(入库结转)",
	SUM(T0."生产成本-制造费用(入库结转)") AS "生产成本-制造费用(入库结转)",
	SUM(T0."生产成本-直接材料(其他)") AS "生产成本-直接材料(其他)",
	SUM(T0."生产成本-人工费用(其他)") AS "生产成本-人工费用(其他)",
	SUM(T0."生产成本-制造费用(其他)") AS "生产成本-制造费用(其他)"
	FROM 
		(
		SELECT  
		T0."FcCode" AS "期间",
		SUM(T0."Amount") AS "当期成本合计",
		SUM(T0."1Material") AS "当期材料金额",
		SUM(T0."2ManExp") AS "当期人工费用",
		SUM(T0."3LabAmount") AS "当期制造费用",
		0.00 AS "生产成本合计",
		0.00 AS "生产成本-直接材料",
		0.00 AS "生产成本-人工费用",
		0.00 AS "生产成本-制造费用",
		0.00 AS "生产成本-直接材料(入库结转)",
		0.00 AS "生产成本-人工费用(入库结转)",
		0.00 AS "生产成本-制造费用(入库结转)",
		0.00 AS "生产成本-直接材料(其他)",
		0.00 AS "生产成本-人工费用(其他)",
		0.00 AS "生产成本-制造费用(其他)"
		FROM MTC_COST_0321_OWOR_SUM T0
		JOIN OITM T2 ON T0."ItemCode"=T2."ItemCode"
		WHERE T0."FcCode" BETWEEN :SFcCode AND :EFcCode
		AND T0."WorType" NOT IN ('40','50')
		AND IFNULL(T0."IgnQty",0)<>0
		GROUP BY T0."FcCode"
		
		UNION ALL
		SELECT LEFT(T0."RefDate",7) AS "期间",
		0.00 AS "当期成本合计",
		0.00 AS "当期材料金额",
		0.00 AS "当期人工费用",
		0.00 AS "当期制造费用",
		SUM(T1."Credit") AS "生产成本合计",
		SUM(CASE WHEN T1."Account"='500101' THEN T1."Credit" ELSE 0 END) AS "生产成本-直接材料",
		SUM(CASE WHEN T1."Account"='500102' THEN T1."Credit" ELSE 0 END) AS "生产成本-人工费用",
		SUM(CASE WHEN T1."Account"='500103' THEN T1."Credit" ELSE 0 END) AS "生产成本-制造费用",
		SUM(CASE WHEN T1."Account"='500101' AND T0."TransCode"='PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-直接材料(入库结转)",
		SUM(CASE WHEN T1."Account"='500102' AND T0."TransCode"='PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-人工费用(入库结转)",
		SUM(CASE WHEN T1."Account"='500103' AND T0."TransCode"='PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-制造费用(入库结转)",
		SUM(CASE WHEN T1."Account"='500101' AND IFNULL(T0."TransCode",'')<>'PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-直接材料(其他)",
		SUM(CASE WHEN T1."Account"='500102' AND IFNULL(T0."TransCode",'')<>'PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-人工费用(其他)",
		SUM(CASE WHEN T1."Account"='500103' AND IFNULL(T0."TransCode",'')<>'PP05' THEN T1."Credit" ELSE 0 END) AS "生产成本-制造费用(其他)"
		FROM OJDT T0
		JOIN JDT1 T1 ON T0."TransId"=T1."TransId"
		WHERE LEFT(T0."RefDate",7) BETWEEN :SFcCode AND :EFcCode
		AND T1."Account" IN ('500101','500102','500103')
		AND T1."Credit">0
		GROUP BY LEFT(T0."RefDate",7),T0."TransCode"
		
		--
		UNION ALL
		SELECT LEFT(T0."RefDate",7) AS "期间",
		0.00 AS "当期成本合计",
		0.00 AS "当期材料金额",
		0.00 AS "当期人工费用",
		0.00 AS "当期制造费用",
		0.00 AS "生产成本合计",
		0.00 AS "生产成本-直接材料",
		0.00 AS "生产成本-人工费用",
		0.00 AS "生产成本-制造费用",
		0.00 AS "生产成本-直接材料(入库结转)",
		0.00 AS "生产成本-人工费用(入库结转)",
		0.00 AS "生产成本-制造费用(入库结转)",
		0.00 AS "生产成本-直接材料(其他)",
		0.00 AS "生产成本-人工费用(其他)",
		SUM(CASE WHEN LEFT(T1."Account",4)='5101' AND IFNULL(T0."TransCode",'')='MR02' THEN 1*(T1."Debit"-T1."Credit") ELSE 0 END) AS "生产成本-制造费用(其他)"
		FROM OJDT T0
		JOIN JDT1 T1 ON T0."TransId"=T1."TransId"
		WHERE LEFT(T0."RefDate",7) BETWEEN :SFcCode AND :EFcCode
		AND LEFT(T1."Account",4)='5101'
		GROUP BY LEFT(T0."RefDate",7),T0."TransCode"
		
		) T0
		
	GROUP BY T0."期间"
	ORDER BY T0."期间"
	;
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO401101
CREATE PROCEDURE "MTC_RPT_CO401101"
(
  IN OrdType NVARCHAR(50) ,  --生产工单/委外工单
  IN STYPE INT,	--0汇总  1明细 3对比表
  IN sdate DATE,
  IN edate DATE,
  IN ItemCode NVARCHAR(50)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	
	TMP_DETAIL=
	SELECT T6."CardCode",T6."CardName",T1."U_SupNum",'202' AS "WorType" --"生产订单类型"
	,CASE T1."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' 
	WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END AS "OcdType" --"工单类型"
	,T1."DocEntry" AS "OWOREntry"
	,T1."DocNum" AS "OWORNum"
	,CASE T1."Status" WHEN 'P' THEN '已计划' WHEN 'R' THEN '已下达' WHEN 'L' THEN '已结算' WHEN 'C' THEN '已取消' END AS "Status"
	,T0."IgnQty"
	,T1."CloseDate"
	,T1."PostDate"
	,T4."ItemCode"
	,T5."ItemName"
	,T5."U_Specs"
	,T5."InvntryUom"
	,T2."PlannedQty"/T1."PlannedQty" AS "Prc"	--料比
	,-1*T4."IgeQty" AS "InQty"  --领料发出
	,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" AS "OutQty" --"倒冲入库"
	,IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0) AS "InvntQty" -- "结存数量"
	,CASE WHEN T1."CloseDate"<=:edate AND T1."Status" IN ('C','L') THEN 0
			ELSE IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0)
			END AS "ActInvntQty" -- "结存数量"
	,T10."Price" AS "InvntPrice" --"单价"
	,CASE WHEN T1."CloseDate"<=:edate AND T1."Status" IN ('C','L') THEN 0
		ELSE (IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0))*IFNULL(T10."Price",0)
		END AS "InvntAmt"  --"结存金额"
	FROM OWOR T1
	JOIN (SELECT "DocEntry","ItemCode",SUM("PlannedQty") AS "PlannedQty"
			FROM WOR1 GROUP BY "DocEntry","ItemCode") T2 ON T1."DocEntry"=T2."DocEntry"
	LEFT JOIN (SELECT "OWOREntry","OWORNum"
			,SUM("Quantity") AS "IgnQty"
			FROM "MTC_VIEW_ProductDetail"
			WHERE 1=1 AND "Type"='主件' AND "DocDate"<=:edate
			GROUP BY "OWOREntry","OWORNum"
			) T0 ON T0."OWOREntry"=T1."DocEntry"
	JOIN (SELECT "OWOREntry","OWORNum","ItemCode",SUM("Quantity") AS "IgeQty"
			FROM "MTC_VIEW_ProductDetail"
			WHERE "Type"='子件' AND "DocDate"<=:edate
			GROUP BY "OWOREntry","OWORNum","ItemCode" 
		) T4 ON T2."DocEntry"=T4."OWOREntry" AND T2."ItemCode"=T4."ItemCode"
	LEFT JOIN OCRD T6 ON T1."U_CardCode"=T6."CardCode"
	LEFT JOIN OITM T5 ON T2."ItemCode"=T5."ItemCode"
	LEFT JOIN (SELECT "ItemCode","Price",ROW_NUMBER() OVER(PARTITION BY "ItemCode" ORDER BY "FcCode" DESC) AS "ID"
				FROM MTC_COST_0301_INVNT 
				WHERE "FcCode"<=TO_CHAR(:edate,'YYYY-MM') AND "CostCode"='20' AND "Price"<>0
				) T10 ON T5."ItemCode"=T10."ItemCode" AND T10."ID"=1
	WHERE 1=1
	AND T1."U_OrdType" NOT IN ('40')
	AND ((:OrdType='生产工单' AND T1."U_OrdType" IN ('10','20','30'))
			OR (:OrdType='委外工单' AND T1."U_OrdType"='50')
			)
	AND IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0)<>0
	
	UNION ALL
	SELECT T6."CardCode",T6."CardName",T1."U_SupNum",T1."Object" AS "生产订单类型"
	,CASE T1."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' 
	WHEN 40 THEN '生产试打' WHEN 50 THEN '委外工单' END AS "工单类型",T1."DocEntry" AS "OWOREntry",T1."DocNum" AS "OWORNum"
	,CASE T1."U_Status" WHEN 'P' THEN '已计划' WHEN 'R' THEN '已下达' WHEN 'L' THEN '已结算' WHEN 'C' THEN '已取消' END AS "U_Status",T0."IgnQty"
	,T1."U_CloseDate" AS "CloseDate",T1."U_PostDate" AS "PostDate"
	,T4."ItemCode",T5."ItemName"
	,T5."U_Specs"
	,T5."InvntryUom",T2."PlannedQty"/T1."U_PlannedQty" AS "料比"
	,-1*T4."IgeQty" AS "领料发出"
	,T0."IgnQty"*T2."PlannedQty"/T1."U_PlannedQty" AS "倒冲入库"
	,IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."U_PlannedQty",0) AS "结存数量"
	,CASE WHEN T1."U_CloseDate"<=:edate AND T1."U_Status" IN ('C','L') THEN 0 
		ELSE IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."U_PlannedQty",0)
		END AS "计入结存数量"
	,T10."Price"
	,CASE WHEN T1."U_CloseDate"<=:edate AND T1."U_Status" IN ('C','L') THEN 0 
		ELSE (IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."U_PlannedQty",0))*IFNULL(T10."Price",0)
		END AS "结存金额"
	FROM "@MTC_OWOR" T1
	JOIN (SELECT "DocEntry","U_ItemCode" AS "ItemCode",SUM("U_PlannedQty") AS "PlannedQty"
			FROM "@MTC_WOR1" GROUP BY "DocEntry","U_ItemCode") T2 ON T1."DocEntry"=T2."DocEntry"
	LEFT JOIN (SELECT "BaseEntry" AS "OWOREntry"
			,SUM("Quantity") AS "IgnQty"
			FROM "MTC_VIEW_ProductDetail_MTCOWOR"
			WHERE 1=1 AND "Type"='主件' AND "DocDate"<=:edate
			GROUP BY "BaseEntry"
			) T0 ON T0."OWOREntry"=T1."DocEntry"
	JOIN (SELECT "BaseEntry" AS "OWOREntry","ItemCode" AS "ItemCode",SUM("Quantity") AS "IgeQty"
			FROM "MTC_VIEW_ProductDetail_MTCOWOR"
			WHERE "Type"='子件' AND "DocDate"<=:edate
			GROUP BY "BaseEntry","ItemCode" 
		) T4 ON T2."DocEntry"=T4."OWOREntry" AND T2."ItemCode"=T4."ItemCode"
	LEFT JOIN OCRD T6 ON T1."U_CardCode"=T6."CardCode"
	LEFT JOIN OITM T5 ON T2."ItemCode"=T5."ItemCode"
	LEFT JOIN (SELECT "ItemCode","Price",ROW_NUMBER() OVER(PARTITION BY "ItemCode" ORDER BY "FcCode" DESC) AS "ID"
				FROM MTC_COST_0301_INVNT 
				WHERE "FcCode"<=TO_CHAR(:edate,'YYYY-MM') AND "CostCode"='20' AND "Price"<>0
				) T10 ON T5."ItemCode"=T10."ItemCode" AND T10."ID"=1
	WHERE 1=1
	AND T1."U_OrdType" NOT IN ('40')
	AND ((:OrdType='生产工单' AND T1."U_OrdType" IN ('10','20','30'))
			OR (:OrdType='委外工单' AND T1."U_OrdType"='50')
			)
	AND IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."U_PlannedQty",0)<>0
	
	ORDER BY T1."PostDate";
	
	IF :STYPE = 2 THEN
		SELECT 
		T0."U_SupNum"
		,T0."WorType" 	--"生产订单类型"
		,T0."OcdType" 			--"工单类型"
		,T0."OWOREntry"
		,T0."OWORNum"
		,T0."Status"
		,T0."CloseDate"
		,T0."PostDate"
		,SUM(T0."InQty") AS "InQty"  			--领料发出
		,SUM(T0."OutQty") AS "OutQty" 			--"倒冲入库"
		,SUM(T0."InvntQty") AS "InvntQty" 			-- "结存数量"
		,SUM(T0."ActInvntQty") AS "ActInvntQty" 			-- "结存数量"
		--,T0."InvntPrice" 		--"单价"
		,SUM(T0."InvntAmt") AS "InvntAmt"
		,T0."CardCode",T0."CardName"
		FROM :TMP_DETAIL T0
		GROUP BY T0."U_SupNum",T0."WorType" 	--"生产订单类型"
		,T0."OcdType" 			--"工单类型"
		,T0."OWOREntry"
		,T0."OWORNum"
		,T0."Status"
		,T0."CloseDate"
		,T0."PostDate"--,T0."InvntPrice"
		,T0."CardCode",T0."CardName"
		ORDER BY T0."PostDate"
		;
		
	ELSEIF :STYPE = 1 THEN 
		SELECT T0."U_SupNum",T0."WorType" 	--"生产订单类型"
		,T0."OcdType" 			--"工单类型"
		,T0."OWOREntry"
		,T0."OWORNum"
		,T0."Status"
		,T0."IgnQty"
		,T0."CloseDate"
		,T0."PostDate"
		,T0."ItemCode"
		,T0."ItemName"
		,T0."U_Specs"
		,T0."InvntryUom"
		,T0."Prc"				--料比
		,T0."InQty"  			--领料发出
		,T0."OutQty" 			--"倒冲入库"
		,T0."InvntQty" 			-- "结存数量"
		,T0."ActInvntQty" 			-- "结存数量"
		,T0."InvntPrice" 		--"单价"
		,T0."InvntAmt"
		,T0."CardCode",T0."CardName"
		FROM :TMP_DETAIL T0
		ORDER BY T0."PostDate"
		;
	ELSEIF :STYPE = 3 THEN
	
		TMP_OJDT = 
		SELECT T2."AcctCode",T2."AcctName",SUM(T1."Debit"-T1."Credit") AS "OJDTAmt"
		FROM "OJDT" T0
		JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
		JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
		WHERE T0."RefDate"<=:edate
		AND T2."AcctCode"='500101'
		GROUP BY T2."AcctCode",T2."AcctName"
		;
		
		SELECT 
		TO_CHAR(:edate,'YYYY-MM') AS "期间"
		,T0."PrjName" AS "项目"
		,SUM(T0."InvntAmt") AS "在产品结存金额"
		,SUM(T0."OJDTAmt") AS "分录结存金额"
		,SUM(T0."InvntAmt")-SUM(T0."OJDTAmt") AS "差异"
		FROM (
			SELECT '生产成本-在产品' AS "PrjName",SUM(T0."InvntAmt") AS "InvntAmt",0.00 AS "OJDTAmt"
			FROM :TMP_DETAIL T0
			WHERE T0."InvntQty">0
			UNION ALL
			SELECT '生产成本-在产品' AS "PrjName",0.00 AS "InvntAmt",SUM("OJDTAmt") AS "OJDTAmt" FROM :TMP_OJDT
			) T0
		GROUP BY T0."PrjName";
		
	END IF;
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO4013
CREATE PROCEDURE "MTC_RPT_CO4013"
(
  IN STYPE INT,	--0汇总  1明细
  IN sdate DATE,
  IN edate DATE,
  IN ItemCode NVARCHAR(50)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	--CALL "MTC_RPT_CO4013"('2025-06-01','2025-06-30','')
	
	TMP_QC=
	SELECT -1 AS "ObjType"
	,T1."DocEntry",T1."DocEntry" AS "DocNum"
	,'202' AS "WorType",-1 AS "WorEntry",-1 AS "WorNum",'50' AS "U_OrdType",'' AS "Status",'2024-12-31' AS "DocDate"
	,T2."CardCode",T2."CardName",T1."U_Text1" AS "ItemCode"
	--,T2."PlannedQty" AS "子件计划数量"
	,T1."U_Dec1" AS "S_IgeQty"
	,0.00 AS "Due_IgeQty"
	,0.00 AS "E_IgeQty"
	,0.00 AS "S_IgnQty"
	,0.00 AS "Due_IgnQty"
	,-1*T1."U_Dec1" AS "E_IgnQty"
	FROM "@MTC_IMPT1" T1
	LEFT JOIN OCRD T2 ON T1."U_Text2"=T2."CardCode"
	WHERE T1."DocEntry"=10;
	
	TMP_In=
	SELECT T0."ObjType",T0."DocEntry",T0."DocNum",'202' AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum",T1."U_OrdType",T1."Status",T0."DocDate"
	,T3."CardCode",T3."CardName",T0."ItemCode"
	--,T2."PlannedQty" AS "子件计划数量"
	,T0."S_IgeQty"
	,T0."Due_IgeQty"
	,T0."E_IgeQty"
	,0.00 AS "S_IgnQty"
	,0.00 AS "Due_IgnQty"
	,0.00 AS "E_IgnQty"
	FROM (SELECT "ObjType","DocEntry","DocNum","OWOREntry","OWORNum","ItemCode","DocDate"
			,-1*(CASE WHEN "DocDate"<:sdate THEN "Quantity" ELSE 0 END) AS "S_IgeQty"
			,-1*(CASE WHEN "DocDate">=:sdate AND "DocDate"<=:edate THEN "Quantity" ELSE 0 END) AS "Due_IgeQty"
			,-1*(CASE WHEN "DocDate"<=:edate THEN "Quantity" ELSE 0 END) AS "E_IgeQty"
			FROM "MTC_VIEW_ProductDetail"
			WHERE "DocDate"<=:edate AND "ID"<>3 AND "Type"='子件'
			AND "DocDate">='2025-01-01'
			 --GROUP BY "OWOREntry","OWORNum","ItemCode"
			) T0
	LEFT JOIN OWOR T1 ON T0."OWOREntry"=T1."DocEntry"
	LEFT JOIN OCRD T3 ON T1."U_CardCode"=T3."CardCode"
	WHERE 1=1
	AND T1."U_OrdType"='50'
	--AND T1."DocNum"=301
	;
	
	TMP_Out=
	SELECT T0."ObjType",T0."DocEntry",T0."DocNum",'202' AS "WorType",T1."DocEntry" AS "WorEntry",T1."DocNum" AS "WorNum",T1."U_OrdType",T1."Status",T0."DocDate"
	--,T0."IgnQty" AS "主件实际领料",T1."PlannedQty" AS "主件计划数量"
	,T3."CardCode",T3."CardName",T2."ItemCode"
	--,T2."PlannedQty" AS "子件计划数量"
	,0.00 AS "S_IgeQty"
	,0.00 AS "Due_IgeQty"
	,0.00 AS "E_IgeQty"
	,T0."S_IgnQty"*T2."PlannedQty"/T1."PlannedQty"
	,T0."Due_IgnQty"*T2."PlannedQty"/T1."PlannedQty"
	,T0."E_IgnQty"*T2."PlannedQty"/T1."PlannedQty"
	FROM (SELECT "ObjType","DocEntry","DocNum","OWOREntry","OWORNum","DocDate"
			,(CASE WHEN "DocDate"<:sdate THEN "Quantity" ELSE 0 END) AS "S_IgnQty"
			,(CASE WHEN "DocDate">=:sdate AND "DocDate"<=:edate THEN "Quantity" ELSE 0 END) AS "Due_IgnQty"
			,(CASE WHEN "DocDate"<=:edate THEN "Quantity" ELSE 0 END) AS "E_IgnQty"
			FROM "MTC_VIEW_ProductDetail"
			WHERE "DocDate"<=:edate AND "Type"='主件'
			AND "DocDate">='2025-01-01' --GROUP BY "OWOREntry","OWORNum"
			) T0
	LEFT JOIN OWOR T1 ON T0."OWOREntry"=T1."DocEntry"
	LEFT JOIN WOR1 T2 ON T1."DocEntry"=T2."DocEntry"
	LEFT JOIN OCRD T3 ON T1."U_CardCode"=T3."CardCode"
	WHERE 1=1
	AND T1."U_OrdType"='50'
	--AND T1."DocNum"=301
	;
	
	--汇总
	IF :STYPE = 0 THEN
	
		SELECT 
		 T0."CardCode",T0."CardName",T0."ItemCode",T1."ItemName"
		,SUM(IFNULL(T0."S_IgeQty",0)-IFNULL(T0."S_IgnQty",0)) AS "期初数量"
		,SUM(IFNULL(T0."Due_IgeQty",0)) AS "委外发出(入库)"
		,SUM(IFNULL(T0."Due_IgnQty",0)) AS "委外收回(出库)"
		,SUM(IFNULL(T0."E_IgeQty",0)-IFNULL(T0."E_IgnQty",0)) AS "期末数量"
		,:sdate AS sdate
		,:edate AS edate
		FROM (
			SELECT * FROM :TMP_QC
			UNION ALL
			SELECT * FROM :TMP_In
			UNION ALL
			SELECT * FROM :TMP_Out
			) T0
		LEFT JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
		--LEFT JOIN (SELECT * FROM MTC_COST_0301_INVNT WHERE "FcCode"='[%0]' AND "CostCode"='20') T1 ON T0."ItemCode"=T1."ItemCode"
		WHERE 1=1
		AND T1."InvntItem"='Y'
		GROUP BY T0."CardCode",T0."CardName",T0."ItemCode",T1."ItemName"
		ORDER BY T0."CardCode",T0."ItemCode"
		;
	--明细
	ELSEIF :STYPE = 1 THEN
	
		SELECT T0."类型",T0."ObjType",T0."DocEntry",T0."DocNum" AS "出入库单号",T0."DocDate" AS "日期",T0."WorEntry" AS "生产订单号Entry",T0."WorNum" AS "生产订单号Num"
		,T0."CardCode",T0."CardName",T0."ItemCode"
		,T0."Due_IgeQty" AS "委外发出(入库)"
		,T0."Due_IgnQty" AS "委外收回(出库)"
		 FROM (
			SELECT '期初' AS "类型",* FROM :TMP_QC
			UNION ALL
			SELECT '材料领用' AS "类型",* FROM :TMP_In WHERE "DocDate">=:sdate AND "DocDate"<=:edate
			UNION ALL
			SELECT '入库倒冲' AS "类型",* FROM :TMP_Out  WHERE "DocDate">=:sdate AND "DocDate"<=:edate
			) T0 WHERE (T0."ItemCode"=:ItemCode OR :ItemCode = '')
			ORDER BY T0."ItemCode",T0."DocDate",T0."DocEntry"
			;
	--按订单汇总
	ELSEIF :STYPE = 2 THEN
	
		SELECT 
		T0."WorType" AS "生产订单类型"
		,CASE T0."U_OrdType" WHEN 10 THEN '生产计划单' WHEN 20 THEN '包装计划单' WHEN 30 THEN '返工计划单' WHEN 40 
			THEN '生产试打' WHEN 50 THEN '委外工单' END AS "工单类型"
		,T0."WorEntry" AS "生产订单号Entry",T0."WorNum" AS "生产订单号Num"
		,CASE WHEN T1."Status"='R' THEN '已下达' WHEN T1."Status"='L' THEN '已结算' WHEN T1."Status"='P' THEN '已计划' END AS "生产订单状态"
		,T1."CloseDate" AS "生产订单关闭日期"
		,T0."CardCode",T0."CardName",T0."ItemCode",T5."ItemName"
		,SUM(CASE WHEN T0."类型"='期初' THEN IFNULL(T0."Due_IgeQty",0)-IFNULL(T0."Due_IgnQty",0) ELSE 0 END) AS "期初数量"
		,SUM(T0."Due_IgeQty") AS "委外发出(入库)"
		,SUM(T0."Due_IgnQty") AS "委外收回(出库)"
		,SUM(IFNULL(T0."Due_IgeQty",0)-IFNULL(T0."Due_IgnQty",0)) AS "库存数量"
		 FROM (
			SELECT '期初' AS "类型",* FROM :TMP_QC
			UNION ALL
			SELECT '材料领用' AS "类型",* FROM :TMP_In WHERE "DocDate">=:sdate AND "DocDate"<=:edate
			UNION ALL
			SELECT '入库倒冲' AS "类型",* FROM :TMP_Out  WHERE "DocDate">=:sdate AND "DocDate"<=:edate
			) T0
		LEFT JOIN (SELECT '202' AS "ObjType","DocEntry","DocNum","Status","CloseDate" FROM OWOR 
			) T1 ON T0."WorType"=T1."ObjType" AND T0."WorEntry"=T1."DocEntry"
		LEFT JOIN OITM T5 ON T0."ItemCode"=T5."ItemCode"
		WHERE (T0."ItemCode"=:ItemCode OR :ItemCode = '')
		GROUP BY T0."WorType",T0."U_OrdType",T0."WorEntry",T0."WorNum",T1."Status",T1."CloseDate",T0."CardCode",T0."CardName",T0."ItemCode",T5."ItemName"
			ORDER BY T0."ItemCode",T0."WorEntry"
			;
	
	--从订单角度看
	ELSEIF :STYPE = 3 THEN 
		SELECT T6."CardCode",T6."CardName"
		,T1."DocEntry" AS "OWOREntry",T1."DocNum" AS "OWORNum"
		,T0."IgnQty"
		,T1."CloseDate",T1."PostDate"
		,T4."ItemCode",T5."ItemName",T5."U_Specs" AS "规格",T5."InvntryUom" AS "单位"
		,T2."PlannedQty"/T1."PlannedQty" AS "料比"
		,-1*T4."IgeQty" AS "领料发出"
		,T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty" AS "倒冲入库"
		,IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0) AS "结存数量"
		,T10."Price" AS "结存单价"
		,(IFNULL(-1*T4."IgeQty",0)-IFNULL(T0."IgnQty"*T2."PlannedQty"/T1."PlannedQty",0))*IFNULL(T10."Price",0) AS "结存金额"
			FROM OWOR T1
			JOIN (SELECT "DocEntry","ItemCode",SUM("PlannedQty") AS "PlannedQty"
					FROM WOR1 GROUP BY "DocEntry","ItemCode") T2 ON T1."DocEntry"=T2."DocEntry"
			LEFT JOIN (SELECT "OWOREntry","OWORNum"
					,SUM("Quantity") AS "IgnQty"
					FROM "MTC_VIEW_ProductDetail"
					WHERE 1=1 AND "Type"='主件' AND "DocDate"<=:edate
					GROUP BY "OWOREntry","OWORNum"
					) T0 ON T0."OWOREntry"=T1."DocEntry"
			JOIN (SELECT "OWOREntry","OWORNum","ItemCode",SUM("Quantity") AS "IgeQty"
					FROM "MTC_VIEW_ProductDetail"
					WHERE "Type"='子件' AND "DocDate"<=:edate
					GROUP BY "OWOREntry","OWORNum","ItemCode" 
				) T4 ON T2."DocEntry"=T4."OWOREntry" AND T2."ItemCode"=T4."ItemCode"
			LEFT JOIN OCRD T6 ON T1."U_CardCode"=T6."CardCode"
			LEFT JOIN OITM T5 ON T2."ItemCode"=T5."ItemCode"
			LEFT JOIN (SELECT "ItemCode","Price",ROW_NUMBER() OVER(PARTITION BY "ItemCode" ORDER BY "FcCode" DESC) AS "ID"
						FROM MTC_COST_0301_INVNT 
						WHERE "FcCode"<=TO_CHAR(:edate,'YYYY-MM') AND "CostCode"='20' AND "Price"<>0
						) T10 ON T5."ItemCode"=T10."ItemCode" AND T10."ID"=1
			WHERE 1=1
			AND T1."U_OrdType"='50'
			
			ORDER BY T1."PostDate";
	END IF;
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO6001
CREATE PROCEDURE "MTC_RPT_CO6001"
(
  UserId INT,
  FcCode NVARCHAR(30),
  IsOBTF NVARCHAR(10) --是否包含凭单
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 


	TMP_YW=
	SELECT 
	T4."AcctCode",
	T4."AcctName",
	SUM(ROUND(T0."QM_Amount",2)) AS "QM_Amount"
	FROM MTC_COST_0301_INVNT T0
	JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
	LEFT JOIN OITB T2 ON T0."ItmsGrpCod"=T2."ItmsGrpCod"
	LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct",MAX("ShpdGdsAct") AS "ShpdGdsAct"
			FROM OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
		) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
	LEFT JOIN "OACT" T4 ON T3."StockAct"=T4."AcctCode"
	WHERE T0."FcCode" = :FcCode
	--AND T1."InvntItem"='Y'
	AND T0."CostCode"='20'
	GROUP BY T0."FcCode",
	T4."AcctCode",
	T4."AcctName"
	
	--业务端的归集的制造费用和人工费用
	UNION ALL	
	SELECT "AcctCode","AcctName"
	,SUM(ROUND("Amount",2)) AS "Amount"
	FROM MTC_COST_0311_PRODUCTEXP_ADD
	WHERE "FcCode"=:FcCode
	AND IFNULL("Amount",0)<>0
	GROUP BY "AcctCode","AcctName"
	
	
	--业务端的归集的制造费用（500103）
	UNION ALL	
	SELECT T3."AcctCode",T3."AcctName"
	,SUM(ROUND(T0."Amount",2)) AS "Amount"
	FROM MTC_COST_0311_PRODUCTEXP_ADD T0
	LEFT JOIn "OACT" T3 ON T3."AcctCode"='500103'
	WHERE "FcCode"=:FcCode
	AND IFNULL("Amount",0)<>0
	AND LEFT(T0."AcctCode",4)='5101'
	GROUP BY T3."AcctCode",T3."AcctName"
	
	--在产品
	UNION ALL
	SELECT  
	T3."AcctCode",T3."AcctName"
	,SUM(ROUND(IFNULL(T0."在产品新",0),2)) AS "在产品金额"
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	LEFT JOIN OACT T3 ON CASE WHEN T0."WorType" IN ('10','20','30') THEN '500101' WHEN T0."WorType"='50' THEN '140801' END=T3."AcctCode"
	WHERE T0."期间"=:FcCode
	GROUP BY T3."AcctCode",T3."AcctName"
	;
	
	TMP_OJDT=
	SELECT T2."AcctCode",T2."AcctName",SUM(T1."Debit"-T1."Credit") AS "CW_Amount"
	FROM "OJDT" T0
	JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
	JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
	--JOIN "OFPR" T3 ON T0."RefDate" BETWEEN T3."F_RefDate" AND T3."T_RefDate"
	WHERE 1=1
	--去掉调整交易
	--AND T0."AdjTran"='N'
	AND LEFT(T0."RefDate",7)<=:FcCode
	AND (LEFT(T2."AcctCode",4) IN ('1403','1404','1405','1406','1408','1409') OR T2."AcctCode"='500101')
	GROUP BY T2."AcctCode",T2."AcctName"
	
	--期初发出商品金额减掉
	UNION ALL
    SELECT T2."AcctCode",T2."AcctName",-1*SUM(T1."Debit"-T1."Credit") AS "CW_Amount"
	FROM "OJDT" T0
	JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
	JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
	--JOIN "OFPR" T3 ON T0."RefDate" BETWEEN T3."F_RefDate" AND T3."T_RefDate"
	WHERE 1=1
	--去掉调整交易
	--AND T0."AdjTran"='N'
	AND LEFT(T0."RefDate",7)<:FcCode
	AND LEFT(T2."AcctCode",4) IN ('1406')
	GROUP BY T2."AcctCode",T2."AcctName"
	
	--5101制造费用排除掉结转制造费用的分录（PP04）
	UNION ALL
	SELECT T2."AcctCode",T2."AcctName",SUM(T1."Debit"-T1."Credit") AS "CW_Amount"
	FROM "OJDT" T0
	JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
	JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
	--JOIN "OFPR" T3 ON T0."RefDate" BETWEEN T3."F_RefDate" AND T3."T_RefDate"
	WHERE 1=1
	--去掉调整交易
	--AND T0."AdjTran"='N'
	AND (LEFT(T0."RefDate",7)<:FcCode OR (LEFT(T0."RefDate",7)=:FcCode AND IFNULL(T0."TransCode",'') NOT IN ('PP04')))
	AND LEFT(T2."AcctCode",4) IN ('5101')
	GROUP BY T2."AcctCode",T2."AcctName"
	
	--5001排除掉5001开头的，需要取PP04
	UNION ALL
	SELECT T2."AcctCode",T2."AcctName",SUM(T1."Debit"-T1."Credit") AS "CW_Amount"
	FROM "OJDT" T0
	JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
	JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
	--JOIN "OFPR" T3 ON T0."RefDate" BETWEEN T3."F_RefDate" AND T3."T_RefDate"
	WHERE 1=1
	--去掉调整交易
	--AND T0."AdjTran"='N'
	AND (LEFT(T0."RefDate",7)<:FcCode OR (LEFT(T0."RefDate",7)=:FcCode AND IFNULL(T0."TransCode",'') IN ('PP04','')))
	AND T2."AcctCode" IN ('500102','500103')
	GROUP BY T2."AcctCode",T2."AcctName"
	;
	
	TMP_MTC_COST_0801_TOOJDT=
	SELECT "AcctCode","AcctName",SUM("Debit"-"Credit") AS "0801Amount"
	FROM MTC_COST_0801_TOOJDT
	WHERE "FcCode"=:FcCode
	AND LEFT("AcctCode",4) IN ('1403','1404','1405','1406','1408','1409','5101','5001')
	--排除结转制造费用的分录
	AND "TransCode" NOT IN ('PP04')
	GROUP BY "AcctCode","AcctName"
	;
	
	
	TMP_OpenOBTF=
	SELECT T2."AcctCode",T2."AcctName"
    ,SUM(IFNULL(T1."Debit",0)-IFNULL(T1."Credit",0)) AS "BtfAmount"   ---金额
    FROM OBTF T0
    JOIN BTF1 T1 ON T0."TransId" = T1."TransId" AND T0."BatchNum" = T1."BatchNum"
    JOIN OACT T2 ON T1."Account" = T2."AcctCode"
    WHERE T0."BtfStatus"='O'
    AND LEFT(T0."RefDate",7)=:FcCode
	AND LEFT("AcctCode",4) IN ('1403','1404','1405','1406','1408','1409','5101','5001')
	--排除结转制造费用的分录
	AND T0."TransCode" NOT IN ('PP04')
     GROUP BY T2."AcctCode",T2."AcctName"
	;
	
	SELECT 
	:FcCode AS "FcCode",CASE WHEN LEFT(T0."AcctCode",4) IN ('1403','1404','1405','1408','1409') OR T0."AcctCode"='500101'
	  THEN '核对余额'
	ELSE '核对发生额'
	END AS "核对口径"
	,T0."AcctCode",T2."AcctName" AS "科目名称"
	,SUM(T0."QM_Amount") AS "业务余额"
	,SUM(T0."CW_Amount") AS "财务余额"
	,SUM(IFNULL(T0."QM_Amount",0))-SUM(IFNULL(T0."CW_Amount",0)) AS "差异金额[业务-财务]"
	,SUM(T0."0801Amount") AS "中间分录发生额"
	,SUM(IFNULL(T0."QM_Amount",0))-SUM(IFNULL(T0."CW_Amount",0))-SUM(T0."0801Amount") AS "差异金额[业务-财务-中间表]"
	,SUM(T0."BtfAmount") AS "凭单发生额"
	,SUM(IFNULL(T0."QM_Amount",0))-SUM(IFNULL(T0."CW_Amount",0))-SUM(T0."BtfAmount") AS "差异金额[业务-财务-凭单表]"
	FROM
	(
		SELECT "AcctCode","AcctName","QM_Amount",0 AS "CW_Amount",0 AS "0801Amount",0 AS "BtfAmount"  FROM :TMP_YW
		UNION ALL
		SELECT "AcctCode","AcctName",0 AS "QM_Amount","CW_Amount",0,0 FROM :TMP_OJDT
		UNION ALL
		SELECT "AcctCode","AcctName",0 AS "QM_Amount",0 AS "CW_Amount","0801Amount",0 AS "BtfAmount"
		FROM :TMP_MTC_COST_0801_TOOJDT
		UNION ALL
		SELECT "AcctCode","AcctName",0 AS "QM_Amount",0 AS "CW_Amount",0,"BtfAmount" AS "BtfAmount"
		FROM :TMP_OpenOBTF
	) T0
	LEFT JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
	GROUP BY T0."AcctCode",T2."AcctName",CASE WHEN LEFT(T0."AcctCode",4) IN ('1403','1404','1405','1406','1408','1409','5001') OR T0."AcctCode"='500101'
	  THEN '核对余额'
	ELSE '核对发生额'
	END
	ORDER BY T0."AcctCode"
	;

END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO8002
CREATE PROCEDURE "MTC_RPT_CO8002"
(
  BPLId NVARCHAR(10),
  FcCode NVARCHAR(30),
  UserId INT
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 

	DECLARE EndDate DATE;
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	
	SELECT :FcCode AS "FcCode",T1."U_Type" AS "报表类型",T1."U_RptCode",T1."U_RptName" AS "报表名称"
	,CASE WHEN T11."TransId" IS NOT NULL THEN '已冲销,' ELSE '' END || T1."U_RptCode" AS "Re"
	,T11."TransId" AS "ReJDTId"
	,CASE WHEN T1."U_RptCode" LIKE 'JC%' THEN NULL
		WHEN T21."TransId" IS NOT NULL OR T22."TransId" IS NOT NULL THEN '已结转,' ELSE '' END || T1."U_RptCode"
		AS "JZ"
	,COALESCE(T21."TransId",'凭单号'||T22."TransId") AS "JZJDTId"	
	,T1."U_Notes" AS "说明",:EndDate AS "EndDate"
	,CASE WHEN T1."U_RptCode"='AR01' THEN '100' WHEN T1."U_RptCode" IN ('AR02','JE02') THEN '106' END AS "GroupCode"
	,T1."U_OrderBy"
	,T1."U_Proc" AS "来源"
	,T1."U_IsRev"
	FROM "@MTC_BRPT" T0
	JOIN "@MTC_BRPT1" T1 ON T0."Code"=T1."Code"
	LEFT JOIN (SELECT T0."TransCode",STRING_AGG("TransId",',') AS "TransId" FROM "OJDT" T0
				WHERE LEFT(T0."RefDate",7)=:FcCode
						AND EXISTS(SELECT 1 FROM OJDT P0
							WHERE P0."TransId"=T0."StornoToTr") GROUP BY T0."TransCode"
			) T11 ON T1."U_RptCode"=T11."TransCode"
	LEFT JOIN (SELECT "TransCode",STRING_AGG("TransId",',') AS "TransId" FROM "OJDT" T0
				WHERE LEFT("RefDate",7)=:FcCode AND "StornoToTr" IS NULL
				AND NOT EXISTS(SELECT 1 FROM OJDT P0
							WHERE T0."TransId"=P0."StornoToTr")
				AND "TransId">33641
				GROUP BY "TransCode"
			) T21 ON T1."U_RptCode"=T21."TransCode"
	LEFT JOIN (SELECT "TransCode",STRING_AGG("BatchNum",',') AS "TransId" FROM "OBTF" 
				WHERE LEFT("RefDate",7)=:FcCode AND "BatchNum">622 AND "Memo" NOT LIKE '%2026-07%' GROUP BY "TransCode"
			) T22 ON T1."U_RptCode"=T22."TransCode"
	WHERE T0."Code"='JZ'
	AND T1."U_Status"='Y'
--AND EXISTS(SELECT 1 FROM OUSR P0 LEFT JOIN USR7 P1 ON P0."USERID"=P1."UserId" LEFT JOIN "@MTC_BRPT2" P2 ON P1."GroupId"=P2."U_UserCode"      
--WHERE 1=1 AND (P0."SUPERUSER"='Y' OR (IFNULL(P2."U_UserCode",'')<>'' AND P2."Code"=T0."Code")) AND P0."USERID"=$[USER] )
	ORDER BY T1."U_OrderBy";
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO8002.JC01
CREATE PROCEDURE "MTC_RPT_CO8002.JC01"
(
  BPLId NVARCHAR(10),
  FcCode NVARCHAR(30),
  UserId INT
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 

	DECLARE EndDate DATE;
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	
	TMP_OJDT=
	SELECT T2."AcctCode",T2."AcctName"
	,SUM(T1."Debit"-T1."Credit") AS "Amt"
	FROM "OJDT" T0
	JOIN JDT1 T1 ON T0."TransId"=T1."TransId"
	JOIN OACT T2 ON T1."Account"=T2."AcctCode"
	WHERE 1=1
	AND LEFT(T0."RefDate",7)=:FcCode
	GROUP BY T2."AcctCode",T2."AcctName"
	;
	
	TMP_JZ=
	SELECT 
	T0."TransCode",
	T0."TransName",
	T1."AcctCode",
	T1."AcctName",
	SUM(IFNULL("Debit",0)-IFNULL("Credit",0)) AS "Amt"
	FROM MTC_COST_0801_TOOJDT T0
	JOIN "OACT" T1 ON T0."AcctCode"=T1."AcctCode"
	WHERE T0."FcCode"='2025-04' --AND "TransCode"=:TransCode
	GROUP BY T0."TransCode",
	T0."TransName",
	T1."AcctCode",
	T1."AcctName"
	;
	
	CREATE LOCAL TEMPORARY TABLE #Pro(
	 "ID" INT
	,"项目" NVARCHAR(100)
	,"科目编码" NVARCHAR(50)
	,"科目名称" NVARCHAR(100)
	,"金额" DECIMAL(19,6)
	);
	
	INSERT INTO #Pro
	SELECT 1001,'收入',"AcctCode","AcctName",-1*"Amt" FROM :TMP_OJDT WHERE "AcctCode" LIKE '6001%'
	UNION ALL
	SELECT 2001,'成本',"AcctCode","AcctName","Amt" FROM :TMP_OJDT WHERE "AcctCode" LIKE '6401%'
	;
	
	SELECT * FROM #PRO ORDER BY "ID";
	
	DROP TABLE #PRO;
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO8003
CREATE PROCEDURE "MTC_RPT_CO8003"
(
  FcCode NVARCHAR(30)
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 

	SELECT 
	--主表
	T0."DocEntry"				
	,T0."U_FcCode" "期间"
	,T0."U_RefDate" "过账日期"	
	,'打开明细' AS "打开明细"	
	,T0."U_TransId" "分录"		
	,T0."U_RevOJDT" "取消日记账分录"		
	,T0."U_TransCode" "交易代码"	
	,T3."TrnsCodDsc" AS "交易名称"	
	,T0."U_Memo" "备注"			
	,T0."U_IsRev" "是否下月冲销"		
	,T0."U_RevDate" "冲销日期"
	,T1."U_Debit" AS "分录的借方金额"
	,T1."U_Credit" AS "分录的贷方金额"	
	,T2."U_GTotal" AS "业务端静态表金额"
	,T0."Remark" "备注1"
	FROM "@MTC_COST_OJDT" T0
	LEFT JOIN (	
			SELECT "DocEntry",SUM("U_Debit") AS "U_Debit",SUM("U_Credit") AS "U_Credit"
			FROM "@MTC_COST_OJDT1" GROUP BY "DocEntry"
		) T1 ON T1."DocEntry"=T0."DocEntry"
	LEFT JOIN (	
			SELECT "DocEntry",SUM("U_GTotal") AS "U_GTotal"
			FROM "@MTC_COST_OJDT2" GROUP BY "DocEntry"
		) T2 ON T2."DocEntry"=T0."DocEntry"
	LEFT JOIN OTRC T3 ON T3."TrnsCode"=T0."U_TransCode"
	WHERE 1=1
	AND T0."U_FcCode"=:FcCode
	ORDER BY T0."DocEntry";
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_CO800301
CREATE PROCEDURE "MTC_RPT_CO800301"
(
  DocEntry INT
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	DECLARE TransCode NVARCHAR(50);
	
	SELECT "U_TransCode" INTO TransCode
	FROM "@MTC_COST_OJDT" T0
	WHERE T0."DocEntry"=:DocEntry;
	
	IF :TransCode = 'AR01' OR :TransCode = 'AR02' THEN
		SELECT T0."DocEntry",T0."LineId" AS "行号"
		,T0."U_ItemCode" AS "物料编码",T0."U_ItemName" AS "物料名称"
		,T0."U_Quantity" AS "数量"
		,T0."U_LineTotal" AS "未税金额"
		,T0."U_VatSum" AS "税额"
		,T0."U_GTotal" AS "含税金额"
		,T0."U_ObjType" AS "来源单据编码" 
		,'' AS "来源单据类型"
		,T0."U_DocEntry" AS "来源单号Entry"
		,T0."U_DocNum" AS "来源单号Num"
		,T0."U_LineNum" AS "来源行号"
		,T0."U_CardCode" AS "业务伙伴编码"
		,T0."U_CardName" AS "业务伙伴名称"
		,T0."U_AcctCode" AS "科目编码"
		,T0."U_AcctName" AS "科目名称"
		,T0."U_StockAcctCode" AS "库存科目编码"
		,T0."U_StockAcctName" AS "库存科目名称"
		FROM "@MTC_COST_OJDT2" T0
		WHERE T0."DocEntry"=:DocEntry;
	ELSEIF :TransCode = 'YF01' OR :TransCode = 'PP01' OR :TransCode = 'WW01' OR :TransCode = 'YF01'
		OR :TransCode = 'DN01' OR :TransCode = 'DN02' OR :TransCode = 'DN03' OR :TransCode = 'DN04'
		OR :TransCode = 'AR03' OR :TransCode = 'AR04'
		THEN
		SELECT T0."DocEntry",T0."LineId" AS "行号"
		,T0."U_ItemCode" AS "物料编码",T0."U_ItemName" AS "物料名称"
		,-1*T0."U_Quantity" AS "数量"
		,-1*T0."U_LineTotal" AS "金额"
		,T0."U_ObjType" AS "来源单据编码" 
		,'' AS "来源单据类型"
		,T0."U_DocEntry" AS "来源单号Entry"
		,T0."U_DocNum" AS "来源单号Num"
		,T0."U_LineNum" AS "来源行号"
		,T0."U_CardCode" AS "业务伙伴编码"
		,T0."U_CardName" AS "业务伙伴名称"
		,T0."U_AcctCode" AS "科目编码"
		,T0."U_AcctName" AS "科目名称"
		,T0."U_StockAcctCode" AS "库存科目编码"
		,T0."U_StockAcctName" AS "库存科目名称"
		FROM "@MTC_COST_OJDT2" T0
		WHERE T0."DocEntry"=:DocEntry;
	ELSE
		SELECT T0."DocEntry",T0."LineId" AS "行号"
		,T0."U_ItemCode" AS "物料编码",T0."U_ItemName" AS "物料名称"
		,T0."U_Quantity" AS "数量"
		,T0."U_LineTotal" AS "未税金额"
		,T0."U_VatSum" AS "税额"
		,T0."U_GTotal" AS "含税金额"
		,T0."U_ObjType" AS "来源单据编码" 
		,'' AS "来源单据类型"
		,T0."U_DocEntry" AS "来源单号Entry"
		,T0."U_DocNum" AS "来源单号Num"
		,T0."U_LineNum" AS "来源行号"
		,T0."U_CardCode" AS "业务伙伴编码"
		,T0."U_CardName" AS "业务伙伴名称"
		,T0."U_AcctCode" AS "科目编码"
		,T0."U_AcctName" AS "科目名称"
		,T0."U_StockAcctCode" AS "库存科目编码"
		,T0."U_StockAcctName" AS "库存科目名称"
		FROM "@MTC_COST_OJDT2" T0
		WHERE T0."DocEntry"=:DocEntry;
	END IF;
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_COJZ_01
CREATE PROCEDURE "MTC_RPT_COJZ_01"
(
  Type INT,  		--1 查看明细 0查看分录
  TransCode NVARCHAR(50),
  FcCode NVARCHAR(10),
  IsOJDT NVARCHAR(10) DEFAULT 'N'		--是否生成分录  Y生成分录  N不生成分录
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	
	DECLARE MAXEntry INT;
	DECLARE RevDate DATE;   --下个月初的冲销日期	
	DECLARE EndDate	DATE;	--当月结束日期
	DECLARE LastFcCode NVARCHAR(30); --上一期间
	
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	SELECT MIN("F_RefDate") INTO RevDate FROM OFPR WHERE "Code">:FcCode; 
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	
	IF :IsOJDT = 'Y' THEN
	  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
	  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
	  		RETURN;
	  	END IF;
	END IF;
	
	DELETE FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"='JZ01';
	DELETE FROM MTC_COST_0802_OJDTBASEDETAIL WHERE "FcCode"=:FcCode AND "TransCode"='JZ01';
	
	INSERT INTO MTC_COST_0801_TOOJDT(
	"BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"ProfitCode",
	"OcrName1",
	"Project",
	"LineMemo",
	"CreateDate",
	"Creator"
	)
	SELECT 0,T0."期间",T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,-1*ROUND(SUM(ROUND(T0."关单差异",2)),2) AS "Debit"
	,0.00 AS "Credit",NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ01'
	JOIN OACT T2 ON T2."AcctCode"='500101'
	WHERE T0."WorType" IN ('10','20','30') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	GROUP BY T0."期间",T1."TrnsCode",T1."TrnsCodDsc",T1."TrnsCodDsc",T2."AcctCode",T2."AcctName"
	HAVING ROUND(SUM(T0."关单差异"),2)<>0
	UNION ALL
	SELECT 0,T0."期间",T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,ROUND(SUM(ROUND(T0."关单差异",2)),2) AS "Debit"
	,0.00 AS "Credit",NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ01'
	JOIN OACT T2 ON T2."AcctCode"='510199'
	WHERE T0."WorType" IN ('10','20','30') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	GROUP BY T0."期间",T1."TrnsCode",T1."TrnsCodDsc",T1."TrnsCodDsc",T2."AcctCode",T2."AcctName"
	HAVING ROUND(SUM(T0."关单差异"),2)<>0;
	
	
	INSERT INTO "MTC_COST_0802_OJDTBASEDETAIL"
	("FcCode","DocDate","TransCode","TransName","U_Type",
		"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
		"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
		"U_ItemCode","U_ItemName","U_CardCode","U_CardName",
		"U_Quantity","U_Price","U_LineTotal",
		"U_PriceAfVAT","U_GTotal","U_GTotalFc","U_LineMemo",
		"U_AcctCode","U_AcctName","StockAcctCode","StockAcctName","U_Debit","U_Credit",
		"CostPrice","CostAmt","VatSum",
		"U_Currency","U_Point","U_FCDebit","U_FCCredit",
		"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5"
	)
	SELECT T0."期间",T0."订单关单日期",T1."TrnsCode",T1."TrnsCodDsc",'结转关单差异JZ01' AS "U_Type",
	T0."DocType",T0."WorEntry",T0."WorNum",0 AS "LineId",
	NULL,NULL,NULL,NULL,
	T0."物料编码",T0."物料名称",NULL,NULL,
	0,0,T0."关单差异",0,T0."关单差异",0 AS "U_GTotalFc",'结转关单差异JZ01' AS "U_LineMemo",
	T3."AcctCode" AS "U_AcctCode",T3."AcctName" AS "U_AcctName",T2."AcctCode" AS "U_StockCode",T2."AcctName" AS "U_StockName",
	T0."关单差异",0.00 AS "U_Credit",
	0,0,0,NULL,NULL,NULL,NULL,
	NULL,NULL,NULL,NULL,NULL,NULL
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ01'
	LEFT JOIN OACT T2 ON T2."AcctCode"='500101'
	LEFT JOIN OACT T3 ON T3."AcctCode"='510199'
	WHERE T0."WorType" IN ('10','20','30') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	;

	TMP=
	SELECT "BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"Project",
	"ProfitCode",
	"OcrName1",
	"OcrCode2",
	"OcrName2",
	"LineMemo",
	"CreateDate",
	"Creator",
	"DocEntry",
	"CardCode",
	"CardName",
	CASE WHEN IFNULL("FCCurrency",'')='' THEN 'RMB' ELSE "FCCurrency" END AS "FCCurrency",
	"FCDebit",
	"FCCredit",
	"DocDate"
	FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"=:TransCode;
	
	
	IF :Type = 1 THEN 
		
		SELECT * FROM :TMP;
		
	ELSEIF :Type=0 THEN
		TMP_OJDT=
		SELECT 'Y' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
		,NULL AS "AcctCode",NULL AS "AcctName"
		,NULL AS "CardCode",NULL AS "CardName",NULL AS "FCCurrency"
		,NULL AS "FCDebit",NULL AS "FCCredit",NULL AS "Debit",NULL AS "Credit",NULL AS "ProfitCode",NULL AS "Project"
		FROM DUMMY T1
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=0
		
		UNION ALL
		SELECT 'N' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T2."AcctCode" AS "Account",T2."AcctName"
		,T1."CardCode" AS "ShortName",T1."CardName",T0."FCCurrency" AS "DocCur"
		,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
		FROM :TMP T0
		LEFT JOIN OCRD T1 ON T0."CardCode"=T1."CardCode"
		LEFT JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=1;
		
		IF :IsOJDT = 'N' THEN
			SELECT * FROM :TMP_OJDT;
		ELSEIF :IsOJDT = 'Y' THEN
			SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
			DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
			DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			
			INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
			,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
			SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',T0."RefDate",:FcCode
				,T0."TransCode",T0."Memo"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN 'Y' ELSE 'N' END AS "U_IsRev"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN :RevDate ELSE NULL END AS "U_RevDate"
				FROM :TMP_OJDT T0;
			
			INSERT INTO "@MTC_COST_OJDT1"(
				"DocEntry","LineId","U_LineMemo"
				,"U_AcctCode","U_AcctName","U_CardCode","U_CardName","U_FCCurrency"
				,"U_FCDebit","U_FCCredit","U_Debit","U_Credit","U_OcrCode1","U_OcrCode5" --"Project"
				)
			SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER (PARTITION BY "TransCode","RefDate" ORDER BY T0."AcctCode",T0."CardCode") AS "LineId","Memo"
				,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",T0."FCCurrency"
				,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
				FROM :TMP_OJDT T0;
				
			INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point",
					"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
					"U_CostPrice","U_CostAmt","U_VatSum","U_StockAcctCode","U_StockAcctName","U_DocDate","U_WhsCode"			
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."U_ObjType",P0."U_DocEntry",P0."U_DocNum",P0."U_LineNum"
				,P0."U_BaseType",P0."U_BaseEntry",P0."U_BaseRef",P0."U_BaseLine"
				,P0."U_ItemCode",P1."ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				,P0."U_Project",P0."U_OcrCode1",P0."U_OcrCode2",P0."U_OcrCode3",P0."U_OcrCode4",P0."U_OcrCode5"			
				,P0."CostPrice",P0."CostAmt",P0."VatSum",P0."StockAcctCode",P0."StockAcctName",P0."DocDate",P0."WhsCode"	
				FROM "MTC_COST_0802_OJDTBASEDETAIL" P0 
				LEFT JOIN OITM P1 ON P0."U_ItemCode"=P1."ItemCode"
				WHERE P0."FcCode"=:FcCode AND P0."TransCode"=:TransCode;
				
			SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
				,T0."U_TransCode" AS "TransCode",NULL AS "TransName",T0."U_Memo" AS "Memo"
				,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName",T1."U_CardCode" AS "CardCode"
				,T1."U_CardName" AS "CardName",T1."U_FCCurrency" AS "FCCurrency"
				,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
				,T1."U_OcrCode5" AS "Project"
				,T1."U_OcrCode1" AS "ProfitCode"
				,T0."U_IsRev" AS "IsRev",TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
			FROM "@MTC_COST_OJDT" T0
			JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode;
			
		END IF;
	END IF;
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_COJZ_03
CREATE PROCEDURE "MTC_RPT_COJZ_03"
(
  Type INT,  		--1 查看明细 0查看分录
  TransCode NVARCHAR(50),
  FcCode NVARCHAR(10),
  IsOJDT NVARCHAR(10) DEFAULT 'N'		--是否生成分录  Y生成分录  N不生成分录
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	--JZ03结转委外关单差异
	
	DECLARE MAXEntry INT;
	DECLARE RevDate DATE;   --下个月初的冲销日期	
	DECLARE EndDate	DATE;	--当月结束日期
	DECLARE LastFcCode NVARCHAR(30); --上一期间
	
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	SELECT MIN("F_RefDate") INTO RevDate FROM OFPR WHERE "Code">:FcCode; 
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	
	IF :IsOJDT = 'Y' THEN
	  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
	  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
	  		RETURN;
	  	END IF;
	END IF;
	
	DELETE FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"='JZ03';
	DELETE FROM MTC_COST_0802_OJDTBASEDETAIL WHERE "FcCode"=:FcCode AND "TransCode"='JZ03';
	
	INSERT INTO MTC_COST_0801_TOOJDT(
	"BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"ProfitCode",
	"OcrName1",
	"Project",
	"LineMemo",
	"CreateDate",
	"Creator"
	)
	SELECT 0,T0."期间",T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,-1*ROUND(SUM(ROUND(T0."关单差异",2)),2) AS "Debit"
	,0.00 AS "Credit",NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ03'
	JOIN OACT T2 ON T2."AcctCode"='140801'
	WHERE T0."WorType" IN ('50') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	GROUP BY T0."期间",T1."TrnsCode",T1."TrnsCodDsc",T1."TrnsCodDsc",T2."AcctCode",T2."AcctName"
	HAVING ROUND(SUM(T0."关单差异"),2)<>0
	UNION ALL
	SELECT 0,T0."期间",T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,ROUND(SUM(ROUND(T0."关单差异",2)),2) AS "Debit"
	,0.00 AS "Credit",NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ03'
	JOIN OACT T2 ON T2."AcctCode"='510198'
	WHERE T0."WorType" IN ('50') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	GROUP BY T0."期间",T1."TrnsCode",T1."TrnsCodDsc",T1."TrnsCodDsc",T2."AcctCode",T2."AcctName"
	HAVING ROUND(SUM(T0."关单差异"),2)<>0;
	
	
	INSERT INTO "MTC_COST_0802_OJDTBASEDETAIL"
	("FcCode","DocDate","TransCode","TransName","U_Type",
		"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
		"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
		"U_ItemCode","U_ItemName","U_CardCode","U_CardName",
		"U_Quantity","U_Price","U_LineTotal",
		"U_PriceAfVAT","U_GTotal","U_GTotalFc","U_LineMemo",
		"U_AcctCode","U_AcctName","StockAcctCode","StockAcctName","U_Debit","U_Credit",
		"CostPrice","CostAmt","VatSum",
		"U_Currency","U_Point","U_FCDebit","U_FCCredit",
		"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5"
	)
	SELECT T0."期间",T0."订单关单日期",T1."TrnsCode",T1."TrnsCodDsc",'结转关单差异JZ03' AS "U_Type",
	T0."DocType",T0."WorEntry",T0."WorNum",0 AS "LineId",
	NULL,NULL,NULL,NULL,
	T0."物料编码",T0."物料名称",NULL,NULL,
	0,0,T0."关单差异",0,T0."关单差异",0 AS "U_GTotalFc",'结转关单差异JZ03' AS "U_LineMemo",
	T3."AcctCode" AS "U_AcctCode",T3."AcctName" AS "U_AcctName",T2."AcctCode" AS "U_StockCode",T2."AcctName" AS "U_StockName",
	T0."关单差异",0.00 AS "U_Credit",
	0,0,0,NULL,NULL,NULL,NULL,
	NULL,NULL,NULL,NULL,NULL,NULL
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ03'
	LEFT JOIN OACT T2 ON T2."AcctCode"='140801'
	LEFT JOIN OACT T3 ON T3."AcctCode"='510198'
	WHERE T0."WorType" IN ('50') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	;

	TMP=
	SELECT "BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"Project",
	"ProfitCode",
	"OcrName1",
	"OcrCode2",
	"OcrName2",
	"LineMemo",
	"CreateDate",
	"Creator",
	"DocEntry",
	"CardCode",
	"CardName",
	CASE WHEN IFNULL("FCCurrency",'')='' THEN 'RMB' ELSE "FCCurrency" END AS "FCCurrency",
	"FCDebit",
	"FCCredit",
	"DocDate"
	FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"=:TransCode;
	
	
	IF :Type = 1 THEN 
		
		SELECT * FROM :TMP;
		
	ELSEIF :Type=0 THEN
		TMP_OJDT=
		SELECT 'Y' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
		,NULL AS "AcctCode",NULL AS "AcctName"
		,NULL AS "CardCode",NULL AS "CardName",NULL AS "FCCurrency"
		,NULL AS "FCDebit",NULL AS "FCCredit",NULL AS "Debit",NULL AS "Credit",NULL AS "ProfitCode",NULL AS "Project"
		FROM DUMMY T1
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=0
		
		UNION ALL
		SELECT 'N' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T2."AcctCode" AS "Account",T2."AcctName"
		,T1."CardCode" AS "ShortName",T1."CardName",T0."FCCurrency" AS "DocCur"
		,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
		FROM :TMP T0
		LEFT JOIN OCRD T1 ON T0."CardCode"=T1."CardCode"
		LEFT JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=1;
		
		IF :IsOJDT = 'N' THEN
			SELECT * FROM :TMP_OJDT;
		ELSEIF :IsOJDT = 'Y' THEN
			SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
			DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
			DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			
			INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
			,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
			SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',T0."RefDate",:FcCode
				,T0."TransCode",T0."Memo"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN 'Y' ELSE 'N' END AS "U_IsRev"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN :RevDate ELSE NULL END AS "U_RevDate"
				FROM :TMP_OJDT T0;
			
			INSERT INTO "@MTC_COST_OJDT1"(
				"DocEntry","LineId","U_LineMemo"
				,"U_AcctCode","U_AcctName","U_CardCode","U_CardName","U_FCCurrency"
				,"U_FCDebit","U_FCCredit","U_Debit","U_Credit","U_OcrCode1","U_OcrCode5" --"Project"
				)
			SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER (PARTITION BY "TransCode","RefDate" ORDER BY T0."AcctCode",T0."CardCode") AS "LineId","Memo"
				,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",T0."FCCurrency"
				,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
				FROM :TMP_OJDT T0;
				
			INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point",
					"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
					"U_CostPrice","U_CostAmt","U_VatSum","U_StockAcctCode","U_StockAcctName","U_DocDate","U_WhsCode"			
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."U_ObjType",P0."U_DocEntry",P0."U_DocNum",P0."U_LineNum"
				,P0."U_BaseType",P0."U_BaseEntry",P0."U_BaseRef",P0."U_BaseLine"
				,P0."U_ItemCode",P1."ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				,P0."U_Project",P0."U_OcrCode1",P0."U_OcrCode2",P0."U_OcrCode3",P0."U_OcrCode4",P0."U_OcrCode5"			
				,P0."CostPrice",P0."CostAmt",P0."VatSum",P0."StockAcctCode",P0."StockAcctName",P0."DocDate",P0."WhsCode"	
				FROM "MTC_COST_0802_OJDTBASEDETAIL" P0 
				LEFT JOIN OITM P1 ON P0."U_ItemCode"=P1."ItemCode"
				WHERE P0."FcCode"=:FcCode AND P0."TransCode"=:TransCode;
				
			SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
				,T0."U_TransCode" AS "TransCode",NULL AS "TransName",T0."U_Memo" AS "Memo"
				,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName",T1."U_CardCode" AS "CardCode"
				,T1."U_CardName" AS "CardName",T1."U_FCCurrency" AS "FCCurrency"
				,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
				,T1."U_OcrCode5" AS "Project"
				,T1."U_OcrCode1" AS "ProfitCode"
				,T0."U_IsRev" AS "IsRev",TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
			FROM "@MTC_COST_OJDT" T0
			JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode;
			
		END IF;
	END IF;
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_COJZ_04
CREATE PROCEDURE "MTC_RPT_COJZ_04"
(
  Type INT,  		--1 查看明细 0查看分录
  TransCode NVARCHAR(50),
  FcCode NVARCHAR(10),
  IsOJDT NVARCHAR(10) DEFAULT 'N'		--是否生成分录  Y生成分录  N不生成分录
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	--JZ04结转尾差
	
	DECLARE MAXEntry INT;
	DECLARE RevDate DATE;   --下个月初的冲销日期	
	DECLARE EndDate	DATE;	--当月结束日期
	DECLARE LastFcCode NVARCHAR(30); --上一期间
	DECLARE CNT INT = 0;
	
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	SELECT MIN("F_RefDate") INTO RevDate FROM OFPR WHERE "Code">:FcCode; 
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	
	IF :IsOJDT = 'Y' THEN
	  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
	  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
	  		RETURN;
	  	END IF;
	END IF;
	
	DELETE FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"='JZ04';
	DELETE FROM MTC_COST_0802_OJDTBASEDETAIL WHERE "FcCode"=:FcCode AND "TransCode"='JZ04';
	
	
	TMP_OJDT_DIFF=
	SELECT T0."AcctCode",SUM(T0."CW_Amount") AS "CW_Amount",SUM(T0."YW_Amount") AS "YW_Amount"
	,-1*SUM(IFNULL(T0."CW_Amount",0)-IFNULL(T0."YW_Amount",0)) AS "DiffAmt"
	FROM (
			SELECT T2."AcctCode",T2."AcctName",SUM(T1."Debit"-T1."Credit") AS "CW_Amount",0.00 AS "YW_Amount"
			FROM "OJDT" T0
			JOIN "JDT1" T1 ON T0."TransId"=T1."TransId"
			JOIN "OACT" T2 ON T1."Account"=T2."AcctCode"
			--JOIN "OFPR" T3 ON T0."RefDate" BETWEEN T3."F_RefDate" AND T3."T_RefDate"
			WHERE 1=1
			--去掉调整交易
			--AND T0."AdjTran"='N'
			AND LEFT(T0."RefDate",7)<=:FcCode
			AND LEFT(T2."AcctCode",4) IN ('1403','1405','1409')
			GROUP BY T2."AcctCode",T2."AcctName"
			UNION ALL
			SELECT T2."AcctCode",T2."AcctName"
		    ,SUM(IFNULL(T1."Debit",0)-IFNULL(T1."Credit",0)) AS "BtfAmount"   ---金额
			,0.00 AS "YW_Amount"
		    FROM OBTF T0
		    JOIN BTF1 T1 ON T0."TransId" = T1."TransId" AND T0."BatchNum" = T1."BatchNum"
		    JOIN OACT T2 ON T1."Account" = T2."AcctCode"
		    WHERE T0."BtfStatus"='O'
		    AND LEFT(T0."RefDate",7)<=:FcCode
			AND LEFT("AcctCode",4) IN ('1403','1405','1409')
		    GROUP BY T2."AcctCode",T2."AcctName"
		    UNION ALL
			SELECT 
			T4."AcctCode",
			T4."AcctName",0.00 AS "CW_Amount",
			SUM(ROUND(T0."QM_Amount",2)) AS "YW_Amount"
			FROM MTC_COST_0301_INVNT T0
			JOIN OITM T1 ON T0."ItemCode"=T1."ItemCode"
			LEFT JOIN OITB T2 ON T0."ItmsGrpCod"=T2."ItmsGrpCod"
			LEFT JOIN (SELECT "ItmsGrpCod",MAX("StockAct") AS "StockAct",MAX("ShpdGdsAct") AS "ShpdGdsAct"
					FROM OGAR WHERE "PeriodCat"=LEFT(:FcCode,4) GROUP BY "ItmsGrpCod"
				) T3 ON T2."ItmsGrpCod"=T3."ItmsGrpCod"
			LEFT JOIN "OACT" T4 ON T3."StockAct"=T4."AcctCode"
			WHERE T0."FcCode" = :FcCode
			--AND T1."InvntItem"='Y'
			AND T0."CostCode"='20'
			GROUP BY T0."FcCode",
			T4."AcctCode",
			T4."AcctName"
	) T0 GROUP BY T0."AcctCode" HAVING SUM(IFNULL(T0."CW_Amount",0)-IFNULL(T0."YW_Amount",0))<>0
	;
	
	SELECT COUNT(1) INTO CNT FROM :TMP_OJDT_DIFF;
	
	IF :CNT =0 THEN
		SELECT '0' as "error",'无差异，不需要调整' AS "message" FROM DUMMY;
		RETURN;
	END IF;
	
	INSERT INTO MTC_COST_0801_TOOJDT(
	"BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"ProfitCode",
	"OcrName1",
	"Project",
	"LineMemo",
	"CreateDate",
	"Creator"
	)
	SELECT 0,:FcCode,T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,CASE WHEN T0."DiffAmt">0 THEN -1 ELSE 1 END *IFNULL(T0."DiffAmt",0) AS "Debit"
	,0.00 AS "Credit",NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM :TMP_OJDT_DIFF T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ04'
	JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
	
	UNION ALL
	SELECT 0,:FcCode,T1."TrnsCode",T1."TrnsCodDsc",:EndDate,T1."TrnsCodDsc",0
	,T2."AcctCode",T2."AcctName"
	,0.00 AS "Debit"
	,SUM(CASE WHEN T0."DiffAmt">0 THEN -1 ELSE 1 END *IFNULL(T0."DiffAmt",0)) AS "Credit"
	,NULL,NULL,NULL
	,T1."TrnsCodDsc"
	,CURRENT_TIMESTAMP
	,''
	FROM :TMP_OJDT_DIFF T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ04' 
	JOIN OACT T2 ON T2."AcctCode"='640101'
	GROUP BY T1."TrnsCode",T1."TrnsCodDsc",T2."AcctCode",T2."AcctName";
	
	/*
	INSERT INTO "MTC_COST_0802_OJDTBASEDETAIL"
	("FcCode","DocDate","TransCode","TransName","U_Type",
		"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
		"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
		"U_ItemCode","U_ItemName","U_CardCode","U_CardName",
		"U_Quantity","U_Price","U_LineTotal",
		"U_PriceAfVAT","U_GTotal","U_GTotalFc","U_LineMemo",
		"U_AcctCode","U_AcctName","StockAcctCode","StockAcctName","U_Debit","U_Credit",
		"CostPrice","CostAmt","VatSum",
		"U_Currency","U_Point","U_FCDebit","U_FCCredit",
		"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5"
	)
	SELECT T0."期间",T0."订单关单日期",T1."TrnsCode",T1."TrnsCodDsc",'结转关单差异JZ03' AS "U_Type",
	T0."DocType",T0."WorEntry",T0."WorNum",0 AS "LineId",
	NULL,NULL,NULL,NULL,
	T0."物料编码",T0."物料名称",NULL,NULL,
	0,0,T0."关单差异",0,T0."关单差异",0 AS "U_GTotalFc",'结转关单差异JZ03' AS "U_LineMemo",
	T3."AcctCode" AS "U_AcctCode",T3."AcctName" AS "U_AcctName",T2."AcctCode" AS "U_StockCode",T2."AcctName" AS "U_StockName",
	T0."关单差异",0.00 AS "U_Credit",
	0,0,0,NULL,NULL,NULL,NULL,
	NULL,NULL,NULL,NULL,NULL,NULL
	FROM "MTC_COST_0322_OWOR_ZCP" T0
	JOIN OTRC T1 ON T1."TrnsCode"='JZ03'
	LEFT JOIN OACT T2 ON T2."AcctCode"='140801'
	LEFT JOIN OACT T3 ON T3."AcctCode"='510198'
	WHERE T0."WorType" IN ('50') 
	AND T0."订单状态"='已结算' AND T0."期间"=:FcCode AND T0."关单结算期间"=:FcCode
	;
	*/
	TMP=
	SELECT "BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"Project",
	"ProfitCode",
	"OcrName1",
	"OcrCode2",
	"OcrName2",
	"LineMemo",
	"CreateDate",
	"Creator",
	"DocEntry",
	"CardCode",
	"CardName",
	CASE WHEN IFNULL("FCCurrency",'')='' THEN 'RMB' ELSE "FCCurrency" END AS "FCCurrency",
	"FCDebit",
	"FCCredit",
	"DocDate"
	FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"=:TransCode;
	
	
	IF :Type = 1 THEN 
		
		SELECT * FROM :TMP;
		
	ELSEIF :Type=0 THEN
		TMP_OJDT=
		SELECT 'Y' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
		,NULL AS "AcctCode",NULL AS "AcctName"
		,NULL AS "CardCode",NULL AS "CardName",NULL AS "FCCurrency"
		,NULL AS "FCDebit",NULL AS "FCCredit",NULL AS "Debit",NULL AS "Credit",NULL AS "ProfitCode",NULL AS "Project"
		FROM DUMMY T1
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=0
		
		UNION ALL
		SELECT 'N' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T2."AcctCode" AS "Account",T2."AcctName"
		,T1."CardCode" AS "ShortName",T1."CardName",T0."FCCurrency" AS "DocCur"
		,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
		FROM :TMP T0
		LEFT JOIN OCRD T1 ON T0."CardCode"=T1."CardCode"
		LEFT JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=1;
		
		IF :IsOJDT = 'N' THEN
			SELECT * FROM :TMP_OJDT;
		ELSEIF :IsOJDT = 'Y' THEN
			SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
			DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
			DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			
			INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
			,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
			SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',T0."RefDate",:FcCode
				,T0."TransCode",T0."Memo"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN 'Y' ELSE 'N' END AS "U_IsRev"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN :RevDate ELSE NULL END AS "U_RevDate"
				FROM :TMP_OJDT T0;
			
			INSERT INTO "@MTC_COST_OJDT1"(
				"DocEntry","LineId","U_LineMemo"
				,"U_AcctCode","U_AcctName","U_CardCode","U_CardName","U_FCCurrency"
				,"U_FCDebit","U_FCCredit","U_Debit","U_Credit","U_OcrCode1","U_OcrCode5" --"Project"
				)
			SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER (PARTITION BY "TransCode","RefDate" ORDER BY T0."AcctCode",T0."CardCode") AS "LineId","Memo"
				,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",T0."FCCurrency"
				,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
				FROM :TMP_OJDT T0;
				
			INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point",
					"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
					"U_CostPrice","U_CostAmt","U_VatSum","U_StockAcctCode","U_StockAcctName","U_DocDate","U_WhsCode"			
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."U_ObjType",P0."U_DocEntry",P0."U_DocNum",P0."U_LineNum"
				,P0."U_BaseType",P0."U_BaseEntry",P0."U_BaseRef",P0."U_BaseLine"
				,P0."U_ItemCode",P1."ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				,P0."U_Project",P0."U_OcrCode1",P0."U_OcrCode2",P0."U_OcrCode3",P0."U_OcrCode4",P0."U_OcrCode5"			
				,P0."CostPrice",P0."CostAmt",P0."VatSum",P0."StockAcctCode",P0."StockAcctName",P0."DocDate",P0."WhsCode"	
				FROM "MTC_COST_0802_OJDTBASEDETAIL" P0 
				LEFT JOIN OITM P1 ON P0."U_ItemCode"=P1."ItemCode"
				WHERE P0."FcCode"=:FcCode AND P0."TransCode"=:TransCode;
				
			SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
				,T0."U_TransCode" AS "TransCode",NULL AS "TransName",T0."U_Memo" AS "Memo"
				,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName",T1."U_CardCode" AS "CardCode"
				,T1."U_CardName" AS "CardName",T1."U_FCCurrency" AS "FCCurrency"
				,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
				,T1."U_OcrCode5" AS "Project"
				,T1."U_OcrCode1" AS "ProfitCode"
				,T0."U_IsRev" AS "IsRev",TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
			FROM "@MTC_COST_OJDT" T0
			JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode;
			
		END IF;
	END IF;
	
	
	
END

@@
-- @stmt 旧模块 PROCEDURE MTC_RPT_COJZ_TOOJDT
CREATE PROCEDURE "MTC_RPT_COJZ_TOOJDT"
(
  Type INT,  		--1 查看明细 0查看分录
  TransCode NVARCHAR(50),
  FcCode NVARCHAR(10),
  IsOJDT NVARCHAR(10) DEFAULT 'N'		--是否生成分录  Y生成分录  N不生成分录
 )
LANGUAGE SQLSCRIPT
AS
BEGIN 
	
	DECLARE MAXEntry INT;
	DECLARE RevDate DATE;   --下个月初的冲销日期	
	DECLARE EndDate	DATE;	--当月结束日期
	DECLARE LastFcCode NVARCHAR(30); --上一期间
	
	SELECT "T_RefDate" INTO EndDate FROM OFPR WHERE "Code"=:FcCode;
	SELECT MIN("F_RefDate") INTO RevDate FROM OFPR WHERE "Code">:FcCode; 
	SELECT MAX("Code") INTO LastFcCode FROM OFPR WHERE "Code"<:FcCode;
	
	IF :IsOJDT = 'Y' THEN
	  	IF EXISTS(SELECT 1 FROM "OFPR" WHERE "PeriodStat"='Y' AND "Code"=:FcCode) THEN
	  		SELECT -1 AS "Code",'账期已锁定，无法计算成本' AS "Msg" FROM DUMMY;
	  		RETURN;
	  	END IF;
	END IF;

	TMP=
	SELECT "BPLId",
	"FcCode",
	"TransCode",
	"TransName",
	"RefDate",
	"Memo",
	"Line_ID",
	"AcctCode",
	"AcctName",
	"Debit",
	"Credit",
	"Project",
	"ProfitCode",
	"OcrName1",
	"OcrCode2",
	"OcrName2",
	"LineMemo",
	"CreateDate",
	"Creator",
	"DocEntry",
	"CardCode",
	"CardName",
	CASE WHEN IFNULL("FCCurrency",'')='' THEN 'RMB' ELSE "FCCurrency" END AS "FCCurrency",
	"FCDebit",
	"FCCredit",
	"DocDate"
	FROM MTC_COST_0801_TOOJDT WHERE "FcCode"=:FcCode AND "TransCode"=:TransCode;
	
	
	IF :Type = 1 THEN 
		
		SELECT * FROM :TMP;
		
	ELSEIF :Type=0 THEN
		TMP_OJDT=
		SELECT 'Y' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo"
		,NULL AS "AcctCode",NULL AS "AcctName"
		,NULL AS "CardCode",NULL AS "CardName",NULL AS "FCCurrency"
		,NULL AS "FCDebit",NULL AS "FCCredit",NULL AS "Debit",NULL AS "Credit",NULL AS "ProfitCode",NULL AS "Project"
		FROM DUMMY T1
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=0
		
		UNION ALL
		SELECT 'N' AS "flag",NULL AS "TransId",T31."TrnsCode" AS "TransCode",T31."TrnsCodDsc",:EndDate AS "RefDate"
		,T31."TrnsCodDsc"||','||:FcCode||'月' AS "Memo",T2."AcctCode" AS "Account",T2."AcctName"
		,T1."CardCode" AS "ShortName",T1."CardName",T0."FCCurrency" AS "DocCur"
		,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
		FROM :TMP T0
		LEFT JOIN OCRD T1 ON T0."CardCode"=T1."CardCode"
		LEFT JOIN OACT T2 ON T0."AcctCode"=T2."AcctCode"
		LEFT JOIN OTRC T31 ON T31."TrnsCode"=:TransCode
		WHERE 1=1;
		
		IF :IsOJDT = 'N' THEN
			SELECT * FROM :TMP_OJDT;
		ELSEIF :IsOJDT = 'Y' THEN
			SELECT IFNULL(MAX("DocEntry"),0) INTO MAXEntry FROM "@MTC_COST_OJDT";
			DELETE FROM "@MTC_COST_OJDT" WHERE "U_FcCode"=:FcCode AND "U_TransCode"=:TransCode;
			DELETE FROM "@MTC_COST_OJDT1" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			DELETE FROM "@MTC_COST_OJDT2" WHERE "DocEntry" NOT IN (SELECT "DocEntry" FROM "@MTC_COST_OJDT");
			
			INSERT INTO "@MTC_COST_OJDT"("DocEntry","DocNum","Object","Canceled","U_RefDate","U_FcCode"
			,"U_TransCode","U_Memo","U_IsRev","U_RevDate")
			SELECT TOP 1 :MAXEntry+1 AS "DocEntry",:MAXEntry+1 AS "DocNum",'MTC_COST_OJDT','N',T0."RefDate",:FcCode
				,T0."TransCode",T0."Memo"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN 'Y' ELSE 'N' END AS "U_IsRev"
				,CASE WHEN T0."TransCode" IN ('AR03','AR04') THEN :RevDate ELSE NULL END AS "U_RevDate"
				FROM :TMP_OJDT T0;
			
			INSERT INTO "@MTC_COST_OJDT1"(
				"DocEntry","LineId","U_LineMemo"
				,"U_AcctCode","U_AcctName","U_CardCode","U_CardName","U_FCCurrency"
				,"U_FCDebit","U_FCCredit","U_Debit","U_Credit","U_OcrCode1","U_OcrCode5" --"Project"
				)
			SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER (PARTITION BY "TransCode","RefDate" ORDER BY T0."AcctCode",T0."CardCode") AS "LineId","Memo"
				,T0."AcctCode",T0."AcctName",T0."CardCode",T0."CardName",T0."FCCurrency"
				,T0."FCDebit",T0."FCCredit",T0."Debit",T0."Credit",T0."ProfitCode",T0."Project"
				FROM :TMP_OJDT T0;
				
			INSERT INTO "@MTC_COST_OJDT2"(
					"DocEntry","LineId","VisOrder",
					"Object","LogInst","U_Type",
					"U_ObjType","U_DocEntry","U_DocNum","U_LineNum",
					"U_BaseType","U_BaseEntry","U_BaseRef","U_BaseLine",
					"U_ItemCode","U_ItemName","U_Quantity",
					"U_CardCode","U_CardName","U_AcctCode","U_AcctName",
					"U_Price","U_LineTotal","U_PriceAfVAT","U_GTotal",
					"U_Debit","U_Credit","U_Point",
					"U_Project","U_OcrCode1","U_OcrCode2","U_OcrCode3","U_OcrCode4","U_OcrCode5",
					"U_CostPrice","U_CostAmt","U_VatSum","U_StockAcctCode","U_StockAcctName","U_DocDate","U_WhsCode"			
					)
				SELECT :MAXEntry+1 AS "DocEntry"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "LineId"
				,ROW_NUMBER() OVER(ORDER BY P0."U_Type") AS "VisOrder"
				,'MTC_COST_OJDT' AS "Object",NULL AS "LogInst",P0."U_Type"
				,P0."U_ObjType",P0."U_DocEntry",P0."U_DocNum",P0."U_LineNum"
				,P0."U_BaseType",P0."U_BaseEntry",P0."U_BaseRef",P0."U_BaseLine"
				,P0."U_ItemCode",P1."ItemName",P0."U_Quantity"
				,P0."U_CardCode",P0."U_CardName",P0."U_AcctCode",P0."U_AcctName"
				,P0."U_Price",P0."U_LineTotal",P0."U_PriceAfVAT",P0."U_GTotal"
				,P0."U_Debit",P0."U_Credit",P0."U_Point"
				,P0."U_Project",P0."U_OcrCode1",P0."U_OcrCode2",P0."U_OcrCode3",P0."U_OcrCode4",P0."U_OcrCode5"			
				,P0."CostPrice",P0."CostAmt",P0."VatSum",P0."StockAcctCode",P0."StockAcctName",P0."DocDate",P0."WhsCode"	
				FROM "MTC_COST_0802_OJDTBASEDETAIL" P0 
				LEFT JOIN OITM P1 ON P0."U_ItemCode"=P1."ItemCode"
				WHERE P0."FcCode"=:FcCode AND P0."TransCode"=:TransCode;
				
			SELECT 'Y' AS "flag",T0."DocEntry",T1."LineId",TO_VARCHAR(T0."U_RefDate",'YYYYMMDD') AS "RefDate"
				,T0."U_TransCode" AS "TransCode",NULL AS "TransName",T0."U_Memo" AS "Memo"
				,T1."U_AcctCode" AS "AcctCode",T1."U_AcctName" AS "AcctName",T1."U_CardCode" AS "CardCode"
				,T1."U_CardName" AS "CardName",T1."U_FCCurrency" AS "FCCurrency"
				,T1."U_FCDebit" AS "FCDebit",T1."U_FCCredit" AS "FCCredit",T1."U_Debit" AS "Debit",T1."U_Credit" AS "Credit"
				,T1."U_OcrCode5" AS "Project"
				,T1."U_OcrCode1" AS "ProfitCode"
				,T0."U_IsRev" AS "IsRev",TO_VARCHAR(T0."U_RevDate",'YYYYMMDD') AS "RevDate"
			FROM "@MTC_COST_OJDT" T0
			JOIN "@MTC_COST_OJDT1" T1 ON T0."DocEntry"=T1."DocEntry"
			WHERE T0."U_FcCode"=:FcCode AND T0."U_TransCode"=:TransCode;
			
		END IF;
	END IF;
	
	
	
END

@@
-- @stmt 配置数据 @MTC_COST_IOTYPE I01
INSERT INTO "@MTC_COST_IOTYPE" ("Code", "Name", "U_IOType", "U_TransCode") SELECT 'I01', '采购入库', 'I', 'PUR1' FROM DUMMY WHERE NOT EXISTS (SELECT 1 FROM "@MTC_COST_IOTYPE" WHERE "Code" = 'I01')

