-- @stmt 配置数据 @MTC_COST_IOTYPE I10
INSERT INTO "@MTC_COST_IOTYPE" ("Code", "Name", "U_IOType", "U_TransCode") SELECT 'I10', '盘点入库', 'I', 'IO01' FROM DUMMY WHERE NOT EXISTS (SELECT 1 FROM "@MTC_COST_IOTYPE" WHERE "Code" = 'I10')

