    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("RunType" NVARCHAR(1))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Scenario';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Scenario" NVARCHAR(30) DEFAULT '''')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Initiator';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Initiator" NVARCHAR(10) DEFAULT ''USER'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'UserCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("UserCode" NVARCHAR(50))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'StartTime';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("StartTime" TIMESTAMP)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'EndTime';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("EndTime" TIMESTAMP)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Status';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Status" NVARCHAR(10))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'IterCount';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("IterCount" INT DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Converged';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Converged" NVARCHAR(1) DEFAULT ''N'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Params';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Params" NCLOB)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_RUN' AND COLUMN_NAME = 'Msg';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_RUN" ADD ("Msg" NVARCHAR(2000))'; END IF;
