-- @stmt 新框架 02_config_meta_tables.sql #1
-- =====================================================================
-- 新成本框架 第 1 期：配置与规则层、元数据层（设计稿 3.2、3.3）
-- 生效期间：FromFc ≤ 账期 ≤ ToFc（账期 = OFPR."Code"，格式 YYYY-MM）
-- =====================================================================
CREATE COLUMN TABLE "MTC_CA_C_PARAM" (
    "ParamCode"  NVARCHAR(50)   NOT NULL,
    "FromFc"     NVARCHAR(10)   NOT NULL DEFAULT '0000-00',
    "ToFc"       NVARCHAR(10)   NOT NULL DEFAULT '9999-99',
    "Value"      NVARCHAR(200)  NOT NULL,
    "DataType"   NVARCHAR(10)   NOT NULL DEFAULT 'DEC',   -- DEC / INT / STR / LIST（逗号列表，存成 ,A,B,）
    "Descr"      NVARCHAR(500),
    PRIMARY KEY ("ParamCode", "FromFc")
)

@@
-- @stmt 新框架 02_config_meta_tables.sql #2
COMMENT ON TABLE "MTC_CA_C_PARAM" IS '计算参数：一行 = 一个参数在一段账期内的取值'

@@
-- @stmt 新框架 02_config_meta_tables.sql #3
-- 参数目录（用户 2026-10-28：参数在 B1 @MTC_CA_PARAM 平铺表格维护）：哪些参数可以在 B1 维护、类型、中文名、填法。
-- 导入脚本 sl_import_costcfg.py --param、B1 保存校验 MTC_CA_V_B1CFG_ISSUES、P05 同步、执行台参数总览共用。新增参数时在这里登记一行。
CREATE COLUMN TABLE "MTC_CA_C_PARAM_DEF" (
    "ParamCode"  NVARCHAR(50)   NOT NULL,               -- 参数代码 = B1 @MTC_CA_PARAM.Code（第二段起 代码@起始账期）
    "Target"     NVARCHAR(10)   NOT NULL DEFAULT 'PARAM', -- 同步到哪：PARAM = MTC_CA_C_PARAM，ACCT = MTC_CA_C_ACCT（Usage = 参数代码）
    "Category"   NVARCHAR(20)   NOT NULL,               -- 分类：费用归集 / 计算控制 / 尾差与校验 / 凭证与对账 / 业务口径
    "SortNo"     INT            NOT NULL DEFAULT 0,     -- 显示顺序
    "CnName"     NVARCHAR(100)  NOT NULL,               -- 中文名（B1 Name）
    "DataType"   NVARCHAR(10)   NOT NULL,               -- DEC 数字 / INT 整数 / STR 文字 / LIST 逗号列表 / FC 账期 YYYY-MM / DATE 日期 YYYY-MM-DD
    "Choices"    NVARCHAR(200),                         -- 只能取这些值（逗号分隔），空 = 不限
    "Hint"       NVARCHAR(254),                         -- 填法、可选值、单位（B1 U_Hint）
    PRIMARY KEY ("ParamCode")
)

@@
-- @stmt 新框架 02_config_meta_tables.sql #4
COMMENT ON TABLE "MTC_CA_C_PARAM_DEF" IS '参数目录：可在 B1 @MTC_CA_PARAM 维护的参数、类型、中文名和填法'

@@
-- @stmt 新框架 02_config_meta_tables.sql #5
-- B1 @MTC_CA_PARAM 上一次保存（TN）或同步（P05）时的原样快照（用户 2026-10-29）：B1 保存时用它判断锁定（U_Locked = Y）的行有没有被改。
-- 由 MTC_CA_P_PARAM_B1_SNAP（P05 调用）整表刷新、MTC_CA_P_B1CFG_TN 逐行刷新；计算不读它，计算读 MTC_CA_C_PARAM。
CREATE COLUMN TABLE "MTC_CA_C_PARAM_B1" (
    "Code"       NVARCHAR(50)   NOT NULL,               -- @MTC_CA_PARAM.Code
    "FromFc"     NVARCHAR(10),                          -- U_FromFc（原样，空 = 不限）
    "ToFc"       NVARCHAR(10),                          -- U_ToFc
    "Value"      NVARCHAR(500),                         -- U_Value（原样）
    "Locked"     NVARCHAR(1)    NOT NULL DEFAULT 'N',   -- U_Locked：Y 锁定；B1 没有这个字段时都是 N
    "SnapSrc"    NVARCHAR(10),                          -- SYNC = P05 整表刷新，TN = B1 保存时
    "SnapTime"   TIMESTAMP,
    PRIMARY KEY ("Code")
)

@@
-- @stmt 新框架 02_config_meta_tables.sql #6
COMMENT ON TABLE "MTC_CA_C_PARAM_B1" IS 'B1 @MTC_CA_PARAM 上一次保存 / 同步时的快照：B1 保存时判断锁定（U_Locked = Y）的参数有没有被改'

@@
