-- @stmt 新框架 05_config_pool.sql #1
-- =====================================================================
-- 新成本框架 第 1 期：费用池配置（设计稿 4.4，替代 0312 中写死的车间和物料组）
-- 初始值按旧 0312【读代码】。Q9 用户确认：车间划分做成配置，以后在这三张表里改，不改代码。
-- 关单差异固定进 C_PARAM.CLOSE_DIF_POOL（Q10）；没配置的成本中心、没有成本中心的重估进默认池（Q12）。
-- =====================================================================
CREATE COLUMN TABLE "MTC_CA_C_POOL" (
    "PoolCode"   NVARCHAR(20)   NOT NULL,
    "PoolName"   NVARCHAR(100)  NOT NULL,
    "IsDefault"  NVARCHAR(1)    NOT NULL DEFAULT 'N',   -- 成本中心没有配置时进默认池；只能有一个
    "Descr"      NVARCHAR(500),
    PRIMARY KEY ("PoolCode")
)

@@
-- @stmt 新框架 05_config_pool.sql #2
COMMENT ON TABLE "MTC_CA_C_POOL" IS '费用池（车间）：制造费用和人工按池归集、按池分摊'

@@
-- @stmt 新框架 05_config_pool.sql #3
CREATE COLUMN TABLE "MTC_CA_C_POOL_SRC" (
    "OcrCode"    NVARCHAR(20)   NOT NULL,               -- 成本中心（OPRC.PrcCode）
    "FromFc"     NVARCHAR(10)   NOT NULL DEFAULT '0000-00',
    "ToFc"       NVARCHAR(10)   NOT NULL DEFAULT '9999-99',
    "PoolCode"   NVARCHAR(20)   NOT NULL,
    "Descr"      NVARCHAR(500),
    PRIMARY KEY ("OcrCode", "FromFc")
)

@@
-- @stmt 新框架 05_config_pool.sql #3 补齐 MTC_CA_C_POOL_SRC 缺少的列
DO BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_SRC' AND COLUMN_NAME = 'OcrCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_SRC" ADD ("OcrCode" NVARCHAR(20))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_SRC' AND COLUMN_NAME = 'FromFc';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_SRC" ADD ("FromFc" NVARCHAR(10) DEFAULT ''0000-00'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_SRC' AND COLUMN_NAME = 'ToFc';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_SRC" ADD ("ToFc" NVARCHAR(10) DEFAULT ''9999-99'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_SRC' AND COLUMN_NAME = 'PoolCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_SRC" ADD ("PoolCode" NVARCHAR(20))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_SRC' AND COLUMN_NAME = 'Descr';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_SRC" ADD ("Descr" NVARCHAR(500))'; END IF;
END

@@
-- @stmt 新框架 05_config_pool.sql #4
COMMENT ON TABLE "MTC_CA_C_POOL_SRC" IS '成本中心 → 费用池；没有配置的成本中心进默认池'

@@
-- @stmt 新框架 05_config_pool.sql #5
CREATE COLUMN TABLE "MTC_CA_C_POOL_TGT" (
    "PoolCode"    NVARCHAR(20)   NOT NULL,
    "ItmsGrpCod"  NVARCHAR(20)   NOT NULL,              -- 匹配值：MatchBy=GRP 时是产品物料组 OITM.ItmsGrpCod，GRPTYPE 时是 OITB.U_ItemGrpType
    "FromFc"      NVARCHAR(10)   NOT NULL DEFAULT '0000-00',
    "ToFc"        NVARCHAR(10)   NOT NULL DEFAULT '9999-99',
    "WorTypes"    NVARCHAR(100)  NOT NULL DEFAULT ',10,20,30,40,',  -- 可分摊的订单类型，前后带逗号
    "Descr"       NVARCHAR(500),
    "MatchBy"     NVARCHAR(10)   NOT NULL DEFAULT 'GRP', -- GRP 按物料组 / GRPTYPE 按 U_ItemGrpType（Q17，与 PP05 凭证车间一致）
    PRIMARY KEY ("PoolCode", "ItmsGrpCod", "FromFc")
)

@@
-- @stmt 新框架 05_config_pool.sql #5 补齐 MTC_CA_C_POOL_TGT 缺少的列
DO BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'PoolCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("PoolCode" NVARCHAR(20))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'ItmsGrpCod';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("ItmsGrpCod" NVARCHAR(20))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'FromFc';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("FromFc" NVARCHAR(10) DEFAULT ''0000-00'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'ToFc';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("ToFc" NVARCHAR(10) DEFAULT ''9999-99'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'WorTypes';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("WorTypes" NVARCHAR(100) DEFAULT '',10,20,30,40,'')'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'Descr';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("Descr" NVARCHAR(500))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_C_POOL_TGT' AND COLUMN_NAME = 'MatchBy';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_C_POOL_TGT" ADD ("MatchBy" NVARCHAR(10) DEFAULT ''GRP'')'; END IF;
END

@@
-- @stmt 新框架 05_config_pool.sql #6
COMMENT ON TABLE "MTC_CA_C_POOL_TGT" IS '费用池 → 可分摊的产品（按物料组或 U_ItemGrpType）和订单类型；权重 = 单位工时 × 订单本期入库数；同一产品只能属于一个池（Q22）'

