-- @stmt 新框架 06_snapshot_tables.sql #18
-- 历史委外差异转出（用户 2026-11-04，设计稿 8.9）：不带运行键，运行清理不动；P20_EXP 读 PlanFc = 本期的行
CREATE COLUMN TABLE "MTC_CA_WW_HIST" (
    "OrderType"  NVARCHAR(20)   NOT NULL,       -- 202 / MTC_OWOR
    "OrderEntry" INTEGER        NOT NULL,
    "DocNum"     INTEGER,                       -- 订单号 Num
    "ItemCode"   NVARCHAR(50),                  -- 产品
    "B1Status"   NVARCHAR(1),                   -- L 已结算 / C 已取消
    "CloseDate"  DATE,                          -- 关单日期（已取消且没有关单日期时 = 承接账期末）
    "LastFc"     NVARCHAR(10),                  -- 旧在产品表 0322_OWOR_ZCP 最后有这张订单的账期
    "Amount"     DECIMAL(19,2)  NOT NULL,       -- 留在 140801 的在产品金额，整张转出，可为负
    "LoadFc"     NVARCHAR(10),                  -- 载入时的承接账期
    "LoadTime"   TIMESTAMP,
    "PlanFc"     NVARCHAR(10),                  -- 计划在哪个账期转出；空 = 待转
    "PlanUser"   NVARCHAR(50),
    "PlanTime"   TIMESTAMP,
    "PlanNote"   NVARCHAR(500),                 -- 转出理由
    "Manual"     NVARCHAR(1)    DEFAULT 'N' NOT NULL,   -- Y = 已在 PlanFc 手工做分录转出，不进计算、不生成 JZ05
    PRIMARY KEY ("OrderType", "OrderEntry")
)

@@
