@@
-- @stmt 新框架 07_snapshot_procs.sql #1
-- =====================================================================
-- 新成本框架 第 1 期：P20 输入快照（设计稿 3.4、4）
-- 全部只读 B1，按“截至期末”取数；写 MTC_CA_S_*（带运行键）。
-- 账期范围取 OFPR.F_RefDate–T_RefDate（旧代码用 LEFT(日期,7)=账期，月度账期下等价）。
--   MTC_CA_F_PARAM / MTC_CA_F_ACCT  取参数、科目
--   MTC_CA_P_RUN_CTX                取运行键和账期起止日
--   MTC_CA_F_GI_ORDER               收货 / 发货行 → 订单（视图 MTC_VIEW_Document + U_OWORType 兜底），P20_LINE、P20_SUBFEE 共用（2026-10-31）
--   MTC_CA_P20_ITEM     物料与层级        替代 MTC_CO_001GetItemLevel
--   MTC_CA_P20_LINE     库存变动          替代 0303_INVNTDETAIL2（四段取数）
--   MTC_CA_P20_SUBFEE   委外加工费来源    替代 0306 / MTC_VIEW_ProductDetail ID 3
--   MTC_CA_P20_ORDER    订单与计划用料    替代 0321_OWOR、0106_OWORLIST
--   MTC_CA_P20_EXP      费用来源          替代 0311 的凭证、重估段
--   MTC_CA_P20_MISC     工时、期初维护价
--   MTC_CA_P20_OPEN     物料期初、订单 × 材料期初
--   MTC_CA_P05_CFG_SYNC 费用池 / 计算参数从 B1 自定义表同步到 MTC_CA_C_*（用户 2026-10-14；参数表 2026-10-28 改为 @MTC_CA_PARAM）
--     2026-10-29 起 P_RUN / P_PRECHECK / P_BOOTSTRAP 一开始就先调用它（RunId 为空，不记步骤）；同时刷新 B1 参数快照 MTC_CA_C_PARAM_B1
--   MTC_CA_P_PARAM_B1_SNAP / MTC_CA_P_PARAM_LOCK_CHECK  B1 参数锁定（U_Locked）：快照、保存时检查（2026-10-29）
--   MTC_CA_P20_SNAPSHOT 依次调用以上过程并写步骤日志
-- =====================================================================
CREATE OR REPLACE FUNCTION "MTC_CA_F_PARAM" (IN Code NVARCHAR(50), IN FcCode NVARCHAR(10))
RETURNS Val NVARCHAR(200)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    SELECT MAX("Value") INTO Val FROM "MTC_CA_C_PARAM"
     WHERE "ParamCode" = :Code AND :FcCode BETWEEN "FromFc" AND "ToFc";
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #2
CREATE OR REPLACE FUNCTION "MTC_CA_F_ACCT" (IN Usage NVARCHAR(30), IN FcCode NVARCHAR(10))
RETURNS Acct NVARCHAR(15)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    SELECT MAX("AcctCode") INTO Acct FROM "MTC_CA_C_ACCT"
     WHERE "Usage" = :Usage AND :FcCode BETWEEN "FromFc" AND "ToFc";
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #3
-- 收货（59）/ 发货（60）行 → 订单，P20_LINE（本期库存变动）和 P20_SUBFEE（加工费对应的生产收货，不限账期）共用一份规则（用户 2026-10-31）。
--   ① 视图 MTC_VIEW_Document 改写后的来源：U_OWORType='MTC_OWOR' 时为返工单（BaseEntry 取 U_MTCOWORNum），BaseType = -1 且
--      U_OWORType='202' 时按 U_OWORNum 找生产订单；行号只在 BaseType = -1 时取 U_ 行号。
--   ② 视图没给出订单（不是 202 / MTC_OWOR）的行，按行上 U_OWORType 补（2026-10-29，PRE-06）：'202' → U_OWORNum（OWOR.DocNum）找 DocEntry、
--      行号 U_OWORLineNum，单号对上多张订单时不关联；'MTC_OWOR' → U_MTCOWORNum（DocEntry）、行号 U_MTCOWORLineNum。形态转换（参数
--      CONV_IN_BUSITYPE / CONV_OUT_BUSITYPE）不动。不改旧模块共用的视图。
--   d0 / d1 为空 = 不限日期。Src：VIEW = 视图结果，UDF = 按 U_OWORType 补的。OrderLine 为空或 '' 的是完工 / 主件行。
CREATE OR REPLACE FUNCTION "MTC_CA_F_GI_ORDER" (IN Fc NVARCHAR(10), IN d0 DATE, IN d1 DATE)
RETURNS TABLE ("ObjType" NVARCHAR(20), "DocEntry" NVARCHAR(20), "LineNum" NVARCHAR(20), "U_BusiType" NVARCHAR(50),
               "OrderType" NVARCHAR(20), "OrderEntry" NVARCHAR(20), "OrderRef" NVARCHAR(100), "OrderLine" NVARCHAR(20), "Src" NVARCHAR(4))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE convIn NVARCHAR(20) := IFNULL("MTC_CA_F_PARAM"('CONV_IN_BUSITYPE', :Fc), '204');
    DECLARE convOut NVARCHAR(20) := IFNULL("MTC_CA_F_PARAM"('CONV_OUT_BUSITYPE', :Fc), '205');
    v = SELECT TO_NVARCHAR("ObjType") AS "ObjType", TO_NVARCHAR("DocEntry") AS "DocEntry", TO_NVARCHAR("LineNum") AS "LineNum",
               TO_NVARCHAR("U_BusiType") AS "U_BusiType", TO_NVARCHAR("BaseType") AS "BaseType", TO_NVARCHAR("BaseEntry") AS "BaseEntry",
               TO_NVARCHAR("BaseRef") AS "BaseRef", TO_NVARCHAR("BaseLine") AS "BaseLine"
          FROM "MTC_VIEW_Document"
         WHERE TO_NVARCHAR("ObjType") IN ('59', '60')
           AND (:d0 IS NULL OR "DocDate" >= :d0) AND (:d1 IS NULL OR "DocDate" <= :d1);
    gl = SELECT '59' AS "ObjType", TO_NVARCHAR(D."DocEntry") AS "DocEntry", TO_NVARCHAR(D."LineNum") AS "LineNum",
                TRIM(TO_NVARCHAR(D."U_OWORType")) AS "OT", NULLIF(TRIM(TO_NVARCHAR(D."U_OWORNum")), '') AS "ONum",
                TO_NVARCHAR(D."U_OWORLineNum") AS "OLine", NULLIF(TRIM(TO_NVARCHAR(D."U_MTCOWORNum")), '') AS "MNum",
                TO_NVARCHAR(D."U_MTCOWORLineNum") AS "MLine"
           FROM "IGN1" D JOIN "OIGN" H ON H."DocEntry" = D."DocEntry"
          WHERE (:d0 IS NULL OR H."DocDate" >= :d0) AND (:d1 IS NULL OR H."DocDate" <= :d1)
            AND TRIM(TO_NVARCHAR(D."U_OWORType")) IN ('202', 'MTC_OWOR')
         UNION ALL
         SELECT '60', TO_NVARCHAR(D."DocEntry"), TO_NVARCHAR(D."LineNum"),
                TRIM(TO_NVARCHAR(D."U_OWORType")), NULLIF(TRIM(TO_NVARCHAR(D."U_OWORNum")), ''),
                TO_NVARCHAR(D."U_OWORLineNum"), NULLIF(TRIM(TO_NVARCHAR(D."U_MTCOWORNum")), ''),
                TO_NVARCHAR(D."U_MTCOWORLineNum")
           FROM "IGE1" D JOIN "OIGE" H ON H."DocEntry" = D."DocEntry"
          WHERE (:d0 IS NULL OR H."DocDate" >= :d0) AND (:d1 IS NULL OR H."DocDate" <= :d1)
            AND TRIM(TO_NVARCHAR(D."U_OWORType")) IN ('202', 'MTC_OWOR');
    -- 订单号（DocNum）在不同编号序列里可能重复：对上多张订单时不关联（PRE-06 报出），避免一行变两行
    glo = SELECT G."ObjType", G."DocEntry", G."LineNum", MAX(G."OT") AS "OT",
                 CASE WHEN MAX(G."OT") = 'MTC_OWOR' THEN MAX(G."MNum")
                      WHEN COUNT(DISTINCT W."DocEntry") = 1 THEN TO_NVARCHAR(MAX(W."DocEntry")) END AS "OEntry",
                 CASE WHEN MAX(G."OT") = 'MTC_OWOR' THEN MAX(G."MNum") ELSE MAX(G."ONum") END AS "ORef",
                 CASE WHEN MAX(G."OT") = '202' THEN MAX(G."OLine") ELSE MAX(G."MLine") END AS "OLine"
            FROM :gl G
            LEFT JOIN "OWOR" W ON G."OT" = '202' AND TO_NVARCHAR(W."DocNum") = G."ONum"
           GROUP BY G."ObjType", G."DocEntry", G."LineNum";
    RETURN SELECT V."ObjType", V."DocEntry", V."LineNum", V."U_BusiType",
                  CASE WHEN F."OEntry" IS NOT NULL THEN F."OT" ELSE V."BaseType" END AS "OrderType",
                  CASE WHEN F."OEntry" IS NOT NULL THEN F."OEntry" ELSE V."BaseEntry" END AS "OrderEntry",
                  CASE WHEN F."OEntry" IS NOT NULL THEN F."ORef" ELSE V."BaseRef" END AS "OrderRef",
                  CASE WHEN F."OEntry" IS NOT NULL THEN F."OLine" ELSE V."BaseLine" END AS "OrderLine",
                  CASE WHEN F."OEntry" IS NOT NULL THEN 'UDF' ELSE 'VIEW' END AS "Src"
             FROM :v V
             LEFT JOIN :glo F ON F."ObjType" = V."ObjType" AND F."DocEntry" = V."DocEntry" AND F."LineNum" = V."LineNum"
                             AND IFNULL(V."BaseType", '') NOT IN ('202', 'MTC_OWOR')
                             AND IFNULL(V."U_BusiType", '') NOT IN (:convIn, :convOut);
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #4
CREATE OR REPLACE PROCEDURE "MTC_CA_P_RUN_CTX" (
    IN  RunId BIGINT,
    OUT fc    NVARCHAR(10),
    OUT rt    NVARCHAR(1),
    OUT scen  NVARCHAR(30),
    OUT d0    DATE,
    OUT d1    DATE
)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    SELECT MAX(R."FcCode"), MAX(R."RunType"), MAX(R."Scenario"), MAX(TO_DATE(P."F_RefDate")), MAX(TO_DATE(P."T_RefDate"))
      INTO fc, rt, scen, d0, d1
      FROM "MTC_CA_RUN" R JOIN "OFPR" P ON P."Code" = R."FcCode"
     WHERE R."RunId" = :RunId;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #5
-- 物料层级：无 BOM = 0；其余 = 子件最高级 + 1；子件缺失、循环引用 = -1（PRE-02 阻断）；最后按 C_LEVEL_OVR 覆盖。
-- 与旧算法的差别：只取 ITT1 中 Type=4（物料）的子件，资源行不参与；不再限制最高 8 级（LEVEL_GUARD 只防死循环）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_ITEM" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE guard INT;
    DECLARE i INT := 1;
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    guard := TO_INTEGER(IFNULL("MTC_CA_F_PARAM"('LEVEL_GUARD', :fc), '30'));

    bom = SELECT DISTINCT T1."Father", T1."Code" AS "Child"
            FROM "ITT1" T1 JOIN "OITT" T0 ON T0."Code" = T1."Father"
           WHERE T1."Type" = 4;

    INSERT INTO "MTC_CA_S_ITEM" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "ItemName", "ItmsGrpCod", "GrpType",
                                 "CalType", "InvntItem", "IsBomFather", "iLevel", "LevelSrc")
    SELECT :fc, :rt, :scen, :RunId, I."ItemCode", I."ItemName", TO_NVARCHAR(I."ItmsGrpCod"), G."U_ItemGrpType",
           I."U_ItemProp", I."InvntItem",
           CASE WHEN F."Father" IS NULL THEN 'N' ELSE 'Y' END,
           CASE WHEN F."Father" IS NULL THEN 0 ELSE -1 END,
           CASE WHEN F."Father" IS NULL THEN 'NOBOM' ELSE NULL END
      FROM "OITM" I
      LEFT JOIN "OITB" G ON G."ItmsGrpCod" = I."ItmsGrpCod"
      LEFT JOIN (SELECT DISTINCT "Father" FROM :bom) F ON F."Father" = I."ItemCode";
    RowCnt := ::ROWCOUNT;

    -- 第 i 轮：所有子件都已定级、且子件最高级 = i-1 的父件定为 i 级；某轮没有新定级的就不会再有
    WHILE :i <= :guard DO
        UPDATE "MTC_CA_S_ITEM" SET "iLevel" = :i, "LevelSrc" = 'BOM'
         WHERE "RunId" = :RunId AND "iLevel" = -1
           AND "ItemCode" IN (SELECT B."Father"
                                FROM :bom B
                                LEFT JOIN "MTC_CA_S_ITEM" C ON C."RunId" = :RunId AND C."ItemCode" = B."Child"
                               GROUP BY B."Father"
                              HAVING MIN(IFNULL(C."iLevel", -1)) >= 0 AND MAX(C."iLevel") = :i - 1);
        n := ::ROWCOUNT;
        IF :n = 0 THEN
            BREAK;
        END IF;
        i := :i + 1;
    END WHILE;

    UPDATE "MTC_CA_S_ITEM" SET "LevelNote" = '子件不在物料主数据'
     WHERE "RunId" = :RunId AND "iLevel" = -1
       AND "ItemCode" IN (SELECT B."Father" FROM :bom B
                           WHERE NOT EXISTS (SELECT 1 FROM "OITM" O WHERE O."ItemCode" = B."Child"));
    UPDATE "MTC_CA_S_ITEM"
       SET "LevelNote" = CASE WHEN :i > :guard THEN '超过层级保护上限 ' || :guard ELSE '循环引用，或子件未能定级' END
     WHERE "RunId" = :RunId AND "iLevel" = -1 AND "LevelNote" IS NULL;

    UPDATE T0 SET T0."iLevel" = T1."iLevel", T0."LevelSrc" = 'OVR',
                  T0."LevelNote" = '手工覆盖（原为 ' || T0."iLevel" || '）：' || IFNULL(T1."Reason", '')
      FROM "MTC_CA_S_ITEM" T0
      JOIN "MTC_CA_C_LEVEL_OVR" T1 ON T1."ItemCode" = T0."ItemCode" AND :fc BETWEEN T1."FromFc" AND T1."ToFc"
     WHERE T0."RunId" = :RunId;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #6
-- 库存变动：OIVL（计价仓库、排除 67 转储）+ MTC_VIEW_Document 识别交易类型、订单、配对键；
-- 采购收货 / 退货、应付发票 / 贷项的金额按旧 0303 规则算出 SrcAmt；再加 @MTC_OMRV 的 MRV1 重估行（I11；WW 改由 P20_AP 计算）。
-- 与旧 0303 的差别：仓库口径改为 U_IsCost（Q1）；18/19 没有基于收货的取发票行金额（#14）；作废的重估单不再计入。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_LINE" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE mfgp NVARCHAR(15);
    DECLARE convIn NVARCHAR(20); DECLARE convOut NVARCHAR(20);
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    mfgp := IFNULL("MTC_CA_F_ACCT"('MFG_EXP_PREFIX', :fc), '5101');
    convIn := IFNULL("MTC_CA_F_PARAM"('CONV_IN_BUSITYPE', :fc), '204');     -- 形态转换转入 / 转出的业务类型（参数，2026-10-27）
    convOut := IFNULL("MTC_CA_F_PARAM"('CONV_OUT_BUSITYPE', :fc), '205');

    vdoc0 = SELECT TO_NVARCHAR("ObjType") AS "ObjType", TO_NVARCHAR("DocEntry") AS "DocEntry", TO_NVARCHAR("LineNum") AS "LineNum",
                  "CANCELED", "CardCode", TO_NVARCHAR("BaseType") AS "BaseType", TO_NVARCHAR("BaseEntry") AS "BaseEntry",
                  TO_NVARCHAR("BaseRef") AS "BaseRef", TO_NVARCHAR("BaseLine") AS "BaseLine",
                  NULLIF("TransCode", '') AS "TransCode", "U_BusiType", "AcctCode", "OcrCode"
             FROM "MTC_VIEW_Document"
            WHERE "DocDate" BETWEEN :d0 AND :d1;
    -- 收货 / 发货行的订单：MTC_CA_F_GI_ORDER（视图 + U_OWORType 兜底，与 P20_SUBFEE 共用，2026-10-31；兜底规则 2026-10-29，PRE-06）
    glo = SELECT "ObjType", "DocEntry", "LineNum", "OrderType", "OrderEntry", "OrderLine"
            FROM "MTC_CA_F_GI_ORDER"(:fc, :d0, :d1) WHERE "Src" = 'UDF';
    vdoc = SELECT V."ObjType", V."DocEntry", V."LineNum", V."CANCELED", V."CardCode",
                  CASE WHEN F."DocEntry" IS NOT NULL THEN F."OrderType" ELSE V."BaseType" END AS "BaseType",
                  CASE WHEN F."DocEntry" IS NOT NULL THEN F."OrderEntry" ELSE V."BaseEntry" END AS "BaseEntry",
                  V."BaseRef",
                  CASE WHEN F."DocEntry" IS NOT NULL THEN F."OrderLine" ELSE V."BaseLine" END AS "BaseLine",
                  V."TransCode", V."U_BusiType", V."AcctCode", V."OcrCode"
             FROM :vdoc0 V
             LEFT JOIN :glo F ON F."ObjType" = V."ObjType" AND F."DocEntry" = V."DocEntry" AND F."LineNum" = V."LineNum";

    -- 收货 / 退货行的暂估单价（U_InitPrice 优先）
    rec = SELECT '20' AS "ObjType", D."DocEntry", D."LineNum",
                 CASE WHEN IFNULL(D."U_InitPrice", 0) <> 0 THEN D."U_InitPrice" ELSE D."Price" END AS "Price"
            FROM "PDN1" D
          UNION ALL
          SELECT '21', D."DocEntry", D."LineNum",
                 CASE WHEN IFNULL(D."U_InitPrice", 0) <> 0 THEN D."U_InitPrice" ELSE D."Price" END
            FROM "RPD1" D;

    -- 发票 / 贷项：基于收货 / 退货的取差额，否则取行金额；取消单取原单金额的相反数（原单不限日期）
    inv18 = SELECT D."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate", M."CANCELED", D."BaseType", D."BaseEntry", D."BaseLine",
                   CASE WHEN D."BaseType" IN (20, 21) THEN D."LineTotal" - D."Quantity" * IFNULL(R."Price", 0)
                        ELSE D."LineTotal" END AS "Amt"
              FROM "OPCH" M JOIN "PCH1" D ON D."DocEntry" = M."DocEntry"
              LEFT JOIN :rec R ON R."ObjType" = TO_NVARCHAR(D."BaseType") AND R."DocEntry" = D."BaseEntry" AND R."LineNum" = D."BaseLine";
    inv19 = SELECT D."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate", M."CANCELED", D."BaseType", D."BaseEntry", D."BaseLine",
                   CASE WHEN D."BaseType" IN (20, 21) THEN D."LineTotal" - D."Quantity" * IFNULL(R."Price", 0)
                        ELSE D."LineTotal" END AS "Amt"
              FROM "ORPC" M JOIN "RPC1" D ON D."DocEntry" = M."DocEntry"
              LEFT JOIN :rec R ON R."ObjType" = TO_NVARCHAR(D."BaseType") AND R."DocEntry" = D."BaseEntry" AND R."LineNum" = D."BaseLine";

    src = SELECT '20' AS "ObjType", D."DocEntry", D."LineNum",
                 CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END
                 * CASE WHEN IFNULL(D."U_InitPrice", 0) <> 0 THEN D."U_InitPrice" * D."Quantity" ELSE D."Price" * D."Quantity" END AS "Amt"
            FROM "OPDN" M JOIN "PDN1" D ON D."DocEntry" = M."DocEntry"
           WHERE M."DocDate" BETWEEN :d0 AND :d1
          UNION ALL
          SELECT '21', D."DocEntry", D."LineNum",
                 CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END
                 * CASE WHEN IFNULL(D."U_InitPrice", 0) <> 0 THEN D."U_InitPrice" * D."Quantity" ELSE D."LineTotal" END
            FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry"
           WHERE M."DocDate" BETWEEN :d0 AND :d1
          UNION ALL
          SELECT '18', A."DocEntry", A."LineNum",
                 CASE WHEN A."CANCELED" = 'C' THEN -IFNULL(O."Amt", 0) ELSE A."Amt" END
            FROM :inv18 A
            LEFT JOIN :inv18 O ON A."CANCELED" = 'C' AND A."BaseType" = 18 AND O."DocEntry" = A."BaseEntry" AND O."LineNum" = A."BaseLine"
           WHERE A."DocDate" BETWEEN :d0 AND :d1
          UNION ALL
          SELECT '19', A."DocEntry", A."LineNum",
                 CASE WHEN A."CANCELED" = 'C' THEN IFNULL(O."Amt", 0) ELSE -A."Amt" END
            FROM :inv19 A
            LEFT JOIN :inv19 O ON A."CANCELED" = 'C' AND A."BaseType" = 19 AND O."DocEntry" = A."BaseEntry" AND O."LineNum" = A."BaseLine"
           WHERE A."DocDate" BETWEEN :d0 AND :d1;

    INSERT INTO "MTC_CA_S_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "Src", "SrcKey", "ObjType", "DocEntry",
        "DocNum", "LineNum", "Canceled", "DocDate", "ItemCode", "WhsCode", "Qty", "B1Amt", "SrcAmt", "TransCode", "Dir",
        "BusiType", "BusiClass", "CardCode", "BaseType", "BaseEntry", "BaseLine", "OrderType", "OrderEntry", "OrderLine",
        "PairKey", "AcctCode", "OcrCode", "SharedExp")
    SELECT :fc, :rt, :scen, :RunId,
           ROW_NUMBER() OVER (ORDER BY P0."TransSeq"),
           'OIVL', TO_NVARCHAR(P0."TransSeq"), TO_NVARCHAR(P0."TransType"), P0."CreatedBy",
           TO_NVARCHAR(P0."BASE_REF"), P0."DocLineNum", V."CANCELED", TO_DATE(P0."DocDate"),
           P0."ItemCode", P0."LocCode", P0."InQty" - P0."OutQty", P0."SumStock", S."Amt",
           V."TransCode", IO."U_IOType", V."U_BusiType", C."U_TransType", V."CardCode",
           -- 销售退货：标准来源不是交货时，取行上 U_BaseType / U_BaseEntry / U_BaseLine 指向的原交货（PRE-04、退货定价）
           CASE WHEN R16."DocEntry" IS NOT NULL THEN '15' ELSE V."BaseType" END,
           CASE WHEN R16."DocEntry" IS NOT NULL THEN TO_NVARCHAR(R16."U_BaseEntry") ELSE V."BaseEntry" END,
           CASE WHEN R16."DocEntry" IS NOT NULL THEN TO_NVARCHAR(R16."U_BaseLine") ELSE V."BaseLine" END,
           -- 订单领料 / 入库：视图已把 59/60 的来源改写为订单（形态转换 CONV_IN_BUSITYPE / CONV_OUT_BUSITYPE 除外）
           -- 只有工单交易 I03/O03/I07/O07/I08/O08/I09/O09 关联订单；其他交易（如 210 其他辅助领用 O04）
           -- 单据上填了订单号也不关联，不计入订单成本，也不触发 PRE-10（用户 2026-10-14）
           CASE WHEN V."ObjType" IN ('59', '60') AND IFNULL(V."U_BusiType", '') NOT IN (:convIn, :convOut) AND V."TransCode" IN ('I03', 'O03', 'I07', 'O07', 'I08', 'O08', 'I09', 'O09')
                 AND V."BaseType" IN ('202', 'MTC_OWOR') THEN V."BaseType" END,
           CASE WHEN V."ObjType" IN ('59', '60') AND IFNULL(V."U_BusiType", '') NOT IN (:convIn, :convOut) AND V."TransCode" IN ('I03', 'O03', 'I07', 'O07', 'I08', 'O08', 'I09', 'O09')
                 AND V."BaseType" IN ('202', 'MTC_OWOR') AND V."BaseEntry" LIKE_REGEXPR '^[0-9]+$' THEN TO_INTEGER(V."BaseEntry") END,
           CASE WHEN V."ObjType" IN ('59', '60') AND IFNULL(V."U_BusiType", '') NOT IN (:convIn, :convOut) AND V."TransCode" IN ('I03', 'O03', 'I07', 'O07', 'I08', 'O08', 'I09', 'O09')
                 AND V."BaseType" IN ('202', 'MTC_OWOR') AND V."BaseLine" LIKE_REGEXPR '^[0-9]+$' THEN TO_INTEGER(V."BaseLine") END,
           CASE WHEN V."U_BusiType" IN (:convIn, :convOut) AND V."BaseType" IS NOT NULL AND V."BaseEntry" IS NOT NULL AND V."BaseLine" IS NOT NULL
                THEN V."BaseType" || '-' || V."BaseEntry" || '-' || V."BaseLine" END,
           V."AcctCode", V."OcrCode",
           CASE WHEN V."ObjType" IN ('59', '60') AND V."TransCode" IN ('I04', 'O04', 'I10', 'O10')
                 AND V."AcctCode" LIKE :mfgp || '%' THEN 'Y' ELSE 'N' END
      FROM "OIVL" P0
      JOIN "MTC_CA_V_WHS" W ON W."WhsCode" = P0."LocCode" AND W."IsCost" = 'Y'
      LEFT JOIN :vdoc V ON V."ObjType" = TO_NVARCHAR(P0."TransType") AND V."DocEntry" = TO_NVARCHAR(P0."CreatedBy")
                       AND V."LineNum" = TO_NVARCHAR(P0."DocLineNum")
      LEFT JOIN :src S ON S."ObjType" = TO_NVARCHAR(P0."TransType") AND S."DocEntry" = P0."CreatedBy" AND S."LineNum" = P0."DocLineNum"
      LEFT JOIN "@MTC_COST_IOTYPE" IO ON IO."Code" = V."TransCode"
      LEFT JOIN "@U_CIOTRN" C ON C."Code" = V."U_BusiType"
      LEFT JOIN "RDN1" R16 ON V."ObjType" = '16' AND IFNULL(V."CANCELED", 'N') <> 'C' AND IFNULL(V."BaseType", '') <> '15'
                          AND R16."DocEntry" = P0."CreatedBy" AND R16."LineNum" = P0."DocLineNum"
                          AND TO_NVARCHAR(R16."U_BaseType") = '15' AND R16."U_BaseEntry" IS NOT NULL AND R16."U_BaseLine" IS NOT NULL
     WHERE P0."DocDate" BETWEEN :d0 AND :d1
       AND P0."TransType" <> 67;
    RowCnt := ::ROWCOUNT;

    -- 库存重估 WW / MRV1 → I11；U_CalType=InvntCost 的只调整结存，不参与当期成本计算
    INSERT INTO "MTC_CA_S_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "Src", "SrcKey", "ObjType", "DocEntry",
        "DocNum", "LineNum", "Canceled", "DocDate", "ItemCode", "WhsCode", "Qty", "B1Amt", "SrcAmt", "TransCode", "Dir",
        "BaseType", "BaseEntry", "BaseLine", "AcctCode", "NoCost", "NoCostNote")
    SELECT :fc, :rt, :scen, :RunId,
           :RowCnt + ROW_NUMBER() OVER (ORDER BY T1."DocEntry", T1."LineId"),
           'OMRV', T1."DocEntry" || '-' || T1."LineId", IFNULL(T0."Object", 'MTC_OMRV'), T1."DocEntry",
           TO_NVARCHAR(T0."DocNum"), T1."LineId", T0."Canceled", TO_DATE(T0."U_DocDate"),
           IFNULL(T1."U_ItemCode", ''), NULL, 0, NULL, T1."U_Amount", 'I11', IO."U_IOType",
           T1."U_BaseType", TO_NVARCHAR(T1."U_BaseEntry"), TO_NVARCHAR(T1."U_BaseLine"), T1."U_AcctCode",
           CASE WHEN T1."U_CalType" = 'InvntCost' THEN 'Y' ELSE 'N' END,
           CASE WHEN T1."U_CalType" = 'InvntCost' THEN '重估类型 InvntCost：调整结存，不参与当期成本计算' END
      FROM "@MTC_OMRV" T0
      JOIN "@MTC_OMRV1" T1 ON T1."DocEntry" = T0."DocEntry"
      LEFT JOIN "@MTC_COST_IOTYPE" IO ON IO."Code" = 'I11'
     -- WW（委外发票差异，旧 6101_1 PUR3 写入）不再读，由 MTC_CA_P20_AP 从发票直接计算（设计稿 4.6）
     WHERE T0."U_BaseType" = 'MRV1'
       AND IFNULL(T0."Canceled", 'N') = 'N'
       AND T0."U_DocDate" BETWEEN :d0 AND :d1;
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #7
-- 委外加工费：加工费采购收货行（PDN1.U_BaseType='59' 指向生产收货）→ 生产收货所属订单；
-- 加工费退货按退货自己的日期计入（旧视图不分日期扣减）；@MTC_OMRV ProWW 中能找到订单的行也计入订单。
-- 没有关联采购收货的加工费退货（物料 = 参数 SUBFEE_ITEM；用户 2026-10-15 按 X 开头，2026-11-04 改：其他 X 开头物料不是加工费，原来被 PRE-12 误报）：取退货行自己的 U_BaseType/U_BaseEntry（生产收货），
-- 或直接按行上的 U_OWORNum / U_MTCOWORNum 找生产订单 / 返工单；之前漏掉，导致 WW03 多结转 140802（2026-09 POST-06）。
-- 生产收货的订单：取 MTC_CA_F_GI_ORDER 的完工 / 主件行，与 P20_LINE 同一规则（用户 2026-10-31；原来 202 取视图、返工单另读 IGN1，2026-10-13）。
-- 订单匹配：先按 收货单 + 加工费行上的订单匹配（202 比 U_OWORNum = OWOR.DocNum；返工单 U_OWORType='MTC_OWOR' 时 U_OWORNum 为空，
-- 比 U_MTCOWORNum = @MTC_OWOR.DocEntry，用户 2026-10-14）；收货单只对应一张订单时直接用；仍找不到的 OrderEntry 为空（PRE-12 警告，金额不进任何订单）。
-- 金额符号【读代码】：旧 0306 计入 4WWExp 的是 +LineTotal、ProWW 为 +U_Amount。
-- 金额口径（用户 2026-10-30 方案 B）：收货 / 退货改取 S_AP_MOVE 的暂估金额（指定单价 → 已确认价 → LineTotal），与 PUR4 借 140802 同一口径。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_SUBFEE" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE feeItem NVARCHAR(50);
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    feeItem := IFNULL("MTC_CA_F_PARAM"('SUBFEE_ITEM', :fc), 'X0510001');

    fee = SELECT 'PDN' AS "Src", D."DocEntry" || '-' || D."LineNum" AS "SrcKey", TO_DATE(M."DocDate") AS "DocDate",
                 D."ItemCode", CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity" AS "Qty",
                 CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END * D."LineTotal" AS "Amount",
                 TO_NVARCHAR(D."U_BaseEntry") AS "RcptEntry", TO_NVARCHAR(D."U_OWORNum") AS "OWORNum",
                 TO_NVARCHAR(D."U_OWORType") AS "OWORType", TO_NVARCHAR(D."U_MTCOWORNum") AS "MTCOWORNum"
            FROM "OPDN" M JOIN "PDN1" D ON D."DocEntry" = M."DocEntry"
           WHERE TO_NVARCHAR(D."U_BaseType") = '59' AND M."DocDate" BETWEEN :d0 AND :d1
          UNION ALL
          SELECT 'RPD', D."DocEntry" || '-' || D."LineNum", TO_DATE(M."DocDate"),
                 D."ItemCode", CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity",
                 CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."LineTotal",
                 TO_NVARCHAR(P."U_BaseEntry"), TO_NVARCHAR(P."U_OWORNum"),
                 TO_NVARCHAR(P."U_OWORType"), TO_NVARCHAR(P."U_MTCOWORNum")
            FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry"
            JOIN "PDN1" P ON D."BaseType" = 20 AND P."DocEntry" = D."BaseEntry" AND P."LineNum" = D."BaseLine"
           WHERE TO_NVARCHAR(P."U_BaseType") = '59' AND M."DocDate" BETWEEN :d0 AND :d1
          UNION ALL
          -- 没有关联采购收货的加工费退货（物料 = SUBFEE_ITEM，用户 2026-11-04）：用退货行自己的 U_ 字段找生产收货 / 订单
          SELECT 'RPD', D."DocEntry" || '-' || D."LineNum", TO_DATE(M."DocDate"),
                 D."ItemCode", CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity",
                 CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."LineTotal",
                 CASE WHEN TO_NVARCHAR(D."U_BaseType") = '59' THEN TO_NVARCHAR(D."U_BaseEntry") END, TO_NVARCHAR(D."U_OWORNum"),
                 TO_NVARCHAR(D."U_OWORType"), TO_NVARCHAR(D."U_MTCOWORNum")
            FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry"
           WHERE IFNULL(D."BaseType", -1) <> 20 AND D."ItemCode" = :feeItem AND M."DocDate" BETWEEN :d0 AND :d1;

    -- 生产收货 → 订单（完工 / 主件行：订单行为空）：与 P20_LINE 同一规则 MTC_CA_F_GI_ORDER（视图 + U_OWORType 兜底，2026-10-31），
    -- 不限日期（加工费可能对上月的生产收货）。原来 202 取视图、返工单另读 IGN1，BaseType 不是 -1 的 202 收货挂不上订单。
    rcpt = SELECT DISTINCT G."DocEntry" AS "RcptEntry", G."OrderType", G."OrderEntry", G."OrderRef"
             FROM "MTC_CA_F_GI_ORDER"(:fc, NULL, NULL) G
            WHERE G."ObjType" = '59' AND G."OrderType" IN ('202', 'MTC_OWOR') AND IFNULL(G."OrderLine", '') = ''
              AND G."DocEntry" IN (SELECT "RcptEntry" FROM :fee);

    cand = SELECT F."SrcKey", R."OrderType", R."OrderEntry",
                  CASE WHEN R."OrderType" = '202' AND R."OrderRef" = F."OWORNum" THEN 1
                       WHEN R."OrderType" = 'MTC_OWOR' AND F."OWORType" = 'MTC_OWOR' AND R."OrderEntry" = F."MTCOWORNum" THEN 1
                       ELSE 0 END AS "Hit",
                  COUNT(*) OVER (PARTITION BY F."Src", F."SrcKey") AS "Cnt", F."Src"
             FROM :fee F JOIN :rcpt R ON R."RcptEntry" = F."RcptEntry";
    cand2 = SELECT C.*, SUM(C."Hit") OVER (PARTITION BY C."Src", C."SrcKey") AS "Hits" FROM :cand C;
    pick0 = SELECT "Src", "SrcKey", "OrderType", "OrderEntry",
                   CASE WHEN "Hit" = 1 THEN '按生产收货 + 订单号匹配' ELSE '生产收货只对应一张订单' END AS "Note"
              FROM :cand2
             WHERE ("Hits" = 1 AND "Hit" = 1) OR ("Hits" = 0 AND "Cnt" = 1);
    -- 找不到生产收货时（没有关联收货的加工费退货），直接按行上的订单号找订单：
    -- 返工单 U_OWORType='MTC_OWOR' 时 U_MTCOWORNum = @MTC_OWOR.DocEntry，否则 U_OWORNum = OWOR.DocNum（用户 2026-10-15）
    dir = SELECT F."Src", F."SrcKey", 'MTC_OWOR' AS "OrderType", TO_NVARCHAR(R."DocEntry") AS "OrderEntry",
                 '按退货行上的返工单号匹配' AS "Note"
            FROM :fee F JOIN "@MTC_OWOR" R ON TO_NVARCHAR(R."DocEntry") = F."MTCOWORNum"
           WHERE F."OWORType" = 'MTC_OWOR'
          UNION ALL
          SELECT F."Src", F."SrcKey", '202', TO_NVARCHAR(W."DocEntry"), '按退货行上的生产订单号匹配'
            FROM :fee F JOIN "OWOR" W ON TO_NVARCHAR(W."DocNum") = F."OWORNum"
           WHERE IFNULL(F."OWORType", '') <> 'MTC_OWOR';
    -- 单号对应多张订单时不取，避免重复计入
    pick = SELECT "Src", "SrcKey", "OrderType", "OrderEntry", "Note" FROM :pick0
           UNION ALL
           SELECT D."Src", D."SrcKey", D."OrderType", D."OrderEntry", D."Note"
             FROM (SELECT X.*, COUNT(*) OVER (PARTITION BY X."Src", X."SrcKey") AS "Cnt" FROM :dir X) D
            WHERE D."Cnt" = 1
              AND NOT EXISTS (SELECT 1 FROM :pick0 P WHERE P."Src" = D."Src" AND P."SrcKey" = D."SrcKey");

    -- 金额取暂估口径（用户 2026-10-30 方案 B）：与 PUR4 计提同一份 S_AP_MOVE（P20_AP 先执行），指定单价 U_InitPrice → 已确认价 Price × 数量 → LineTotal，
    -- 退货按所基于收货行的暂估单价（含清余数）；S_AP_MOVE 里没有的（不是委外加工费物料 SUBFEE_ITEM）仍取 LineTotal。旧 0306 / 视图 ID 3 一律 LineTotal
    am = SELECT CASE WHEN "ObjType" = '20' THEN 'PDN' ELSE 'RPD' END AS "Src", "DocEntry" || '-' || "LineNum" AS "SrcKey", SUM("AccrAmt") AS "Amt"
           FROM "MTC_CA_S_AP_MOVE"
          WHERE "RunId" = :RunId AND "AccrType" = 'SUBFEE' AND "MoveType" IN ('ACCR', 'RET') AND "DocDate" BETWEEN :d0 AND :d1
          GROUP BY "ObjType", "DocEntry", "LineNum";
    INSERT INTO "MTC_CA_S_SUBFEE" ("FcCode", "RunType", "Scenario", "RunId", "FeeId", "Src", "SrcKey", "DocDate", "ItemCode",
                                   "Qty", "Amount", "RcptEntry", "OrderType", "OrderEntry", "MatchNote")
    SELECT :fc, :rt, :scen, :RunId, ROW_NUMBER() OVER (ORDER BY F."Src", F."SrcKey"),
           F."Src", F."SrcKey", F."DocDate", F."ItemCode", F."Qty", COALESCE(A."Amt", F."Amount"),
           CASE WHEN F."RcptEntry" LIKE_REGEXPR '^[0-9]+$' THEN TO_INTEGER(F."RcptEntry") END,
           K."OrderType", CASE WHEN K."OrderEntry" LIKE_REGEXPR '^[0-9]+$' THEN TO_INTEGER(K."OrderEntry") END,
           IFNULL(K."Note", CASE WHEN X."RcptEntry" IS NOT NULL
                                 THEN '生产收货对应多张订单，订单号对不上' ELSE '找不到生产收货或其订单' END)
      FROM :fee F
      LEFT JOIN :pick K ON K."Src" = F."Src" AND K."SrcKey" = F."SrcKey"
      LEFT JOIN :am A ON A."Src" = F."Src" AND A."SrcKey" = F."SrcKey"
      LEFT JOIN (SELECT DISTINCT "RcptEntry" FROM :rcpt) X ON X."RcptEntry" = F."RcptEntry";
    RowCnt := ::ROWCOUNT;

    INSERT INTO "MTC_CA_S_SUBFEE" ("FcCode", "RunType", "Scenario", "RunId", "FeeId", "Src", "SrcKey", "DocDate", "ItemCode",
                                   "Qty", "Amount", "OrderType", "OrderEntry", "MatchNote")
    SELECT :fc, :rt, :scen, :RunId, :RowCnt + ROW_NUMBER() OVER (ORDER BY T1."DocEntry", T1."LineId"),
           'PROWW', T1."DocEntry" || '-' || T1."LineId", TO_DATE(T0."U_DocDate"), T1."U_ItemCode",
           T1."U_Quantity", T1."U_Amount", T1."U_BaseType", T1."U_BaseEntry", '重估单行上的订单'
      FROM "@MTC_OMRV" T0
      JOIN "@MTC_OMRV1" T1 ON T1."DocEntry" = T0."DocEntry"
      LEFT JOIN "OWOR" W ON T1."U_BaseType" = '202' AND W."DocEntry" = T1."U_BaseEntry"
      LEFT JOIN "@MTC_OWOR" M ON T1."U_BaseType" = 'MTC_OWOR' AND M."DocEntry" = T1."U_BaseEntry"
     WHERE T0."U_BaseType" = 'ProWW' AND IFNULL(T0."Canceled", 'N') = 'N'
       AND T0."U_DocDate" BETWEEN :d0 AND :d1
       AND (W."DocEntry" IS NOT NULL OR M."DocEntry" IS NOT NULL);
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #8
-- 订单：本期范围内的订单（已下达、截至期初未关闭、未取消），加上本期单据引用到的其他订单（InScope='N'，PRE-10）。
-- 截至期末的状态（设计稿 Q4）：当前状态为关闭且关单日期 ≤ 期末 → CLOSED；关单日期在本期 → ClosedInFc。
-- 取消日期取 UpdateDate（用户 2026-11-04，OWOR 没有单独的取消日期）：本期及以后才取消的订单本期仍在范围内，本期取消的按关单处理，剩余在产品转关单差异；
-- 订单 120896 就是 9 月发料、10 月全部退回后 10-27 取消，期初和本期都要算上它。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_ORDER" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);

    ord = SELECT '202' AS "OrderType", W."DocEntry" AS "OrderEntry", TO_NVARCHAR(W."DocNum") AS "OrderNum",
                 TO_NVARCHAR(W."U_OrdType") AS "WorType", W."ItemCode", W."PlannedQty", TO_DATE(W."PostDate") AS "PostDate",
                 TO_NVARCHAR(W."Status") AS "B1Status", TO_DATE(W."CloseDate") AS "CloseDate", W."CardCode",
                 CASE WHEN W."Status" = 'C' THEN TO_DATE(W."UpdateDate") END AS "CancelDate"
            FROM "OWOR" W
          UNION ALL
          SELECT 'MTC_OWOR', M."DocEntry", TO_NVARCHAR(M."DocNum"), TO_NVARCHAR(M."U_OrdType"), M."U_ItemCode", M."U_PlannedQty",
                 TO_DATE(M."U_PostDate"), TO_NVARCHAR(M."U_Status"), TO_DATE(M."U_CloseDate"), M."U_CardCode",
                 CASE WHEN M."U_Status" = 'C' THEN TO_DATE(M."UpdateDate") END
            FROM "@MTC_OWOR" M;

    ref = SELECT DISTINCT "OrderType", "OrderEntry" FROM "MTC_CA_S_LINE" WHERE "RunId" = :RunId AND "OrderEntry" IS NOT NULL
          UNION
          SELECT DISTINCT "OrderType", "OrderEntry" FROM "MTC_CA_S_SUBFEE" WHERE "RunId" = :RunId AND "OrderEntry" IS NOT NULL;

    INSERT INTO "MTC_CA_S_ORDER" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "OrderNum", "WorType",
        "ItemCode", "PlannedQty", "PostDate", "B1Status", "CloseDate", "StatusAtEnd", "ClosedInFc", "InScope", "CardCode")
    SELECT :fc, :rt, :scen, :RunId, O."OrderType", O."OrderEntry", O."OrderNum", O."WorType", O."ItemCode", O."PlannedQty",
           O."PostDate", O."B1Status", O."CloseDate",
           CASE WHEN O."B1Status" = 'L' AND (O."CloseDate" IS NULL OR O."CloseDate" <= :d1) THEN 'CLOSED'
                WHEN O."CancelDate" BETWEEN :d0 AND :d1 THEN 'CLOSED' ELSE 'OPEN' END,
           CASE WHEN O."B1Status" = 'L' AND O."CloseDate" BETWEEN :d0 AND :d1 THEN 'Y'
                WHEN O."CancelDate" BETWEEN :d0 AND :d1 THEN 'Y' ELSE 'N' END,
           CASE WHEN (O."B1Status" <> 'C' OR O."CancelDate" >= :d0) AND IFNULL(O."PostDate", :d0) <= :d1
                 AND NOT (O."B1Status" = 'L' AND O."CloseDate" < :d0) THEN 'Y' ELSE 'N' END,
           O."CardCode"
      FROM :ord O
      LEFT JOIN :ref R ON R."OrderType" = O."OrderType" AND R."OrderEntry" = O."OrderEntry"
     WHERE ((O."B1Status" <> 'C' OR O."CancelDate" >= :d0) AND IFNULL(O."PostDate", :d0) <= :d1 AND NOT (O."B1Status" = 'L' AND O."CloseDate" < :d0))
        OR R."OrderEntry" IS NOT NULL;
    RowCnt := ::ROWCOUNT;

    UPDATE T0 SET T0."RecvQty" = T1."Qty"
      FROM "MTC_CA_S_ORDER" T0
      JOIN (SELECT "OrderType", "OrderEntry", SUM("Qty") AS "Qty"
              FROM "MTC_CA_S_LINE"
             WHERE "RunId" = :RunId AND "BusiClass" = 'B01' AND "OrderLine" IS NULL AND "OrderEntry" IS NOT NULL
             GROUP BY "OrderType", "OrderEntry") T1
        ON T1."OrderType" = T0."OrderType" AND T1."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId;

    INSERT INTO "MTC_CA_S_ORDER_LINE" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "OrderLine",
                                       "ItemCode", "BaseQty", "PlannedQty")
    SELECT :fc, :rt, :scen, :RunId, '202', L."DocEntry", L."LineNum", L."ItemCode", L."BaseQty", L."PlannedQty"
      FROM "WOR1" L
      JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = '202' AND O."OrderEntry" = L."DocEntry"
     WHERE L."ItemType" = 4
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, 'MTC_OWOR', L."DocEntry", L."LineId", L."U_ItemCode", L."U_BaseQty", L."U_PlannedQty"
      FROM "@MTC_WOR1" L
      JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = 'MTC_OWOR' AND O."OrderEntry" = L."DocEntry";
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #9
-- 费用来源（设计稿 4.4）：
--   JDT   已过账凭证：人工科目（LAB_EXP）与制造费用科目（MFG_EXP_PREFIX 开头），凭证代码在 EXP_JDT_TRANSCODES 中（沿用 0311）
--   WWHIST 历史委外差异转出：MTC_CA_WW_HIST 中 PlanFc = 本期的订单（用户 2026-11-04）
--   MRV   重估单 MRV1（含 InvntCost）：费用 = -U_Amount。旧 0311 还读 MRV2（旧 0501 写的 0 数量尾差），新框架由 TAIL-01 / JZ04 处理，
--         不再读（同 P70 的 MR02、P20_LINE，2026-10-17）
--   PROWW 重估单 ProWW 中找不到订单的行：费用 = -U_Amount（找得到订单的进 S_SUBFEE，不再同时进费用池）
-- 不再读 JZ01 / JZ03 草稿（关单差异由迭代产生）；公摊材料来自 S_LINE.SharedExp，在迭代中按当轮单价计价。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_EXP" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE lab NVARCHAR(15); DECLARE mfgp NVARCHAR(15); DECLARE codes NVARCHAR(200);
    DECLARE histAcct NVARCHAR(15); DECLARE histOcr NVARCHAR(20);
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    histAcct := "MTC_CA_F_ACCT"('WW_HIST_EXP', :fc);
    histOcr  := "MTC_CA_F_PARAM"('WW_HIST_OCR', :fc);
    lab   := IFNULL("MTC_CA_F_ACCT"('LAB_EXP', :fc), '500102');
    mfgp  := IFNULL("MTC_CA_F_ACCT"('MFG_EXP_PREFIX', :fc), '5101');
    codes := IFNULL("MTC_CA_F_PARAM"('EXP_JDT_TRANSCODES', :fc), ',,');

    INSERT INTO "MTC_CA_S_EXP" ("FcCode", "RunType", "Scenario", "RunId", "ExpId", "Src", "SrcKey", "SrcTrans", "SrcObj", "SrcDoc",
                                "DocDate", "AcctCode", "OcrCode", "Elem", "Amount")
    SELECT :fc, :rt, :scen, :RunId, ROW_NUMBER() OVER (ORDER BY T1."TransId", T1."Line_ID"),
           'JDT', T1."TransId" || '-' || T1."Line_ID", IFNULL(T0."TransCode", ''), TO_NVARCHAR(T0."TransType"), T0."CreatedBy",
           TO_DATE(T0."RefDate"), T1."Account", T1."ProfitCode",
           CASE WHEN T1."Account" = :lab THEN 'LAB' ELSE 'MFG' END,
           T1."Debit" - T1."Credit"
      FROM "OJDT" T0
      JOIN "JDT1" T1 ON T1."TransId" = T0."TransId"
      LEFT JOIN "OJDT" R ON R."TransId" = T0."StornoToTr"
     WHERE T0."RefDate" BETWEEN :d0 AND :d1
       AND (T1."Account" = :lab OR T1."Account" LIKE :mfgp || '%')
       -- 冲销凭证没带凭证代码时按原凭证的代码算，成本凭证的冲销不进费用池（用户 2026-11-05）
       AND LOCATE(:codes, ',' || COALESCE(NULLIF(T0."TransCode", ''), R."TransCode", '') || ',') > 0;
    RowCnt := ::ROWCOUNT;

    INSERT INTO "MTC_CA_S_EXP" ("FcCode", "RunType", "Scenario", "RunId", "ExpId", "Src", "SrcKey", "SrcTrans", "SrcObj", "SrcDoc",
                                "DocDate", "AcctCode", "OcrCode", "Elem", "Amount", "Note")
    SELECT :fc, :rt, :scen, :RunId, :RowCnt + ROW_NUMBER() OVER (ORDER BY T1."DocEntry", T1."LineId"),
           CASE WHEN T0."U_BaseType" = 'ProWW' THEN 'PROWW' ELSE 'MRV' END,
           T1."DocEntry" || '-' || T1."LineId", T0."U_BaseType", IFNULL(T0."Object", 'MTC_OMRV'), T1."DocEntry",
           TO_DATE(T0."U_DocDate"), T1."U_AcctCode", NULL, 'MFG', -T1."U_Amount",
           CASE WHEN T0."U_BaseType" = 'ProWW' THEN '没有关联到订单的委外重估' ELSE '重估类型 ' || IFNULL(T1."U_CalType", '') END
      FROM "@MTC_OMRV" T0
      JOIN "@MTC_OMRV1" T1 ON T1."DocEntry" = T0."DocEntry"
      LEFT JOIN "OWOR" W ON T1."U_BaseType" = '202' AND W."DocEntry" = T1."U_BaseEntry"
      LEFT JOIN "@MTC_OWOR" M ON T1."U_BaseType" = 'MTC_OWOR' AND M."DocEntry" = T1."U_BaseEntry"
     WHERE IFNULL(T0."Canceled", 'N') = 'N'
       AND T0."U_DocDate" BETWEEN :d0 AND :d1
       AND (T0."U_BaseType" = 'MRV1'
            OR (T0."U_BaseType" = 'ProWW' AND W."DocEntry" IS NULL AND M."DocEntry" IS NULL));
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;

    -- 历史委外差异转出（用户 2026-11-04）：本期计划转出的订单进费用池，P70 按这些行生成 JZ05，不依赖凭证是否已过账
    INSERT INTO "MTC_CA_S_EXP" ("FcCode", "RunType", "Scenario", "RunId", "ExpId", "Src", "SrcKey", "SrcTrans", "SrcObj", "SrcDoc",
                                "DocDate", "AcctCode", "OcrCode", "Elem", "Amount", "Note")
    SELECT :fc, :rt, :scen, :RunId, :RowCnt + ROW_NUMBER() OVER (ORDER BY "OrderType", "OrderEntry"),
           'WWHIST', "OrderType" || '-' || "OrderEntry", 'JZ05', "OrderType", "OrderEntry",
           :d1, :histAcct, :histOcr, 'MFG', "Amount", '历史委外差异转出：订单号 Num ' || IFNULL(TO_NVARCHAR("DocNum"), '')
      FROM "MTC_CA_WW_HIST" WHERE "PlanFc" = :fc AND "Manual" = 'N';
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #10
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_MISC" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);

    -- 工时全是空的物料取 0（2026-10-30：MAX 为 NULL 时写表报 SQL 287，整个运行失败），由 PRE-14 当作没有工时报出
    INSERT INTO "MTC_CA_S_HOURS" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "Hours", "MinHours", "LineCnt")
    SELECT :fc, :rt, :scen, :RunId, T1."U_ItemCode", IFNULL(MAX(T1."U_Time"), 0), IFNULL(MIN(T1."U_Time"), 0), COUNT(*)
      FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T1."DocEntry" = T0."DocEntry"
     WHERE T0."U_FcCode" = :fc AND IFNULL(T0."Canceled", 'N') = 'N' AND T1."U_ItemCode" IS NOT NULL
     GROUP BY T1."U_ItemCode";
    RowCnt := ::ROWCOUNT;

    INSERT INTO "MTC_CA_S_QCPRICE" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "Price", "MinPrice", "LineCnt")
    SELECT :fc, :rt, :scen, :RunId, T1."U_ItemCode", MAX(T1."U_Price"), MIN(T1."U_Price"), COUNT(*)
      FROM "@MTC_COST_QCPRICE" T0 JOIN "@MTC_COST_QCPRICE1" T1 ON T1."DocEntry" = T0."DocEntry"
     WHERE T0."U_FcCode" = :fc AND IFNULL(T0."Canceled", 'N') = 'N' AND T1."U_ItemCode" IS NOT NULL
       AND IFNULL(T1."U_Price", 0) <> 0
     GROUP BY T1."U_ItemCode";
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #11
-- 期初：上期 = 承接账期（BOOTSTRAP_FC）时取 MTC_CA_BOOT_*；否则取上期新框架最近一次成功的正式运行结果（2026-10-18 实现）。
-- 取不到时不报错，由 PRE-16 阻断。模拟运行同样取上期正式结果。
-- 上期正式结果重算后，本期要重新计算（期初在取快照时复制，不随上期变化）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_OPEN" (IN RunId BIGINT, OUT RowCnt BIGINT, OUT Msg NVARCHAR(500))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE prev NVARCHAR(10); DECLARE boot NVARCHAR(10);
    DECLARE prevRun BIGINT;
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    SELECT MAX("Code") INTO prev FROM "OFPR" WHERE "Code" < :fc;
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :fc);
    RowCnt := 0;

    IF :prev = :boot THEN
        INSERT INTO "MTC_CA_S_OPEN" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "Qty",
                                     "MatAmt", "MfgAmt", "LabAmt", "SubAmt", "Amount", "Src")
        SELECT :fc, :rt, :scen, :RunId, "ItemCode", "Qty", "MatAmt", "MfgAmt", "LabAmt", "SubAmt", "Amount", 'BOOT'
          FROM "MTC_CA_BOOT_ITEM" WHERE "FcCode" = :boot;
        RowCnt := ::ROWCOUNT;

        -- 订单 × 材料：旧框架不分料工费，按领用材料的承接比例（MTC_CA_BOOT_RATIO）拆分，没有比例的全部记材料（用户 2026-10-18）；
        -- 制造、人工、委外四舍五入到分，材料 = 金额 − 其余三项
        INSERT INTO "MTC_CA_S_ORDER_OPEN" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "ItemCode",
                                           "CumIssueQty", "CumIssueMat", "CumIssueMfg", "CumIssueLab", "CumIssueSub",
                                           "CumCarriedMat", "CumCarriedMfg", "CumCarriedLab", "CumCarriedSub", "Src")
        SELECT :fc, :rt, :scen, :RunId, B."OrderType", B."OrderEntry", B."ItemCode", B."CumIssueQty",
               B."CumIssueAmt" - ROUND(B."CumIssueAmt" * IFNULL(R."RMfg", 0), 2) - ROUND(B."CumIssueAmt" * IFNULL(R."RLab", 0), 2)
                               - ROUND(B."CumIssueAmt" * IFNULL(R."RSub", 0), 2),
               ROUND(B."CumIssueAmt" * IFNULL(R."RMfg", 0), 2), ROUND(B."CumIssueAmt" * IFNULL(R."RLab", 0), 2),
               ROUND(B."CumIssueAmt" * IFNULL(R."RSub", 0), 2),
               B."CumCarriedAmt" - ROUND(B."CumCarriedAmt" * IFNULL(R."RMfg", 0), 2) - ROUND(B."CumCarriedAmt" * IFNULL(R."RLab", 0), 2)
                                 - ROUND(B."CumCarriedAmt" * IFNULL(R."RSub", 0), 2),
               ROUND(B."CumCarriedAmt" * IFNULL(R."RMfg", 0), 2), ROUND(B."CumCarriedAmt" * IFNULL(R."RLab", 0), 2),
               ROUND(B."CumCarriedAmt" * IFNULL(R."RSub", 0), 2),
               'BOOT'
          FROM "MTC_CA_BOOT_ORDER_MAT" B
          LEFT JOIN "MTC_CA_BOOT_RATIO" R ON R."FcCode" = B."FcCode" AND R."ItemCode" = B."ItemCode"
         WHERE B."FcCode" = :boot;
        n := ::ROWCOUNT;
        RowCnt := :RowCnt + :n;

        UPDATE T0 SET T0."PrevRecvQty" = T1."CumRecvQty"
          FROM "MTC_CA_S_ORDER" T0
          JOIN "MTC_CA_BOOT_ORDER" T1 ON T1."FcCode" = :boot AND T1."OrderType" = T0."OrderType" AND T1."OrderEntry" = T0."OrderEntry"
         WHERE T0."RunId" = :RunId;
        Msg := '期初取自承接账期 ' || :boot;
    ELSE
        -- 上期已生成凭单时取凭单所用的那次运行（账期状态 MTC_CA_PERIOD，2026-10-19）；
        -- 否则取上期最近一次成功的正式运行（只有它保留明细；上期未生成凭单时 P00 已警告）
        SELECT MAX("PostRunId") INTO prevRun FROM "MTC_CA_PERIOD" WHERE "FcCode" = :prev AND "Status" = 'POSTED';
        IF :prevRun IS NULL THEN
            SELECT MAX("RunId") INTO prevRun FROM "MTC_CA_RUN"
             WHERE "FcCode" = :prev AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'OK';
        END IF;
        IF :prevRun IS NULL THEN
            Msg := '上期 ' || IFNULL(:prev, '（无）') || ' 没有成功的正式运行，请先计算上期';
        ELSE
            -- 物料：上期期末数量和四项金额
            INSERT INTO "MTC_CA_S_OPEN" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "Qty",
                                         "MatAmt", "MfgAmt", "LabAmt", "SubAmt", "Amount", "Src")
            SELECT :fc, :rt, :scen, :RunId, "ItemCode", "EndQty", "EndMat", "EndMfg", "EndLab", "EndSub",
                   "EndMat" + "EndMfg" + "EndLab" + "EndSub", 'PREV'
              FROM "MTC_CA_R_ITEM"
             WHERE "RunId" = :prevRun
               AND ("EndQty" <> 0 OR "EndMat" <> 0 OR "EndMfg" <> 0 OR "EndLab" <> 0 OR "EndSub" <> 0);
            RowCnt := ::ROWCOUNT;

            -- 订单 × 材料（含 '#SUBFEE' 委外加工费）：累计领料 = 上期期初累计 + 上期领料；累计结转 = 上期期初累计 + 上期结转 + 关单差异
            -- （即累计领料 − 累计结转 = 上期期末在产品）。上期按关单处理的订单（ClosedInFc = 'Y'）在产品已转关单差异，不再带入；
            -- 未关闭订单的行全部带入（在产品为 0 的也带，结转比例按累计数算）
            INSERT INTO "MTC_CA_S_ORDER_OPEN" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "ItemCode",
                                               "CumIssueQty", "CumIssueMat", "CumIssueMfg", "CumIssueLab", "CumIssueSub",
                                               "CumCarriedMat", "CumCarriedMfg", "CumCarriedLab", "CumCarriedSub", "Src")
            SELECT :fc, :rt, :scen, :RunId, M."OrderType", M."OrderEntry", M."ItemCode",
                   M."OpenIssQty" + M."IssQty",
                   M."OpenIssMat" + M."IssMat", M."OpenIssMfg" + M."IssMfg", M."OpenIssLab" + M."IssLab", M."OpenIssSub" + M."IssSub",
                   M."OpenCarMat" + M."CarMat" + M."ClsMat", M."OpenCarMfg" + M."CarMfg" + M."ClsMfg",
                   M."OpenCarLab" + M."CarLab" + M."ClsLab", M."OpenCarSub" + M."CarSub" + M."ClsSub",
                   'PREV'
              FROM "MTC_CA_R_ORDER_MAT" M
              JOIN "MTC_CA_R_ORDER" O ON O."RunId" = M."RunId" AND O."OrderType" = M."OrderType" AND O."OrderEntry" = M."OrderEntry"
             WHERE M."RunId" = :prevRun AND O."ClosedInFc" = 'N';
            n := ::ROWCOUNT;
            RowCnt := :RowCnt + :n;

            -- 订单累计入库数 = 上期的截至上期累计 + 上期入库
            UPDATE T0 SET T0."PrevRecvQty" = T1."PrevRecvQty" + T1."RecvQty"
              FROM "MTC_CA_S_ORDER" T0
              JOIN "MTC_CA_R_ORDER" T1 ON T1."RunId" = :prevRun AND T1."OrderType" = T0."OrderType" AND T1."OrderEntry" = T0."OrderEntry"
             WHERE T0."RunId" = :RunId;
            Msg := '期初取自上期 ' || :prev || ' 正式运行 #' || :prevRun;
        END IF;
    END IF;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #12
-- 应付暂估变动（替代 6101_1 的 TMP 取数，设计稿 4.6；Q16、Q26–Q28）：
--   暂估行 = 收货行、不基于收货的退货行，物料是库存物料或委外加工费物料（SUBFEE_ITEM）；
--   变动 = 暂估行本身（ACCR）、基于它的退货 / 换货（RET）、发票 / 贷项（INV），以及这些单据的取消单（取原单的相反数，Q26）；
--   开票、退货冲回 = 数量 × 暂估单价，累计数量达到暂估行数量的那一笔 = 整行暂估 − 以前已冲回（Q27）；
--   退货按所基于收货行的暂估单价（Q28）。只保存截至期末仍未清、或本期有变动的暂估行（含其历史变动）。
--   暂估单价（材料、委外加工费相同）：U_InitPrice（期初和上线后系统 Price 有误时的指定单价）→ U_IsPrice='Y' 已确认价 Price × 数量 → LineTotal。
--   委外加工费计入订单的金额（P20_SUBFEE）也取本表，与 PUR4 同一口径（用户 2026-10-30 方案 B）。
-- 委外加工费发票的“发票 − 暂估”差额同时写入 S_LINE（Src='APDIF'，I11，物料 = 发票行 U_ItemCode 的产品），
-- 替代旧 6101_1 PUR3 写的 @MTC_OMRV WW 重估单（新框架不再读 WW 单）。
-- 材料（库存物料）的收货、退货、发票差额：用本表金额覆盖 P20_LINE 按旧 0303 规则算的 S_LINE.SrcAmt，
-- 使物料成本与 PUR1 / PUR2 凭证同一口径（Q29，用户 2026-10-13 同意）；同一单据行有多条 OIVL 时金额放在第一条。
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_AP" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE feeItem NVARCHAR(50); DECLARE difAcct NVARCHAR(15);
    DECLARE maxLine BIGINT; DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    feeItem := IFNULL("MTC_CA_F_PARAM"('SUBFEE_ITEM', :fc), 'X0510001');
    difAcct := "MTC_CA_F_ACCT"('WW_FEE_DIF', :fc);

    base = SELECT '20' AS "BaseObj", M."DocEntry" AS "BaseEntry", D."LineNum" AS "BaseLine", TO_DATE(M."DocDate") AS "BaseDate",
                  1 AS "BaseSign", D."Quantity" AS "BaseQty", M."CardCode", D."ItemCode",
                  D."U_InitPrice", D."U_IsPrice", D."Price", D."LineTotal"
             FROM "OPDN" M JOIN "PDN1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND IFNULL(D."BaseType", -1) <> 21
           UNION ALL
           SELECT '21', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), -1, D."Quantity", M."CardCode", D."ItemCode",
                  D."U_InitPrice", D."U_IsPrice", D."Price", D."LineTotal"
             FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND IFNULL(D."BaseType", -1) <> 20;
    bp = SELECT B."BaseObj", B."BaseEntry", B."BaseLine", B."BaseDate", B."BaseSign", B."BaseQty", B."CardCode", B."ItemCode",
                CASE WHEN B."ItemCode" = :feeItem THEN 'SUBFEE' ELSE 'MAT' END AS "AccrType",
                CASE WHEN IFNULL(B."U_InitPrice", 0) <> 0 THEN B."U_InitPrice" WHEN B."U_IsPrice" = 'Y' THEN B."Price"
                     ELSE B."LineTotal" / NULLIF(B."BaseQty", 0) END AS "UP",
                ROUND(CASE WHEN IFNULL(B."U_InitPrice", 0) <> 0 THEN B."BaseQty" * B."U_InitPrice"
                           WHEN B."U_IsPrice" = 'Y' THEN B."BaseQty" * B."Price" ELSE B."LineTotal" END, 2) AS "FullAmt"
           FROM :base B JOIN "OITM" I ON I."ItemCode" = B."ItemCode"
          WHERE I."InvntItem" = 'Y' OR B."ItemCode" = :feeItem;

    -- 取消单行 → 原单行
    cx = SELECT '20' AS "ObjType", M."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate", '20' AS "OrigObj", D."BaseEntry" AS "OrigEntry", D."BaseLine" AS "OrigLine"
           FROM "OPDN" M JOIN "PDN1" D ON D."DocEntry" = M."DocEntry" WHERE M."CANCELED" = 'C' AND D."BaseType" = 20 AND M."DocDate" <= :d1
         UNION ALL
         SELECT '21', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), '21', D."BaseEntry", D."BaseLine"
           FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry" WHERE M."CANCELED" = 'C' AND D."BaseType" = 21 AND M."DocDate" <= :d1
         UNION ALL
         SELECT '18', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), '18', D."BaseEntry", D."BaseLine"
           FROM "OPCH" M JOIN "PCH1" D ON D."DocEntry" = M."DocEntry" WHERE M."CANCELED" = 'C' AND D."BaseType" = 18 AND M."DocDate" <= :d1
         UNION ALL
         SELECT '19', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), '19', D."BaseEntry", D."BaseLine"
           FROM "ORPC" M JOIN "RPC1" D ON D."DocEntry" = M."DocEntry" WHERE M."CANCELED" = 'C' AND D."BaseType" = 19 AND M."DocDate" <= :d1;

    -- 消耗暂估行的原单：发票 / 贷项（INV）、退货 / 换货（RET）
    cons = SELECT '18' AS "ObjType", M."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate",
                  TO_NVARCHAR(D."BaseType") AS "BaseObj", D."BaseEntry", D."BaseLine", D."Quantity" AS "Q",
                  D."LineTotal" AS "DocAmt", D."U_ItemCode" AS "ProdItem", 'INV' AS "MoveType"
             FROM "OPCH" M JOIN "PCH1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND D."BaseType" IN (20, 21)
           UNION ALL
           SELECT '19', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), TO_NVARCHAR(D."BaseType"), D."BaseEntry", D."BaseLine", D."Quantity",
                  -D."LineTotal", D."U_ItemCode", 'INV'
             FROM "ORPC" M JOIN "RPC1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND D."BaseType" IN (20, 21)
           UNION ALL
           SELECT '21', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), '20', D."BaseEntry", D."BaseLine", D."Quantity", NULL, NULL, 'RET'
             FROM "ORPD" M JOIN "RPD1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND D."BaseType" = 20
           UNION ALL
           SELECT '20', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), '21', D."BaseEntry", D."BaseLine", D."Quantity", NULL, NULL, 'RET'
             FROM "OPDN" M JOIN "PDN1" D ON D."DocEntry" = M."DocEntry"
            WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d1 AND D."BaseType" = 21;

    -- 原单 + 取消单；先按 数量 × 暂估单价 取整，再找累计数量达到暂估行数量的那一笔
    ev = SELECT B."BaseObj", B."BaseEntry", B."BaseLine", C."ObjType", C."DocEntry", C."LineNum", C."DocDate", 'N' AS "IsCancel",
                C."ObjType" AS "OrigObj", C."DocEntry" AS "OrigEntry", C."LineNum" AS "OrigLine",
                C."Q" AS "CQ", ROUND(C."Q" * B."UP", 2) AS "Simple", C."DocAmt", C."ProdItem", C."MoveType"
           FROM :cons C JOIN :bp B ON B."BaseObj" = C."BaseObj" AND B."BaseEntry" = C."BaseEntry" AND B."BaseLine" = C."BaseLine"
         UNION ALL
         SELECT B."BaseObj", B."BaseEntry", B."BaseLine", X."ObjType", X."DocEntry", X."LineNum", X."DocDate", 'Y',
                C."ObjType", C."DocEntry", C."LineNum",
                -C."Q", -ROUND(C."Q" * B."UP", 2), -C."DocAmt", C."ProdItem", C."MoveType"
           FROM :cx X
           JOIN :cons C ON C."ObjType" = X."OrigObj" AND C."DocEntry" = X."OrigEntry" AND C."LineNum" = X."OrigLine"
           JOIN :bp B ON B."BaseObj" = C."BaseObj" AND B."BaseEntry" = C."BaseEntry" AND B."BaseLine" = C."BaseLine";
    ew = SELECT E.*, B."BaseQty", B."FullAmt",
                SUM(E."CQ") OVER (PARTITION BY E."BaseObj", E."BaseEntry", E."BaseLine"
                                  ORDER BY E."DocDate", E."IsCancel", E."ObjType", E."DocEntry", E."LineNum" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "CumQ",
                SUM(E."Simple") OVER (PARTITION BY E."BaseObj", E."BaseEntry", E."BaseLine"
                                      ORDER BY E."DocDate", E."IsCancel", E."ObjType", E."DocEntry", E."LineNum" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "CumS"
           FROM :ev E JOIN :bp B ON B."BaseObj" = E."BaseObj" AND B."BaseEntry" = E."BaseEntry" AND B."BaseLine" = E."BaseLine";
    eo = SELECT W.*,
                CASE WHEN W."IsCancel" = 'N' AND W."CumQ" >= W."BaseQty" - 0.000001 AND W."CumQ" - W."CQ" < W."BaseQty" - 0.000001
                     THEN W."FullAmt" - (W."CumS" - W."Simple") ELSE W."Simple" END AS "Mag",
                CASE WHEN W."IsCancel" = 'N' AND W."CumQ" >= W."BaseQty" - 0.000001 AND W."CumQ" - W."CQ" < W."BaseQty" - 0.000001
                     THEN 'LAST' ELSE 'ROUND' END AS "Rule"
           FROM :ew W;
    -- 取消单取原单最终金额的相反数（原单若是清余数的那一笔，也按清余数后的金额反向）
    ef = SELECT E."BaseObj", E."BaseEntry", E."BaseLine", E."ObjType", E."DocEntry", E."LineNum", E."DocDate", E."IsCancel",
                E."CQ", CASE WHEN E."IsCancel" = 'Y' THEN -O."Mag" ELSE E."Mag" END AS "Mag",
                CASE WHEN E."IsCancel" = 'Y' THEN 'CANCEL' ELSE E."Rule" END AS "Rule",
                E."DocAmt", E."ProdItem", E."MoveType"
           FROM :eo E
           LEFT JOIN :eo O ON E."IsCancel" = 'Y' AND O."IsCancel" = 'N' AND O."ObjType" = E."OrigObj" AND O."DocEntry" = E."OrigEntry" AND O."LineNum" = E."OrigLine"
                          AND O."BaseObj" = E."BaseObj" AND O."BaseEntry" = E."BaseEntry" AND O."BaseLine" = E."BaseLine";

    mv = SELECT B."BaseObj", B."BaseEntry", B."BaseLine", 'ACCR' AS "MoveType", 'N' AS "IsCancel", B."BaseObj" AS "ObjType",
                B."BaseEntry" AS "DocEntry", B."BaseLine" AS "LineNum", B."BaseDate" AS "DocDate",
                B."BaseQty" AS "Qty", B."BaseSign" * B."FullAmt" AS "AccrAmt", CAST(NULL AS DECIMAL(19,2)) AS "DocAmt",
                CAST(NULL AS NVARCHAR(50)) AS "ProdItem", 'FULL' AS "AmtRule"
           FROM :bp B
         UNION ALL
         SELECT B."BaseObj", B."BaseEntry", B."BaseLine", 'ACCR', 'Y', X."ObjType", X."DocEntry", X."LineNum", X."DocDate",
                -B."BaseQty", -B."BaseSign" * B."FullAmt", NULL, NULL, 'CANCEL'
           FROM :cx X JOIN :bp B ON B."BaseObj" = X."OrigObj" AND B."BaseEntry" = X."OrigEntry" AND B."BaseLine" = X."OrigLine"
         UNION ALL
         SELECT F."BaseObj", F."BaseEntry", F."BaseLine", F."MoveType", F."IsCancel", F."ObjType", F."DocEntry", F."LineNum", F."DocDate",
                -F."CQ", -B."BaseSign" * F."Mag", F."DocAmt", F."ProdItem", F."Rule"
           FROM :ef F JOIN :bp B ON B."BaseObj" = F."BaseObj" AND B."BaseEntry" = F."BaseEntry" AND B."BaseLine" = F."BaseLine";

    keep = SELECT "BaseObj", "BaseEntry", "BaseLine" FROM :mv
            GROUP BY "BaseObj", "BaseEntry", "BaseLine"
           HAVING ABS(SUM("Qty")) > 0.000001 OR ABS(SUM("AccrAmt")) >= 0.005 OR MAX("DocDate") >= :d0;

    INSERT INTO "MTC_CA_S_AP_MOVE" ("FcCode", "RunType", "Scenario", "RunId", "MoveId", "BaseObj", "BaseEntry", "BaseLine", "BaseDate",
        "BaseSign", "BaseQty", "UnitPrice", "FullAmt", "CardCode", "ItemCode", "AccrType", "MoveType", "IsCancel",
        "ObjType", "DocEntry", "LineNum", "DocDate", "Qty", "AccrAmt", "DocAmt", "ProdItem", "AmtRule")
    SELECT :fc, :rt, :scen, :RunId,
           ROW_NUMBER() OVER (ORDER BY M."BaseObj", M."BaseEntry", M."BaseLine", M."DocDate", M."IsCancel", M."ObjType", M."DocEntry", M."LineNum"),
           M."BaseObj", M."BaseEntry", M."BaseLine", B."BaseDate", B."BaseSign", B."BaseQty", B."UP", B."FullAmt", B."CardCode", B."ItemCode",
           B."AccrType", M."MoveType", M."IsCancel", M."ObjType", M."DocEntry", M."LineNum", M."DocDate",
           M."Qty", M."AccrAmt", M."DocAmt", M."ProdItem", M."AmtRule"
      FROM :mv M
      JOIN :keep K ON K."BaseObj" = M."BaseObj" AND K."BaseEntry" = M."BaseEntry" AND K."BaseLine" = M."BaseLine"
      JOIN :bp B ON B."BaseObj" = M."BaseObj" AND B."BaseEntry" = M."BaseEntry" AND B."BaseLine" = M."BaseLine";
    RowCnt := ::ROWCOUNT;

    -- 材料的收货 / 退货 / 发票差额改取暂估口径（Q29）：存货影响 = 暂估、退货的 AccrAmt；发票为 发票 − 暂估
    amv = SELECT "ObjType", "DocEntry", "LineNum",
                 SUM(CASE WHEN "MoveType" = 'INV' THEN IFNULL("DocAmt", 0) + "AccrAmt" ELSE "AccrAmt" END) AS "Amt"
            FROM "MTC_CA_S_AP_MOVE"
           WHERE "RunId" = :RunId AND "AccrType" = 'MAT' AND "DocDate" BETWEEN :d0 AND :d1
           GROUP BY "ObjType", "DocEntry", "LineNum";
    tgt = SELECT L."LineId", A."Amt",
                 ROW_NUMBER() OVER (PARTITION BY L."ObjType", L."DocEntry", L."LineNum" ORDER BY L."LineId") AS "Rn"
            FROM "MTC_CA_S_LINE" L
            JOIN :amv A ON A."ObjType" = L."ObjType" AND A."DocEntry" = L."DocEntry" AND A."LineNum" = L."LineNum"
           WHERE L."RunId" = :RunId AND L."Src" = 'OIVL';
    UPDATE T0 SET T0."SrcAmt" = CASE WHEN X."Rn" = 1 THEN X."Amt" ELSE 0 END
      FROM "MTC_CA_S_LINE" T0
      JOIN :tgt X ON X."LineId" = T0."LineId"
     WHERE T0."RunId" = :RunId;

    -- 委外加工费发票差异 → 产品的 I11（替代 @MTC_OMRV WW 单）；没有产品物料的由 PRE-21 报出
    SELECT IFNULL(MAX("LineId"), 0) INTO maxLine FROM "MTC_CA_S_LINE" WHERE "RunId" = :RunId;
    INSERT INTO "MTC_CA_S_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "Src", "SrcKey", "ObjType", "DocEntry",
        "LineNum", "Canceled", "DocDate", "ItemCode", "Qty", "SrcAmt", "TransCode", "Dir", "CardCode",
        "BaseType", "BaseEntry", "BaseLine", "AcctCode")
    SELECT :fc, :rt, :scen, :RunId, :maxLine + ROW_NUMBER() OVER (ORDER BY A."MoveId"),
           'APDIF', A."ObjType" || '-' || A."DocEntry" || '-' || A."LineNum", A."ObjType", A."DocEntry",
           A."LineNum", CASE WHEN A."IsCancel" = 'Y' THEN 'C' ELSE 'N' END, A."DocDate", A."ProdItem", 0,
           A."DocAmt" + A."AccrAmt", 'I11', IO."U_IOType", A."CardCode",
           A."BaseObj", TO_NVARCHAR(A."BaseEntry"), TO_NVARCHAR(A."BaseLine"), :difAcct
      FROM "MTC_CA_S_AP_MOVE" A
      JOIN "MTC_CA_S_ITEM" I ON I."RunId" = A."RunId" AND I."ItemCode" = A."ProdItem"
      LEFT JOIN "@MTC_COST_IOTYPE" IO ON IO."Code" = 'I11'
     WHERE A."RunId" = :RunId AND A."AccrType" = 'SUBFEE' AND A."MoveType" = 'INV'
       AND A."DocDate" BETWEEN :d0 AND :d1 AND A."DocAmt" + A."AccrAmt" <> 0;
    n := ::ROWCOUNT;
    RowCnt := :RowCnt + :n;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #13
-- B1 @MTC_CA_PARAM 原样快照 → MTC_CA_C_PARAM_B1（用户 2026-10-29：参数可在 B1 用 UDF U_Locked = Y 锁定，保存时用快照判断有没有被改）
--   KeyVal 为空 = 整表刷新（P05 每次同步时）；否则只刷新这一条 Code（B1 保存时 MTC_CA_P_B1CFG_TN 调用，删除的行同时从快照删掉）。
--   B1 表不存在时什么都不做；没有 U_Locked 字段时都记 N。B1 表在部署时可能还不存在，所以用动态 SQL。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_PARAM_B1_SNAP" (IN KeyVal NVARCHAR(255), IN Src NVARCHAR(10))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE nTab INT; DECLARE nCol INT;
    DECLARE lk NVARCHAR(200); DECLARE w NVARCHAR(600) := '';
    DECLARE k NVARCHAR(255) := TRIM(:KeyVal);
    SELECT COUNT(*) INTO nTab FROM SYS."TABLES" WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = '@MTC_CA_PARAM';
    IF :nTab = 0 THEN
        RETURN;
    END IF;
    SELECT COUNT(*) INTO nCol FROM SYS."TABLE_COLUMNS"
     WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = '@MTC_CA_PARAM' AND "COLUMN_NAME" = 'U_Locked';
    lk := CASE WHEN :nCol > 0 THEN 'CASE WHEN UPPER(TRIM("U_Locked")) = ''Y'' THEN ''Y'' ELSE ''N'' END' ELSE '''N''' END;
    IF :k IS NULL THEN
        DELETE FROM "MTC_CA_C_PARAM_B1";
    ELSE
        DELETE FROM "MTC_CA_C_PARAM_B1" WHERE "Code" = :k;
        w := ' WHERE TRIM("Code") = ''' || REPLACE(:k, '''', '''''') || '''';
    END IF;
    EXEC 'INSERT INTO "MTC_CA_C_PARAM_B1" ("Code", "FromFc", "ToFc", "Value", "Locked", "SnapSrc", "SnapTime")
          SELECT TRIM("Code"), TRIM("U_FromFc"), TRIM("U_ToFc"), TRIM("U_Value"), ' || :lk || ', ''' || IFNULL(:Src, '') || ''', CURRENT_TIMESTAMP
            FROM "@MTC_CA_PARAM"' || :w;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #14
-- 锁定检查（B1 保存 @MTC_CA_PARAM 时由 MTC_CA_P_B1CFG_TN 调用，用户 2026-10-29）：快照里这条是锁定的（上一次保存 / 同步时 U_Locked = Y），
-- 这次保存后仍是 Y 而起始账期、截止账期或取值变了 → 拒绝；整条被删掉 → 拒绝。这次把锁定改成 N 的放行（谁能改由 SAP 权限控制）。
-- errMsg 为空 = 通过。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_PARAM_LOCK_CHECK" (IN KeyVal NVARCHAR(255), OUT errMsg NVARCHAR(200))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE k NVARCHAR(255) := TRIM(:KeyVal);
    DECLARE kq NVARCHAR(600);
    DECLARE nPrev INT; DECLARE nCur INT; DECLARE nCol INT;
    DECLARE prevS NVARCHAR(1000); DECLARE curS NVARCHAR(1000);
    DECLARE lk NVARCHAR(200);
    errMsg := '';
    SELECT COUNT(*) INTO nPrev FROM "MTC_CA_C_PARAM_B1" WHERE "Code" = :k AND "Locked" = 'Y';
    IF :nPrev = 0 THEN
        RETURN;
    END IF;
    SELECT MAX(IFNULL("FromFc", '') || '|' || IFNULL("ToFc", '') || '|' || IFNULL("Value", '')) INTO prevS
      FROM "MTC_CA_C_PARAM_B1" WHERE "Code" = :k;
    kq := '''' || REPLACE(:k, '''', '''''') || '''';
    EXEC 'SELECT COUNT(*) FROM "@MTC_CA_PARAM" WHERE TRIM("Code") = ' || :kq INTO nCur;
    IF :nCur = 0 THEN
        errMsg := LEFT('[成本配置] ' || :k || '：已锁定（U_Locked = Y），不能删除；确需删除，先把锁定改成 N 保存后再删', 200);
        RETURN;
    END IF;
    SELECT COUNT(*) INTO nCol FROM SYS."TABLE_COLUMNS"
     WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = '@MTC_CA_PARAM' AND "COLUMN_NAME" = 'U_Locked';
    lk := CASE WHEN :nCol > 0 THEN 'CASE WHEN UPPER(TRIM("U_Locked")) = ''Y'' THEN ''Y'' ELSE ''N'' END' ELSE '''N''' END;
    EXEC 'SELECT MAX(' || :lk || ' || ''|'' || IFNULL(TRIM("U_FromFc"), '''') || ''|'' || IFNULL(TRIM("U_ToFc"), '''') || ''|'' || IFNULL(TRIM("U_Value"), ''''))
            FROM "@MTC_CA_PARAM" WHERE TRIM("Code") = ' || :kq INTO curS;
    IF LEFT(:curS, 1) = 'Y' AND SUBSTRING(:curS, 3) <> :prevS THEN
        errMsg := LEFT('[成本配置] ' || :k || '：已锁定（U_Locked = Y），取值和起止账期不能改；确需修改，先把锁定改成 N', 200);
    END IF;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #15
-- P05：费用归集 / 分摊配置从 B1 自定义表同步（用户 2026-10-14：配置在 SAP 里维护，执行台不做编辑页；表结构见 新框架/B1自定义表_费用配置.md）
--   @MTC_CA_POOL    主数据 UDO 表头：Code 池代码、Name 池名称、U_IsDefault 默认池、U_IsCloseDif 关单差异池、U_Descr
--   @MTC_CA_POOL1   成本中心 → 池：U_OcrCode、U_FromFc、U_ToFc、U_Descr
--   @MTC_CA_POOL2   池 → 分摊范围：U_MatchBy（GRPTYPE / GRP）、U_MatchVal、U_WorTypes、U_FromFc、U_ToFc、U_Descr
--   @MTC_CA_PARAM   计算参数（用户 2026-10-28，平铺表格）：一行 = 一个参数的一段账期；Code = 参数代码，第二段起 代码@起始账期；
--                   U_FromFc、U_ToFc、U_Value（Name / U_Category / U_DataType / U_Hint 只是提示）。参数目录见 MTC_CA_C_PARAM_DEF
--   @MTC_CA_EXPSET / @MTC_CA_EXPSET1  旧的参数表（表头 Code + 子表 U_FromFc、U_ToFc、U_Value）：没建 @MTC_CA_PARAM 或它没有数据时才读
-- 表不存在或没有数据时沿用 MTC_CA_C_*（种子值）。B1 有数据时整组覆盖 MTC_CA_C_POOL / _SRC / _TGT 和 C_PARAM.CLOSE_DIF_POOL，
-- 参数只覆盖 B1 里出现的参数代码。结构错误（重复键、默认池 / 关单差异池不是正好 1 个、未知参数代码、账期格式等）时该组不覆盖，
-- 步骤记 FAIL，由 PRE-18 阻断。账期空 = 不限；订单类型空 = 10,20,30,40；凭证代码里的“空”= 没有凭证代码的手工凭证。
-- 2026-10-28：装了 20_b1cfg_check.sql（视图 MTC_CA_V_B1CFG_ISSUES，B1 保存校验同一口径）时，校验以视图为准；
--   费用池没装视图时用下面的内联检查（含账期格式、起止顺序）；@MTC_CA_PARAM 必须装视图。
-- B1 表在部署时可能还不存在，所以全部用动态 SQL。
-- 2026-10-29：主体改名 _X，多返回 oErr（1 = 有配置错误、该组没覆盖）/ oMsg（同步说明），给执行台“从 B1 拉取”用；
--   MTC_CA_P05_CFG_SYNC(RunId) 签名不变，是外壳（在本过程后面）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P05_CFG_SYNC_X" (IN RunId BIGINT, OUT oErr INT, OUT oMsg NVARCHAR(2000))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE nTab INT; DECLARE nRow INT; DECLARE nBad INT; DECLARE nDef INT; DECLARE nCls INT; DECLARE nView INT;
    DECLARE n1 INT; DECLARE n2 INT; DECLARE n3 INT;
    DECLARE s NVARCHAR(1000);
    DECLARE err NVARCHAR(1000) := '';
    DECLARE msg NVARCHAR(2000) := '';

    SELECT COUNT(*) INTO nView FROM SYS."VIEWS" WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "VIEW_NAME" = 'MTC_CA_V_B1CFG_ISSUES';
    -- B1 参数原样快照（锁定判断用，2026-10-29）
    CALL "MTC_CA_P_PARAM_B1_SNAP"(NULL, 'SYNC');

    -- 费用池
    SELECT COUNT(*) INTO nTab FROM "TABLES"
     WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" IN ('@MTC_CA_POOL', '@MTC_CA_POOL1', '@MTC_CA_POOL2');
    IF :nTab < 3 THEN
        msg := '费用池：B1 未建 @MTC_CA_POOL / 1 / 2，沿用 MTC_CA_C_POOL*';
    ELSE
        EXEC 'SELECT COUNT(*) FROM "@MTC_CA_POOL"' INTO nRow;
        IF :nRow = 0 THEN
            msg := '费用池：@MTC_CA_POOL 没有数据，沿用 MTC_CA_C_POOL*';
        ELSE
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_POOL" WHERE "U_IsDefault" = ''Y''' INTO nDef;
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_POOL" WHERE "U_IsCloseDif" = ''Y''' INTO nCls;
            IF :nDef <> 1 THEN err := :err || '默认池（U_IsDefault=Y）应正好 1 个，实际 ' || :nDef || ' 个；'; END IF;
            IF :nCls <> 1 THEN err := :err || '关单差异池（U_IsCloseDif=Y）应正好 1 个，实际 ' || :nCls || ' 个；'; END IF;
            IF :nView > 0 THEN
                -- 2026-10-28：与 B1 保存校验同一口径（重复、账期格式、起止顺序、账期段重叠、成本中心 / 匹配值存在等）
                EXEC 'SELECT COUNT(*) FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = ''MTC_CA_POOL''' INTO nBad;
                IF :nBad > 0 THEN
                    EXEC 'SELECT LEFT(STRING_AGG("KeyCode" || '' '' || "Msg", ''；'' ORDER BY "KeyCode"), 600) FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = ''MTC_CA_POOL''' INTO s;
                    err := :err || :nBad || ' 个问题：' || :s || '；';
                END IF;
            ELSE
                EXEC 'SELECT COUNT(*) FROM (SELECT 1 FROM "@MTC_CA_POOL1" WHERE IFNULL(TRIM("U_OcrCode"), '''') <> ''''
                       GROUP BY TRIM("U_OcrCode"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00'') HAVING COUNT(*) > 1)' INTO nBad;
                IF :nBad > 0 THEN err := :err || '成本中心 + 起始账期重复 ' || :nBad || ' 组；'; END IF;
                EXEC 'SELECT COUNT(*) FROM (SELECT 1 FROM "@MTC_CA_POOL2" WHERE IFNULL(TRIM("U_MatchVal"), '''') <> ''''
                       GROUP BY "Code", TRIM("U_MatchVal"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00'') HAVING COUNT(*) > 1)' INTO nBad;
                IF :nBad > 0 THEN err := :err || '分摊范围（池 + 匹配值 + 起始账期）重复 ' || :nBad || ' 组；'; END IF;
                -- 2026-10-28：账期格式和起止顺序（格式不对时按字符串比较会悄悄匹配不上）
                EXEC 'SELECT COUNT(*) FROM (SELECT "U_FromFc" AS F, "U_ToFc" AS T FROM "@MTC_CA_POOL1" UNION ALL SELECT "U_FromFc", "U_ToFc" FROM "@MTC_CA_POOL2")
                       WHERE (IFNULL(TRIM(F), '''') <> '''' AND NOT TRIM(F) LIKE_REGEXPR ''^[0-9]{4}-(0[1-9]|1[0-2])$'')
                          OR (IFNULL(TRIM(T), '''') <> '''' AND NOT TRIM(T) LIKE_REGEXPR ''^[0-9]{4}-(0[1-9]|1[0-2])$'')
                          OR IFNULL(NULLIF(TRIM(F), ''''), ''0000-00'') > IFNULL(NULLIF(TRIM(T), ''''), ''9999-99'')' INTO nBad;
                IF :nBad > 0 THEN err := :err || '成本中心 / 分摊范围的起止账期不是 YYYY-MM 或起始晚于截止 ' || :nBad || ' 行；'; END IF;
            END IF;

            IF :err <> '' THEN
                msg := '费用池：B1 配置有误，未同步，沿用上次的 MTC_CA_C_POOL*：' || RTRIM(:err, '；');
            ELSE
                DELETE FROM "MTC_CA_C_POOL_TGT";
                DELETE FROM "MTC_CA_C_POOL_SRC";
                DELETE FROM "MTC_CA_C_POOL";
                EXEC 'INSERT INTO "MTC_CA_C_POOL" ("PoolCode", "PoolName", "IsDefault", "Descr")
                      SELECT TRIM("Code"), IFNULL(NULLIF(TRIM("Name"), ''''), TRIM("Code")),
                             CASE WHEN "U_IsDefault" = ''Y'' THEN ''Y'' ELSE ''N'' END,
                             LEFT(''B1 @MTC_CA_POOL'' || IFNULL(''：'' || "U_Descr", ''''), 500)
                        FROM "@MTC_CA_POOL"';
                EXEC 'INSERT INTO "MTC_CA_C_POOL_SRC" ("OcrCode", "FromFc", "ToFc", "PoolCode", "Descr")
                      SELECT TRIM("U_OcrCode"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00''),
                             IFNULL(NULLIF(TRIM("U_ToFc"), ''''), ''9999-99''), TRIM("Code"),
                             LEFT(''B1 @MTC_CA_POOL1'' || IFNULL(''：'' || "U_Descr", ''''), 500)
                        FROM "@MTC_CA_POOL1" WHERE IFNULL(TRIM("U_OcrCode"), '''') <> ''''';
                EXEC 'INSERT INTO "MTC_CA_C_POOL_TGT" ("PoolCode", "ItmsGrpCod", "FromFc", "ToFc", "WorTypes", "Descr", "MatchBy")
                      SELECT TRIM("Code"), TRIM("U_MatchVal"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00''),
                             IFNULL(NULLIF(TRIM("U_ToFc"), ''''), ''9999-99''),
                             CASE WHEN IFNULL(TRIM("U_WorTypes"), '''') = '''' THEN '',10,20,30,40,''
                                  ELSE '','' || REPLACE(REPLACE(TRIM("U_WorTypes"), '' '', ''''), ''，'', '','') || '','' END,
                             LEFT(''B1 @MTC_CA_POOL2'' || IFNULL(''：'' || "U_Descr", ''''), 500),
                             UPPER(IFNULL(NULLIF(TRIM("U_MatchBy"), ''''), ''GRPTYPE''))
                        FROM "@MTC_CA_POOL2" WHERE IFNULL(TRIM("U_MatchVal"), '''') <> ''''';
                DELETE FROM "MTC_CA_C_PARAM" WHERE "ParamCode" = 'CLOSE_DIF_POOL';
                EXEC 'INSERT INTO "MTC_CA_C_PARAM" ("ParamCode", "FromFc", "ToFc", "Value", "DataType", "Descr")
                      SELECT ''CLOSE_DIF_POOL'', ''0000-00'', ''9999-99'', TRIM("Code"), ''STR'', ''关单差异进的费用池（B1 @MTC_CA_POOL.U_IsCloseDif）''
                        FROM "@MTC_CA_POOL" WHERE "U_IsCloseDif" = ''Y''';
                SELECT COUNT(*) INTO n1 FROM "MTC_CA_C_POOL";
                SELECT COUNT(*) INTO n2 FROM "MTC_CA_C_POOL_SRC";
                SELECT COUNT(*) INTO n3 FROM "MTC_CA_C_POOL_TGT";
                msg := '费用池：已从 B1 同步 ' || :n1 || ' 个池、' || :n2 || ' 条成本中心、' || :n3 || ' 条分摊范围';
            END IF;
        END IF;
    END IF;

    -- 计算参数：科目用途 MFG_EXP_PREFIX / LAB_EXP（→ C_ACCT）和 MTC_CA_C_PARAM 中除 CLOSE_DIF_POOL 外的全部参数（→ C_PARAM）
    -- 都可以在 B1 维护（用户 2026-10-14）。B1 中出现的代码整组以 B1 为准（各起止账期行全部替换），没出现的沿用 MTC_CA_C_* 现有值。
    -- 列表型参数在 B1 里直接填 A,B,C，同步时转成 ,A,B,C,；单独一项“空”表示空代码（EXP_JDT_TRANSCODES）。
    -- CLOSE_DIF_POOL 在费用池 @MTC_CA_POOL.U_IsCloseDif 维护，这里不接受。
    -- 2026-10-28 起优先读平铺表 @MTC_CA_PARAM（参数目录 MTC_CA_C_PARAM_DEF，校验 MTC_CA_V_B1CFG_ISSUES）；没有时读旧 @MTC_CA_EXPSET / 1。
    n1 := LENGTH(:err);
    SELECT COUNT(*) INTO nTab FROM "TABLES" WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = '@MTC_CA_PARAM';
    nRow := 0;
    IF :nTab = 1 THEN
        EXEC 'SELECT COUNT(*) FROM "@MTC_CA_PARAM"' INTO nRow;
    END IF;
    IF :nRow > 0 THEN
        IF :nView = 0 THEN
            err := :err || '已建 @MTC_CA_PARAM，但没有安装校验视图 MTC_CA_V_B1CFG_ISSUES（B1 建全 @MTC_CA_POOL / 1 / 2、OPRC.U_CalType 后重新部署，或执行 新框架/sql/20_b1cfg_check.sql）；';
        ELSE
            EXEC 'SELECT COUNT(*) FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = ''MTC_CA_PARAM''' INTO nBad;
            IF :nBad > 0 THEN
                EXEC 'SELECT LEFT(STRING_AGG("KeyCode" || '' '' || "Msg", ''；'' ORDER BY "KeyCode"), 600) FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = ''MTC_CA_PARAM''' INTO s;
                err := :err || :nBad || ' 个问题：' || :s || '；';
            END IF;
        END IF;
        IF LENGTH(:err) > :n1 THEN
            msg := :msg || '；计算参数：B1 @MTC_CA_PARAM 配置有误，未同步：' || RTRIM(SUBSTRING(:err, :n1 + 1), '；');
        ELSE
            -- B 子查询：参数代码 = Code 中 @ 之前的部分
            EXEC 'DELETE FROM "MTC_CA_C_ACCT" WHERE "Usage" IN (
                    SELECT D."ParamCode" FROM "@MTC_CA_PARAM" B JOIN "MTC_CA_C_PARAM_DEF" D ON D."ParamCode" = SUBSTR_BEFORE(TRIM(B."Code") || ''@'', ''@'')
                     WHERE D."Target" = ''ACCT'')';
            EXEC 'INSERT INTO "MTC_CA_C_ACCT" ("Usage", "FromFc", "ToFc", "AcctCode", "Descr")
                  SELECT D."ParamCode", IFNULL(NULLIF(TRIM(B."U_FromFc"), ''''), ''0000-00''), IFNULL(NULLIF(TRIM(B."U_ToFc"), ''''), ''9999-99''),
                         TRIM(B."U_Value"), ''B1 @MTC_CA_PARAM：'' || D."CnName"
                    FROM "@MTC_CA_PARAM" B JOIN "MTC_CA_C_PARAM_DEF" D ON D."ParamCode" = SUBSTR_BEFORE(TRIM(B."Code") || ''@'', ''@'')
                   WHERE D."Target" = ''ACCT''';
            -- C_PARAM：B1 中出现的参数，旧行先改名（FromFc 前加 #）保留类型和说明，插入 B1 的行后再删掉旧行
            EXEC 'UPDATE "MTC_CA_C_PARAM" SET "FromFc" = ''#'' || "FromFc"
                   WHERE LEFT("FromFc", 1) <> ''#'' AND "ParamCode" IN (
                         SELECT D."ParamCode" FROM "@MTC_CA_PARAM" B JOIN "MTC_CA_C_PARAM_DEF" D ON D."ParamCode" = SUBSTR_BEFORE(TRIM(B."Code") || ''@'', ''@'')
                          WHERE D."Target" = ''PARAM'')';
            EXEC 'INSERT INTO "MTC_CA_C_PARAM" ("ParamCode", "FromFc", "ToFc", "Value", "DataType", "Descr")
                  SELECT D."ParamCode", IFNULL(NULLIF(TRIM(B."U_FromFc"), ''''), ''0000-00''), IFNULL(NULLIF(TRIM(B."U_ToFc"), ''''), ''9999-99''),
                         CASE WHEN D."DataType" <> ''LIST'' THEN TRIM(B."U_Value")
                              WHEN TRIM(BOTH '','' FROM REPLACE(REPLACE(IFNULL(TRIM(B."U_Value"), ''''), '' '', ''''), ''，'', '','')) = '''' THEN '',''
                              ELSE REPLACE(REPLACE('','' || TRIM(BOTH '','' FROM REPLACE(REPLACE(UPPER(IFNULL(TRIM(B."U_Value"), '''')), '' '', ''''), ''，'', '','')) || '','',
                                                   '',空,'', '',,''), '',空,'', '',,'') END,
                         CASE WHEN D."DataType" = ''LIST'' THEN ''LIST'' WHEN D."DataType" IN (''DEC'', ''INT'') THEN D."DataType" ELSE ''STR'' END,
                         LEFT(''B1 @MTC_CA_PARAM：'' || IFNULL(O."Descr", D."CnName"), 500)
                    FROM "@MTC_CA_PARAM" B
                    JOIN "MTC_CA_C_PARAM_DEF" D ON D."ParamCode" = SUBSTR_BEFORE(TRIM(B."Code") || ''@'', ''@'') AND D."Target" = ''PARAM''
                    LEFT JOIN (SELECT "ParamCode", MAX(REPLACE(REPLACE("Descr", ''B1 @MTC_CA_EXPSET：'', ''''), ''B1 @MTC_CA_PARAM：'', '''')) AS "Descr"
                                 FROM "MTC_CA_C_PARAM" WHERE LEFT("FromFc", 1) = ''#'' GROUP BY "ParamCode") O
                      ON O."ParamCode" = D."ParamCode"';
            DELETE FROM "MTC_CA_C_PARAM" WHERE LEFT("FromFc", 1) = '#';
            msg := :msg || '；计算参数：已从 B1 @MTC_CA_PARAM 同步 ' || :nRow || ' 行';
        END IF;
    ELSE
    -- 旧表 @MTC_CA_EXPSET / 1（2026-10-14 的逻辑；2026-10-28 只改了“空”的替换）
    SELECT COUNT(*) INTO nTab FROM "TABLES"
     WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" IN ('@MTC_CA_EXPSET', '@MTC_CA_EXPSET1');
    IF :nTab < 2 THEN
        msg := :msg || '；计算参数：B1 未建 @MTC_CA_PARAM（或旧 @MTC_CA_EXPSET / 1），沿用 MTC_CA_C_ACCT / C_PARAM';
    ELSE
        EXEC 'SELECT COUNT(*) FROM "@MTC_CA_EXPSET1"' INTO nRow;
        IF :nRow = 0 THEN
            msg := :msg || '；计算参数：@MTC_CA_PARAM 和旧 @MTC_CA_EXPSET1 都没有数据，沿用 MTC_CA_C_ACCT / C_PARAM';
        ELSE
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_EXPSET" E
                   WHERE TRIM(E."Code") NOT IN (''MFG_EXP_PREFIX'', ''LAB_EXP'')
                     AND NOT EXISTS (SELECT 1 FROM "MTC_CA_C_PARAM" P WHERE P."ParamCode" = TRIM(E."Code") AND P."ParamCode" <> ''CLOSE_DIF_POOL'')' INTO nBad;
            IF :nBad > 0 THEN err := :err || '有 ' || :nBad || ' 个参数代码不认识（CLOSE_DIF_POOL 请在费用池的“关单差异池”维护）；'; END IF;
            EXEC 'SELECT COUNT(*) FROM (SELECT 1 FROM "@MTC_CA_EXPSET1"
                   GROUP BY TRIM("Code"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00'') HAVING COUNT(*) > 1)' INTO nBad;
            IF :nBad > 0 THEN err := :err || '参数 + 起始账期重复 ' || :nBad || ' 组；'; END IF;
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_EXPSET1"
                   WHERE (IFNULL(TRIM("U_FromFc"), '''') <> '''' AND NOT TRIM("U_FromFc") LIKE_REGEXPR ''^[0-9]{4}-[0-9]{2}$'')
                      OR (IFNULL(TRIM("U_ToFc"), '''') <> '''' AND NOT TRIM("U_ToFc") LIKE_REGEXPR ''^[0-9]{4}-[0-9]{2}$'')' INTO nBad;
            IF :nBad > 0 THEN err := :err || '起止账期不是 YYYY-MM 格式 ' || :nBad || ' 行；'; END IF;
            -- 取值：科目和非列表参数不能为空；DEC 必须是数字、INT 必须是整数
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_EXPSET1" E
                   WHERE IFNULL(TRIM(E."U_Value"), '''') = ''''
                     AND (TRIM(E."Code") IN (''MFG_EXP_PREFIX'', ''LAB_EXP'')
                          OR EXISTS (SELECT 1 FROM "MTC_CA_C_PARAM" P WHERE P."ParamCode" = TRIM(E."Code")
                                      AND P."DataType" <> ''LIST'' AND LEFT(IFNULL(P."Value", ''''), 1) <> '',''))' INTO nBad;
            IF :nBad > 0 THEN err := :err || '取值为空 ' || :nBad || ' 行；'; END IF;
            EXEC 'SELECT COUNT(*) FROM "@MTC_CA_EXPSET1" E
                   WHERE EXISTS (SELECT 1 FROM "MTC_CA_C_PARAM" P WHERE P."ParamCode" = TRIM(E."Code")
                                  AND ((P."DataType" = ''DEC'' AND NOT IFNULL(TRIM(E."U_Value"), '''') LIKE_REGEXPR ''^-?[0-9]+(\.[0-9]+)?$'')
                                    OR (P."DataType" = ''INT'' AND NOT IFNULL(TRIM(E."U_Value"), '''') LIKE_REGEXPR ''^-?[0-9]+$'')))' INTO nBad;
            IF :nBad > 0 THEN err := :err || '数值参数的取值不是数字 ' || :nBad || ' 行；'; END IF;

            IF LENGTH(:err) > :n1 THEN
                msg := :msg || '；计算参数：B1 配置有误，未同步：' || RTRIM(SUBSTRING(:err, :n1 + 1), '；');
            ELSE
                EXEC 'DELETE FROM "MTC_CA_C_ACCT" WHERE "Usage" IN (SELECT TRIM("Code") FROM "@MTC_CA_EXPSET1" WHERE TRIM("Code") IN (''MFG_EXP_PREFIX'', ''LAB_EXP''))';
                EXEC 'INSERT INTO "MTC_CA_C_ACCT" ("Usage", "FromFc", "ToFc", "AcctCode", "Descr")
                      SELECT TRIM("Code"), IFNULL(NULLIF(TRIM("U_FromFc"), ''''), ''0000-00''), IFNULL(NULLIF(TRIM("U_ToFc"), ''''), ''9999-99''),
                             TRIM("U_Value"), ''B1 @MTC_CA_EXPSET''
                        FROM "@MTC_CA_EXPSET1" WHERE TRIM("Code") IN (''MFG_EXP_PREFIX'', ''LAB_EXP'')';
                -- C_PARAM：B1 中出现的参数，旧行先改名（FromFc 前加 #）保留类型和说明，插入 B1 的行后再删掉旧行
                EXEC 'UPDATE "MTC_CA_C_PARAM" SET "FromFc" = ''#'' || "FromFc"
                       WHERE LEFT("FromFc", 1) <> ''#'' AND "ParamCode" IN (SELECT TRIM("Code") FROM "@MTC_CA_EXPSET1")';
                -- 2026-10-28：“空”只替换单独的一项（原来整串替换，会把带“空”字的值改掉）
                EXEC 'INSERT INTO "MTC_CA_C_PARAM" ("ParamCode", "FromFc", "ToFc", "Value", "DataType", "Descr")
                      SELECT TRIM(E."Code"), IFNULL(NULLIF(TRIM(E."U_FromFc"), ''''), ''0000-00''), IFNULL(NULLIF(TRIM(E."U_ToFc"), ''''), ''9999-99''),
                             CASE WHEN O."IsList" = 1
                                  THEN REPLACE(REPLACE('','' || TRIM(BOTH '','' FROM REPLACE(REPLACE(UPPER(IFNULL(TRIM(E."U_Value"), '''')), '' '', ''''), ''，'', '','')) || '','',
                                                       '',空,'', '',,''), '',空,'', '',,'')
                                  ELSE TRIM(E."U_Value") END,
                             CASE WHEN O."IsList" = 1 THEN ''LIST'' ELSE O."DataType" END,
                             LEFT(''B1 @MTC_CA_EXPSET：'' || O."Descr", 500)
                        FROM "@MTC_CA_EXPSET1" E
                        JOIN (SELECT "ParamCode", MAX("DataType") AS "DataType",
                                     MAX(CASE WHEN "DataType" = ''LIST'' OR LEFT(IFNULL("Value", ''''), 1) = '','' THEN 1 ELSE 0 END) AS "IsList",
                                     MAX(REPLACE(REPLACE("Descr", ''B1 @MTC_CA_EXPSET：'', ''''), ''B1 @MTC_CA_PARAM：'', '''')) AS "Descr"
                                FROM "MTC_CA_C_PARAM" WHERE LEFT("FromFc", 1) = ''#'' GROUP BY "ParamCode") O
                          ON O."ParamCode" = TRIM(E."Code")';
                DELETE FROM "MTC_CA_C_PARAM" WHERE LEFT("FromFc", 1) = '#';
                msg := :msg || '；计算参数：已从 B1 旧 @MTC_CA_EXPSET 同步 ' || :nRow || ' 行';
            END IF;
        END IF;
    END IF;
    END IF;

    -- 成本中心按 OPRC.U_CalType（成本计入类型）归池（用户 2026-10-14）：C_POOL_SRC 的 OcrCode 既可以是成本中心代码，
    -- 也可以是 U_CalType 的取值（如 P017 = 包装车间）。U_CalType 等于某条配置的成本中心，展开成一条同池、同账期的配置
    -- （Descr 标记 'OPRC.U_CalType=<值>'，每次运行先删后建）；本身已单独配置的成本中心不展开；U_CalType 为空的进默认池。
    DELETE FROM "MTC_CA_C_POOL_SRC" WHERE "Descr" LIKE 'OPRC.U\_CalType=%' ESCAPE '\';
    SELECT COUNT(*) INTO nTab FROM "TABLE_COLUMNS"
     WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = 'OPRC' AND "COLUMN_NAME" = 'U_CalType';
    IF :nTab > 0 THEN
        EXEC 'INSERT INTO "MTC_CA_C_POOL_SRC" ("OcrCode", "FromFc", "ToFc", "PoolCode", "Descr")
              SELECT P."PrcCode", S."FromFc", S."ToFc", S."PoolCode", ''OPRC.U_CalType='' || S."OcrCode"
                FROM "OPRC" P
                JOIN "MTC_CA_C_POOL_SRC" S ON S."OcrCode" = TRIM(P."U_CalType")
               WHERE IFNULL(TRIM(P."U_CalType"), '''') <> '''' AND S."OcrCode" <> P."PrcCode"
                 AND NOT EXISTS (SELECT 1 FROM "MTC_CA_C_POOL_SRC" X WHERE X."OcrCode" = P."PrcCode")';
        SELECT COUNT(*) INTO n1 FROM "MTC_CA_C_POOL_SRC" WHERE "Descr" LIKE 'OPRC.U\_CalType=%' ESCAPE '\';
        msg := :msg || '；按 OPRC.U_CalType 归池的成本中心 ' || :n1 || ' 个';
    END IF;

    -- 运行记录里的参数快照在 P00 记下，同步后按本期生效值刷新（B1 改的参数要体现在本次运行记录里）
    UPDATE "MTC_CA_RUN" R
       SET "Params" = (SELECT '{' || IFNULL(STRING_AGG('"' || P."ParamCode" || '":"' || REPLACE(REPLACE(P."Value", '\', '\\'), '"', '\"') || '"', ',' ORDER BY P."ParamCode"), '') || '}'
                         FROM "MTC_CA_C_PARAM" P WHERE R."FcCode" BETWEEN P."FromFc" AND P."ToFc")
     WHERE R."RunId" = :RunId;

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P05', CASE WHEN :err <> '' THEN 'FAIL' ELSE 'OK' END, NULL, LEFT(:msg, 2000));
    oErr := CASE WHEN :err <> '' THEN 1 ELSE 0 END;
    oMsg := LEFT(:msg, 2000);
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #16
CREATE OR REPLACE PROCEDURE "MTC_CA_P05_CFG_SYNC" (IN RunId BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE e INT; DECLARE m NVARCHAR(2000);
    CALL "MTC_CA_P05_CFG_SYNC_X"(:RunId, e, m);
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #17
-- 执行台“从 B1 拉取”（用户 2026-10-29）：不算、不建运行记录，只把 B1 @MTC_CA_PARAM / 费用池抽取到 MTC_CA_C_*，返回 Code / Msg。
-- 有运行中的计算时拒绝（会改掉正在用的参数）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_CFG_PULL" ()
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE e INT; DECLARE m NVARCHAR(2000);
    SELECT COUNT(*) INTO n FROM "MTC_CA_RUN" WHERE "Status" = 'RUNNING';
    IF :n > 0 THEN
        SELECT -1 AS "Code", '有运行中的计算，等它结束再拉取（如确认已中断，先用 MTC_CA_P_RUN_END 把它标为 FAIL）' AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    CALL "MTC_CA_P05_CFG_SYNC_X"(NULL, e, m);
    SELECT CASE WHEN :e = 0 THEN 0 ELSE -1 END AS "Code",
           CASE WHEN :e = 0 THEN '已从 B1 拉取：' ELSE 'B1 配置有错，出错的那一组没有覆盖：' END || TRIM(LEADING '；' FROM :m) AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 07_snapshot_procs.sql #18
CREATE OR REPLACE PROCEDURE "MTC_CA_P20_SNAPSHOT" (IN RunId BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n BIGINT;
    DECLARE m NVARCHAR(500);
    -- 先把 B1 里维护的费用池 / 归集参数同步到 MTC_CA_C_*（用户 2026-10-14）
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P05', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P05_CFG_SYNC"(:RunId);

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_ITEM', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_ITEM"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_ITEM', 'OK', :n, '物料与层级');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_LINE', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_LINE"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_LINE', 'OK', :n, '库存变动');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_AP', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_AP"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_AP', 'OK', :n, '应付暂估变动、委外发票差异');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_SUBFEE', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_SUBFEE"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_SUBFEE', 'OK', :n, '委外加工费');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_ORDER', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_ORDER"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_ORDER', 'OK', :n, '订单与计划用料');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_EXP', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_EXP"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_EXP', 'OK', :n, '费用来源');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_MISC', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_MISC"(:RunId, n);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_MISC', 'OK', :n, '工时、期初维护价');

    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_OPEN', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P20_OPEN"(:RunId, n, m);
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P20_OPEN', CASE WHEN :n > 0 THEN 'OK' ELSE 'WARN' END, :n, :m);
END

@@
-- @stmt 新框架 08_precheck.sql #1
-- =====================================================================
-- 新成本框架 第 1 期：P10 计算前检查（设计稿第 6 节；替代 CAL_1001_CHECK，只读）
-- 在 P20 快照之后执行，检查快照和 B1 单据；不修改 B1、不重建旧表、不写期初维护价。
-- 结果写 MTC_CA_R_CHECK（每项一行）和 MTC_CA_R_CHECK_DTL（问题明细，每项最多 CHECK_DTL_MAX 行）。
-- 检查项的标题、是否阻断登记在 MTC_CA_C_CHECK；Active='N' 的记为 SKIP。
-- =====================================================================
-- 物料本期的单价来源（用户 2026-11-06，PRE-23 与 PRE-04 共用）：HasIn = 有计入加权单价的采购 / 完工等行；IsSrc = 这些行或期初能给出单价。
-- 能给出单价 = 有带金额的入库、QCP_PRICED_IN 中非采购类的入库（完工、形态转换等，金额要算了才知道）或期初有数量有金额，
-- 且 加权单价的分母 > 0（期初数量 + 计入加权单价的行，同 P30 InVal、P45）。0 金额的采购收货、收货后全退的物料给不出单价，盘盈等按加权价的行会是 0 成本。
CREATE OR REPLACE FUNCTION "MTC_CA_F_QCP_SRC" (IN RunId BIGINT, IN PricedIn NVARCHAR(200))
RETURNS TABLE ("ItemCode" NVARCHAR(50), "HasIn" NVARCHAR(1), "IsSrc" NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    RETURN
    SELECT X."ItemCode", MAX(X."HasIn") AS "HasIn",
           CASE WHEN MAX(X."CanPrice") = 'Y' AND SUM(X."ValQty") > 0 THEN 'Y' ELSE 'N' END AS "IsSrc"
      FROM (SELECT V."ItemCode",
                   CASE WHEN V."IsFix" = 'Y' OR V."IsPriced" = 'Y' THEN 'Y' ELSE 'N' END AS "HasIn",
                   -- 分母同 P30 的 InVal：固定价、完工、形态转换，加上生产退料、销售退货、销售取消单
                   CASE WHEN V."IsFix" = 'Y' OR V."IsPriced" = 'Y' OR V."TransCode" = 'O06'
                          OR (V."Canceled" = 'C' AND V."ObjType" IN ('15', '16'))
                          OR (V."BusiClass" = 'B03' AND V."OrderEntry" IS NOT NULL AND V."Qty" > 0) THEN V."Qty" ELSE 0 END AS "ValQty",
                   CASE WHEN V."Qty" > 0 AND V."SrcAmt" IS NOT NULL AND V."SrcAmt" <> 0 THEN 'Y'
                        WHEN V."Qty" > 0 AND V."IsFix" = 'N' AND V."IsPriced" = 'Y' THEN 'Y'
                        ELSE 'N' END AS "CanPrice"
              FROM (SELECT "ItemCode", "Qty", "SrcAmt", "TransCode", "Canceled", "ObjType", "BusiClass", "OrderEntry",
                           CASE WHEN "Src" IN ('OMRV', 'APDIF') OR "ObjType" IN ('20', '21', '18', '19') THEN 'Y' ELSE 'N' END AS "IsFix",
                           CASE WHEN LOCATE(:PricedIn, ',' || IFNULL("TransCode", '') || ',') > 0 THEN 'Y' ELSE 'N' END AS "IsPriced"
                      FROM "MTC_CA_S_LINE"
                     WHERE "RunId" = :RunId AND "Qty" <> 0 AND IFNULL("NoCost", 'N') = 'N') V
            UNION ALL
            SELECT "ItemCode", 'N', "Qty", CASE WHEN "Qty" > 0 AND "Amount" <> 0 THEN 'Y' ELSE 'N' END
              FROM "MTC_CA_S_OPEN" WHERE "RunId" = :RunId) X
     GROUP BY X."ItemCode";
END

@@
-- @stmt 新框架 08_precheck.sql #2
CREATE OR REPLACE PROCEDURE "MTC_CA_P_CHECK_PUT" (
    IN RunId   BIGINT,
    IN CheckId NVARCHAR(20),
    IN dtl     TABLE ("KeyCode" NVARCHAR(5000), "Info" NVARCHAR(5000)),
    IN Msg     NVARCHAR(1000)
)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE cnt BIGINT;
    DECLARE blk NVARCHAR(1);
    DECLARE act NVARCHAR(1);
    DECLARE stage NVARCHAR(4);
    DECLARE maxDtl INT;
    DECLARE title NVARCHAR(200);
    DECLARE nDone INT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    maxDtl := TO_INTEGER(IFNULL("MTC_CA_F_PARAM"('CHECK_DTL_MAX', :fc), '200'));
    SELECT IFNULL(MAX("IsBlock"), 'N'), IFNULL(MAX("Active"), 'Y'), IFNULL(MAX("Stage"), 'PRE'), IFNULL(MAX("Title"), '')
      INTO blk, act, stage, title FROM "MTC_CA_C_CHECK" WHERE "CheckId" = :CheckId;
    -- 计算后校验（POST）不通过一律阻断，没有警告（用户 2026-10-14）；
    -- 例外：参数 POST_WARN_IDS 中的检查按 C_CHECK.IsBlock（POST-15 PUR 逐单据勾稽先只警告，用户 2026-10-30）
    -- POST-16 费用波动、POST-17 加权价入库 0 成本固定只警告，不靠参数，B1 里的 POST_WARN_IDS 不用改（用户 2026-11-06）
    -- POST-18 领料完整性、POST-19 完工没有材料、POST-20 单耗偏离同样固定只警告（用户 2026-11-11）
    IF :stage = 'POST' AND LOCATE(IFNULL("MTC_CA_F_PARAM"('POST_WARN_IDS', :fc), ',POST-15,') || ',POST-16,,POST-17,,POST-18,,POST-19,,POST-20,', ',' || :CheckId || ',') = 0 THEN blk := 'Y'; END IF;
    SELECT COUNT(*) INTO cnt FROM :dtl;

    INSERT INTO "MTC_CA_R_CHECK" ("FcCode", "RunType", "Scenario", "RunId", "CheckId", "Stage", "Result", "IssueCnt", "IsBlock", "Msg", "CheckTime")
    VALUES (:fc, :rt, :scen, :RunId, :CheckId, :stage,
            CASE WHEN :act = 'N' THEN 'SKIP' WHEN :cnt = 0 THEN 'PASS' WHEN :blk = 'Y' THEN 'FAIL' ELSE 'WARN' END,
            :cnt, :blk, :Msg, CURRENT_TIMESTAMP);

    IF :act = 'Y' AND :cnt > 0 THEN
        INSERT INTO "MTC_CA_R_CHECK_DTL" ("FcCode", "RunType", "Scenario", "RunId", "CheckId", "SeqNo", "KeyCode", "Info")
        SELECT :fc, :rt, :scen, :RunId, :CheckId, "SeqNo", LEFT("KeyCode", 200), LEFT("Info", 1000)
          FROM (SELECT ROW_NUMBER() OVER (ORDER BY "KeyCode", "Info") AS "SeqNo", "KeyCode", "Info" FROM :dtl)
         WHERE "SeqNo" <= :maxDtl;
    END IF;

    -- 执行台进度：已完成几项、刚完成哪一项（不含明细）
    SELECT COUNT(*) INTO nDone FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "Stage" = :stage;
    CALL "MTC_CA_P_LOG_NOTE"(:RunId, '已完成 ' || :nDone || ' 项校验，刚完成 ' || :CheckId || ' ' || :title || '：'
         || CASE WHEN :act = 'N' THEN '跳过' WHEN :cnt = 0 THEN '通过' ELSE :cnt || ' 条问题' END);
END

@@
-- @stmt 新框架 08_precheck.sql #3
-- 校验明细的单号：单据类型 + DocEntry → “类型-DocNum 单号”（SAP 里按 DocNum 查，用户 2026-10-29）；查不到单号时仍写“类型-DocEntry n”
-- P10、P60、P75 共用，放在 08 是因为它最先部署
CREATE OR REPLACE FUNCTION "MTC_CA_F_DOCKEY" (IN ObjType NVARCHAR(20), IN DocEntry INTEGER)
RETURNS KeyText NVARCHAR(100)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE num INTEGER;
    SELECT MAX("DocNum") INTO num FROM (
        SELECT "DocNum" FROM "OINV" WHERE :ObjType = '13' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "ORIN" WHERE :ObjType = '14' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "ODLN" WHERE :ObjType = '15' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "ORDN" WHERE :ObjType = '16' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OPCH" WHERE :ObjType = '18' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "ORPC" WHERE :ObjType = '19' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OPDN" WHERE :ObjType = '20' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "ORPD" WHERE :ObjType = '21' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OIGN" WHERE :ObjType = '59' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OIGE" WHERE :ObjType = '60' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OWTR" WHERE :ObjType = '67' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "OWOR" WHERE :ObjType = '202' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "@MTC_OWOR" WHERE :ObjType = 'MTC_OWOR' AND "DocEntry" = :DocEntry UNION ALL
        SELECT "DocNum" FROM "@MTC_OMRV" WHERE :ObjType = 'MTC_OMRV' AND "DocEntry" = :DocEntry);
    KeyText := IFNULL(:ObjType, '') || CASE WHEN :num IS NULL THEN '-DocEntry ' || IFNULL(TO_NVARCHAR(:DocEntry), '')
                                            ELSE '-DocNum ' || TO_NVARCHAR(:num) END;
END

@@
-- @stmt 新框架 08_precheck.sql #4
-- 发出商品（P71 和 PRE-27 共用；放在这里是因为 08 比 16 先部署）
-- 截至某日（含）已交货未开票的交货 / 独立退货行（口径同 CO6103），P71 用它取期末和期初（上期末）两份（用户 2026-10-15 对账列示期初 / 本期 / 期末）
CREATE OR REPLACE FUNCTION "MTC_CA_F_GOODS_OPEN" (IN d DATE)
RETURNS TABLE ("ObjType" NVARCHAR(20), "DocEntry" INTEGER, "LineNum" INTEGER, "DocDate" DATE, "CardCode" NVARCHAR(50),
               "CustType" NVARCHAR(20), "IsSample" NVARCHAR(1), "ItemCode" NVARCHAR(50),
               "DocQty" DECIMAL(19,6), "InvQty" DECIMAL(19,6), "RetQty" DECIMAL(19,6), "OpenQty" DECIMAL(19,6))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE smpSt NVARCHAR(500);
    -- 样品销售的销售订单类型（@MTC_SALORDTYPE.U_BusiType，参数 SAMPLE_SALTYPES，2026-10-27）；账期取 d 所在月
    smpSt := IFNULL("MTC_CA_F_PARAM"('SAMPLE_SALTYPES', TO_NVARCHAR(:d, 'YYYY-MM')), ',样品销售,');
    salType = SELECT "Name", MAX("U_CustType") AS "CustType", MAX("U_BusiType") AS "BusiType"
                FROM "@MTC_SALORDTYPE" GROUP BY "Name";

    -- 截至 d 已取消的原单、截至 d 有效的后续单据（同 CO6103）
    cxl = SELECT DISTINCT D."BaseType" AS "ObjType", D."BaseEntry" AS "DocEntry"
            FROM "ODLN" M JOIN "DLN1" D ON M."DocEntry" = D."DocEntry" WHERE M."CANCELED" = 'C' AND M."DocDate" <= :d AND D."BaseType" = 15
          UNION
          SELECT DISTINCT D."BaseType", D."BaseEntry" FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry" WHERE M."CANCELED" = 'C' AND M."DocDate" <= :d AND D."BaseType" = 16
          UNION
          SELECT DISTINCT D."BaseType", D."BaseEntry" FROM "OINV" M JOIN "INV1" D ON M."DocEntry" = D."DocEntry" WHERE M."CANCELED" = 'C' AND M."DocDate" <= :d AND D."BaseType" = 13
          UNION
          SELECT DISTINCT D."BaseType", D."BaseEntry" FROM "ORIN" M JOIN "RIN1" D ON M."DocEntry" = D."DocEntry" WHERE M."CANCELED" = 'C' AND M."DocDate" <= :d AND D."BaseType" = 14;
    nxt = SELECT D."BaseType", D."BaseEntry", D."BaseLine", SUM(D."Quantity") AS "Qty", 'INV' AS "K"
            FROM "OINV" M JOIN "INV1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d AND D."BaseType" = 15
             AND NOT EXISTS (SELECT 1 FROM :cxl X WHERE X."ObjType" = 13 AND X."DocEntry" = M."DocEntry")
           GROUP BY D."BaseType", D."BaseEntry", D."BaseLine"
          UNION ALL
          SELECT D."BaseType", D."BaseEntry", D."BaseLine", SUM(D."Quantity"), 'INV'
            FROM "ORIN" M JOIN "RIN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d AND D."BaseType" = 16
             AND NOT EXISTS (SELECT 1 FROM :cxl X WHERE X."ObjType" = 14 AND X."DocEntry" = M."DocEntry")
           GROUP BY D."BaseType", D."BaseEntry", D."BaseLine"
          UNION ALL
          SELECT D."BaseType", D."BaseEntry", D."BaseLine", SUM(D."Quantity"), 'RET'
            FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d AND D."BaseType" = 15
             AND NOT EXISTS (SELECT 1 FROM :cxl X WHERE X."ObjType" = 16 AND X."DocEntry" = M."DocEntry")
           GROUP BY D."BaseType", D."BaseEntry", D."BaseLine";
    src = SELECT '15' AS "ObjType", M."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate", M."CardCode", M."U_SalOrdType",
                 D."ItemCode", 1 AS "Sign", D."Quantity"
            FROM "ODLN" M JOIN "DLN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d
             AND NOT EXISTS (SELECT 1 FROM :cxl X WHERE X."ObjType" = 15 AND X."DocEntry" = M."DocEntry")
          UNION ALL
          SELECT '16', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), M."CardCode", M."U_SalOrdType",
                 D."ItemCode", -1, D."Quantity"
            FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."CANCELED" <> 'C' AND M."DocDate" <= :d AND IFNULL(D."BaseType", -1) <> 15
             AND NOT EXISTS (SELECT 1 FROM :cxl X WHERE X."ObjType" = 16 AND X."DocEntry" = M."DocEntry");

    RETURN
    SELECT S."ObjType", S."DocEntry", S."LineNum", S."DocDate", S."CardCode",
           T."CustType", CASE WHEN LOCATE(:smpSt, ',' || T."BusiType" || ',') > 0 THEN 'Y' ELSE 'N' END AS "IsSample", S."ItemCode",
           S."Sign" * S."Quantity" AS "DocQty", IFNULL(N1."Qty", 0) AS "InvQty", IFNULL(N2."Qty", 0) AS "RetQty",
           S."Sign" * (S."Quantity" - IFNULL(N1."Qty", 0) - IFNULL(N2."Qty", 0)) AS "OpenQty"
      FROM :src S
      JOIN "OITM" I ON I."ItemCode" = S."ItemCode" AND I."InvntItem" = 'Y'
      LEFT JOIN :salType T ON T."Name" = S."U_SalOrdType"
      LEFT JOIN :nxt N1 ON N1."K" = 'INV' AND TO_NVARCHAR(N1."BaseType") = S."ObjType" AND N1."BaseEntry" = S."DocEntry" AND N1."BaseLine" = S."LineNum"
      LEFT JOIN :nxt N2 ON N2."K" = 'RET' AND TO_NVARCHAR(N2."BaseType") = S."ObjType" AND N2."BaseEntry" = S."DocEntry" AND N2."BaseLine" = S."LineNum"
     WHERE ABS(S."Quantity" - IFNULL(N1."Qty", 0) - IFNULL(N2."Qty", 0)) > 0.000001;
END

@@
-- @stmt 新框架 08_precheck.sql #5
-- 截至某日（含）交货 / 独立退货行的后续消耗：开票（INV 应收发票、RIN 应收贷项）、基于交货的退货（RET），取消单数量反号、经原单找到交货 / 退货行。
-- Qty 与原行 DocQty 同号（交货的开票、退货为正，独立退货的贷项为负），所以 原行未清数量 = DocQty − SUM(Qty)，与 F_GOODS_OPEN 一致。
-- P71 用它算 DN03 转出金额、尾差和发出商品余额（用户 2026-10-15：分次开票的尾差在全部消耗完时清掉）
CREATE OR REPLACE FUNCTION "MTC_CA_F_GOODS_MOVE" (IN d DATE)
RETURNS TABLE ("SrcObj" NVARCHAR(20), "SrcEntry" INTEGER, "SrcLine" INTEGER, "K" NVARCHAR(10), "DocEntry" INTEGER, "LineNum" INTEGER,
               "DocDate" DATE, "U_SalOrdType" NVARCHAR(100), "Qty" DECIMAL(19,6))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    RETURN
    SELECT TO_NVARCHAR(CASE WHEN D."BaseType" = 13 THEN O."BaseType" ELSE D."BaseType" END) AS "SrcObj",
           CASE WHEN D."BaseType" = 13 THEN O."BaseEntry" ELSE D."BaseEntry" END AS "SrcEntry",
           CASE WHEN D."BaseType" = 13 THEN O."BaseLine" ELSE D."BaseLine" END AS "SrcLine",
           CAST('INV' AS NVARCHAR(10)) AS "K", M."DocEntry", D."LineNum", TO_DATE(M."DocDate") AS "DocDate",
           CAST(M."U_SalOrdType" AS NVARCHAR(100)) AS "U_SalOrdType",
           CAST(CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity" AS DECIMAL(19,6)) AS "Qty"
      FROM "OINV" M JOIN "INV1" D ON M."DocEntry" = D."DocEntry"
      JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
      LEFT JOIN "INV1" O ON D."BaseType" = 13 AND O."DocEntry" = D."BaseEntry" AND O."LineNum" = D."BaseLine"
     WHERE M."DocDate" <= :d AND (D."BaseType" = 15 OR (D."BaseType" = 13 AND O."BaseType" = 15))
    UNION ALL
    SELECT TO_NVARCHAR(CASE WHEN D."BaseType" = 14 THEN O."BaseType" ELSE D."BaseType" END),
           CASE WHEN D."BaseType" = 14 THEN O."BaseEntry" ELSE D."BaseEntry" END,
           CASE WHEN D."BaseType" = 14 THEN O."BaseLine" ELSE D."BaseLine" END,
           'RIN', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), M."U_SalOrdType",
           CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity"
      FROM "ORIN" M JOIN "RIN1" D ON M."DocEntry" = D."DocEntry"
      JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
      LEFT JOIN "RIN1" O ON D."BaseType" = 14 AND O."DocEntry" = D."BaseEntry" AND O."LineNum" = D."BaseLine"
     WHERE M."DocDate" <= :d AND (D."BaseType" = 16 OR (D."BaseType" = 14 AND O."BaseType" = 16))
    UNION ALL
    SELECT TO_NVARCHAR(CASE WHEN D."BaseType" = 16 THEN O."BaseType" ELSE D."BaseType" END),
           CASE WHEN D."BaseType" = 16 THEN O."BaseEntry" ELSE D."BaseEntry" END,
           CASE WHEN D."BaseType" = 16 THEN O."BaseLine" ELSE D."BaseLine" END,
           'RET', M."DocEntry", D."LineNum", TO_DATE(M."DocDate"), M."U_SalOrdType",
           CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity"
      FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry"
      JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
      LEFT JOIN "RDN1" O ON D."BaseType" = 16 AND O."DocEntry" = D."BaseEntry" AND O."LineNum" = D."BaseLine"
     WHERE M."DocDate" <= :d AND (D."BaseType" = 15 OR (D."BaseType" = 16 AND O."BaseType" = 15));
END

@@
-- @stmt 新框架 08_precheck.sql #6
CREATE OR REPLACE PROCEDURE "MTC_CA_P10_PRECHECK" (IN RunId BIGINT, OUT BlockCnt INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE stat NVARCHAR(1);
    DECLARE n BIGINT;
    DECLARE feeItem NVARCHAR(50);
    DECLARE bt25 NVARCHAR(500);
    DECLARE convIn NVARCHAR(20); DECLARE convOut NVARCHAR(20);
    DECLARE wwWt NVARCHAR(200); DECLARE trialWt NVARCHAR(200); DECLARE trialBt NVARCHAR(500);
    DECLARE custDom NVARCHAR(50); DECLARE custExp NVARCHAR(50);
    DECLARE exWhs08 NVARCHAR(5000);
    DECLARE pricedIn NVARCHAR(200);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    -- 业务口径参数（MTC_CA_C_PARAM，2026-10-27 从代码中的固定值改为参数）
    convIn := IFNULL("MTC_CA_F_PARAM"('CONV_IN_BUSITYPE', :fc), '204');
    convOut := IFNULL("MTC_CA_F_PARAM"('CONV_OUT_BUSITYPE', :fc), '205');
    wwWt := IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', :fc), ',50,');
    trialWt := IFNULL("MTC_CA_F_PARAM"('TRIAL_WORTYPES', :fc), ',40,');
    trialBt := IFNULL("MTC_CA_F_PARAM"('TRIAL_ISSUE_BUSITYPES', :fc), ',307,305,');
    custDom := IFNULL("MTC_CA_F_PARAM"('CUST_DOM', :fc), '国内客户');
    custExp := IFNULL("MTC_CA_F_PARAM"('CUST_EXP', :fc), '国外客户');
    exWhs08 := IFNULL("MTC_CA_F_PARAM"('PRE08_EXCL_WHS', :fc), ',');
    pricedIn := IFNULL("MTC_CA_F_PARAM"('QCP_PRICED_IN', :fc), ',I01,I03,I05,I07,I08,I09,I90,');

    -- PRE-01 账期未锁定（正式运行在 P00 已拦截；模拟运行允许算锁定账期）
    SELECT MAX("PeriodStat") INTO stat FROM "OFPR" WHERE "Code" = :fc;
    t01 = SELECT :fc AS "KeyCode", '账期已锁定' AS "Info" FROM DUMMY WHERE :rt = 'F' AND :stat = 'Y';
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-01', :t01, NULL);

    -- PRE-02 本期有变动的物料、有出入库订单的产品都有层级，且不是 -1
    t02 = SELECT L."ItemCode" AS "KeyCode",
                 CASE WHEN I."ItemCode" IS NULL THEN '物料不在物料主数据' ELSE '层级为 -1：' || IFNULL(I."LevelNote", '') END AS "Info"
            FROM (SELECT DISTINCT "ItemCode" FROM "MTC_CA_S_LINE" WHERE "RunId" = :RunId
                  UNION   -- 本期有领料或入库的订单的产品：层级决定订单在第几层结转
                  SELECT DISTINCT O."ItemCode" FROM "MTC_CA_S_ORDER" O
                   WHERE O."RunId" = :RunId AND O."ItemCode" IS NOT NULL
                     AND EXISTS (SELECT 1 FROM "MTC_CA_S_LINE" X WHERE X."RunId" = :RunId
                                    AND X."OrderType" = O."OrderType" AND X."OrderEntry" = O."OrderEntry")) L
            LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = L."ItemCode"
           WHERE IFNULL(I."iLevel", -1) = -1;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-02', :t02, NULL);

    -- PRE-03 形态转换同月一对一（同修正稿 CAL_1001_CHECK 第 15 项：每个配对键正好一行转出 CONV_OUT_BUSITYPE、一行转入 CONV_IN_BUSITYPE）
    t03 = SELECT "ObjType" || '-DocNum ' || "DocNum" || '-LineNum ' || "LineNum" AS "KeyCode",
                 '业务类型 ' || "BusiType" || ' 的行缺少配对键（U_BaseType / U_BaseEntry / U_BaseLineGrpNum）' AS "Info"
            FROM "MTC_CA_S_LINE"
           WHERE "RunId" = :RunId AND "BusiType" IN (:convIn, :convOut) AND "Canceled" = 'N' AND "PairKey" IS NULL
          UNION ALL
          SELECT "PairKey", '本月转入 ' || SUM(CASE WHEN "BusiType" = :convIn THEN 1 ELSE 0 END)
                            || ' 行、转出 ' || SUM(CASE WHEN "BusiType" = :convOut THEN 1 ELSE 0 END) || ' 行（应各 1 行）'
            FROM "MTC_CA_S_LINE"
           WHERE "RunId" = :RunId AND "BusiType" IN (:convIn, :convOut) AND "Canceled" = 'N' AND "PairKey" IS NOT NULL
           GROUP BY "PairKey"
          HAVING SUM(CASE WHEN "BusiType" = :convIn THEN 1 ELSE 0 END) <> 1
              OR SUM(CASE WHEN "BusiType" = :convOut THEN 1 ELSE 0 END) <> 1;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-03', :t03, NULL);

    -- PRE-04 没有原交货的销售退货：允许发生，只警告（用户 2026-10-13）；有期初维护价按维护价，没有按本期加权价（清单 S10）
    -- 原交货键在 P20_LINE 中确定：RDN1 标准来源是交货时用标准来源，否则用行上 U_BaseType='15' / U_BaseEntry / U_BaseLine
    -- 物料没有维护价、也没有其他价格来源（与 PRE-23 同一口径 MTC_CA_F_QCP_SRC，2026-11-06）时，
    -- 加权价为 0，退货会按 0 成本入库，说明里写明（用户 2026-10-29）
    s04 = SELECT "ItemCode" FROM "MTC_CA_F_QCP_SRC"(:RunId, :pricedIn) WHERE "IsSrc" = 'Y';
    t04 = SELECT L."ObjType" || '-DocNum ' || L."DocNum" || '-LineNum ' || L."LineNum" AS "KeyCode",
                 L."ItemCode" || ' 退货没有原交货，' || CASE WHEN Q."ItemCode" IS NOT NULL THEN '按期初维护价'
                                                                 WHEN P."ItemCode" IS NOT NULL THEN '也没有期初维护价，按本期加权价'
                                                                 ELSE '也没有期初维护价和其他价格来源，将按 0 成本入库，请在期初成本价维护中填价' END AS "Info"
            FROM "MTC_CA_S_LINE" L
            LEFT JOIN "MTC_CA_S_QCPRICE" Q ON Q."RunId" = :RunId AND Q."ItemCode" = L."ItemCode"
            LEFT JOIN :s04 P ON P."ItemCode" = L."ItemCode"
           WHERE L."RunId" = :RunId AND L."TransCode" = 'O06' AND IFNULL(L."Canceled", 'N') <> 'C'
             AND NOT (L."BaseType" = '15' AND L."BaseEntry" IS NOT NULL);
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-04', :t04, NULL);

    -- PRE-05 计价仓库的每条库存变动都能识别交易类型（旧流程静默丢弃，#13）
    -- 数量和金额都为 0 的 OIVL 行（如基于交货的应收发票 13）不影响库存，不报；数量为 0 但有金额的仍报出
    t05 = SELECT "ObjType" || '-DocNum ' || "DocNum" || '-LineNum ' || IFNULL(TO_NVARCHAR("LineNum"), '') AS "KeyCode",
                 '单据类型 ' || "ObjType" || CASE WHEN "BusiType" IS NOT NULL THEN '，业务类型 ' || "BusiType" ELSE '' END
                 || ' 识别不了交易类型；物料 ' || "ItemCode"
                 || CASE WHEN "Qty" = 0 THEN '（数量为 0，但 OIVL 金额不为 0）' ELSE '' END AS "Info"
            FROM "MTC_CA_S_LINE"
           WHERE "RunId" = :RunId AND "Src" = 'OIVL' AND "TransCode" IS NULL
             AND NOT ("Qty" = 0 AND IFNULL("B1Amt", 0) = 0);
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-05', :t05, NULL);

    -- PRE-06 订单领料 / 入库行能找到订单（只看工单交易 I03/O03/I07/O07/I08/O08/I09/O09，与 P20_LINE 关联订单的口径一致，用户 2026-10-14）
    t06 = SELECT L."ObjType" || '-DocNum ' || L."DocNum" || '-LineNum ' || IFNULL(TO_NVARCHAR(L."LineNum"), '') AS "KeyCode",
                 CASE WHEN L."OrderEntry" IS NULL THEN '交易类型 ' || IFNULL(L."TransCode", '') || '（业务类型 ' || IFNULL(L."BusiType", '') || '）是订单领料 / 入库，但没有关联订单'
                      ELSE '关联的订单 ' || L."OrderType" || '-DocEntry ' || L."OrderEntry" || ' 不存在' END AS "Info"
            FROM "MTC_CA_S_LINE" L
            LEFT JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = L."OrderType" AND O."OrderEntry" = L."OrderEntry"
           WHERE L."RunId" = :RunId AND L."TransCode" IN ('I03', 'O03', 'I07', 'O07', 'I08', 'O08', 'I09', 'O09') AND O."OrderEntry" IS NULL;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-06', :t06, NULL);

    -- PRE-07 库存转储一端是计价仓库、另一端不是：不允许（Q7）
    t07 = SELECT '67' || '-DocNum ' || T0."DocNum" || '-LineNum ' || T1."LineNum" AS "KeyCode",
                 T1."ItemCode" || ' 从 ' || T1."FromWhsCod" || CASE WHEN A."IsCost" = 'Y' THEN '（计价）' ELSE '（不计价）' END
                 || ' 转到 ' || T1."WhsCode" || CASE WHEN B."IsCost" = 'Y' THEN '（计价）' ELSE '（不计价）' END AS "Info"
            FROM "OWTR" T0
            JOIN "WTR1" T1 ON T1."DocEntry" = T0."DocEntry"
            JOIN "MTC_CA_V_WHS" A ON A."WhsCode" = T1."FromWhsCod"
            JOIN "MTC_CA_V_WHS" B ON B."WhsCode" = T1."WhsCode"
           WHERE T0."DocDate" BETWEEN :d0 AND :d1 AND A."IsCost" <> B."IsCost";
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-07', :t07, NULL);

    -- PRE-08 不计价仓库中有采购、订单领料或完工（这些行不计成本，提示核对仓库设置）
    --   参数 PRE08_EXCL_WHS 列出的仓库不报（用户 2026-10-29：警告太多）
    t08 = SELECT TO_NVARCHAR(P0."TransType") || '-DocNum ' || TO_NVARCHAR(P0."BASE_REF") || '-LineNum ' || TO_NVARCHAR(P0."DocLineNum") AS "KeyCode",
                 '仓库 ' || P0."LocCode" || ' 不计价，交易类型 ' || V."TransCode" || '，物料 ' || P0."ItemCode" AS "Info"
            FROM "OIVL" P0
            JOIN "MTC_CA_V_WHS" W ON W."WhsCode" = P0."LocCode" AND W."IsCost" = 'N'
            JOIN "MTC_VIEW_Document" V ON TO_NVARCHAR(V."ObjType") = TO_NVARCHAR(P0."TransType")
                                      AND TO_NVARCHAR(V."DocEntry") = TO_NVARCHAR(P0."CreatedBy")
                                      AND TO_NVARCHAR(V."LineNum") = TO_NVARCHAR(P0."DocLineNum")
           WHERE P0."DocDate" BETWEEN :d0 AND :d1 AND P0."TransType" <> 67
             AND V."TransCode" IN ('I01', 'I06', 'I03', 'I07', 'I08', 'I09', 'I90', 'O03', 'O07', 'O08', 'O09', 'O90')
             AND LOCATE(:exWhs08, ',' || P0."LocCode" || ',') = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-08', :t08, NULL);

    -- PRE-09 试打订单（TRIAL_WORTYPES，默认 40）只能用 TRIAL_ISSUE_BUSITYPES（默认 307 试打领用、305 生产报废）领料（旧检查第 4 项）
    t09 = SELECT L."ObjType" || '-DocNum ' || L."DocNum" || '-LineNum ' || IFNULL(TO_NVARCHAR(L."LineNum"), '') AS "KeyCode",
                 '试打订单 ' || O."OrderNum" || ' 的领料业务类型是 ' || IFNULL(L."BusiType", '空') AS "Info"
            FROM "MTC_CA_S_LINE" L
            JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = L."OrderType" AND O."OrderEntry" = L."OrderEntry"
           WHERE L."RunId" = :RunId AND LOCATE(:trialWt, ',' || O."WorType" || ',') > 0 AND L."BusiClass" = 'B03'
             AND LOCATE(:trialBt, ',' || IFNULL(L."BusiType", '') || ',') = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-09', :t09, NULL);

    -- PRE-10 期初前已关闭或已取消的订单本期仍有出入库 / 加工费（旧检查第 13、14 项）
    --   只有工单交易 I03/O03/I07/O07/I08/O08/I09/O09 会关联订单（P20_LINE），其他交易填了订单号也不报（用户 2026-10-14）
    t10 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode",
                 '订单状态 ' || IFNULL(O."B1Status", '') || '，关单日期 ' || IFNULL(TO_NVARCHAR(O."CloseDate"), '空') || '，本期仍有单据引用' AS "Info"
            FROM "MTC_CA_S_ORDER" O
           WHERE O."RunId" = :RunId AND O."InScope" = 'N';
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-10', :t10, NULL);

    -- PRE-11 订单状态为关闭但没有关单日期：无法判断在哪一期结转关单差异
    t11 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode", '状态为关闭，但关单日期为空' AS "Info"
            FROM "MTC_CA_S_ORDER" O
           WHERE O."RunId" = :RunId AND O."B1Status" = 'L' AND O."CloseDate" IS NULL;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-11', :t11, NULL);

    -- PRE-12 委外加工费找不到订单（这笔金额不进任何订单；只警告，用户 2026-10-13）；SrcKey = DocEntry-LineNum（ProWW 为 @MTC_OMRV DocEntry-LineId）
    --   报出时显示 DocNum（SAP 里按它查，用户 2026-10-29）：PDN → 20 OPDN，RPD → 21 ORPD，PROWW → @MTC_OMRV；查不到单号时仍显示 DocEntry
    --   第二段（用户 2026-11-04）：S_AP_MOVE 里本期计提的加工费行，却不在 S_SUBFEE（收货行没填 U_BaseType = '59' 等）：PUR4 记了 140802，订单没有这笔
    t12 = SELECT CASE F."Src" WHEN 'PDN' THEN '20' WHEN 'RPD' THEN '21' WHEN 'PROWW' THEN 'MTC_OMRV' ELSE F."Src" END
                 || IFNULL('-DocNum ' || TO_NVARCHAR(COALESCE(P."DocNum", R."DocNum", M."DocNum")), '-DocEntry ' || SUBSTR_BEFORE(F."SrcKey", '-'))
                 || CASE WHEN F."Src" = 'PROWW' THEN '-LineId ' ELSE '-LineNum ' END || SUBSTR_AFTER(F."SrcKey", '-') AS "KeyCode",
                 IFNULL(F."MatchNote", '') || '；加工费物料 ' || IFNULL(F."ItemCode", '') AS "Info"
            FROM "MTC_CA_S_SUBFEE" F
            LEFT JOIN "OPDN" P ON F."Src" = 'PDN' AND TO_NVARCHAR(P."DocEntry") = SUBSTR_BEFORE(F."SrcKey", '-')
            LEFT JOIN "ORPD" R ON F."Src" = 'RPD' AND TO_NVARCHAR(R."DocEntry") = SUBSTR_BEFORE(F."SrcKey", '-')
            LEFT JOIN "@MTC_OMRV" M ON F."Src" = 'PROWW' AND TO_NVARCHAR(M."DocEntry") = SUBSTR_BEFORE(F."SrcKey", '-')
           WHERE F."RunId" = :RunId AND F."OrderEntry" IS NULL
          UNION ALL
          SELECT A."ObjType" || IFNULL('-DocNum ' || TO_NVARCHAR(COALESCE(P."DocNum", R."DocNum")), '-DocEntry ' || TO_NVARCHAR(A."DocEntry"))
                 || '-LineNum ' || TO_NVARCHAR(A."LineNum"),
                 '已按加工费计提暂估，但收货 / 退货行没有指向生产收货（U_BaseType 不是 59）；加工费物料 ' || IFNULL(A."ItemCode", '')
            FROM (SELECT DISTINCT "ObjType", "DocEntry", "LineNum", "ItemCode"
                    FROM "MTC_CA_S_AP_MOVE"
                   WHERE "RunId" = :RunId AND "AccrType" = 'SUBFEE' AND "MoveType" IN ('ACCR', 'RET')
                     AND "ObjType" IN ('20', '21') AND "DocDate" BETWEEN :d0 AND :d1) A
            LEFT JOIN "OPDN" P ON A."ObjType" = '20' AND P."DocEntry" = A."DocEntry"
            LEFT JOIN "ORPD" R ON A."ObjType" = '21' AND R."DocEntry" = A."DocEntry"
           WHERE NOT EXISTS (SELECT 1 FROM "MTC_CA_S_SUBFEE" F
                              WHERE F."RunId" = :RunId AND F."Src" = CASE WHEN A."ObjType" = '20' THEN 'PDN' ELSE 'RPD' END
                                AND F."SrcKey" = A."DocEntry" || '-' || A."LineNum");
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-12', :t12, NULL);

    -- PRE-13 同一账期同一产品有多个不同的单位工时（Q21 阻断；用户说明正常不会出现）
    t13 = SELECT "ItemCode" AS "KeyCode", '工时单中有 ' || "LineCnt" || ' 行，最小 ' || TO_NVARCHAR("MinHours") || '，最大 ' || TO_NVARCHAR("Hours") AS "Info"
            FROM "MTC_CA_S_HOURS"
           WHERE "RunId" = :RunId AND "LineCnt" > 1 AND "MinHours" <> "Hours";
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-13', :t13, NULL);

    -- PRE-14 本期有入库、应分摊费用的订单，产品没有工时（Q11）
    t14 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode",
                 '产品 ' || O."ItemCode" || '（费用池 ' || T."PoolCode" || '）本期有入库，但没有工时' AS "Info"
            FROM "MTC_CA_S_ORDER" O
            JOIN "MTC_CA_V_ITEM_POOL" T ON T."RunId" = :RunId AND T."ItemCode" = O."ItemCode"
                                       AND LOCATE(T."WorTypes", ',' || O."WorType" || ',') > 0
            LEFT JOIN "MTC_CA_S_HOURS" H ON H."RunId" = :RunId AND H."ItemCode" = O."ItemCode"
           WHERE O."RunId" = :RunId AND O."RecvQty" > 0 AND IFNULL(H."Hours", 0) = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-14', :t14, NULL);

    -- PRE-15 制造费用凭证来自其他出入库 / 盘点单，而该单据行又作为公摊材料计入费用池（可能重复计入）
    t15 = SELECT DISTINCT "MTC_CA_F_DOCKEY"(E."SrcObj", E."SrcDoc") AS "KeyCode",
                 '凭证 ' || SUBSTR_BEFORE(E."SrcKey", '-') || '（代码 ' || IFNULL(NULLIF(E."SrcTrans", ''), '空') || '）记 ' || E."AcctCode"
                 || '，来源单据同时有公摊材料行' AS "Info"
            FROM "MTC_CA_S_EXP" E
            JOIN "MTC_CA_S_LINE" L ON L."RunId" = :RunId AND L."SharedExp" = 'Y' AND L."ObjType" = E."SrcObj" AND L."DocEntry" = E."SrcDoc"
           WHERE E."RunId" = :RunId AND E."Src" = 'JDT' AND E."SrcObj" IN ('59', '60');
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-15', :t15, NULL);

    -- PRE-16 有期初（上期承接或上期新框架结果）
    SELECT COUNT(*) INTO n FROM "MTC_CA_S_OPEN" WHERE "RunId" = :RunId;
    t16 = SELECT :fc AS "KeyCode", '没有取到期初：上期既不是承接账期（需先运行 MTC_CA_P_BOOTSTRAP），也没有上期新框架结果' AS "Info"
            FROM DUMMY WHERE :n = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-16', :t16, NULL);

    -- PRE-17 本期有入库的生产订单，产品不在任何费用池的分摊范围（按物料组或 U_ItemGrpType 匹配，见 MTC_CA_V_ITEM_POOL）
    t17 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode",
                 '产品 ' || O."ItemCode" || '（物料组 ' || IFNULL(I."ItmsGrpCod", '空') || '，车间类别 ' || IFNULL(I."GrpType", '空')
                 || '）不在 MTC_CA_C_POOL_TGT 的范围内，分不到制造费用和人工' AS "Info"
            FROM "MTC_CA_S_ORDER" O
            LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = O."ItemCode"
           WHERE O."RunId" = :RunId AND O."RecvQty" > 0 AND LOCATE(:wwWt, ',' || O."WorType" || ',') = 0
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_V_ITEM_POOL" T
                              WHERE T."RunId" = :RunId AND T."ItemCode" = O."ItemCode"
                                AND LOCATE(T."WorTypes", ',' || O."WorType" || ',') > 0);
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-17', :t17, NULL);

    -- PRE-18 费用池配置有效：正好一个默认池；关单差异池、成本中心映射、分摊范围引用的池都存在；
    --        同一产品本期只属于一个池（Q22；按物料组和按 U_ItemGrpType 的配置混用时也能查出）
    t18 = SELECT 'C_POOL' AS "KeyCode", '默认池应正好 1 个，实际 ' || COUNT(*) || ' 个' AS "Info"
            FROM "MTC_CA_C_POOL" WHERE "IsDefault" = 'Y'
          HAVING COUNT(*) <> 1
          UNION ALL
          SELECT 'CLOSE_DIF_POOL', '关单差异池 ' || IFNULL(P."V", '空') || ' 不在 MTC_CA_C_POOL 中'
            FROM (SELECT "MTC_CA_F_PARAM"('CLOSE_DIF_POOL', :fc) AS "V" FROM DUMMY) P
           WHERE NOT EXISTS (SELECT 1 FROM "MTC_CA_C_POOL" C WHERE C."PoolCode" = P."V")
          UNION ALL
          SELECT 'C_POOL_SRC-' || S."OcrCode", '引用的池 ' || S."PoolCode" || ' 不存在'
            FROM "MTC_CA_C_POOL_SRC" S
           WHERE :fc BETWEEN S."FromFc" AND S."ToFc"
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_C_POOL" C WHERE C."PoolCode" = S."PoolCode")
          UNION ALL
          SELECT 'C_POOL_TGT-' || T."ItmsGrpCod", '引用的池 ' || T."PoolCode" || ' 不存在'
            FROM "MTC_CA_C_POOL_TGT" T
           WHERE :fc BETWEEN T."FromFc" AND T."ToFc"
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_C_POOL" C WHERE C."PoolCode" = T."PoolCode")
          UNION ALL
          SELECT 'C_POOL_TGT-' || T."ItmsGrpCod", 'MatchBy 只能是 GRP 或 GRPTYPE，实际 ' || IFNULL(T."MatchBy", '空')
            FROM "MTC_CA_C_POOL_TGT" T
           WHERE :fc BETWEEN T."FromFc" AND T."ToFc" AND IFNULL(T."MatchBy", '') NOT IN ('GRP', 'GRPTYPE')
          UNION ALL
          -- 同一产品匹配到多条分摊范围（即使是同一个池，权重也会重复计入）
          SELECT 'ITEM-' || V."ItemCode", '产品匹配到 ' || COUNT(*) || ' 条分摊范围：' || STRING_AGG(V."PoolCode" || '/' || V."MatchBy" || ':' || V."MatchKey", '、')
            FROM "MTC_CA_V_ITEM_POOL" V
           WHERE V."RunId" = :RunId
           GROUP BY V."ItemCode"
          HAVING COUNT(*) > 1
          UNION ALL
          -- 以下用户 2026-10-14 增加（配置改在 B1 维护）：B1 同步失败、成本中心不存在或同期多条、匹配值不存在
          SELECT 'B1 配置', "Msg" FROM "MTC_CA_RUN_STEP" WHERE "RunId" = :RunId AND "StepCode" = 'P05' AND "Status" = 'FAIL'
          UNION ALL
          SELECT 'C_POOL_SRC-' || S."OcrCode", '成本中心 ' || S."OcrCode" || ' 在 OPRC 中不存在，也没有成本中心的 U_CalType 等于它'
            FROM "MTC_CA_C_POOL_SRC" S
           WHERE :fc BETWEEN S."FromFc" AND S."ToFc" AND NOT EXISTS (SELECT 1 FROM "OPRC" P WHERE P."PrcCode" = S."OcrCode")
             -- 作为 OPRC.U_CalType 取值使用、已展开到成本中心的不报（P05）
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_C_POOL_SRC" E WHERE E."Descr" = 'OPRC.U_CalType=' || S."OcrCode")
          UNION ALL
          SELECT 'C_POOL_SRC-' || S."OcrCode", '成本中心本期匹配到 ' || COUNT(*) || ' 条配置：' || STRING_AGG(S."PoolCode" || '（' || S."FromFc" || '~' || S."ToFc" || '）', '、')
            FROM "MTC_CA_C_POOL_SRC" S
           WHERE :fc BETWEEN S."FromFc" AND S."ToFc"
           GROUP BY S."OcrCode" HAVING COUNT(*) > 1
          UNION ALL
          SELECT 'C_POOL_TGT-' || T."ItmsGrpCod",
                 CASE WHEN T."MatchBy" = 'GRP' THEN '物料组 ' ELSE '车间类别（OITB.U_ItemGrpType）' END || T."ItmsGrpCod" || ' 在 OITB 中不存在'
            FROM "MTC_CA_C_POOL_TGT" T
           WHERE :fc BETWEEN T."FromFc" AND T."ToFc"
             AND ((T."MatchBy" = 'GRP' AND NOT EXISTS (SELECT 1 FROM "OITB" B WHERE TO_NVARCHAR(B."ItmsGrpCod") = T."ItmsGrpCod"))
               OR (T."MatchBy" = 'GRPTYPE' AND NOT EXISTS (SELECT 1 FROM "OITB" B WHERE B."U_ItemGrpType" = T."ItmsGrpCod")));
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-18', :t18, NULL);

    -- PRE-19 本期净入库为负的生产订单（完工退回多于入库）：不分摊制造费用和人工（Q20）
    t19 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode",
                 '产品 ' || O."ItemCode" || ' 本期净入库 ' || TO_NVARCHAR(O."RecvQty") || '，不分摊制造费用和人工' AS "Info"
            FROM "MTC_CA_S_ORDER" O
           WHERE O."RunId" = :RunId AND O."RecvQty" < 0 AND LOCATE(:wwWt, ',' || O."WorType" || ',') = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-19', :t19, NULL);

    -- PRE-20 本期应付发票 / 贷项中，库存物料或委外加工费的行不基于收货 / 退货（直接开票、基于采购订单、基于发票的调价贷项）：
    --        PUR2 / PUR3 会冲回它们的系统分录却没有对应的暂估可冲（Q24，用户说明不会出现）
    feeItem := IFNULL("MTC_CA_F_PARAM"('SUBFEE_ITEM', :fc), 'X0510001');
    t20 = SELECT '18' || '-DocNum ' || M."DocNum" || '-LineNum ' || D."LineNum" AS "KeyCode",
                 '应付发票行 ' || D."ItemCode" || ' 不基于收货 / 退货（来源类型 ' || IFNULL(TO_NVARCHAR(D."BaseType"), '无') || '）' AS "Info"
            FROM "OPCH" M JOIN "PCH1" D ON D."DocEntry" = M."DocEntry" JOIN "OITM" I ON I."ItemCode" = D."ItemCode"
           WHERE M."DocDate" BETWEEN :d0 AND :d1 AND M."CANCELED" <> 'C' AND IFNULL(D."BaseType", -1) NOT IN (20, 21)
             AND (I."InvntItem" = 'Y' OR D."ItemCode" = :feeItem)
          UNION ALL
          SELECT '19' || '-DocNum ' || M."DocNum" || '-LineNum ' || D."LineNum",
                 '应付贷项行 ' || D."ItemCode" || ' 不基于收货 / 退货（来源类型 ' || IFNULL(TO_NVARCHAR(D."BaseType"), '无') || '）'
            FROM "ORPC" M JOIN "RPC1" D ON D."DocEntry" = M."DocEntry" JOIN "OITM" I ON I."ItemCode" = D."ItemCode"
           WHERE M."DocDate" BETWEEN :d0 AND :d1 AND M."CANCELED" <> 'C' AND IFNULL(D."BaseType", -1) NOT IN (20, 21)
             AND (I."InvntItem" = 'Y' OR D."ItemCode" = :feeItem);
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-20', :t20, NULL);

    -- PRE-21 本期委外加工费发票的“发票 − 暂估”差额找不到产品（发票行 U_ItemCode 为空或不是物料），差额进不了成本
    t21 = SELECT "MTC_CA_F_DOCKEY"(A."ObjType", A."DocEntry") || '-LineNum ' || A."LineNum" AS "KeyCode",
                 '委外加工费发票差额 ' || TO_NVARCHAR(A."DocAmt" + A."AccrAmt") || '，产品物料 ' || IFNULL(A."ProdItem", '空') || ' 无效' AS "Info"
            FROM "MTC_CA_S_AP_MOVE" A
            LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = A."RunId" AND I."ItemCode" = A."ProdItem"
           WHERE A."RunId" = :RunId AND A."AccrType" = 'SUBFEE' AND A."MoveType" = 'INV'
             AND A."DocDate" BETWEEN :d0 AND :d1 AND A."DocAmt" + A."AccrAmt" <> 0 AND I."ItemCode" IS NULL;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-21', :t21, NULL);

    -- PRE-22 本期材料暂估变动（收货、退货、发票差额）在计价仓库没有库存记录：凭证记了存货科目，物料成本却不含这笔（Q29）
    t22 = SELECT "MTC_CA_F_DOCKEY"(A."ObjType", A."DocEntry") || '-LineNum ' || A."LineNum" AS "KeyCode",
                 CASE A."MoveType" WHEN 'INV' THEN '发票差额 ' || TO_NVARCHAR(IFNULL(A."DocAmt", 0) + A."AccrAmt")
                      ELSE '暂估 ' || TO_NVARCHAR(A."AccrAmt") END || '，物料 ' || A."ItemCode" || ' 没有计价仓库的 OIVL 记录' AS "Info"
            FROM "MTC_CA_S_AP_MOVE" A
           WHERE A."RunId" = :RunId AND A."AccrType" = 'MAT' AND A."DocDate" BETWEEN :d0 AND :d1
             AND CASE WHEN A."MoveType" = 'INV' THEN IFNULL(A."DocAmt", 0) + A."AccrAmt" ELSE A."AccrAmt" END <> 0
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_S_LINE" L
                              WHERE L."RunId" = :RunId AND L."Src" = 'OIVL' AND L."ObjType" = A."ObjType"
                                AND L."DocEntry" = A."DocEntry" AND L."LineNum" = A."LineNum");
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-22', :t22, NULL);

    -- PRE-24 工单类型（U_OrdType）不能为空：为空时分不到制造费用和人工（PRE-17 只看 10–40），对账也归不到生产 / 委外在产品（用户 2026-10-14）
    t24 = SELECT O."OrderType" || '-DocNum ' || O."OrderNum" AS "KeyCode",
                 '产品 ' || IFNULL(O."ItemCode", '空') || '，工单类型（U_OrdType）为空' AS "Info"
            FROM "MTC_CA_S_ORDER" O
           WHERE O."RunId" = :RunId AND IFNULL(O."WorType", '') = '';
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-24', :t24, NULL);

    -- PRE-25 其他收发货行上的科目与库存交易事务配置（@U_CITRN1：业务类型 + 部门 U_CtrCode + 物料组 → U_AcctCode）不一致（用户 2026-10-15）
    -- 例：210 其他辅助领用配的是 5101 制造费用，单据上填了 500101，YF01 借 500101 却没有订单承接，生产在产品对账（POST-13）对不上。
    -- 范围由参数 ACCT_CHECK_BUSITYPES 控制（默认 210）；配置里找不到 业务类型 + 部门 + 物料组 的组合也报出。
    bt25 := IFNULL("MTC_CA_F_PARAM"('ACCT_CHECK_BUSITYPES', :fc), ',210,');
    cfg25 = SELECT TO_NVARCHAR("Code") AS "BusiType", TO_NVARCHAR("U_CtrCode") AS "OcrCode", TO_NVARCHAR("U_ItmGrpCod") AS "ItmsGrpCod",
                   MAX("U_AcctCode") AS "CfgAcct", COUNT(DISTINCT "U_AcctCode") AS "AcctCnt"
              FROM "@U_CITRN1"
             WHERE IFNULL("U_AcctCode", '') <> ''
             GROUP BY TO_NVARCHAR("Code"), TO_NVARCHAR("U_CtrCode"), TO_NVARCHAR("U_ItmGrpCod");
    t25 = SELECT L."ObjType" || '-DocNum ' || L."DocNum" || '-LineNum ' || L."LineNum" AS "KeyCode",
                 '业务类型 ' || L."BusiType" || '，部门 ' || IFNULL(L."OcrCode", '空') || '，物料 ' || L."ItemCode"
                 || '（物料组 ' || IFNULL(I."ItmsGrpCod", '空') || '）：单据科目 ' || IFNULL(L."AcctCode", '空')
                 || CASE WHEN C."CfgAcct" IS NULL THEN '，库存交易事务配置中没有这个 业务类型 + 部门 + 物料组'
                         WHEN C."AcctCnt" > 1 THEN '，库存交易事务配置中同一组合有多个科目'
                         ELSE ' ≠ 配置科目 ' || C."CfgAcct" END AS "Info"
            FROM "MTC_CA_S_LINE" L
            LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = L."RunId" AND I."ItemCode" = L."ItemCode"
            LEFT JOIN :cfg25 C ON C."BusiType" = L."BusiType" AND C."OcrCode" = L."OcrCode"
                              AND C."ItmsGrpCod" = TO_NVARCHAR(I."ItmsGrpCod")
           WHERE L."RunId" = :RunId AND L."ObjType" IN ('59', '60') AND IFNULL(L."Canceled", 'N') = 'N'
             AND LOCATE(:bt25, ',' || L."BusiType" || ',') > 0
             AND (C."CfgAcct" IS NULL OR C."AcctCnt" > 1 OR IFNULL(L."AcctCode", '') <> C."CfgAcct");
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-25', :t25, NULL);

    -- PRE-26 本期应收发票 / 贷项的库存物料行不基于交货 / 退货（直接开票出库、预留发票、基于发票的退货贷项）：
    --        发出商品和 DN03 只认基于交货 / 退货的开票，这类行的成本结转不了（用户 2026-10-15：不会出现，出现就阻断）
    t26 = SELECT '13' || '-DocNum ' || M."DocNum" || '-LineNum ' || D."LineNum" AS "KeyCode",
                 '应收发票行 ' || D."ItemCode" || ' 不基于交货（来源类型 ' || IFNULL(TO_NVARCHAR(D."BaseType"), '无') || '）' AS "Info"
            FROM "OINV" M JOIN "INV1" D ON D."DocEntry" = M."DocEntry" JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
           WHERE M."DocDate" BETWEEN :d0 AND :d1 AND M."CANCELED" <> 'C' AND IFNULL(D."BaseType", -1) <> 15
          UNION ALL
          SELECT '14' || '-DocNum ' || M."DocNum" || '-LineNum ' || D."LineNum",
                 '应收贷项行 ' || D."ItemCode" || ' 不基于退货（来源类型 ' || IFNULL(TO_NVARCHAR(D."BaseType"), '无') || '）'
            FROM "ORIN" M JOIN "RIN1" D ON D."DocEntry" = M."DocEntry" JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
           WHERE M."DocDate" BETWEEN :d0 AND :d1 AND M."CANCELED" <> 'C' AND IFNULL(D."BaseType", -1) <> 16;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-26', :t26, NULL);

    -- PRE-27 销售单据没有客户类型（U_SalOrdType 在 @MTC_SALORDTYPE 中找不到，或 U_CustType 不是参数 CUST_DOM / CUST_EXP，默认 国内客户 / 国外客户）：
    --        DN03 取不到 6401 科目、AR03/AR04 不计提、样品 DN02/DN04 不生成（用户 2026-10-15 阻断）。
    --        范围：本期交货 / 退货 / 应收发票 / 贷项的库存物料行，以及截至期末仍未开票的交货 / 独立退货行
    st27 = SELECT "Name", MAX("U_CustType") AS "CustType" FROM "@MTC_SALORDTYPE" GROUP BY "Name";
    doc27 = SELECT '15' AS "ObjType", M."DocNum", M."DocEntry", M."U_SalOrdType", TO_DATE(M."DocDate") AS "DocDate"
              FROM "ODLN" M WHERE M."CANCELED" <> 'C'
            UNION ALL SELECT '16', M."DocNum", M."DocEntry", M."U_SalOrdType", TO_DATE(M."DocDate") FROM "ORDN" M WHERE M."CANCELED" <> 'C'
            UNION ALL SELECT '13', M."DocNum", M."DocEntry", M."U_SalOrdType", TO_DATE(M."DocDate") FROM "OINV" M WHERE M."CANCELED" <> 'C'
            UNION ALL SELECT '14', M."DocNum", M."DocEntry", M."U_SalOrdType", TO_DATE(M."DocDate") FROM "ORIN" M WHERE M."CANCELED" <> 'C';
    itm27 = SELECT '15' AS "ObjType", D."DocEntry" FROM "DLN1" D JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
            UNION SELECT '16', D."DocEntry" FROM "RDN1" D JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
            UNION SELECT '13', D."DocEntry" FROM "INV1" D JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
            UNION SELECT '14', D."DocEntry" FROM "RIN1" D JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y';
    open27 = SELECT DISTINCT "ObjType", "DocEntry" FROM "MTC_CA_F_GOODS_OPEN"(:d1);
    t27 = SELECT D."ObjType" || '-DocNum ' || D."DocNum" AS "KeyCode",
                 '销售订单类型 ' || IFNULL(D."U_SalOrdType", '空')
                 || CASE WHEN T."Name" IS NULL THEN ' 在 @MTC_SALORDTYPE 中没有' ELSE ' 的客户类型为 ' || IFNULL(T."CustType", '空') END
                 || CASE WHEN D."DocDate" < :d0 THEN '（以前账期的单据，截至期末仍未开票）' ELSE '' END AS "Info"
            FROM :doc27 D
            LEFT JOIN :st27 T ON T."Name" = D."U_SalOrdType"
           WHERE IFNULL(T."CustType", '') NOT IN (:custDom, :custExp)
             AND ((D."DocDate" BETWEEN :d0 AND :d1
                   AND EXISTS (SELECT 1 FROM :itm27 X WHERE X."ObjType" = D."ObjType" AND X."DocEntry" = D."DocEntry"))
                  OR EXISTS (SELECT 1 FROM :open27 O WHERE O."ObjType" = D."ObjType" AND O."DocEntry" = D."DocEntry"));
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-27', :t27, NULL);

    -- PRE-28 参数目录 MTC_CA_C_PARAM_DEF 里的参数，B1 @MTC_CA_PARAM 没有适用于本账期的行（用户 2026-11-01 阻断，为保证准确）：
    --        P05 对 B1 里没有的参数静默沿用新框架种子值，新加的参数（如 GOODS_TAIL_MAX）B1 没补也照算，这里拦下。
    --        判断用 B1 原样快照 MTC_CA_C_PARAM_B1（P05 每次同步时整表刷新）：Code 中 @ 前 = 参数代码，起止账期为空 = 不限。
    --        只看有没有行；取值是否为空、格式、账期重叠由 PRE-18（B1 同步出错）管，列表型参数可以填空值。
    --        旧表 @MTC_CA_EXPSET 不算维护（2026-10-28 起参数在 @MTC_CA_PARAM 维护）。
    SELECT COUNT(*) INTO n FROM SYS."TABLES" WHERE "SCHEMA_NAME" = CURRENT_SCHEMA AND "TABLE_NAME" = '@MTC_CA_PARAM';
    t28 = SELECT '@MTC_CA_PARAM' AS "KeyCode",
                 'B1 没有计算参数表 @MTC_CA_PARAM：参数目录中的 ' || (SELECT COUNT(*) FROM "MTC_CA_C_PARAM_DEF") || ' 个参数都没有维护（在 B1 建表后用 sl_import_costcfg.py --param 导入）' AS "Info"
            FROM DUMMY WHERE :n = 0
          UNION ALL
          SELECT D."ParamCode",
                 D."CnName" || '（' || D."Category" || '）：'
                 || CASE WHEN B."P" IS NOT NULL THEN 'B1 有这个参数（' || B."Ranges" || '），但没有一行的起止账期包含 ' || :fc
                         ELSE 'B1 @MTC_CA_PARAM 没有这个参数' END
                 || CASE WHEN IFNULL(D."Hint", '') <> '' THEN '；填法：' || D."Hint" ELSE '' END
            FROM "MTC_CA_C_PARAM_DEF" D
            LEFT JOIN (SELECT "P", STRING_AGG("F" || '~' || "T", '、' ORDER BY "F") AS "Ranges",
                              MAX(CASE WHEN "F" <= :fc AND "T" >= :fc THEN 1 ELSE 0 END) AS "InFc"
                         FROM (SELECT SUBSTR_BEFORE(TRIM("Code") || '@', '@') AS "P",
                                      IFNULL(NULLIF(TRIM("FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("ToFc"), ''), '9999-99') AS "T"
                                 FROM "MTC_CA_C_PARAM_B1")
                        GROUP BY "P") B ON B."P" = D."ParamCode"
           WHERE :n > 0 AND IFNULL(B."InFc", 0) = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-28', :t28, NULL);

    -- PRE-29 已生成凭单账期里有未进结果的重估单（用户 2026-11-04，只警告）：单据日期在 POSTED 账期内、未取消的 MRV1 行，
    --        不在生成凭单所用运行（PostRunId）的快照里。那个账期不能再正式计算，后面账期按日期也不读它，这笔金额没有任何地方报出。
    --        只报 MTC_CA_S_LINE 里有这次运行的账期：快照没了就无从判断，不误报。
    t29 = SELECT 'MTC_OMRV-DocNum ' || IFNULL(TO_NVARCHAR(T0."DocNum"), TO_NVARCHAR(T0."DocEntry")) || '-LineId ' || T1."LineId" AS "KeyCode",
                 '账期 ' || P."FcCode" || ' 已生成凭单（运行 #' || P."PostRunId" || '），这行重估没有进该账期结果：物料 ' || IFNULL(T1."U_ItemCode", '')
                 || '，日期 ' || TO_NVARCHAR(TO_DATE(T0."U_DocDate")) || '，金额 ' || TO_NVARCHAR(T1."U_Amount")
                 || '。后面账期也不会读它；在 B1 取消后改到未生成凭单的账期重做，或撤销凭单后重新计算' AS "Info"
            FROM "MTC_CA_PERIOD" P
            JOIN "OFPR" F ON F."Code" = P."FcCode"
            JOIN "@MTC_OMRV" T0 ON TO_DATE(T0."U_DocDate") BETWEEN TO_DATE(F."F_RefDate") AND TO_DATE(F."T_RefDate")
            JOIN "@MTC_OMRV1" T1 ON T1."DocEntry" = T0."DocEntry"
           WHERE P."Status" = 'POSTED' AND T0."U_BaseType" = 'MRV1' AND IFNULL(T0."Canceled", 'N') = 'N'
             AND EXISTS (SELECT 1 FROM "MTC_CA_S_LINE" S WHERE S."RunId" = P."PostRunId")
             AND NOT EXISTS (SELECT 1 FROM "MTC_CA_S_LINE" S WHERE S."RunId" = P."PostRunId" AND S."Src" = 'OMRV'
                                AND S."SrcKey" = T1."DocEntry" || '-' || T1."LineId");
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-29', :t29, NULL);

    -- PRE-30 本期有历史委外差异转出时，JZ05 需要的配置要齐（用户 2026-11-04）
    SELECT COUNT(*) INTO n FROM "MTC_CA_WW_HIST" WHERE "PlanFc" = :fc AND "Manual" = 'N';
    t30 = SELECT 'JZ05' AS "KeyCode", 'B1 凭证代码（OTRC）里没有 JZ05，生成凭单会失败，请先在 B1 建' AS "Info"
            FROM DUMMY WHERE :n > 0 AND NOT EXISTS (SELECT 1 FROM "OTRC" WHERE "TrnsCode" = 'JZ05')
          UNION ALL
          SELECT 'COST_TRANSCODES', '参数 COST_TRANSCODES 没有 JZ05：过账后 PP04 会重复结转 510109，请在 B1 @MTC_CA_PARAM 加上'
            FROM (SELECT IFNULL("MTC_CA_F_PARAM"('COST_TRANSCODES', :fc), ',') AS "V" FROM DUMMY) P
           WHERE :n > 0 AND LOCATE(P."V", ',JZ05,') = 0
          UNION ALL
          SELECT 'EXP_JDT_TRANSCODES', '参数 EXP_JDT_TRANSCODES 含 JZ05：过账后会重复进费用池，请从 B1 @MTC_CA_PARAM 去掉'
            FROM (SELECT IFNULL("MTC_CA_F_PARAM"('EXP_JDT_TRANSCODES', :fc), ',') AS "V" FROM DUMMY) P
           WHERE :n > 0 AND LOCATE(P."V", ',JZ05,') > 0
          UNION ALL
          SELECT 'WW_HIST_EXP', '转出科目 ' || IFNULL(P."V", '空') || ' 在 OACT 中不存在或不能记账'
            FROM (SELECT "MTC_CA_F_ACCT"('WW_HIST_EXP', :fc) AS "V" FROM DUMMY) P
           WHERE :n > 0 AND NOT EXISTS (SELECT 1 FROM "OACT" A WHERE A."AcctCode" = P."V" AND A."Postable" = 'Y')
          UNION ALL
          SELECT 'WW_HIST_OCR', '转出成本中心 ' || IFNULL(P."V", '空') || ' 在 OPRC 中不存在'
            FROM (SELECT "MTC_CA_F_PARAM"('WW_HIST_OCR', :fc) AS "V" FROM DUMMY) P
           WHERE :n > 0 AND NOT EXISTS (SELECT 1 FROM "OPRC" O WHERE O."PrcCode" = P."V");
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-30', :t30, NULL);

    -- PRE-31 委外加工费与入库不同期（用户 2026-11-06，只警告）：业务要求本月入库本月暂估。本期加工费收货行对应的生产收货不在本期时列出，
    --   尤其订单本期还有下一批入库时：加工费全部结转给这批入库，订单上没有留存，POST-06 也看不到。不改计算。
    --   只看未取消的收货行；退货、取消单是更正，不算。键用订单，执行台点行看该订单当月交易（加工费非库存，不在快照里）
    t31 = SELECT F."OrderType" || IFNULL('-DocNum ' || O."OrderNum", '-DocEntry ' || TO_NVARCHAR(F."OrderEntry")) AS "KeyCode",
                 '加工费收货 DocNum ' || TO_NVARCHAR(P."DocNum") || ' 行 ' || SUBSTR_AFTER(F."SrcKey", '-') || '（' || TO_NVARCHAR(F."DocDate", 'YYYY-MM-DD')
                 || '）金额 ' || TO_NVARCHAR(ROUND(F."Amount", 2)) || '；生产收货 DocNum ' || TO_NVARCHAR(I."DocNum") || '（' || TO_NVARCHAR(TO_DATE(I."DocDate"), 'YYYY-MM-DD')
                 || '）；产品 ' || IFNULL(O."ItemCode", '') || '；'
                 || CASE WHEN IFNULL(O."RecvQty", 0) <> 0 THEN '订单本期有入库，这笔结转给本期入库'
                         WHEN O."StatusAtEnd" = 'CLOSED' THEN '订单已关闭，这笔转关单差异'
                         ELSE '订单本期没有入库，留在订单上等下次入库' END AS "Info"
            FROM "MTC_CA_S_SUBFEE" F
            JOIN "OPDN" P ON TO_NVARCHAR(P."DocEntry") = SUBSTR_BEFORE(F."SrcKey", '-') AND P."CANCELED" = 'N'
            JOIN "OIGN" I ON I."DocEntry" = F."RcptEntry"
            LEFT JOIN "MTC_CA_S_ORDER" O ON O."RunId" = F."RunId" AND O."OrderType" = F."OrderType" AND O."OrderEntry" = F."OrderEntry"
           WHERE F."RunId" = :RunId AND F."Src" = 'PDN' AND F."OrderEntry" IS NOT NULL
             AND TO_DATE(I."DocDate") NOT BETWEEN :d0 AND :d1;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-31', :t31, NULL);

    SELECT COUNT(*) INTO BlockCnt FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "Stage" = 'PRE' AND "Result" = 'FAIL';
END

@@
-- @stmt 新框架 09_bootstrap.sql #1
-- =====================================================================
-- 新成本框架 第 1 期：期初承接（设计稿第 7 节，一次性）
-- CALL "MTC_CA_P_BOOTSTRAP"('2026-08');   -- 承接账期 = MTC_CA_C_PARAM.BOOTSTRAP_FC
-- 从旧框架该期结果取物料期末和订单在产品，写 MTC_CA_BOOT_*；之后起始账期（2026-09）的 P20_OPEN 读这些表。
-- 前提：旧框架该期已按月结顺序跑完（含 CO4001 IsInsert='Y'、两次 CO4011 写 ZCP1）。可重复执行。
-- 旧表符号【读代码】：0321_OWOR1 的领料数量、金额为负（出库为负），这里取反为正。
-- 0321_OWOR1 早期行可能没有 DocType，按 202 处理。
-- 物料期末和订单领料的料工费拆分（用户 2026-10-18）：旧框架期末不分料工费，按旧框架截至承接账期最近一个有完工的账期算比例，
-- 写 MTC_CA_BOOT_RATIO；物料期末在这里拆，订单 × 材料在 P20_OPEN 复制到快照时按领用材料的比例拆。
-- =====================================================================
-- BOOT-01（设计稿 Q8）：ZCP1 合计 ≠ ZCP 订单在产品；另列出在产品大于累计领料（累计结转为负）的材料
CREATE OR REPLACE VIEW "MTC_CA_V_BOOT_CHECK" AS
SELECT "FcCode", 'ZCP1≠ZCP' AS "Issue", "OrderType", "OrderEntry", NULL AS "ItemCode",
       IFNULL("Zcp1Wip", 0) AS "Value1", IFNULL("ZcpWip", 0) AS "Value2"
  FROM "MTC_CA_BOOT_ORDER"
 WHERE ABS(IFNULL("Zcp1Wip", 0) - IFNULL("ZcpWip", 0)) > 0.01
UNION ALL
SELECT "FcCode", '在产品>累计领料', "OrderType", "OrderEntry", "ItemCode", "WipAmt", "CumIssueAmt"
  FROM "MTC_CA_BOOT_ORDER_MAT"
 WHERE "CumCarriedAmt" < -0.01

@@
-- @stmt 新框架 09_bootstrap.sql #2
-- 料工费比例（承接 MTC_CA_P_BOOTSTRAP 和历史回填 MTC_CA_P_LEGACY_LOAD 共用；2026-11-02 从 P_BOOTSTRAP 原样抽出，口径不变）
-- 一行 = 一个产品截至 FcCode 的料工费比例（四项合计 1），没有完工记录的物料不在结果里（调用方按 100% 材料处理）
-- 料工费比例（用户 2026-10-18）：每个产品取旧 0321_OWOR_SUM 截至 FcCode、最近一个有完工（IgnQty > 0）的账期，
-- 本期完工成本 1Material / 2ManExp（制造）/ 3LabAmount（人工）/ 4WWExp（委外）。不用返工单（REWORK_WORTYPES，默认 30，领料和产出是同一物料）；
-- 四项有负数或合计 ≤ 0 的账期跳过，往前找。
-- 旧框架把领用的半成品成本整个记在 1Material，新框架四项随物料逐级传递，所以 1Material 再按订单累计领料的金额构成
-- 拆到各领用材料，按材料自己的比例（下层先算）展开；采购件、没有完工记录或还没算出比例的材料按 100% 材料。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_LEGACY_RATIO" (IN FcCode NVARCHAR(10),
    OUT oRatio TABLE ("ItemCode" NVARCHAR(50), "RatioFc" NVARCHAR(10), "RMat" DECIMAL(19,10), "RMfg" DECIMAL(19,10),
                      "RLab" DECIMAL(19,10), "RSub" DECIMAL(19,10), "Basis" NVARCHAR(200)))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE i INT;
    DECLARE rwWt NVARCHAR(200);
    rwWt := IFNULL("MTC_CA_F_PARAM"('REWORK_WORTYPES', :FcCode), ',30,');   -- 返工单的订单类型（参数，2026-10-27）
    cand = SELECT "ItemCode", "FcCode" AS "RatioFc", MAX("iLevel") AS "Lv",
                  SUM(IFNULL("1Material", 0)) AS "M", SUM(IFNULL("2ManExp", 0)) AS "F",
                  SUM(IFNULL("3LabAmount", 0)) AS "L", SUM(IFNULL("4WWExp", 0)) AS "S"
             FROM "MTC_COST_0321_OWOR_SUM"
            WHERE "FcCode" <= :FcCode AND LOCATE(:rwWt, ',' || IFNULL("WorType", '') || ',') = 0 AND IFNULL("IgnQty", 0) > 0 AND "ItemCode" IS NOT NULL
            GROUP BY "ItemCode", "FcCode"
           HAVING SUM(IFNULL("1Material", 0)) >= 0 AND SUM(IFNULL("2ManExp", 0)) >= 0
              AND SUM(IFNULL("3LabAmount", 0)) >= 0 AND SUM(IFNULL("4WWExp", 0)) >= 0
              AND SUM(IFNULL("1Material", 0) + IFNULL("2ManExp", 0) + IFNULL("3LabAmount", 0) + IFNULL("4WWExp", 0)) > 0;
    pick = SELECT "ItemCode", "RatioFc", "M", "F", "L", "S", "M" + "F" + "L" + "S" AS "T",
                  CASE WHEN IFNULL("Lv", -1) < 0 THEN 20 ELSE LEAST("Lv", 19) END AS "LvKey"
             FROM (SELECT C.*, ROW_NUMBER() OVER (PARTITION BY C."ItemCode" ORDER BY C."RatioFc" DESC) AS "Rn" FROM :cand C) X
            WHERE X."Rn" = 1;
    ordc = SELECT IFNULL(S."DocType", '202') AS "OrderType", S."WorEntry", S."ItemCode", S."FcCode", IFNULL(S."1Material", 0) AS "M"
             FROM "MTC_COST_0321_OWOR_SUM" S
             JOIN :pick P ON P."ItemCode" = S."ItemCode" AND P."RatioFc" = S."FcCode"
            WHERE LOCATE(:rwWt, ',' || IFNULL(S."WorType", '') || ',') = 0 AND IFNULL(S."IgnQty", 0) > 0;
    -- 订单截至该账期的累计领料（净额为正的材料），0321_OWOR1 金额出库为负
    oiss = SELECT O."OrderType", O."WorEntry", O."FcCode", W."ItemCode" AS "Mat", -SUM(IFNULL(W."Amount", 0)) AS "Amt"
             FROM (SELECT DISTINCT "OrderType", "WorEntry", "FcCode" FROM :ordc) O
             JOIN "MTC_COST_0321_OWOR1" W ON IFNULL(W."DocType", '202') = O."OrderType" AND W."WorEntry" = O."WorEntry" AND W."FcCode" <= O."FcCode"
            GROUP BY O."OrderType", O."WorEntry", O."FcCode", W."ItemCode"
           HAVING -SUM(IFNULL(W."Amount", 0)) > 0;
    otot = SELECT "OrderType", "WorEntry", "FcCode", SUM("Amt") AS "Tot" FROM :oiss GROUP BY "OrderType", "WorEntry", "FcCode";
    -- 产品 × 领用材料的完工材料金额；订单没有领料记录的，完工材料记为直接材料（Mat 为空）
    mix = SELECT O."ItemCode" AS "Prod", I."Mat", SUM(O."M" * I."Amt" / T."Tot") AS "W"
            FROM :ordc O
            JOIN :otot T ON T."OrderType" = O."OrderType" AND T."WorEntry" = O."WorEntry" AND T."FcCode" = O."FcCode"
            JOIN :oiss I ON I."OrderType" = O."OrderType" AND I."WorEntry" = O."WorEntry" AND I."FcCode" = O."FcCode"
           GROUP BY O."ItemCode", I."Mat"
          UNION ALL
          SELECT O."ItemCode", CAST(NULL AS NVARCHAR(50)), SUM(O."M")
            FROM :ordc O
           WHERE NOT EXISTS (SELECT 1 FROM :otot T WHERE T."OrderType" = O."OrderType" AND T."WorEntry" = O."WorEntry" AND T."FcCode" = O."FcCode")
           GROUP BY O."ItemCode";
    -- 下层先算，上层展开时读已算出的下层比例（原来读 MTC_CA_BOOT_RATIO，现在读累积的表变量，结果相同）
    acc = SELECT CAST(NULL AS NVARCHAR(50)) AS "ItemCode", CAST(NULL AS NVARCHAR(10)) AS "RatioFc",
                 CAST(0 AS DECIMAL(19,10)) AS "RMat", CAST(0 AS DECIMAL(19,10)) AS "RMfg",
                 CAST(0 AS DECIMAL(19,10)) AS "RLab", CAST(0 AS DECIMAL(19,10)) AS "RSub", CAST(NULL AS NVARCHAR(200)) AS "Basis"
            FROM DUMMY WHERE 1 = 0;
    i := 0;
    WHILE :i <= 20 DO   -- 按层级从下往上（20 = 层级未知）；沿用 P40 写法用 WHILE
        acc = SELECT * FROM :acc
              UNION ALL
              SELECT P."ItemCode", P."RatioFc",
                     CAST(IFNULL(X."EMat", P."M") / P."T" AS DECIMAL(19,10)), CAST((P."F" + IFNULL(X."EMfg", 0)) / P."T" AS DECIMAL(19,10)),
                     CAST((P."L" + IFNULL(X."ELab", 0)) / P."T" AS DECIMAL(19,10)), CAST((P."S" + IFNULL(X."ESub", 0)) / P."T" AS DECIMAL(19,10)),
                     CAST('旧 0321_OWOR_SUM ' || P."RatioFc" || ' 完工成本，材料按领料逐级展开' AS NVARCHAR(200))
                FROM :pick P
                LEFT JOIN (SELECT A."Prod",
                                  SUM(A."W" * IFNULL(R."RMat", 1)) AS "EMat", SUM(A."W" * IFNULL(R."RMfg", 0)) AS "EMfg",
                                  SUM(A."W" * IFNULL(R."RLab", 0)) AS "ELab", SUM(A."W" * IFNULL(R."RSub", 0)) AS "ESub"
                             FROM :mix A
                             LEFT JOIN :acc R ON R."ItemCode" = A."Mat"
                            GROUP BY A."Prod") X ON X."Prod" = P."ItemCode"
               WHERE P."LvKey" = :i;
        i := :i + 1;
    END WHILE;
    oRatio = SELECT * FROM :acc;
END

@@
-- @stmt 新框架 09_bootstrap.sql #3
CREATE OR REPLACE PROCEDURE "MTC_CA_P_BOOTSTRAP" (IN FcCode NVARCHAR(10))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE d1 DATE;
    DECLARE nItem BIGINT; DECLARE nOrd BIGINT; DECLARE nMat BIGINT; DECLARE nDiff BIGINT;
    DECLARE nRatio BIGINT; DECLARE nSplit BIGINT;
    DECLARE gc INT; DECLARE gm NVARCHAR(2000);
    DECLARE bootFc NVARCHAR(10);
    SELECT MAX(TO_DATE("T_RefDate")) INTO d1 FROM "OFPR" WHERE "Code" = :FcCode;
    IF :d1 IS NULL THEN
        SELECT -1 AS "Code", '账期不存在：' || IFNULL(:FcCode, '') AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    -- 先把 B1 @MTC_CA_PARAM 抽取到 MTC_CA_C_PARAM（用户 2026-10-29），承接账期以抽取后的 BOOTSTRAP_FC 为准：
    -- 执行台按页面上显示的账期发起，页面是上次抽取的值，B1 改过时这里拦住；任务结束后执行台自动刷新承接账期，再点一次即可
    CALL "MTC_CA_P05_CFG_SYNC"(NULL);
    COMMIT;
    bootFc := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :FcCode);
    IF IFNULL(:bootFc, '') <> :FcCode THEN
        SELECT -1 AS "Code", '承接账期参数 BOOTSTRAP_FC（已从 B1 @MTC_CA_PARAM 读取）是 ' || IFNULL(:bootFc, '（空）') || '，不是 ' || :FcCode
                             || '；执行台已按新值刷新，确认承接账期后再点一次期初承接' AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    -- 起始账期已生成凭单时不能重做承接（会改掉已出凭单那期的期初；用户 2026-10-19）
    CALL "MTC_CA_P_PERIOD_GUARD"(:FcCode, 'BOOT', gc, gm);
    IF :gc <> 0 THEN
        SELECT -1 AS "Code", :gm AS "Msg" FROM DUMMY;
        RETURN;
    END IF;

    DELETE FROM "MTC_CA_BOOT_ITEM" WHERE "FcCode" = :FcCode;
    DELETE FROM "MTC_CA_BOOT_ORDER" WHERE "FcCode" = :FcCode;
    DELETE FROM "MTC_CA_BOOT_ORDER_MAT" WHERE "FcCode" = :FcCode;
    DELETE FROM "MTC_CA_BOOT_RATIO" WHERE "FcCode" = :FcCode;

    -- 物料期末：先全部记材料，下面有料工费比例的再拆分
    -- 0301 每个物料按 MTC_COST_0101_COSTTYPE 每个成本类型一行，0302 回写期末数量时不分成本类型，各行数量相同；
    -- 旧代码只用 CostCode='20' 这一行（金额也只写在这一行），所以只取这一行，不能各行相加（2026-10-13）
    INSERT INTO "MTC_CA_BOOT_ITEM" ("FcCode", "ItemCode", "Qty", "MatAmt", "Amount", "Src", "LoadTime")
    SELECT :FcCode, "ItemCode", SUM(IFNULL("QM_Qty", 0)), SUM(IFNULL("QM_Amount", 0)), SUM(IFNULL("QM_Amount", 0)),
           '旧 0301 期末；没有完工记录，全部记材料', CURRENT_TIMESTAMP
      FROM "MTC_COST_0301_INVNT"
     WHERE "FcCode" = :FcCode AND "CostCode" = '20'
     GROUP BY "ItemCode"
    HAVING SUM(IFNULL("QM_Qty", 0)) <> 0 OR SUM(IFNULL("QM_Amount", 0)) <> 0;
    nItem := ::ROWCOUNT;

    -- 料工费比例（用户 2026-10-18）：算法在 MTC_CA_P_LEGACY_RATIO（2026-11-02 抽出，历史回填共用，口径不变）
    CALL "MTC_CA_P_LEGACY_RATIO"(:FcCode, rat);
    INSERT INTO "MTC_CA_BOOT_RATIO" ("FcCode", "ItemCode", "RatioFc", "RMat", "RMfg", "RLab", "RSub", "Basis", "LoadTime")
    SELECT :FcCode, "ItemCode", "RatioFc", "RMat", "RMfg", "RLab", "RSub", "Basis", CURRENT_TIMESTAMP FROM :rat;
    SELECT COUNT(*) INTO nRatio FROM "MTC_CA_BOOT_RATIO" WHERE "FcCode" = :FcCode;

    -- 物料期末按比例拆分：制造、人工、委外四舍五入到分，材料 = 金额 − 其余三项（合计不变）
    UPDATE T0 SET T0."MfgAmt" = ROUND(T0."Amount" * R."RMfg", 2), T0."LabAmt" = ROUND(T0."Amount" * R."RLab", 2),
                  T0."SubAmt" = ROUND(T0."Amount" * R."RSub", 2),
                  T0."MatAmt" = T0."Amount" - ROUND(T0."Amount" * R."RMfg", 2) - ROUND(T0."Amount" * R."RLab", 2) - ROUND(T0."Amount" * R."RSub", 2),
                  T0."Src" = '旧 0301 期末；料工费按旧框架 ' || R."RatioFc" || ' 完工比例拆分（MTC_CA_BOOT_RATIO）'
      FROM "MTC_CA_BOOT_ITEM" T0
      JOIN "MTC_CA_BOOT_RATIO" R ON R."FcCode" = T0."FcCode" AND R."ItemCode" = T0."ItemCode"
     WHERE T0."FcCode" = :FcCode;
    nSplit := ::ROWCOUNT;

    -- 截至承接账期期末仍未关闭的订单。按期末当时的状态看：期末之后才取消的也算（取消日期取 UpdateDate，用户 2026-11-04）
    ord = SELECT '202' AS "OrderType", "DocEntry" AS "OrderEntry"
            FROM "OWOR"
           WHERE ("Status" <> 'C' OR TO_DATE("UpdateDate") > :d1) AND IFNULL(TO_DATE("PostDate"), :d1) <= :d1
             AND NOT ("Status" = 'L' AND IFNULL(TO_DATE("CloseDate"), :d1) <= :d1)
          UNION ALL
          SELECT 'MTC_OWOR', "DocEntry"
            FROM "@MTC_OWOR"
           WHERE ("U_Status" <> 'C' OR TO_DATE("UpdateDate") > :d1) AND IFNULL(TO_DATE("U_PostDate"), :d1) <= :d1
             AND NOT ("U_Status" = 'L' AND IFNULL(TO_DATE("U_CloseDate"), :d1) <= :d1);

    issue = SELECT IFNULL("DocType", '202') AS "OrderType", TO_INTEGER("WorEntry") AS "OrderEntry", "ItemCode",
                   -SUM(IFNULL("IgeQty", 0)) AS "Qty", -SUM(IFNULL("Amount", 0)) AS "Amt"
              FROM "MTC_COST_0321_OWOR1"
             WHERE "FcCode" <= :FcCode AND "WorEntry" LIKE_REGEXPR '^[0-9]+$'
             GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry"), "ItemCode";
    wip = SELECT "DocType" AS "OrderType", "WorEntry" AS "OrderEntry", "ItemCode",
                 SUM(IFNULL("Quantity", 0)) AS "Qty", SUM(IFNULL("Amount", 0)) AS "Amt"
            FROM "MTC_COST_0322_OWOR_ZCP1"
           WHERE "FcCode" = :FcCode
           GROUP BY "DocType", "WorEntry", "ItemCode";

    INSERT INTO "MTC_CA_BOOT_ORDER_MAT" ("FcCode", "OrderType", "OrderEntry", "ItemCode", "CumIssueQty", "CumIssueAmt",
                                         "WipQty", "WipAmt", "CumCarriedAmt", "LoadTime")
    SELECT :FcCode, K."OrderType", K."OrderEntry", K."ItemCode",
           IFNULL(I."Qty", 0), IFNULL(I."Amt", 0), IFNULL(W."Qty", 0), IFNULL(W."Amt", 0),
           IFNULL(I."Amt", 0) - IFNULL(W."Amt", 0), CURRENT_TIMESTAMP
      FROM (SELECT "OrderType", "OrderEntry", "ItemCode" FROM :issue
            UNION
            SELECT "OrderType", "OrderEntry", "ItemCode" FROM :wip) K
      JOIN :ord O ON O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
      LEFT JOIN :issue I ON I."OrderType" = K."OrderType" AND I."OrderEntry" = K."OrderEntry" AND I."ItemCode" = K."ItemCode"
      LEFT JOIN :wip W ON W."OrderType" = K."OrderType" AND W."OrderEntry" = K."OrderEntry" AND W."ItemCode" = K."ItemCode";
    nMat := ::ROWCOUNT;

    INSERT INTO "MTC_CA_BOOT_ORDER" ("FcCode", "OrderType", "OrderEntry", "CumRecvQty", "ZcpWip", "Zcp1Wip", "LoadTime")
    SELECT :FcCode, O."OrderType", O."OrderEntry", IFNULL(R."Qty", 0), Z."Wip",
           (SELECT SUM(W."Amt") FROM :wip W WHERE W."OrderType" = O."OrderType" AND W."OrderEntry" = O."OrderEntry"),
           CURRENT_TIMESTAMP
      FROM :ord O
      LEFT JOIN (SELECT IFNULL("DocType", '202') AS "OrderType", TO_INTEGER("WorEntry") AS "OrderEntry", SUM(IFNULL("IgnQty", 0)) AS "Qty"
                   FROM "MTC_COST_0321_OWOR"
                  WHERE "FcCode" <= :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$'
                  GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry")) R
        ON R."OrderType" = O."OrderType" AND R."OrderEntry" = O."OrderEntry"
      LEFT JOIN (SELECT "DocType", "WorEntry", SUM(IFNULL("在产品新", 0)) AS "Wip"
                   FROM "MTC_COST_0322_OWOR_ZCP"
                  WHERE "期间" = :FcCode
                  GROUP BY "DocType", "WorEntry") Z
        ON Z."DocType" = O."OrderType" AND Z."WorEntry" = O."OrderEntry"
     WHERE R."OrderEntry" IS NOT NULL OR Z."WorEntry" IS NOT NULL
        OR EXISTS (SELECT 1 FROM "MTC_CA_BOOT_ORDER_MAT" M
                    WHERE M."FcCode" = :FcCode AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry");
    nOrd := ::ROWCOUNT;

    SELECT COUNT(*) INTO nDiff FROM "MTC_CA_V_BOOT_CHECK" WHERE "FcCode" = :FcCode;

    SELECT 0 AS "Code",
           '期初承接完成：物料 ' || :nItem || ' 个（其中 ' || :nSplit || ' 个按旧框架完工比例拆分料工费，其余全部记材料；比例见 MTC_CA_BOOT_RATIO，共 '
           || :nRatio || ' 个物料），订单 ' || :nOrd || ' 张，订单 × 材料 ' || :nMat || ' 行；'
           || CASE WHEN :nDiff = 0 THEN '各项核对一致' ELSE :nDiff || ' 项需要核对，见 MTC_CA_V_BOOT_CHECK' END AS "Msg"
      FROM DUMMY;
END

@@
-- @stmt 新框架 11_result_tables.sql #1
-- =====================================================================
-- 新成本框架 第 2 期：计算结果表（设计稿 3.5）
-- 四项成本要素贯穿全流程：Mat 材料、Mfg 制造费用、Lab 人工、Sub 委外加工费；金额 = 四项之和。
-- 迭代过程中原地更新，收敛后在 P50 定稿；未收敛 / 失败时由 MTC_CA_P_RUN_CLEAN 删除本次结果。
-- =====================================================================
CREATE COLUMN TABLE "MTC_CA_R_LINE" (
    "FcCode" NVARCHAR(10) NOT NULL, "RunType" NVARCHAR(1) NOT NULL, "Scenario" NVARCHAR(30) NOT NULL, "RunId" BIGINT NOT NULL,
    "LineId"     BIGINT         NOT NULL,       -- = S_LINE.LineId
    "ItemCode"   NVARCHAR(50)   NOT NULL,
    "TransCode"  NVARCHAR(10),
    "Qty"        DECIMAL(19,6)  NOT NULL,
    "Cat"        NVARCHAR(10)   NOT NULL,       -- 定价类别，见 MTC_CA_P30_INIT
    "InVal"      NVARCHAR(1)    NOT NULL DEFAULT 'N',  -- Y = 计入物料加权单价的入库
    "OrderType"  NVARCHAR(20),
    "OrderEntry" INTEGER,
    "PoolCode"   NVARCHAR(20),                  -- 公摊材料行归入的费用池
    "IsShared"   NVARCHAR(1)    NOT NULL DEFAULT 'N',
    "MatAmt"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "MfgAmt"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "LabAmt"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "SubAmt"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "Amount"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "Price"      DECIMAL(19,6),
    "PriceSrc"   NVARCHAR(200),
    "RuleId"     NVARCHAR(20),
    "Iter"       INT,
    PRIMARY KEY ("RunId", "LineId")
)

@@
-- @stmt 新框架 11_result_tables.sql #2
COMMENT ON TABLE "MTC_CA_R_LINE" IS '单据行成本：一行 = 一条库存变动（对应 S_LINE），含四项金额、价格来源、规则编号'

@@
-- @stmt 新框架 11_result_tables.sql #3
CREATE INDEX "MTC_CA_R_LINE_IX1" ON "MTC_CA_R_LINE" ("RunId", "ItemCode")

@@
-- @stmt 新框架 11_result_tables.sql #4
CREATE INDEX "MTC_CA_R_LINE_IX2" ON "MTC_CA_R_LINE" ("RunId", "OrderType", "OrderEntry")

@@
-- @stmt 新框架 11_result_tables.sql #5
CREATE COLUMN TABLE "MTC_CA_R_ITEM" (
    "FcCode" NVARCHAR(10) NOT NULL, "RunType" NVARCHAR(1) NOT NULL, "Scenario" NVARCHAR(30) NOT NULL, "RunId" BIGINT NOT NULL,
    "ItemCode"   NVARCHAR(50)   NOT NULL,
    "iLevel"     INT            NOT NULL,       -- 计算用层级（-1 的物料放在最高层之后）
    "OpenQty"    DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "OpenMat"    DECIMAL(19,6)  NOT NULL DEFAULT 0, "OpenMfg" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "OpenLab"    DECIMAL(19,6)  NOT NULL DEFAULT 0, "OpenSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "PMat"       DECIMAL(19,6)  NOT NULL DEFAULT 0, "PMfg" DECIMAL(19,6) NOT NULL DEFAULT 0,   -- 当前单价（四项）
    "PLab"       DECIMAL(19,6)  NOT NULL DEFAULT 0, "PSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "LastPMat"   DECIMAL(19,6)  NOT NULL DEFAULT 0, "LastPMfg" DECIMAL(19,6) NOT NULL DEFAULT 0, -- 上一轮单价
    "LastPLab"   DECIMAL(19,6)  NOT NULL DEFAULT 0, "LastPSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "PriceSrc"   NVARCHAR(20),                  -- WAVG 本期加权 / QCPRICE 维护价兜底 / OPEN 期初单价 / ZERO 无价
    "InQty"      DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "InMat"      DECIMAL(19,6)  NOT NULL DEFAULT 0, "InMfg" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "InLab"      DECIMAL(19,6)  NOT NULL DEFAULT 0, "InSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "OutQty"     DECIMAL(19,6)  NOT NULL DEFAULT 0,   -- 出库为负
    "OutMat"     DECIMAL(19,6)  NOT NULL DEFAULT 0, "OutMfg" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "OutLab"     DECIMAL(19,6)  NOT NULL DEFAULT 0, "OutSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "EndQty"     DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "EndMat"     DECIMAL(19,6)  NOT NULL DEFAULT 0, "EndMfg" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "EndLab"     DECIMAL(19,6)  NOT NULL DEFAULT 0, "EndSub" DECIMAL(19,6) NOT NULL DEFAULT 0,
    "EndAmount"  DECIMAL(19,6)  NOT NULL DEFAULT 0,
    "Flags"      NVARCHAR(200),                 -- 负库存 / 兜底价 / 无价 / 尾差无处挤
    "TailAmt"    DECIMAL(19,6)  NOT NULL DEFAULT 0,   -- 零库存尾差结转（TAIL-01，Q32）：已计入 Out 四项，凭证 JZ04；负数 = 转出
    "RtOpenMat"   DECIMAL(19,4),                 -- 期初料工费占比·材料（%）= 期初材料 ÷ 期初四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOpenLab"   DECIMAL(19,4),                 -- 期初料工费占比·人工（%）= 期初人工 ÷ 期初四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOpenMfg"   DECIMAL(19,4),                 -- 期初料工费占比·制造费用（%）= 期初制造费用 ÷ 期初四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOpenSub"   DECIMAL(19,4),                 -- 期初料工费占比·委外加工费（%）= 期初委外加工费 ÷ 期初四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtInMat"     DECIMAL(19,4),                 -- 入库料工费占比·材料（%）= 入库材料 ÷ 入库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtInLab"     DECIMAL(19,4),                 -- 入库料工费占比·人工（%）= 入库人工 ÷ 入库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtInMfg"     DECIMAL(19,4),                 -- 入库料工费占比·制造费用（%）= 入库制造费用 ÷ 入库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtInSub"     DECIMAL(19,4),                 -- 入库料工费占比·委外加工费（%）= 入库委外加工费 ÷ 入库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOutMat"    DECIMAL(19,4),                 -- 出库料工费占比·材料（%）= 出库材料 ÷ 出库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOutLab"    DECIMAL(19,4),                 -- 出库料工费占比·人工（%）= 出库人工 ÷ 出库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOutMfg"    DECIMAL(19,4),                 -- 出库料工费占比·制造费用（%）= 出库制造费用 ÷ 出库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtOutSub"    DECIMAL(19,4),                 -- 出库料工费占比·委外加工费（%）= 出库委外加工费 ÷ 出库四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtEndMat"    DECIMAL(19,4),                 -- 期末料工费占比·材料（%）= 期末材料 ÷ 期末四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtEndLab"    DECIMAL(19,4),                 -- 期末料工费占比·人工（%）= 期末人工 ÷ 期末四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtEndMfg"    DECIMAL(19,4),                 -- 期末料工费占比·制造费用（%）= 期末制造费用 ÷ 期末四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    "RtEndSub"    DECIMAL(19,4),                 -- 期末料工费占比·委外加工费（%）= 期末委外加工费 ÷ 期末四项合计 × 100；四项合计为 0 时为空（P50，用户 2026-10-18）
    PRIMARY KEY ("RunId", "ItemCode")
)

@@
-- @stmt 新框架 11_result_tables.sql #5 补齐 MTC_CA_R_ITEM 缺少的列
DO BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'FcCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("FcCode" NVARCHAR(10), "RunType" NVARCHAR(1), "Scenario" NVARCHAR(30), "RunId" BIGINT)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'ItemCode';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("ItemCode" NVARCHAR(50))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'iLevel';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("iLevel" INT)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'OpenQty';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("OpenQty" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'OpenMat';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("OpenMat" DECIMAL(19,6) DEFAULT 0, "OpenMfg" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'OpenLab';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("OpenLab" DECIMAL(19,6) DEFAULT 0, "OpenSub" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'PMat';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("PMat" DECIMAL(19,6) DEFAULT 0, "PMfg" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'PLab';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("PLab" DECIMAL(19,6) DEFAULT 0, "PSub" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'LastPMat';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("LastPMat" DECIMAL(19,6) DEFAULT 0, "LastPMfg" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'LastPLab';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("LastPLab" DECIMAL(19,6) DEFAULT 0, "LastPSub" DECIMAL(19,6) DEFAULT 0)'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'PriceSrc';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("PriceSrc" NVARCHAR(20))'; END IF;
    SELECT COUNT(*) INTO n FROM SYS.TABLE_COLUMNS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND TABLE_NAME = 'MTC_CA_R_ITEM' AND COLUMN_NAME = 'InQty';
    IF :n = 0 THEN EXEC 'ALTER TABLE "MTC_CA_R_ITEM" ADD ("InQty" DECIMAL(19,6) DEFAULT 0)'; END IF;
