@@
-- @stmt 新框架 12_p30_init.sql #1
-- =====================================================================
-- 新成本框架 第 2 期：P30 初始化与固定价格（设计稿 4、4.1）
-- 替代：0302 Step1001–1009 中与迭代无关的部分、0321_OWOR 的订单汇总、0311 的凭证与重估段。
--
-- 单据行定价类别 Cat（R_LINE.Cat）：
--   FIX     采购收货 / 退货、应付发票 / 贷项差额、库存重估 I11、委外发票差异 APDIF：取 S_LINE.SrcAmt（规则 FIX-01；APDIF 记委外要素）
--   NOCOST  U_CalType=InvntCost 的重估：金额计入期末，不参与加权单价（RVL-01）
--   SRT     有原交货的销售退货：原交货在以前账期的，按原交货单位成本（SRT-01）；原交货在本期的改为 WAVG（与原交货同价）
--   SRTQ    没有原交货的销售退货：期初维护价（SRT-01）；没有维护价的改为 WAVG（SRT-03，PRE-04 警告）
--   CNL     交货 / 退货的取消单：原单为固定价的按原单单位成本反向；否则 WAVG（CNL-01）
--           原单在本期按加权价的，与原单同价相抵，正常；本期找不到原单的才由 POST-05 报出
--   TRF_IN  形态转换入库 I05：= 配对 O05 的金额（迭代中计算，TRF-01）
--   RCPT    订单完工入库：订单本期完工成本按数量分配（WIP-01）
--   ISSUE   订单领料：子件当前单价（WAVG-01）
--   RTN304  生产退料（RETURN_BUSITYPES，默认 304）：该订单该材料的平均领料单价（RTN-01）
--           另外：领料类业务类型（B03）的收货单行、数量为正（把材料退回库存，如 59 + 309 返工退回、302、308）也按退料处理（用户确认 2026-10-30：收货单上用领料类业务类型就是退料）。
--           原来按物料当前单价算负数领料、不计入加权单价；返工单退回的就是本订单的产品时（FH100_COST_TEST #16：MTC_OWOR 512 / 511），
--           产品单价 =（… − 退回数量 × 本身单价 × 结转比例）÷ 本期入库数量，每轮乘 −退回数量 × 比例 ÷ 入库数量（−10 × 0.444 ÷ 3 = −1.48），发散。
--   B1      没有订单的期初生产入库 I90：取 B1 金额（B1-01）
--   WAVG    其余（销售出库、其他出入库、盘点、形态转换出库等）：物料本期加权单价（WAVG-01）
-- InVal='Y' 的行计入物料加权单价的分子分母：FIX、SRT、SRTQ、CNL（固定价）、TRF_IN、RCPT、RTN304、B1。
-- 金额约定：每条单据行定价时四项分别取整到 2 位；订单内部的结转、在产品保留 6 位，完工入库行按订单成本取整后尾差挤最大行。
-- =====================================================================
-- PRE-23 需要维护期初成本价的物料（用户 2026-10-13，替代旧 CAL_1001_CHECK 第 2 项的收集部分；只读，不写 @MTC_COST_QCPRICE）
-- 判断：物料本期有要按单价计价的行（不是带固定金额的行、不是参数 QCP_PRICED_IN 中的入库、不是有原交货的销售退货），
-- 且计算前没有任何价格来源——没有期初结存金额、没有 QCP_PRICED_IN 中的入库（采购、生产 / 委外 / 返工完工、形态转换）、
-- 没有带金额的入库、没有期初维护价。0 金额的采购收货不算来源，加权单价的分母（期初数量 + 计入加权单价的行）要大于 0（MTC_CA_F_QCP_SRC，用户 2026-11-06）。这些物料不维护价格，本期出库会按 0 或按迭代中偶然得到的价格计价（POST-07 事后报出）。
-- 首次出现 = 以前各期的新框架结果、期初承接、旧 0301 和本期期初都没有这个物料；建议价取以前最近一个账期不为 0 的单价，
-- 都没有时取物料主数据最近采购价。结果写 MTC_CA_R_QCP_NEED（只做检查时也保留），PRE-23 明细最多 CHECK_DTL_MAX 行。
-- 部署在 11 之后（读 R_ITEM 历史）；由 MTC_CA_P_RUN、MTC_CA_P_PRECHECK 在 P10 之后调用。
CREATE OR REPLACE PROCEDURE "MTC_CA_P10_QCP" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE pricedIn NVARCHAR(200);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    pricedIn := IFNULL("MTC_CA_F_PARAM"('QCP_PRICED_IN', :fc), ',I01,I03,I05,I07,I08,I09,I90,');

    ln = SELECT "LineId", "ItemCode", IFNULL("TransCode", '') AS "TransCode", "Qty",
                "ObjType", "DocEntry", "DocNum", "LineNum", "DocDate", "BusiType", "WhsCode",
                CASE WHEN "SrcAmt" IS NOT NULL THEN 'N'
                     WHEN LOCATE(:pricedIn, ',' || IFNULL("TransCode", '') || ',') > 0 THEN 'N'
                     WHEN "TransCode" = 'O06' AND "BaseType" = '15' AND "BaseEntry" IS NOT NULL THEN 'N'   -- 与 P30 SRT 同一判断（2026-10-29）
                     ELSE 'Y' END AS "IsNeed"
           FROM "MTC_CA_S_LINE"
          WHERE "RunId" = :RunId AND "Qty" <> 0 AND IFNULL("NoCost", 'N') = 'N';
    fs = SELECT "ItemCode", "HasIn", "IsSrc" FROM "MTC_CA_F_QCP_SRC"(:RunId, :pricedIn);
    src = SELECT "ItemCode" FROM :fs WHERE "IsSrc" = 'Y'
          UNION SELECT "ItemCode" FROM "MTC_CA_S_QCPRICE" WHERE "RunId" = :RunId AND "Price" <> 0;
    need = SELECT X."ItemCode", STRING_AGG(X."TransCode", ',' ORDER BY X."TransCode") AS "NeedTrans", SUM(X."Qty") AS "NeedQty"
             FROM (SELECT "ItemCode", "TransCode", SUM(ABS("Qty")) AS "Qty" FROM :ln
                    WHERE "IsNeed" = 'Y' AND "ItemCode" NOT IN (SELECT "ItemCode" FROM :src)
                    GROUP BY "ItemCode", "TransCode") X
            GROUP BY X."ItemCode";

    -- 以前出现过（不论有没有价格）与以前的单价
    seen = SELECT "ItemCode", "FcCode" FROM "MTC_CA_R_ITEM"
            WHERE "RunType" = 'F' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
           UNION ALL
           SELECT "ItemCode", "FcCode" FROM "MTC_CA_BOOT_ITEM"
            WHERE "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
           UNION ALL
           SELECT "ItemCode", "FcCode" FROM "MTC_COST_0301_INVNT"
            WHERE "CostCode" = '20' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
           UNION ALL
           SELECT "ItemCode", :fc FROM "MTC_CA_S_OPEN" WHERE "RunId" = :RunId AND "ItemCode" IN (SELECT "ItemCode" FROM :need);
    hist = SELECT "ItemCode", "FcCode", "Price", "Src", "Pri" FROM (
               SELECT "ItemCode", "FcCode", "PMat" + "PMfg" + "PLab" + "PSub" AS "Price", 'NEW' AS "Src", 1 AS "Pri"
                 FROM "MTC_CA_R_ITEM" WHERE "RunType" = 'F' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
               UNION ALL
               SELECT "ItemCode", "FcCode", "Price", 'OLD', 2
                 FROM "MTC_COST_0301_INVNT" WHERE "CostCode" = '20' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
               UNION ALL
               SELECT "ItemCode", "FcCode", "Amount" / NULLIF("Qty", 0), 'BOOT', 3
                 FROM "MTC_CA_BOOT_ITEM" WHERE "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need))
            WHERE IFNULL("Price", 0) > 0;
    sugg = SELECT "ItemCode", "FcCode", "Price", "Src"
             FROM (SELECT H.*, ROW_NUMBER() OVER (PARTITION BY "ItemCode" ORDER BY "FcCode" DESC, "Pri") AS "Rn" FROM :hist H)
            WHERE "Rn" = 1;

    -- 来源单据行和按交易类型的单号清单（用户 2026-10-30：清单和 B1 行备注里要看得出这个物料为什么要维护）
    INSERT INTO "MTC_CA_R_QCP_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "ItemCode", "ObjType", "DocEntry", "DocNum",
                                     "LineNum", "DocDate", "TransCode", "BusiType", "WhsCode", "Qty")
    SELECT :fc, :rt, :scen, :RunId, "LineId", "ItemCode", "ObjType", "DocEntry", "DocNum", "LineNum", "DocDate", "TransCode", "BusiType", "WhsCode", "Qty"
      FROM :ln WHERE "IsNeed" = 'Y' AND "ItemCode" IN (SELECT "ItemCode" FROM :need);
    dt = SELECT "ItemCode", "TransCode", "ObjType", IFNULL("DocNum", 'Entry ' || "DocEntry") AS "DocNum", MIN("DocDate") AS "DocDate"
           FROM :ln WHERE "IsNeed" = 'Y' AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
          GROUP BY "ItemCode", "TransCode", "ObjType", IFNULL("DocNum", 'Entry ' || "DocEntry");
    dt2 = SELECT "ItemCode", "TransCode", "DocNum",
                 ROW_NUMBER() OVER (PARTITION BY "ItemCode", "TransCode" ORDER BY "DocDate", "DocNum") AS "Rn",
                 COUNT(*) OVER (PARTITION BY "ItemCode", "TransCode") AS "Cnt"
            FROM :dt;
    tx = SELECT X."ItemCode", X."TransCode", IFNULL(T."Name", '') AS "TransName", MAX(X."Cnt") AS "Cnt",
                STRING_AGG(X."DocNum", '、' ORDER BY X."Rn") AS "Docs"
           FROM :dt2 X LEFT JOIN "@MTC_COST_IOTYPE" T ON T."Code" = X."TransCode"
          WHERE X."Rn" <= 10
          GROUP BY X."ItemCode", X."TransCode", IFNULL(T."Name", '');
    nd = SELECT "ItemCode",
                STRING_AGG(CASE WHEN "TransCode" = '' THEN '交易类型识别不了' ELSE "TransCode" || ' ' || "TransName" END, '、' ORDER BY "TransCode") AS "Names",
                STRING_AGG(CASE WHEN "TransCode" = '' THEN '交易类型识别不了' ELSE "TransCode" || ' ' || "TransName" END
                           || ' ' || "Cnt" || ' 张（单号 Num ' || "Docs" || CASE WHEN "Cnt" > 10 THEN ' 等' ELSE '' END || '）', '；' ORDER BY "TransCode") AS "Docs"
           FROM :tx GROUP BY "ItemCode";

    INSERT INTO "MTC_CA_R_QCP_NEED" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "ItemName", "ItmsGrpCod", "iLevel",
                                     "FirstSeen", "LastFc", "NeedTrans", "NeedQty", "SuggPrice", "SuggSrc", "SuggFc", "Reason", "NeedDocs")
    SELECT :fc, :rt, :scen, :RunId, N."ItemCode", I."ItemName", I."ItmsGrpCod", I."iLevel",
           CASE WHEN S."LastFc" IS NULL THEN 'Y' ELSE 'N' END, S."LastFc", LEFT(N."NeedTrans", 500), N."NeedQty",
           CASE WHEN G."Price" IS NOT NULL THEN G."Price" WHEN IFNULL(M."LastPurPrc", 0) > 0 THEN M."LastPurPrc" END,
           CASE WHEN G."Price" IS NOT NULL THEN G."Src" WHEN IFNULL(M."LastPurPrc", 0) > 0 THEN 'LASTPUR' END,
           G."FcCode",
           LEFT(CASE WHEN S."LastFc" IS NULL THEN '首次出现（以前各期和本期期初都没有这个物料）'
                     ELSE '以前出现过（最近 ' || S."LastFc" || '），本期期初没有结存金额' END
                || '；本期有 ' || IFNULL(D."Names", N."NeedTrans") || ' 要按单价计价'
                || CASE WHEN H."ItemCode" IS NOT NULL THEN '，本期的采购 / 完工入库给不出单价（金额为 0 或已退回），也没有期初维护价'
                        ELSE '，计算前没有采购 / 完工 / 形态转换入库，也没有期初维护价' END, 500),
           LEFT(D."Docs", 1000)
      FROM :need N
      LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = N."ItemCode"
      LEFT JOIN (SELECT "ItemCode", MAX("FcCode") AS "LastFc" FROM :seen GROUP BY "ItemCode") S ON S."ItemCode" = N."ItemCode"
      LEFT JOIN :sugg G ON G."ItemCode" = N."ItemCode"
      LEFT JOIN :nd D ON D."ItemCode" = N."ItemCode"
      LEFT JOIN (SELECT "ItemCode" FROM :fs WHERE "HasIn" = 'Y') H ON H."ItemCode" = N."ItemCode"
      LEFT JOIN "OITM" M ON M."ItemCode" = N."ItemCode";
    RowCnt := ::ROWCOUNT;

    t23 = SELECT "ItemCode" AS "KeyCode",
                 IFNULL("Reason", '') || '；'
                 || CASE WHEN "SuggPrice" IS NULL THEN '没有可参考的价格'
                         ELSE '建议价 ' || TO_NVARCHAR(ROUND("SuggPrice", 6)) || '（'
                              || MAP("SuggSrc", 'NEW', IFNULL("SuggFc", '') || ' 新框架期末单价', 'OLD', IFNULL("SuggFc", '') || ' 旧框架单价',
                                     'BOOT', IFNULL("SuggFc", '') || ' 期初承接', 'LASTPUR', '物料主数据最近采购价', "SuggSrc") || '）' END
                 || IFNULL('；单据：' || "NeedDocs", '') AS "Info"
            FROM "MTC_CA_R_QCP_NEED" WHERE "RunId" = :RunId;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'PRE-23', :t23, CASE WHEN :RowCnt > 0 THEN :RowCnt || ' 个物料，完整清单见执行台“期初价维护”页（MTC_CA_R_QCP_NEED）' END);
END

@@
-- @stmt 新框架 12_p30_init.sql #2
-- PRE-14 按物料汇总：需要维护工时的产品（用户 2026-10-29：要快速拿到清单去 B1 工时单维护；只读，不写 @MTC_COST_TIME）
-- 口径同 PRE-14（本期有入库、在费用池分摊范围内的订单，产品没有工时或工时为 0），按产品一行；参考工时取以前最近一个账期
-- 工时单里不为 0 的单位工时。PRE-14 是阻断项，阻断时不进 P30，所以清单写结果表 MTC_CA_R_HOURS_NEED（只做检查和阻断时都保留）。
-- 部署在 11 之后；由 MTC_CA_P_RUN、MTC_CA_P_PRECHECK 在 P10 之后调用。
CREATE OR REPLACE PROCEDURE "MTC_CA_P10_HOURS" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);

    ord = SELECT DISTINCT O."ItemCode", O."OrderType", O."OrderEntry", O."OrderNum", O."RecvQty", T."PoolCode"
            FROM "MTC_CA_S_ORDER" O
            JOIN "MTC_CA_V_ITEM_POOL" T ON T."RunId" = :RunId AND T."ItemCode" = O."ItemCode"
                                       AND LOCATE(T."WorTypes", ',' || O."WorType" || ',') > 0
            LEFT JOIN "MTC_CA_S_HOURS" H ON H."RunId" = :RunId AND H."ItemCode" = O."ItemCode"
           WHERE O."RunId" = :RunId AND O."RecvQty" > 0 AND IFNULL(H."Hours", 0) = 0;
    agg = SELECT "ItemCode", COUNT(*) AS "OrderCnt", SUM("RecvQty") AS "RecvQty"
            FROM (SELECT DISTINCT "ItemCode", "OrderType", "OrderEntry", "RecvQty" FROM :ord)
           GROUP BY "ItemCode";
    pools = SELECT X."ItemCode", STRING_AGG(X."PoolCode", ',' ORDER BY X."PoolCode") AS "Pools",
                   STRING_AGG(X."PoolCode" || IFNULL(' ' || C."PoolName", ''), '、' ORDER BY X."PoolCode") AS "PoolNames"
              FROM (SELECT DISTINCT "ItemCode", "PoolCode" FROM :ord) X
              LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = X."PoolCode"
             GROUP BY X."ItemCode";
    -- 本期有入库的订单清单（用户 2026-10-30：工时单行备注写明哪些订单、哪个费用池）
    od = SELECT "ItemCode", "OrderType", "OrderEntry", "OrderNum", "RecvQty",
                ROW_NUMBER() OVER (PARTITION BY "ItemCode" ORDER BY "OrderType", "OrderEntry") AS "Rn"
           FROM (SELECT DISTINCT "ItemCode", "OrderType", "OrderEntry", "OrderNum", "RecvQty" FROM :ord);
    ods = SELECT "ItemCode",
                 STRING_AGG(MAP("OrderType", '202', '生产订单', 'MTC_OWOR', '返工单', "OrderType") || ' Num ' || IFNULL("OrderNum", 'Entry ' || "OrderEntry")
                            || '（入库 ' || TO_NVARCHAR(TO_DECIMAL(ROUND("RecvQty", 2), 19, 2)) || '）', '、' ORDER BY "Rn") AS "Orders"
            FROM :od WHERE "Rn" <= 15 GROUP BY "ItemCode";
    ref = SELECT "ItemCode", "RefFc", "RefHours"
            FROM (SELECT T1."U_ItemCode" AS "ItemCode", T0."U_FcCode" AS "RefFc", MAX(T1."U_Time") AS "RefHours",
                         ROW_NUMBER() OVER (PARTITION BY T1."U_ItemCode" ORDER BY T0."U_FcCode" DESC) AS "Rn"
                    FROM "@MTC_COST_TIME" T0 JOIN "@MTC_COST_TIME1" T1 ON T1."DocEntry" = T0."DocEntry"
                   WHERE IFNULL(T0."Canceled", 'N') = 'N' AND T0."U_FcCode" < :fc AND T1."U_Time" > 0
                     AND T1."U_ItemCode" IN (SELECT "ItemCode" FROM :agg)
                   GROUP BY T1."U_ItemCode", T0."U_FcCode")
           WHERE "Rn" = 1;

    INSERT INTO "MTC_CA_R_HOURS_NEED" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "ItemName", "ItmsGrpCod",
                                       "Pools", "OrderCnt", "RecvQty", "CurHours", "RefHours", "RefFc", "PoolNames", "NeedOrders")
    SELECT :fc, :rt, :scen, :RunId, A."ItemCode", I."ItemName", I."ItmsGrpCod",
           LEFT(P."Pools", 500), A."OrderCnt", A."RecvQty", H."Hours", R."RefHours", R."RefFc",
           LEFT(P."PoolNames", 500), LEFT(D."Orders" || CASE WHEN A."OrderCnt" > 15 THEN ' 等 ' || A."OrderCnt" || ' 张' ELSE '' END, 1000)
      FROM :agg A
      LEFT JOIN :ods D ON D."ItemCode" = A."ItemCode"
      LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = A."ItemCode"
      LEFT JOIN :pools P ON P."ItemCode" = A."ItemCode"
      LEFT JOIN "MTC_CA_S_HOURS" H ON H."RunId" = :RunId AND H."ItemCode" = A."ItemCode"
      LEFT JOIN :ref R ON R."ItemCode" = A."ItemCode";
    RowCnt := ::ROWCOUNT;

    IF :RowCnt > 0 THEN
        UPDATE "MTC_CA_R_CHECK" SET "Msg" = :RowCnt || ' 个产品，按物料汇总的清单见执行台“工时维护”页（MTC_CA_R_HOURS_NEED）'
         WHERE "RunId" = :RunId AND "CheckId" = 'PRE-14' AND "Msg" IS NULL;
    END IF;
END

@@
-- @stmt 新框架 12_p30_init.sql #3
CREATE OR REPLACE PROCEDURE "MTC_CA_P30_INIT" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE maxLv INT;
    DECLARE defPool NVARCHAR(20);
    DECLARE boot NVARCHAR(10);
    DECLARE rtnBt NVARCHAR(500);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    rtnBt := IFNULL("MTC_CA_F_PARAM"('RETURN_BUSITYPES', :fc), ',304,');   -- 生产退料的业务类型（参数，2026-10-27）
    SELECT MAX("PoolCode") INTO defPool FROM "MTC_CA_C_POOL" WHERE "IsDefault" = 'Y';
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :fc);

    -- 1. 单据行与定价类别
    INSERT INTO "MTC_CA_R_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "ItemCode", "TransCode", "Qty", "Cat",
                                 "OrderType", "OrderEntry", "IsShared", "PoolCode", "RuleId")
    SELECT :fc, :rt, :scen, :RunId, L."LineId", L."ItemCode", L."TransCode", L."Qty",
           CASE WHEN L."NoCost" = 'Y' THEN 'NOCOST'
                WHEN L."Src" IN ('OMRV', 'APDIF') OR L."ObjType" IN ('20', '21', '18', '19') THEN 'FIX'
                WHEN L."TransCode" = 'I05' THEN 'TRF_IN'
                WHEN L."Canceled" = 'C' AND L."ObjType" IN ('15', '16') THEN 'CNL'
                WHEN L."TransCode" = 'O06' AND L."BaseType" = '15' AND L."BaseEntry" IS NOT NULL THEN 'SRT'
                WHEN L."TransCode" = 'O06' THEN 'SRTQ'
                WHEN L."BusiClass" = 'B01' AND L."OrderEntry" IS NOT NULL AND L."OrderLine" IS NULL THEN 'RCPT'
                WHEN (LOCATE(:rtnBt, ',' || L."BusiType" || ',') > 0 OR (L."BusiClass" = 'B03' AND L."Qty" > 0))
                     AND L."OrderEntry" IS NOT NULL THEN 'RTN304'
                WHEN L."BusiClass" = 'B03' AND L."OrderEntry" IS NOT NULL THEN 'ISSUE'
                WHEN L."TransCode" = 'I90' THEN 'B1'
                ELSE 'WAVG' END,
           L."OrderType", L."OrderEntry", L."SharedExp",
           CASE WHEN L."SharedExp" = 'Y' THEN IFNULL(PS."PoolCode", :defPool) END,
           NULL
      FROM "MTC_CA_S_LINE" L
      LEFT JOIN "MTC_CA_C_POOL_SRC" PS ON PS."OcrCode" = L."OcrCode" AND :fc BETWEEN PS."FromFc" AND PS."ToFc"
     WHERE L."RunId" = :RunId;
    RowCnt := ::ROWCOUNT;

    -- 2. 固定价格
    UPDATE T0 SET T0."MatAmt" = CASE WHEN S."Src" = 'APDIF' THEN 0 ELSE ROUND(IFNULL(S."SrcAmt", 0), 2) END,
                  T0."SubAmt" = CASE WHEN S."Src" = 'APDIF' THEN ROUND(IFNULL(S."SrcAmt", 0), 2) ELSE 0 END,
                  T0."Amount" = ROUND(IFNULL(S."SrcAmt", 0), 2),
                  T0."PriceSrc" = CASE WHEN T0."Cat" = 'NOCOST' THEN '重估（InvntCost，只调整结存）'
                                       WHEN S."Src" = 'APDIF' THEN '委外加工费发票差异（发票 − 暂估）' ELSE '来源金额' END,
                  T0."RuleId" = CASE WHEN T0."Cat" = 'NOCOST' THEN 'RVL-01' ELSE 'FIX-01' END
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_S_LINE" S ON S."RunId" = T0."RunId" AND S."LineId" = T0."LineId"
     WHERE T0."RunId" = :RunId AND T0."Cat" IN ('FIX', 'NOCOST');

    UPDATE T0 SET T0."MatAmt" = ROUND(IFNULL(S."B1Amt", 0), 2), T0."Amount" = ROUND(IFNULL(S."B1Amt", 0), 2),
                  T0."PriceSrc" = '没有订单的期初生产入库，取 B1 金额', T0."RuleId" = 'B1-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_S_LINE" S ON S."RunId" = T0."RunId" AND S."LineId" = T0."LineId"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'B1';

    UPDATE T0 SET T0."MatAmt" = ROUND(Q."Price" * T0."Qty", 2), T0."Amount" = ROUND(Q."Price" * T0."Qty", 2),
                  T0."PriceSrc" = '没有原交货，按期初维护价', T0."RuleId" = 'SRT-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_S_QCPRICE" Q ON Q."RunId" = T0."RunId" AND Q."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'SRTQ';
    UPDATE T0 SET T0."Cat" = 'WAVG', T0."PriceSrc" = '没有原交货，也没有期初维护价，按本期加权价', T0."RuleId" = 'SRT-03'
      FROM "MTC_CA_R_LINE" T0
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'SRTQ'
       AND NOT EXISTS (SELECT 1 FROM "MTC_CA_S_QCPRICE" Q WHERE Q."RunId" = T0."RunId" AND Q."ItemCode" = T0."ItemCode");

    -- 3. 销售退货配对：原交货在本期 → WAVG；在以前账期 → 新框架当期结果，2026-08 及以前取旧 0302；都没有 → WAVG 并标注
    srt = SELECT T0."LineId", S."BaseEntry", S."BaseLine"
            FROM "MTC_CA_R_LINE" T0
            JOIN "MTC_CA_S_LINE" S ON S."RunId" = T0."RunId" AND S."LineId" = T0."LineId"
           WHERE T0."RunId" = :RunId AND T0."Cat" = 'SRT';
    same = SELECT R."LineId", MIN(O."LineId") AS "SrcLineId"
             FROM :srt R
             JOIN "MTC_CA_S_LINE" O ON O."RunId" = :RunId AND O."ObjType" = '15'
                                   AND TO_NVARCHAR(O."DocEntry") = R."BaseEntry" AND TO_NVARCHAR(O."LineNum") = R."BaseLine"
            GROUP BY R."LineId";
    prevNew = SELECT R."LineId", S."FcCode",
                     SUM(L."MatAmt") / NULLIF(SUM(L."Qty"), 0) AS "UMat", SUM(L."MfgAmt") / NULLIF(SUM(L."Qty"), 0) AS "UMfg",
                     SUM(L."LabAmt") / NULLIF(SUM(L."Qty"), 0) AS "ULab", SUM(L."SubAmt") / NULLIF(SUM(L."Qty"), 0) AS "USub"
                FROM :srt R
                JOIN "MTC_CA_S_LINE" S ON S."ObjType" = '15' AND TO_NVARCHAR(S."DocEntry") = R."BaseEntry"
                                      AND TO_NVARCHAR(S."LineNum") = R."BaseLine" AND S."FcCode" < :fc
                JOIN "MTC_CA_RUN" U ON U."RunId" = S."RunId" AND U."Status" = 'OK' AND U."RunType" = 'F'
                JOIN "MTC_CA_R_LINE" L ON L."RunId" = S."RunId" AND L."LineId" = S."LineId"
               WHERE R."LineId" NOT IN (SELECT "LineId" FROM :same)
               GROUP BY R."LineId", S."FcCode";
    prevOld = SELECT R."LineId", MAX(O."FcCode") AS "FcCode",
                     SUM(O."Amount") / NULLIF(SUM(O."Quantity"), 0) AS "UMat"
                FROM :srt R
                JOIN "MTC_COST_0302_INVNTDETAIL1" O ON O."ObjType" = '15' AND TO_NVARCHAR(O."DocEntry") = R."BaseEntry"
                                                   AND TO_NVARCHAR(O."LineNum") = R."BaseLine" AND O."FcCode" <= :boot
               WHERE R."LineId" NOT IN (SELECT "LineId" FROM :same)
                 AND R."LineId" NOT IN (SELECT "LineId" FROM :prevNew)
               GROUP BY R."LineId";

    INSERT INTO "MTC_CA_R_PAIR" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "PairType", "SrcLineId", "SrcFc", "SrcTable",
                                 "UMat", "UMfg", "ULab", "USub", "Note")
    SELECT :fc, :rt, :scen, :RunId, "LineId", 'SRT', "SrcLineId", :fc, 'MTC_CA_S_LINE', NULL, NULL, NULL, NULL,
           '原交货在本期，按本期加权价（与原交货同价）'
      FROM :same
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, P."LineId", 'SRT', NULL, P."FcCode", 'MTC_CA_R_LINE', P."UMat", P."UMfg", P."ULab", P."USub",
           '原交货在 ' || P."FcCode" || '，取新框架当期成本'
      FROM (SELECT X.*, ROW_NUMBER() OVER (PARTITION BY X."LineId" ORDER BY X."FcCode" DESC) AS "Rn" FROM :prevNew X) P
     WHERE P."Rn" = 1
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, "LineId", 'SRT', NULL, "FcCode", 'MTC_COST_0302_INVNTDETAIL1', "UMat", 0, 0, 0,
           '原交货在 ' || "FcCode" || '，取旧框架成本（全部记材料）'
      FROM :prevOld;

    UPDATE T0 SET T0."Cat" = 'WAVG', T0."PriceSrc" = P."Note", T0."RuleId" = 'SRT-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_PAIR" P ON P."RunId" = T0."RunId" AND P."LineId" = T0."LineId" AND P."SrcLineId" IS NOT NULL
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'SRT';
    UPDATE T0 SET T0."MatAmt" = ROUND(IFNULL(P."UMat", 0) * T0."Qty", 2), T0."MfgAmt" = ROUND(IFNULL(P."UMfg", 0) * T0."Qty", 2),
                  T0."LabAmt" = ROUND(IFNULL(P."ULab", 0) * T0."Qty", 2), T0."SubAmt" = ROUND(IFNULL(P."USub", 0) * T0."Qty", 2),
                  T0."Amount" = ROUND(IFNULL(P."UMat", 0) * T0."Qty", 2) + ROUND(IFNULL(P."UMfg", 0) * T0."Qty", 2)
                              + ROUND(IFNULL(P."ULab", 0) * T0."Qty", 2) + ROUND(IFNULL(P."USub", 0) * T0."Qty", 2),
                  T0."PriceSrc" = P."Note", T0."RuleId" = 'SRT-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_PAIR" P ON P."RunId" = T0."RunId" AND P."LineId" = T0."LineId" AND P."SrcLineId" IS NULL
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'SRT';
    UPDATE "MTC_CA_R_LINE" SET "Cat" = 'WAVG', "PriceSrc" = '找不到原交货成本，按本期加权价', "RuleId" = 'SRT-02'
     WHERE "RunId" = :RunId AND "Cat" = 'SRT'
       AND "LineId" NOT IN (SELECT "LineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId);

    -- 4. 交货 / 退货的取消单：原单在本期且为固定价 → 按原单单位成本；否则 WAVG
    cnl = SELECT T0."LineId", MIN(O."LineId") AS "SrcLineId"
            FROM "MTC_CA_R_LINE" T0
            JOIN "MTC_CA_S_LINE" S ON S."RunId" = T0."RunId" AND S."LineId" = T0."LineId"
            JOIN "MTC_CA_S_LINE" O ON O."RunId" = :RunId AND O."ObjType" = S."ObjType"
                                  AND TO_NVARCHAR(O."DocEntry") = S."BaseEntry" AND TO_NVARCHAR(O."LineNum") = S."BaseLine"
                                  AND O."ItemCode" = S."ItemCode"
           WHERE T0."RunId" = :RunId AND T0."Cat" = 'CNL'
           GROUP BY T0."LineId";
    INSERT INTO "MTC_CA_R_PAIR" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "PairType", "SrcLineId", "SrcFc", "SrcTable",
                                 "UMat", "UMfg", "ULab", "USub", "Note")
    SELECT :fc, :rt, :scen, :RunId, C."LineId", 'CNL', C."SrcLineId", :fc, 'MTC_CA_S_LINE',
           O."MatAmt" / NULLIF(O."Qty", 0), O."MfgAmt" / NULLIF(O."Qty", 0), O."LabAmt" / NULLIF(O."Qty", 0), O."SubAmt" / NULLIF(O."Qty", 0),
           '取消原单（本期，固定价）'
      FROM :cnl C
      JOIN "MTC_CA_R_LINE" O ON O."RunId" = :RunId AND O."LineId" = C."SrcLineId"
     WHERE O."Cat" IN ('FIX', 'SRT', 'SRTQ');
    UPDATE T0 SET T0."MatAmt" = ROUND(IFNULL(P."UMat", 0) * T0."Qty", 2), T0."MfgAmt" = ROUND(IFNULL(P."UMfg", 0) * T0."Qty", 2),
                  T0."LabAmt" = ROUND(IFNULL(P."ULab", 0) * T0."Qty", 2), T0."SubAmt" = ROUND(IFNULL(P."USub", 0) * T0."Qty", 2),
                  T0."Amount" = ROUND(IFNULL(P."UMat", 0) * T0."Qty", 2) + ROUND(IFNULL(P."UMfg", 0) * T0."Qty", 2)
                              + ROUND(IFNULL(P."ULab", 0) * T0."Qty", 2) + ROUND(IFNULL(P."USub", 0) * T0."Qty", 2),
                  T0."PriceSrc" = P."Note", T0."RuleId" = 'CNL-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_PAIR" P ON P."RunId" = T0."RunId" AND P."LineId" = T0."LineId"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'CNL';
    -- 原单在本期、按加权价（普通交货）：取消单与原单同一个本期加权单价，金额正好相抵，不是异常（2026-10-14）
    UPDATE "MTC_CA_R_LINE" SET "Cat" = 'WAVG', "PriceSrc" = '取消单：原单在本期、按加权价，与原单同价相抵', "RuleId" = 'CNL-01'
     WHERE "RunId" = :RunId AND "Cat" = 'CNL'
       AND "LineId" NOT IN (SELECT "LineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId)
       AND "LineId" IN (SELECT "LineId" FROM :cnl);
    UPDATE "MTC_CA_R_LINE" SET "Cat" = 'WAVG', "PriceSrc" = '取消单：本期找不到原单，按本期加权价', "RuleId" = 'CNL-01'
     WHERE "RunId" = :RunId AND "Cat" = 'CNL'
       AND "LineId" NOT IN (SELECT "LineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId);

    -- 5. 形态转换配对：I05 ↔ 同配对键、同取消状态的 O05，必须正好一行；否则 WAVG 并标注
    trf = SELECT I."LineId", MAX(O."LineId") AS "SrcLineId", COUNT(*) AS "Cnt"
            FROM "MTC_CA_S_LINE" I
            JOIN "MTC_CA_S_LINE" O ON O."RunId" = I."RunId" AND O."TransCode" = 'O05' AND O."PairKey" = I."PairKey"
                                  AND IFNULL(O."Canceled", 'N') = IFNULL(I."Canceled", 'N')
           WHERE I."RunId" = :RunId AND I."TransCode" = 'I05'
           GROUP BY I."LineId";
    INSERT INTO "MTC_CA_R_PAIR" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "PairType", "SrcLineId", "SrcFc", "SrcTable", "Note")
    SELECT :fc, :rt, :scen, :RunId, "LineId", 'TRF', "SrcLineId", :fc, 'MTC_CA_S_LINE', '形态转换：A 入库 = B 出库'
      FROM :trf WHERE "Cnt" = 1;
    UPDATE "MTC_CA_R_LINE" SET "Cat" = 'WAVG', "PriceSrc" = '形态转换配不上唯一的转出行，按本期加权价', "RuleId" = 'TRF-01'
     WHERE "RunId" = :RunId AND "Cat" = 'TRF_IN'
       AND "LineId" NOT IN (SELECT "LineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId AND "PairType" = 'TRF');

    UPDATE "MTC_CA_R_LINE" SET "InVal" = 'Y'
     WHERE "RunId" = :RunId AND "Cat" IN ('FIX', 'SRT', 'SRTQ', 'CNL', 'TRF_IN', 'RCPT', 'RTN304', 'B1');

    -- 6. 物料：有变动、有期初或是订单产品的物料；层级 -1 / 无层级的放在最高层之后
    SELECT IFNULL(MAX("iLevel"), 0) INTO maxLv FROM "MTC_CA_S_ITEM" WHERE "RunId" = :RunId;
    INSERT INTO "MTC_CA_R_ITEM" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "iLevel",
                                 "OpenQty", "OpenMat", "OpenMfg", "OpenLab", "OpenSub", "PMat", "PMfg", "PLab", "PSub", "PriceSrc")
    SELECT :fc, :rt, :scen, :RunId, K."ItemCode",
           CASE WHEN IFNULL(I."iLevel", -1) < 0 THEN :maxLv + 1 ELSE I."iLevel" END,
           IFNULL(O."Qty", 0), IFNULL(O."MatAmt", 0), IFNULL(O."MfgAmt", 0), IFNULL(O."LabAmt", 0), IFNULL(O."SubAmt", 0),
           -- 第 1 轮初值：期初维护价；没有则上期期末单价；都没有为 0
           CASE WHEN Q."ItemCode" IS NOT NULL THEN Q."Price" WHEN O."Qty" > 0 THEN O."MatAmt" / O."Qty" ELSE 0 END,
           CASE WHEN Q."ItemCode" IS NULL AND O."Qty" > 0 THEN O."MfgAmt" / O."Qty" ELSE 0 END,
           CASE WHEN Q."ItemCode" IS NULL AND O."Qty" > 0 THEN O."LabAmt" / O."Qty" ELSE 0 END,
           CASE WHEN Q."ItemCode" IS NULL AND O."Qty" > 0 THEN O."SubAmt" / O."Qty" ELSE 0 END,
           CASE WHEN Q."ItemCode" IS NOT NULL THEN 'QCPRICE' WHEN O."Qty" > 0 THEN 'OPEN' ELSE 'ZERO' END
      FROM (SELECT "ItemCode" FROM "MTC_CA_S_LINE" WHERE "RunId" = :RunId
            UNION SELECT "ItemCode" FROM "MTC_CA_S_OPEN" WHERE "RunId" = :RunId
            UNION SELECT "ItemCode" FROM "MTC_CA_S_ORDER" WHERE "RunId" = :RunId AND "ItemCode" IS NOT NULL) K
      LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = K."ItemCode"
      LEFT JOIN "MTC_CA_S_OPEN" O ON O."RunId" = :RunId AND O."ItemCode" = K."ItemCode"
      LEFT JOIN "MTC_CA_S_QCPRICE" Q ON Q."RunId" = :RunId AND Q."ItemCode" = K."ItemCode";

    -- 7. 订单：结转比例 r = min(累计入库 ÷ 计划, 1)，本期无入库为空（S5）；R_ORDER.ClosedInFc = 截至期末已关闭（含以前账期关闭的，Q35）
    INSERT INTO "MTC_CA_R_ORDER" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "WorType", "ItemCode", "iLevel",
                                  "PlannedQty", "PrevRecvQty", "RecvQty", "Ratio", "ClosedInFc")
    SELECT :fc, :rt, :scen, :RunId, O."OrderType", O."OrderEntry", O."WorType", O."ItemCode",
           IFNULL(I."iLevel", :maxLv + 1), O."PlannedQty", O."PrevRecvQty", O."RecvQty",
           CASE WHEN O."RecvQty" = 0 THEN NULL
                WHEN IFNULL(O."PlannedQty", 0) <= 0 THEN 1
                ELSE LEAST(GREATEST((O."PrevRecvQty" + O."RecvQty") / O."PlannedQty", 0), 1) END,
           -- 按关单处理（期末在产品转关单差异）：本期关闭，或以前账期已关闭、本期仍有单据挂上来的（如加工费退货，Q35，用户 2026-10-17）
           CASE WHEN O."ClosedInFc" = 'Y' OR O."StatusAtEnd" = 'CLOSED' THEN 'Y' ELSE 'N' END
      FROM "MTC_CA_S_ORDER" O
      LEFT JOIN "MTC_CA_R_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = O."ItemCode"
     WHERE O."RunId" = :RunId;

    -- 8. 订单 × 材料：期初累计 + 本期领料行；委外加工费作为 '#SUBFEE' 行
    INSERT INTO "MTC_CA_R_ORDER_MAT" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "ItemCode",
                                      "OpenIssQty", "OpenIssMat", "OpenIssMfg", "OpenIssLab", "OpenIssSub",
                                      "OpenCarMat", "OpenCarMfg", "OpenCarLab", "OpenCarSub", "IssQty", "IssSub")
    SELECT :fc, :rt, :scen, :RunId, K."OrderType", K."OrderEntry", K."ItemCode",
           IFNULL(P."CumIssueQty", 0), IFNULL(P."CumIssueMat", 0), IFNULL(P."CumIssueMfg", 0), IFNULL(P."CumIssueLab", 0), IFNULL(P."CumIssueSub", 0),
           IFNULL(P."CumCarriedMat", 0), IFNULL(P."CumCarriedMfg", 0), IFNULL(P."CumCarriedLab", 0), IFNULL(P."CumCarriedSub", 0),
           IFNULL(L."Qty", 0), IFNULL(F."Amount", 0)
      FROM (SELECT "OrderType", "OrderEntry", "ItemCode" FROM "MTC_CA_S_ORDER_OPEN" WHERE "RunId" = :RunId
            UNION
            SELECT "OrderType", "OrderEntry", "ItemCode" FROM "MTC_CA_R_LINE"
             WHERE "RunId" = :RunId AND "Cat" IN ('ISSUE', 'RTN304')
            UNION
            SELECT "OrderType", "OrderEntry", '#SUBFEE' FROM "MTC_CA_S_SUBFEE"
             WHERE "RunId" = :RunId AND "OrderEntry" IS NOT NULL) K
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
      LEFT JOIN "MTC_CA_S_ORDER_OPEN" P ON P."RunId" = :RunId AND P."OrderType" = K."OrderType"
                                       AND P."OrderEntry" = K."OrderEntry" AND P."ItemCode" = K."ItemCode"
      LEFT JOIN (SELECT "OrderType", "OrderEntry", "ItemCode", -SUM("Qty") AS "Qty" FROM "MTC_CA_R_LINE"
                  WHERE "RunId" = :RunId AND "Cat" IN ('ISSUE', 'RTN304')
                  GROUP BY "OrderType", "OrderEntry", "ItemCode") L
        ON L."OrderType" = K."OrderType" AND L."OrderEntry" = K."OrderEntry" AND L."ItemCode" = K."ItemCode"
      LEFT JOIN (SELECT "OrderType", "OrderEntry", SUM("Amount") AS "Amount" FROM "MTC_CA_S_SUBFEE"
                  WHERE "RunId" = :RunId AND "OrderEntry" IS NOT NULL GROUP BY "OrderType", "OrderEntry") F
        ON K."ItemCode" = '#SUBFEE' AND F."OrderType" = K."OrderType" AND F."OrderEntry" = K."OrderEntry";

    -- 8b. 订单 × 材料的结转比例（用户 2026-10-30）：订单比例 r 按“累计入库 ÷ 计划”，有退料时净领料少于计划，按 r 结转会少结转、
    --     甚至本期结转为负（2026-10 返工单 MTC_OWOR 512：领 18 退 10、累计入库 8 = 计划 18 的 0.444，本期材料结转约 −5271.67）。
    --     改为按净领料数量：max(r, 累计入库 × 该材料计划用量 ÷ 订单计划数 ÷ 净领料数量)，最高 1。
    --     超领（净领料多于所需）时第二项小于 r，仍按 r，与原来一致；没有计划行、订单计划数 ≤ 0、净领料 ≤ 0 时用 r；加工费为 1
    UPDATE T0 SET T0."Ratio" =
           CASE WHEN O."RecvQty" = 0 THEN NULL
                WHEN T0."ItemCode" = '#SUBFEE' THEN 1
                WHEN IFNULL(PL."Qty", 0) > 0 AND IFNULL(O."PlannedQty", 0) > 0 AND T0."OpenIssQty" + T0."IssQty" > 0
                THEN LEAST(GREATEST(O."Ratio",
                                    (O."PrevRecvQty" + O."RecvQty") * PL."Qty" / O."PlannedQty" / (T0."OpenIssQty" + T0."IssQty")), 1)
                ELSE O."Ratio" END
      FROM "MTC_CA_R_ORDER_MAT" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
      LEFT JOIN (SELECT "OrderType", "OrderEntry", "ItemCode", SUM("PlannedQty") AS "Qty" FROM "MTC_CA_S_ORDER_LINE"
                  WHERE "RunId" = :RunId GROUP BY "OrderType", "OrderEntry", "ItemCode") PL
        ON PL."OrderType" = T0."OrderType" AND PL."OrderEntry" = T0."OrderEntry" AND PL."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId;

    -- 9. 费用池固定部分：凭证、重估（按成本中心归池，没配置或没有成本中心的进默认池，Q12）
    INSERT INTO "MTC_CA_R_POOL" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "Src", "Amount")
    -- HANA 不接受 GROUP BY 里带变量的表达式，先在子查询里算出池代码
    SELECT :fc, :rt, :scen, :RunId, X."PoolCode", X."Elem", X."Src", SUM(X."Amount")
      FROM (SELECT IFNULL(PS."PoolCode", :defPool) AS "PoolCode", E."Elem", E."Src", E."Amount"
              FROM "MTC_CA_S_EXP" E
              LEFT JOIN "MTC_CA_C_POOL_SRC" PS ON PS."OcrCode" = E."OcrCode" AND :fc BETWEEN PS."FromFc" AND PS."ToFc"
             WHERE E."RunId" = :RunId) X
     GROUP BY X."PoolCode", X."Elem", X."Src";
END

@@
-- @stmt 新框架 13_p40_iter.sql #1
-- =====================================================================
-- 新成本框架 第 2 期：P40 迭代（设计稿 4、4.2–4.4）
-- 替代：0311 / 0312（费用池与分摊）、0306（委外加工费）、0401_CAL 六段 + 返工段、0402_CAL_OWOR(_30)、
--       CO4001 / CO4011（在产品、关单差异）、“算两遍”。
-- 每轮：P41 按当前单价给加权价行定价 → P42 费用池 → P43 分摊 → P45 逐级（L = 0 … 最高层）→ P47 收敛判断。
-- 每轮只把“当前物料单价、上一轮关单差异”作为输入，结果只取决于快照和参数，与运行次数无关。
-- =====================================================================

-- P41：加权价类行（WAVG）按物料当前单价定价；公摊材料行也在其中
CREATE OR REPLACE PROCEDURE "MTC_CA_P41_PRICE" (IN RunId BIGINT, IN Iter INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    UPDATE T0 SET T0."MatAmt" = ROUND(I."PMat" * T0."Qty", 2), T0."MfgAmt" = ROUND(I."PMfg" * T0."Qty", 2),
                  T0."LabAmt" = ROUND(I."PLab" * T0."Qty", 2), T0."SubAmt" = ROUND(I."PSub" * T0."Qty", 2),
                  T0."Amount" = ROUND(I."PMat" * T0."Qty", 2) + ROUND(I."PMfg" * T0."Qty", 2)
                              + ROUND(I."PLab" * T0."Qty", 2) + ROUND(I."PSub" * T0."Qty", 2),
                  -- 退货、取消单、形态转换的兜底说明保留，其余每轮刷新单价来源；上一轮挤尾差的标记去掉
                  T0."PriceSrc" = CASE WHEN T0."RuleId" IS NULL OR T0."RuleId" = 'WAVG-01'
                                       THEN '物料本期加权单价（' || I."PriceSrc" || '）' ELSE REPLACE(T0."PriceSrc", '；含期末尾差（RND-01）', '') END,
                  T0."RuleId" = IFNULL(T0."RuleId", 'WAVG-01'), T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_ITEM" I ON I."RunId" = T0."RunId" AND I."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'WAVG';

    -- 尾差（RND-01，2026-10-13）：逐行 ROUND(单价 × 数量, 2) 后，出光的物料期末会剩 ±0.01（如 101100111：5 × 1527.555 = 7637.775 → 7637.78，
    -- 9 × 1527.555 = 13747.995 → 13748.00，合计多出 0.01）。在这里挤进数量最大的加权价出库行，公摊材料行也可以挤——在 P42 之前，
    -- 费用池和分摊用的就是挤过的金额；P50 只能挤非公摊行（那时费用已分摊），只给没收敛的情况兜底。形态转换转出行不挤（P45 按层重新定价）。
    -- 用的入库金额是上一轮的，收敛后与最终结果一致。
    -- 2026-10-13：候选行加上订单领料（ISSUE）。全部领给订单出光的物料（如 040600093）原来没有可挤的行，期末剩 0.01；
    -- 数量最大的出库行是领料行时这里不挤，由 P45 在该订单所在层给领料定价后挤，再汇总订单材料。
    tail = SELECT I."ItemCode",
                  I."OpenMat" + S."Mat" AS "TMat", I."OpenMfg" + S."Mfg" AS "TMfg", I."OpenLab" + S."Lab" AS "TLab", I."OpenSub" + S."Sub" AS "TSub"
             FROM "MTC_CA_R_ITEM" I
             JOIN (SELECT "ItemCode", SUM("Qty") AS "Qty", SUM("MatAmt") AS "Mat", SUM("MfgAmt") AS "Mfg", SUM("LabAmt") AS "Lab", SUM("SubAmt") AS "Sub"
                     FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId GROUP BY "ItemCode") S ON S."ItemCode" = I."ItemCode"
            WHERE I."RunId" = :RunId AND I."OpenQty" + S."Qty" = 0
              AND (I."OpenMat" + S."Mat" <> 0 OR I."OpenMfg" + S."Mfg" <> 0 OR I."OpenLab" + S."Lab" <> 0 OR I."OpenSub" + S."Sub" <> 0);
    cand = SELECT L."LineId", L."Cat", T."TMat", T."TMfg", T."TLab", T."TSub",
                  ROW_NUMBER() OVER (PARTITION BY L."ItemCode" ORDER BY ABS(L."Qty") DESC, L."LineId") AS "Rn"
             FROM "MTC_CA_R_LINE" L
             JOIN :tail T ON T."ItemCode" = L."ItemCode"
            WHERE L."RunId" = :RunId AND L."Cat" IN ('WAVG', 'ISSUE') AND L."Qty" < 0
              AND L."LineId" NOT IN (SELECT "SrcLineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId AND "SrcLineId" IS NOT NULL);
    UPDATE T0 SET T0."MatAmt" = T0."MatAmt" - C."TMat", T0."MfgAmt" = T0."MfgAmt" - C."TMfg",
                  T0."LabAmt" = T0."LabAmt" - C."TLab", T0."SubAmt" = T0."SubAmt" - C."TSub",
                  T0."Amount" = T0."Amount" - C."TMat" - C."TMfg" - C."TLab" - C."TSub",
                  T0."PriceSrc" = T0."PriceSrc" || '；含期末尾差（RND-01）'
      FROM "MTC_CA_R_LINE" T0
      JOIN :cand C ON C."LineId" = T0."LineId" AND C."Rn" = 1 AND C."Cat" = 'WAVG'
     WHERE T0."RunId" = :RunId;
END

@@
-- @stmt 新框架 13_p40_iter.sql #2
-- P42：费用池 = 固定部分（凭证、重估，P30 已写）+ 公摊材料（按当前单价）+ 关单差异（上一轮，全部进 CLOSE_DIF_POOL）
CREATE OR REPLACE PROCEDURE "MTC_CA_P42_POOL" (IN RunId BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE clsPool NVARCHAR(20);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    clsPool := "MTC_CA_F_PARAM"('CLOSE_DIF_POOL', :fc);

    DELETE FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId AND "Src" IN ('SHARED', 'CLOSEDIF');

    -- 公摊材料：出库为负，计入费用为正
    INSERT INTO "MTC_CA_R_POOL" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "Src", "Amount")
    SELECT :fc, :rt, :scen, :RunId, "PoolCode", 'MFG', 'SHARED', -SUM("Amount")
      FROM "MTC_CA_R_LINE"
     WHERE "RunId" = :RunId AND "IsShared" = 'Y'
     GROUP BY "PoolCode";

    INSERT INTO "MTC_CA_R_POOL" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "Src", "Amount")
    SELECT :fc, :rt, :scen, :RunId, :clsPool, 'MFG', 'CLOSEDIF', SUM("CloseDifAmt")
      FROM "MTC_CA_R_ORDER"
     WHERE "RunId" = :RunId
    HAVING SUM("CloseDifAmt") <> 0;
END

@@
-- @stmt 新框架 13_p40_iter.sql #3
-- P43：各池按“单位工时 × 本期入库数”一步分到池范围内本期有入库的订单；金额取 2 位，尾差挤最大行；
-- 制造、人工用同一权重（Q19）；返工单用产品的正常单位工时（Q18）；只分给本期净入库 > 0 的订单，净入库为负的由 PRE-19 报出（Q20）；
-- 池内没有可分摊订单的金额留在池里（未分摊，POST-03 报出，Q13）
CREATE OR REPLACE PROCEDURE "MTC_CA_P43_ALLOC" (IN RunId BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);

    DELETE FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :RunId;

    elig = SELECT T."PoolCode", O."OrderType", O."OrderEntry", H."Hours", O."RecvQty", H."Hours" * O."RecvQty" AS "W"
             FROM "MTC_CA_R_ORDER" O
             JOIN "MTC_CA_V_ITEM_POOL" T ON T."RunId" = O."RunId" AND T."ItemCode" = O."ItemCode"
                                        AND LOCATE(T."WorTypes", ',' || O."WorType" || ',') > 0
             JOIN "MTC_CA_S_HOURS" H ON H."RunId" = O."RunId" AND H."ItemCode" = O."ItemCode"
            WHERE O."RunId" = :RunId AND O."RecvQty" > 0 AND H."Hours" <> 0;
    pools = SELECT "PoolCode", "Elem", SUM("Amount") AS "Amt"
              FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId GROUP BY "PoolCode", "Elem";
    raw = SELECT P."PoolCode", P."Elem", P."Amt", E."OrderType", E."OrderEntry", E."Hours", E."RecvQty", E."W",
                 E."W" / NULLIF(SUM(E."W") OVER (PARTITION BY P."PoolCode", P."Elem"), 0) AS "Ratio"
            FROM :pools P JOIN :elig E ON E."PoolCode" = P."PoolCode";
    rnd = SELECT R.*, ROUND(R."Amt" * R."Ratio", 2) AS "A",
                 ROUND(R."Amt", 2) - SUM(ROUND(R."Amt" * R."Ratio", 2)) OVER (PARTITION BY R."PoolCode", R."Elem") AS "Tail",
                 ROW_NUMBER() OVER (PARTITION BY R."PoolCode", R."Elem" ORDER BY ABS(R."W") DESC, R."OrderType", R."OrderEntry") AS "Rn"
            FROM :raw R WHERE R."Ratio" IS NOT NULL;

    INSERT INTO "MTC_CA_R_ALLOC" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "OrderType", "OrderEntry",
                                  "Hours", "RecvQty", "Weight", "Ratio", "Amount")
    SELECT :fc, :rt, :scen, :RunId, "PoolCode", "Elem", "OrderType", "OrderEntry", "Hours", "RecvQty", "W", "Ratio",
           "A" + CASE WHEN "Rn" = 1 THEN "Tail" ELSE 0 END
      FROM :rnd;

    UPDATE "MTC_CA_R_ORDER" SET "AllocMfg" = 0, "AllocLab" = 0 WHERE "RunId" = :RunId;
    UPDATE T0 SET T0."AllocMfg" = A."Mfg", T0."AllocLab" = A."Lab"
      FROM "MTC_CA_R_ORDER" T0
      JOIN (SELECT "OrderType", "OrderEntry",
                   SUM(CASE WHEN "Elem" = 'MFG' THEN "Amount" ELSE 0 END) AS "Mfg",
                   SUM(CASE WHEN "Elem" = 'LAB' THEN "Amount" ELSE 0 END) AS "Lab"
              FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :RunId GROUP BY "OrderType", "OrderEntry") A
        ON A."OrderType" = T0."OrderType" AND A."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId;
END

@@
-- @stmt 新框架 13_p40_iter.sql #4
-- P45：第 Lv 层
--   a 本层订单的领料按子件当前单价定价（下层本轮已更新；同层 / 上层用上一轮，返工单靠迭代收敛，S2）；生产退料按订单该材料平均领料单价
--   b 订单 × 材料结转：本期有入库时 结转 = 累计领料 × 本行比例 − 以前已结转（R_ORDER_MAT.Ratio：max(订单比例, 累计入库所需 ÷ 净领料)，最高 1；加工费 1；2026-10-30）；在产品 = 累计领料 − 累计结转；本期关单的在产品转关单差异
--   c 订单完工成本 = 材料结转（四项）+ 分摊制造 / 人工 + 加工费结转
--   d 完工入库行按订单成本 × 行数量 ÷ 本期入库数，取 2 位，尾差挤数量最大的行
--   e 形态转换 I05 = −O05（B 的当前单价）；本层物料加权单价 =（期初 + 计价入库）÷（期初数量 + 计价入库数量）
CREATE OR REPLACE PROCEDURE "MTC_CA_P45_LEVEL" (IN RunId BIGINT, IN Lv INT, IN Iter INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    -- a 领料
    UPDATE T0 SET T0."MatAmt" = ROUND(I."PMat" * T0."Qty", 2), T0."MfgAmt" = ROUND(I."PMfg" * T0."Qty", 2),
                  T0."LabAmt" = ROUND(I."PLab" * T0."Qty", 2), T0."SubAmt" = ROUND(I."PSub" * T0."Qty", 2),
                  T0."Amount" = ROUND(I."PMat" * T0."Qty", 2) + ROUND(I."PMfg" * T0."Qty", 2)
                              + ROUND(I."PLab" * T0."Qty", 2) + ROUND(I."PSub" * T0."Qty", 2),
                  T0."PriceSrc" = '子件当前单价（' || I."PriceSrc" || '）', T0."RuleId" = 'WAVG-01', T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
      JOIN "MTC_CA_R_ITEM" I ON I."RunId" = T0."RunId" AND I."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'ISSUE' AND O."iLevel" = :Lv;

    avg304 = SELECT M."OrderType", M."OrderEntry", M."ItemCode",
                    (M."OpenIssMat" + IFNULL(S."Mat", 0)) / NULLIF(M."OpenIssQty" + IFNULL(S."Qty", 0), 0) AS "UMat",
                    (M."OpenIssMfg" + IFNULL(S."Mfg", 0)) / NULLIF(M."OpenIssQty" + IFNULL(S."Qty", 0), 0) AS "UMfg",
                    (M."OpenIssLab" + IFNULL(S."Lab", 0)) / NULLIF(M."OpenIssQty" + IFNULL(S."Qty", 0), 0) AS "ULab",
                    (M."OpenIssSub" + IFNULL(S."Sub", 0)) / NULLIF(M."OpenIssQty" + IFNULL(S."Qty", 0), 0) AS "USub"
               FROM "MTC_CA_R_ORDER_MAT" M
               JOIN "MTC_CA_R_ORDER" O ON O."RunId" = M."RunId" AND O."OrderType" = M."OrderType" AND O."OrderEntry" = M."OrderEntry"
               LEFT JOIN (SELECT "OrderType", "OrderEntry", "ItemCode", -SUM("Qty") AS "Qty",
                                 -SUM("MatAmt") AS "Mat", -SUM("MfgAmt") AS "Mfg", -SUM("LabAmt") AS "Lab", -SUM("SubAmt") AS "Sub"
                            FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId AND "Cat" = 'ISSUE'
                           GROUP BY "OrderType", "OrderEntry", "ItemCode") S
                 ON S."OrderType" = M."OrderType" AND S."OrderEntry" = M."OrderEntry" AND S."ItemCode" = M."ItemCode"
              WHERE M."RunId" = :RunId AND O."iLevel" = :Lv;
    UPDATE T0 SET T0."MatAmt" = ROUND(IFNULL(A."UMat", I."PMat") * T0."Qty", 2), T0."MfgAmt" = ROUND(IFNULL(A."UMfg", I."PMfg") * T0."Qty", 2),
                  T0."LabAmt" = ROUND(IFNULL(A."ULab", I."PLab") * T0."Qty", 2), T0."SubAmt" = ROUND(IFNULL(A."USub", I."PSub") * T0."Qty", 2),
                  T0."Amount" = ROUND(IFNULL(A."UMat", I."PMat") * T0."Qty", 2) + ROUND(IFNULL(A."UMfg", I."PMfg") * T0."Qty", 2)
                              + ROUND(IFNULL(A."ULab", I."PLab") * T0."Qty", 2) + ROUND(IFNULL(A."USub", I."PSub") * T0."Qty", 2),
                  T0."PriceSrc" = CASE WHEN A."UMat" IS NULL THEN '订单没有领料可参考，按物料当前单价' ELSE '该订单该材料平均领料单价' END,
                  T0."RuleId" = 'RTN-01', T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
      JOIN "MTC_CA_R_ITEM" I ON I."RunId" = T0."RunId" AND I."ItemCode" = T0."ItemCode"
      LEFT JOIN :avg304 A ON A."OrderType" = T0."OrderType" AND A."OrderEntry" = T0."OrderEntry" AND A."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'RTN304' AND O."iLevel" = :Lv;

    -- a 尾差（RND-01，2026-10-13）：出光的物料，数量最大的出库行（选法同 P41）是本层订单的领料行时，尾差挤进这一行，
    -- 再在 b 汇总进订单材料。物料其他行的金额用当前值（以后层级的领料是上一轮的），收敛后与最终结果一致。
    ttail = SELECT I."ItemCode",
                  I."OpenMat" + S."Mat" AS "TMat", I."OpenMfg" + S."Mfg" AS "TMfg", I."OpenLab" + S."Lab" AS "TLab", I."OpenSub" + S."Sub" AS "TSub"
             FROM "MTC_CA_R_ITEM" I
             JOIN (SELECT "ItemCode", SUM("Qty") AS "Qty", SUM("MatAmt") AS "Mat", SUM("MfgAmt") AS "Mfg", SUM("LabAmt") AS "Lab", SUM("SubAmt") AS "Sub"
                     FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId GROUP BY "ItemCode") S ON S."ItemCode" = I."ItemCode"
            WHERE I."RunId" = :RunId AND I."OpenQty" + S."Qty" = 0
              AND (I."OpenMat" + S."Mat" <> 0 OR I."OpenMfg" + S."Mfg" <> 0 OR I."OpenLab" + S."Lab" <> 0 OR I."OpenSub" + S."Sub" <> 0);
    tcand = SELECT L."LineId", L."Cat", L."OrderType", L."OrderEntry", T."TMat", T."TMfg", T."TLab", T."TSub",
                  ROW_NUMBER() OVER (PARTITION BY L."ItemCode" ORDER BY ABS(L."Qty") DESC, L."LineId") AS "Rn"
             FROM "MTC_CA_R_LINE" L
             JOIN :ttail T ON T."ItemCode" = L."ItemCode"
            WHERE L."RunId" = :RunId AND L."Cat" IN ('WAVG', 'ISSUE') AND L."Qty" < 0
              AND L."LineId" NOT IN (SELECT "SrcLineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId AND "SrcLineId" IS NOT NULL);
    UPDATE T0 SET T0."MatAmt" = T0."MatAmt" - C."TMat", T0."MfgAmt" = T0."MfgAmt" - C."TMfg",
                  T0."LabAmt" = T0."LabAmt" - C."TLab", T0."SubAmt" = T0."SubAmt" - C."TSub",
                  T0."Amount" = T0."Amount" - C."TMat" - C."TMfg" - C."TLab" - C."TSub",
                  T0."PriceSrc" = T0."PriceSrc" || '；含期末尾差（RND-01）'
      FROM "MTC_CA_R_LINE" T0
      JOIN :tcand C ON C."LineId" = T0."LineId" AND C."Rn" = 1 AND C."Cat" = 'ISSUE'
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = C."OrderType" AND O."OrderEntry" = C."OrderEntry"
     WHERE T0."RunId" = :RunId AND O."iLevel" = :Lv;

    -- b 订单 × 材料
    UPDATE T0 SET T0."IssMat" = S."Mat", T0."IssMfg" = S."Mfg", T0."IssLab" = S."Lab", T0."IssSub" = S."Sub"
      FROM "MTC_CA_R_ORDER_MAT" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
      JOIN (SELECT "OrderType", "OrderEntry", "ItemCode",
                   -SUM("MatAmt") AS "Mat", -SUM("MfgAmt") AS "Mfg", -SUM("LabAmt") AS "Lab", -SUM("SubAmt") AS "Sub"
              FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId AND "Cat" IN ('ISSUE', 'RTN304')
             GROUP BY "OrderType", "OrderEntry", "ItemCode") S
        ON S."OrderType" = T0."OrderType" AND S."OrderEntry" = T0."OrderEntry" AND S."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND O."iLevel" = :Lv;

    -- 结转按 订单 × 材料 × 要素 取 2 位（用户 2026-10-14）：完工成本 = 各行结转之和，在产品 = 领料 − 结转，都是 2 位，与 PP05 / WW03 凭证逐笔一致
    -- 比例取 R_ORDER_MAT.Ratio（P30 算好：按净领料数量，有退料时不少结转；加工费 1；本期无入库为空 → 结转 0，用户 2026-10-30）
    UPDATE T0 SET
           T0."CarMat" = IFNULL(ROUND((T0."OpenIssMat" + T0."IssMat") * T0."Ratio" - T0."OpenCarMat", 2), 0),
           T0."CarMfg" = IFNULL(ROUND((T0."OpenIssMfg" + T0."IssMfg") * T0."Ratio" - T0."OpenCarMfg", 2), 0),
           T0."CarLab" = IFNULL(ROUND((T0."OpenIssLab" + T0."IssLab") * T0."Ratio" - T0."OpenCarLab", 2), 0),
           T0."CarSub" = IFNULL(ROUND((T0."OpenIssSub" + T0."IssSub") * T0."Ratio" - T0."OpenCarSub", 2), 0)
      FROM "MTC_CA_R_ORDER_MAT" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId AND O."iLevel" = :Lv;

    UPDATE T0 SET
           T0."ClsMat" = CASE WHEN O."ClosedInFc" = 'Y' THEN T0."OpenIssMat" + T0."IssMat" - T0."OpenCarMat" - T0."CarMat" ELSE 0 END,
           T0."ClsMfg" = CASE WHEN O."ClosedInFc" = 'Y' THEN T0."OpenIssMfg" + T0."IssMfg" - T0."OpenCarMfg" - T0."CarMfg" ELSE 0 END,
           T0."ClsLab" = CASE WHEN O."ClosedInFc" = 'Y' THEN T0."OpenIssLab" + T0."IssLab" - T0."OpenCarLab" - T0."CarLab" ELSE 0 END,
           T0."ClsSub" = CASE WHEN O."ClosedInFc" = 'Y' THEN T0."OpenIssSub" + T0."IssSub" - T0."OpenCarSub" - T0."CarSub" ELSE 0 END,
           T0."WipMat" = CASE WHEN O."ClosedInFc" = 'Y' THEN 0 ELSE T0."OpenIssMat" + T0."IssMat" - T0."OpenCarMat" - T0."CarMat" END,
           T0."WipMfg" = CASE WHEN O."ClosedInFc" = 'Y' THEN 0 ELSE T0."OpenIssMfg" + T0."IssMfg" - T0."OpenCarMfg" - T0."CarMfg" END,
           T0."WipLab" = CASE WHEN O."ClosedInFc" = 'Y' THEN 0 ELSE T0."OpenIssLab" + T0."IssLab" - T0."OpenCarLab" - T0."CarLab" END,
           T0."WipSub" = CASE WHEN O."ClosedInFc" = 'Y' THEN 0 ELSE T0."OpenIssSub" + T0."IssSub" - T0."OpenCarSub" - T0."CarSub" END
      FROM "MTC_CA_R_ORDER_MAT" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId AND O."iLevel" = :Lv;

    -- c 订单完工成本
    UPDATE "MTC_CA_R_ORDER"
       SET "CostMat" = 0, "CostMfg" = "AllocMfg", "CostLab" = "AllocLab", "CostSub" = 0, "WipAmt" = 0, "CloseDifAmt" = 0
     WHERE "RunId" = :RunId AND "iLevel" = :Lv;
    UPDATE T0 SET T0."CostMat" = S."CarMat", T0."CostMfg" = T0."AllocMfg" + S."CarMfg",
                  T0."CostLab" = T0."AllocLab" + S."CarLab", T0."CostSub" = S."CarSub",
                  T0."WipAmt" = S."Wip", T0."CloseDifAmt" = S."Cls"
      FROM "MTC_CA_R_ORDER" T0
      JOIN (SELECT "OrderType", "OrderEntry", SUM("CarMat") AS "CarMat", SUM("CarMfg") AS "CarMfg",
                   SUM("CarLab") AS "CarLab", SUM("CarSub") AS "CarSub",
                   SUM("WipMat" + "WipMfg" + "WipLab" + "WipSub") AS "Wip",
                   SUM("ClsMat" + "ClsMfg" + "ClsLab" + "ClsSub") AS "Cls"
              FROM "MTC_CA_R_ORDER_MAT" WHERE "RunId" = :RunId GROUP BY "OrderType", "OrderEntry") S
        ON S."OrderType" = T0."OrderType" AND S."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId AND T0."iLevel" = :Lv;
    UPDATE "MTC_CA_R_ORDER"
       SET "CostAmt" = "CostMat" + "CostMfg" + "CostLab" + "CostSub",
           "UnitCost" = ("CostMat" + "CostMfg" + "CostLab" + "CostSub") / NULLIF("RecvQty", 0)
     WHERE "RunId" = :RunId AND "iLevel" = :Lv;

    -- d 完工入库行
    UPDATE T0 SET T0."MatAmt" = CASE WHEN O."RecvQty" = 0 THEN 0 ELSE ROUND(O."CostMat" * T0."Qty" / O."RecvQty", 2) END,
                  T0."MfgAmt" = CASE WHEN O."RecvQty" = 0 THEN 0 ELSE ROUND(O."CostMfg" * T0."Qty" / O."RecvQty", 2) END,
                  T0."LabAmt" = CASE WHEN O."RecvQty" = 0 THEN 0 ELSE ROUND(O."CostLab" * T0."Qty" / O."RecvQty", 2) END,
                  T0."SubAmt" = CASE WHEN O."RecvQty" = 0 THEN 0 ELSE ROUND(O."CostSub" * T0."Qty" / O."RecvQty", 2) END,
                  T0."PriceSrc" = '订单本期完工成本', T0."RuleId" = 'WIP-01', T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'RCPT' AND O."iLevel" = :Lv;
    tail = SELECT L."LineId",
                  ROUND(O."CostMat", 2) - SUM(L."MatAmt") OVER (PARTITION BY L."OrderType", L."OrderEntry") AS "TMat",
                  ROUND(O."CostMfg", 2) - SUM(L."MfgAmt") OVER (PARTITION BY L."OrderType", L."OrderEntry") AS "TMfg",
                  ROUND(O."CostLab", 2) - SUM(L."LabAmt") OVER (PARTITION BY L."OrderType", L."OrderEntry") AS "TLab",
                  ROUND(O."CostSub", 2) - SUM(L."SubAmt") OVER (PARTITION BY L."OrderType", L."OrderEntry") AS "TSub",
                  ROW_NUMBER() OVER (PARTITION BY L."OrderType", L."OrderEntry" ORDER BY ABS(L."Qty") DESC, L."LineId") AS "Rn"
             FROM "MTC_CA_R_LINE" L
             JOIN "MTC_CA_R_ORDER" O ON O."RunId" = L."RunId" AND O."OrderType" = L."OrderType" AND O."OrderEntry" = L."OrderEntry"
            WHERE L."RunId" = :RunId AND L."Cat" = 'RCPT' AND O."iLevel" = :Lv AND O."RecvQty" <> 0;
    UPDATE T0 SET T0."MatAmt" = T0."MatAmt" + X."TMat", T0."MfgAmt" = T0."MfgAmt" + X."TMfg",
                  T0."LabAmt" = T0."LabAmt" + X."TLab", T0."SubAmt" = T0."SubAmt" + X."TSub"
      FROM "MTC_CA_R_LINE" T0
      JOIN :tail X ON X."LineId" = T0."LineId" AND X."Rn" = 1
     WHERE T0."RunId" = :RunId;
    UPDATE T0 SET T0."Amount" = T0."MatAmt" + T0."MfgAmt" + T0."LabAmt" + T0."SubAmt"
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_ORDER" O ON O."RunId" = T0."RunId" AND O."OrderType" = T0."OrderType" AND O."OrderEntry" = T0."OrderEntry"
     WHERE T0."RunId" = :RunId AND T0."Cat" = 'RCPT' AND O."iLevel" = :Lv;

    -- e 形态转换：本层 A 的 I05 = −O05（B 按当前单价）
    trf = SELECT P."LineId", P."SrcLineId"
            FROM "MTC_CA_R_PAIR" P
            JOIN "MTC_CA_R_LINE" A ON A."RunId" = P."RunId" AND A."LineId" = P."LineId"
            JOIN "MTC_CA_R_ITEM" IA ON IA."RunId" = P."RunId" AND IA."ItemCode" = A."ItemCode"
           WHERE P."RunId" = :RunId AND P."PairType" = 'TRF' AND IA."iLevel" = :Lv;
    UPDATE T0 SET T0."MatAmt" = ROUND(I."PMat" * T0."Qty", 2), T0."MfgAmt" = ROUND(I."PMfg" * T0."Qty", 2),
                  T0."LabAmt" = ROUND(I."PLab" * T0."Qty", 2), T0."SubAmt" = ROUND(I."PSub" * T0."Qty", 2),
                  T0."Amount" = ROUND(I."PMat" * T0."Qty", 2) + ROUND(I."PMfg" * T0."Qty", 2)
                              + ROUND(I."PLab" * T0."Qty", 2) + ROUND(I."PSub" * T0."Qty", 2), T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN :trf X ON X."SrcLineId" = T0."LineId"
      JOIN "MTC_CA_R_ITEM" I ON I."RunId" = T0."RunId" AND I."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId;
    UPDATE T0 SET T0."MatAmt" = -B."MatAmt", T0."MfgAmt" = -B."MfgAmt", T0."LabAmt" = -B."LabAmt", T0."SubAmt" = -B."SubAmt",
                  T0."Amount" = -B."Amount", T0."PriceSrc" = '形态转换：= 转出行金额', T0."RuleId" = 'TRF-01', T0."Iter" = :Iter
      FROM "MTC_CA_R_LINE" T0
      JOIN :trf X ON X."LineId" = T0."LineId"
      JOIN "MTC_CA_R_LINE" B ON B."RunId" = T0."RunId" AND B."LineId" = X."SrcLineId"
     WHERE T0."RunId" = :RunId;

    -- e 本层物料加权单价
    UPDATE "MTC_CA_R_ITEM" SET "InQty" = 0, "InMat" = 0, "InMfg" = 0, "InLab" = 0, "InSub" = 0
     WHERE "RunId" = :RunId AND "iLevel" = :Lv;
    UPDATE T0 SET T0."InQty" = S."Qty", T0."InMat" = S."Mat", T0."InMfg" = S."Mfg", T0."InLab" = S."Lab", T0."InSub" = S."Sub"
      FROM "MTC_CA_R_ITEM" T0
      JOIN (SELECT "ItemCode", SUM("Qty") AS "Qty", SUM("MatAmt") AS "Mat", SUM("MfgAmt") AS "Mfg",
                   SUM("LabAmt") AS "Lab", SUM("SubAmt") AS "Sub"
              FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId AND "InVal" = 'Y' GROUP BY "ItemCode") S
        ON S."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId AND T0."iLevel" = :Lv;
    UPDATE "MTC_CA_R_ITEM"
       SET "PMat" = ("OpenMat" + "InMat") / ("OpenQty" + "InQty"), "PMfg" = ("OpenMfg" + "InMfg") / ("OpenQty" + "InQty"),
           "PLab" = ("OpenLab" + "InLab") / ("OpenQty" + "InQty"), "PSub" = ("OpenSub" + "InSub") / ("OpenQty" + "InQty"),
           "PriceSrc" = 'WAVG'
     WHERE "RunId" = :RunId AND "iLevel" = :Lv AND "OpenQty" + "InQty" > 0;
END

@@
-- @stmt 新框架 13_p40_iter.sql #5
-- P40：迭代到收敛或达到最大轮数
CREATE OR REPLACE PROCEDURE "MTC_CA_P40_ITERATE" (IN RunId BIGINT, OUT Converged NVARCHAR(1), OUT Iters INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE maxIter INT; DECLARE convP DECIMAL(19,6); DECLARE convA DECIMAL(19,6);
    DECLARE maxLv INT; DECLARE lv INT;
    DECLARE k INT := 0;
    DECLARE lastPool DECIMAL(19,6); DECLARE newPool DECIMAL(19,6);
    DECLARE lastCls DECIMAL(19,6); DECLARE newCls DECIMAL(19,6);
    DECLARE dP DECIMAL(19,6); DECLARE nUnconv INT;
    DECLARE topN INT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    topN := TO_INTEGER(IFNULL("MTC_CA_F_PARAM"('ITER_TRACE_TOP', :fc), '30'));
    maxIter := TO_INTEGER(IFNULL("MTC_CA_F_PARAM"('MAX_ITER', :fc), '50'));
    convP := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('CONV_PRICE', :fc), '0.000001'), 19, 6);
    convA := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('CONV_AMT', :fc), '0.01'), 19, 6);
    SELECT GREATEST(IFNULL(MAX("iLevel"), 0), 0) INTO maxLv FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId;
    Converged := 'N';

    WHILE :k < :maxIter DO
        k := :k + 1;
        UPDATE "MTC_CA_R_ITEM" SET "LastPMat" = "PMat", "LastPMfg" = "PMfg", "LastPLab" = "PLab", "LastPSub" = "PSub"
         WHERE "RunId" = :RunId;
        SELECT IFNULL(SUM("Amount"), 0) INTO lastPool FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId;
        SELECT IFNULL(SUM("CloseDifAmt"), 0) INTO lastCls FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId;

        -- 执行台进度（MTC_CA_P_LOG_NOTE 自治提交，页面轮询时能看到当前在第几轮、第几级）
        CALL "MTC_CA_P_LOG_NOTE"(:RunId, '第 ' || :k || ' 轮：加权价行定价（P41）');
        CALL "MTC_CA_P41_PRICE"(:RunId, :k);
        CALL "MTC_CA_P_LOG_NOTE"(:RunId, '第 ' || :k || ' 轮：费用池归集（P42）');
        CALL "MTC_CA_P42_POOL"(:RunId);
        CALL "MTC_CA_P_LOG_NOTE"(:RunId, '第 ' || :k || ' 轮：费用分摊（P43）');
        CALL "MTC_CA_P43_ALLOC"(:RunId);
        -- 这个 HANA 版本的 FOR 循环变量不能直接在 CALL 中引用（报 identifier must be declared），改用 WHILE
        lv := 0;
        WHILE :lv <= :maxLv DO
            CALL "MTC_CA_P_LOG_NOTE"(:RunId, '第 ' || :k || ' 轮：逐级结转第 ' || :lv || ' 级 / 共 0–' || :maxLv || ' 级（P45）');
            CALL "MTC_CA_P45_LEVEL"(:RunId, :lv, :k);
            lv := :lv + 1;
        END WHILE;

        SELECT IFNULL(SUM("Amount"), 0) INTO newPool FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId;
        SELECT IFNULL(SUM("CloseDifAmt"), 0) INTO newCls FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId;
        SELECT IFNULL(MAX(GREATEST(ABS("PMat" - "LastPMat"), ABS("PMfg" - "LastPMfg"), ABS("PLab" - "LastPLab"), ABS("PSub" - "LastPSub"))), 0),
               SUM(CASE WHEN GREATEST(ABS("PMat" - "LastPMat"), ABS("PMfg" - "LastPMfg"), ABS("PLab" - "LastPLab"), ABS("PSub" - "LastPSub")) > :convP THEN 1 ELSE 0 END)
          INTO dP, nUnconv
          FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId;

        -- 迭代日志自治提交：运行中执行台就能看到每一轮，计算出错回滚后也保留供排查
        BEGIN AUTONOMOUS TRANSACTION
            INSERT INTO "MTC_CA_RUN_ITER" ("RunId", "Iter", "MaxPriceDelta", "PoolDelta", "CloseDifDelta", "UnconvItems", "EndTime")
            VALUES (:RunId, :k, :dP, ROUND(:newPool - :lastPool, 2), ROUND(:newCls - :lastCls, 2), IFNULL(:nUnconv, 0), CURRENT_TIMESTAMP);
        END;
        -- 迭代明细（2026-10-29）：本轮单价变化最大的前 topN 个物料。R_ITEM 的本轮单价还没提交，自治事务看不到，所以在本事务里写，
        -- 和本轮结果一起在本轮末尾提交（2026-10-30）
        IF :topN > 0 AND :dP > :convP THEN
            INSERT INTO "MTC_CA_RUN_ITER_ITEM" ("RunId", "Iter", "Rk", "ItemCode", "iLevel", "PriceDelta", "Price", "LastPrice",
                                                "PMat", "PMfg", "PLab", "PSub", "OpenQty", "OpenAmt", "InQty", "InAmt", "PriceSrc")
            SELECT :RunId, :k, "Rk", "ItemCode", "iLevel", "D", "PMat" + "PMfg" + "PLab" + "PSub",
                   "LastPMat" + "LastPMfg" + "LastPLab" + "LastPSub", "PMat", "PMfg", "PLab", "PSub",
                   "OpenQty", "OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub", "InQty", "InMat" + "InMfg" + "InLab" + "InSub", "PriceSrc"
              FROM (SELECT I.*, ROW_NUMBER() OVER (ORDER BY I."D" DESC, I."ItemCode") AS "Rk"
                      FROM (SELECT T.*, GREATEST(ABS("PMat" - "LastPMat"), ABS("PMfg" - "LastPMfg"),
                                                 ABS("PLab" - "LastPLab"), ABS("PSub" - "LastPSub")) AS "D"
                              FROM "MTC_CA_R_ITEM" T WHERE T."RunId" = :RunId) I
                     WHERE I."D" > :convP)
             WHERE "Rk" <= :topN;
        END IF;
        CALL "MTC_CA_P_LOG_NOTE"(:RunId, '第 ' || :k || ' 轮完成，还有 ' || IFNULL(:nUnconv, 0) || ' 个物料单价未收敛');
        -- 每轮提交（2026-10-30，#14 发散到第 50 轮溢出、全部回滚后无从排查）：后面某一轮出错时，回滚的只是出错那一轮，
        -- R_* 停在最后一轮完成时的状态，和 MTC_CA_RUN_ITER_ITEM 对得上；P_RUN 出错时按 KEEP_NOCONV 保留供排查
        COMMIT;

        -- 本轮所用的关单差异（上一轮结果）与本轮算出的一致、单价不再变化，即收敛
        IF :dP <= :convP AND ABS(:newCls - :lastCls) <= :convA AND ABS(:newPool - :lastPool) <= :convA THEN
            Converged := 'Y';
            BREAK;
        END IF;
    END WHILE;
    Iters := :k;
END

@@
-- @stmt 新框架 14_p50_p60_p65.sql #1
-- =====================================================================
-- 新成本框架 第 2 期：P50 定稿、P60 计算后校验与指标快照、P65 新旧比对（设计稿 4、6）
-- 替代：0401 末尾“91 写入”和入库尾差处理、CAL_1004_CHECK(_LS)、CO4004 的勾稽部分、C01–C18 中与新表相关的项。
-- =====================================================================

-- P50：按最终单价给加权价行定价；物料进销存四项；期末数量为 0 而金额不为 0 的，尾差挤进该物料数量最大的普通出库行；
-- 没有可挤的出库行、且尾差在参数 TAIL_MAX（±0.02，Q32 用户 2026-10-14）以内的，记入 R_ITEM.TailAmt 结转（TAIL-01，凭证 JZ04，借 / 贷 TAIL_ADJ 科目）
CREATE OR REPLACE PROCEDURE "MTC_CA_P50_FINALIZE" (IN RunId BIGINT, IN Iters INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE tailMax DECIMAL(19,6);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    tailMax := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('TAIL_MAX', :fc), '0'), 19, 6);
    CALL "MTC_CA_P41_PRICE"(:RunId, :Iters);

    -- 形态转换：P41 重新给 O05 定价后，I05 再对齐
    UPDATE T0 SET T0."MatAmt" = -B."MatAmt", T0."MfgAmt" = -B."MfgAmt", T0."LabAmt" = -B."LabAmt", T0."SubAmt" = -B."SubAmt",
                  T0."Amount" = -B."Amount"
      FROM "MTC_CA_R_LINE" T0
      JOIN "MTC_CA_R_PAIR" P ON P."RunId" = T0."RunId" AND P."LineId" = T0."LineId" AND P."PairType" = 'TRF'
      JOIN "MTC_CA_R_LINE" B ON B."RunId" = T0."RunId" AND B."LineId" = P."SrcLineId"
     WHERE T0."RunId" = :RunId;

    -- 进销存：数量为正是入库、为负是出库；数量为 0 的（发票差额、重估）按交易类型方向
    UPDATE "MTC_CA_R_ITEM"
       SET "InQty" = 0, "InMat" = 0, "InMfg" = 0, "InLab" = 0, "InSub" = 0,
           "OutQty" = 0, "OutMat" = 0, "OutMfg" = 0, "OutLab" = 0, "OutSub" = 0, "Flags" = NULL, "TailAmt" = 0
     WHERE "RunId" = :RunId;
    flow = SELECT "ItemCode",
                  CASE WHEN "Qty" > 0 THEN 'I' WHEN "Qty" < 0 THEN 'O'
                       WHEN LEFT(IFNULL("TransCode", 'I'), 1) = 'O' AND "TransCode" <> 'O06' THEN 'O' ELSE 'I' END AS "Dir",
                  "Qty", "MatAmt", "MfgAmt", "LabAmt", "SubAmt"
             FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId;
    UPDATE T0 SET T0."InQty" = S."InQty", T0."InMat" = S."InMat", T0."InMfg" = S."InMfg", T0."InLab" = S."InLab", T0."InSub" = S."InSub",
                  T0."OutQty" = S."OutQty", T0."OutMat" = S."OutMat", T0."OutMfg" = S."OutMfg", T0."OutLab" = S."OutLab", T0."OutSub" = S."OutSub"
      FROM "MTC_CA_R_ITEM" T0
      JOIN (SELECT "ItemCode",
                   SUM(CASE WHEN "Dir" = 'I' THEN "Qty" ELSE 0 END) AS "InQty",
                   SUM(CASE WHEN "Dir" = 'I' THEN "MatAmt" ELSE 0 END) AS "InMat", SUM(CASE WHEN "Dir" = 'I' THEN "MfgAmt" ELSE 0 END) AS "InMfg",
                   SUM(CASE WHEN "Dir" = 'I' THEN "LabAmt" ELSE 0 END) AS "InLab", SUM(CASE WHEN "Dir" = 'I' THEN "SubAmt" ELSE 0 END) AS "InSub",
                   SUM(CASE WHEN "Dir" = 'O' THEN "Qty" ELSE 0 END) AS "OutQty",
                   SUM(CASE WHEN "Dir" = 'O' THEN "MatAmt" ELSE 0 END) AS "OutMat", SUM(CASE WHEN "Dir" = 'O' THEN "MfgAmt" ELSE 0 END) AS "OutMfg",
                   SUM(CASE WHEN "Dir" = 'O' THEN "LabAmt" ELSE 0 END) AS "OutLab", SUM(CASE WHEN "Dir" = 'O' THEN "SubAmt" ELSE 0 END) AS "OutSub"
              FROM :flow GROUP BY "ItemCode") S
        ON S."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId;
    UPDATE "MTC_CA_R_ITEM"
       SET "EndQty" = "OpenQty" + "InQty" + "OutQty",
           "EndMat" = "OpenMat" + "InMat" + "OutMat", "EndMfg" = "OpenMfg" + "InMfg" + "OutMfg",
           "EndLab" = "OpenLab" + "InLab" + "OutLab", "EndSub" = "OpenSub" + "InSub" + "OutSub"
     WHERE "RunId" = :RunId;

    -- 尾差（RND-01）：不挤公摊材料行（费用已分摊）和形态转换转出行（要与转入相等）
    cand = SELECT L."LineId", L."ItemCode",
                  ROW_NUMBER() OVER (PARTITION BY L."ItemCode" ORDER BY ABS(L."Qty") DESC, L."LineId") AS "Rn"
             FROM "MTC_CA_R_LINE" L
             JOIN "MTC_CA_R_ITEM" I ON I."RunId" = L."RunId" AND I."ItemCode" = L."ItemCode"
            WHERE L."RunId" = :RunId AND L."Cat" = 'WAVG' AND L."Qty" < 0 AND L."IsShared" = 'N'
              AND L."LineId" NOT IN (SELECT "SrcLineId" FROM "MTC_CA_R_PAIR" WHERE "RunId" = :RunId AND "SrcLineId" IS NOT NULL)
              AND I."EndQty" = 0
              AND (I."EndMat" <> 0 OR I."EndMfg" <> 0 OR I."EndLab" <> 0 OR I."EndSub" <> 0);
    UPDATE T0 SET T0."MatAmt" = T0."MatAmt" - I."EndMat", T0."MfgAmt" = T0."MfgAmt" - I."EndMfg",
                  T0."LabAmt" = T0."LabAmt" - I."EndLab", T0."SubAmt" = T0."SubAmt" - I."EndSub",
                  T0."Amount" = T0."Amount" - I."EndMat" - I."EndMfg" - I."EndLab" - I."EndSub",
                  T0."PriceSrc" = T0."PriceSrc" || '；含期末尾差', T0."RuleId" = 'RND-01'
      FROM "MTC_CA_R_LINE" T0
      JOIN :cand C ON C."LineId" = T0."LineId" AND C."Rn" = 1
      JOIN "MTC_CA_R_ITEM" I ON I."RunId" = T0."RunId" AND I."ItemCode" = T0."ItemCode"
     WHERE T0."RunId" = :RunId;
    UPDATE T0 SET T0."OutMat" = T0."OutMat" - T0."EndMat", T0."OutMfg" = T0."OutMfg" - T0."EndMfg",
                  T0."OutLab" = T0."OutLab" - T0."EndLab", T0."OutSub" = T0."OutSub" - T0."EndSub",
                  T0."EndMat" = 0, T0."EndMfg" = 0, T0."EndLab" = 0, T0."EndSub" = 0
      FROM "MTC_CA_R_ITEM" T0
      JOIN :cand C ON C."ItemCode" = T0."ItemCode" AND C."Rn" = 1
     WHERE T0."RunId" = :RunId;

    -- 零库存尾差结转（TAIL-01）：仍是期末数量 0、金额不为 0（没有可挤的出库行），总额和四项都在 ±TAIL_MAX 以内的，
    -- 计入出库方向、期末清零，金额记 TailAmt，由 P70 生成 JZ04 凭证；超过的留在期末，POST-07 报出
    UPDATE "MTC_CA_R_ITEM"
       SET "TailAmt" = -("EndMat" + "EndMfg" + "EndLab" + "EndSub"),
           "OutMat" = "OutMat" - "EndMat", "OutMfg" = "OutMfg" - "EndMfg", "OutLab" = "OutLab" - "EndLab", "OutSub" = "OutSub" - "EndSub",
           "EndMat" = 0, "EndMfg" = 0, "EndLab" = 0, "EndSub" = 0
     WHERE "RunId" = :RunId AND "EndQty" = 0
       AND ("EndMat" <> 0 OR "EndMfg" <> 0 OR "EndLab" <> 0 OR "EndSub" <> 0)
       AND ABS("EndMat" + "EndMfg" + "EndLab" + "EndSub") <= :tailMax
       AND ABS("EndMat") <= :tailMax AND ABS("EndMfg") <= :tailMax AND ABS("EndLab") <= :tailMax AND ABS("EndSub") <= :tailMax;

    UPDATE "MTC_CA_R_ITEM"
       SET "EndAmount" = "EndMat" + "EndMfg" + "EndLab" + "EndSub",
           "Flags" = NULLIF(
                     CASE WHEN "EndQty" < 0 THEN '负库存；' ELSE '' END
                  || CASE WHEN "OutQty" <> 0 AND "PriceSrc" = 'QCPRICE' THEN '用了维护价兜底；' ELSE '' END
                  || CASE WHEN "OutQty" <> 0 AND "PriceSrc" = 'OPEN' THEN '本期无计价入库，用期初单价；' ELSE '' END
                  || CASE WHEN "OutQty" <> 0 AND "PriceSrc" = 'ZERO' THEN '无价；' ELSE '' END
                  -- 没有任何价格来源时按加权价的入库（如无原单销售退货、盘盈）都是 0 成本，没有出库也报（用户 2026-10-29）
                  || CASE WHEN "InQty" > 0 AND "PriceSrc" = 'ZERO' THEN '按 0 成本入库（没有期初、计价入库和维护价）；' ELSE '' END
                  || CASE WHEN "EndQty" = 0 AND ("EndMat" <> 0 OR "EndMfg" <> 0 OR "EndLab" <> 0 OR "EndSub" <> 0)
                          THEN '期末数量为 0 但金额不为 0，没有可挤尾差的出库行，且超过尾差结转上限 TAIL_MAX；' ELSE '' END, '')
     WHERE "RunId" = :RunId;

    -- 料工费占比（用户 2026-10-18）：期初、入库、出库、期末各自的材料 / 人工 / 制造 / 委外 ÷ 该项四项合计 × 100，保留 4 位；
    -- 四项合计为 0（绝对值不超过 0.005）时为空。出库四项都是负数，比值仍为正。物料组小计、合计的占比由执行台按汇总金额现算
    UPDATE "MTC_CA_R_ITEM"
       SET
           "RtOpenMat" = CASE WHEN ABS("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") > 0.005 THEN ROUND("OpenMat" / ("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") * 100, 4) END,
           "RtOpenLab" = CASE WHEN ABS("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") > 0.005 THEN ROUND("OpenLab" / ("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") * 100, 4) END,
           "RtOpenMfg" = CASE WHEN ABS("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") > 0.005 THEN ROUND("OpenMfg" / ("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") * 100, 4) END,
           "RtOpenSub" = CASE WHEN ABS("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") > 0.005 THEN ROUND("OpenSub" / ("OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub") * 100, 4) END,
           "RtInMat" = CASE WHEN ABS("InMat" + "InMfg" + "InLab" + "InSub") > 0.005 THEN ROUND("InMat" / ("InMat" + "InMfg" + "InLab" + "InSub") * 100, 4) END,
           "RtInLab" = CASE WHEN ABS("InMat" + "InMfg" + "InLab" + "InSub") > 0.005 THEN ROUND("InLab" / ("InMat" + "InMfg" + "InLab" + "InSub") * 100, 4) END,
           "RtInMfg" = CASE WHEN ABS("InMat" + "InMfg" + "InLab" + "InSub") > 0.005 THEN ROUND("InMfg" / ("InMat" + "InMfg" + "InLab" + "InSub") * 100, 4) END,
           "RtInSub" = CASE WHEN ABS("InMat" + "InMfg" + "InLab" + "InSub") > 0.005 THEN ROUND("InSub" / ("InMat" + "InMfg" + "InLab" + "InSub") * 100, 4) END,
           "RtOutMat" = CASE WHEN ABS("OutMat" + "OutMfg" + "OutLab" + "OutSub") > 0.005 THEN ROUND("OutMat" / ("OutMat" + "OutMfg" + "OutLab" + "OutSub") * 100, 4) END,
           "RtOutLab" = CASE WHEN ABS("OutMat" + "OutMfg" + "OutLab" + "OutSub") > 0.005 THEN ROUND("OutLab" / ("OutMat" + "OutMfg" + "OutLab" + "OutSub") * 100, 4) END,
           "RtOutMfg" = CASE WHEN ABS("OutMat" + "OutMfg" + "OutLab" + "OutSub") > 0.005 THEN ROUND("OutMfg" / ("OutMat" + "OutMfg" + "OutLab" + "OutSub") * 100, 4) END,
           "RtOutSub" = CASE WHEN ABS("OutMat" + "OutMfg" + "OutLab" + "OutSub") > 0.005 THEN ROUND("OutSub" / ("OutMat" + "OutMfg" + "OutLab" + "OutSub") * 100, 4) END,
           "RtEndMat" = CASE WHEN ABS("EndMat" + "EndMfg" + "EndLab" + "EndSub") > 0.005 THEN ROUND("EndMat" / ("EndMat" + "EndMfg" + "EndLab" + "EndSub") * 100, 4) END,
           "RtEndLab" = CASE WHEN ABS("EndMat" + "EndMfg" + "EndLab" + "EndSub") > 0.005 THEN ROUND("EndLab" / ("EndMat" + "EndMfg" + "EndLab" + "EndSub") * 100, 4) END,
           "RtEndMfg" = CASE WHEN ABS("EndMat" + "EndMfg" + "EndLab" + "EndSub") > 0.005 THEN ROUND("EndMfg" / ("EndMat" + "EndMfg" + "EndLab" + "EndSub") * 100, 4) END,
           "RtEndSub" = CASE WHEN ABS("EndMat" + "EndMfg" + "EndLab" + "EndSub") > 0.005 THEN ROUND("EndSub" / ("EndMat" + "EndMfg" + "EndLab" + "EndSub") * 100, 4) END
     WHERE "RunId" = :RunId;

    UPDATE "MTC_CA_R_LINE" SET "Price" = "Amount" / NULLIF("Qty", 0) WHERE "RunId" = :RunId;
END

@@
-- @stmt 新框架 14_p50_p60_p65.sql #2
-- P60：计算后校验（结果写 R_CHECK，Stage = POST）和指标快照（RUN_KPI，每次运行都保留）
CREATE OR REPLACE PROCEDURE "MTC_CA_P60_POSTCHECK" (IN RunId BIGINT, OUT FailCnt INT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE boot NVARCHAR(10); DECLARE prev NVARCHAR(10);
    DECLARE tailMax DECIMAL(19,6); DECLARE tailWarn DECIMAL(19,6); DECLARE pjPct DECIMAL(19,6); DECLARE pjAmt DECIMAL(19,6);
    DECLARE fdPct DECIMAL(19,6); DECLARE fdAmt DECIMAL(19,6); DECLARE fdMon INT; DECLARE fdN INT; DECLARE fdMsg NVARCHAR(1000);
    DECLARE idPct DECIMAL(19,6); DECLARE idAmt DECIMAL(19,6);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :fc);
    tailMax := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('TAIL_MAX', :fc), '0.02'), 19, 6);
    tailWarn := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('TAIL_WARN', :fc), '0.1'), 19, 6);
    pjPct := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('PRICE_JUMP_PCT', :fc), '30'), 19, 6);
    pjAmt := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('PRICE_JUMP_AMT', :fc), '100'), 19, 6);
    fdPct := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('FEE_DEV_PCT', :fc), '30'), 19, 6);
    fdAmt := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('FEE_DEV_AMT', :fc), '50000'), 19, 6);
    fdMon := TO_INTEGER(IFNULL("MTC_CA_F_PARAM"('FEE_BASE_MONTHS', :fc), '6'));
    idPct := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('ISSUE_DEV_PCT', :fc), '10'), 19, 6);
    idAmt := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('ISSUE_DEV_AMT', :fc), '500'), 19, 6);
    SELECT MAX("Code") INTO prev FROM "OFPR" WHERE "Code" < :fc;

    -- POST-01 期末数量 = B1（计价仓库 OIVL 截至期末）
    b1 = SELECT P0."ItemCode", SUM(P0."InQty" - P0."OutQty") AS "Qty"
           FROM "OIVL" P0 JOIN "MTC_CA_V_WHS" W ON W."WhsCode" = P0."LocCode" AND W."IsCost" = 'Y'
          WHERE P0."DocDate" <= :d1
          GROUP BY P0."ItemCode";
    t01 = SELECT K."ItemCode" AS "KeyCode",
                 '新框架期末 ' || TO_NVARCHAR(IFNULL(I."EndQty", 0)) || '，B1 ' || TO_NVARCHAR(IFNULL(B."Qty", 0)) AS "Info"
            FROM (SELECT "ItemCode" FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId UNION SELECT "ItemCode" FROM :b1) K
            LEFT JOIN "MTC_CA_R_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = K."ItemCode"
            LEFT JOIN :b1 B ON B."ItemCode" = K."ItemCode"
           WHERE ABS(IFNULL(I."EndQty", 0) - IFNULL(B."Qty", 0)) > 0.000001;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-01', :t01, NULL);

    -- POST-02 进销存四项平衡
    t02 = SELECT "ItemCode" AS "KeyCode", '期初 + 入 + 出 ≠ 期末' AS "Info"
            FROM "MTC_CA_R_ITEM"
           WHERE "RunId" = :RunId
             AND (ABS("OpenMat" + "InMat" + "OutMat" - "EndMat") > 0.01 OR ABS("OpenMfg" + "InMfg" + "OutMfg" - "EndMfg") > 0.01
               OR ABS("OpenLab" + "InLab" + "OutLab" - "EndLab") > 0.01 OR ABS("OpenSub" + "InSub" + "OutSub" - "EndSub") > 0.01
               OR ABS("OpenQty" + "InQty" + "OutQty" - "EndQty") > 0.000001);
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-02', :t02, NULL);

    -- POST-03 费用守恒：池 = 已分摊 + 未分摊；未分摊报出（Q13）
    t03 = SELECT P."PoolCode" || '-' || P."Elem" AS "KeyCode",
                 '费用池 ' || TO_NVARCHAR(ROUND(P."Amt", 2)) || '，已分摊 ' || TO_NVARCHAR(IFNULL(A."Amt", 0)) || '，未分摊 '
                 || TO_NVARCHAR(ROUND(P."Amt" - IFNULL(A."Amt", 0), 2)) AS "Info"
            FROM (SELECT "PoolCode", "Elem", SUM("Amount") AS "Amt" FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId GROUP BY "PoolCode", "Elem") P
            LEFT JOIN (SELECT "PoolCode", "Elem", SUM("Amount") AS "Amt" FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :RunId GROUP BY "PoolCode", "Elem") A
              ON A."PoolCode" = P."PoolCode" AND A."Elem" = P."Elem"
           WHERE ABS(P."Amt" - IFNULL(A."Amt", 0)) > 0.01;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-03', :t03, NULL);

    -- POST-04 订单勾稽：累计领料 = 累计结转 + 在产品 + 关单差异；本期关单的订单在产品为 0
    t04 = SELECT "MTC_CA_F_DOCKEY"(M."OrderType", M."OrderEntry") || '-' || M."ItemCode" AS "KeyCode", '累计领料 ≠ 累计结转 + 在产品 + 关单差异' AS "Info"
            FROM "MTC_CA_R_ORDER_MAT" M
           WHERE M."RunId" = :RunId
             AND ABS(M."OpenIssMat" + M."IssMat" + M."OpenIssMfg" + M."IssMfg" + M."OpenIssLab" + M."IssLab" + M."OpenIssSub" + M."IssSub"
                     - (M."OpenCarMat" + M."CarMat" + M."OpenCarMfg" + M."CarMfg" + M."OpenCarLab" + M."CarLab" + M."OpenCarSub" + M."CarSub")
                     - (M."WipMat" + M."WipMfg" + M."WipLab" + M."WipSub") - (M."ClsMat" + M."ClsMfg" + M."ClsLab" + M."ClsSub")) > 0.01
          UNION ALL
          SELECT "MTC_CA_F_DOCKEY"("OrderType", "OrderEntry"), '本期关单但在产品不为 0'
            FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId AND "ClosedInFc" = 'Y' AND ABS("WipAmt") > 0.01
          UNION ALL
          SELECT "MTC_CA_F_DOCKEY"(O."OrderType", O."OrderEntry"), '完工入库行合计 ≠ 订单完工成本'
            FROM "MTC_CA_R_ORDER" O
            JOIN (SELECT "OrderType", "OrderEntry", SUM("Amount") AS "Amt" FROM "MTC_CA_R_LINE"
                   WHERE "RunId" = :RunId AND "Cat" = 'RCPT' GROUP BY "OrderType", "OrderEntry") L
              ON L."OrderType" = O."OrderType" AND L."OrderEntry" = O."OrderEntry"
           WHERE O."RunId" = :RunId AND O."RecvQty" <> 0 AND ABS(L."Amt" - O."CostAmt") > 0.05;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-04', :t04, NULL);

    -- POST-05 配对：I05 = −O05；退货、取消单按原单成本
    -- 明细按单据写（用户 2026-10-13：只有行号看不出是什么单）：KeyCode = ObjType-DocNum-LineNum，与 PRE 检查一致；
    -- Info 开头写单据类型中文名、取消单 / 被取消、物料、交易类型
    t05r = SELECT P."LineId", P."PairType" || '：金额与来源行不对应' AS "Msg"
             FROM "MTC_CA_R_PAIR" P
             JOIN "MTC_CA_R_LINE" A ON A."RunId" = P."RunId" AND A."LineId" = P."LineId"
             LEFT JOIN "MTC_CA_R_LINE" B ON B."RunId" = P."RunId" AND B."LineId" = P."SrcLineId"
            WHERE P."RunId" = :RunId
              AND ((P."PairType" = 'TRF' AND ABS(A."Amount" + IFNULL(B."Amount", 0)) > 0.01)
                OR (P."PairType" IN ('SRT', 'CNL') AND P."SrcLineId" IS NULL
                    AND ABS(A."Amount" - ROUND((IFNULL(P."UMat", 0) + IFNULL(P."UMfg", 0) + IFNULL(P."ULab", 0) + IFNULL(P."USub", 0)) * A."Qty", 2)) > 0.05))
           UNION ALL
           SELECT "LineId", '找不到原交货成本或配对，按加权价兜底（' || "RuleId" || '）'
             FROM "MTC_CA_R_LINE"
            WHERE "RunId" = :RunId AND ("RuleId" = 'SRT-02' OR ("RuleId" = 'TRF-01' AND "Cat" = 'WAVG'))
           -- 取消单：原单在本期、按加权价的与原单同价相抵，不报；只报本期找不到原单的（2026-10-14）
           UNION ALL
           SELECT T."LineId", '取消单本期找不到原单，按加权价兜底（CNL-01）'
             FROM "MTC_CA_R_LINE" T
             JOIN "MTC_CA_S_LINE" S ON S."RunId" = T."RunId" AND S."LineId" = T."LineId"
            WHERE T."RunId" = :RunId AND T."RuleId" = 'CNL-01' AND T."Cat" = 'WAVG'
              AND NOT EXISTS (SELECT 1 FROM "MTC_CA_S_LINE" O
                               WHERE O."RunId" = S."RunId" AND O."ObjType" = S."ObjType" AND O."ItemCode" = S."ItemCode"
                                 AND TO_NVARCHAR(O."DocEntry") = S."BaseEntry" AND TO_NVARCHAR(O."LineNum") = S."BaseLine");
    t05 = SELECT IFNULL(S."ObjType" || '-DocNum ' || S."DocNum" || '-LineNum ' || IFNULL(TO_NVARCHAR(S."LineNum"), ''), 'LineId ' || TO_NVARCHAR(T."LineId")) AS "KeyCode",
                 CASE S."ObjType" WHEN '13' THEN '应收发票' WHEN '14' THEN '应收贷项' WHEN '15' THEN '销售交货' WHEN '16' THEN '销售退货'
                                  WHEN '18' THEN '应付发票' WHEN '19' THEN '应付贷项' WHEN '20' THEN '采购收货' WHEN '21' THEN '采购退货'
                                  WHEN '59' THEN '收货单' WHEN '60' THEN '发货单' WHEN '67' THEN '库存转储' WHEN '162' THEN '库存重估'
                                  ELSE IFNULL(S."ObjType", '') END
                 || CASE S."Canceled" WHEN 'C' THEN '（取消单）' WHEN 'Y' THEN '（已被取消）' ELSE '' END
                 || ' ' || IFNULL(S."DocNum", '') || ' 第 ' || IFNULL(TO_NVARCHAR(S."LineNum"), '') || ' 行，物料 ' || IFNULL(S."ItemCode", '')
                 || '，' || IFNULL(S."TransCode", '') || '：' || T."Msg" AS "Info"
            FROM :t05r T
            LEFT JOIN "MTC_CA_S_LINE" S ON S."RunId" = :RunId AND S."LineId" = T."LineId";
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-05', :t05, NULL);

    -- POST-06 委外对账移到 P75（MTC_CA_F_RECON，要用到凭证底稿，用户 2026-10-13）

    -- POST-07 物料标记：负库存、兜底价、无价、尾差无处挤
    t07 = SELECT "ItemCode" AS "KeyCode", "Flags" AS "Info" FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId AND "Flags" IS NOT NULL;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-07', :t07, NULL);

    -- POST-17 盘盈等按加权价的入库是 0 成本：物料算出的单价为 0（只有 0 金额收货，或期初数量有、金额为 0），固定只警告（用户 2026-11-06）。
    -- 完全没有单价来源的（PriceSrc = ZERO）归 POST-07
    t17 = SELECT L."ItemCode" AS "KeyCode", '单价为 0，' || L."Trans" || ' 按加权价入库 ' || TO_NVARCHAR(L."Qty") || '，都是 0 成本；请确认入库金额，或补期初维护价' AS "Info"
            FROM (SELECT "ItemCode", SUM("Qty") AS "Qty", STRING_AGG("TransCode", '、') AS "Trans"
                    FROM (SELECT "ItemCode", IFNULL("TransCode", '') AS "TransCode", SUM("Qty") AS "Qty" FROM "MTC_CA_R_LINE"
                           WHERE "RunId" = :RunId AND "Cat" = 'WAVG' AND "Qty" > 0 GROUP BY "ItemCode", IFNULL("TransCode", ''))
                   GROUP BY "ItemCode") L
            JOIN "MTC_CA_R_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = L."ItemCode"
           WHERE I."PriceSrc" IN ('WAVG', 'OPEN') AND I."PMat" + I."PMfg" + I."PLab" + I."PSub" = 0;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-17', :t17, NULL);

    -- POST-18 领料完整性（用户 2026-11-11，只警告）：订单本期领料（R_ORDER_MAT）是从挂订单的领料 / 退料行汇总的，这里查掉出去的行：
    --   ① 按订单核对 收发存明细的领料 / 退料行合计 = 订单本期领料（不含加工费）；订单不在本期订单清单时这些行的金额进不了在产品
    --   ② 生产领料（B03）、完工入库（B01）类业务没挂订单的行：按普通出入库计价，不进任何订单
    iss = SELECT "OrderType", "OrderEntry", -SUM("Amount") AS "Amt", COUNT(*) AS "Cnt"
            FROM "MTC_CA_R_LINE" WHERE "RunId" = :RunId AND "Cat" IN ('ISSUE', 'RTN304') GROUP BY "OrderType", "OrderEntry";
    omat = SELECT "OrderType", "OrderEntry", SUM("IssMat" + "IssMfg" + "IssLab" + "IssSub") AS "Amt"
             FROM "MTC_CA_R_ORDER_MAT" WHERE "RunId" = :RunId AND "ItemCode" <> '#SUBFEE' GROUP BY "OrderType", "OrderEntry";
    t18 = SELECT "MTC_CA_F_DOCKEY"(K."OrderType", K."OrderEntry") AS "KeyCode",
                 CASE WHEN O."OrderEntry" IS NULL
                      THEN '订单不在本期订单清单：领料 / 退料 ' || TO_NVARCHAR(IFNULL(L."Cnt", 0)) || ' 行，金额 ' || TO_NVARCHAR(ROUND(IFNULL(L."Amt", 0), 2)) || ' 没进在产品'
                      ELSE '收发存明细领料 ' || TO_NVARCHAR(ROUND(IFNULL(L."Amt", 0), 2)) || '，订单本期领料 ' || TO_NVARCHAR(ROUND(IFNULL(M."Amt", 0), 2))
                           || '，差 ' || TO_NVARCHAR(ROUND(IFNULL(L."Amt", 0) - IFNULL(M."Amt", 0), 2)) END AS "Info"
            FROM (SELECT "OrderType", "OrderEntry" FROM :iss UNION SELECT "OrderType", "OrderEntry" FROM :omat) K
            LEFT JOIN :iss L ON L."OrderType" = K."OrderType" AND L."OrderEntry" = K."OrderEntry"
            LEFT JOIN :omat M ON M."OrderType" = K."OrderType" AND M."OrderEntry" = K."OrderEntry"
            LEFT JOIN "MTC_CA_R_ORDER" O ON O."RunId" = :RunId AND O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
           WHERE O."OrderEntry" IS NULL OR ABS(IFNULL(L."Amt", 0) - IFNULL(M."Amt", 0)) > 0.05
          UNION ALL
          SELECT "MTC_CA_F_DOCKEY"(S."ObjType", S."DocEntry") || '-LineNum ' || IFNULL(TO_NVARCHAR(S."LineNum"), ''),
                 CASE WHEN S."BusiClass" = 'B03' THEN '生产领料类' ELSE '完工入库类' END || '业务（' || IFNULL(S."BusiType", '') || '）没挂订单：'
                 || L."ItemCode" || ' 数量 ' || TO_NVARCHAR(L."Qty") || '，金额 ' || TO_NVARCHAR(ROUND(L."Amount", 2)) || '，按普通出入库计价，不进任何订单'
            FROM "MTC_CA_R_LINE" L JOIN "MTC_CA_S_LINE" S ON S."RunId" = L."RunId" AND S."LineId" = L."LineId"
           WHERE L."RunId" = :RunId AND S."BusiClass" IN ('B01', 'B03') AND S."OrderEntry" IS NULL AND L."Cat" <> 'NOCOST';
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-18', :t18, NULL);

    -- POST-19 完工没有材料（用户 2026-11-11，只警告）：本期有完工入库，本级材料 ≤ 0（本级材料 = 完工成本 − 本级分摊制造 − 人工 − 加工费结转，同 R02）：
    --   没领料就入库、领料挂错订单，或退料多于领料。“累计完工达计划仍有在产品”不用另查：这时结转比例为 1（P30 Ratio），在产品必然为 0
    t19 = SELECT "MTC_CA_F_DOCKEY"(O."OrderType", O."OrderEntry") AS "KeyCode",
                 O."ItemCode" || ' 本期完工 ' || TO_NVARCHAR(O."RecvQty") || '，本级材料 '
                 || TO_NVARCHAR(ROUND(O."CostAmt" - O."AllocMfg" - O."AllocLab" - IFNULL(F."CarSub", 0), 2))
                 || CASE WHEN M."OrderEntry" IS NULL THEN '，订单没有任何领料' ELSE '' END AS "Info"
            FROM "MTC_CA_R_ORDER" O
            LEFT JOIN "MTC_CA_R_ORDER_MAT" F ON F."RunId" = O."RunId" AND F."OrderType" = O."OrderType" AND F."OrderEntry" = O."OrderEntry" AND F."ItemCode" = '#SUBFEE'
            LEFT JOIN (SELECT DISTINCT "OrderType", "OrderEntry" FROM "MTC_CA_R_ORDER_MAT"
                        WHERE "RunId" = :RunId AND "ItemCode" <> '#SUBFEE' AND "OpenIssQty" + "IssQty" <> 0) M
              ON M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
           WHERE O."RunId" = :RunId AND O."RecvQty" > 0
             AND O."CostAmt" - O."AllocMfg" - O."AllocLab" - IFNULL(F."CarSub", 0) <= 0.005;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-19', :t19, NULL);

    -- POST-20 单耗偏离（用户 2026-11-11，只警告）：订单 × 材料，累计净领料数量 与 按计划应领 = 订单用料计划数（S_ORDER_LINE.PlannedQty，WOR1 / @MTC_WOR1）÷ 订单计划数 × 累计完工数 比较，
    --   口径同 P30 结转比例的单位计划用量；用订单自己的用料计划而不是当前 BOM，返工单、委外单也能比。
    --   少领：本期有完工或本期关单的订单都比；超领、计划外领料（订单用料里没有或计划为 0 的材料）只比已完工的（本期关单，或累计完工 ≥ 计划数），
    --   没完工前多领的料还在产线上。影响金额 = 偏离数量 × 物料本期单价；偏离比例 > ISSUE_DEV_PCT 且影响金额 ≥ ISSUE_DEV_AMT 才报。
    --   不含加工费；订单计划数 ≤ 0、计划用量为负（联产品 / 副产品）的不比。
    pl = SELECT "OrderType", "OrderEntry", "ItemCode", SUM("PlannedQty") AS "Qty"
           FROM "MTC_CA_S_ORDER_LINE" WHERE "RunId" = :RunId GROUP BY "OrderType", "OrderEntry", "ItemCode";
    dev = SELECT O."OrderType", O."OrderEntry", O."ItemCode" AS "Prod", K."ItemCode",
                 CASE WHEN O."ClosedInFc" = 'Y' OR O."PrevRecvQty" + O."RecvQty" >= O."PlannedQty" - 0.000001 THEN 'Y' ELSE 'N' END AS "Done",
                 IFNULL(M."OpenIssQty" + M."IssQty", 0) AS "Act",
                 IFNULL((O."PrevRecvQty" + O."RecvQty") * P."Qty" / O."PlannedQty", 0) AS "Need",
                 IFNULL(I."PMat" + I."PMfg" + I."PLab" + I."PSub", 0) AS "Price"
            FROM "MTC_CA_R_ORDER" O
            JOIN (SELECT "OrderType", "OrderEntry", "ItemCode" FROM :pl
                  UNION SELECT "OrderType", "OrderEntry", "ItemCode" FROM "MTC_CA_R_ORDER_MAT" WHERE "RunId" = :RunId AND "ItemCode" <> '#SUBFEE') K
              ON K."OrderType" = O."OrderType" AND K."OrderEntry" = O."OrderEntry"
            LEFT JOIN :pl P ON P."OrderType" = K."OrderType" AND P."OrderEntry" = K."OrderEntry" AND P."ItemCode" = K."ItemCode"
            LEFT JOIN "MTC_CA_R_ORDER_MAT" M ON M."RunId" = O."RunId" AND M."OrderType" = K."OrderType" AND M."OrderEntry" = K."OrderEntry" AND M."ItemCode" = K."ItemCode"
            LEFT JOIN "MTC_CA_R_ITEM" I ON I."RunId" = O."RunId" AND I."ItemCode" = K."ItemCode"
           WHERE O."RunId" = :RunId AND IFNULL(O."PlannedQty", 0) > 0 AND IFNULL(P."Qty", 0) >= 0
             AND (O."RecvQty" > 0 OR (O."ClosedInFc" = 'Y' AND O."PrevRecvQty" + O."RecvQty" > 0));
    t20 = SELECT "MTC_CA_F_DOCKEY"("OrderType", "OrderEntry") || '-' || "ItemCode" AS "KeyCode",
                 CASE WHEN "Need" = 0 THEN '计划外领料（订单用料里没有，替代料或多领）' WHEN "Act" < "Need" THEN '少领' ELSE '超领' END
                 || '：产品 ' || "Prod" || '，累计领料 ' || TO_NVARCHAR(ROUND("Act", 6)) || '，按计划应领 ' || TO_NVARCHAR(ROUND("Need", 6))
                 || CASE WHEN "Need" <> 0 THEN '，偏离 ' || TO_NVARCHAR(ROUND(("Act" - "Need") * 100 / "Need", 1)) || '%' ELSE '' END
                 || '，影响约 ' || TO_NVARCHAR(ROUND(ABS("Act" - "Need") * "Price", 2)) AS "Info"
            FROM :dev
           WHERE ABS("Act" - "Need") * "Price" >= :idAmt
             AND (("Need" = 0 AND "Done" = 'Y' AND "Act" > 0)
               OR ("Need" > 0 AND "Act" < "Need" AND ("Need" - "Act") * 100 / "Need" > :idPct)
               OR ("Need" > 0 AND "Done" = 'Y' AND "Act" > "Need" AND ("Act" - "Need") * 100 / "Need" > :idPct));
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-20', :t20, NULL);

    -- POST-14 物料成本异常（用户 2026-10-14）：单价、数量、金额异常，含小尾差和价格大幅波动；原为只警告，2026-10-14 起计算后校验不通过一律阻断。
    -- 单价 P = 本期加权单价四项之和；期初单价 = 期初金额 ÷ 期初数量。阈值：TAIL_MAX（零库存尾差）、TAIL_WARN（挤入出库行的尾差）、PRICE_JUMP_PCT（%）、PRICE_JUMP_AMT（影响金额下限）
    itm = SELECT "ItemCode", "OpenQty", "OpenMat" + "OpenMfg" + "OpenLab" + "OpenSub" AS "OpenAmt",
                 "PMat" + "PMfg" + "PLab" + "PSub" AS "P", "OutQty", "EndQty", "EndAmount", "TailAmt"
            FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId;
    t14 = -- ① 小尾差：零库存尾差已结转（TAIL-01）
          SELECT "ItemCode" AS "KeyCode", '小尾差：期末数量 0，尾差 ' || TO_NVARCHAR(ROUND(-"TailAmt", 2)) || ' 已结转（JZ04，TAIL-01）' AS "Info"
            FROM :itm WHERE ROUND("TailAmt", 2) <> 0
          -- ② 尾差偏大：挤进出库行的尾差（行金额 − 数量 × 单价）绝对值 ≥ TAIL_WARN（0.1）；
          --    这行吸收的是其他出库行四项分别四舍五入的累积差，行多时几分钱是正常的，不用 TAIL_MAX（用户 2026-10-14）
          UNION ALL
          SELECT L."ItemCode", '尾差偏大：' || IFNULL(S."ObjType" || '-' || S."DocNum" || '-' || TO_NVARCHAR(S."LineNum"), 'LineId ' || L."LineId")
                 || ' 挤入尾差 ' || TO_NVARCHAR(ROUND(L."Amount" - ROUND(L."Qty" * I."P", 2), 2))
            FROM "MTC_CA_R_LINE" L
            JOIN :itm I ON I."ItemCode" = L."ItemCode"
            LEFT JOIN "MTC_CA_S_LINE" S ON S."RunId" = L."RunId" AND S."LineId" = L."LineId"
           WHERE L."RunId" = :RunId AND (L."RuleId" = 'RND-01' OR L."PriceSrc" LIKE '%含期末尾差%')
             AND ABS(L."Amount" - ROUND(L."Qty" * I."P", 2)) >= :tailWarn
          -- ③ 期末数量 0 但金额不为 0（超过 TAIL_MAX，未结转）
          UNION ALL
          SELECT "ItemCode", '数量 0 金额不为 0：期末金额 ' || TO_NVARCHAR(ROUND("EndAmount", 2)) || '（超过尾差上限，未结转）'
            FROM :itm WHERE "EndQty" = 0 AND ROUND("EndAmount", 2) <> 0
          -- ④ 期末数量与金额方向不一致：有数量没金额、金额为负、负库存
          UNION ALL
          SELECT "ItemCode", CASE WHEN "EndQty" < 0 THEN '负库存：' WHEN "EndAmount" = 0 THEN '有数量无金额：' ELSE '金额为负：' END
                 || '期末数量 ' || TO_NVARCHAR(ROUND("EndQty", 6)) || '，金额 ' || TO_NVARCHAR(ROUND("EndAmount", 2))
            FROM :itm WHERE ("EndQty" > 0 AND "EndAmount" <= 0) OR "EndQty" < 0
          -- ⑤ 期末单价偏离本期加权单价（期末金额 ÷ 期末数量 与 P 相差超过 PRICE_JUMP_PCT，且金额差超过 PRICE_JUMP_AMT）
          UNION ALL
          SELECT "ItemCode", '期末单价偏离：期末单价 ' || TO_NVARCHAR(ROUND("EndAmount" / NULLIF("EndQty", 0), 4)) || '，本期加权单价 ' || TO_NVARCHAR(ROUND("P", 4))
                 || '，金额差 ' || TO_NVARCHAR(ROUND("EndAmount" - "EndQty" * "P", 2))
            FROM :itm
           WHERE "EndQty" > 0 AND "EndAmount" > 0 AND "P" > 0
             AND ABS("EndAmount" / NULLIF("EndQty", 0) - "P") / NULLIF("P", 0) * 100 > :pjPct AND ABS("EndAmount" - "EndQty" * "P") > :pjAmt
          -- ⑥ 价格波动：本期加权单价与期初单价相差超过 PRICE_JUMP_PCT，且影响金额（单价差 × 本期出库和期末数量）超过 PRICE_JUMP_AMT
          UNION ALL
          SELECT "ItemCode", '价格波动：期初单价 ' || TO_NVARCHAR(ROUND("OpenAmt" / NULLIF("OpenQty", 0), 4)) || ' → 本期 ' || TO_NVARCHAR(ROUND("P", 4))
                 || '（' || CASE WHEN "P" > "OpenAmt" / NULLIF("OpenQty", 0) THEN '+' ELSE '' END
                 || TO_NVARCHAR(ROUND(("P" - "OpenAmt" / NULLIF("OpenQty", 0)) / NULLIF("OpenAmt" / NULLIF("OpenQty", 0), 0) * 100, 1)) || '%），影响金额约 '
                 || TO_NVARCHAR(ROUND(ABS("P" - "OpenAmt" / NULLIF("OpenQty", 0)) * (ABS("OutQty") + ABS("EndQty")), 2))
            FROM :itm
           WHERE "OpenQty" > 0 AND "OpenAmt" > 0
             AND ABS("P" - "OpenAmt" / NULLIF("OpenQty", 0)) / NULLIF("OpenAmt" / NULLIF("OpenQty", 0), 0) * 100 > :pjPct
             AND ABS("P" - "OpenAmt" / NULLIF("OpenQty", 0)) * (ABS("OutQty") + ABS("EndQty")) > :pjAmt
          -- ⑦ 有数量无金额的单据行（物料本期单价大于 0）
          UNION ALL
          SELECT L."ItemCode", '有数量无金额的单据行 ' || COUNT(*) || ' 行，数量合计 ' || TO_NVARCHAR(ROUND(SUM(L."Qty"), 6))
            FROM "MTC_CA_R_LINE" L JOIN :itm I ON I."ItemCode" = L."ItemCode"
           WHERE L."RunId" = :RunId AND L."Qty" <> 0 AND L."Amount" = 0 AND I."P" > 0
           GROUP BY L."ItemCode";
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-14', :t14, NULL);

    -- POST-16 费用波动（用户 2026-11-06，只警告）：制造 / 人工费用按全部和按池，与本期之前最近 FEE_BASE_MONTHS 个月比较。
    -- 基准取中位数，个别错误月份不影响；不含关单差异、历史委外转出（历史运行 H 的费用含关单差异，分不开）。
    -- 同时满足才报：① 金额偏离基准金额 ② 也偏离“基准单位费用 × 本期产量”，产量能解释的不报。偏离 = 差额 ≥ FEE_DEV_AMT 且比例 > FEE_DEV_PCT。
    -- 本期产量 0（费用全没了时分不到订单）只看 ①。产量 = 分摊到费用的订单的本期入库数，历史运行没有工时，所以不用工时。
    -- 全部从历史运行比起；池要等新框架积够 3 个月（历史运行只有虚拟池 LEGACY）。基准不足 3 个月的不比较。
    feeRun = SELECT "FcCode", "RunId"
               FROM (SELECT "FcCode", "RunId", ROW_NUMBER() OVER (ORDER BY "FcCode" DESC) AS "Rn"
                       FROM (SELECT "FcCode", IFNULL("PostRunId", "CalcRunId") AS "RunId" FROM "MTC_CA_PERIOD"
                              WHERE "FcCode" < :fc AND "FcCode" > :boot
                             UNION ALL
                             SELECT "FcCode", MAX("RunId") FROM "MTC_CA_RUN"
                              WHERE "RunType" = 'H' AND "Status" = 'OK' AND "FcCode" < :fc AND "FcCode" <= :boot
                              GROUP BY "FcCode")
                      WHERE "RunId" IS NOT NULL)
              WHERE "Rn" <= :fdMon;
    feeSrc = SELECT "RunId", "PoolCode", "Elem", SUM("Amount") AS "Amt"
               FROM "MTC_CA_R_POOL"
              WHERE ("RunId" = :RunId OR "RunId" IN (SELECT "RunId" FROM :feeRun)) AND "Src" NOT IN ('CLOSEDIF', 'WWHIST')
              GROUP BY "RunId", "PoolCode", "Elem";
    feeAmt = SELECT "RunId", "PoolCode", "Elem", "Amt" FROM :feeSrc WHERE "PoolCode" <> 'LEGACY'
             UNION ALL
             SELECT "RunId", '全部' AS "PoolCode", "Elem", SUM("Amt") AS "Amt" FROM :feeSrc GROUP BY "RunId", "Elem";
    -- 一张订单可以在几个池里，算全部时只数一次
    feeOrd = SELECT "RunId", "PoolCode", "Elem", "OrderType", "OrderEntry", "RecvQty"
               FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :RunId OR "RunId" IN (SELECT "RunId" FROM :feeRun);
    feeQty = SELECT "RunId", "PoolCode", "Elem", SUM("RecvQty") AS "Qty" FROM :feeOrd WHERE "PoolCode" <> 'LEGACY'
              GROUP BY "RunId", "PoolCode", "Elem"
             UNION ALL
             SELECT "RunId", '全部' AS "PoolCode", "Elem", SUM("Q") AS "Qty"
               FROM (SELECT "RunId", "Elem", "OrderType", "OrderEntry", MAX("RecvQty") AS "Q" FROM :feeOrd
                      GROUP BY "RunId", "Elem", "OrderType", "OrderEntry")
              GROUP BY "RunId", "Elem";
    feeBase = SELECT A."PoolCode", A."Elem", COUNT(*) AS "Months", MEDIAN(A."Amt") AS "BaseAmt",
                     MEDIAN(A."Amt" / NULLIF(Q."Qty", 0)) AS "BaseRate"
                FROM :feeAmt A
                LEFT JOIN :feeQty Q ON Q."RunId" = A."RunId" AND Q."PoolCode" = A."PoolCode" AND Q."Elem" = A."Elem"
               WHERE A."RunId" <> :RunId
               GROUP BY A."PoolCode", A."Elem"
              HAVING COUNT(*) >= 3;
    -- 从基准出发：本期这个池 / 要素完全没有费用时也要报
    feeCur = SELECT B."PoolCode", B."Elem", B."Months", B."BaseAmt", IFNULL(A."Amt", 0) AS "Amt", IFNULL(Q."Qty", 0) AS "Qty",
                    B."BaseRate", B."BaseRate" * IFNULL(Q."Qty", 0) AS "ExpAmt"
               FROM :feeBase B
               LEFT JOIN :feeAmt A ON A."RunId" = :RunId AND A."PoolCode" = B."PoolCode" AND A."Elem" = B."Elem"
               LEFT JOIN :feeQty Q ON Q."RunId" = :RunId AND Q."PoolCode" = B."PoolCode" AND Q."Elem" = B."Elem";
    t16 = SELECT "PoolCode" || '-' || "Elem" AS "KeyCode",
                 CASE "Elem" WHEN 'MFG' THEN '制造费用' WHEN 'LAB' THEN '人工费用' ELSE "Elem" END || ' 本期 ' || TO_NVARCHAR(ROUND("Amt", 2))
                 || '，近 ' || "Months" || ' 个月中位数 ' || TO_NVARCHAR(ROUND("BaseAmt", 2))
                 || '（' || CASE WHEN "Amt" > "BaseAmt" THEN '+' ELSE '' END || TO_NVARCHAR(ROUND(("Amt" - "BaseAmt") / NULLIF(ABS("BaseAmt"), 0) * 100, 1)) || '%）'
                 || CASE WHEN "Qty" = 0 OR "BaseRate" IS NULL THEN '；本期没有分摊到费用的入库'
                         ELSE '；按本期产量 ' || TO_NVARCHAR(ROUND("Qty", 2)) || ' 折算应约 ' || TO_NVARCHAR(ROUND("ExpAmt", 2))
                              || '（' || CASE WHEN "Amt" > "ExpAmt" THEN '+' ELSE '' END || TO_NVARCHAR(ROUND(("Amt" - "ExpAmt") / NULLIF(ABS("ExpAmt"), 0) * 100, 1)) || '%）' END AS "Info"
            FROM :feeCur
           WHERE ABS("Amt" - "BaseAmt") >= :fdAmt AND ABS("Amt" - "BaseAmt") / NULLIF(ABS("BaseAmt"), 0) * 100 > :fdPct
             AND ("Qty" = 0 OR "BaseRate" IS NULL
                  OR (ABS("Amt" - "ExpAmt") >= :fdAmt AND ABS("Amt" - "ExpAmt") / NULLIF(ABS("ExpAmt"), 0) * 100 > :fdPct));
    SELECT COUNT(*) INTO fdN FROM :feeRun;
    fdMsg := CASE WHEN :fdN < 3 THEN '基准月份只有 ' || :fdN || ' 个，不足 3 个月，未比较' ELSE '基准取本期之前最近 ' || :fdN || ' 个已计算账期' END;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'POST-16', :t16, :fdMsg);

    -- BOOT-01 期初承接核对（仅本期期初取自承接账期时）
    t08 = SELECT "MTC_CA_F_DOCKEY"("OrderType", "OrderEntry") || IFNULL('-' || "ItemCode", '') AS "KeyCode",
                 "Issue" || '：' || TO_NVARCHAR(ROUND("Value1", 2)) || ' / ' || TO_NVARCHAR(ROUND("Value2", 2)) AS "Info"
            FROM "MTC_CA_V_BOOT_CHECK" WHERE "FcCode" = :boot AND :prev = :boot;
    CALL "MTC_CA_P_CHECK_PUT"(:RunId, 'BOOT-01', :t08, NULL);

    SELECT COUNT(*) INTO FailCnt FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "Stage" = 'POST' AND "Result" = 'FAIL';

    -- 指标快照（每次运行都保留，用于比较两次运行）
    INSERT INTO "MTC_CA_RUN_KPI" ("RunId", "KpiType", "KeyCode", "Value")
    SELECT :RunId, 'ITEM_PRICE', "ItemCode", "PMat" + "PMfg" + "PLab" + "PSub" FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId
    UNION ALL
    SELECT :RunId, 'ITEM_END_AMT', "ItemCode", "EndAmount" FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId AND "EndAmount" <> 0
    UNION ALL
    SELECT :RunId, 'ORDER_COST', "OrderType" || '-' || "OrderEntry", "CostAmt" FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId AND "CostAmt" <> 0
    UNION ALL
    SELECT :RunId, 'ORDER_WIP', "OrderType" || '-' || "OrderEntry", "WipAmt" FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId AND "WipAmt" <> 0
    UNION ALL
    SELECT :RunId, 'POOL', "PoolCode" || '-' || "Elem", SUM("Amount") FROM "MTC_CA_R_POOL" WHERE "RunId" = :RunId GROUP BY "PoolCode", "Elem"
    UNION ALL
    SELECT :RunId, 'TOTAL_END_AMT', '', IFNULL(SUM("EndAmount"), 0) FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId
    UNION ALL
    SELECT :RunId, 'TOTAL_WIP', '', IFNULL(SUM("WipAmt"), 0) FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId
    UNION ALL
    SELECT :RunId, 'TOTAL_CLOSEDIF', '', IFNULL(SUM("CloseDifAmt"), 0) FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId;
END

@@
-- @stmt 新框架 14_p50_p60_p65.sql #3
-- P65：新旧比对（旧框架同一账期已运行时）。差额 > 0.01 的写 R_CMP，原因先记 UNEXPLAINED，逐项归因
CREATE OR REPLACE PROCEDURE "MTC_CA_P65_COMPARE" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE n BIGINT;
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    RowCnt := 0;
    SELECT COUNT(*) INTO n FROM "MTC_COST_0301_INVNT" WHERE "FcCode" = :fc AND "CostCode" = '20';
    IF :n = 0 THEN
        RETURN;
    END IF;

    -- 旧单价（用户 2026-10-13）：旧 0401 最后的“91 写入”把 Price 改成期末结存单价，期末数量为 0 时为空；
    -- 所以期末数量不为 0 取 Price，为 0 取 Out_Price（出库金额 ÷ 出库数量）。两个都没有的不比单价，只比期末金额
    oldItem = SELECT "ItemCode", SUM(IFNULL("QM_Amount", 0)) AS "EndAmt",
                     MAX(CASE WHEN IFNULL("QM_Qty", 0) <> 0 THEN "Price" ELSE "Out_Price" END) AS "Price",
                     MAX(CASE WHEN IFNULL("QM_Qty", 0) <> 0 THEN '旧值取 0301.Price（期末单价）' ELSE '旧值取 0301.Out_Price（期末数量为 0，用出库单价）' END) AS "PriceFrom"
                FROM "MTC_COST_0301_INVNT" WHERE "FcCode" = :fc AND "CostCode" = '20' GROUP BY "ItemCode";
    oldOrd = SELECT IFNULL("DocType", '202') AS "OrderType", TO_INTEGER("WorEntry") AS "OrderEntry", SUM(IFNULL("Amount", 0)) AS "Cost"
               FROM "MTC_COST_0321_OWOR_SUM"
              WHERE "FcCode" = :fc AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$'
              GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry");
    oldWip = SELECT "DocType" AS "OrderType", "WorEntry" AS "OrderEntry", SUM(IFNULL("在产品新", 0)) AS "Wip"
               FROM "MTC_COST_0322_OWOR_ZCP" WHERE "期间" = :fc GROUP BY "DocType", "WorEntry";

    INSERT INTO "MTC_CA_R_CMP" ("FcCode", "RunType", "Scenario", "RunId", "Kind", "KeyCode", "NewVal", "OldVal", "Diff", "Note")
    SELECT :fc, :rt, :scen, :RunId, 'ITEM_END', K."ItemCode", IFNULL(I."EndAmount", 0), IFNULL(O."EndAmt", 0),
           IFNULL(I."EndAmount", 0) - IFNULL(O."EndAmt", 0), CAST(NULL AS NVARCHAR(500))
      FROM (SELECT "ItemCode" FROM "MTC_CA_R_ITEM" WHERE "RunId" = :RunId UNION SELECT "ItemCode" FROM :oldItem) K
      LEFT JOIN "MTC_CA_R_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = K."ItemCode"
      LEFT JOIN :oldItem O ON O."ItemCode" = K."ItemCode"
     WHERE ABS(IFNULL(I."EndAmount", 0) - IFNULL(O."EndAmt", 0)) > 0.01
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, 'ITEM_PRICE', I."ItemCode", I."PMat" + I."PMfg" + I."PLab" + I."PSub", O."Price",
           I."PMat" + I."PMfg" + I."PLab" + I."PSub" - O."Price", O."PriceFrom"
      FROM "MTC_CA_R_ITEM" I JOIN :oldItem O ON O."ItemCode" = I."ItemCode"
     WHERE I."RunId" = :RunId AND O."Price" IS NOT NULL AND ABS(I."PMat" + I."PMfg" + I."PLab" + I."PSub" - O."Price") > 0.0001
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, 'ORDER_COST', K."OrderType" || '-' || K."OrderEntry", IFNULL(N."CostAmt", 0), IFNULL(O."Cost", 0),
           IFNULL(N."CostAmt", 0) - IFNULL(O."Cost", 0), NULL
      FROM (SELECT "OrderType", "OrderEntry" FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId AND "RecvQty" <> 0
            UNION SELECT "OrderType", "OrderEntry" FROM :oldOrd) K
      LEFT JOIN "MTC_CA_R_ORDER" N ON N."RunId" = :RunId AND N."OrderType" = K."OrderType" AND N."OrderEntry" = K."OrderEntry"
      LEFT JOIN :oldOrd O ON O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
     WHERE ABS(IFNULL(N."CostAmt", 0) - IFNULL(O."Cost", 0)) > 0.01
    UNION ALL
    SELECT :fc, :rt, :scen, :RunId, 'WIP', K."OrderType" || '-' || K."OrderEntry", IFNULL(N."WipAmt", 0), IFNULL(O."Wip", 0),
           IFNULL(N."WipAmt", 0) - IFNULL(O."Wip", 0), NULL
      FROM (SELECT "OrderType", "OrderEntry" FROM "MTC_CA_R_ORDER" WHERE "RunId" = :RunId AND "WipAmt" <> 0
            UNION SELECT "OrderType", "OrderEntry" FROM :oldWip) K
      LEFT JOIN "MTC_CA_R_ORDER" N ON N."RunId" = :RunId AND N."OrderType" = K."OrderType" AND N."OrderEntry" = K."OrderEntry"
      LEFT JOIN :oldWip O ON O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
     WHERE ABS(IFNULL(N."WipAmt", 0) - IFNULL(O."Wip", 0)) > 0.01;
    RowCnt := ::ROWCOUNT;
END

@@
-- @stmt 新框架 14_p50_p60_p65.sql #4
-- P55 库存重估清单（用户 2026-11-04，设计稿 8.8）：P50 定稿后列出要人工判断是否重估的物料，写 MTC_CA_R_REVAL_NEED，只是清单，不写 B1。
--   ZERO  结存数量 > 0 且金额 <= 0
--   APDIF 本期发票 / 贷项差额（数量为 0 的 18 / 19 行）使加权价偏离剔除差异后单价 ≥ REVAL_DEV_PCT；已有 MRV1 重估的物料算处理过，不再按偏离列出
-- 建议单价：有差额且剔除后单价 > 0 取它，否则取以前最近一期不为 0 的单价（同 P10_QCP），再取最近采购价，都没有为空。
-- 调整金额 =（目标单价 − 当前加权价）×（期初数量 + 计价入库数量）：重估单是 ProCost，进加权价，本期出库和期末都按目标单价
--   （InvntCost 不进加权价，本期领料仍按异常单价，用户 2026-11-04 改用 ProCost）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P55_REVAL" (IN RunId BIGINT, OUT RowCnt BIGINT)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE fc NVARCHAR(10); DECLARE rt NVARCHAR(1); DECLARE scen NVARCHAR(30); DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE devPct DECIMAL(19,6);
    CALL "MTC_CA_P_RUN_CTX"(:RunId, fc, rt, scen, d0, d1);
    devPct := TO_DECIMAL(IFNULL("MTC_CA_F_PARAM"('REVAL_DEV_PCT', :fc), '10'), 19, 6);

    ln = SELECT L."ItemCode", L."Qty", L."Amount", L."InVal", L."Cat", S."Src", S."ObjType",
                CASE WHEN L."Qty" = 0 AND L."Cat" = 'FIX' AND S."ObjType" IN ('18', '19') THEN 'Y' ELSE 'N' END AS "IsDif"
           FROM "MTC_CA_R_LINE" L
           JOIN "MTC_CA_S_LINE" S ON S."RunId" = L."RunId" AND S."LineId" = L."LineId"
          WHERE L."RunId" = :RunId;
    sm = SELECT "ItemCode",
                SUM(CASE WHEN "InVal" = 'Y' THEN "Qty" ELSE 0 END) AS "InQ",
                SUM(CASE WHEN "InVal" = 'Y' THEN "Amount" ELSE 0 END) AS "InA",
                SUM(CASE WHEN "IsDif" = 'Y' THEN "Amount" ELSE 0 END) AS "Dif",
                SUM(CASE WHEN "Src" = 'OMRV' AND "Cat" = 'FIX' THEN "Amount" ELSE 0 END) AS "Rvl"
           FROM :ln GROUP BY "ItemCode";
    p0 = SELECT I."ItemCode", I."iLevel", I."EndQty", I."EndMat" + I."EndMfg" + I."EndLab" + I."EndSub" AS "EndAmt",
                I."OpenQty" + IFNULL(S."InQ", 0) AS "Q",
                I."OpenMat" + I."OpenMfg" + I."OpenLab" + I."OpenSub" + IFNULL(S."InA", 0) AS "A",
                IFNULL(S."Dif", 0) AS "Dif", IFNULL(S."Rvl", 0) AS "Rvl"
           FROM "MTC_CA_R_ITEM" I
           LEFT JOIN :sm S ON S."ItemCode" = I."ItemCode"
          WHERE I."RunId" = :RunId AND I."OpenQty" + IFNULL(S."InQ", 0) > 0;
    -- 除数都要 NULLIF：HANA 合并表变量后，除法可能先于 p0 的 Q > 0 过滤、CASE 的判断计算，Q = 0 的物料会报 304（2026-11-04 运行时遇到）
    p1 = SELECT P.*, "A" / NULLIF("Q", 0) AS "CurP", ("A" - "Dif" - "Rvl") / NULLIF("Q", 0) AS "BaseP" FROM :p0 P;
    p2 = SELECT P.*, CASE WHEN "Dif" <> 0 AND "BaseP" > 0 THEN ABS("CurP" - "BaseP") / NULLIF("BaseP", 0) * 100 END AS "Dev" FROM :p1 P;
    cand = SELECT P.*, CASE WHEN "Dev" >= :devPct AND "Rvl" = 0 THEN 'APDIF'
                            WHEN "EndQty" > 0 AND "EndAmt" < 0.005 THEN 'ZERO' END AS "Kind"
             FROM :p2 P;
    need = SELECT * FROM :cand WHERE "Kind" IS NOT NULL;

    hist = SELECT "ItemCode", "FcCode", "Price", "Src", "Pri" FROM (
               SELECT "ItemCode", "FcCode", "PMat" + "PMfg" + "PLab" + "PSub" AS "Price", 'NEW' AS "Src", 1 AS "Pri"
                 FROM "MTC_CA_R_ITEM" WHERE "RunType" = 'F' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
               UNION ALL
               SELECT "ItemCode", "FcCode", "Price", 'OLD', 2
                 FROM "MTC_COST_0301_INVNT" WHERE "CostCode" = '20' AND "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need)
               UNION ALL
               SELECT "ItemCode", "FcCode", "Amount" / NULLIF("Qty", 0), 'BOOT', 3
                 FROM "MTC_CA_BOOT_ITEM" WHERE "FcCode" < :fc AND "ItemCode" IN (SELECT "ItemCode" FROM :need))
            WHERE IFNULL("Price", 0) > 0;
    sugg = SELECT "ItemCode", "FcCode", "Price", "Src"
             FROM (SELECT H.*, ROW_NUMBER() OVER (PARTITION BY "ItemCode" ORDER BY "FcCode" DESC, "Pri") AS "Rn" FROM :hist H)
            WHERE "Rn" = 1;

    -- 造成差额的单据：按单据类型列单号 Num，每类最多 10 张
    dd = SELECT DISTINCT S."ItemCode", S."ObjType", IFNULL(S."DocNum", 'Entry ' || S."DocEntry") AS "DocNum"
           FROM "MTC_CA_S_LINE" S
          WHERE S."RunId" = :RunId AND S."Qty" = 0 AND S."ObjType" IN ('18', '19')
            AND S."ItemCode" IN (SELECT "ItemCode" FROM :need);
    dd2 = SELECT D.*, ROW_NUMBER() OVER (PARTITION BY "ItemCode", "ObjType" ORDER BY "DocNum") AS "Rn",
                 COUNT(*) OVER (PARTITION BY "ItemCode", "ObjType") AS "Cnt" FROM :dd D;
    dd3 = SELECT "ItemCode", "ObjType", MAX("Cnt") AS "Cnt", STRING_AGG("DocNum", '、' ORDER BY "Rn") AS "Docs"
            FROM :dd2 WHERE "Rn" <= 10 GROUP BY "ItemCode", "ObjType";
    docs = SELECT "ItemCode", STRING_AGG(MAP("ObjType", '18', '应付发票 ', '应付贷项 ') || "Docs"
                                         || CASE WHEN "Cnt" > 10 THEN ' 等 ' || "Cnt" || ' 张' ELSE '' END, '；' ORDER BY "ObjType") AS "Docs"
             FROM :dd3 GROUP BY "ItemCode";

    pick = SELECT N.*, CASE WHEN N."Dif" <> 0 AND N."BaseP" > 0 THEN N."BaseP" WHEN G."Price" IS NOT NULL THEN G."Price"
                            WHEN IFNULL(M."LastPurPrc", 0) > 0 THEN M."LastPurPrc" END AS "Sugg",
                  CASE WHEN N."Dif" <> 0 AND N."BaseP" > 0 THEN 'EXDIF' WHEN G."Price" IS NOT NULL THEN G."Src"
                       WHEN IFNULL(M."LastPurPrc", 0) > 0 THEN 'LASTPUR' END AS "SuggSrc",
                  CASE WHEN N."Dif" <> 0 AND N."BaseP" > 0 THEN NULL ELSE G."FcCode" END AS "SuggFc"
             FROM :need N
             LEFT JOIN :sugg G ON G."ItemCode" = N."ItemCode"
             LEFT JOIN "OITM" M ON M."ItemCode" = N."ItemCode";

    INSERT INTO "MTC_CA_R_REVAL_NEED" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "ItemName", "ItmsGrpCod", "iLevel", "Kind",
        "EndQty", "EndAmt", "BaseQty", "CurPrice", "ApDif", "RevalAmt", "DevPct", "SuggPrice", "SuggSrc", "SuggFc", "AdjAmt", "Reason", "NeedDocs")
    SELECT :fc, :rt, :scen, :RunId, P."ItemCode", I."ItemName", I."ItmsGrpCod", P."iLevel", P."Kind",
           P."EndQty", P."EndAmt", P."Q", P."CurP", P."Dif", P."Rvl", P."Dev", P."Sugg", P."SuggSrc", P."SuggFc",
           ROUND((P."Sugg" - P."CurP") * P."Q", 2),
           LEFT(CASE WHEN P."Kind" = 'APDIF'
                     THEN '本期发票 / 贷项差额 ' || TO_NVARCHAR(ROUND(P."Dif", 2)) || '，加权价 ' || TO_NVARCHAR(ROUND(P."CurP", 6))
                          || ' 偏离剔除差异后单价 ' || TO_NVARCHAR(ROUND(P."BaseP", 6)) || ' 达 ' || TO_NVARCHAR(ROUND(P."Dev", 1)) || '%'
                     ELSE '结存数量 ' || TO_NVARCHAR(ROUND(P."EndQty", 2)) || '，结存金额 ' || TO_NVARCHAR(ROUND(P."EndAmt", 2)) || '（<= 0）' END, 500),
           LEFT(D."Docs", 1000)
      FROM :pick P
      LEFT JOIN "MTC_CA_S_ITEM" I ON I."RunId" = :RunId AND I."ItemCode" = P."ItemCode"
      LEFT JOIN :docs D ON D."ItemCode" = P."ItemCode";
    RowCnt := ::ROWCOUNT;
END

@@
-- @stmt 新框架 15_p70_tables.sql #1
-- =====================================================================
-- 新成本框架 第 3 期：凭证、发出商品、应付暂估的结果表与配置（设计稿 3.5、4.5、4.6，清单 S12、S15）
-- 凭证先逐条来源写 R_JDT_SRC（金额带符号：正 = 借，负 = 贷），再按 凭证代码 × 科目 × 成本中心 × 项目 汇总成 R_JDT。
-- 新框架只生成凭证，不过账；过账仍在库外完成（与旧 0801 相同）。
-- =====================================================================
CREATE COLUMN TABLE "MTC_CA_R_JDT_SRC" (
    "FcCode" NVARCHAR(10) NOT NULL, "RunType" NVARCHAR(1) NOT NULL, "Scenario" NVARCHAR(30) NOT NULL, "RunId" BIGINT NOT NULL,
    "SrcId"      BIGINT         NOT NULL,
    "TransCode"  NVARCHAR(10)   NOT NULL,       -- OTRC.TrnsCode
    "AcctCode"   NVARCHAR(15),                  -- 空 = 取不到科目（POST-08 报出）
    "OcrCode"    NVARCHAR(20),
    "Project"    NVARCHAR(20),
    "Amount"     DECIMAL(19,2)  NOT NULL,       -- 正 = 借方，负 = 贷方
    "SrcType"    NVARCHAR(10)   NOT NULL,       -- LINE 单据行（R_LINE.LineId）/ ORDER 订单 / DOC B1 单据行 / GL 总账 / OMRV 重估行
    "SrcKey"     NVARCHAR(100),
    "Note"       NVARCHAR(200),
    "VendorCode" NVARCHAR(50),                  -- 220202 应付暂估行的供应商（写入 JDT1.U_VendorCode，PUR1–PUR5）
    PRIMARY KEY ("RunId", "SrcId")
)

@@
