-- @stmt 新框架 19_jv.sql #1
-- =====================================================================
-- 新成本框架 第 5 期：生成 SAP 日记账凭单（用户 2026-10-19，设计稿 8.6；Q36 OBTF、Q41 用操作人自己的 B1 账号、
-- Q42 一种凭证代码一张、Q43 计算后校验不通过不能生成、Q44 本期 B1 已有的凭证代码自动排除）
--   MTC_CA_F_JV_PLAN    生成计划：本期最近一次成功正式运行的凭证底稿（R_JDT）按凭证代码汇总，标出能否生成（只读）
--   MTC_CA_P_JV_BEGIN   生成前检查：账期未锁定、有成功的正式运行、没有正在运行的正式计算、计算后校验全部通过
--   MTC_CA_P_JV_LOG     记一张凭单的生成结果（MTC_CA_JV）
--   MTC_CA_P_JV_FINISH  本次生成结束：有已生成的凭单 → 账期状态 POSTED
--   MTC_CA_P_JV_UNDO    撤销：凭单已在 B1 删除（或已过账的已冲销）后，记为 DELETED，账期状态回到 CALC
--   MTC_CA_P_CHECK_ACK / _UNACK  计算后校验阻断项的人工确认 / 取消（Q45，用户 2026-10-19）：确认过的项不再阻断生成凭单
-- 凭单本身由执行台服务（tools/console/dev_server.py，服务器模式）经 Service Layer JournalVouchers 建，不用 SQL 写 B1 表；
-- 表头 Ref1 = 'MTC_CA#运行号'，服务端按 Ref1 + 凭证代码找回批号（同用户插件做法，2026-10-19）；有 UDF OJDT.U_MTC_CARunId 时顺带写运行号。
-- 建好后服务端回写 OBTD.Remarks；JV_REV_TRANSCODES 中的代码（AR03 / AR04）回写 OBTF.AutoStorno = 'Y'、StornoDate = 下一账期第一天。
-- 替代：旧流程 0801 只生成中间表，过账在库外完成；6101_1 写 UDO @MTC_COST_OJDT。
-- 依赖 01（MTC_CA_JV）、03（P_PERIOD_SET）、06（R_CHECK）、15（R_JDT）。
-- HANA 注意：COUNT(*) 和 STRING_AGG 写在同一条 SELECT … INTO 里，没有行时报 1299 no data found（2026-10-19 测试发现），一律先 COUNT、有行再取 STRING_AGG。
-- =====================================================================
CREATE OR REPLACE FUNCTION "MTC_CA_F_JV_PLAN" (IN FcCode NVARCHAR(10))
RETURNS TABLE ("RunId" BIGINT, "TransCode" NVARCHAR(10), "TransName" NVARCHAR(100), "RefDate" DATE, "LineCnt" INT,
               "Debit" DECIMAL(19,2), "Credit" DECIMAL(19,2), "BadAcct" INT, "State" NVARCHAR(10), "BatchNum" INT, "StateMsg" NVARCHAR(500),
               "AutoRev" NVARCHAR(1), "RevDate" DATE)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE d0 DATE; DECLARE d1 DATE; DECLARE revCodes NVARCHAR(1000); DECLARE revDate DATE;
    SELECT MAX("RunId") INTO rid FROM "MTC_CA_RUN" WHERE "FcCode" = :FcCode AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'OK';
    SELECT MAX(TO_DATE("F_RefDate")), MAX(TO_DATE("T_RefDate")) INTO d0, d1 FROM "OFPR" WHERE "Code" = :FcCode;
    -- 下月初自动冲销（参数 JV_REV_TRANSCODES，默认 AR03、AR04；冲销日期 = 下一账期第一天，同旧 COJZ_01/03）
    revCodes := IFNULL("MTC_CA_F_PARAM"('JV_REV_TRANSCODES', :FcCode), ',');
    SELECT MIN(TO_DATE("F_RefDate")) INTO revDate FROM "OFPR" WHERE "Code" > :FcCode;
    -- 本模块生成过的批号（含已撤销的）：它们以及由它们过账出的 OJDT 不算“B1 里已有”
    mine = SELECT DISTINCT "BatchNum" FROM "MTC_CA_JV" WHERE "BatchNum" IS NOT NULL;
    done = SELECT "TransCode", MAX("BatchNum") AS "BatchNum" FROM "MTC_CA_JV"
            WHERE "FcCode" = :FcCode AND "Status" = 'CREATED' GROUP BY "TransCode";
    -- Q44：本期 B1 里已有同一凭证代码的凭证（已过账、不是冲销）或未清凭单 → 整个代码不生成（如 2026-09 手工过账的 PUR1、MR02）
    b1 = SELECT DISTINCT "TransCode" FROM (
             SELECT H."TransCode" FROM "OJDT" H
              WHERE H."RefDate" BETWEEN :d0 AND :d1 AND H."StornoToTr" IS NULL
                AND NOT EXISTS (SELECT 1 FROM :mine M WHERE M."BatchNum" = H."BatchNum")
             UNION ALL
             SELECT T."TransCode" FROM "OBTF" T
              WHERE T."BtfStatus" = 'O' AND T."RefDate" BETWEEN :d0 AND :d1
                AND NOT EXISTS (SELECT 1 FROM :mine M WHERE M."BatchNum" = T."BatchNum"))
          WHERE IFNULL("TransCode", '') <> '';
    -- 科目：底稿里是内部科目代码；万一是显示代码（FormatCode）也认
    ln = SELECT J."TransCode", J."TransName", J."RefDate", J."Debit", J."Credit",
                CASE WHEN A1."AcctCode" IS NOT NULL THEN A1."Postable" ELSE A2."Postable" END AS "Postable",
                IFNULL(A1."AcctCode", A2."AcctCode") AS "Acct"
           FROM "MTC_CA_R_JDT" J
           LEFT JOIN "OACT" A1 ON A1."AcctCode" = J."AcctCode"
           LEFT JOIN (SELECT "FormatCode", MAX("AcctCode") AS "AcctCode", MAX("Postable") AS "Postable" FROM "OACT"
                       WHERE IFNULL("FormatCode", '') <> '' GROUP BY "FormatCode") A2 ON A2."FormatCode" = J."AcctCode"
          WHERE J."RunId" = :rid AND (J."Debit" <> 0 OR J."Credit" <> 0);
    agg = SELECT L."TransCode", MAX(L."TransName") AS "TransName", MAX(L."RefDate") AS "RefDate", COUNT(*) AS "LineCnt",
                 SUM(L."Debit") AS "Debit", SUM(L."Credit") AS "Credit",
                 SUM(CASE WHEN L."Acct" IS NULL OR IFNULL(L."Postable", 'N') <> 'Y' THEN 1 ELSE 0 END) AS "BadAcct",
                 MAX(D."BatchNum") AS "BatchNum", MAX(B."TransCode") AS "B1Code"
            FROM :ln L
            LEFT JOIN :done D ON D."TransCode" = L."TransCode"
            LEFT JOIN :b1 B ON B."TransCode" = L."TransCode"
           GROUP BY L."TransCode";
    RETURN SELECT :rid AS "RunId", "TransCode", "TransName", "RefDate", "LineCnt", "Debit", "Credit", "BadAcct",
                  CASE WHEN "BatchNum" IS NOT NULL THEN 'CREATED'
                       WHEN "B1Code" IS NOT NULL THEN 'B1'
                       WHEN "Debit" <> "Credit" THEN 'UNBAL'
                       WHEN "BadAcct" > 0 THEN 'BADACCT'
                       ELSE 'READY' END AS "State",
                  "BatchNum",
                  CASE WHEN "BatchNum" IS NOT NULL THEN '已生成，B1 批号 ' || TO_VARCHAR("BatchNum")
                       WHEN "B1Code" IS NOT NULL THEN '本期 B1 已有这个凭证代码的凭证或未清凭单，不生成'
                       WHEN "Debit" <> "Credit" THEN '借贷不平，不能生成'
                       WHEN "BadAcct" > 0 THEN TO_VARCHAR("BadAcct") || ' 行科目不存在或不能记账，不能生成'
                       ELSE '可以生成' END AS "StateMsg",
                  CASE WHEN LOCATE(:revCodes, ',' || "TransCode" || ',') > 0 THEN 'Y' ELSE 'N' END AS "AutoRev",
                  CASE WHEN LOCATE(:revCodes, ',' || "TransCode" || ',') > 0 THEN :revDate END AS "RevDate"
             FROM :agg ORDER BY "TransCode";
END

@@
-- @stmt 新框架 19_jv.sql #2
-- 生成前检查（Q43）。返回 Code 0 / -1、Msg、RunId（生成所用的运行）
CREATE OR REPLACE PROCEDURE "MTC_CA_P_JV_BEGIN" (IN FcCode NVARCHAR(10), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE stat NVARCHAR(1); DECLARE rid BIGINT; DECLARE ids NVARCHAR(1000);
    SELECT COUNT(*), MAX("PeriodStat") INTO n, stat FROM "OFPR" WHERE "Code" = :FcCode;
    IF :n = 0 THEN
        SELECT -1 AS "Code", '账期不存在：' || IFNULL(:FcCode, '') AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    IF :stat = 'Y' THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 已在 B1 锁定，不能生成凭单' AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM "MTC_CA_RUN" WHERE "FcCode" = :FcCode AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'RUNNING';
    IF :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 有正在运行的正式计算，等它结束再生成' AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    SELECT MAX("RunId") INTO rid FROM "MTC_CA_RUN" WHERE "FcCode" = :FcCode AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'OK';
    IF :rid IS NULL THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 还没有成功的正式计算' AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    -- 已生成过凭单的运行必须就是这次（正常情况下生成后不能再正式计算，这里兜底）
    SELECT COUNT(*) INTO n FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "Status" = 'CREATED' AND "RunId" <> :rid;
    IF :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 已有其他运行生成的凭单，先撤销' AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    -- 历史委外差异转出的计划在计算之后改过：底稿和计划对不上，要重新计算（用户 2026-11-04）
    SELECT COUNT(*) INTO n
      FROM (SELECT "OrderType" || '-' || "OrderEntry" AS "K", "Amount" FROM "MTC_CA_WW_HIST" WHERE "PlanFc" = :FcCode AND "Manual" = 'N') A
      FULL JOIN (SELECT "SrcKey" AS "K", "Amount" FROM "MTC_CA_S_EXP" WHERE "RunId" = :rid AND "Src" = 'WWHIST') B ON B."K" = A."K"
     WHERE A."K" IS NULL OR B."K" IS NULL OR A."Amount" <> B."Amount";
    IF :n > 0 THEN
        SELECT -1 AS "Code", '运行 #' || TO_VARCHAR(:rid) || ' 之后改过历史委外差异转出计划（' || :n || ' 张订单不一致），请重新计算' AS "Msg",
               CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    -- Q45：已人工确认（MTC_CA_CHECK_ACK）的阻断项不算
    SELECT COUNT(*) INTO n
      FROM "MTC_CA_R_CHECK" C
     WHERE C."RunId" = :rid AND C."Stage" = 'POST' AND C."Result" = 'FAIL'
       AND NOT EXISTS (SELECT 1 FROM "MTC_CA_CHECK_ACK" A WHERE A."RunId" = C."RunId" AND A."CheckId" = C."CheckId");
    ids := '';
    IF :n > 0 THEN
        SELECT LEFT(STRING_AGG(C."CheckId", '、' ORDER BY C."CheckId"), 900) INTO ids
          FROM "MTC_CA_R_CHECK" C
         WHERE C."RunId" = :rid AND C."Stage" = 'POST' AND C."Result" = 'FAIL'
           AND NOT EXISTS (SELECT 1 FROM "MTC_CA_CHECK_ACK" A WHERE A."RunId" = C."RunId" AND A."CheckId" = C."CheckId");
    END IF;
    IF :n > 0 THEN
        SELECT -1 AS "Code", '运行 #' || TO_VARCHAR(:rid) || ' 计算后校验 ' || :n || ' 项未通过且未确认（' || :ids || '）：处理后重新计算，或在“生成凭单”页逐项确认后再生成' AS "Msg",
               CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY; RETURN;
    END IF;
    SELECT 0 AS "Code", '' AS "Msg", :rid AS "RunId" FROM DUMMY;
END

@@
-- @stmt 新框架 19_jv.sql #3
CREATE OR REPLACE PROCEDURE "MTC_CA_P_JV_LOG" (
    IN FcCode NVARCHAR(10), IN RunId BIGINT, IN TransCode NVARCHAR(10), IN BatchNum NVARCHAR(20), IN Status NVARCHAR(10),
    IN Debit NVARCHAR(30), IN Credit NVARCHAR(30), IN LineCnt NVARCHAR(10), IN UserCode NVARCHAR(50), IN Msg NVARCHAR(2000)
)
LANGUAGE SQLSCRIPT AS
BEGIN
    -- 参数按字符串传（执行台统一按 NVARCHAR 绑定），这里转换
    INSERT INTO "MTC_CA_JV" ("JvId", "FcCode", "RunId", "TransCode", "BatchNum", "Status", "Debit", "Credit", "LineCnt",
                             "CreateUser", "CreateTime", "Msg")
    VALUES ("MTC_CA_SEQ_JV".NEXTVAL, :FcCode, :RunId, :TransCode, TO_INT(NULLIF(:BatchNum, '')), :Status,
            TO_DECIMAL(NULLIF(:Debit, ''), 19, 2), TO_DECIMAL(NULLIF(:Credit, ''), 19, 2), TO_INT(NULLIF(:LineCnt, '')),
            :UserCode, CURRENT_TIMESTAMP, LEFT(:Msg, 2000));
    SELECT 0 AS "Code", '' AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_jv.sql #4
CREATE OR REPLACE PROCEDURE "MTC_CA_P_JV_FINISH" (IN FcCode NVARCHAR(10), IN RunId BIGINT, IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE bat NVARCHAR(1000); DECLARE st NVARCHAR(10);
    SELECT COUNT(*) INTO n
      FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "RunId" = :RunId AND "Status" = 'CREATED';
    bat := '';
    IF :n > 0 THEN
        SELECT LEFT(STRING_AGG("TransCode" || ' ' || TO_VARCHAR("BatchNum"), '、' ORDER BY "TransCode"), 900) INTO bat
          FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "RunId" = :RunId AND "Status" = 'CREATED';
    END IF;
    IF :n = 0 THEN
        SELECT -1 AS "Code", '没有已生成的凭单' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT IFNULL(MAX("Status"), 'OPEN') INTO st FROM "MTC_CA_PERIOD" WHERE "FcCode" = :FcCode;
    IF :st = 'POSTED' THEN
        -- 已是 POSTED（之后又补生成了取消勾选的代码）：只记日志
        INSERT INTO "MTC_CA_PERIOD_LOG" ("FcCode", "LogTime", "FromStatus", "ToStatus", "RunId", "UserCode", "Msg")
        VALUES (:FcCode, CURRENT_TIMESTAMP, 'POSTED', 'POSTED', :RunId, :UserCode, '补生成凭单，现有：' || :bat);
    ELSE
        CALL "MTC_CA_P_PERIOD_SET"(:FcCode, 'POSTED', :RunId, :UserCode, '生成凭单：' || :bat);
    END IF;
    COMMIT;
    SELECT 0 AS "Code", '已生成 ' || :n || ' 张凭单：' || :bat AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_jv.sql #5
-- 撤销（Q38）：Service Layer 不能删除日记账凭单，先由用户在 B1“日记账凭单”里删除；已过账的要先冲销。
-- 这里核对 B1：本账期已生成的批号都不在未清凭单（OBTF BtfStatus='O'）里，由它们过账出的凭证都已冲销，才记为 DELETED、状态回到 CALC。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_JV_UNDO" (IN FcCode NVARCHAR(10), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE calcRun BIGINT; DECLARE lst NVARCHAR(1000);
    SELECT COUNT(*) INTO n
      FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "Status" = 'CREATED';
    lst := '';
    IF :n > 0 THEN
        SELECT LEFT(STRING_AGG("TransCode" || ' ' || IFNULL(TO_VARCHAR("BatchNum"), ''), '、' ORDER BY "TransCode"), 900) INTO lst
          FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "Status" = 'CREATED';
    END IF;
    IF :n = 0 THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 没有可撤销的凭单' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT COUNT(*) INTO n
      FROM "MTC_CA_JV" J
     WHERE J."FcCode" = :FcCode AND J."Status" = 'CREATED'
       AND EXISTS (SELECT 1 FROM "OBTF" T WHERE T."BatchNum" = J."BatchNum" AND T."BtfStatus" = 'O');
    lst := '';
    IF :n > 0 THEN
        SELECT LEFT(STRING_AGG(J."TransCode" || ' 批号 ' || TO_VARCHAR(J."BatchNum"), '、' ORDER BY J."TransCode"), 900) INTO lst
          FROM "MTC_CA_JV" J
         WHERE J."FcCode" = :FcCode AND J."Status" = 'CREATED'
           AND EXISTS (SELECT 1 FROM "OBTF" T WHERE T."BatchNum" = J."BatchNum" AND T."BtfStatus" = 'O');
    END IF;
    IF :n > 0 THEN
        SELECT -1 AS "Code", '这些凭单还在 B1 未清凭单里，请先在 B1“财务 → 日记账凭单”中删除，再点撤销：' || :lst AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT COUNT(*) INTO n
      FROM "MTC_CA_JV" J JOIN "OJDT" H ON H."BatchNum" = J."BatchNum"
     WHERE J."FcCode" = :FcCode AND J."Status" = 'CREATED' AND H."StornoToTr" IS NULL
       AND NOT EXISTS (SELECT 1 FROM "OJDT" R WHERE R."StornoToTr" = H."TransId");
    lst := '';
    IF :n > 0 THEN
        SELECT LEFT(STRING_AGG(J."TransCode" || ' 凭证 ' || TO_VARCHAR(H."TransId"), '、' ORDER BY J."TransCode"), 900) INTO lst
          FROM "MTC_CA_JV" J JOIN "OJDT" H ON H."BatchNum" = J."BatchNum"
         WHERE J."FcCode" = :FcCode AND J."Status" = 'CREATED' AND H."StornoToTr" IS NULL
           AND NOT EXISTS (SELECT 1 FROM "OJDT" R WHERE R."StornoToTr" = H."TransId");
    END IF;
    IF :n > 0 THEN
        SELECT -1 AS "Code", '这些凭单已在 B1 过账、还没冲销，不能撤销；请先在 B1 冲销：' || :lst AS "Msg" FROM DUMMY; RETURN;
    END IF;
    -- 前面已确认有 CREATED 行，这里一定有数据
    SELECT LEFT(STRING_AGG("TransCode" || ' ' || IFNULL(TO_VARCHAR("BatchNum"), ''), '、' ORDER BY "TransCode"), 900) INTO lst
      FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "Status" = 'CREATED';
    UPDATE "MTC_CA_JV" SET "Status" = 'DELETED', "DelUser" = :UserCode, "DelTime" = CURRENT_TIMESTAMP
     WHERE "FcCode" = :FcCode AND "Status" = 'CREATED';
    SELECT MAX("CalcRunId") INTO calcRun FROM "MTC_CA_PERIOD" WHERE "FcCode" = :FcCode;
    CALL "MTC_CA_P_PERIOD_SET"(:FcCode, 'CALC', :calcRun, :UserCode, '撤销凭单：' || IFNULL(:lst, ''));
    COMMIT;
    SELECT 0 AS "Code", '已撤销，账期回到“已计算”，可以重新计算：' || IFNULL(:lst, '') AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_jv.sql #6
-- 确认一项计算后校验阻断（Q45）：只能确认本期最近一次成功正式运行的 POST 阻断项；已生成凭单后不能再改；理由至少 4 个字。
-- 记一行 MTC_CA_CHECK_ACK，并在 MTC_CA_PERIOD_LOG 留痕（状态不变）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_CHECK_ACK" (IN RunId BIGINT, IN CheckId NVARCHAR(20), IN UserCode NVARCHAR(50), IN Reason NVARCHAR(500))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE fc NVARCHAR(10); DECLARE latest BIGINT; DECLARE st NVARCHAR(10);
    SELECT MAX("FcCode") INTO fc FROM "MTC_CA_RUN" WHERE "RunId" = :RunId AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'OK';
    IF :fc IS NULL THEN
        SELECT -1 AS "Code", '运行 #' || TO_VARCHAR(:RunId) || ' 不是成功的正式运行' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT MAX("RunId") INTO latest FROM "MTC_CA_RUN" WHERE "FcCode" = :fc AND "RunType" = 'F' AND "Scenario" = '' AND "Status" = 'OK';
    IF :latest <> :RunId THEN
        SELECT -1 AS "Code", '只能确认本期最近一次成功正式运行（#' || TO_VARCHAR(:latest) || '）的校验' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT IFNULL(MAX("Status"), 'OPEN') INTO st FROM "MTC_CA_PERIOD" WHERE "FcCode" = :fc;
    SELECT COUNT(*) INTO n FROM "MTC_CA_JV" WHERE "FcCode" = :fc AND "Status" = 'CREATED';
    IF :st = 'POSTED' OR :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || :fc || ' 已生成凭单，不能再改确认' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "CheckId" = :CheckId AND "Stage" = 'POST' AND "Result" = 'FAIL';
    IF :n = 0 THEN
        SELECT -1 AS "Code", :CheckId || ' 在运行 #' || TO_VARCHAR(:RunId) || ' 中不是未通过的计算后校验，不需要确认' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF LENGTH(TRIM(IFNULL(:Reason, ''))) < 4 THEN
        SELECT -1 AS "Code", '请写明确认理由（至少 4 个字）' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    UPSERT "MTC_CA_CHECK_ACK" ("RunId", "CheckId", "UserCode", "AckTime", "Reason")
    VALUES (:RunId, :CheckId, :UserCode, CURRENT_TIMESTAMP, TRIM(:Reason)) WITH PRIMARY KEY;
    INSERT INTO "MTC_CA_PERIOD_LOG" ("FcCode", "LogTime", "FromStatus", "ToStatus", "RunId", "UserCode", "Msg")
    SELECT :fc, CURRENT_TIMESTAMP, IFNULL(MAX("Status"), 'OPEN'), IFNULL(MAX("Status"), 'OPEN'), :RunId, :UserCode,
           LEFT('确认阻断项 ' || :CheckId || '：' || TRIM(:Reason), 2000)
      FROM "MTC_CA_PERIOD" WHERE "FcCode" = :fc;
    SELECT 0 AS "Code", '已确认 ' || :CheckId || '，生成凭单时不再被这一项阻断' AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_jv.sql #7
CREATE OR REPLACE PROCEDURE "MTC_CA_P_CHECK_UNACK" (IN RunId BIGINT, IN CheckId NVARCHAR(20), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE fc NVARCHAR(10); DECLARE st NVARCHAR(10);
    SELECT MAX("FcCode") INTO fc FROM "MTC_CA_RUN" WHERE "RunId" = :RunId;
    SELECT IFNULL(MAX("Status"), 'OPEN') INTO st FROM "MTC_CA_PERIOD" WHERE "FcCode" = :fc;
    SELECT COUNT(*) INTO n FROM "MTC_CA_JV" WHERE "FcCode" = :fc AND "Status" = 'CREATED';
    IF :st = 'POSTED' OR :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || IFNULL(:fc, '') || ' 已生成凭单，不能再改确认' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    DELETE FROM "MTC_CA_CHECK_ACK" WHERE "RunId" = :RunId AND "CheckId" = :CheckId;
    n := ::ROWCOUNT;
    IF :n > 0 THEN
        INSERT INTO "MTC_CA_PERIOD_LOG" ("FcCode", "LogTime", "FromStatus", "ToStatus", "RunId", "UserCode", "Msg")
        SELECT :fc, CURRENT_TIMESTAMP, IFNULL(MAX("Status"), 'OPEN'), IFNULL(MAX("Status"), 'OPEN'), :RunId, :UserCode, '取消确认阻断项 ' || :CheckId
          FROM "MTC_CA_PERIOD" WHERE "FcCode" = :fc;
    END IF;
    SELECT 0 AS "Code", CASE WHEN :n > 0 THEN '已取消确认 ' || :CheckId ELSE :CheckId || ' 本来就没有确认' END AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_ww_hist.sql #1
-- =====================================================================
-- 历史委外差异转出（用户 2026-11-04，设计稿 8.9，清单 S4）
--   旧 CO4001 委外订单关单日期 >= 2026-08 才把在产品转关单差异，更早关闭的留在 140801；期初承接只取未关闭订单，
--   这些订单业务端为 0、总账仍有余额。用户按整张订单选账期转出，P20_EXP 进费用池，P70 生成 JZ05（借 510109 / P016，贷 140801）。
--   MTC_CA_P_WW_HIST_LOAD  从旧在产品表载入待转清单（已计划的行不动）
--   MTC_CA_P_WW_HIST_SET   把一张订单转入某账期 / 取消
--   MTC_CA_P_WW_HIST_MARK  标记已手工做分录转出（Manual = Y）/ 取消：不进计算、不生成 JZ05，只是不能再选
-- 依赖 06（MTC_CA_WW_HIST）、旧表 MTC_COST_0322_OWOR_ZCP。只处理 140801，不含 140802。
-- 只读排查：diag_ww_closed_hist.sql。
-- =====================================================================
CREATE OR REPLACE PROCEDURE "MTC_CA_P_WW_HIST_LOAD" (IN FcCode NVARCHAR(10), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE boot NVARCHAR(10); DECLARE wwWt NVARCHAR(200); DECLARE d1 DATE;
    DECLARE n INT; DECLARE amt DECIMAL(19,2);
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :FcCode);
    wwWt := IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', :FcCode), ',50,');
    SELECT MAX(TO_DATE("T_RefDate")) INTO d1 FROM "OFPR" WHERE "Code" = :boot;
    IF :d1 IS NULL THEN
        SELECT -1 AS "Code", '承接账期 ' || IFNULL(:boot, '（空）') || ' 在 OFPR 中不存在' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    -- 每张订单截至承接账期最后一次出现在旧在产品表的记录
    z = SELECT "OrderType", "OrderEntry", "LastFc", "WorType", "Wip" FROM (
            SELECT IFNULL("DocType", '202') AS "OrderType", "WorEntry" AS "OrderEntry", "期间" AS "LastFc",
                   MAX("WorType") AS "WorType", SUM(IFNULL("在产品新", 0)) AS "Wip",
                   ROW_NUMBER() OVER (PARTITION BY IFNULL("DocType", '202'), "WorEntry" ORDER BY "期间" DESC) AS "Rn"
              FROM "MTC_COST_0322_OWOR_ZCP"
             WHERE "期间" <= :boot
             GROUP BY IFNULL("DocType", '202'), "WorEntry", "期间")
         WHERE "Rn" = 1 AND "Wip" <> 0 AND LOCATE(:wwWt, ',' || IFNULL("WorType", '') || ',') > 0;
    -- 截至承接账期期末不算未关闭的订单：和 MTC_CA_P_BOOTSTRAP 的“未关闭”条件互补
    c = SELECT '202' AS "OrderType", "DocEntry" AS "OrderEntry", "DocNum", "ItemCode", "Status",
               IFNULL(TO_DATE("CloseDate"), :d1) AS "CloseDate"
          FROM "OWOR"
         WHERE ("Status" = 'C' AND TO_DATE("UpdateDate") <= :d1) OR ("Status" = 'L' AND IFNULL(TO_DATE("CloseDate"), :d1) <= :d1)
        UNION ALL
        SELECT 'MTC_OWOR', "DocEntry", "DocNum", "U_ItemCode", "U_Status", IFNULL(TO_DATE("U_CloseDate"), :d1)
          FROM "@MTC_OWOR"
         WHERE ("U_Status" = 'C' AND TO_DATE("UpdateDate") <= :d1) OR ("U_Status" = 'L' AND IFNULL(TO_DATE("U_CloseDate"), :d1) <= :d1);

    DELETE FROM "MTC_CA_WW_HIST" WHERE "PlanFc" IS NULL;
    INSERT INTO "MTC_CA_WW_HIST" ("OrderType", "OrderEntry", "DocNum", "ItemCode", "B1Status", "CloseDate", "LastFc", "Amount", "LoadFc", "LoadTime")
    SELECT Z."OrderType", Z."OrderEntry", C."DocNum", C."ItemCode", C."Status", C."CloseDate", Z."LastFc", Z."Wip", :boot, CURRENT_TIMESTAMP
      FROM :z Z JOIN :c C ON C."OrderType" = Z."OrderType" AND C."OrderEntry" = Z."OrderEntry"
     WHERE NOT EXISTS (SELECT 1 FROM "MTC_CA_WW_HIST" H WHERE H."OrderType" = Z."OrderType" AND H."OrderEntry" = Z."OrderEntry");
    SELECT COUNT(*), IFNULL(SUM("Amount"), 0) INTO n, amt FROM "MTC_CA_WW_HIST" WHERE "PlanFc" IS NULL;
    SELECT 0 AS "Code", '已载入：待转 ' || :n || ' 张订单，净额 ' || TO_NVARCHAR(:amt) || '（承接账期 ' || :boot || '）' AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_ww_hist.sql #2
-- OnOff：Y 转入 FcCode，N 取消。已生成凭单或正在计算的账期不能改；改完要重新计算。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_WW_HIST_SET" (
    IN FcCode NVARCHAR(10), IN OrderType NVARCHAR(20), IN OrderEntry INT, IN OnOff NVARCHAR(1),
    IN Note NVARCHAR(500), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE planFc NVARCHAR(10); DECLARE startFc NVARCHAR(10); DECLARE st NVARCHAR(10); DECLARE man NVARCHAR(1);
    SELECT COUNT(*), MAX("PlanFc"), MAX("Manual") INTO n, planFc, man FROM "MTC_CA_WW_HIST"
     WHERE "OrderType" = :OrderType AND "OrderEntry" = :OrderEntry;
    IF :n = 0 THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 不在待转清单里' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :man = 'Y' THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 已在 ' || :planFc || ' 手工转出' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    startFc := "MTC_CA_F_PARAM"('START_FC', :FcCode);
    IF :FcCode < :startFc THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 早于新框架起始账期 ' || :startFc AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'Y' AND :planFc IS NOT NULL AND :planFc <> :FcCode THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 已计划在 ' || :planFc || ' 转出，不能重复转' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'N' AND IFNULL(:planFc, '') <> :FcCode THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 没有计划在 ' || :FcCode || ' 转出' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'Y' AND LENGTH(TRIM(IFNULL(:Note, ''))) = 0 THEN
        SELECT -1 AS "Code", '请写转出理由' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT MAX("Status") INTO st FROM "MTC_CA_PERIOD" WHERE "FcCode" = :FcCode;
    SELECT COUNT(*) INTO n FROM "MTC_CA_JV" WHERE "FcCode" = :FcCode AND "Status" = 'CREATED';
    IF IFNULL(:st, '') = 'POSTED' OR :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 已生成凭单，不能改；需要改时先撤销凭单' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    SELECT COUNT(*) INTO n FROM "MTC_CA_RUN" WHERE "FcCode" = :FcCode AND "Status" = 'RUNNING';
    IF :n > 0 THEN
        SELECT -1 AS "Code", '账期 ' || :FcCode || ' 正在计算，等它结束再改' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    UPDATE "MTC_CA_WW_HIST"
       SET "PlanFc" = CASE WHEN :OnOff = 'Y' THEN :FcCode END,
           "PlanUser" = CASE WHEN :OnOff = 'Y' THEN :UserCode END,
           "PlanTime" = CASE WHEN :OnOff = 'Y' THEN CURRENT_TIMESTAMP END,
           "PlanNote" = CASE WHEN :OnOff = 'Y' THEN :Note END
     WHERE "OrderType" = :OrderType AND "OrderEntry" = :OrderEntry;
    SELECT 0 AS "Code", CASE WHEN :OnOff = 'Y' THEN '已转入 ' || :FcCode ELSE '已取消' END AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 19_ww_hist.sql #3
-- 已手工做分录转出的订单（如 2026-09 的手工凭证）：FcCode = 手工分录的账期，可以早于起始账期。分录已在总账，这里只标记，不影响计算。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_WW_HIST_MARK" (
    IN FcCode NVARCHAR(10), IN OrderType NVARCHAR(20), IN OrderEntry INT, IN OnOff NVARCHAR(1),
    IN Note NVARCHAR(500), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT; DECLARE planFc NVARCHAR(10); DECLARE man NVARCHAR(1);
    SELECT COUNT(*), MAX("PlanFc"), MAX("Manual") INTO n, planFc, man FROM "MTC_CA_WW_HIST"
     WHERE "OrderType" = :OrderType AND "OrderEntry" = :OrderEntry;
    IF :n = 0 THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 不在待转清单里' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'Y' AND :planFc IS NOT NULL THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 已计划在 ' || :planFc || ' 转出' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'N' AND :man <> 'Y' THEN
        SELECT -1 AS "Code", '订单 ' || :OrderType || '-' || :OrderEntry || ' 没有标记手工转出' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    IF :OnOff = 'Y' AND LENGTH(TRIM(IFNULL(:Note, ''))) = 0 THEN
        SELECT -1 AS "Code", '请写说明' AS "Msg" FROM DUMMY; RETURN;
    END IF;
    UPDATE "MTC_CA_WW_HIST"
       SET "Manual" = :OnOff,
           "PlanFc" = CASE WHEN :OnOff = 'Y' THEN :FcCode END,
           "PlanUser" = CASE WHEN :OnOff = 'Y' THEN :UserCode END,
           "PlanTime" = CASE WHEN :OnOff = 'Y' THEN CURRENT_TIMESTAMP END,
           "PlanNote" = CASE WHEN :OnOff = 'Y' THEN :Note END
     WHERE "OrderType" = :OrderType AND "OrderEntry" = :OrderEntry;
    SELECT 0 AS "Code", CASE WHEN :OnOff = 'Y' THEN '已标记 ' || :FcCode || ' 手工转出' ELSE '已取消标记' END AS "Msg" FROM DUMMY;
END

@@
-- @stmt 新框架 10_run_entry.sql #1
-- =====================================================================
-- 新成本框架：入口过程（设计稿第 4 节）
-- CALL "MTC_CA_P_RUN"('2026-09', 'F', '', 'manager', 'USER');
--   参数：账期 OFPR.Code、F 正式 / S 模拟、模拟场景（正式为空串）、用户、发起方 USER / AI
--   返回：Code 0 成功 / -1 参数或运行错误 / -2 计算前检查阻断 / -3 未收敛；Msg；RunId
-- 步骤：P00 准备 → P20 快照 → P10 计算前检查 → P30 初始化与固定价格 →（模拟）P31 场景假设 → P40 迭代 → P50 定稿
--       → P60 计算后校验与指标快照 → P65 新旧比对 → P71 发出商品 → P73 应付暂估 → P74 应付暂估凭证 → P70 凭证 → P75 凭证校验 → P80 收尾
-- 未收敛：不定稿、不出凭证，上一次成功运行的结果保留，迭代日志 MTC_CA_RUN_ITER / MTC_CA_RUN_ITER_ITEM 保留供排查；
--   参数 KEEP_NOCONV = Y（默认，2026-10-29）时本次快照和最后一轮的中间结果也保留（运行状态 NOCONV，下次同类运行成功时删掉），N 时删除。
--   P40 及以后出错（运行状态 FAIL，2026-10-30）同样按 KEEP_NOCONV 保留快照和出错前最后一次提交的中间结果（P40 每轮提交）。
-- 依赖 03、07、08、12、13、14、16、17，部署顺序在它们之后。
-- 账期状态（2026-10-19）：正式计算先过 MTC_CA_P_PERIOD_GUARD（已生成凭单的账期拒绝，上期未生成凭单等只警告，警告写在 P00 步骤），成功后账期状态记为 CALC。
-- =====================================================================
CREATE OR REPLACE PROCEDURE "MTC_CA_P_RUN" (
    IN FcCode    NVARCHAR(10),
    IN RunType   NVARCHAR(1),
    IN Scenario  NVARCHAR(30),
    IN UserCode  NVARCHAR(50),
    IN Initiator NVARCHAR(10)
)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE RunId BIGINT;
    DECLARE Code  INT;
    DECLARE Msg   NVARCHAR(2000);
    DECLARE n     BIGINT;
    DECLARE nBlk  INT;
    DECLARE conv  NVARCHAR(1);
    DECLARE iters INT;
    DECLARE nFail INT;
    DECLARE postFail NVARCHAR(1000);
    DECLARE warn  NVARCHAR(2000) := '';
    DECLARE keepNc NVARCHAR(10);
    DECLARE stage NVARCHAR(4) := '';      -- 进入 P40 后为 P40（2026-10-30）
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE em NVARCHAR(2000) := 'SQL ' || ::SQL_ERROR_CODE || ': ' || LEFT(::SQL_ERROR_MESSAGE, 1900);
        DECLARE m BIGINT;
        ROLLBACK;
        BEGIN
            -- 清理失败也不能盖掉原始错误
            DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN END;
            -- P40 及以后出错（2026-10-30，#14 迭代发散到第 50 轮溢出）：快照、P30 和已完成的迭代轮次都已提交，
            -- KEEP_NOCONV = Y 时和未收敛一样保留供排查（只回滚了出错那一步），下次同类运行成功时删掉
            IF :stage = 'P40' AND IFNULL("MTC_CA_F_PARAM"('KEEP_NOCONV', :FcCode), 'Y') = 'Y' THEN
                CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'NCV', m);
                COMMIT;
                em := LEFT(:em, 1950) || '（快照和出错前的中间结果已保留供排查）';
            ELSE
                CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'FAIL', m);
                COMMIT;
            END IF;
        END;
        CALL "MTC_CA_P_RUN_END"(:RunId, 'FAIL', :em);
        SELECT -1 AS "Code", :em AS "Msg", :RunId AS "RunId" FROM DUMMY;
    END;

    -- 先把 B1 @MTC_CA_PARAM / 费用池抽取到 MTC_CA_C_*，账期检查、运行记录和后面各步都用抽取后的值（用户 2026-10-29：
    -- 每次发起先读 B1 再算；P20 快照里还会再同步一次并记 P05 步骤）
    CALL "MTC_CA_P05_CFG_SYNC"(NULL);
    COMMIT;

    -- P00 准备：正式计算先看账期状态（已生成凭单的账期拒绝，不建运行头；用户 2026-10-19）
    IF IFNULL(:RunType, '') = 'F' THEN
        CALL "MTC_CA_P_PERIOD_GUARD"(:FcCode, 'CALC', Code, warn);
        IF :Code <> 0 THEN
            SELECT :Code AS "Code", :warn AS "Msg", CAST(NULL AS BIGINT) AS "RunId" FROM DUMMY;
            RETURN;
        END IF;
    END IF;
    CALL "MTC_CA_P_RUN_BEGIN"(:FcCode, :RunType, :Scenario, :UserCode, IFNULL(:Initiator, 'USER'), RunId, Code, Msg);
    IF :Code <> 0 THEN
        SELECT :Code AS "Code", :Msg AS "Msg", :RunId AS "RunId" FROM DUMMY;
        RETURN;
    END IF;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P00', CASE WHEN :warn <> '' THEN 'WARN' ELSE 'OK' END, NULL,
                             '参数、账期、并发检查通过' || CASE WHEN :warn <> '' THEN '；' || :warn ELSE '' END);

    -- P20 快照（先取快照，P10 在快照上检查）
    CALL "MTC_CA_P20_SNAPSHOT"(:RunId);
    COMMIT;

    -- P10 计算前检查：有阻断项就停止，保留检查结果和本次快照（2026-11-04：阻断时看当月交易明细，P_RUN_CLEAN BLK 只删以前保留的）
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P10', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P10_PRECHECK"(:RunId, nBlk);
    CALL "MTC_CA_P10_QCP"(:RunId, n);       -- PRE-23 需要维护期初成本价的物料（警告，不阻断）
    CALL "MTC_CA_P10_HOURS"(:RunId, n);     -- PRE-14 按物料汇总的需要维护工时的产品（清单，阻断时也保留）
    COMMIT;
    IF :nBlk > 0 THEN
        CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P10', 'FAIL', :nBlk, '阻断项数');
        CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'BLK', n);
        COMMIT;
        CALL "MTC_CA_P_RUN_END"(:RunId, 'BLOCKED', :nBlk || ' 项计算前检查未通过，见 MTC_CA_R_CHECK / MTC_CA_R_CHECK_DTL');
        SELECT -2 AS "Code", :nBlk || ' 项计算前检查未通过，见 MTC_CA_R_CHECK' AS "Msg", :RunId AS "RunId" FROM DUMMY;
        RETURN;
    END IF;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P10', 'OK', 0, '阻断项数');

    -- P30 初始化与固定价格
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P30', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P30_INIT"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P30', 'OK', :n, '单据行数');

    -- P31 模拟场景假设（只在 RunType = S 时调整，设计稿第 8 节）
    IF :RunType = 'S' THEN
        CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P31', 'RUNNING', NULL, NULL);
        CALL "MTC_CA_P31_SCENARIO"(:RunId, n, Msg);
        COMMIT;
        CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P31', 'OK', :n, :Msg);
    END IF;

    -- P40 迭代
    stage := 'P40';
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P40', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P40_ITERATE"(:RunId, conv, iters);
    UPDATE "MTC_CA_RUN" SET "IterCount" = :iters, "Converged" = :conv WHERE "RunId" = :RunId;
    COMMIT;
    IF :conv <> 'Y' THEN
        CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P40', 'FAIL', :iters, '达到最大迭代轮数仍未收敛，见 MTC_CA_RUN_ITER / MTC_CA_RUN_ITER_ITEM');
        keepNc := IFNULL("MTC_CA_F_PARAM"('KEEP_NOCONV', :FcCode), 'Y');
        IF :keepNc = 'Y' THEN
            CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'NCV', n);
            Msg := '未定稿，最后一轮的中间结果保留供排查；';
        ELSE
            CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'FAIL', n);
            Msg := '未写结果；';
        END IF;
        COMMIT;
        CALL "MTC_CA_P_RUN_END"(:RunId, 'NOCONV', '迭代 ' || :iters || ' 轮未收敛，' || :Msg || '上一次成功运行的结果保留');
        SELECT -3 AS "Code", '迭代 ' || :iters || ' 轮未收敛，见 MTC_CA_RUN_ITER' AS "Msg", :RunId AS "RunId" FROM DUMMY;
        RETURN;
    END IF;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P40', 'OK', :iters, '迭代轮数');

    -- P50 定稿
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P50', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P50_FINALIZE"(:RunId, :iters);
    CALL "MTC_CA_P55_REVAL"(:RunId, n);     -- 库存重估清单（用户 2026-11-04），只写清单，不写 B1
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P50', 'OK', NULL, NULL);

    -- P60 计算后校验、指标快照
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P60', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P60_POSTCHECK"(:RunId, nFail);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P60', CASE WHEN :nFail > 0 THEN 'BLOCKED' ELSE 'OK' END, :nFail, '未通过的校验数（计算后校验不通过即阻断）');

    -- P65 新旧比对
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P65', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P65_COMPARE"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P65', 'OK', :n, '有差异的物料 / 订单数');

    -- P71 发出商品与交货成本、P73 应付暂估、P74 应付暂估凭证、P70 凭证、P75 凭证与暂估校验
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P71', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P71_SALES"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P71', 'OK', :n, '未清交货 / 退货行数');
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P73', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P73_AP_ACCR"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P73', 'OK', :n, '未清收货 / 退货行数');
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P74', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P74_AP_JDT"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P74', 'OK', :n, '应付暂估凭证来源行数');
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P70', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P70_JDT"(:RunId, n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P70', 'OK', :n, '凭证行数');
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P75', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P75_POSTCHECK"(:RunId, nFail);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P75', CASE WHEN :nFail > 0 THEN 'BLOCKED' ELSE 'OK' END, :nFail, '未通过的校验数（计算后校验不通过即阻断）');

    -- P80 收尾：删除同运行键下旧明细
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P80', 'RUNNING', NULL, NULL);
    CALL "MTC_CA_P_RUN_CLEAN"(:RunId, 'OK', n);
    COMMIT;
    CALL "MTC_CA_P_LOG_STEP"(:RunId, 'P80', 'OK', :n, '删除旧明细行数');
    -- 计算后校验不通过一律阻断（用户 2026-10-14）：结果保留供排查，运行说明里写明哪几项阻断、处理前不能过账
    SELECT COUNT(*) INTO nFail
      FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "Stage" = 'POST' AND "Result" = 'FAIL';
    postFail := '';
    IF :nFail > 0 THEN
        SELECT LEFT(STRING_AGG("CheckId", '、' ORDER BY "CheckId"), 900) INTO postFail
          FROM "MTC_CA_R_CHECK" WHERE "RunId" = :RunId AND "Stage" = 'POST' AND "Result" = 'FAIL';
    END IF;
    Msg := '计算完成，迭代 ' || :iters || ' 轮'
           || CASE WHEN :nFail > 0 THEN '；计算后校验 ' || :nFail || ' 项未通过（阻断）：' || :postFail || '，处理前不能过账' ELSE '' END;
    -- 账期状态：正式计算成功 → CALC，记下这次运行（计算后校验不通过也记，生成凭单时再拦）
    IF :RunType = 'F' THEN
        CALL "MTC_CA_P_PERIOD_SET"(:FcCode, 'CALC', :RunId, :UserCode, :Msg);
        COMMIT;
    END IF;
    CALL "MTC_CA_P_RUN_END"(:RunId, 'OK', :Msg);
    SELECT 0 AS "Code", :Msg AS "Msg", :RunId AS "RunId" FROM DUMMY;
END

@@
-- @stmt 新框架 同步数据字典
CALL "MTC_CA_P_META_SYNC"()

@@
-- @stmt B1 配置校验 20_b1cfg_check.sql #1
-- @needs @MTC_CA_PARAM,@MTC_CA_POOL,@MTC_CA_POOL1,@MTC_CA_POOL2,OPRC.U_CalType,OITB.U_ItemGrpType
-- =====================================================================
-- B1 成本配置校验（用户 2026-10-28）：@MTC_CA_PARAM 计算参数、@MTC_CA_POOL / 1 / 2 费用池
--   MTC_CA_V_B1CFG_ISSUES  问题清单（Obj, KeyCode, Msg）：B1 保存校验、P05 同步、执行台“检查 B1 配置”共用这一个口径
--   MTC_CA_P_B1CFG_TN      给 SBO_SP_TransactionNotification 调用：保存的那条记录有问题时返回 error = 1 和中文提示
--                          （TN 里加的那一段见 20_b1cfg_tn_snippet.sql）
-- 视图直接引用 B1 自定义表。2026-10-29 起进部署包（用户决定）：每条带 -- @needs，部署程序检查 @MTC_CA_PARAM、@MTC_CA_POOL / 1 / 2、
--   OPRC.U_CalType、OITB.U_ItemGrpType 都在才执行，缺了跳过并列出缺什么；B1 补齐后重新部署即可。也可以单独执行本文件：
--   python3 新框架/tools/hana_exec.py -f 新框架/sql/20_b1cfg_check.sql
-- 没有这个视图时 P05 不同步 @MTC_CA_PARAM（计算参数只用新框架现有值），执行台“检查 B1 配置”也用不了。
-- 依赖 MTC_CA_C_PARAM_DEF（02 / 04 或 patch_20261028_param_ui.sql）。离线写的，还没编译。
-- 2026-10-29 起还依赖 MTC_CA_C_PARAM_B1、MTC_CA_P_PARAM_B1_SNAP、MTC_CA_P_PARAM_LOCK_CHECK（02 / 07，部署包已含）；
--   B1 字段 U_Locked（锁定）可选，没加时都算不锁定。
-- KeyCode = 记录的 Code（参数行的 Code；费用池是池代码，成本中心 / 分摊范围的问题也记在池上，Msg 写明第几行）。
-- 账期为空 = 不限（起始 0000-00、截止 9999-99）。
-- =====================================================================
CREATE OR REPLACE VIEW "MTC_CA_V_B1CFG_ISSUES" AS
-- ---------- 计算参数 @MTC_CA_PARAM ----------
SELECT 'MTC_CA_PARAM' AS "Obj", B."Code" AS "KeyCode",
       CASE WHEN B."P" = 'CLOSE_DIF_POOL' THEN '关单差异池不在这里维护，请在费用池上勾“关单差异池”'
            ELSE '参数代码 ' || B."P" || ' 不认识（Code 应是参数代码，第二段起写 参数代码@起始账期）' END AS "Msg"
  FROM (SELECT TRIM("Code") AS "Code", SUBSTR_BEFORE(TRIM("Code") || '@', '@') AS "P" FROM "@MTC_CA_PARAM") B
 WHERE NOT EXISTS (SELECT 1 FROM "MTC_CA_C_PARAM_DEF" D WHERE D."ParamCode" = B."P")
UNION ALL
SELECT 'MTC_CA_PARAM', TRIM("Code"), 'Code 中 @ 后面应等于起始账期 ' || IFNULL(NULLIF(TRIM("U_FromFc"), ''), '（空）')
  FROM "@MTC_CA_PARAM"
 WHERE SUBSTR_AFTER(TRIM("Code"), '@') <> '' AND SUBSTR_AFTER(TRIM("Code"), '@') <> IFNULL(TRIM("U_FromFc"), '')
UNION ALL
SELECT 'MTC_CA_PARAM', TRIM("Code"), '起始账期 ' || TRIM("U_FromFc") || ' 不是 YYYY-MM 格式（如 2026-11）'
  FROM "@MTC_CA_PARAM"
 WHERE IFNULL(TRIM("U_FromFc"), '') <> '' AND NOT TRIM("U_FromFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$'
UNION ALL
SELECT 'MTC_CA_PARAM', TRIM("Code"), '截止账期 ' || TRIM("U_ToFc") || ' 不是 YYYY-MM 格式（如 2026-11）'
  FROM "@MTC_CA_PARAM"
 WHERE IFNULL(TRIM("U_ToFc"), '') <> '' AND NOT TRIM("U_ToFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$'
UNION ALL
SELECT 'MTC_CA_PARAM', TRIM("Code"), '起始账期晚于截止账期'
  FROM "@MTC_CA_PARAM"
 WHERE IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') > IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99')
UNION ALL
-- 同一参数的账期段重叠（两行各报一次）
SELECT 'MTC_CA_PARAM', A."Code", '与 ' || B."Code" || ' 的账期重叠：同一参数每个账期只能有一个值'
  FROM (SELECT TRIM("Code") AS "Code", SUBSTR_BEFORE(TRIM("Code") || '@', '@') AS "P",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T" FROM "@MTC_CA_PARAM") A
  JOIN (SELECT TRIM("Code") AS "Code", SUBSTR_BEFORE(TRIM("Code") || '@', '@') AS "P",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T" FROM "@MTC_CA_PARAM") B
    ON B."P" = A."P" AND B."Code" <> A."Code" AND A."F" <= B."T" AND B."F" <= A."T"
UNION ALL
-- 取值：按参数目录的类型检查
SELECT 'MTC_CA_PARAM', B."Code",
       CASE WHEN B."V" = '' THEN '取值不能为空'
            WHEN D."DataType" = 'DEC'  THEN '取值应是数字，实际 ' || B."V"
            WHEN D."DataType" = 'INT'  THEN '取值应是整数，实际 ' || B."V"
            WHEN D."DataType" = 'FC'   THEN '取值应是账期 YYYY-MM，实际 ' || B."V"
            WHEN D."DataType" = 'DATE' THEN '取值应是日期 YYYY-MM-DD，实际 ' || B."V"
            WHEN D."DataType" = 'LIST' THEN '列表太长（最多 196 个字符）'
            ELSE '取值只能是 ' || D."Choices" || '，实际 ' || B."V" END
  FROM (SELECT TRIM("Code") AS "Code", SUBSTR_BEFORE(TRIM("Code") || '@', '@') AS "P", IFNULL(TRIM("U_Value"), '') AS "V" FROM "@MTC_CA_PARAM") B
  JOIN "MTC_CA_C_PARAM_DEF" D ON D."ParamCode" = B."P"
 WHERE (B."V" = '' AND D."DataType" <> 'LIST')
    OR (B."V" <> '' AND D."DataType" = 'DEC'  AND NOT B."V" LIKE_REGEXPR '^-?[0-9]+(\.[0-9]+)?$')
    OR (B."V" <> '' AND D."DataType" = 'INT'  AND NOT B."V" LIKE_REGEXPR '^-?[0-9]+$')
    OR (B."V" <> '' AND D."DataType" = 'FC'   AND NOT B."V" LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$')
    OR (B."V" <> '' AND D."DataType" = 'DATE' AND NOT B."V" LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$')
    OR (D."DataType" = 'LIST' AND LENGTH(B."V") > 196)
    OR (B."V" <> '' AND D."DataType" = 'STR' AND IFNULL(D."Choices", '') <> ''
        AND NOT (',' || D."Choices" || ',') LIKE ('%,' || UPPER(B."V") || ',%'))
UNION ALL
-- ---------- 费用池表头 @MTC_CA_POOL ----------
SELECT 'MTC_CA_POOL', TRIM("Code"), '“默认池”只能填 Y 或 N'
  FROM "@MTC_CA_POOL" WHERE IFNULL("U_IsDefault", 'N') NOT IN ('Y', 'N')
UNION ALL
SELECT 'MTC_CA_POOL', TRIM("Code"), '“关单差异池”只能填 Y 或 N'
  FROM "@MTC_CA_POOL" WHERE IFNULL("U_IsCloseDif", 'N') NOT IN ('Y', 'N')
UNION ALL
-- 正好一个由 PRE-18 在运行时查；保存时只挡“多于一个”，换池时可以先取消原来的再设新的
SELECT 'MTC_CA_POOL', "Code", '默认池只能有一个，现在有 ' || "N" || ' 个'
  FROM (SELECT TRIM("Code") AS "Code", COUNT(*) OVER () AS "N" FROM "@MTC_CA_POOL" WHERE "U_IsDefault" = 'Y') X
 WHERE "N" > 1
UNION ALL
SELECT 'MTC_CA_POOL', "Code", '关单差异池只能有一个，现在有 ' || "N" || ' 个'
  FROM (SELECT TRIM("Code") AS "Code", COUNT(*) OVER () AS "N" FROM "@MTC_CA_POOL" WHERE "U_IsCloseDif" = 'Y') X
 WHERE "N" > 1
UNION ALL
-- ---------- 成本中心 @MTC_CA_POOL1 ----------
SELECT 'MTC_CA_POOL', TRIM(S."Code"), '成本中心第 ' || S."LineId" || ' 行：' || TRIM(S."U_OcrCode") || ' 不是成本中心代码，也没有成本中心的成本计入类型（U_CalType）等于它'
  FROM "@MTC_CA_POOL1" S
 WHERE IFNULL(TRIM(S."U_OcrCode"), '') <> ''
   AND NOT EXISTS (SELECT 1 FROM "OPRC" P WHERE P."PrcCode" = TRIM(S."U_OcrCode") OR TRIM(P."U_CalType") = TRIM(S."U_OcrCode"))
UNION ALL
SELECT 'MTC_CA_POOL', TRIM("Code"), '成本中心第 ' || "LineId" || ' 行：起止账期应是 YYYY-MM（如 2026-11），且起始不晚于截止'
  FROM "@MTC_CA_POOL1"
 WHERE (IFNULL(TRIM("U_FromFc"), '') <> '' AND NOT TRIM("U_FromFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$')
    OR (IFNULL(TRIM("U_ToFc"), '') <> '' AND NOT TRIM("U_ToFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$')
    OR IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') > IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99')
UNION ALL
-- 同一成本中心（或成本计入类型）账期重叠，含跨池：一个成本中心同一账期只能进一个池
SELECT 'MTC_CA_POOL', A."Code", '成本中心第 ' || A."LineId" || ' 行：' || A."Ocr" || ' 与费用池 ' || B."Code" || ' 第 ' || B."LineId" || ' 行的账期重叠'
  FROM (SELECT TRIM("Code") AS "Code", "LineId", TRIM("U_OcrCode") AS "Ocr",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T"
          FROM "@MTC_CA_POOL1" WHERE IFNULL(TRIM("U_OcrCode"), '') <> '') A
  JOIN (SELECT TRIM("Code") AS "Code", "LineId", TRIM("U_OcrCode") AS "Ocr",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T"
          FROM "@MTC_CA_POOL1" WHERE IFNULL(TRIM("U_OcrCode"), '') <> '') B
    ON B."Ocr" = A."Ocr" AND NOT (B."Code" = A."Code" AND B."LineId" = A."LineId") AND A."F" <= B."T" AND B."F" <= A."T"
UNION ALL
-- ---------- 分摊范围 @MTC_CA_POOL2 ----------
SELECT 'MTC_CA_POOL', TRIM("Code"), '分摊范围第 ' || "LineId" || ' 行：匹配方式只能是 GRPTYPE（车间类别）或 GRP（物料组），实际 ' || TRIM("U_MatchBy")
  FROM "@MTC_CA_POOL2"
 WHERE IFNULL(TRIM("U_MatchVal"), '') <> '' AND UPPER(IFNULL(TRIM("U_MatchBy"), '')) NOT IN ('', 'GRP', 'GRPTYPE')
UNION ALL
SELECT 'MTC_CA_POOL', TRIM(T."Code"),
       '分摊范围第 ' || T."LineId" || ' 行：' || CASE WHEN UPPER(IFNULL(TRIM(T."U_MatchBy"), '')) = 'GRP' THEN '物料组 ' ELSE '车间类别（物料组上的 U_ItemGrpType）' END
       || TRIM(T."U_MatchVal") || ' 不存在'
  FROM "@MTC_CA_POOL2" T
 WHERE IFNULL(TRIM(T."U_MatchVal"), '') <> ''
   AND ((UPPER(IFNULL(TRIM(T."U_MatchBy"), '')) = 'GRP'
         AND NOT EXISTS (SELECT 1 FROM "OITB" B WHERE TO_NVARCHAR(B."ItmsGrpCod") = TRIM(T."U_MatchVal")))
     OR (UPPER(IFNULL(TRIM(T."U_MatchBy"), '')) IN ('', 'GRPTYPE')
         AND NOT EXISTS (SELECT 1 FROM "OITB" B WHERE TRIM(B."U_ItemGrpType") = TRIM(T."U_MatchVal"))))
UNION ALL
SELECT 'MTC_CA_POOL', TRIM("Code"), '分摊范围第 ' || "LineId" || ' 行：订单类型只能填数字，用逗号分隔（如 10,20,30,40），空 = 10,20,30,40'
  FROM "@MTC_CA_POOL2"
 WHERE IFNULL(TRIM("U_WorTypes"), '') <> ''
   AND NOT REPLACE(REPLACE(TRIM("U_WorTypes"), ' ', ''), '，', ',') LIKE_REGEXPR '^[0-9]+(,[0-9]+)*$'
UNION ALL
SELECT 'MTC_CA_POOL', TRIM("Code"), '分摊范围第 ' || "LineId" || ' 行：起止账期应是 YYYY-MM（如 2026-11），且起始不晚于截止'
  FROM "@MTC_CA_POOL2"
 WHERE (IFNULL(TRIM("U_FromFc"), '') <> '' AND NOT TRIM("U_FromFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$')
    OR (IFNULL(TRIM("U_ToFc"), '') <> '' AND NOT TRIM("U_ToFc") LIKE_REGEXPR '^[0-9]{4}-(0[1-9]|1[0-2])$')
    OR IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') > IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99')
UNION ALL
-- 同一匹配方式 + 匹配值账期重叠，含跨池（Q22：同一产品只能属于一个池；混用 GRP / GRPTYPE 的重叠由 PRE-18 按产品查）
SELECT 'MTC_CA_POOL', A."Code", '分摊范围第 ' || A."LineId" || ' 行：' || A."MB" || ' ' || A."MV" || ' 与费用池 ' || B."Code" || ' 第 ' || B."LineId" || ' 行的账期重叠'
  FROM (SELECT TRIM("Code") AS "Code", "LineId", UPPER(IFNULL(NULLIF(TRIM("U_MatchBy"), ''), 'GRPTYPE')) AS "MB", TRIM("U_MatchVal") AS "MV",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T"
          FROM "@MTC_CA_POOL2" WHERE IFNULL(TRIM("U_MatchVal"), '') <> '') A
  JOIN (SELECT TRIM("Code") AS "Code", "LineId", UPPER(IFNULL(NULLIF(TRIM("U_MatchBy"), ''), 'GRPTYPE')) AS "MB", TRIM("U_MatchVal") AS "MV",
               IFNULL(NULLIF(TRIM("U_FromFc"), ''), '0000-00') AS "F", IFNULL(NULLIF(TRIM("U_ToFc"), ''), '9999-99') AS "T"
          FROM "@MTC_CA_POOL2" WHERE IFNULL(TRIM("U_MatchVal"), '') <> '') B
    ON B."MB" = A."MB" AND B."MV" = A."MV" AND NOT (B."Code" = A."Code" AND B."LineId" = A."LineId") AND A."F" <= B."T" AND B."F" <= A."T"

@@
-- @stmt B1 配置校验 20_b1cfg_check.sql #2
-- @needs @MTC_CA_PARAM,@MTC_CA_POOL,@MTC_CA_POOL1,@MTC_CA_POOL2,OPRC.U_CalType,OITB.U_ItemGrpType
COMMENT ON VIEW "MTC_CA_V_B1CFG_ISSUES" IS 'B1 成本配置（@MTC_CA_PARAM、@MTC_CA_POOL / 1 / 2）的问题清单：B1 保存校验、P05 同步、执行台“检查 B1 配置”共用'

@@
-- @stmt B1 配置校验 20_b1cfg_check.sql #3
-- @needs @MTC_CA_PARAM,@MTC_CA_POOL,@MTC_CA_POOL1,@MTC_CA_POOL2,OPRC.U_CalType,OITB.U_ItemGrpType
-- SBO_SP_TransactionNotification 调用（object_type = UDO 代码，KeyVal = list_of_cols_val_tab_del = 记录的 Code）
-- 2026-10-29：计算参数另做锁定检查（MTC_CA_P_PARAM_LOCK_CHECK，U_Locked = Y 的行不能改值、不能删），通过后刷新这条的快照
--   MTC_CA_C_PARAM_B1。删除（D）只做锁定检查：TN 片段对 MTC_CA_PARAM 的 D 也调用本过程（见 20_b1cfg_tn_snippet.sql）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_B1CFG_TN" (IN ObjType NVARCHAR(30), IN KeyVal NVARCHAR(255),
                                                 OUT err INT, OUT errMsg NVARCHAR(200))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE n INT;
    DECLARE lockMsg NVARCHAR(200);
    err := 0; errMsg := '';
    SELECT COUNT(*) INTO n FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = :ObjType AND "KeyCode" = TRIM(:KeyVal);
    IF :n > 0 THEN
        SELECT TOP 1 LEFT('[成本配置] ' || "KeyCode" || '：' || "Msg" || CASE WHEN :n > 1 THEN '（共 ' || :n || ' 个问题）' ELSE '' END, 200)
          INTO errMsg
          FROM "MTC_CA_V_B1CFG_ISSUES" WHERE "Obj" = :ObjType AND "KeyCode" = TRIM(:KeyVal) ORDER BY "Msg";
        err := 1;
        RETURN;
    END IF;
    IF :ObjType = 'MTC_CA_PARAM' THEN
        CALL "MTC_CA_P_PARAM_LOCK_CHECK"(:KeyVal, lockMsg);
        IF :lockMsg <> '' THEN
            err := 1; errMsg := :lockMsg;
            RETURN;
        END IF;
        CALL "MTC_CA_P_PARAM_B1_SNAP"(:KeyVal, 'TN');
    END IF;
END

@@
-- @stmt B1 配置校验 20_b1cfg_check.sql #4
-- @needs @MTC_CA_PARAM,@MTC_CA_POOL,@MTC_CA_POOL1,@MTC_CA_POOL2,OPRC.U_CalType,OITB.U_ItemGrpType
-- 装好后先把 B1 现有参数记一次快照（锁定从这一刻起生效）
CALL "MTC_CA_P_PARAM_B1_SNAP"(NULL, 'SYNC')

@@
-- @stmt 成本报表 21_reports.sql #1
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- =====================================================================
-- 新成本框架：成本报表（用户 2026-10-30，设计稿 8.7；替代旧 MTC_RPT_CO* 报表）
-- 25 个只读存储过程 MTC_CA_RPT_00 … 24，B1 查询管理器里存 CALL "MTC_CA_RPT_xx"('[%0]', …) 打开，
-- 执行台“成本报表”页调同一批过程（actions.json rpt00 … rpt24），口径只有一套。
--
-- 通用约定：
--   · 参数全部 NVARCHAR，留空 = 全部；多个值用英文逗号（中文逗号也认）；物料编码、订单号、业务伙伴等代码按开头匹配，值前加 = 精确匹配（如 =A1）。
--   · 账期 FcFrom / FcTo（OFPR.Code）：FcFrom 空 = 最近一个已计算账期，FcTo 空 = FcFrom。单期报表只有 Fc；对比账期 CmpFc 空 = 上期。
--   · 取哪次运行（MTC_CA_F_RPT_RUN）：账期已生成凭单 → MTC_CA_PERIOD.PostRunId，否则 → CalcRunId（最近一次成功的正式运行）；
--     不跟执行台顶栏所选的运行走，网页和 SAP 看到的永远一样。承接账期（BOOTSTRAP_FC）及以前取旧框架回填的历史运行（RunType H，
--     22_legacy_load.sql，用户 2026-11-02），从上线（2024-12）起连续可查；历史期 R08 / R11 / R14 / R17 / R18 没有数据，返回一行提示。
--   · STYPE 显示方式：0 汇总 / 1 明细 / 2… 各报表在头注释里写明。NonZero = Y 只显示有数量或金额的行。
--   · 四项成本要素：材料 / 人工 / 制造 / 委外；列名用“·”分组（执行台拆成两行表头）。
--   · 过程只读（READS SQL DATA），只返回一个结果集，不写任何表；执行台在只读事务里 CALL。
--   · 业务口径参数（委外订单类型、样品销售类型、国内 / 国外客户）一律读 MTC_CA_C_PARAM，不写死。
-- 部署：build_deploy.py 把本文件放进部署包（带 -- @needs，B1 表齐了才执行）；单独部署 python3 新框架/tools/hana_exec.py -f 新框架/sql/21_reports.sql。
-- 勾稽语句：21_reports_verify.sql（每段正常返回 0 行）。离线写的，还没编译。
-- =====================================================================

-- 新参数：物料组 → 存货类别（R16 期末存货结构用）。格式 物料组:类别，逗号分隔，如 101:原材料,102:原材料,105:产成品；
-- 没列的物料组按 BOM 判断：层级 0 = 原材料，是别的物料的子件 = 半成品，其余 = 产成品
UPSERT "MTC_CA_C_PARAM" ("ParamCode", "FromFc", "ToFc", "Value", "DataType", "Descr") VALUES ('RPT_GRP_CLASS', '0000-00', '9999-99', ',', 'LIST', '成本报表 R16：物料组 → 存货类别（物料组:类别，逗号分隔）；没列的物料组按 BOM 判断（层级 0 原材料 / 是子件的半成品 / 其余产成品），用户 2026-10-30') WITH PRIMARY KEY

@@
-- @stmt 成本报表 21_reports.sql #2
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
UPSERT "MTC_CA_C_PARAM_DEF" ("ParamCode", "Target", "Category", "SortNo", "CnName", "DataType", "Choices", "Hint") VALUES ('RPT_GRP_CLASS', 'PARAM', '凭证与对账', 520, '成本报表：物料组对应的存货类别', 'LIST', NULL, '物料组:类别，逗号分隔，如 101:原材料,105:产成品；可以为空 = 全部按 BOM 判断') WITH PRIMARY KEY

@@
-- @stmt 成本报表 21_reports.sql #3
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- 单据类型的中文名（用户 2026-11-11：报表上显示中文）：B1 对象类型 + 订单（202 / MTC_OWOR）+ 自定义单据，名称同视图 MTC_DocType（订单两项同 MTC_CA_F_RPT_OTNAME）；认不出的原样返回代码
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_DTNAME" (IN ObjType NVARCHAR(20))
RETURNS N NVARCHAR(30)
LANGUAGE SQLSCRIPT AS
BEGIN
    N := CASE :ObjType
           WHEN '13' THEN '应收发票' WHEN '14' THEN '应收贷项' WHEN '15' THEN '销售交货' WHEN '16' THEN '销售退货' WHEN '17' THEN '销售订单'
           WHEN '18' THEN '应付发票' WHEN '19' THEN '应付贷项' WHEN '20' THEN '采购收货' WHEN '21' THEN '采购退货' WHEN '22' THEN '采购订单'
           WHEN '23' THEN '销售报价单' WHEN '24' THEN '收款单' WHEN '29' THEN '日记帐凭证' WHEN '30' THEN '日记帐分录' WHEN '46' THEN '付款单'
           WHEN '59' THEN '其他收货' WHEN '60' THEN '其他发货' WHEN '67' THEN '库存转储' WHEN '162' THEN '库存重估' WHEN '10000071' THEN '盘点过帐'
           WHEN '202' THEN '生产订单' WHEN 'MTC_OWOR' THEN '返工单' WHEN 'MTC_OMRV' THEN '库存重估单'
           WHEN 'MTC_CSOIGE' THEN '领料申请' WHEN 'MTC_FHTZ' THEN '发货通知单' WHEN 'MTC_JCTZ' THEN '采购到货单'
           ELSE :ObjType END;
END

@@
-- @stmt 成本报表 21_reports.sql #4
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- 订单单据、订单类型的中文名（用户 2026-11-11：报表上显示中文，名称同旧 CO4011 / CO4013）；认不出的原样返回代码，空返回空
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_OTNAME" (IN OrderType NVARCHAR(20))
RETURNS N NVARCHAR(20)
LANGUAGE SQLSCRIPT AS
BEGIN
    N := CASE :OrderType WHEN '202' THEN '生产订单' WHEN 'MTC_OWOR' THEN '返工单' ELSE :OrderType END;
END

@@
-- @stmt 成本报表 21_reports.sql #5
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_WTNAME" (IN WorType NVARCHAR(10))
RETURNS N NVARCHAR(20)
LANGUAGE SQLSCRIPT AS
BEGIN
    N := CASE :WorType WHEN '10' THEN '生产计划单' WHEN '20' THEN '包装计划单' WHEN '30' THEN '返工计划单' WHEN '40' THEN '生产试打'
                       WHEN '50' THEN '委外工单' ELSE :WorType END;
END

@@
-- @stmt 成本报表 21_reports.sql #6
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- 逗号列表拆成行（空串 → 0 行）；最多 200 个值。V = 值，P = 开头匹配用的 LIKE 模式；值以 = 开头时精确匹配（如 =A1 不会匹配 A10，执行台钻取明细时用）
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_LIST" (IN Str NVARCHAR(5000))
RETURNS TABLE ("V" NVARCHAR(200), "P" NVARCHAR(201))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE s NVARCHAR(5000) := REPLACE(IFNULL(:Str, ''), '，', ',');
    RETURN SELECT DISTINCT CASE WHEN LEFT("V", 1) = '=' THEN SUBSTRING("V", 2) ELSE "V" END AS "V",
                           CASE WHEN LEFT("V", 1) = '=' THEN SUBSTRING("V", 2) ELSE "V" || '%' END AS "P"
             FROM (SELECT TRIM(SUBSTR_REGEXPR('[^,]+' IN :s OCCURRENCE TO_INTEGER(G."GENERATED_PERIOD_START"))) AS "V"
                     FROM SERIES_GENERATE_INTEGER(1, 1, 201) G)
            WHERE "V" IS NOT NULL AND "V" <> '' AND "V" <> '=';
END

@@
-- @stmt 成本报表 21_reports.sql #7
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- 账期 → 取数运行（所有报表共用“取哪次运行”的规则）：一行 = 区间内一个账期（OFPR），没有可用运行的 RunId 为空
-- 承接账期 BOOTSTRAP_FC 及以前 → 最近一次成功的历史运行（RunType H，旧框架回填，22_legacy_load.sql；用户 2026-11-02 报表合并：
-- 并行期以前取旧框架，即使这些账期有新框架的测试运行也不用）；以后 → 新框架：已生成凭单取 PostRunId，否则取 CalcRunId
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_RUN" (IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10))
RETURNS TABLE ("FcCode" NVARCHAR(10), "RunId" BIGINT, "PStatus" NVARCHAR(10), "PStatusName" NVARCHAR(20), "RunSrc" NVARCHAR(30),
               "EndTime" TIMESTAMP, "UserCode" NVARCHAR(50), "Batches" NVARCHAR(1000), "D0" DATE, "D1" DATE, "PrevFc" NVARCHAR(10),
               "Note" NVARCHAR(200))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE f0 NVARCHAR(10); DECLARE f1 NVARCHAR(10); DECLARE t NVARCHAR(10); DECLARE boot NVARCHAR(10);
    f0 := NULLIF(TRIM(IFNULL(:FcFrom, '')), '');
    f1 := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    boot := IFNULL("MTC_CA_F_PARAM"('BOOTSTRAP_FC', IFNULL(:f1, IFNULL(:f0, TO_NVARCHAR(CURRENT_DATE, 'YYYY-MM')))), '0000-00');
    IF :f0 IS NULL THEN
        SELECT MAX("FcCode") INTO f0 FROM "MTC_CA_PERIOD" WHERE IFNULL("PostRunId", "CalcRunId") IS NOT NULL AND "FcCode" > :boot;
    END IF;
    IF :f0 IS NULL THEN   -- 新框架还没有算过：取最近一个历史运行的账期
        SELECT MAX("FcCode") INTO f0 FROM "MTC_CA_RUN" WHERE "RunType" = 'H' AND "Status" = 'OK';
    END IF;
    IF :f1 IS NULL THEN f1 := :f0; END IF;
    IF :f1 < :f0 THEN t := :f0; f0 := :f1; f1 := :t; END IF;
    RETURN
    SELECT X."FcCode", X."RunId",
           CASE WHEN X."Lock" = 'Y' THEN 'LOCKED' WHEN X."Hist" = 'Y' THEN 'HIST' ELSE IFNULL(X."St", 'OPEN') END AS "PStatus",
           CASE WHEN X."Hist" = 'Y' THEN CASE WHEN X."RunId" IS NOT NULL THEN '历史（旧框架回填）' ELSE '历史（未回填）' END
                WHEN X."St" = 'POSTED' THEN '已生成凭单' WHEN X."St" = 'CALC' THEN '已计算' ELSE '未计算' END
             || CASE WHEN X."Lock" = 'Y' THEN '（B1 已锁定）' ELSE '' END AS "PStatusName",
           CASE WHEN X."Hist" = 'Y' THEN CASE WHEN X."RunId" IS NOT NULL THEN '旧框架回填' END
                WHEN X."PostRunId" IS NOT NULL THEN '生成凭单所用运行' WHEN X."CalcRunId" IS NOT NULL THEN '最近一次成功正式运行' END AS "RunSrc",
           R."EndTime", R."UserCode", CASE WHEN X."Hist" = 'N' THEN J."Batches" END AS "Batches",
           X."D0", X."D1", X."PrevFc",
           CASE WHEN X."RunId" IS NULL
                THEN CASE WHEN X."Hist" = 'Y' THEN '承接账期及以前取旧框架回填，这一期还没有回填（22_legacy_load.sql）' ELSE '本期没有成功的正式计算' END
                WHEN R."RunId" IS NULL THEN '运行记录不存在'
                WHEN NOT EXISTS (SELECT 1 FROM "MTC_CA_R_ITEM" I WHERE I."RunId" = R."RunId") THEN '运行明细已清理，报表没有数据'
                WHEN X."Hist" = 'Y' THEN '历史期：料工费按旧框架完工比例拆分；发出商品、应付暂估、校验结果没有' END AS "Note"
      FROM (SELECT O."Code" AS "FcCode", CASE WHEN O."Code" <= :boot THEN 'Y' ELSE 'N' END AS "Hist",
                   CASE WHEN O."Code" <= :boot THEN H."RunId" ELSE COALESCE(P."PostRunId", P."CalcRunId") END AS "RunId",
                   P."Status" AS "St", P."PostRunId", P."CalcRunId", O."PeriodStat" AS "Lock",
                   TO_DATE(O."F_RefDate") AS "D0", TO_DATE(O."T_RefDate") AS "D1",
                   (SELECT MAX(Y."Code") FROM "OFPR" Y WHERE Y."Code" < O."Code") AS "PrevFc"
              FROM "OFPR" O
              LEFT JOIN "MTC_CA_PERIOD" P ON P."FcCode" = O."Code"
              LEFT JOIN (SELECT "FcCode", MAX("RunId") AS "RunId" FROM "MTC_CA_RUN"
                          WHERE "RunType" = 'H' AND "Scenario" = 'LEGACY' AND "Status" = 'OK' GROUP BY "FcCode") H ON H."FcCode" = O."Code"
             WHERE O."Code" BETWEEN :f0 AND :f1) X
      LEFT JOIN "MTC_CA_RUN" R ON R."RunId" = X."RunId"
      LEFT JOIN (SELECT "FcCode", LEFT(STRING_AGG(TO_NVARCHAR("TransCode") || ' #' || TO_NVARCHAR("BatchNum"), ', ' ORDER BY "TransCode"), 1000) AS "Batches"
                   FROM "MTC_CA_JV" WHERE "Status" = 'CREATED' AND "BatchNum" IS NOT NULL GROUP BY "FcCode") J ON J."FcCode" = X."FcCode";
END

@@
-- @stmt 成本报表 21_reports.sql #8
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- 区间内只有历史运行（旧框架回填）、没有新框架运行时为 Y：第一阶段不支持历史期的报表（R08 / R11 / R14 / R17 / R18）
-- 这时只返回一行提示（2026-11-02）；区间跨新旧时照常计算，历史期那几个月没有数据
CREATE OR REPLACE FUNCTION "MTC_CA_F_RPT_HISTONLY" (IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10))
RETURNS Flag NVARCHAR(1)
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nH INT; DECLARE nN INT;
    SELECT IFNULL(SUM(CASE WHEN R."RunType" = 'H' THEN 1 ELSE 0 END), 0), IFNULL(SUM(CASE WHEN R."RunType" <> 'H' THEN 1 ELSE 0 END), 0)
      INTO nH, nN
      FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) U JOIN "MTC_CA_RUN" R ON R."RunId" = U."RunId";
    Flag := CASE WHEN :nH > 0 AND :nN = 0 THEN 'Y' ELSE 'N' END;
END

@@
-- @stmt 成本报表 21_reports.sql #9
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R00 成本报表运行状态：各账期报表取的是哪次运行、什么时候算的、凭单批号。
-- 参数：FcFrom, FcTo（都空 = 最近 12 个账期）
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_00_RUN" (IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE f0 NVARCHAR(10) := NULLIF(TRIM(IFNULL(:FcFrom, '')), '');
    DECLARE f1 NVARCHAR(10) := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    DECLARE lastFc NVARCHAR(10);
    IF :f0 IS NULL AND :f1 IS NULL THEN
        SELECT MAX("FcCode") INTO lastFc FROM "MTC_CA_PERIOD";
        SELECT MAX("Code") INTO lastFc FROM "OFPR" WHERE "Code" <= IFNULL(:lastFc, TO_NVARCHAR(CURRENT_DATE, 'YYYY-MM'));
        SELECT MIN("Code") INTO f0 FROM (SELECT TOP 12 "Code" FROM "OFPR" WHERE "Code" <= :lastFc ORDER BY "Code" DESC);
        f1 := :lastFc;
    END IF;
    SELECT R."FcCode" AS "账期", R."PStatusName" AS "账期状态", R."RunId" AS "运行号", R."RunSrc" AS "取数来源",
           R."EndTime" AS "计算完成时间", R."UserCode" AS "操作人", R."Batches" AS "凭单批号", R."D0" AS "期初日", R."D1" AS "期末日",
           R."Note" AS "说明"
      FROM "MTC_CA_F_RPT_RUN"(:f0, IFNULL(:f1, :f0)) R
     ORDER BY R."FcCode" DESC;
END

@@
-- @stmt 成本报表 21_reports.sql #10
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R03 存货收发存汇总：每个物料（或物料组、存货科目）期初、本期入库、出库、期末的数量和四项金额。
-- 参数：FcFrom, FcTo, Item 物料, ItemGrp 物料组, Lvl 层级, ShowElem 展开四项 Y/N, ByCat 按收发类别分列 Y/N, NonZero Y/N,
--       STYPE 0 按物料 / 1 按物料组 / 2 按存货科目（OGAR.StockAct，物料组的存货科目）
-- 口径：MTC_CA_R_ITEM（P50 定稿）；入 / 出按数量正负（数量为 0 的发票差额、重估按交易类型方向）；多个账期时期初取第一期、期末取最后一期、
--       收发累加。按收发类别分列时“本期收发”各列带符号（增加为正），期初 + 各列合计 = 期末（尾差结转单列）。
-- 勾稽：期末金额合计 = R09 存货科目业务端；生产入库 = R01 / R02 完工成本合计（21_reports_verify.sql V01、V03）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_03_INVSUM" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Lvl NVARCHAR(100),
    IN ShowElem NVARCHAR(1), IN ByCat NVARCHAR(1), IN NonZero NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE fA NVARCHAR(10); DECLARE fB NVARCHAR(10);
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nLvl INT;
    DECLARE st NVARCHAR(1) := IFNULL(NULLIF(:STYPE, ''), '0');
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("FcCode"), MAX("FcCode") INTO fA, fB FROM :runs;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lLvl  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Lvl);     SELECT COUNT(*) INTO nLvl FROM :lLvl;

    it = SELECT R."ItemCode",
                MAX(CASE WHEN U."FcCode" = :fB THEN R."iLevel" END) AS "Lv",
                SUM(CASE WHEN U."FcCode" = :fA THEN R."OpenQty" ELSE 0 END) AS "BQ",
                SUM(CASE WHEN U."FcCode" = :fA THEN R."OpenMat" ELSE 0 END) AS "BMat", SUM(CASE WHEN U."FcCode" = :fA THEN R."OpenLab" ELSE 0 END) AS "BLab",
                SUM(CASE WHEN U."FcCode" = :fA THEN R."OpenMfg" ELSE 0 END) AS "BMfg", SUM(CASE WHEN U."FcCode" = :fA THEN R."OpenSub" ELSE 0 END) AS "BSub",
                SUM(R."InQty") AS "IQ", SUM(R."InMat") AS "IMat", SUM(R."InLab") AS "ILab", SUM(R."InMfg") AS "IMfg", SUM(R."InSub") AS "ISub",
                -SUM(R."OutQty") AS "OQ", -SUM(R."OutMat") AS "OMat", -SUM(R."OutLab") AS "OLab", -SUM(R."OutMfg") AS "OMfg", -SUM(R."OutSub") AS "OSub",
                SUM(CASE WHEN U."FcCode" = :fB THEN R."EndQty" ELSE 0 END) AS "EQ",
                SUM(CASE WHEN U."FcCode" = :fB THEN R."EndMat" ELSE 0 END) AS "EMat", SUM(CASE WHEN U."FcCode" = :fB THEN R."EndLab" ELSE 0 END) AS "ELab",
                SUM(CASE WHEN U."FcCode" = :fB THEN R."EndMfg" ELSE 0 END) AS "EMfg", SUM(CASE WHEN U."FcCode" = :fB THEN R."EndSub" ELSE 0 END) AS "ESub",
                SUM(R."TailAmt") AS "CTail"
           FROM :runs U JOIN "MTC_CA_R_ITEM" R ON R."RunId" = U."RunId"
          GROUP BY R."ItemCode";
    cat = SELECT L."ItemCode",
                 SUM(CASE WHEN L."TransCode" IN ('I01', 'I06') THEN L."Amount" ELSE 0 END) AS "CPur",
                 SUM(CASE WHEN L."TransCode" IN ('I03', 'I07', 'I08', 'I09', 'I90') THEN L."Amount" ELSE 0 END) AS "CPrd",
                 SUM(CASE WHEN L."TransCode" IN ('O03', 'O07', 'O90') THEN L."Amount" ELSE 0 END) AS "CIss",
                 SUM(CASE WHEN L."TransCode" IN ('O08', 'O09') THEN L."Amount" ELSE 0 END) AS "CWw",
                 SUM(CASE WHEN L."TransCode" IN ('O01', 'O06') THEN L."Amount" ELSE 0 END) AS "CSal",
                 SUM(CASE WHEN L."TransCode" IN ('I05', 'O05') THEN L."Amount" ELSE 0 END) AS "CTrf",
                 SUM(CASE WHEN L."TransCode" IN ('I02', 'O02') THEN L."Amount" ELSE 0 END) AS "CMov",
                 SUM(CASE WHEN L."TransCode" IN ('I04', 'O04') THEN L."Amount" ELSE 0 END) AS "COth",
                 SUM(CASE WHEN L."TransCode" IN ('I10', 'O10') THEN L."Amount" ELSE 0 END) AS "CCnt",
                 SUM(CASE WHEN L."TransCode" IS NULL OR L."TransCode" NOT IN ('I01', 'I06', 'I03', 'I07', 'I08', 'I09', 'I90', 'O03', 'O07', 'O90', 'O08', 'O09',
                                                                            'O01', 'O06', 'I05', 'O05', 'I02', 'O02', 'I04', 'O04', 'I10', 'O10')
                          THEN L."Amount" ELSE 0 END) AS "CRev"
            FROM :runs U JOIN "MTC_CA_R_LINE" L ON L."RunId" = U."RunId"
           GROUP BY L."ItemCode";
    base = SELECT I.*, M."ItemName", TO_NVARCHAR(M."ItmsGrpCod") AS "Grp", G."ItmsGrpNam" AS "GrpName",
                  A."StockAct" AS "Acct", AC."AcctName",
                  IFNULL(C."CPur", 0) AS "CPur", IFNULL(C."CPrd", 0) AS "CPrd", IFNULL(C."CIss", 0) AS "CIss", IFNULL(C."CWw", 0) AS "CWw",
                  IFNULL(C."CSal", 0) AS "CSal", IFNULL(C."CTrf", 0) AS "CTrf", IFNULL(C."CMov", 0) AS "CMov", IFNULL(C."COth", 0) AS "COth",
                  IFNULL(C."CCnt", 0) AS "CCnt", IFNULL(C."CRev", 0) AS "CRev"
             FROM :it I
             LEFT JOIN :cat C ON C."ItemCode" = I."ItemCode"
             LEFT JOIN "OITM" M ON M."ItemCode" = I."ItemCode"
             LEFT JOIN "OITB" G ON G."ItmsGrpCod" = M."ItmsGrpCod"
             LEFT JOIN (SELECT "ItmsGrpCod", MAX("StockAct") AS "StockAct" FROM "OGAR" WHERE "PeriodCat" = LEFT(:fB, 4) GROUP BY "ItmsGrpCod") A
                    ON A."ItmsGrpCod" = M."ItmsGrpCod"
             LEFT JOIN "OACT" AC ON AC."AcctCode" = A."StockAct"
            WHERE (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE I."ItemCode" LIKE X."P"))
              AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
              AND (:nLvl = 0 OR EXISTS (SELECT 1 FROM :lLvl X WHERE TO_NVARCHAR(I."Lv") = X."V"))
              AND (IFNULL(:NonZero, 'N') <> 'Y' OR I."BQ" <> 0 OR I."IQ" <> 0 OR I."OQ" <> 0 OR I."EQ" <> 0
                   OR I."BMat" + I."BLab" + I."BMfg" + I."BSub" <> 0 OR I."IMat" + I."ILab" + I."IMfg" + I."ISub" <> 0
                   OR I."OMat" + I."OLab" + I."OMfg" + I."OSub" <> 0 OR I."EMat" + I."ELab" + I."EMfg" + I."ESub" <> 0);
    base2 = SELECT B.*, CASE :st WHEN '1' THEN B."Grp" WHEN '2' THEN B."Acct" ELSE B."ItemCode" END AS "KCode",
                  CASE :st WHEN '1' THEN LPAD(IFNULL(B."Grp", ''), 10, '0') WHEN '2' THEN IFNULL(B."Acct", '')
                       ELSE LPAD(IFNULL(B."Grp", ''), 10, '0') || B."ItemCode" END AS "SK"
             FROM :base B;
    o = SELECT CASE WHEN :st = '2' THEN NULL ELSE MAX("Grp") END AS "物料组",
               MAX("Acct") AS "存货科目",
               "KCode" AS "代码",
               CASE :st WHEN '1' THEN MAX("GrpName") WHEN '2' THEN MAX("AcctName") ELSE MAX("ItemName") END AS "名称",
               CASE WHEN :st = '0' THEN MAX("Lv") END AS "层级",
               CAST(SUM("BQ") AS DECIMAL(19,6)) AS "期初·数量",
               CAST(SUM("BMat" + "BLab" + "BMfg" + "BSub") / NULLIF(CASE WHEN :st = '0' THEN SUM("BQ") END, 0) AS DECIMAL(19,6)) AS "期初·单价",
               CAST(SUM("BMat" + "BLab" + "BMfg" + "BSub") AS DECIMAL(19,2)) AS "期初·金额",
               CAST(SUM("BMat") AS DECIMAL(19,2)) AS "期初·材料", CAST(SUM("BLab") AS DECIMAL(19,2)) AS "期初·人工",
               CAST(SUM("BMfg") AS DECIMAL(19,2)) AS "期初·制造", CAST(SUM("BSub") AS DECIMAL(19,2)) AS "期初·委外",
               CAST(SUM("IQ") AS DECIMAL(19,6)) AS "入库·数量",
               CAST(SUM("IMat" + "ILab" + "IMfg" + "ISub") / NULLIF(CASE WHEN :st = '0' THEN SUM("IQ") END, 0) AS DECIMAL(19,6)) AS "入库·单价",
               CAST(SUM("IMat" + "ILab" + "IMfg" + "ISub") AS DECIMAL(19,2)) AS "入库·金额",
               CAST(SUM("IMat") AS DECIMAL(19,2)) AS "入库·材料", CAST(SUM("ILab") AS DECIMAL(19,2)) AS "入库·人工",
               CAST(SUM("IMfg") AS DECIMAL(19,2)) AS "入库·制造", CAST(SUM("ISub") AS DECIMAL(19,2)) AS "入库·委外",
               CAST(SUM("OQ") AS DECIMAL(19,6)) AS "出库·数量",
               CAST(SUM("OMat" + "OLab" + "OMfg" + "OSub") / NULLIF(CASE WHEN :st = '0' THEN SUM("OQ") END, 0) AS DECIMAL(19,6)) AS "出库·单价",
               CAST(SUM("OMat" + "OLab" + "OMfg" + "OSub") AS DECIMAL(19,2)) AS "出库·金额",
               CAST(SUM("OMat") AS DECIMAL(19,2)) AS "出库·材料", CAST(SUM("OLab") AS DECIMAL(19,2)) AS "出库·人工",
               CAST(SUM("OMfg") AS DECIMAL(19,2)) AS "出库·制造", CAST(SUM("OSub") AS DECIMAL(19,2)) AS "出库·委外",
               CAST(SUM("EQ") AS DECIMAL(19,6)) AS "期末·数量",
               CAST(SUM("EMat" + "ELab" + "EMfg" + "ESub") / NULLIF(CASE WHEN :st = '0' THEN SUM("EQ") END, 0) AS DECIMAL(19,6)) AS "期末·单价",
               CAST(SUM("EMat" + "ELab" + "EMfg" + "ESub") AS DECIMAL(19,2)) AS "期末·金额",
               CAST(SUM("EMat") AS DECIMAL(19,2)) AS "期末·材料", CAST(SUM("ELab") AS DECIMAL(19,2)) AS "期末·人工",
               CAST(SUM("EMfg") AS DECIMAL(19,2)) AS "期末·制造", CAST(SUM("ESub") AS DECIMAL(19,2)) AS "期末·委外",
               CAST(SUM("CPur") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·采购", CAST(SUM("CPrd") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·生产入库",
               CAST(SUM("CIss") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·生产领用", CAST(SUM("CWw") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·委外发出",
               CAST(SUM("CSal") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·销售及退货", CAST(SUM("CTrf") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·形态转换",
               CAST(SUM("CMov") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·转储", CAST(SUM("COth") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·其他出入库",
               CAST(SUM("CCnt") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·盘点", CAST(SUM("CRev") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·重估及差异",
               CAST(SUM("CTail") AS DECIMAL(19,2)) AS "本期收发（增 + 减 −）·尾差结转",
               "SK"
          FROM :base2
         GROUP BY "KCode", "SK";
    IF IFNULL(:ShowElem, 'N') = 'Y' AND IFNULL(:ByCat, 'N') = 'Y' THEN
        SELECT "物料组", "存货科目", "代码", "名称", "层级",
               "期初·数量", "期初·单价", "期初·金额", "期初·材料", "期初·人工", "期初·制造", "期初·委外",
               "入库·数量", "入库·单价", "入库·金额", "入库·材料", "入库·人工", "入库·制造", "入库·委外",
               "出库·数量", "出库·单价", "出库·金额", "出库·材料", "出库·人工", "出库·制造", "出库·委外",
               "期末·数量", "期末·单价", "期末·金额", "期末·材料", "期末·人工", "期末·制造", "期末·委外",
               "本期收发（增 + 减 −）·采购", "本期收发（增 + 减 −）·生产入库", "本期收发（增 + 减 −）·生产领用", "本期收发（增 + 减 −）·委外发出",
               "本期收发（增 + 减 −）·销售及退货", "本期收发（增 + 减 −）·形态转换", "本期收发（增 + 减 −）·转储", "本期收发（增 + 减 −）·其他出入库",
               "本期收发（增 + 减 −）·盘点", "本期收发（增 + 减 −）·重估及差异", "本期收发（增 + 减 −）·尾差结转"
          FROM :o ORDER BY "SK";
    ELSEIF IFNULL(:ShowElem, 'N') = 'Y' THEN
        SELECT "物料组", "存货科目", "代码", "名称", "层级",
               "期初·数量", "期初·单价", "期初·金额", "期初·材料", "期初·人工", "期初·制造", "期初·委外",
               "入库·数量", "入库·单价", "入库·金额", "入库·材料", "入库·人工", "入库·制造", "入库·委外",
               "出库·数量", "出库·单价", "出库·金额", "出库·材料", "出库·人工", "出库·制造", "出库·委外",
               "期末·数量", "期末·单价", "期末·金额", "期末·材料", "期末·人工", "期末·制造", "期末·委外"
          FROM :o ORDER BY "SK";
    ELSEIF IFNULL(:ByCat, 'N') = 'Y' THEN
        SELECT "物料组", "存货科目", "代码", "名称", "层级", "期初·数量", "期初·金额",
               "本期收发（增 + 减 −）·采购", "本期收发（增 + 减 −）·生产入库", "本期收发（增 + 减 −）·生产领用", "本期收发（增 + 减 −）·委外发出",
               "本期收发（增 + 减 −）·销售及退货", "本期收发（增 + 减 −）·形态转换", "本期收发（增 + 减 −）·转储", "本期收发（增 + 减 −）·其他出入库",
               "本期收发（增 + 减 −）·盘点", "本期收发（增 + 减 −）·重估及差异", "本期收发（增 + 减 −）·尾差结转",
               "期末·数量", "期末·金额"
          FROM :o ORDER BY "SK";
    ELSE
        SELECT "物料组", "存货科目", "代码", "名称", "层级",
               "期初·数量", "期初·单价", "期初·金额", "入库·数量", "入库·单价", "入库·金额",
               "出库·数量", "出库·单价", "出库·金额", "期末·数量", "期末·单价", "期末·金额"
          FROM :o ORDER BY "SK";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #11
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R04 存货明细账：逐条库存变动，带结存数量和金额。
-- 参数：FcFrom, FcTo, Item 物料, ItemGrp 物料组, Trans 交易类型（I01、O03…）, Dir 方向（I 入 / O 出）, OrderNum 订单号 Num, Whs 仓库
-- 口径：MTC_CA_R_LINE + MTC_CA_S_LINE（单据信息）；结存 = 第一期期初 + 按 账期、日期、行号 累计（先按物料全部行算好再按条件筛选，
--       所以只看某类交易时结存仍是该物料的真实结存）；尾差结转（JZ04）放在每期期末日。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_04_LEDGER" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Trans NVARCHAR(500),
    IN Dir NVARCHAR(1), IN OrderNum NVARCHAR(5000), IN Whs NVARCHAR(500))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE fA NVARCHAR(10); DECLARE nItem INT; DECLARE nGrp INT; DECLARE nTr INT; DECLARE nOrd INT; DECLARE nWhs INT;
    runs = SELECT "FcCode", "RunId", "D1" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("FcCode") INTO fA FROM :runs;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lTr   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Trans);    SELECT COUNT(*) INTO nTr FROM :lTr;
    lOrd  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:OrderNum); SELECT COUNT(*) INTO nOrd FROM :lOrd;
    lWhs  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Whs);      SELECT COUNT(*) INTO nWhs FROM :lWhs;

    items = SELECT DISTINCT R."ItemCode"
              FROM :runs U JOIN "MTC_CA_R_ITEM" R ON R."RunId" = U."RunId"
              LEFT JOIN "OITM" M ON M."ItemCode" = R."ItemCode"
             WHERE (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE R."ItemCode" LIKE X."P"))
               AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"));
    beg = SELECT R."ItemCode", R."OpenQty" AS "Q", R."OpenMat" + R."OpenMfg" + R."OpenLab" + R."OpenSub" AS "A"
            FROM :runs U JOIN "MTC_CA_R_ITEM" R ON R."RunId" = U."RunId" JOIN :items I ON I."ItemCode" = R."ItemCode"
           WHERE U."FcCode" = :fA;
    mv = SELECT U."FcCode", L."ItemCode", D."DocDate", L."LineId", D."ObjType", D."DocNum", D."LineNum", L."TransCode", D."BusiType", D."WhsCode",
                L."OrderType", L."OrderEntry", SO."OrderNum", SO."WorType", L."Qty", L."Amount", L."MatAmt", L."LabAmt", L."MfgAmt", L."SubAmt", L."PriceSrc",
                CASE WHEN L."Qty" > 0 THEN 'I' WHEN L."Qty" < 0 THEN 'O'
                     WHEN LEFT(IFNULL(L."TransCode", 'I'), 1) = 'O' AND L."TransCode" <> 'O06' THEN 'O' ELSE 'I' END AS "Dir"
           FROM :runs U
           JOIN "MTC_CA_R_LINE" L ON L."RunId" = U."RunId"
           JOIN :items I ON I."ItemCode" = L."ItemCode"
           JOIN "MTC_CA_S_LINE" D ON D."RunId" = L."RunId" AND D."LineId" = L."LineId"
           LEFT JOIN "MTC_CA_S_ORDER" SO ON SO."RunId" = L."RunId" AND SO."OrderType" = L."OrderType" AND SO."OrderEntry" = L."OrderEntry"
          WHERE NOT (D."ObjType" IN ('13', '14') AND L."Qty" = 0 AND L."Amount" = 0)
         UNION ALL
         SELECT U."FcCode", R."ItemCode", U."D1", 999999999999, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
                0, R."TailAmt", 0, 0, 0, 0, '零库存尾差结转（JZ04，TAIL-01）', 'O'
           FROM :runs U JOIN "MTC_CA_R_ITEM" R ON R."RunId" = U."RunId" JOIN :items I ON I."ItemCode" = R."ItemCode"
          WHERE R."TailAmt" <> 0;
    bal = SELECT M.*,
                 IFNULL(B."Q", 0) + SUM(M."Qty") OVER (PARTITION BY M."ItemCode" ORDER BY M."FcCode", M."DocDate", M."LineId" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "BalQ",
                 IFNULL(B."A", 0) + SUM(M."Amount") OVER (PARTITION BY M."ItemCode" ORDER BY M."FcCode", M."DocDate", M."LineId" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "BalA"
            FROM :mv M LEFT JOIN :beg B ON B."ItemCode" = M."ItemCode";
    SELECT X."账期", X."物料", M."ItemName" AS "名称", X."日期", "MTC_CA_F_RPT_DTNAME"(X."单据类型") AS "单据类型", X."单号 Num", X."行号", X."交易类型", T."Name" AS "交易类型名称",
           X."业务类型", X."仓库", X."订单号 Num", "MTC_CA_F_RPT_WTNAME"(X."订单类型") AS "订单类型",
           X."入库·数量", CAST(X."入库·金额" / NULLIF(X."入库·数量", 0) AS DECIMAL(19,6)) AS "入库·单价", X."入库·金额",
           X."出库·数量", CAST(X."出库·金额" / NULLIF(X."出库·数量", 0) AS DECIMAL(19,6)) AS "出库·单价", X."出库·金额",
           X."结存·数量", CAST(X."结存·金额" / NULLIF(X."结存·数量", 0) AS DECIMAL(19,6)) AS "结存·单价", X."结存·金额",
           X."本行·材料", X."本行·人工", X."本行·制造", X."本行·委外", X."定价来源"
      FROM (
        SELECT :fA AS "账期", B."ItemCode" AS "物料", CAST(NULL AS DATE) AS "日期", CAST(NULL AS NVARCHAR(20)) AS "单据类型", CAST('期初结存' AS NVARCHAR(50)) AS "单号 Num",
               CAST(NULL AS INTEGER) AS "行号", CAST(NULL AS NVARCHAR(10)) AS "交易类型", CAST(NULL AS NVARCHAR(20)) AS "业务类型", CAST(NULL AS NVARCHAR(8)) AS "仓库",
               CAST(NULL AS NVARCHAR(50)) AS "订单号 Num", CAST(NULL AS NVARCHAR(10)) AS "订单类型",
               CAST(NULL AS DECIMAL(19,6)) AS "入库·数量", CAST(NULL AS DECIMAL(19,2)) AS "入库·金额", CAST(NULL AS DECIMAL(19,6)) AS "出库·数量", CAST(NULL AS DECIMAL(19,2)) AS "出库·金额",
               CAST(B."Q" AS DECIMAL(19,6)) AS "结存·数量", CAST(B."A" AS DECIMAL(19,2)) AS "结存·金额",
               CAST(NULL AS DECIMAL(19,2)) AS "本行·材料", CAST(NULL AS DECIMAL(19,2)) AS "本行·人工", CAST(NULL AS DECIMAL(19,2)) AS "本行·制造", CAST(NULL AS DECIMAL(19,2)) AS "本行·委外",
               CAST(NULL AS NVARCHAR(200)) AS "定价来源", '0000-00' AS "SF", CAST(NULL AS DATE) AS "SD", CAST(-1 AS BIGINT) AS "SL"
          FROM :beg B
         WHERE :nTr = 0 AND IFNULL(:Dir, '') = '' AND :nOrd = 0 AND :nWhs = 0
           AND EXISTS (SELECT 1 FROM :mv M WHERE M."ItemCode" = B."ItemCode")
        UNION ALL
        SELECT B."FcCode", B."ItemCode", B."DocDate", B."ObjType", B."DocNum", B."LineNum", B."TransCode", B."BusiType", B."WhsCode",
               B."OrderNum", B."WorType",
               CASE WHEN B."Dir" = 'I' THEN CAST(B."Qty" AS DECIMAL(19,6)) END, CASE WHEN B."Dir" = 'I' THEN CAST(B."Amount" AS DECIMAL(19,2)) END,
               CASE WHEN B."Dir" = 'O' THEN CAST(-B."Qty" AS DECIMAL(19,6)) END, CASE WHEN B."Dir" = 'O' THEN CAST(-B."Amount" AS DECIMAL(19,2)) END,
               CAST(B."BalQ" AS DECIMAL(19,6)), CAST(B."BalA" AS DECIMAL(19,2)),
               CAST(B."MatAmt" AS DECIMAL(19,2)), CAST(B."LabAmt" AS DECIMAL(19,2)), CAST(B."MfgAmt" AS DECIMAL(19,2)), CAST(B."SubAmt" AS DECIMAL(19,2)),
               B."PriceSrc", B."FcCode", B."DocDate", B."LineId"
          FROM :bal B
         WHERE (:nTr = 0 OR EXISTS (SELECT 1 FROM :lTr X WHERE B."TransCode" = X."V"))
           AND (IFNULL(:Dir, '') = '' OR B."Dir" = :Dir)
           AND (:nOrd = 0 OR EXISTS (SELECT 1 FROM :lOrd X WHERE B."OrderNum" LIKE X."P"))
           AND (:nWhs = 0 OR EXISTS (SELECT 1 FROM :lWhs X WHERE B."WhsCode" = X."V"))
      ) X
      LEFT JOIN "OITM" M ON M."ItemCode" = X."物料"
      LEFT JOIN "@MTC_COST_IOTYPE" T ON T."Code" = X."交易类型"
     ORDER BY X."物料", X."SF", X."SD", X."SL";
END

@@
-- @stmt 成本报表 21_reports.sql #12
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R01 产品成本计算单：每张订单期初在产品 + 本期投入 + 本级分摊 = 完工转出 + 关单差异 + 期末在产品（四项）。
-- 参数：FcFrom, FcTo, WorType 订单类型（10/20/30/40/50）, OrderNum 订单号 Num, Item 产品, ItemGrp 产品物料组,
--       Scope 订单范围（空 全部 / 1 本期有完工 / 2 本期按关单处理 / 3 期末有在产品）, STYPE 0 按订单 / 1 订单 × 材料
-- 口径：MTC_CA_R_ORDER（完工成本、分摊、在产品、关单差异）+ MTC_CA_R_ORDER_MAT（期初累计、本期领料、结转、在产品、关单差异）；
--       材料 '#SUBFEE' 行 = 委外加工费。多个账期时每个账期一行。“勾稽差额”应为 0。
-- 勾稽：完工转出合计 = R02 总成本 = R03 生产入库；期末在产品 = R09 生产成本 / 委外加工物资业务端；本级分摊 = R06 已分配（V02–V05）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_01_ORDCALC" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN WorType NVARCHAR(100), IN OrderNum NVARCHAR(5000), IN Item NVARCHAR(5000),
    IN ItemGrp NVARCHAR(5000), IN Scope NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nWt INT; DECLARE nOrd INT; DECLARE nItem INT; DECLARE nGrp INT;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType);  SELECT COUNT(*) INTO nWt FROM :lWt;
    lOrd  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:OrderNum); SELECT COUNT(*) INTO nOrd FROM :lOrd;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    ord = SELECT O.*, S."OrderNum", S."StatusAtEnd", S."CardCode", M."ItemName", TO_NVARCHAR(M."ItmsGrpCod") AS "Grp"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
            LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
           WHERE (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"))
             AND (:nOrd = 0 OR EXISTS (SELECT 1 FROM :lOrd X WHERE S."OrderNum" LIKE X."P"))
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
             AND (IFNULL(:Scope, '') = '' OR (:Scope = '1' AND O."RecvQty" <> 0) OR (:Scope = '2' AND O."ClosedInFc" = 'Y') OR (:Scope = '3' AND O."WipAmt" <> 0));
    IF :STYPE = '1' THEN
        SELECT O."FcCode" AS "账期", "MTC_CA_F_RPT_OTNAME"(O."OrderType") AS "订单单据", O."OrderNum" AS "订单号 Num", O."OrderEntry" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"(O."WorType") AS "订单类型",
               O."ItemCode" AS "产品", O."ItemName" AS "产品名称",
               M."ItemCode" AS "材料",
               CASE WHEN M."ItemCode" = '#SUBFEE' THEN '委外加工费' ELSE I."ItemName" END AS "材料名称",
               CAST(M."OpenIssQty" AS DECIMAL(19,6)) AS "期初·累计领料数量",
               CAST(M."OpenIssMat" + M."OpenIssLab" + M."OpenIssMfg" + M."OpenIssSub" - M."OpenCarMat" - M."OpenCarLab" - M."OpenCarMfg" - M."OpenCarSub" AS DECIMAL(19,2)) AS "期初·在产品",
               CAST(M."IssQty" AS DECIMAL(19,6)) AS "本期领料·数量",
               CAST(M."IssMat" + M."IssLab" + M."IssMfg" + M."IssSub" AS DECIMAL(19,2)) AS "本期领料·金额",
               CAST(M."Ratio" AS DECIMAL(19,6)) AS "结转比例",
               CAST(M."CarMat" AS DECIMAL(19,2)) AS "完工转出·材料", CAST(M."CarLab" AS DECIMAL(19,2)) AS "完工转出·人工",
               CAST(M."CarMfg" AS DECIMAL(19,2)) AS "完工转出·制造", CAST(M."CarSub" AS DECIMAL(19,2)) AS "完工转出·委外",
               CAST(M."CarMat" + M."CarLab" + M."CarMfg" + M."CarSub" AS DECIMAL(19,2)) AS "完工转出·合计",
               CAST(M."ClsMat" + M."ClsLab" + M."ClsMfg" + M."ClsSub" AS DECIMAL(19,2)) AS "关单差异",
               CAST(M."WipMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(M."WipLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(M."WipMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(M."WipSub" AS DECIMAL(19,2)) AS "期末在产品·委外",
               CAST(M."WipMat" + M."WipLab" + M."WipMfg" + M."WipSub" AS DECIMAL(19,2)) AS "期末在产品·合计"
          FROM :ord O
          JOIN "MTC_CA_R_ORDER_MAT" M ON M."RunId" = O."RunId" AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
          LEFT JOIN "OITM" I ON I."ItemCode" = M."ItemCode"
         ORDER BY O."FcCode", O."iLevel", O."OrderType", O."OrderEntry", CASE WHEN M."ItemCode" = '#SUBFEE' THEN 1 ELSE 0 END, M."ItemCode";
    ELSE
        mat = SELECT "RunId", "OrderType", "OrderEntry",
                     SUM("OpenIssMat" - "OpenCarMat") AS "BMat", SUM("OpenIssLab" - "OpenCarLab") AS "BLab",
                     SUM("OpenIssMfg" - "OpenCarMfg") AS "BMfg", SUM("OpenIssSub" - "OpenCarSub") AS "BSub",
                     SUM("IssMat") AS "IMat", SUM("IssLab") AS "ILab", SUM("IssMfg") AS "IMfg", SUM("IssSub") AS "ISub",
                     SUM("ClsMat" + "ClsLab" + "ClsMfg" + "ClsSub") AS "Cls",
                     SUM("WipMat") AS "WMat", SUM("WipLab") AS "WLab", SUM("WipMfg") AS "WMfg", SUM("WipSub") AS "WSub"
                FROM "MTC_CA_R_ORDER_MAT" WHERE "RunId" IN (SELECT "RunId" FROM :runs)
               GROUP BY "RunId", "OrderType", "OrderEntry";
        SELECT O."FcCode" AS "账期", "MTC_CA_F_RPT_OTNAME"(O."OrderType") AS "订单单据", O."OrderNum" AS "订单号 Num", O."OrderEntry" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"(O."WorType") AS "订单类型",
               O."ItemCode" AS "产品", O."ItemName" AS "产品名称", O."Grp" AS "物料组", O."iLevel" AS "层级", O."CardCode" AS "委外供应商",
               O."StatusAtEnd" AS "期末状态", O."ClosedInFc" AS "按关单处理",
               CAST(O."PlannedQty" AS DECIMAL(19,6)) AS "计划数", CAST(O."PrevRecvQty" AS DECIMAL(19,6)) AS "上期累计完工", CAST(O."RecvQty" AS DECIMAL(19,6)) AS "本期完工",
               CAST(IFNULL(M."BMat", 0) AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(IFNULL(M."BLab", 0) AS DECIMAL(19,2)) AS "期初在产品·人工",
               CAST(IFNULL(M."BMfg", 0) AS DECIMAL(19,2)) AS "期初在产品·制造", CAST(IFNULL(M."BSub", 0) AS DECIMAL(19,2)) AS "期初在产品·委外",
               CAST(IFNULL(M."BMat" + M."BLab" + M."BMfg" + M."BSub", 0) AS DECIMAL(19,2)) AS "期初在产品·合计",
               CAST(IFNULL(M."IMat", 0) AS DECIMAL(19,2)) AS "本期投入·材料", CAST(IFNULL(M."ILab", 0) AS DECIMAL(19,2)) AS "本期投入·人工",
               CAST(IFNULL(M."IMfg", 0) AS DECIMAL(19,2)) AS "本期投入·制造", CAST(IFNULL(M."ISub", 0) AS DECIMAL(19,2)) AS "本期投入·委外",
               CAST(IFNULL(M."IMat" + M."ILab" + M."IMfg" + M."ISub", 0) AS DECIMAL(19,2)) AS "本期投入·合计",
               CAST(O."AllocLab" AS DECIMAL(19,2)) AS "本级分摊·人工", CAST(O."AllocMfg" AS DECIMAL(19,2)) AS "本级分摊·制造",
               CAST(O."CostMat" AS DECIMAL(19,2)) AS "完工转出·材料", CAST(O."CostLab" AS DECIMAL(19,2)) AS "完工转出·人工",
               CAST(O."CostMfg" AS DECIMAL(19,2)) AS "完工转出·制造", CAST(O."CostSub" AS DECIMAL(19,2)) AS "完工转出·委外",
               CAST(O."CostAmt" AS DECIMAL(19,2)) AS "完工转出·合计", CAST(O."UnitCost" AS DECIMAL(19,6)) AS "完工转出·单位成本",
               CAST(O."CloseDifAmt" AS DECIMAL(19,2)) AS "关单差异",
               CAST(IFNULL(M."WMat", 0) AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(IFNULL(M."WLab", 0) AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(IFNULL(M."WMfg", 0) AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(IFNULL(M."WSub", 0) AS DECIMAL(19,2)) AS "期末在产品·委外",
               CAST(O."WipAmt" AS DECIMAL(19,2)) AS "期末在产品·合计",
               CAST(IFNULL(M."BMat" + M."BLab" + M."BMfg" + M."BSub", 0) + IFNULL(M."IMat" + M."ILab" + M."IMfg" + M."ISub", 0) + O."AllocLab" + O."AllocMfg"
                    - O."CostAmt" - O."CloseDifAmt" - O."WipAmt" AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :ord O
          LEFT JOIN :mat M ON M."RunId" = O."RunId" AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
         ORDER BY O."FcCode", O."iLevel", O."OrderType", O."OrderEntry";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #13
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R02 完工产品成本汇总：每个产品本期完工数量、四项成本、单位成本和构成。
-- 参数：FcFrom, FcTo, Item 产品, ItemGrp 物料组, Lvl 层级, WorType 订单类型, STYPE 0 按产品 / 1 产品 × 订单
-- 口径：MTC_CA_R_ORDER 本期完工成本（Cost*，含本级分摊），只列本期有完工或有完工成本的订单；多个账期时按产品显示也按账期分行（第一列账期，用户 2026-11-11）。
--       成本是还原后的：完工成本·制造 = 本级分摊·制造（本期费用池分到这张订单，随完工全部转出）+ 领料带入·制造（结转的材料和半成品里含的制造，含期初在产品），
--       人工同理。多层产品同一笔费用在半成品和成品上各算一次，所以完工成本·制造的合计大于当期分摊（用户 2026-11-06）。
--       完工成本·委外 = 本级分摊·委外（这张订单自己的加工费 '#SUBFEE' 本期结转，直接计入订单，不走费用池）+ 领料带入·委外（半成品里含的加工费）；
--       加工费结转按有入库时全部转出，可能含以前账期留在订单上的，所以不一定等于本期发生的加工费，委外工单上的合计 = R07 完工转出·加工费。
--       本级分摊·材料 = 完工成本·合计 − 本级分摊·制造 − 人工 − 委外，即领用的材料和半成品全额（半成品里含的料工费都算材料），同 R22 本级口径；
--       本级分摊四项合计 = 完工成本·合计（用户 2026-11-11）。
--       入库单价 = 完工入库行（R_LINE Cat = RCPT）的金额合计 ÷ 数量合计，用来核对单位成本·合计：入库行按订单成本 × 行数量 ÷ 本期入库数分摊、
--       尾差挤数量最大的行，正常两者只差分位；差得多说明入库行和订单成本没对上（用户 2026-11-11）。
-- 勾稽：总成本 = R01 完工转出合计 = R03 生产入库（V01）；不加条件时本级分摊·制造 / 人工合计 = R06 已分配（V04）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_02_PRODCOST" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Lvl NVARCHAR(100),
    IN WorType NVARCHAR(100), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nLvl INT; DECLARE nWt INT;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lLvl  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Lvl);     SELECT COUNT(*) INTO nLvl FROM :lLvl;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType); SELECT COUNT(*) INTO nWt FROM :lWt;
    ord = SELECT U."FcCode", O."RunId", O."OrderType", O."OrderEntry", S."OrderNum", O."WorType", O."ItemCode", M."ItemName",
                 TO_NVARCHAR(M."ItmsGrpCod") AS "Grp", G."ItmsGrpNam" AS "GrpName", O."iLevel",
                 O."RecvQty", O."CostMat", O."CostLab", O."CostMfg", O."CostSub", O."CostAmt", O."AllocLab", O."AllocMfg",
                 IFNULL(F."CarSub", 0) AS "OwnSub", IFNULL(RC."Qty", 0) AS "RcptQty", IFNULL(RC."Amt", 0) AS "RcptAmt"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
            LEFT JOIN "MTC_CA_R_ORDER_MAT" F ON F."RunId" = O."RunId" AND F."OrderType" = O."OrderType" AND F."OrderEntry" = O."OrderEntry" AND F."ItemCode" = '#SUBFEE'
            LEFT JOIN (SELECT L."RunId", L."OrderType", L."OrderEntry", SUM(L."Qty") AS "Qty", SUM(L."Amount") AS "Amt"
                         FROM "MTC_CA_R_LINE" L
                        WHERE L."Cat" = 'RCPT' AND L."RunId" IN (SELECT "RunId" FROM :runs)
                        GROUP BY L."RunId", L."OrderType", L."OrderEntry") RC
                   ON RC."RunId" = O."RunId" AND RC."OrderType" = O."OrderType" AND RC."OrderEntry" = O."OrderEntry"
            LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
            LEFT JOIN "OITB" G ON G."ItmsGrpCod" = M."ItmsGrpCod"
           WHERE (O."RecvQty" <> 0 OR O."CostAmt" <> 0)
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
             AND (:nLvl = 0 OR EXISTS (SELECT 1 FROM :lLvl X WHERE TO_NVARCHAR(O."iLevel") = X."V"))
             AND (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"));
    IF :STYPE = '1' THEN
        SELECT "ItemCode" AS "产品", "ItemName" AS "名称", "FcCode" AS "账期",
               "MTC_CA_F_RPT_OTNAME"("OrderType") AS "订单单据", "OrderNum" AS "订单号 Num",
               "OrderEntry" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"("WorType") AS "订单类型",
               CAST("RecvQty" AS DECIMAL(19,6)) AS "完工数量",
               CAST("CostMat" AS DECIMAL(19,2)) AS "完工成本·材料", CAST("CostLab" AS DECIMAL(19,2)) AS "完工成本·人工",
               CAST("CostMfg" AS DECIMAL(19,2)) AS "完工成本·制造", CAST("CostSub" AS DECIMAL(19,2)) AS "完工成本·委外",
               CAST("CostAmt" AS DECIMAL(19,2)) AS "完工成本·合计",
               CAST("CostAmt" - "AllocMfg" - "AllocLab" - "OwnSub" AS DECIMAL(19,2)) AS "本级分摊·材料",
               CAST("AllocMfg" AS DECIMAL(19,2)) AS "本级分摊·制造", CAST("AllocLab" AS DECIMAL(19,2)) AS "本级分摊·人工", CAST("OwnSub" AS DECIMAL(19,2)) AS "本级分摊·委外",
               CAST("CostMfg" - "AllocMfg" AS DECIMAL(19,2)) AS "领料带入·制造", CAST("CostLab" - "AllocLab" AS DECIMAL(19,2)) AS "领料带入·人工", CAST("CostSub" - "OwnSub" AS DECIMAL(19,2)) AS "领料带入·委外",
               CAST("CostAmt" / NULLIF("RecvQty", 0) AS DECIMAL(19,6)) AS "单位成本·合计",
               CAST("RcptAmt" / NULLIF("RcptQty", 0) AS DECIMAL(19,6)) AS "入库单价",
               CAST("CostMat" / NULLIF("RecvQty", 0) AS DECIMAL(19,6)) AS "单位成本·材料", CAST("CostLab" / NULLIF("RecvQty", 0) AS DECIMAL(19,6)) AS "单位成本·人工",
               CAST("CostMfg" / NULLIF("RecvQty", 0) AS DECIMAL(19,6)) AS "单位成本·制造", CAST("CostSub" / NULLIF("RecvQty", 0) AS DECIMAL(19,6)) AS "单位成本·委外"
          FROM :ord ORDER BY "ItemCode", "FcCode", "OrderType", "OrderEntry";
    ELSE
        SELECT "FcCode" AS "账期", "Grp" AS "物料组", MAX("GrpName") AS "物料组名称", "ItemCode" AS "产品", MAX("ItemName") AS "名称", MAX("iLevel") AS "层级",
               COUNT(*) AS "订单数", CAST(SUM("RecvQty") AS DECIMAL(19,6)) AS "完工数量",
               CAST(SUM("CostMat") AS DECIMAL(19,2)) AS "完工成本·材料", CAST(SUM("CostLab") AS DECIMAL(19,2)) AS "完工成本·人工",
               CAST(SUM("CostMfg") AS DECIMAL(19,2)) AS "完工成本·制造", CAST(SUM("CostSub") AS DECIMAL(19,2)) AS "完工成本·委外",
               CAST(SUM("CostAmt") AS DECIMAL(19,2)) AS "完工成本·合计",
               CAST(SUM("CostAmt" - "AllocMfg" - "AllocLab" - "OwnSub") AS DECIMAL(19,2)) AS "本级分摊·材料",
               CAST(SUM("AllocMfg") AS DECIMAL(19,2)) AS "本级分摊·制造", CAST(SUM("AllocLab") AS DECIMAL(19,2)) AS "本级分摊·人工", CAST(SUM("OwnSub") AS DECIMAL(19,2)) AS "本级分摊·委外",
               CAST(SUM("CostMfg" - "AllocMfg") AS DECIMAL(19,2)) AS "领料带入·制造", CAST(SUM("CostLab" - "AllocLab") AS DECIMAL(19,2)) AS "领料带入·人工", CAST(SUM("CostSub" - "OwnSub") AS DECIMAL(19,2)) AS "领料带入·委外",
               CAST(SUM("CostAmt") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·合计",
               CAST(SUM("RcptAmt") / NULLIF(SUM("RcptQty"), 0) AS DECIMAL(19,6)) AS "入库单价",
               CAST(SUM("CostMat") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·材料", CAST(SUM("CostLab") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·人工",
               CAST(SUM("CostMfg") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·制造", CAST(SUM("CostSub") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·委外",
               CAST(SUM("CostMat") * 100 / NULLIF(SUM("CostAmt"), 0) AS DECIMAL(19,2)) AS "构成 %·材料", CAST(SUM("CostLab") * 100 / NULLIF(SUM("CostAmt"), 0) AS DECIMAL(19,2)) AS "构成 %·人工",
               CAST(SUM("CostMfg") * 100 / NULLIF(SUM("CostAmt"), 0) AS DECIMAL(19,2)) AS "构成 %·制造", CAST(SUM("CostSub") * 100 / NULLIF(SUM("CostAmt"), 0) AS DECIMAL(19,2)) AS "构成 %·委外"
          FROM :ord
         GROUP BY "FcCode", "Grp", "ItemCode"
         ORDER BY "FcCode", LPAD(IFNULL("Grp", ''), 10, '0'), "ItemCode";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #14
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R05 材料耗用汇总：材料本期领用到哪里去了（生产 / 委外 / 返工 / 试打 / 其他出入库 / 销售 / 盘点 / 形态转换）。
-- 参数：FcFrom, FcTo, Item 材料, ItemGrp 材料物料组, Dest 去向（中文，逗号分隔）, Prod 产品（只对订单领用有效）,
--       STYPE 0 材料 × 去向 / 1 材料 × 订单或科目 / 2 产品 × 材料（只含订单领用）
-- 口径：MTC_CA_R_LINE 的出库成本（耗用 = −金额，退料冲减）。挂订单的行按订单类型分去向（参数 WW_WORTYPES 委外、REWORK_WORTYPES 返工、
--       TRIAL_WORTYPES 试打，其余生产），不含订单完工入库；不挂订单的按交易类型：O01/O06 销售、O10/I10 盘点、O04/I04 其他出入库（业务类型在
--       TRIAL_ISSUE_BUSITYPES 的算试打）、O05 形态转换；采购、转储、重估不算耗用。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_05_MATUSE" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Dest NVARCHAR(200),
    IN Prod NVARCHAR(5000), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE fB NVARCHAR(10); DECLARE ww NVARCHAR(200); DECLARE rw NVARCHAR(200); DECLARE tr NVARCHAR(200); DECLARE tbi NVARCHAR(200);
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nDest INT; DECLARE nProd INT;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MAX("FcCode") INTO fB FROM :runs;
    ww := IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', :fB), ',50,');
    rw := IFNULL("MTC_CA_F_PARAM"('REWORK_WORTYPES', :fB), ',30,');
    tr := IFNULL("MTC_CA_F_PARAM"('TRIAL_WORTYPES', :fB), ',40,');
    tbi := IFNULL("MTC_CA_F_PARAM"('TRIAL_ISSUE_BUSITYPES', :fB), ',307,305,');
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lDest = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Dest);    SELECT COUNT(*) INTO nDest FROM :lDest;
    lProd = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Prod);    SELECT COUNT(*) INTO nProd FROM :lProd;
    lnx = SELECT U."FcCode", L."ItemCode", L."Qty", L."Amount", L."MatAmt", L."LabAmt", L."MfgAmt", L."SubAmt", L."OrderType", L."OrderEntry",
                SO."OrderNum", SO."WorType", SO."ItemCode" AS "Prod", D."AcctCode",
                CASE WHEN L."OrderEntry" IS NOT NULL THEN
                          CASE WHEN LOCATE(:ww, ',' || IFNULL(SO."WorType", '') || ',') > 0 THEN '委外'
                               WHEN LOCATE(:rw, ',' || IFNULL(SO."WorType", '') || ',') > 0 THEN '返工'
                               WHEN LOCATE(:tr, ',' || IFNULL(SO."WorType", '') || ',') > 0 THEN '试打' ELSE '生产' END
                     WHEN LOCATE(:tbi, ',' || IFNULL(D."BusiType", '') || ',') > 0 THEN '试打'
                     WHEN L."TransCode" IN ('O01', 'O06') THEN '销售'
                     WHEN L."TransCode" IN ('O10', 'I10') THEN '盘点'
                     WHEN L."TransCode" IN ('O04', 'I04') THEN '其他出入库'
                     WHEN L."TransCode" = 'O05' THEN '形态转换' END AS "Dest"
           FROM :runs U
           JOIN "MTC_CA_R_LINE" L ON L."RunId" = U."RunId"
           JOIN "MTC_CA_S_LINE" D ON D."RunId" = L."RunId" AND D."LineId" = L."LineId"
           LEFT JOIN "MTC_CA_S_ORDER" SO ON SO."RunId" = L."RunId" AND SO."OrderType" = L."OrderType" AND SO."OrderEntry" = L."OrderEntry"
           LEFT JOIN "OITM" M ON M."ItemCode" = L."ItemCode"
          WHERE NOT (L."OrderEntry" IS NOT NULL AND L."TransCode" IN ('I03', 'I07', 'I08', 'I09', 'I90'))
            AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE L."ItemCode" LIKE X."P"))
            AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"));
    lnx2 = SELECT * FROM :lnx
           WHERE "Dest" IS NOT NULL
             AND (:nDest = 0 OR EXISTS (SELECT 1 FROM :lDest X WHERE "Dest" = X."V"))
             AND (:nProd = 0 OR EXISTS (SELECT 1 FROM :lProd X WHERE "Prod" LIKE X."P"));
    IF :STYPE = '2' THEN
        SELECT L."Prod" AS "产品", MAX(P."ItemName") AS "产品名称", L."ItemCode" AS "材料", MAX(M."ItemName") AS "材料名称", COUNT(DISTINCT L."OrderType" || L."OrderEntry") AS "订单数",
               CAST(-SUM(L."Qty") AS DECIMAL(19,6)) AS "耗用·数量", CAST(-SUM(L."Amount") / NULLIF(-SUM(L."Qty"), 0) AS DECIMAL(19,6)) AS "耗用·单价",
               CAST(-SUM(L."Amount") AS DECIMAL(19,2)) AS "耗用·金额",
               CAST(-SUM(L."MatAmt") AS DECIMAL(19,2)) AS "构成·材料", CAST(-SUM(L."LabAmt") AS DECIMAL(19,2)) AS "构成·人工",
               CAST(-SUM(L."MfgAmt") AS DECIMAL(19,2)) AS "构成·制造", CAST(-SUM(L."SubAmt") AS DECIMAL(19,2)) AS "构成·委外"
          FROM :lnx2 L LEFT JOIN "OITM" M ON M."ItemCode" = L."ItemCode" LEFT JOIN "OITM" P ON P."ItemCode" = L."Prod"
         WHERE L."OrderEntry" IS NOT NULL
         GROUP BY L."Prod", L."ItemCode" ORDER BY L."Prod", L."ItemCode";
    ELSEIF :STYPE = '1' THEN
        SELECT L."ItemCode" AS "材料", MAX(M."ItemName") AS "材料名称", L."Dest" AS "去向", L."FcCode" AS "账期",
               MAX("MTC_CA_F_RPT_OTNAME"(L."OrderType")) AS "订单单据", L."OrderNum" AS "订单号 Num", MAX("MTC_CA_F_RPT_WTNAME"(L."WorType")) AS "订单类型", L."Prod" AS "产品", MAX(P."ItemName") AS "产品名称",
               CASE WHEN L."OrderEntry" IS NULL THEN L."AcctCode" END AS "科目", MAX(A."AcctName") AS "科目名称",
               CAST(-SUM(L."Qty") AS DECIMAL(19,6)) AS "耗用·数量", CAST(-SUM(L."Amount") / NULLIF(-SUM(L."Qty"), 0) AS DECIMAL(19,6)) AS "耗用·单价",
               CAST(-SUM(L."Amount") AS DECIMAL(19,2)) AS "耗用·金额"
          FROM :lnx2 L LEFT JOIN "OITM" M ON M."ItemCode" = L."ItemCode" LEFT JOIN "OITM" P ON P."ItemCode" = L."Prod"
          LEFT JOIN "OACT" A ON L."OrderEntry" IS NULL AND A."AcctCode" = L."AcctCode"
         GROUP BY L."ItemCode", L."Dest", L."FcCode", L."OrderType", L."OrderEntry", L."OrderNum", L."WorType", L."Prod",
                  CASE WHEN L."OrderEntry" IS NULL THEN L."AcctCode" END
         ORDER BY L."ItemCode", L."Dest", L."FcCode", L."OrderNum";
    ELSE
        SELECT TO_NVARCHAR(MAX(M."ItmsGrpCod")) AS "物料组", L."ItemCode" AS "材料", MAX(M."ItemName") AS "材料名称", L."Dest" AS "去向",
               CAST(-SUM(L."Qty") AS DECIMAL(19,6)) AS "耗用·数量", CAST(-SUM(L."Amount") / NULLIF(-SUM(L."Qty"), 0) AS DECIMAL(19,6)) AS "耗用·单价",
               CAST(-SUM(L."Amount") AS DECIMAL(19,2)) AS "耗用·金额",
               CAST(-SUM(L."MatAmt") AS DECIMAL(19,2)) AS "构成·材料", CAST(-SUM(L."LabAmt") AS DECIMAL(19,2)) AS "构成·人工",
               CAST(-SUM(L."MfgAmt") AS DECIMAL(19,2)) AS "构成·制造", CAST(-SUM(L."SubAmt") AS DECIMAL(19,2)) AS "构成·委外"
          FROM :lnx2 L LEFT JOIN "OITM" M ON M."ItemCode" = L."ItemCode"
         GROUP BY L."ItemCode", L."Dest"
         ORDER BY L."ItemCode", CASE L."Dest" WHEN '生产' THEN 1 WHEN '返工' THEN 2 WHEN '委外' THEN 3 WHEN '试打' THEN 4 WHEN '其他出入库' THEN 5
                                              WHEN '销售' THEN 6 WHEN '盘点' THEN 7 ELSE 8 END;
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #15
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice,@MTC_CSIGE1,@MTC_CSOIGE,@MTC_CSIGN1,@MTC_CSOIGN,OIGE.U_Creator,OIGN.U_Creator
-- ---------------------------------------------------------------------
-- R24 其他领用明细表（用户 2026-11-06，替代旧的其他领用查询）：与生产订单无关的其他出入库和盘点，逐单据行列出成本、部门、科目、研发项目和领用申请信息。
-- 参数：FcFrom, FcTo, Item 物料, ItemGrp 物料组, Busi 领用类型（业务类型代码）, Dept 部门（成本中心代码）, CostType 成本类型（I04 / O04 / I10 / O10）,
--       STYPE 1 单据行明细（默认）/ 0 领用类型 × 部门 × 科目汇总
-- 口径：MTC_CA_R_LINE + S_LINE，交易类型 I04 / O04 / I10 / O10（这四类不挂订单，P20_LINE 只给 I03 / O03 / I07 / O07 / I08 / O08 / I09 / O09 写订单）。
--       数量、金额按领用为正（入库类为负，= −R_LINE）；只含计价仓库，同收发存；历史期取回填的 R_LINE。公摊费用池有值 = 记 5101，金额进该费用池（V18）。
--       项目、备注、领用人、申请单号直接读当前 B1 单据（IGE1 / IGN1、@MTC_CSOIGE / @MTC_CSOIGN），创建日期、创建人取单据（旧查询取的是计算时间和计算人）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_24_OTHERUSE" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Busi NVARCHAR(500),
    IN Dept NVARCHAR(500), IN CostType NVARCHAR(100), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nBusi INT; DECLARE nDept INT; DECLARE nTr INT;
    DECLARE dB DATE; DECLARE dE DATE;
    runs = SELECT "FcCode", "RunId", "D0", "D1" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("D0"), MAX("D1") INTO dB, dE FROM :runs;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lBusi = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Busi);    SELECT COUNT(*) INTO nBusi FROM :lBusi;
    lDept = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Dept);    SELECT COUNT(*) INTO nDept FROM :lDept;
    lTr   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:CostType); SELECT COUNT(*) INTO nTr FROM :lTr;
    lnx = SELECT U."FcCode", L."RunId", L."LineId", D."ObjType", D."DocEntry", D."DocNum", D."LineNum", D."DocDate", D."BusiType", L."TransCode",
                 L."ItemCode", M."ItemName", M."ItmsGrpCod", I."iLevel", L."Qty", L."Price", L."Amount", L."MatAmt", L."LabAmt", L."MfgAmt", L."SubAmt",
                 L."PriceSrc", CASE WHEN L."IsShared" = 'Y' THEN L."PoolCode" END AS "SharedPool",
                 D."OcrCode", D."WhsCode", D."AcctCode", D."BaseType", D."BaseEntry", D."BaseLine"
            FROM :runs U
            JOIN "MTC_CA_R_LINE" L ON L."RunId" = U."RunId"
            JOIN "MTC_CA_S_LINE" D ON D."RunId" = L."RunId" AND D."LineId" = L."LineId"
            LEFT JOIN "MTC_CA_R_ITEM" I ON I."RunId" = L."RunId" AND I."ItemCode" = L."ItemCode"
            LEFT JOIN "OITM" M ON M."ItemCode" = L."ItemCode"
           WHERE L."TransCode" IN ('I04', 'O04', 'I10', 'O10')
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE L."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
             AND (:nBusi = 0 OR EXISTS (SELECT 1 FROM :lBusi X WHERE D."BusiType" LIKE X."P"))
             AND (:nDept = 0 OR EXISTS (SELECT 1 FROM :lDept X WHERE D."OcrCode" LIKE X."P"))
             AND (:nTr = 0 OR EXISTS (SELECT 1 FROM :lTr X WHERE L."TransCode" = X."V"));
    IF :STYPE = '0' THEN
        SELECT L."BusiType" AS "领用类型编码", MAX(C."Name") AS "领用类型名称", L."OcrCode" AS "部门编码", MAX(P."PrcName") AS "部门名称",
               L."AcctCode" AS "其他领用科目编码", MAX(A."AcctName") AS "其他领用科目名称", COUNT(*) AS "行数",
               CAST(-SUM(L."Amount") AS DECIMAL(19,2)) AS "成本金额",
               CAST(-SUM(L."MatAmt") AS DECIMAL(19,2)) AS "构成·材料", CAST(-SUM(L."LabAmt") AS DECIMAL(19,2)) AS "构成·人工",
               CAST(-SUM(L."MfgAmt") AS DECIMAL(19,2)) AS "构成·制造", CAST(-SUM(L."SubAmt") AS DECIMAL(19,2)) AS "构成·委外"
          FROM :lnx L
          LEFT JOIN "@U_CIOTRN" C ON C."Code" = L."BusiType"
          LEFT JOIN "OPRC" P ON P."PrcCode" = L."OcrCode"
          LEFT JOIN "OACT" A ON A."AcctCode" = L."AcctCode"
         GROUP BY L."BusiType", L."OcrCode", L."AcctCode"
         ORDER BY L."BusiType", L."OcrCode", L."AcctCode";
    ELSE
        ge = SELECT TO_NVARCHAR(T0."ObjType") AS "ObjType", T0."DocEntry", T0."LineNum", MAX(T0."Project") AS "Project", MAX(T."CreateDate") AS "CreateDate",
                    STRING_AGG(TO_NVARCHAR(T2."U_Remark"), ',') AS "Remark", STRING_AGG(TO_NVARCHAR(T2."U_Remark2"), ',') AS "Remark2", STRING_AGG(TO_NVARCHAR(T2."U_Remark3"), ',') AS "Remark3",
                    STRING_AGG(TO_NVARCHAR(COALESCE(U."U_NAME", T."U_Creator")), ',') AS "Creator", STRING_AGG(TO_NVARCHAR(T2."U_SupNum"), ',') AS "SupNum",
                    MAX(TO_NVARCHAR(T2."U_OARequestID")) AS "OaId"
               FROM "IGE1" T0
               JOIN "OIGE" T ON T0."DocEntry" = T."DocEntry"
               LEFT JOIN "@MTC_CSIGE1" T1 ON T1."Object" = T0."U_BaseType" AND T1."DocEntry" = T0."U_BaseEntry" AND T1."LineId" = T0."U_BaseLine"
               LEFT JOIN "@MTC_CSOIGE" T2 ON T2."DocEntry" = T1."DocEntry"
               LEFT JOIN "OUSR" U ON U."USER_CODE" = T2."U_Creator"
              WHERE T."DocDate" BETWEEN :dB AND :dE
              GROUP BY T0."ObjType", T0."DocEntry", T0."LineNum";
        gn = SELECT TO_NVARCHAR(T0."ObjType") AS "ObjType", T0."DocEntry", T0."LineNum", MAX(T0."Project") AS "Project", MAX(T."CreateDate") AS "CreateDate",
                    STRING_AGG(TO_NVARCHAR(T2."U_Remark"), ',') AS "Remark", STRING_AGG(TO_NVARCHAR(T2."U_Remark2"), ',') AS "Remark2", STRING_AGG(TO_NVARCHAR(T2."U_Remark3"), ',') AS "Remark3",
                    STRING_AGG(TO_NVARCHAR(COALESCE(U."U_NAME", T."U_Creator")), ',') AS "Creator", STRING_AGG(TO_NVARCHAR(T2."U_SupNum"), ',') AS "SupNum"
               FROM "IGN1" T0
               JOIN "OIGN" T ON T0."DocEntry" = T."DocEntry"
               LEFT JOIN "@MTC_CSIGN1" T1 ON T1."Object" = T0."U_BaseType" AND T1."DocEntry" = T0."U_BaseEntry" AND T1."LineId" = T0."U_BaseLine"
               LEFT JOIN "@MTC_CSOIGN" T2 ON T2."DocEntry" = T1."DocEntry"
               LEFT JOIN "OUSR" U ON U."USER_CODE" = T2."U_Creator"
              WHERE T."DocDate" BETWEEN :dB AND :dE
              GROUP BY T0."ObjType", T0."DocEntry", T0."LineNum";
        ext = SELECT "ObjType", "DocEntry", "LineNum", "Project", "CreateDate", "Remark", "Remark2", "Remark3", "Creator", "SupNum", "OaId" FROM :ge
              UNION ALL
              SELECT "ObjType", "DocEntry", "LineNum", "Project", "CreateDate", "Remark", "Remark2", "Remark3", "Creator", "SupNum", CAST(NULL AS NVARCHAR(100)) FROM :gn;
        vd = SELECT TO_NVARCHAR("ObjType") AS "ObjType", TO_NVARCHAR("DocEntry") AS "DocEntry", TO_NVARCHAR("LineNum") AS "LineNum", TO_NVARCHAR("BaseRef") AS "BaseRef"
               FROM "MTC_VIEW_Document" WHERE TO_NVARCHAR("ObjType") IN ('59', '60') AND "DocDate" BETWEEN :dB AND :dE;
        SELECT L."FcCode" AS "账期", L."ObjType" AS "单据类型", T9."DocName" AS "单据类型名称", L."DocEntry" AS "单号 Entry", L."DocNum" AS "单号 Num", L."LineNum" AS "行号",
               L."DocDate" AS "过账日期", L."BusiType" AS "领用类型编码", C."Name" AS "领用类型名称", L."TransCode" AS "成本类型编码",
               L."ItemCode" AS "物料编码", L."ItemName" AS "物料名称", TO_NVARCHAR(L."ItmsGrpCod") AS "物料组编码",
               CAST(-L."Qty" AS DECIMAL(19,6)) AS "数量", CAST(L."Price" AS DECIMAL(19,6)) AS "成本单价", CAST(-L."Amount" AS DECIMAL(19,2)) AS "成本金额",
               CAST(-L."MatAmt" AS DECIMAL(19,2)) AS "构成·材料", CAST(-L."LabAmt" AS DECIMAL(19,2)) AS "构成·人工",
               CAST(-L."MfgAmt" AS DECIMAL(19,2)) AS "构成·制造", CAST(-L."SubAmt" AS DECIMAL(19,2)) AS "构成·委外",
               L."OcrCode" AS "部门编码", P."PrcName" AS "部门名称", E."Project" AS "研发项目编码", R."PrjName" AS "研发项目名称",
               L."SharedPool" AS "公摊费用池", L."WhsCode" AS "仓库代码", W."WhsName" AS "仓库名称", L."iLevel" AS "层级",
               G."StockAct" AS "库存科目编码", A1."AcctName" AS "库存科目名称", L."AcctCode" AS "其他领用科目编码", A2."AcctName" AS "其他领用科目名称",
               L."BaseType" AS "来源类型", L."BaseEntry" AS "来源单号 Entry", V."BaseRef" AS "来源单号 Num", L."BaseLine" AS "来源行号",
               E."Remark" AS "备注", E."Remark2" AS "领用说明", E."Remark3" AS "领用人", E."CreateDate" AS "创建日期", E."Creator" AS "创建人",
               CASE WHEN L."ObjType" = '60' THEN E."SupNum" END AS "出库申请单号", CASE WHEN L."ObjType" = '59' THEN E."SupNum" END AS "入库申请单号",
               L."PriceSrc" AS "定价来源", E."OaId" AS "领料申请表ID"
          FROM :lnx L
          LEFT JOIN "MTC_DocType" T9 ON T9."ObjType" = L."ObjType"
          LEFT JOIN "@U_CIOTRN" C ON C."Code" = L."BusiType"
          LEFT JOIN "OPRC" P ON P."PrcCode" = L."OcrCode"
          LEFT JOIN "OWHS" W ON W."WhsCode" = L."WhsCode"
          LEFT JOIN :ext E ON E."ObjType" = L."ObjType" AND E."DocEntry" = L."DocEntry" AND E."LineNum" = L."LineNum"
          LEFT JOIN :vd V ON V."ObjType" = L."ObjType" AND V."DocEntry" = TO_NVARCHAR(L."DocEntry") AND V."LineNum" = TO_NVARCHAR(L."LineNum")
          LEFT JOIN "OPRJ" R ON R."PrjCode" = E."Project"
          LEFT JOIN (SELECT "PeriodCat", "ItmsGrpCod", MAX("StockAct") AS "StockAct" FROM "OGAR" GROUP BY "PeriodCat", "ItmsGrpCod") G
                 ON G."PeriodCat" = LEFT(L."FcCode", 4) AND G."ItmsGrpCod" = L."ItmsGrpCod"
          LEFT JOIN "OACT" A1 ON A1."AcctCode" = G."StockAct"
          LEFT JOIN "OACT" A2 ON A2."AcctCode" = L."AcctCode"
         ORDER BY L."DocDate", L."ObjType", L."DocEntry", L."LineNum", L."LineId";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #16
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R06 制造费用 / 人工分配表：费用池归集了多少、按工时分给了哪些产品和订单、没分到的原因。
-- 参数：FcFrom, FcTo, Pool 费用池, Elem 要素（MFG 制造 / LAB 人工，空 = 两项）, Prod 产品,
--       STYPE 0 池汇总 / 1 池 × 产品（含没分到的产品和原因）/ 2 池 × 订单 / 3 归集来源明细
-- 口径：MTC_CA_R_POOL（归集，按来源 JDT 凭证 / MRV 重估 / PROWW 委外重估 / SHARED 公摊材料 / CLOSEDIF 关单差异 / WWHIST 历史委外差异）、MTC_CA_R_ALLOC
--       （工时 = 单位工时 × 本期入库数，同池按工时比例分）；没分到的原因同执行台“工时分摊”页。
-- 勾稽：已分配合计 = R01 本级分摊人工 + 制造（V04）；未分配应为 0（Q12，未分摊报出不转下期）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_06_EXPALLOC" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Pool NVARCHAR(500), IN Elem NVARCHAR(3), IN Prod NVARCHAR(5000), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nPool INT; DECLARE nProd INT;
    DECLARE el NVARCHAR(3) := CASE WHEN :Elem IN ('MFG', '制造') THEN 'MFG' WHEN :Elem IN ('LAB', '人工') THEN 'LAB' ELSE '' END;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    lPool = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Pool); SELECT COUNT(*) INTO nPool FROM :lPool;
    lProd = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Prod); SELECT COUNT(*) INTO nProd FROM :lProd;
    IF :STYPE = '1' THEN
        ord = SELECT U."FcCode", O."RunId", O."ItemCode", O."OrderType", O."OrderEntry", O."WorType", O."RecvQty"
                FROM :runs U JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
               WHERE O."RecvQty" <> 0 AND (:nProd = 0 OR EXISTS (SELECT 1 FROM :lProd X WHERE O."ItemCode" LIKE X."P"));
        al = SELECT "RunId", "OrderType", "OrderEntry", "PoolCode", MAX("Hours") AS "H", MAX("Weight") AS "W",
                    SUM(CASE WHEN "Elem" = 'MFG' THEN "Amount" ELSE 0 END) AS "Mfg", SUM(CASE WHEN "Elem" = 'LAB' THEN "Amount" ELSE 0 END) AS "Lab"
               FROM "MTC_CA_R_ALLOC" WHERE "RunId" IN (SELECT "RunId" FROM :runs)
              GROUP BY "RunId", "OrderType", "OrderEntry", "PoolCode";
        pw = SELECT "RunId", "PoolCode", MAX("W") AS "TotW" FROM (SELECT "RunId", "PoolCode", "Elem", SUM("Weight") AS "W" FROM "MTC_CA_R_ALLOC"
                                                                   WHERE "RunId" IN (SELECT "RunId" FROM :runs) GROUP BY "RunId", "PoolCode", "Elem")
              GROUP BY "RunId", "PoolCode";
        d = SELECT O."FcCode", O."RunId", O."ItemCode", O."RecvQty", A."PoolCode", A."W", A."Mfg", A."Lab", IFNULL(A."H", H."Hours") AS "UH",
                   CASE WHEN A."PoolCode" IS NOT NULL THEN '已分摊' WHEN O."RecvQty" < 0 THEN '本期净入库为负，不分摊'
                        WHEN LOCATE(IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', O."FcCode"), ',50,'), ',' || IFNULL(O."WorType", '') || ',') > 0 THEN '委外工单，不分摊'
                        WHEN H."ItemCode" IS NULL THEN '没有单位工时' WHEN H."Hours" = 0 THEN '单位工时为 0'
                        ELSE '未分摊：不在费用池范围或池内没有金额' END AS "State"
              FROM :ord O
              LEFT JOIN :al A ON A."RunId" = O."RunId" AND A."OrderType" = O."OrderType" AND A."OrderEntry" = O."OrderEntry"
              LEFT JOIN "MTC_CA_S_HOURS" H ON H."RunId" = O."RunId" AND H."ItemCode" = O."ItemCode";
        SELECT D."FcCode" AS "账期", D."PoolCode" AS "费用池", MAX(C."PoolName") AS "费用池名称", D."ItemCode" AS "产品", MAX(M."ItemName") AS "产品名称",
               D."State" AS "分摊状态", CAST(MAX(D."UH") AS DECIMAL(19,6)) AS "单位工时", COUNT(*) AS "订单数", CAST(SUM(D."RecvQty") AS DECIMAL(19,6)) AS "本期入库数",
               CAST(SUM(D."W") AS DECIMAL(19,6)) AS "工时", CAST(SUM(D."W") * 100 / NULLIF(MAX(P."TotW"), 0) AS DECIMAL(19,4)) AS "占池工时 %",
               CAST(SUM(D."Mfg") AS DECIMAL(19,2)) AS "分摊·制造", CAST(SUM(D."Lab") AS DECIMAL(19,2)) AS "分摊·人工",
               CAST(SUM(D."Mfg") + SUM(D."Lab") AS DECIMAL(19,2)) AS "分摊·合计",
               CAST((SUM(D."Mfg") + SUM(D."Lab")) / NULLIF(SUM(D."RecvQty"), 0) AS DECIMAL(19,6)) AS "每件费用",
               CAST((SUM(D."Mfg") + SUM(D."Lab")) / NULLIF(SUM(D."W"), 0) AS DECIMAL(19,6)) AS "每工时费用"
          FROM :d D
          LEFT JOIN :pw P ON P."RunId" = D."RunId" AND P."PoolCode" = D."PoolCode"
          LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = D."PoolCode"
          LEFT JOIN "OITM" M ON M."ItemCode" = D."ItemCode"
         WHERE :nPool = 0 OR D."PoolCode" IS NULL OR EXISTS (SELECT 1 FROM :lPool X WHERE D."PoolCode" = X."V")
         GROUP BY D."FcCode", D."PoolCode", D."ItemCode", D."State"
         ORDER BY D."FcCode", CASE WHEN D."PoolCode" IS NULL THEN 1 ELSE 0 END, D."PoolCode", D."ItemCode";
    ELSEIF :STYPE = '2' THEN
        SELECT U."FcCode" AS "账期", A."PoolCode" AS "费用池", C."PoolName" AS "费用池名称", CASE A."Elem" WHEN 'MFG' THEN '制造' ELSE '人工' END AS "要素",
               "MTC_CA_F_RPT_OTNAME"(A."OrderType") AS "订单单据", S."OrderNum" AS "订单号 Num", A."OrderEntry" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"(S."WorType") AS "订单类型",
               S."ItemCode" AS "产品", M."ItemName" AS "产品名称",
               CAST(A."Hours" AS DECIMAL(19,6)) AS "单位工时", CAST(A."RecvQty" AS DECIMAL(19,6)) AS "本期入库数", CAST(A."Weight" AS DECIMAL(19,6)) AS "工时",
               CAST(A."Ratio" * 100 AS DECIMAL(19,4)) AS "占池比例 %", CAST(A."Amount" AS DECIMAL(19,2)) AS "分摊金额"
          FROM :runs U
          JOIN "MTC_CA_R_ALLOC" A ON A."RunId" = U."RunId"
          LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = A."RunId" AND S."OrderType" = A."OrderType" AND S."OrderEntry" = A."OrderEntry"
          LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = A."PoolCode"
          LEFT JOIN "OITM" M ON M."ItemCode" = S."ItemCode"
         WHERE (:el = '' OR A."Elem" = :el)
           AND (:nPool = 0 OR EXISTS (SELECT 1 FROM :lPool X WHERE A."PoolCode" = X."V"))
           AND (:nProd = 0 OR EXISTS (SELECT 1 FROM :lProd X WHERE S."ItemCode" LIKE X."P"))
         ORDER BY U."FcCode", A."PoolCode", A."Elem", S."ItemCode", S."OrderNum";
    ELSEIF :STYPE = '3' THEN
        src = SELECT U."FcCode", IFNULL(PS."PoolCode", DP."PoolCode") AS "PoolCode", E."Elem", E."Src", E."SrcTrans", E."AcctCode", E."OcrCode", E."DocDate",
                     E."SrcKey", E."SrcObj", CASE WHEN E."Src" = 'JDT' THEN TO_NVARCHAR(H."BaseRef") WHEN E."Src" IN ('MRV', 'PROWW') THEN TO_NVARCHAR(MR."DocNum") END AS "DocNum",
                     CASE WHEN E."Src" = 'JDT' THEN TO_NVARCHAR(H."Number") END AS "JdtNum",
                     CAST(NULL AS NVARCHAR(50)) AS "ItemCode", CAST(NULL AS DECIMAL(19,6)) AS "Qty", E."Amount", E."Note"
                FROM :runs U
                JOIN "MTC_CA_S_EXP" E ON E."RunId" = U."RunId"
                LEFT JOIN "MTC_CA_C_POOL_SRC" PS ON PS."OcrCode" = E."OcrCode" AND E."FcCode" BETWEEN PS."FromFc" AND PS."ToFc"
                LEFT JOIN "OJDT" H ON E."Src" = 'JDT' AND H."TransId" = CASE WHEN E."SrcKey" LIKE_REGEXPR '^[0-9]+-' THEN TO_INTEGER(SUBSTR_BEFORE(E."SrcKey", '-')) END
                LEFT JOIN "@MTC_OMRV" MR ON E."Src" IN ('MRV', 'PROWW') AND MR."DocEntry" = E."SrcDoc"
                CROSS JOIN (SELECT MAX("PoolCode") AS "PoolCode" FROM "MTC_CA_C_POOL" WHERE "IsDefault" = 'Y') DP
              UNION ALL
              SELECT U."FcCode", L."PoolCode", 'MFG', 'SHARED', L."TransCode", D."AcctCode", D."OcrCode", D."DocDate",
                     D."ObjType" || '-' || IFNULL(D."DocNum", TO_NVARCHAR(D."DocEntry")) || '-' || IFNULL(TO_NVARCHAR(D."LineNum"), ''), D."ObjType", D."DocNum",
                     CAST(NULL AS NVARCHAR(20)), L."ItemCode", -L."Qty", -L."Amount", L."PriceSrc"
                FROM :runs U
                JOIN "MTC_CA_R_LINE" L ON L."RunId" = U."RunId" AND L."IsShared" = 'Y'
                JOIN "MTC_CA_S_LINE" D ON D."RunId" = L."RunId" AND D."LineId" = L."LineId"
              UNION ALL
              SELECT U."FcCode", "MTC_CA_F_PARAM"('CLOSE_DIF_POOL', U."FcCode"), 'MFG', 'CLOSEDIF', CAST(NULL AS NVARCHAR(20)), CAST(NULL AS NVARCHAR(15)),
                     CAST(NULL AS NVARCHAR(20)), CAST(NULL AS DATE), O."OrderType" || '-' || TO_NVARCHAR(O."OrderEntry"), O."OrderType", SO."OrderNum",
                     CAST(NULL AS NVARCHAR(20)), O."ItemCode", CAST(NULL AS DECIMAL(19,6)), O."CloseDifAmt", '订单本期关单差异'
                FROM :runs U
                JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId" AND O."CloseDifAmt" <> 0
                LEFT JOIN "MTC_CA_S_ORDER" SO ON SO."RunId" = O."RunId" AND SO."OrderType" = O."OrderType" AND SO."OrderEntry" = O."OrderEntry";
        SELECT S."FcCode" AS "账期", S."PoolCode" AS "费用池", C."PoolName" AS "费用池名称", CASE S."Elem" WHEN 'MFG' THEN '制造' ELSE '人工' END AS "要素",
               CASE S."Src" WHEN 'JDT' THEN '凭证' WHEN 'MRV' THEN '库存重估' WHEN 'PROWW' THEN '委外重估' WHEN 'SHARED' THEN '公摊材料' WHEN 'CLOSEDIF' THEN '关单差异' WHEN 'WWHIST' THEN '历史委外差异' ELSE S."Src" END AS "来源",
               S."SrcTrans" AS "凭证代码 / 交易类型", S."AcctCode" AS "科目", A."AcctName" AS "科目名称", S."OcrCode" AS "成本中心", S."DocDate" AS "日期",
               "MTC_CA_F_RPT_DTNAME"(S."SrcObj") AS "单据类型", S."DocNum" AS "单号 Num", S."JdtNum" AS "凭证编号 Number", S."SrcKey" AS "来源键",
               S."ItemCode" AS "物料", CAST(S."Qty" AS DECIMAL(19,6)) AS "数量", CAST(S."Amount" AS DECIMAL(19,2)) AS "金额", S."Note" AS "备注"
          FROM :src S
          LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = S."PoolCode"
          LEFT JOIN "OACT" A ON A."AcctCode" = S."AcctCode"
         WHERE (:el = '' OR S."Elem" = :el)
           AND (:nPool = 0 OR EXISTS (SELECT 1 FROM :lPool X WHERE S."PoolCode" = X."V"))
         ORDER BY S."FcCode", S."PoolCode", S."Elem", S."Src", S."DocDate", S."SrcKey";
    ELSE
        poolT = SELECT U."FcCode", P."RunId", P."PoolCode", P."Elem",
                      SUM(CASE WHEN P."Src" = 'JDT' THEN P."Amount" ELSE 0 END) AS "SJdt", SUM(CASE WHEN P."Src" = 'MRV' THEN P."Amount" ELSE 0 END) AS "SMrv",
                      SUM(CASE WHEN P."Src" = 'PROWW' THEN P."Amount" ELSE 0 END) AS "SWw", SUM(CASE WHEN P."Src" = 'SHARED' THEN P."Amount" ELSE 0 END) AS "SShr",
                      -- 历史委外差异转出（WWHIST，用户 2026-11-04）性质同关单差异，并入这一列，各列合计 = 归集·合计
                      SUM(CASE WHEN P."Src" IN ('CLOSEDIF', 'WWHIST') THEN P."Amount" ELSE 0 END) AS "SCls", SUM(P."Amount") AS "Amt"
                 FROM :runs U JOIN "MTC_CA_R_POOL" P ON P."RunId" = U."RunId"
                GROUP BY U."FcCode", P."RunId", P."PoolCode", P."Elem";
        alP = SELECT "RunId", "PoolCode", "Elem", SUM("Amount") AS "Amt", COUNT(*) AS "Cnt", SUM("Weight") AS "W"
               FROM "MTC_CA_R_ALLOC" WHERE "RunId" IN (SELECT "RunId" FROM :runs) GROUP BY "RunId", "PoolCode", "Elem";
        SELECT P."FcCode" AS "账期", P."PoolCode" AS "费用池", C."PoolName" AS "费用池名称", CASE P."Elem" WHEN 'MFG' THEN '制造' ELSE '人工' END AS "要素",
               CAST(P."SJdt" AS DECIMAL(19,2)) AS "归集·凭证", CAST(P."SMrv" AS DECIMAL(19,2)) AS "归集·库存重估", CAST(P."SWw" AS DECIMAL(19,2)) AS "归集·委外重估",
               CAST(P."SShr" AS DECIMAL(19,2)) AS "归集·公摊材料", CAST(P."SCls" AS DECIMAL(19,2)) AS "归集·关单差异", CAST(P."Amt" AS DECIMAL(19,2)) AS "归集·合计",
               CAST(IFNULL(A."Amt", 0) AS DECIMAL(19,2)) AS "已分配", CAST(P."Amt" - IFNULL(A."Amt", 0) AS DECIMAL(19,2)) AS "未分配",
               IFNULL(A."Cnt", 0) AS "分配订单数", CAST(A."W" AS DECIMAL(19,6)) AS "工时合计",
               CAST(IFNULL(A."Amt", 0) / NULLIF(A."W", 0) AS DECIMAL(19,6)) AS "每工时费用"
          FROM :poolT P
          LEFT JOIN :alP A ON A."RunId" = P."RunId" AND A."PoolCode" = P."PoolCode" AND A."Elem" = P."Elem"
          LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = P."PoolCode"
         WHERE (:el = '' OR P."Elem" = :el)
           AND (:nPool = 0 OR EXISTS (SELECT 1 FROM :lPool X WHERE P."PoolCode" = X."V"))
         ORDER BY P."FcCode", P."PoolCode", P."Elem";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #17
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R07 委外加工成本表：委外订单发出材料、加工费、完工成本、在产品，按供应商汇总。
-- 参数：FcFrom, FcTo, Vendor 供应商（订单上的业务伙伴）, OrderNum 订单号 Num, Prod 产品, STYPE 0 按供应商 / 1 按订单 / 2 订单 × 材料
-- 口径：订单类型在参数 WW_WORTYPES 的订单（R_ORDER / R_ORDER_MAT）；'#SUBFEE' 行 = 委外加工费（按暂估金额，S_SUBFEE）；
--       不分摊人工和制造费用。期末在产品·材料 = 140801 业务端，期末在产品·加工费 = 140802 业务端（R09 WW_MAT / WW_FEE）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_07_SUBCON" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Vendor NVARCHAR(5000), IN OrderNum NVARCHAR(5000), IN Prod NVARCHAR(5000), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nVen INT; DECLARE nOrd INT; DECLARE nProd INT; DECLARE fA NVARCHAR(10); DECLARE fB NVARCHAR(10);
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("FcCode"), MAX("FcCode") INTO fA, fB FROM :runs;
    lVen  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Vendor);   SELECT COUNT(*) INTO nVen FROM :lVen;
    lOrd  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:OrderNum); SELECT COUNT(*) INTO nOrd FROM :lOrd;
    lProd = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Prod);     SELECT COUNT(*) INTO nProd FROM :lProd;
    ord = SELECT U."FcCode", O."RunId", O."OrderType", O."OrderEntry", S."OrderNum", O."WorType", O."ItemCode", S."CardCode",
                 O."PlannedQty", O."RecvQty", O."CostAmt", O."CostSub", O."CloseDifAmt", O."WipAmt", O."ClosedInFc", S."StatusAtEnd"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
           WHERE LOCATE(IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', U."FcCode"), ',50,'), ',' || IFNULL(O."WorType", '') || ',') > 0
             AND (:nVen = 0 OR EXISTS (SELECT 1 FROM :lVen X WHERE S."CardCode" LIKE X."P"))
             AND (:nOrd = 0 OR EXISTS (SELECT 1 FROM :lOrd X WHERE S."OrderNum" LIKE X."P"))
             AND (:nProd = 0 OR EXISTS (SELECT 1 FROM :lProd X WHERE O."ItemCode" LIKE X."P"));
    IF :STYPE = '2' THEN
        SELECT O."FcCode" AS "账期", O."CardCode" AS "供应商", "MTC_CA_F_RPT_OTNAME"(O."OrderType") AS "订单单据", O."OrderNum" AS "订单号 Num", O."ItemCode" AS "产品",
               M."ItemCode" AS "材料", CASE WHEN M."ItemCode" = '#SUBFEE' THEN '委外加工费' ELSE I."ItemName" END AS "材料名称",
               CAST(M."OpenIssMat" + M."OpenIssLab" + M."OpenIssMfg" + M."OpenIssSub" - M."OpenCarMat" - M."OpenCarLab" - M."OpenCarMfg" - M."OpenCarSub" AS DECIMAL(19,2)) AS "期初在产品",
               CAST(M."IssQty" AS DECIMAL(19,6)) AS "本期发出·数量", CAST(M."IssMat" + M."IssLab" + M."IssMfg" + M."IssSub" AS DECIMAL(19,2)) AS "本期发出·金额",
               CAST(M."Ratio" AS DECIMAL(19,6)) AS "结转比例",
               CAST(M."CarMat" + M."CarLab" + M."CarMfg" + M."CarSub" AS DECIMAL(19,2)) AS "完工转出",
               CAST(M."ClsMat" + M."ClsLab" + M."ClsMfg" + M."ClsSub" AS DECIMAL(19,2)) AS "关单差异",
               CAST(M."WipMat" + M."WipLab" + M."WipMfg" + M."WipSub" AS DECIMAL(19,2)) AS "期末在产品"
          FROM :ord O
          JOIN "MTC_CA_R_ORDER_MAT" M ON M."RunId" = O."RunId" AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
          LEFT JOIN "OITM" I ON I."ItemCode" = M."ItemCode"
         ORDER BY O."FcCode", O."CardCode", O."OrderNum", CASE WHEN M."ItemCode" = '#SUBFEE' THEN 1 ELSE 0 END, M."ItemCode";
    ELSE
        d = SELECT O."FcCode", O."CardCode", O."OrderType", O."OrderEntry", O."OrderNum", O."ItemCode", O."StatusAtEnd", O."ClosedInFc",
                   O."PlannedQty", O."RecvQty", O."CostAmt", O."CloseDifAmt",
                   SUM(CASE WHEN M."ItemCode" <> '#SUBFEE' THEN M."OpenIssMat" + M."OpenIssLab" + M."OpenIssMfg" + M."OpenIssSub" - M."OpenCarMat" - M."OpenCarLab" - M."OpenCarMfg" - M."OpenCarSub" ELSE 0 END) AS "BMat",
                   SUM(CASE WHEN M."ItemCode" = '#SUBFEE' THEN M."OpenIssSub" - M."OpenCarSub" ELSE 0 END) AS "BFee",
                   SUM(CASE WHEN M."ItemCode" <> '#SUBFEE' THEN M."IssMat" + M."IssLab" + M."IssMfg" + M."IssSub" ELSE 0 END) AS "IMat",
                   SUM(CASE WHEN M."ItemCode" = '#SUBFEE' THEN M."IssSub" ELSE 0 END) AS "IFee",
                   SUM(CASE WHEN M."ItemCode" <> '#SUBFEE' THEN M."CarMat" + M."CarLab" + M."CarMfg" + M."CarSub" ELSE 0 END) AS "CMat",
                   SUM(CASE WHEN M."ItemCode" = '#SUBFEE' THEN M."CarSub" ELSE 0 END) AS "CFee",
                   SUM(CASE WHEN M."ItemCode" <> '#SUBFEE' THEN M."WipMat" + M."WipLab" + M."WipMfg" + M."WipSub" ELSE 0 END) AS "WMat",
                   SUM(CASE WHEN M."ItemCode" = '#SUBFEE' THEN M."WipSub" ELSE 0 END) AS "WFee"
              FROM :ord O
              LEFT JOIN "MTC_CA_R_ORDER_MAT" M ON M."RunId" = O."RunId" AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
             GROUP BY O."FcCode", O."CardCode", O."OrderType", O."OrderEntry", O."OrderNum", O."ItemCode", O."StatusAtEnd", O."ClosedInFc",
                      O."PlannedQty", O."RecvQty", O."CostAmt", O."CloseDifAmt";
        IF :STYPE = '1' THEN
            SELECT D."FcCode" AS "账期", D."CardCode" AS "供应商", C."CardName" AS "供应商名称", "MTC_CA_F_RPT_OTNAME"(D."OrderType") AS "订单单据", D."OrderNum" AS "订单号 Num",
                   D."OrderEntry" AS "订单 Entry", D."ItemCode" AS "产品", M."ItemName" AS "产品名称", D."StatusAtEnd" AS "期末状态", D."ClosedInFc" AS "按关单处理",
                   CAST(D."PlannedQty" AS DECIMAL(19,6)) AS "计划数", CAST(D."RecvQty" AS DECIMAL(19,6)) AS "本期完工",
                   CAST(D."BMat" AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(D."BFee" AS DECIMAL(19,2)) AS "期初在产品·加工费",
                   CAST(D."IMat" AS DECIMAL(19,2)) AS "本期·发出材料", CAST(D."IFee" AS DECIMAL(19,2)) AS "本期·加工费",
                   CAST(D."CMat" AS DECIMAL(19,2)) AS "完工转出·材料", CAST(D."CFee" AS DECIMAL(19,2)) AS "完工转出·加工费",
                   CAST(D."CostAmt" AS DECIMAL(19,2)) AS "完工转出·合计", CAST(D."CostAmt" / NULLIF(D."RecvQty", 0) AS DECIMAL(19,6)) AS "完工转出·单位成本",
                   CAST(D."CloseDifAmt" AS DECIMAL(19,2)) AS "关单差异",
                   CAST(D."WMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(D."WFee" AS DECIMAL(19,2)) AS "期末在产品·加工费"
              FROM :d D LEFT JOIN "OCRD" C ON C."CardCode" = D."CardCode" LEFT JOIN "OITM" M ON M."ItemCode" = D."ItemCode"
             ORDER BY D."FcCode", D."CardCode", D."OrderNum";
        ELSE
            SELECT D."CardCode" AS "供应商", MAX(C."CardName") AS "供应商名称", COUNT(DISTINCT D."OrderType" || D."OrderEntry") AS "订单数",
                   CAST(SUM(D."RecvQty") AS DECIMAL(19,6)) AS "本期完工数量",
                   CAST(SUM(CASE WHEN D."FcCode" = :fA THEN D."BMat" ELSE 0 END) AS DECIMAL(19,2)) AS "期初在产品·材料",
                   CAST(SUM(CASE WHEN D."FcCode" = :fA THEN D."BFee" ELSE 0 END) AS DECIMAL(19,2)) AS "期初在产品·加工费",
                   CAST(SUM(D."IMat") AS DECIMAL(19,2)) AS "本期·发出材料", CAST(SUM(D."IFee") AS DECIMAL(19,2)) AS "本期·加工费",
                   CAST(SUM(D."CMat") AS DECIMAL(19,2)) AS "完工转出·材料", CAST(SUM(D."CFee") AS DECIMAL(19,2)) AS "完工转出·加工费",
                   CAST(SUM(D."CostAmt") AS DECIMAL(19,2)) AS "完工转出·合计", CAST(SUM(D."CloseDifAmt") AS DECIMAL(19,2)) AS "关单差异",
                   CAST(SUM(CASE WHEN D."FcCode" = :fB THEN D."WMat" ELSE 0 END) AS DECIMAL(19,2)) AS "期末在产品·材料",
                   CAST(SUM(CASE WHEN D."FcCode" = :fB THEN D."WFee" ELSE 0 END) AS DECIMAL(19,2)) AS "期末在产品·加工费"
              FROM :d D LEFT JOIN "OCRD" C ON C."CardCode" = D."CardCode"
             GROUP BY D."CardCode" ORDER BY D."CardCode";
        END IF;
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #18
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R08 销售成本计算表：期初发出商品 + 本期发货 − 独立退货 − 本期消耗（开票、贷项、退货、尾差）= 期末发出商品；销售成本 = DN03。
-- 参数：FcFrom, FcTo, Item 物料, ItemGrp 物料组, Cust 客户, CustType 客户类型（@MTC_SALORDTYPE.U_CustType，如 国内客户）,
--       STYPE 0 按产品 / 1 按客户 / 2 按交货（退货）行
-- 口径：期初 / 期末 = R_GOODS_OUT_BEG / R_GOODS_OUT 的未开票成本；发货 = 交货行（15）的出库成本，独立退货 = 不基于交货的销售退货行（16）的入库成本；
--       消耗 = R_GOODS_MOVE（INV 开票、RIN 贷项、RET 基于交货的退货、ADJ 全部消耗完时的尾差）；销售成本（DN03）= 非样品的 INV + RIN + ADJ，
--       样品单列（DN02 / DN04）。“勾稽差额”应为 0。客户和客户类型取交货 / 退货单表头。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_08_SALECOST" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Cust NVARCHAR(5000),
    IN CustType NVARCHAR(200), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE fA NVARCHAR(10); DECLARE fB NVARCHAR(10); DECLARE nItem INT; DECLARE nGrp INT; DECLARE nCust INT; DECLARE nCt INT;
    -- 历史期（旧框架回填）没有发出商品和销售成本的结果（报表合并第一阶段不回填，2026-11-02）
    IF "MTC_CA_F_RPT_HISTONLY"(:FcFrom, :FcTo) = 'Y' THEN
        SELECT '历史期（旧框架回填）没有这张报表的数据：旧框架没有保存发出商品和销售成本的明细结果，请用旧报表查看' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("FcCode"), MAX("FcCode") INTO fA, fB FROM :runs;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lCust = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Cust);     SELECT COUNT(*) INTO nCust FROM :lCust;
    lCt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:CustType); SELECT COUNT(*) INTO nCt FROM :lCt;
    -- 一行 = 一条交货 / 退货行在某一列上的金额
    f = SELECT G."ObjType", G."DocEntry", G."LineNum", G."ItemCode", CAST(G."CostAmt" AS DECIMAL(19,6)) AS "Beg", CAST(0 AS DECIMAL(19,6)) AS "Iss", CAST(0 AS DECIMAL(19,6)) AS "Ret0", CAST(0 AS DECIMAL(19,6)) AS "Inv",
               CAST(0 AS DECIMAL(19,6)) AS "Rin", CAST(0 AS DECIMAL(19,6)) AS "Ret", CAST(0 AS DECIMAL(19,6)) AS "Adj", CAST(0 AS DECIMAL(19,6)) AS "Smp", CAST(0 AS DECIMAL(19,6)) AS "EndA"
          FROM :runs U JOIN "MTC_CA_R_GOODS_OUT_BEG" G ON G."RunId" = U."RunId" WHERE U."FcCode" = :fA
        UNION ALL
        SELECT G."ObjType", G."DocEntry", G."LineNum", G."ItemCode", 0, 0, 0, 0, 0, 0, 0, 0, G."CostAmt"
          FROM :runs U JOIN "MTC_CA_R_GOODS_OUT" G ON G."RunId" = U."RunId" WHERE U."FcCode" = :fB
        UNION ALL
        SELECT D."ObjType", D."DocEntry", D."LineNum", L."ItemCode", 0,
               CASE WHEN D."ObjType" = '15' THEN -L."Amount" ELSE 0 END, CASE WHEN D."ObjType" = '16' THEN L."Amount" ELSE 0 END, 0, 0, 0, 0, 0, 0
          FROM :runs U
          JOIN "MTC_CA_S_LINE" D ON D."RunId" = U."RunId" AND (D."ObjType" = '15' OR (D."ObjType" = '16' AND IFNULL(D."BaseType", '') <> '15'))
          JOIN "MTC_CA_R_LINE" L ON L."RunId" = D."RunId" AND L."LineId" = D."LineId"
        UNION ALL
        SELECT M."SrcObj", M."SrcEntry", M."SrcLine", NULL, 0, 0, 0,
               CASE WHEN M."K" = 'INV' THEN M."Amount" ELSE 0 END, CASE WHEN M."K" = 'RIN' THEN M."Amount" ELSE 0 END,
               CASE WHEN M."K" = 'RET' THEN M."Amount" ELSE 0 END, CASE WHEN M."K" = 'ADJ' THEN M."Amount" ELSE 0 END,
               CASE WHEN M."IsSample" = 'Y' AND M."K" <> 'RET' THEN M."Amount" ELSE 0 END, 0
          FROM :runs U JOIN "MTC_CA_R_GOODS_MOVE" M ON M."RunId" = U."RunId";
    hd = SELECT '15' AS "ObjType", D."DocEntry", D."LineNum", D."ItemCode", H."DocNum", TO_DATE(H."DocDate") AS "DocDate", H."CardCode", H."U_SalOrdType"
           FROM "ODLN" H JOIN "DLN1" D ON D."DocEntry" = H."DocEntry"
          WHERE H."DocEntry" IN (SELECT "DocEntry" FROM :f WHERE "ObjType" = '15')
         UNION ALL
         SELECT '16', D."DocEntry", D."LineNum", D."ItemCode", H."DocNum", TO_DATE(H."DocDate"), H."CardCode", H."U_SalOrdType"
           FROM "ORDN" H JOIN "RDN1" D ON D."DocEntry" = H."DocEntry"
          WHERE H."DocEntry" IN (SELECT "DocEntry" FROM :f WHERE "ObjType" = '16');
    b = SELECT F."ObjType", F."DocEntry", F."LineNum", COALESCE(H."ItemCode", MAX(F."ItemCode")) AS "ItemCode", H."DocNum", H."DocDate", H."CardCode",
               T."CustType", SUM(F."Beg") AS "Beg", SUM(F."Iss") AS "Iss", SUM(F."Ret0") AS "Ret0", SUM(F."Inv") AS "Inv", SUM(F."Rin") AS "Rin",
               SUM(F."Ret") AS "Ret", SUM(F."Adj") AS "Adj", SUM(F."Smp") AS "Smp", SUM(F."EndA") AS "EndA"
          FROM :f F
          LEFT JOIN :hd H ON H."ObjType" = F."ObjType" AND H."DocEntry" = F."DocEntry" AND H."LineNum" = F."LineNum"
          LEFT JOIN (SELECT "Name", MAX("U_CustType") AS "CustType" FROM "@MTC_SALORDTYPE" GROUP BY "Name") T ON T."Name" = H."U_SalOrdType"
         GROUP BY F."ObjType", F."DocEntry", F."LineNum", H."ItemCode", H."DocNum", H."DocDate", H."CardCode", T."CustType";
    b2 = SELECT B.*, M."ItemName", TO_NVARCHAR(M."ItmsGrpCod") AS "Grp", C."CardName"
           FROM :b B LEFT JOIN "OITM" M ON M."ItemCode" = B."ItemCode" LEFT JOIN "OCRD" C ON C."CardCode" = B."CardCode"
          WHERE (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE B."ItemCode" LIKE X."P"))
            AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
            AND (:nCust = 0 OR EXISTS (SELECT 1 FROM :lCust X WHERE B."CardCode" LIKE X."P"))
            AND (:nCt = 0 OR EXISTS (SELECT 1 FROM :lCt X WHERE B."CustType" = X."V"));
    -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
    o = SELECT "K",
               MAX(CASE :STYPE WHEN '1' THEN "CardName" ELSE "ItemName" END) AS "N",
               MAX(CASE WHEN :STYPE = '2' THEN "ObjType" END) AS "ObjType", MAX(CASE WHEN :STYPE = '2' THEN "DocNum" END) AS "DocNum",
               MAX(CASE WHEN :STYPE = '2' THEN "LineNum" END) AS "LineNum", MAX(CASE WHEN :STYPE = '2' THEN "DocDate" END) AS "DocDate",
               MAX(CASE WHEN :STYPE = '2' THEN "CardCode" END) AS "CardCode", MAX(CASE WHEN :STYPE IN ('1', '2') THEN "CustType" END) AS "CustType",
               MAX(CASE WHEN :STYPE = '2' THEN "ItemCode" END) AS "ItemCode",
               SUM("Beg") AS "Beg", SUM("Iss") AS "Iss", SUM("Ret0") AS "Ret0", SUM("Inv") AS "Inv", SUM("Rin") AS "Rin", SUM("Ret") AS "Ret",
               SUM("Adj") AS "Adj", SUM("Smp") AS "Smp", SUM("EndA") AS "EndA"
          FROM (SELECT B.*, CASE :STYPE WHEN '1' THEN B."CardCode" WHEN '2' THEN B."ObjType" || '-' || TO_NVARCHAR(B."DocEntry") || '-' || TO_NVARCHAR(B."LineNum") ELSE B."ItemCode" END AS "K"
                  FROM :b2 B)
         GROUP BY "K";
    SELECT "K" AS "代码", "N" AS "名称", "MTC_CA_F_RPT_DTNAME"("ObjType") AS "单据类型", "DocNum" AS "单号 Num", "LineNum" AS "行号", "DocDate" AS "单据日期",
           "CardCode" AS "客户", "CustType" AS "客户类型", "ItemCode" AS "物料",
           CAST("Beg" AS DECIMAL(19,2)) AS "期初发出商品", CAST("Iss" AS DECIMAL(19,2)) AS "本期·发货", CAST("Ret0" AS DECIMAL(19,2)) AS "本期·独立退货",
           CAST("Inv" AS DECIMAL(19,2)) AS "本期消耗·开票", CAST("Rin" AS DECIMAL(19,2)) AS "本期消耗·贷项", CAST("Ret" AS DECIMAL(19,2)) AS "本期消耗·基于交货退货",
           CAST("Adj" AS DECIMAL(19,2)) AS "本期消耗·尾差",
           CAST("Inv" + "Rin" + "Adj" - "Smp" AS DECIMAL(19,2)) AS "销售成本（DN03）", CAST("Smp" AS DECIMAL(19,2)) AS "样品转出",
           CAST("EndA" AS DECIMAL(19,2)) AS "期末发出商品",
           CAST("Beg" + "Iss" - "Ret0" - "Inv" - "Rin" - "Ret" - "Adj" - "EndA" AS DECIMAL(19,2)) AS "勾稽差额"
      FROM :o ORDER BY "K";
END

@@
-- @stmt 成本报表 21_reports.sql #19
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R09 存货与生产成本对账：业务端（新框架结果）与总账按对账项、科目逐项比较，期初 / 本期 / 期末分开列示。
-- 参数：Fc 账期, Acct 科目（开头匹配）, OnlyDiff 只看有差异 Y/N
-- 口径：MTC_CA_F_RECON（同执行台“财务对账”、POST-06/09/10/11/13）。财务本期 = 本期分录 + 底稿中尚未过账的凭证；手工调整单独一列。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_09_RECON" (IN Fc NVARCHAR(10), IN Acct NVARCHAR(500), IN OnlyDiff NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE nAcct INT;
    SELECT MAX("RunId") INTO rid FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    lAcct = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Acct); SELECT COUNT(*) INTO nAcct FROM :lAcct;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    r = SELECT * FROM "MTC_CA_F_RECON"(:rid);
    SELECT CASE R."Area" WHEN 'STOCK' THEN '存货' WHEN 'WIP_PROD' THEN '生产在产品' WHEN 'WW_MAT' THEN '委外材料' WHEN 'WW_FEE' THEN '委外加工费'
                         WHEN 'GOODS' THEN '发出商品' WHEN 'AP' THEN '应付暂估' ELSE R."Area" END AS "对账项",
           R."AcctCode" AS "科目", A."AcctName" AS "科目名称", R."KeyCode" AS "对象",
           R."BegBiz" AS "期初·业务", R."BegFin" AS "期初·财务", R."BegDiff" AS "期初·差额",
           R."CurBiz" AS "本期·业务", R."CurFin" AS "本期·财务", R."CurDiff" AS "本期·差额",
           R."BizAmt" AS "期末·业务", R."EndFin" AS "期末·财务", R."Diff" AS "期末·差额",
           R."OtherAmt" AS "手工调整·金额", CAST(R."Diff" + R."OtherAmt" AS DECIMAL(19,2)) AS "手工调整·总账差额（含手工）",
           CASE WHEN ABS(R."Diff" - R."BegDiff") <= 0.01 THEN 'Y' ELSE 'N' END AS "手工调整·扣除后 = 期初差额",
           CAST(R."DraftAmt" - R."DupAmt" AS DECIMAL(19,2)) AS "未过账底稿·金额", R."PendCodes" AS "未过账底稿·凭证代码"
      FROM :r R LEFT JOIN "OACT" A ON A."AcctCode" = R."AcctCode"
     WHERE (:nAcct = 0 OR EXISTS (SELECT 1 FROM :lAcct X WHERE R."AcctCode" LIKE X."P"))
       AND (IFNULL(:OnlyDiff, 'N') <> 'Y' OR ABS(R."CurDiff") > 0.01 OR ABS(R."Diff") > 0.01)
     ORDER BY CASE R."Area" WHEN 'STOCK' THEN 1 WHEN 'WIP_PROD' THEN 2 WHEN 'WW_MAT' THEN 3 WHEN 'WW_FEE' THEN 4 WHEN 'GOODS' THEN 5 ELSE 6 END,
              R."AcctCode", R."KeyCode";
END

@@
-- @stmt 成本报表 21_reports.sql #20
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R10 成本凭证清单及来源：本期成本模块生成的凭证（每种凭证代码一张）、分录、每笔分录的业务来源。
-- 参数：Fc 账期, TransCode 凭证代码, Acct 科目（开头匹配）, STYPE 0 按凭证代码（含 B1 凭单批号和状态）/ 1 分录 / 2 来源明细
-- 口径：MTC_CA_R_JDT / R_JDT_SRC（凭证底稿）、MTC_CA_JV（已生成的 B1 日记账凭单）。来源明细金额正 = 借、负 = 贷。
-- 勾稽：来源明细合计 = 分录合计（V06）。
-- 列名：凭证代码、科目编码这两列输出英文字段名 TransCode、AcctCode（用户 2026-11-07，这张报表特殊），执行台按 rpt_defs.json 的 alias 显示中文。
-- 运行号 = 这张报表取数的成本运行（MTC_CA_RUN.RunId，规则同 R00），三种显示方式都有；分录号 = R_JDT.LineNo（凭证代码内的行号），分录、来源明细都有，
--   来源明细按分录号排，同一分录号的来源合计 = 该分录金额（用户 2026-11-11）。
-- 交易号 TransId / 凭证编号 Number / B1 行号 Line_ID：凭单过账后 B1 日记账分录的编号（按 MTC_CA_JV 批号找 OJDT，行按分录号 − 1 并核对科目、金额），待过账时为空（用户 2026-11-11）。
-- 财务凭证号 U_CWNum：同一张 OJDT 的自定义字段 OJDT.U_CWNum，跟交易号同时显示，待过账为空（用户 2026-11-11）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_10_JV" (IN Fc NVARCHAR(10), IN TransCode NVARCHAR(500), IN Acct NVARCHAR(500), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE fc NVARCHAR(10); DECLARE nTc INT; DECLARE nAcct INT;
    SELECT MAX("RunId"), MAX("FcCode") INTO rid, fc FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    lTc   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:TransCode); SELECT COUNT(*) INTO nTc FROM :lTc;
    lAcct = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Acct);      SELECT COUNT(*) INTO nAcct FROM :lAcct;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    -- B1 交易号（用户 2026-11-11）：MTC_CA_JV 最新已生成的凭单批号 → 过账后的 OJDT（同 BatchNum、TransCode；不含 B1 自动冲销的 StornoToTr 凭证）；
    --   待过账、已在 B1 删除的没有。行：执行台按分录号顺序写凭单，Line_ID = 分录号 − 1，再核对科目（FormatCode 换 AcctCode，同 dev_server SQL_JV_LINES）
    --   和借 − 贷金额，对不上的留空
    jv = SELECT G."TransCode", G."BatchNum", MAX(H."TransId") AS "TransId", MAX(H."Number") AS "Number", MAX(H."U_CWNum") AS "U_CWNum"
           FROM (SELECT "TransCode", MAX("BatchNum") AS "BatchNum" FROM "MTC_CA_JV"
                  WHERE "FcCode" = :fc AND "RunId" = :rid AND "Status" = 'CREATED' AND "BatchNum" IS NOT NULL GROUP BY "TransCode") G
           LEFT JOIN "OJDT" H ON H."BatchNum" = G."BatchNum" AND H."TransCode" = G."TransCode" AND H."StornoToTr" IS NULL
          GROUP BY G."TransCode", G."BatchNum";
    jl = SELECT J."TransCode", J."LineNo", L."TransId", L."Line_ID", V."U_CWNum"
           FROM :jv V
           JOIN "MTC_CA_R_JDT" J ON J."RunId" = :rid AND J."TransCode" = V."TransCode"
           LEFT JOIN "OACT" A1 ON A1."AcctCode" = J."AcctCode"
           LEFT JOIN (SELECT "FormatCode", MAX("AcctCode") AS "AcctCode" FROM "OACT" WHERE IFNULL("FormatCode", '') <> '' GROUP BY "FormatCode") A2
             ON A1."AcctCode" IS NULL AND A2."FormatCode" = J."AcctCode"
           JOIN "JDT1" L ON L."TransId" = V."TransId" AND L."Line_ID" = J."LineNo" - 1
                        AND L."Account" = IFNULL(A1."AcctCode", A2."AcctCode") AND L."Debit" - L."Credit" = J."Debit" - J."Credit";
    IF :STYPE = '2' THEN
        SELECT :fc AS "FcCode", :rid AS "运行号", S."TransCode" AS "TransCode", J."LineNo" AS "分录号", X."TransId" AS "交易号 TransId", X."U_CWNum" AS "财务凭证号 U_CWNum", X."Line_ID" AS "B1 行号 Line_ID", S."AcctCode" AS "AcctCode", A."AcctName" AS "科目名称", S."OcrCode" AS "成本中心", S."VendorCode" AS "供应商",
               CASE S."SrcType" WHEN 'LINE' THEN '单据行' WHEN 'ORDER' THEN '订单' WHEN 'DOC' THEN 'B1 单据行' WHEN 'GL' THEN '总账分录' WHEN 'OMRV' THEN '重估单'
                                WHEN 'ITEM' THEN '物料尾差' ELSE S."SrcType" END AS "来源类型",
               S."SrcKey" AS "来源键",
               CAST(CASE WHEN S."Amount" > 0 THEN S."Amount" ELSE 0 END AS DECIMAL(19,2)) AS "借方",
               CAST(CASE WHEN S."Amount" < 0 THEN -S."Amount" ELSE 0 END AS DECIMAL(19,2)) AS "贷方",
               COALESCE(D."DocDate", CAST(NULL AS DATE)) AS "单据日期",
               "MTC_CA_F_RPT_DTNAME"(COALESCE(D."ObjType", O."OrderType")) AS "单据类型", COALESCE(D."DocNum", O."OrderNum") AS "单号 Num", D."LineNum" AS "行号",
               COALESCE(L."ItemCode", O."ItemCode") AS "物料", L."TransCode" AS "交易类型", CAST(L."Qty" AS DECIMAL(19,6)) AS "数量",
               LO."OrderNum" AS "订单号 Num", S."Note" AS "备注"
          FROM "MTC_CA_R_JDT_SRC" S
          LEFT JOIN "MTC_CA_R_LINE" L ON S."SrcType" = 'LINE' AND L."RunId" = S."RunId"
                                     AND L."LineId" = CASE WHEN S."SrcKey" LIKE_REGEXPR '^[0-9]+$' THEN TO_BIGINT(S."SrcKey") END
          LEFT JOIN "MTC_CA_S_LINE" D ON D."RunId" = L."RunId" AND D."LineId" = L."LineId"
          LEFT JOIN "MTC_CA_S_ORDER" LO ON LO."RunId" = L."RunId" AND LO."OrderType" = L."OrderType" AND LO."OrderEntry" = L."OrderEntry"
          LEFT JOIN "MTC_CA_S_ORDER" O ON S."SrcType" = 'ORDER' AND O."RunId" = S."RunId" AND O."OrderType" || '-' || TO_NVARCHAR(O."OrderEntry") = S."SrcKey"
          LEFT JOIN "OACT" A ON A."AcctCode" = S."AcctCode"
          -- 分录号：R_JDT 由 R_JDT_SRC 按 凭证代码 + 科目 + 成本中心 + 项目 + 供应商 汇总（P70，空串当 NULL），同样的键找回；这组来源合计为 0 时没有分录，分录号为空
          LEFT JOIN "MTC_CA_R_JDT" J ON J."RunId" = S."RunId" AND J."TransCode" = S."TransCode" AND IFNULL(J."AcctCode", '') = IFNULL(S."AcctCode", '')
                                    AND IFNULL(J."OcrCode", '') = IFNULL(S."OcrCode", '') AND IFNULL(J."Project", '') = IFNULL(S."Project", '')
                                    AND IFNULL(J."VendorCode", '') = IFNULL(S."VendorCode", '')
          LEFT JOIN :jl X ON X."TransCode" = J."TransCode" AND X."LineNo" = J."LineNo"
         WHERE S."RunId" = :rid
           AND (:nTc = 0 OR EXISTS (SELECT 1 FROM :lTc X WHERE S."TransCode" = X."V"))
           AND (:nAcct = 0 OR EXISTS (SELECT 1 FROM :lAcct X WHERE S."AcctCode" LIKE X."P"))
         ORDER BY S."TransCode", J."LineNo", S."AcctCode", S."OcrCode", S."SrcId";
    ELSEIF :STYPE = '1' THEN
        SELECT :fc AS "FcCode", :rid AS "运行号", J."TransCode" AS "TransCode", J."TransName" AS "凭证名称", J."LineNo" AS "分录号", X."TransId" AS "交易号 TransId", X."U_CWNum" AS "财务凭证号 U_CWNum", X."Line_ID" AS "B1 行号 Line_ID", J."RefDate" AS "过账日期", J."AcctCode" AS "AcctCode", A."AcctName" AS "科目名称",
               J."OcrCode" AS "成本中心", J."Project" AS "项目", J."VendorCode" AS "供应商", J."Debit" AS "借方", J."Credit" AS "贷方"
          FROM "MTC_CA_R_JDT" J LEFT JOIN "OACT" A ON A."AcctCode" = J."AcctCode"
          LEFT JOIN :jl X ON X."TransCode" = J."TransCode" AND X."LineNo" = J."LineNo"
         WHERE J."RunId" = :rid
           AND (:nTc = 0 OR EXISTS (SELECT 1 FROM :lTc X WHERE J."TransCode" = X."V"))
           AND (:nAcct = 0 OR EXISTS (SELECT 1 FROM :lAcct X WHERE J."AcctCode" LIKE X."P"))
         ORDER BY J."TransCode", J."LineNo";
    ELSE
        SELECT :fc AS "FcCode", :rid AS "运行号", J."TransCode" AS "TransCode", MAX(IFNULL(T."TrnsCodDsc", J."TransName")) AS "凭证名称", COUNT(*) AS "分录行数",
               SUM(J."Debit") AS "借方", SUM(J."Credit") AS "贷方", CAST(SUM(J."Debit") - SUM(J."Credit") AS DECIMAL(19,2)) AS "借贷差",
               MAX(V."BatchNum") AS "凭单批号", IFNULL(MAX(V."B1State"), '未生成凭单') AS "B1 状态",
               MAX(X."TransId") AS "交易号 TransId", MAX(X."Number") AS "凭证编号 Number", MAX(X."U_CWNum") AS "财务凭证号 U_CWNum",
               MAX(V."CreateUser") AS "生成人", MAX(V."CreateTime") AS "生成时间"
          FROM "MTC_CA_R_JDT" J
          LEFT JOIN "OTRC" T ON T."TrnsCode" = J."TransCode"
          LEFT JOIN (SELECT G."TransCode", G."BatchNum", G."CreateUser", G."CreateTime",
                            CASE WHEN EXISTS (SELECT 1 FROM "OBTF" B WHERE B."BatchNum" = G."BatchNum" AND B."BtfStatus" = 'O') THEN '待过账'
                                 WHEN EXISTS (SELECT 1 FROM "OJDT" H WHERE H."BatchNum" = G."BatchNum") THEN '已过账' ELSE '已在 B1 删除' END AS "B1State"
                       FROM (SELECT "TransCode", MAX("BatchNum") AS "BatchNum", MAX("CreateUser") AS "CreateUser", MAX("CreateTime") AS "CreateTime"
                               FROM "MTC_CA_JV" WHERE "FcCode" = :fc AND "RunId" = :rid AND "Status" = 'CREATED' AND "BatchNum" IS NOT NULL
                              GROUP BY "TransCode") G) V ON V."TransCode" = J."TransCode"
          LEFT JOIN :jv X ON X."TransCode" = J."TransCode"
         WHERE J."RunId" = :rid
           AND (:nTc = 0 OR EXISTS (SELECT 1 FROM :lTc X WHERE J."TransCode" = X."V"))
           AND (:nAcct = 0 OR EXISTS (SELECT 1 FROM :lAcct X WHERE J."AcctCode" LIKE X."P"))
         GROUP BY J."TransCode" ORDER BY J."TransCode";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #21
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R11 成本异常清单：本期需要人看一眼的物料、订单、费用池和校验项。
-- 参数：Fc 账期, Cat 类别（FLAG 物料标记 / STOCK 期末异常 / PRICE 单价变动 / ORDER 订单 / POOL 费用池 / CHECK 校验）,
--       PricePct 单价变动阈值 %（默认 20）, AmtMin 金额阈值（关单差异绝对值超过它才列，默认 0）
-- 口径：R_ITEM.Flags（负库存 / 兜底价 / 无价 / 尾差无处挤）；期末数量为负、数量为 0 金额不为 0、金额为负；单价（四项合计）与上期最近一次
--       成功正式运行相比变动超过阈值；订单本期有完工但单位成本 ≤ 0、期末在产品为负、关单差异；费用池未分配完；计算后校验不通过或警告（含人工确认）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_11_EXCEPT" (IN Fc NVARCHAR(10), IN Cat NVARCHAR(100), IN PricePct NVARCHAR(20), IN AmtMin NVARCHAR(30))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE pfc NVARCHAR(10); DECLARE prid BIGINT; DECLARE nCat INT;
    DECLARE th DECIMAL(19,6) := TO_DECIMAL(IFNULL(NULLIF(TRIM(:PricePct), ''), '20'), 19, 6);
    DECLARE am DECIMAL(19,6) := TO_DECIMAL(IFNULL(NULLIF(TRIM(:AmtMin), ''), '0'), 19, 6);
    -- 历史期（旧框架回填）没有计算前后校验和异常的结果（报表合并第一阶段不回填，2026-11-02）
    IF "MTC_CA_F_RPT_HISTONLY"(:Fc, :Fc) = 'Y' THEN
        SELECT '历史期（旧框架回填）没有这张报表的数据：旧框架没有保存计算前后校验和异常的明细结果，请用旧报表查看' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    SELECT MAX("RunId"), MAX("PrevFc") INTO rid, pfc FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    SELECT MAX("RunId") INTO prid FROM "MTC_CA_F_RPT_RUN"(:pfc, :pfc);
    lCat = SELECT UPPER("V") AS "V" FROM "MTC_CA_F_RPT_LIST"(:Cat); SELECT COUNT(*) INTO nCat FROM :lCat;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    x = SELECT CAST('FLAG' AS NVARCHAR(10)) AS "C", 1 AS "S", CAST(R."ItemCode" AS NVARCHAR(200)) AS "K", CAST(R."Flags" AS NVARCHAR(2000)) AS "Msg", R."EndAmount" AS "V1", CAST(NULL AS DECIMAL(19,6)) AS "V0", R."EndAmount" AS "Amt"
          FROM "MTC_CA_R_ITEM" R WHERE R."RunId" = :rid AND IFNULL(R."Flags", '') <> ''
        UNION ALL
        SELECT 'STOCK', 2, R."ItemCode",
               CASE WHEN R."EndQty" < 0 THEN '期末数量为负' WHEN R."EndQty" = 0 THEN '期末数量为 0、金额不为 0' ELSE '期末金额为负' END,
               R."EndQty", NULL, R."EndAmount"
          FROM "MTC_CA_R_ITEM" R
         WHERE R."RunId" = :rid AND (R."EndQty" < 0 OR (R."EndQty" = 0 AND ABS(R."EndAmount") > 0.005) OR (R."EndQty" > 0 AND R."EndAmount" < 0))
        UNION ALL
        SELECT 'PRICE', 3, C."ItemCode", '单价比上期变动超过 ' || TO_NVARCHAR(:th) || '%',
               C."PMat" + C."PMfg" + C."PLab" + C."PSub", P."PMat" + P."PMfg" + P."PLab" + P."PSub",
               (C."PMat" + C."PMfg" + C."PLab" + C."PSub" - P."PMat" - P."PMfg" - P."PLab" - P."PSub") * C."EndQty"
          FROM "MTC_CA_R_ITEM" C JOIN "MTC_CA_R_ITEM" P ON P."RunId" = :prid AND P."ItemCode" = C."ItemCode"
         WHERE C."RunId" = :rid AND P."PMat" + P."PMfg" + P."PLab" + P."PSub" > 0 AND C."PMat" + C."PMfg" + C."PLab" + C."PSub" > 0
           AND (C."InQty" <> 0 OR C."OutQty" <> 0)
           AND ABS(C."PMat" + C."PMfg" + C."PLab" + C."PSub" - P."PMat" - P."PMfg" - P."PLab" - P."PSub") * 100
               > :th * (P."PMat" + P."PMfg" + P."PLab" + P."PSub")
        UNION ALL
        SELECT 'ORDER', 4, O."OrderType" || '-' || IFNULL(S."OrderNum", TO_NVARCHAR(O."OrderEntry")),
               CASE WHEN O."RecvQty" > 0 AND IFNULL(O."UnitCost", 0) <= 0 THEN '本期有完工，单位成本 ≤ 0'
                    WHEN O."WipAmt" < -0.005 THEN '期末在产品为负' ELSE '本期关单差异' END,
               CASE WHEN O."RecvQty" > 0 AND IFNULL(O."UnitCost", 0) <= 0 THEN O."UnitCost" WHEN O."WipAmt" < -0.005 THEN O."WipAmt" ELSE O."CloseDifAmt" END,
               NULL, CASE WHEN O."WipAmt" < -0.005 THEN O."WipAmt" WHEN O."RecvQty" > 0 AND IFNULL(O."UnitCost", 0) <= 0 THEN O."CostAmt" ELSE O."CloseDifAmt" END
          FROM "MTC_CA_R_ORDER" O
          LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
         WHERE O."RunId" = :rid
           AND ((O."RecvQty" > 0 AND IFNULL(O."UnitCost", 0) <= 0) OR O."WipAmt" < -0.005 OR (O."CloseDifAmt" <> 0 AND ABS(O."CloseDifAmt") > :am))
        UNION ALL
        SELECT 'POOL', 5, P."PoolCode" || ' ' || P."Elem", '费用池未分配完', P."Amt", A."Amt", P."Amt" - IFNULL(A."Amt", 0)
          FROM (SELECT "PoolCode", "Elem", SUM("Amount") AS "Amt" FROM "MTC_CA_R_POOL" WHERE "RunId" = :rid GROUP BY "PoolCode", "Elem") P
          LEFT JOIN (SELECT "PoolCode", "Elem", SUM("Amount") AS "Amt" FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :rid GROUP BY "PoolCode", "Elem") A
                 ON A."PoolCode" = P."PoolCode" AND A."Elem" = P."Elem"
         WHERE ABS(P."Amt" - IFNULL(A."Amt", 0)) > 0.005
        UNION ALL
        SELECT 'CHECK', 6, K."CheckId", IFNULL(C."Title", '') || '：' || IFNULL(K."Msg", '')
                 || CASE WHEN A."UserCode" IS NOT NULL THEN '（已确认：' || A."UserCode" || '，' || A."Reason" || '）' ELSE '' END,
               K."IssueCnt", NULL, NULL
          FROM "MTC_CA_R_CHECK" K
          LEFT JOIN "MTC_CA_C_CHECK" C ON C."CheckId" = K."CheckId"
          LEFT JOIN "MTC_CA_CHECK_ACK" A ON A."RunId" = K."RunId" AND A."CheckId" = K."CheckId"
         WHERE K."RunId" = :rid AND K."Result" IN ('FAIL', 'WARN');
    SELECT CASE X."C" WHEN 'FLAG' THEN '物料标记' WHEN 'STOCK' THEN '期末异常' WHEN 'PRICE' THEN '单价变动' WHEN 'ORDER' THEN '订单'
                      WHEN 'POOL' THEN '费用池' ELSE '校验' END AS "类别",
           X."C" AS "类别代码", X."K" AS "对象", COALESCE(M."ItemName", PL."PoolName") AS "名称", X."Msg" AS "说明",
           CAST(X."V1" AS DECIMAL(19,6)) AS "本期值", CAST(X."V0" AS DECIMAL(19,6)) AS "上期值",
           CAST(CASE WHEN X."C" = 'PRICE' THEN (X."V1" - X."V0") * 100 / NULLIF(X."V0", 0) END AS DECIMAL(19,2)) AS "变动 %",
           CAST(X."Amt" AS DECIMAL(19,2)) AS "影响金额"
      FROM :x X
      LEFT JOIN "OITM" M ON X."C" IN ('FLAG', 'STOCK', 'PRICE') AND M."ItemCode" = X."K"
      LEFT JOIN "MTC_CA_C_POOL" PL ON X."C" = 'POOL' AND PL."PoolCode" = SUBSTR_BEFORE(X."K", ' ')
     WHERE :nCat = 0 OR EXISTS (SELECT 1 FROM :lCat L WHERE L."V" = X."C")
     ORDER BY X."S", ABS(IFNULL(X."Amt", 0)) DESC, X."K";
END

@@
-- @stmt 成本报表 21_reports.sql #22
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R17 应付暂估（已收货未开票，含退货）：截至期末未清的收货行（扣已开票、扣基于收货的退货）和不基于收货的退货（为负）。
-- 参数：Fc 账期, Vendor 供应商, AccrType 暂估类型（MAT 材料 / SUBFEE 委外加工费，也认中文）, Item 物料, ItemGrp 物料组, DocNum 收货单号 Num,
--       AgeDays 账龄 ≥ 天数, STYPE 0 按供应商（含账龄分段）/ 1 供应商 × 物料 / 2 单据行 / 3 本期变动 / 4 与总账 220202 按供应商核对
-- 口径：MTC_CA_R_AP_ACCR（截至期末未清）、MTC_CA_S_AP_MOVE（每笔变动对 220202 贷方余额的影响），与 PUR1–PUR5 凭证取自同一次运行；
--       暂估单价：U_InitPrice ≠ 0 → 指定单价；U_IsPrice = Y → 已确认价；否则 LineTotal ÷ 数量。账龄 = 期末日 − 收货日期。
-- 勾稽：未清合计 = R09 应付暂估业务端 = reports/MTC_RPT_FI5005_V2 截至期末合计；STYPE 3 期初 + 变动 = 期末（V07、V08）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_17_APACCR" (
    IN Fc NVARCHAR(10), IN Vendor NVARCHAR(5000), IN AccrType NVARCHAR(20), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000),
    IN DocNum NVARCHAR(5000), IN AgeDays NVARCHAR(10), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE d0 DATE; DECLARE d1 DATE; DECLARE nVen INT; DECLARE nItem INT; DECLARE nGrp INT; DECLARE nDoc INT;
    DECLARE aty NVARCHAR(10) := CASE WHEN :AccrType IN ('MAT', '材料') THEN 'MAT' WHEN :AccrType IN ('SUBFEE', '委外加工费', '加工费') THEN 'SUBFEE' ELSE '' END;
    DECLARE age INT := TO_INTEGER(IFNULL(NULLIF(TRIM(:AgeDays), ''), '0'));
    -- 历史期（旧框架回填）没有应付暂估的结果（报表合并第一阶段不回填，2026-11-02）
    IF "MTC_CA_F_RPT_HISTONLY"(:Fc, :Fc) = 'Y' THEN
        SELECT '历史期（旧框架回填）没有这张报表的数据：旧框架没有保存应付暂估的明细结果，请用旧报表查看' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    SELECT MAX("RunId"), MAX("D0"), MAX("D1") INTO rid, d0, d1 FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    lVen  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Vendor);  SELECT COUNT(*) INTO nVen FROM :lVen;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lDoc  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:DocNum);  SELECT COUNT(*) INTO nDoc FROM :lDoc;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    IF :STYPE = '3' THEN
        mv3 = SELECT M.* FROM "MTC_CA_S_AP_MOVE" M LEFT JOIN "OITM" I ON I."ItemCode" = M."ItemCode"
              WHERE M."RunId" = :rid AND M."DocDate" <= :d1
                AND (:aty = '' OR M."AccrType" = :aty)
                AND (:nVen = 0 OR EXISTS (SELECT 1 FROM :lVen X WHERE M."CardCode" LIKE X."P"))
                AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE M."ItemCode" LIKE X."P"))
                AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"));
        o3 = SELECT IFNULL(M."CardCode", '') AS "CardCode",
                   SUM(CASE WHEN M."DocDate" < :d0 THEN M."AccrAmt" ELSE 0 END) AS "Beg",
                   SUM(CASE WHEN M."DocDate" >= :d0 AND M."IsCancel" = 'N' AND M."MoveType" = 'ACCR' AND M."BaseObj" = '20' THEN M."AccrAmt" ELSE 0 END) AS "Rcv",
                   SUM(CASE WHEN M."DocDate" >= :d0 AND M."IsCancel" = 'N' AND M."MoveType" = 'ACCR' AND M."BaseObj" = '21' THEN M."AccrAmt" ELSE 0 END) AS "Ret0",
                   SUM(CASE WHEN M."DocDate" >= :d0 AND M."IsCancel" = 'N' AND M."MoveType" = 'RET' THEN M."AccrAmt" ELSE 0 END) AS "Ret",
                   SUM(CASE WHEN M."DocDate" >= :d0 AND M."IsCancel" = 'N' AND M."MoveType" = 'INV' THEN M."AccrAmt" ELSE 0 END) AS "Inv",
                   SUM(CASE WHEN M."DocDate" >= :d0 AND M."IsCancel" = 'Y' THEN M."AccrAmt" ELSE 0 END) AS "Cnl",
                   SUM(M."AccrAmt") AS "EndA"
              FROM :mv3 M GROUP BY IFNULL(M."CardCode", '');
        acc3 = SELECT IFNULL(A."CardCode", '') AS "CardCode", SUM(A."OpenAmt") AS "Amt"
                FROM "MTC_CA_R_AP_ACCR" A LEFT JOIN "OITM" I ON I."ItemCode" = A."ItemCode"
               WHERE A."RunId" = :rid AND (:aty = '' OR A."AccrType" = :aty)
                 AND (:nVen = 0 OR EXISTS (SELECT 1 FROM :lVen X WHERE A."CardCode" LIKE X."P"))
                 AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE A."ItemCode" LIKE X."P"))
                 AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"))
               GROUP BY IFNULL(A."CardCode", '');
        SELECT O."CardCode" AS "供应商", C."CardName" AS "供应商名称",
               CAST(O."Beg" AS DECIMAL(19,2)) AS "期初未清", CAST(O."Rcv" AS DECIMAL(19,2)) AS "本期·收货暂估", CAST(O."Ret0" AS DECIMAL(19,2)) AS "本期·独立退货",
               CAST(O."Ret" AS DECIMAL(19,2)) AS "本期·基于收货退货", CAST(O."Inv" AS DECIMAL(19,2)) AS "本期·开票冲回", CAST(O."Cnl" AS DECIMAL(19,2)) AS "本期·取消单",
               CAST(O."EndA" AS DECIMAL(19,2)) AS "期末未清", CAST(IFNULL(A."Amt", 0) AS DECIMAL(19,2)) AS "期末未清（逐行）",
               CAST(O."EndA" - IFNULL(A."Amt", 0) AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :o3 O LEFT JOIN :acc3 A ON A."CardCode" = O."CardCode" LEFT JOIN "OCRD" C ON C."CardCode" = O."CardCode"
         WHERE O."Beg" <> 0 OR O."EndA" <> 0 OR O."Rcv" <> 0 OR O."Ret0" <> 0 OR O."Ret" <> 0 OR O."Inv" <> 0 OR O."Cnl" <> 0 OR IFNULL(A."Amt", 0) <> 0
         ORDER BY O."CardCode";
        RETURN;
    END IF;
    IF :STYPE = '4' THEN
        acc4 = SELECT IFNULL("CardCode", '') AS "CardCode", SUM("OpenAmt") AS "Amt" FROM "MTC_CA_R_AP_ACCR" WHERE "RunId" = :rid GROUP BY IFNULL("CardCode", '');
        rc4 = SELECT IFNULL("KeyCode", '') AS "CardCode", SUM("BizAmt") AS "Biz", SUM("EndFin") AS "Fin", SUM("Diff") AS "Diff", SUM("CurDiff") AS "CurDiff"
               FROM "MTC_CA_F_RECON"(:rid) WHERE "Area" = 'AP' GROUP BY IFNULL("KeyCode", '');
        k4 = SELECT "CardCode" FROM :acc4 UNION SELECT "CardCode" FROM :rc4;
        SELECT K."CardCode" AS "供应商", C."CardName" AS "供应商名称",
               CAST(IFNULL(A."Amt", 0) AS DECIMAL(19,2)) AS "报表未清合计", CAST(IFNULL(R."Biz", 0) AS DECIMAL(19,2)) AS "对账·业务端",
               CAST(IFNULL(R."Fin", 0) AS DECIMAL(19,2)) AS "对账·总账 220202", CAST(IFNULL(R."Diff", 0) AS DECIMAL(19,2)) AS "对账·期末差额",
               CAST(IFNULL(R."CurDiff", 0) AS DECIMAL(19,2)) AS "对账·本期差额",
               CAST(IFNULL(A."Amt", 0) - IFNULL(R."Biz", 0) AS DECIMAL(19,2)) AS "报表 − 业务端"
          FROM :k4 K LEFT JOIN :acc4 A ON A."CardCode" = K."CardCode" LEFT JOIN :rc4 R ON R."CardCode" = K."CardCode"
          LEFT JOIN "OCRD" C ON C."CardCode" = K."CardCode"
         WHERE (:nVen = 0 OR EXISTS (SELECT 1 FROM :lVen X WHERE K."CardCode" LIKE X."P"))
         ORDER BY ABS(IFNULL(R."Diff", 0)) DESC, K."CardCode";
        RETURN;
    END IF;
    lnx = SELECT A."ObjType", A."DocEntry", A."LineNum", COALESCE(P."DocNum", R."DocNum") AS "DocNum", A."DocDate", A."CardCode", A."AccrType", A."ItemCode",
                COALESCE(PL."Dscription", RL."Dscription") AS "Dscription", TO_NVARCHAR(I."ItmsGrpCod") AS "Grp",
                A."DocQty", A."InvQty", A."RetQty", A."OpenQty", A."UnitPrice", A."OpenAmt",
                CASE WHEN IFNULL(COALESCE(PL."U_InitPrice", RL."U_InitPrice"), 0) <> 0 THEN '指定单价 U_InitPrice'
                     WHEN COALESCE(PL."U_IsPrice", RL."U_IsPrice") = 'Y' THEN '已确认价' ELSE '行金额 ÷ 数量' END AS "PriceSrc",
                DAYS_BETWEEN(A."DocDate", :d1) AS "Age"
           FROM "MTC_CA_R_AP_ACCR" A
           LEFT JOIN "OPDN" P ON A."ObjType" = '20' AND P."DocEntry" = A."DocEntry"
           LEFT JOIN "PDN1" PL ON A."ObjType" = '20' AND PL."DocEntry" = A."DocEntry" AND PL."LineNum" = A."LineNum"
           LEFT JOIN "ORPD" R ON A."ObjType" = '21' AND R."DocEntry" = A."DocEntry"
           LEFT JOIN "RPD1" RL ON A."ObjType" = '21' AND RL."DocEntry" = A."DocEntry" AND RL."LineNum" = A."LineNum"
           LEFT JOIN "OITM" I ON I."ItemCode" = A."ItemCode"
          WHERE A."RunId" = :rid AND (:aty = '' OR A."AccrType" = :aty)
            AND (:nVen = 0 OR EXISTS (SELECT 1 FROM :lVen X WHERE A."CardCode" LIKE X."P"))
            AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE A."ItemCode" LIKE X."P"))
            AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"))
            AND (:nDoc = 0 OR EXISTS (SELECT 1 FROM :lDoc X WHERE TO_NVARCHAR(COALESCE(P."DocNum", R."DocNum")) LIKE X."P"))
            AND DAYS_BETWEEN(A."DocDate", :d1) >= :age;
    IF :STYPE = '2' THEN
        SELECT L."CardCode" AS "供应商", C."CardName" AS "供应商名称", CASE L."ObjType" WHEN '20' THEN '收货' ELSE '退货' END AS "单据",
               L."DocNum" AS "单号 Num", L."DocEntry" AS "单号 Entry", L."LineNum" AS "行号", L."DocDate" AS "收货日期", L."Age" AS "账龄天数",
               CASE L."AccrType" WHEN 'SUBFEE' THEN '委外加工费' ELSE '材料' END AS "暂估类型", L."ItemCode" AS "物料", L."Dscription" AS "物料描述",
               CAST(L."DocQty" AS DECIMAL(19,6)) AS "收货数量", CAST(L."InvQty" AS DECIMAL(19,6)) AS "已开票数量", CAST(L."RetQty" AS DECIMAL(19,6)) AS "已退货数量",
               CAST(L."OpenQty" AS DECIMAL(19,6)) AS "未清数量", CAST(L."UnitPrice" AS DECIMAL(19,6)) AS "暂估单价", L."PriceSrc" AS "暂估单价来源",
               CAST(L."OpenAmt" AS DECIMAL(19,2)) AS "未清金额"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         ORDER BY L."CardCode", L."DocDate", L."DocEntry", L."LineNum";
    ELSEIF :STYPE = '1' THEN
        SELECT L."CardCode" AS "供应商", MAX(C."CardName") AS "供应商名称", L."ItemCode" AS "物料", MAX(L."Dscription") AS "物料描述",
               COUNT(*) AS "行数", CAST(SUM(L."OpenQty") AS DECIMAL(19,6)) AS "未清数量", CAST(SUM(L."OpenAmt") AS DECIMAL(19,2)) AS "未清金额",
               MIN(L."DocDate") AS "最早收货日期", MAX(L."Age") AS "最长账龄天数"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         GROUP BY L."CardCode", L."ItemCode" ORDER BY L."CardCode", L."ItemCode";
    ELSE
        SELECT L."CardCode" AS "供应商", MAX(C."CardName") AS "供应商名称", COUNT(*) AS "行数",
               CAST(SUM(L."OpenAmt") AS DECIMAL(19,2)) AS "未清金额",
               CAST(SUM(CASE WHEN L."Age" <= 30 THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄·30 天内",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 31 AND 60 THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄·31–60 天",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 61 AND 90 THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄·61–90 天",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 91 AND 180 THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄·91–180 天",
               CAST(SUM(CASE WHEN L."Age" > 180 THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄·180 天以上",
               CAST(SUM(CASE WHEN L."AccrType" = 'SUBFEE' THEN L."OpenAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "其中委外加工费",
               MIN(L."DocDate") AS "最早收货日期"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         GROUP BY L."CardCode" ORDER BY L."CardCode";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #23
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R18 发出商品明细（已发货未开票，含退货）：截至期末未开票的交货行（扣已开票、扣基于交货的退货）和不基于交货的退货（为负）。
-- 参数：Fc 账期, Cust 客户, CustType 客户类型（U_CustType）, SalType 销售订单类型（@MTC_SALORDTYPE.Name）, Item 物料, ItemGrp 物料组,
--       DocNum 交货单号 Num, Sample 样品（空 全部 / Y 只看样品 / N 排除样品）, AgeDays 账龄 ≥ 天数,
--       STYPE 0 按客户（含账龄分段）/ 1 客户 × 物料 / 2 单据行 / 3 本期变动 / 4 与 AR03 / AR04 计提核对
-- 口径：MTC_CA_R_GOODS_OUT（期末）/ R_GOODS_OUT_BEG（期初）/ R_GOODS_MOVE（本期消耗）、R_DNCOST（单位成本）、R_JDT（AR03 国内 / AR04 国外，
--       参数 CUST_DOM / CUST_EXP）；未开票销售金额 = 行金额 ÷ 数量 × 未清数量。账龄 = 期末日 − 交货日期。
-- 勾稽：未清成本合计 = AR03 + AR04 计提（STYPE 4）；STYPE 3 期初 + 变动 = 期末（V09、V10）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_18_GOODSOUT" (
    IN Fc NVARCHAR(10), IN Cust NVARCHAR(5000), IN CustType NVARCHAR(200), IN SalType NVARCHAR(500), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000),
    IN DocNum NVARCHAR(5000), IN Sample NVARCHAR(1), IN AgeDays NVARCHAR(10), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE fc NVARCHAR(10); DECLARE d1 DATE; DECLARE nCust INT; DECLARE nCt INT; DECLARE nSt INT; DECLARE nItem INT; DECLARE nGrp INT; DECLARE nDoc INT;
    DECLARE goods NVARCHAR(15); DECLARE cDom NVARCHAR(50); DECLARE cExp NVARCHAR(50);
    DECLARE age INT := TO_INTEGER(IFNULL(NULLIF(TRIM(:AgeDays), ''), '0'));
    -- 历史期（旧框架回填）没有发出商品的结果（报表合并第一阶段不回填，2026-11-02）
    IF "MTC_CA_F_RPT_HISTONLY"(:Fc, :Fc) = 'Y' THEN
        SELECT '历史期（旧框架回填）没有这张报表的数据：旧框架没有保存发出商品的明细结果，请用旧报表查看' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    SELECT MAX("RunId"), MAX("FcCode"), MAX("D1") INTO rid, fc, d1 FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    lCust = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Cust);     SELECT COUNT(*) INTO nCust FROM :lCust;
    lCt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:CustType); SELECT COUNT(*) INTO nCt FROM :lCt;
    lSt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:SalType);  SELECT COUNT(*) INTO nSt FROM :lSt;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lDoc  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:DocNum);   SELECT COUNT(*) INTO nDoc FROM :lDoc;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    goods := "MTC_CA_F_ACCT"('GOODS_ISSUED', :fc);
    cDom := IFNULL("MTC_CA_F_PARAM"('CUST_DOM', :fc), '国内客户');
    cExp := IFNULL("MTC_CA_F_PARAM"('CUST_EXP', :fc), '国外客户');
    -- 交货 / 退货行的表头信息（期初、期末、本期消耗和本期新增的行都可能用到）
    hd = SELECT '15' AS "ObjType", D."DocEntry", D."LineNum", D."ItemCode", H."DocNum", H."CardCode", H."U_SalOrdType", D."LineTotal", D."Quantity", D."Dscription"
           FROM "ODLN" H JOIN "DLN1" D ON D."DocEntry" = H."DocEntry"
          WHERE H."DocEntry" IN (SELECT "DocEntry" FROM "MTC_CA_R_GOODS_OUT" WHERE "RunId" = :rid AND "ObjType" = '15'
                                 UNION SELECT "DocEntry" FROM "MTC_CA_R_GOODS_OUT_BEG" WHERE "RunId" = :rid AND "ObjType" = '15'
                                 UNION SELECT "SrcEntry" FROM "MTC_CA_R_GOODS_MOVE" WHERE "RunId" = :rid AND "SrcObj" = '15'
                                 UNION SELECT "DocEntry" FROM "MTC_CA_S_LINE" WHERE "RunId" = :rid AND "ObjType" = '15')
         UNION ALL
         SELECT '16', D."DocEntry", D."LineNum", D."ItemCode", H."DocNum", H."CardCode", H."U_SalOrdType", -D."LineTotal", -D."Quantity", D."Dscription"
           FROM "ORDN" H JOIN "RDN1" D ON D."DocEntry" = H."DocEntry"
          WHERE H."DocEntry" IN (SELECT "DocEntry" FROM "MTC_CA_R_GOODS_OUT" WHERE "RunId" = :rid AND "ObjType" = '16'
                                 UNION SELECT "DocEntry" FROM "MTC_CA_R_GOODS_OUT_BEG" WHERE "RunId" = :rid AND "ObjType" = '16'
                                 UNION SELECT "SrcEntry" FROM "MTC_CA_R_GOODS_MOVE" WHERE "RunId" = :rid AND "SrcObj" = '16'
                                 UNION SELECT "DocEntry" FROM "MTC_CA_S_LINE" WHERE "RunId" = :rid AND "ObjType" = '16');
    hd2 = SELECT H.*, T."CustType", CASE WHEN LOCATE(IFNULL("MTC_CA_F_PARAM"('SAMPLE_SALTYPES', :fc), ',样品销售,'), ',' || IFNULL(T."BusiType", '') || ',') > 0 THEN 'Y' ELSE 'N' END AS "IsSample"
            FROM :hd H
            LEFT JOIN (SELECT "Name", MAX("U_CustType") AS "CustType", MAX("U_BusiType") AS "BusiType" FROM "@MTC_SALORDTYPE" GROUP BY "Name") T ON T."Name" = H."U_SalOrdType"
           WHERE (:nCust = 0 OR EXISTS (SELECT 1 FROM :lCust X WHERE H."CardCode" LIKE X."P"))
             AND (:nCt = 0 OR EXISTS (SELECT 1 FROM :lCt X WHERE T."CustType" = X."V"))
             AND (:nSt = 0 OR EXISTS (SELECT 1 FROM :lSt X WHERE H."U_SalOrdType" = X."V"))
             AND (:nDoc = 0 OR EXISTS (SELECT 1 FROM :lDoc X WHERE TO_NVARCHAR(H."DocNum") LIKE X."P"));
    IF :STYPE = '3' THEN
        f = SELECT G."ObjType", G."DocEntry", G."LineNum", G."ItemCode", CAST(G."CostAmt" AS DECIMAL(19,6)) AS "Beg", CAST(0 AS DECIMAL(19,6)) AS "Iss", CAST(0 AS DECIMAL(19,6)) AS "Ret0", CAST(0 AS DECIMAL(19,6)) AS "Inv",
               CAST(0 AS DECIMAL(19,6)) AS "Rin", CAST(0 AS DECIMAL(19,6)) AS "Ret", CAST(0 AS DECIMAL(19,6)) AS "Adj", CAST(0 AS DECIMAL(19,6)) AS "Smp", CAST(0 AS DECIMAL(19,6)) AS "EndA"
              FROM "MTC_CA_R_GOODS_OUT_BEG" G WHERE G."RunId" = :rid
            UNION ALL
            SELECT G."ObjType", G."DocEntry", G."LineNum", G."ItemCode", 0, 0, 0, 0, 0, 0, 0, 0, G."CostAmt" FROM "MTC_CA_R_GOODS_OUT" G WHERE G."RunId" = :rid
            UNION ALL
            SELECT D."ObjType", D."DocEntry", D."LineNum", L."ItemCode", 0,
                   CASE WHEN D."ObjType" = '15' THEN -L."Amount" ELSE 0 END, CASE WHEN D."ObjType" = '16' THEN L."Amount" ELSE 0 END, 0, 0, 0, 0, 0, 0
              FROM "MTC_CA_S_LINE" D JOIN "MTC_CA_R_LINE" L ON L."RunId" = D."RunId" AND L."LineId" = D."LineId"
             WHERE D."RunId" = :rid AND (D."ObjType" = '15' OR (D."ObjType" = '16' AND IFNULL(D."BaseType", '') <> '15'))
            UNION ALL
            SELECT M."SrcObj", M."SrcEntry", M."SrcLine", NULL, 0, 0, 0,
                   CASE WHEN M."K" = 'INV' THEN M."Amount" ELSE 0 END, CASE WHEN M."K" = 'RIN' THEN M."Amount" ELSE 0 END,
                   CASE WHEN M."K" = 'RET' THEN M."Amount" ELSE 0 END, CASE WHEN M."K" = 'ADJ' THEN M."Amount" ELSE 0 END,
                   CASE WHEN M."IsSample" = 'Y' AND M."K" <> 'RET' THEN M."Amount" ELSE 0 END, 0
              FROM "MTC_CA_R_GOODS_MOVE" M WHERE M."RunId" = :rid;
        SELECT H."CardCode" AS "客户", MAX(C."CardName") AS "客户名称",
               CAST(SUM(F."Beg") AS DECIMAL(19,2)) AS "期初未开票成本", CAST(SUM(F."Iss") AS DECIMAL(19,2)) AS "本期·发货", CAST(SUM(F."Ret0") AS DECIMAL(19,2)) AS "本期·独立退货",
               CAST(SUM(F."Inv") AS DECIMAL(19,2)) AS "本期·开票", CAST(SUM(F."Rin") AS DECIMAL(19,2)) AS "本期·贷项", CAST(SUM(F."Ret") AS DECIMAL(19,2)) AS "本期·基于交货退货",
               CAST(SUM(F."Adj") AS DECIMAL(19,2)) AS "本期·尾差", CAST(SUM(F."Smp") AS DECIMAL(19,2)) AS "其中样品转出",
               CAST(SUM(F."EndA") AS DECIMAL(19,2)) AS "期末未开票成本",
               CAST(SUM(F."Beg" + F."Iss" - F."Ret0" - F."Inv" - F."Rin" - F."Ret" - F."Adj" - F."EndA") AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :f F
          JOIN :hd2 H ON H."ObjType" = F."ObjType" AND H."DocEntry" = F."DocEntry" AND H."LineNum" = F."LineNum"
          LEFT JOIN "OCRD" C ON C."CardCode" = H."CardCode"
          LEFT JOIN "OITM" I ON I."ItemCode" = H."ItemCode"
         WHERE (IFNULL(:Sample, '') = '' OR H."IsSample" = :Sample)
           AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE H."ItemCode" LIKE X."P"))
           AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"))
         GROUP BY H."CardCode" ORDER BY H."CardCode";
        RETURN;
    END IF;
    lnx = SELECT G."ObjType", G."DocEntry", G."LineNum", H."DocNum", G."DocDate", H."CardCode", COALESCE(G."CustType", H."CustType") AS "CustType", H."U_SalOrdType",
                G."IsSample", G."ItemCode", H."Dscription", G."DocQty", G."InvQty", G."RetQty", G."OpenQty", G."UnitCost", G."CostSrc", G."CostAmt",
                H."LineTotal" / NULLIF(H."Quantity", 0) * ABS(G."OpenQty") AS "SalAmt",
                DAYS_BETWEEN(G."DocDate", :d1) AS "Age"
           FROM "MTC_CA_R_GOODS_OUT" G
           JOIN :hd2 H ON H."ObjType" = G."ObjType" AND H."DocEntry" = G."DocEntry" AND H."LineNum" = G."LineNum"
           LEFT JOIN "OITM" I ON I."ItemCode" = G."ItemCode"
          WHERE G."RunId" = :rid
            AND (IFNULL(:Sample, '') = '' OR G."IsSample" = :Sample)
            AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE G."ItemCode" LIKE X."P"))
            AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"))
            AND DAYS_BETWEEN(G."DocDate", :d1) >= :age;
    IF :STYPE = '4' THEN
        jd = SELECT CASE "TransCode" WHEN 'AR03' THEN :cDom ELSE :cExp END AS "CustType", "TransCode", SUM("Credit" - "Debit") AS "Amt"
               FROM "MTC_CA_R_JDT" WHERE "RunId" = :rid AND "TransCode" IN ('AR03', 'AR04') AND "AcctCode" = :goods
              GROUP BY "TransCode";
        g = SELECT IFNULL("CustType", '') AS "CustType", SUM("CostAmt") AS "Amt", SUM(CASE WHEN "IsSample" = 'Y' THEN "CostAmt" ELSE 0 END) AS "Smp", COUNT(*) AS "Cnt"
              FROM :lnx GROUP BY IFNULL("CustType", '');
        k = SELECT "CustType" FROM :g UNION SELECT "CustType" FROM :jd;
        SELECT K."CustType" AS "客户类型", MAX(J."TransCode") AS "计提凭证代码", MAX(G."Cnt") AS "未清行数",
               CAST(IFNULL(MAX(G."Amt"), 0) AS DECIMAL(19,2)) AS "未开票成本", CAST(IFNULL(MAX(G."Smp"), 0) AS DECIMAL(19,2)) AS "其中样品",
               CAST(IFNULL(MAX(J."Amt"), 0) AS DECIMAL(19,2)) AS "本期计提（贷 140601）",
               CAST(IFNULL(MAX(G."Amt"), 0) - IFNULL(MAX(J."Amt"), 0) AS DECIMAL(19,2)) AS "差额"
          FROM :k K LEFT JOIN :g G ON G."CustType" = K."CustType" LEFT JOIN :jd J ON J."CustType" = K."CustType"
         GROUP BY K."CustType" ORDER BY K."CustType";
    ELSEIF :STYPE = '2' THEN
        SELECT L."CardCode" AS "客户", C."CardName" AS "客户名称", L."CustType" AS "客户类型", L."U_SalOrdType" AS "销售订单类型", L."IsSample" AS "样品",
               CASE L."ObjType" WHEN '15' THEN '交货' ELSE '退货' END AS "单据", L."DocNum" AS "单号 Num", L."DocEntry" AS "单号 Entry", L."LineNum" AS "行号",
               L."DocDate" AS "交货日期", L."Age" AS "账龄天数", L."ItemCode" AS "物料", L."Dscription" AS "物料描述",
               CAST(L."DocQty" AS DECIMAL(19,6)) AS "交货数量", CAST(L."InvQty" AS DECIMAL(19,6)) AS "已开票数量", CAST(L."RetQty" AS DECIMAL(19,6)) AS "已退货数量",
               CAST(L."OpenQty" AS DECIMAL(19,6)) AS "未清数量", CAST(L."UnitCost" AS DECIMAL(19,6)) AS "单位成本", L."CostSrc" AS "单位成本来源",
               CAST(L."CostAmt" AS DECIMAL(19,2)) AS "未清成本", CAST(L."SalAmt" AS DECIMAL(19,2)) AS "未开票销售金额"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         ORDER BY L."CardCode", L."DocDate", L."DocEntry", L."LineNum";
    ELSEIF :STYPE = '1' THEN
        SELECT L."CardCode" AS "客户", MAX(C."CardName") AS "客户名称", L."ItemCode" AS "物料", MAX(L."Dscription") AS "物料描述", COUNT(*) AS "行数",
               CAST(SUM(L."OpenQty") AS DECIMAL(19,6)) AS "未清数量", CAST(SUM(L."CostAmt") AS DECIMAL(19,2)) AS "未清成本",
               CAST(SUM(L."SalAmt") AS DECIMAL(19,2)) AS "未开票销售金额", MIN(L."DocDate") AS "最早交货日期", MAX(L."Age") AS "最长账龄天数"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         GROUP BY L."CardCode", L."ItemCode" ORDER BY L."CardCode", L."ItemCode";
    ELSE
        SELECT L."CardCode" AS "客户", MAX(C."CardName") AS "客户名称", MAX(L."CustType") AS "客户类型", COUNT(*) AS "行数",
               CAST(SUM(L."CostAmt") AS DECIMAL(19,2)) AS "未清成本", CAST(SUM(L."SalAmt") AS DECIMAL(19,2)) AS "未开票销售金额",
               CAST(SUM(CASE WHEN L."Age" <= 30 THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄（成本）·30 天内",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 31 AND 60 THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄（成本）·31–60 天",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 61 AND 90 THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄（成本）·61–90 天",
               CAST(SUM(CASE WHEN L."Age" BETWEEN 91 AND 180 THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄（成本）·91–180 天",
               CAST(SUM(CASE WHEN L."Age" > 180 THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "账龄（成本）·180 天以上",
               CAST(SUM(CASE WHEN L."IsSample" = 'Y' THEN L."CostAmt" ELSE 0 END) AS DECIMAL(19,2)) AS "其中样品",
               MIN(L."DocDate") AS "最早交货日期"
          FROM :lnx L LEFT JOIN "OCRD" C ON C."CardCode" = L."CardCode"
         GROUP BY L."CardCode" ORDER BY L."CardCode";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #24
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R12 产品单位成本变动分析：本期与对比期相比单位成本变了多少，拆成材料价格、材料用量、费率、工时、委外加工费因素。
-- 参数：Fc 账期, CmpFc 对比账期（空 = 上期）, Item 产品, ItemGrp 物料组, MinPct 只看单位成本变动超过 %（空 = 全部）,
--       STYPE 0 按产品 / 1 产品 × 材料
-- 口径：两期都有完工的产品（R_ORDER.RecvQty > 0）。单位材料按 R_ORDER_MAT 的本期结转：单耗 = 结转数量 ÷ 完工数量（结转数量 =
--       （期初累计领料 + 本期领料）× 结转比例），单价 = 结转金额 ÷ 结转数量；价格因素 = (本期单价 − 对比期单价) × 本期单耗，
--       用量因素 = (本期单耗 − 对比期单耗) × 对比期单价；只有一期领用的材料全部算用量因素。本级费用：费率 = 分摊额 ÷ 工时（R_ALLOC），
--       费率因素 = (本期费率 − 对比期费率) × 本期单位工时，工时因素 = (本期单位工时 − 对比期单位工时) × 对比期费率。
--       “其他”= 变动额 − 各因素（结转比例变化、关单、四舍五入）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_12_COSTVAR" (
    IN Fc NVARCHAR(10), IN CmpFc NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN MinPct NVARCHAR(20), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE pfc NVARCHAR(10); DECLARE cfc NVARCHAR(10); DECLARE prid BIGINT; DECLARE nItem INT; DECLARE nGrp INT;
    DECLARE th DECIMAL(19,6) := TO_DECIMAL(IFNULL(NULLIF(TRIM(:MinPct), ''), '0'), 19, 6);
    SELECT MAX("RunId"), MAX("PrevFc") INTO rid, pfc FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    cfc := IFNULL(NULLIF(TRIM(IFNULL(:CmpFc, '')), ''), :pfc);
    SELECT MAX("RunId") INTO prid FROM "MTC_CA_F_RPT_RUN"(:cfc, :cfc);
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    IF :rid IS NULL OR :prid IS NULL THEN
        SELECT '本期或对比期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    ord = SELECT CASE WHEN O."RunId" = :rid THEN 'C' ELSE 'P' END AS "W", O."RunId", O."OrderType", O."OrderEntry", O."ItemCode", O."RecvQty", O."CostAmt",
                 O."AllocMfg" + O."AllocLab" AS "Fee"
            FROM "MTC_CA_R_ORDER" O LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
           WHERE O."RunId" IN (:rid, :prid) AND O."RecvQty" > 0
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"));
    hrs = SELECT O."W", O."ItemCode", SUM(A."W") AS "H"
            FROM :ord O
            JOIN (SELECT "RunId", "OrderType", "OrderEntry", "PoolCode", MAX("Weight") AS "W" FROM "MTC_CA_R_ALLOC" WHERE "RunId" IN (:rid, :prid)
                   GROUP BY "RunId", "OrderType", "OrderEntry", "PoolCode") A
              ON A."RunId" = O."RunId" AND A."OrderType" = O."OrderType" AND A."OrderEntry" = O."OrderEntry"
           GROUP BY O."W", O."ItemCode";
    pr = SELECT O."ItemCode",
                SUM(CASE WHEN O."W" = 'C' THEN O."RecvQty" ELSE 0 END) AS "Q1", SUM(CASE WHEN O."W" = 'P' THEN O."RecvQty" ELSE 0 END) AS "Q0",
                SUM(CASE WHEN O."W" = 'C' THEN O."CostAmt" ELSE 0 END) AS "A1", SUM(CASE WHEN O."W" = 'P' THEN O."CostAmt" ELSE 0 END) AS "A0",
                SUM(CASE WHEN O."W" = 'C' THEN O."Fee" ELSE 0 END) AS "F1", SUM(CASE WHEN O."W" = 'P' THEN O."Fee" ELSE 0 END) AS "F0"
           FROM :ord O GROUP BY O."ItemCode"
         HAVING SUM(CASE WHEN O."W" = 'C' THEN O."RecvQty" ELSE 0 END) > 0 AND SUM(CASE WHEN O."W" = 'P' THEN O."RecvQty" ELSE 0 END) > 0;
    pr2 = SELECT P.*, IFNULL(H1."H", 0) AS "H1", IFNULL(H0."H", 0) AS "H0"
            FROM :pr P LEFT JOIN :hrs H1 ON H1."W" = 'C' AND H1."ItemCode" = P."ItemCode" LEFT JOIN :hrs H0 ON H0."W" = 'P' AND H0."ItemCode" = P."ItemCode";
    mt = SELECT O."ItemCode" AS "Prod", M."ItemCode" AS "Mat",
                SUM(CASE WHEN O."W" = 'C' THEN (M."OpenIssQty" + M."IssQty") * IFNULL(M."Ratio", 0) ELSE 0 END) AS "CQ1",
                SUM(CASE WHEN O."W" = 'P' THEN (M."OpenIssQty" + M."IssQty") * IFNULL(M."Ratio", 0) ELSE 0 END) AS "CQ0",
                SUM(CASE WHEN O."W" = 'C' THEN M."CarMat" + M."CarLab" + M."CarMfg" + M."CarSub" ELSE 0 END) AS "CA1",
                SUM(CASE WHEN O."W" = 'P' THEN M."CarMat" + M."CarLab" + M."CarMfg" + M."CarSub" ELSE 0 END) AS "CA0"
           FROM :ord O JOIN "MTC_CA_R_ORDER_MAT" M ON M."RunId" = O."RunId" AND M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
          GROUP BY O."ItemCode", M."ItemCode";
    -- 每个产品 × 材料的单耗、单价和两个因素（每件产品）
    mf = SELECT T."Prod", T."Mat", P."Q1", P."Q0",
                T."CQ1" / P."Q1" AS "U1", T."CQ0" / P."Q0" AS "U0",
                T."CA1" / NULLIF(T."CQ1", 0) AS "P1", T."CA0" / NULLIF(T."CQ0", 0) AS "PP0",
                T."CA1" / P."Q1" AS "UC1", T."CA0" / P."Q0" AS "UC0",
                CASE WHEN T."Mat" <> '#SUBFEE' AND T."CQ1" <> 0 AND T."CQ0" <> 0
                     THEN (T."CA1" / T."CQ1" - T."CA0" / T."CQ0") * (T."CQ1" / P."Q1") ELSE 0 END AS "EP",
                CASE WHEN T."Mat" = '#SUBFEE' THEN 0
                     WHEN T."CQ1" <> 0 AND T."CQ0" <> 0 THEN (T."CQ1" / P."Q1" - T."CQ0" / P."Q0") * (T."CA0" / T."CQ0")
                     ELSE T."CA1" / P."Q1" - T."CA0" / P."Q0" END AS "EU",
                CASE WHEN T."Mat" = '#SUBFEE' THEN T."CA1" / P."Q1" - T."CA0" / P."Q0" ELSE 0 END AS "ES"
           FROM :mt T JOIN :pr P ON P."ItemCode" = T."Prod";
    IF :STYPE = '1' THEN
        SELECT F."Prod" AS "产品", MAX(PM."ItemName") AS "产品名称", F."Mat" AS "材料", MAX(CASE WHEN F."Mat" = '#SUBFEE' THEN '委外加工费' ELSE MM."ItemName" END) AS "材料名称",
               CAST(MAX(F."U1") AS DECIMAL(19,6)) AS "单耗·本期", CAST(MAX(F."U0") AS DECIMAL(19,6)) AS "单耗·对比期",
               CAST(MAX(F."P1") AS DECIMAL(19,6)) AS "材料单价·本期", CAST(MAX(F."PP0") AS DECIMAL(19,6)) AS "材料单价·对比期",
               CAST(MAX(F."UC1") AS DECIMAL(19,6)) AS "每件材料成本·本期", CAST(MAX(F."UC0") AS DECIMAL(19,6)) AS "每件材料成本·对比期",
               CAST(MAX(F."UC1") - MAX(F."UC0") AS DECIMAL(19,6)) AS "每件材料成本·变动",
               CAST(MAX(F."EP") AS DECIMAL(19,6)) AS "因素·价格", CAST(MAX(F."EU") AS DECIMAL(19,6)) AS "因素·用量", CAST(MAX(F."ES") AS DECIMAL(19,6)) AS "因素·委外加工费"
          FROM :mf F LEFT JOIN "OITM" PM ON PM."ItemCode" = F."Prod" LEFT JOIN "OITM" MM ON MM."ItemCode" = F."Mat"
         GROUP BY F."Prod", F."Mat"
        HAVING :th = 0 OR ABS(MAX(F."UC1") - MAX(F."UC0")) * 100 >= :th * NULLIF(ABS(MAX(F."UC0")), 0) OR MAX(F."UC0") = 0
         ORDER BY F."Prod", ABS(MAX(F."UC1") - MAX(F."UC0")) DESC;
    ELSE
        fx = SELECT "Prod", SUM("EP") AS "EP", SUM("EU") AS "EU", SUM("ES") AS "ES" FROM :mf GROUP BY "Prod";
        SELECT TO_NVARCHAR(M."ItmsGrpCod") AS "物料组", P."ItemCode" AS "产品", M."ItemName" AS "产品名称",
               :Fc AS "本期", :cfc AS "对比期",
               CAST(P."Q1" AS DECIMAL(19,6)) AS "完工数量·本期", CAST(P."Q0" AS DECIMAL(19,6)) AS "完工数量·对比期",
               CAST(P."A1" / P."Q1" AS DECIMAL(19,6)) AS "单位成本·本期", CAST(P."A0" / P."Q0" AS DECIMAL(19,6)) AS "单位成本·对比期",
               CAST(P."A1" / P."Q1" - P."A0" / P."Q0" AS DECIMAL(19,6)) AS "单位成本·变动",
               CAST((P."A1" / P."Q1" - P."A0" / P."Q0") * 100 / NULLIF(P."A0" / P."Q0", 0) AS DECIMAL(19,2)) AS "单位成本·变动 %",
               CAST(IFNULL(X."EP", 0) AS DECIMAL(19,6)) AS "因素·材料价格", CAST(IFNULL(X."EU", 0) AS DECIMAL(19,6)) AS "因素·材料用量",
               CAST(CASE WHEN P."H1" <> 0 AND P."H0" <> 0 THEN (P."F1" / P."H1" - P."F0" / P."H0") * (P."H1" / P."Q1") ELSE P."F1" / P."Q1" - P."F0" / P."Q0" END AS DECIMAL(19,6)) AS "因素·费率",
               CAST(CASE WHEN P."H1" <> 0 AND P."H0" <> 0 THEN (P."H1" / P."Q1" - P."H0" / P."Q0") * (P."F0" / P."H0") ELSE 0 END AS DECIMAL(19,6)) AS "因素·工时",
               CAST(IFNULL(X."ES", 0) AS DECIMAL(19,6)) AS "因素·委外加工费",
               CAST(P."A1" / P."Q1" - P."A0" / P."Q0" - IFNULL(X."EP", 0) - IFNULL(X."EU", 0) - IFNULL(X."ES", 0)
                    - (P."F1" / P."Q1" - P."F0" / P."Q0") AS DECIMAL(19,6)) AS "因素·其他",
               CAST(P."H1" / P."Q1" AS DECIMAL(19,6)) AS "单位工时·本期", CAST(P."H0" / P."Q0" AS DECIMAL(19,6)) AS "单位工时·对比期",
               CAST(P."F1" / NULLIF(P."H1", 0) AS DECIMAL(19,6)) AS "每工时费用·本期", CAST(P."F0" / NULLIF(P."H0", 0) AS DECIMAL(19,6)) AS "每工时费用·对比期"
          FROM :pr2 P LEFT JOIN :fx X ON X."Prod" = P."ItemCode" LEFT JOIN "OITM" M ON M."ItemCode" = P."ItemCode"
         WHERE :th = 0 OR ABS(P."A1" / P."Q1" - P."A0" / P."Q0") * 100 >= :th * NULLIF(ABS(P."A0" / P."Q0"), 0)
         ORDER BY ABS(P."A1" / P."Q1" - P."A0" / P."Q0") * P."Q1" DESC;
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #25
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R13 材料用量差异（损耗）：订单实际领用与按完工数折算的计划用量之差。
-- 参数：FcFrom, FcTo, Scope 订单范围（空或 2 = 本期按关单处理的订单，1 = 本期有完工的订单）, WorType 订单类型, Item 产品, Mat 材料,
--       MinPct 只看差异超过 %（空 = 全部；计划外领料、计划内未领始终列出）, STYPE 0 产品 × 材料 / 1 订单 × 材料 / 2 按材料
-- 口径：实际 = 截至期末累计领料数量（R_ORDER_MAT 期初累计 + 本期，退料冲减）；标准 = 累计完工数 × 订单行计划用量 ÷ 订单计划数（S_ORDER_LINE，
--       同 P45 结转比例的口径）；差异金额 = 差异数量 × 累计领料平均单价。关单订单的差异就是全部损耗，本期完工未关单的只是阶段数。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_13_USAGE" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Scope NVARCHAR(1), IN WorType NVARCHAR(100), IN Item NVARCHAR(5000), IN Mat NVARCHAR(5000),
    IN MinPct NVARCHAR(20), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nWt INT; DECLARE nItem INT; DECLARE nMat INT;
    DECLARE th DECIMAL(19,6) := TO_DECIMAL(IFNULL(NULLIF(TRIM(:MinPct), ''), '0'), 19, 6);
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType); SELECT COUNT(*) INTO nWt FROM :lWt;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lMat  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Mat);     SELECT COUNT(*) INTO nMat FROM :lMat;
    ord = SELECT U."FcCode", O."RunId", O."OrderType", O."OrderEntry", S."OrderNum", O."WorType", O."ItemCode", O."PlannedQty",
                 O."PrevRecvQty" + O."RecvQty" AS "CumQ", O."ClosedInFc"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
           WHERE (CASE WHEN :Scope = '1' THEN CASE WHEN O."RecvQty" <> 0 THEN 1 ELSE 0 END ELSE CASE WHEN O."ClosedInFc" = 'Y' THEN 1 ELSE 0 END END) = 1
             AND (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"))
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"));
    pl = SELECT L."RunId", L."OrderType", L."OrderEntry", L."ItemCode", SUM(L."PlannedQty") AS "PQ"
           FROM "MTC_CA_S_ORDER_LINE" L JOIN :ord O ON O."RunId" = L."RunId" AND O."OrderType" = L."OrderType" AND O."OrderEntry" = L."OrderEntry"
          GROUP BY L."RunId", L."OrderType", L."OrderEntry", L."ItemCode";
    am = SELECT M."RunId", M."OrderType", M."OrderEntry", M."ItemCode", M."OpenIssQty" + M."IssQty" AS "AQ",
                M."OpenIssMat" + M."OpenIssLab" + M."OpenIssMfg" + M."OpenIssSub" + M."IssMat" + M."IssLab" + M."IssMfg" + M."IssSub" AS "AA"
           FROM "MTC_CA_R_ORDER_MAT" M JOIN :ord O ON O."RunId" = M."RunId" AND O."OrderType" = M."OrderType" AND O."OrderEntry" = M."OrderEntry"
          WHERE M."ItemCode" <> '#SUBFEE';
    k = SELECT "RunId", "OrderType", "OrderEntry", "ItemCode" FROM :pl UNION SELECT "RunId", "OrderType", "OrderEntry", "ItemCode" FROM :am;
    d = SELECT O."FcCode", O."OrderType", O."OrderEntry", O."OrderNum", O."WorType", O."ItemCode" AS "Prod", K."ItemCode" AS "Mat", O."CumQ", O."PlannedQty",
               IFNULL(P."PQ", 0) AS "PQ", IFNULL(A."AQ", 0) AS "AQ", IFNULL(A."AA", 0) AS "AA",
               CASE WHEN IFNULL(O."PlannedQty", 0) > 0 THEN O."CumQ" * IFNULL(P."PQ", 0) / O."PlannedQty" ELSE 0 END AS "SQ",
               COALESCE(A."AA" / NULLIF(A."AQ", 0), RI."PMat" + RI."PMfg" + RI."PLab" + RI."PSub") AS "UP",
               CASE WHEN P."ItemCode" IS NULL THEN '计划外领料' WHEN IFNULL(A."AQ", 0) = 0 THEN '计划内未领' END AS "Note"
          FROM :k K
          JOIN :ord O ON O."RunId" = K."RunId" AND O."OrderType" = K."OrderType" AND O."OrderEntry" = K."OrderEntry"
          LEFT JOIN :pl P ON P."RunId" = K."RunId" AND P."OrderType" = K."OrderType" AND P."OrderEntry" = K."OrderEntry" AND P."ItemCode" = K."ItemCode"
          LEFT JOIN :am A ON A."RunId" = K."RunId" AND A."OrderType" = K."OrderType" AND A."OrderEntry" = K."OrderEntry" AND A."ItemCode" = K."ItemCode"
          LEFT JOIN "MTC_CA_R_ITEM" RI ON RI."RunId" = K."RunId" AND RI."ItemCode" = K."ItemCode"
         WHERE (:nMat = 0 OR EXISTS (SELECT 1 FROM :lMat X WHERE K."ItemCode" LIKE X."P"));
    -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
    o = SELECT "Prod", "Mat", "FcCode", "OrderType", "OrderNum", "OrderEntry",
               COUNT(*) AS "Cnt", SUM("CumQ") AS "CumQ",
               SUM("PQ") AS "PQ", SUM("SQ") AS "SQ", SUM("AQ") AS "AQ", SUM("AA") AS "AA",
               SUM(("AQ" - "SQ") * IFNULL("UP", 0)) AS "DA", MAX("Note") AS "Note"
          FROM (SELECT CASE WHEN :STYPE = '2' THEN NULL ELSE "Prod" END AS "Prod", "Mat",
                       CASE WHEN :STYPE = '1' THEN "FcCode" END AS "FcCode", CASE WHEN :STYPE = '1' THEN "OrderType" END AS "OrderType",
                       CASE WHEN :STYPE = '1' THEN "OrderNum" END AS "OrderNum", CASE WHEN :STYPE = '1' THEN "OrderEntry" END AS "OrderEntry",
                       CASE WHEN :STYPE = '1' THEN "CumQ" END AS "CumQ", "PQ", "SQ", "AQ", "AA", "UP", "Note"
                  FROM :d)
         GROUP BY "Prod", "Mat", "FcCode", "OrderType", "OrderNum", "OrderEntry";
    SELECT X."Prod" AS "产品", PM."ItemName" AS "产品名称", X."FcCode" AS "账期", "MTC_CA_F_RPT_OTNAME"(X."OrderType") AS "订单单据", X."OrderNum" AS "订单号 Num",
           X."Mat" AS "材料", MM."ItemName" AS "材料名称", X."Cnt" AS "订单数", CAST(X."CumQ" AS DECIMAL(19,6)) AS "累计完工数",
           CAST(X."PQ" AS DECIMAL(19,6)) AS "订单计划用量", CAST(X."SQ" AS DECIMAL(19,6)) AS "按完工折算标准用量", CAST(X."AQ" AS DECIMAL(19,6)) AS "实际领用",
           CAST(X."AQ" - X."SQ" AS DECIMAL(19,6)) AS "差异·数量", CAST((X."AQ" - X."SQ") * 100 / NULLIF(X."SQ", 0) AS DECIMAL(19,2)) AS "差异·%",
           CAST(X."AA" / NULLIF(X."AQ", 0) AS DECIMAL(19,6)) AS "平均领料单价", CAST(X."DA" AS DECIMAL(19,2)) AS "差异·金额", X."Note" AS "说明"
      FROM :o X LEFT JOIN "OITM" PM ON PM."ItemCode" = X."Prod" LEFT JOIN "OITM" MM ON MM."ItemCode" = X."Mat"
     WHERE :th = 0 OR X."SQ" = 0 OR X."AQ" = 0 OR ABS(X."AQ" - X."SQ") * 100 >= :th * ABS(X."SQ")
     ORDER BY X."Prod", X."FcCode", X."OrderNum", ABS(X."DA") DESC, X."Mat";
END

@@
-- @stmt 成本报表 21_reports.sql #26
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R14 产品毛利分析：本期开票收入与结转的销售成本（同 DN03 口径）对比。
-- 参数：FcFrom, FcTo, Item 物料, ItemGrp 物料组, Cust 客户, CustType 客户类型, SalType 销售订单类型, InclSample 含样品 Y/N（默认 N）,
--       STYPE 0 按产品 / 1 按客户 / 2 客户 × 产品 / 3 发票行
-- 口径：收入 = 本期过账的应收发票（OINV/INV1）− 应收贷项（ORIN/RIN1）的行金额（本币、不含税），取消单反号；成本 = 新框架 R_GOODS_MOVE
--       里这张发票 / 贷项行消耗交货（独立退货）的成本，加上交货行全部开完票时的尾差（ADJ，挂在交货行的产品和客户上）。
--       不基于交货的发票行（如服务、直接开票）没有成本，标“无交货成本”。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_14_MARGIN" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Cust NVARCHAR(5000),
    IN CustType NVARCHAR(200), IN SalType NVARCHAR(500), IN InclSample NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE d0 DATE; DECLARE d1 DATE; DECLARE fB NVARCHAR(10); DECLARE smp NVARCHAR(200);
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nCust INT; DECLARE nCt INT; DECLARE nSt INT;
    -- 历史期（旧框架回填）没有发出商品和销售成本（DN03）的结果（报表合并第一阶段不回填，2026-11-02）
    IF "MTC_CA_F_RPT_HISTONLY"(:FcFrom, :FcTo) = 'Y' THEN
        SELECT '历史期（旧框架回填）没有这张报表的数据：旧框架没有保存发出商品和销售成本（DN03）的明细结果，请用旧报表查看' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    runs = SELECT "FcCode", "RunId", "D0", "D1" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("D0"), MAX("D1"), MAX("FcCode") INTO d0, d1, fB FROM :runs;
    smp := IFNULL("MTC_CA_F_PARAM"('SAMPLE_SALTYPES', :fB), ',样品销售,');
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lCust = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Cust);     SELECT COUNT(*) INTO nCust FROM :lCust;
    lCt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:CustType); SELECT COUNT(*) INTO nCt FROM :lCt;
    lSt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:SalType);  SELECT COUNT(*) INTO nSt FROM :lSt;
    st = SELECT "Name", MAX("U_CustType") AS "CustType", MAX("U_BusiType") AS "BusiType" FROM "@MTC_SALORDTYPE" GROUP BY "Name";
    cost = SELECT CASE M."K" WHEN 'INV' THEN '13' ELSE '14' END AS "ObjType", M."DocEntry", M."LineNum", SUM(M."Amount") AS "Cost"
             FROM :runs U JOIN "MTC_CA_R_GOODS_MOVE" M ON M."RunId" = U."RunId" AND M."K" IN ('INV', 'RIN')
            GROUP BY M."K", M."DocEntry", M."LineNum";
    rows0 = SELECT '13' AS "ObjType", D."DocEntry", D."LineNum", H."DocNum", TO_DATE(H."DocDate") AS "DocDate", H."CardCode", H."U_SalOrdType" AS "SalType",
                   D."ItemCode", D."Dscription",
                   CAST(CASE WHEN H."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity" AS DECIMAL(19,6)) AS "Qty",
                   CAST(CASE WHEN H."CANCELED" = 'C' THEN -1 ELSE 1 END * D."LineTotal" AS DECIMAL(19,6)) AS "Rev"
              FROM "OINV" H JOIN "INV1" D ON D."DocEntry" = H."DocEntry"
             WHERE TO_DATE(H."DocDate") BETWEEN :d0 AND :d1
            UNION ALL
            SELECT '14', D."DocEntry", D."LineNum", H."DocNum", TO_DATE(H."DocDate"), H."CardCode", H."U_SalOrdType", D."ItemCode", D."Dscription",
                   CASE WHEN H."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity", CASE WHEN H."CANCELED" = 'C' THEN 1 ELSE -1 END * D."LineTotal"
              FROM "ORIN" H JOIN "RIN1" D ON D."DocEntry" = H."DocEntry"
             WHERE TO_DATE(H."DocDate") BETWEEN :d0 AND :d1;
    al = SELECT R."ObjType", R."DocEntry", R."LineNum", R."DocNum", R."DocDate", R."CardCode", R."SalType", R."ItemCode", R."Dscription", R."Qty", R."Rev",
                C."Cost", T."CustType", CASE WHEN LOCATE(:smp, ',' || IFNULL(T."BusiType", '') || ',') > 0 THEN 'Y' ELSE 'N' END AS "IsSample",
                CAST(CASE WHEN C."Cost" IS NULL THEN '无交货成本' END AS NVARCHAR(100)) AS "Note"
           FROM :rows0 R
           LEFT JOIN :cost C ON C."ObjType" = R."ObjType" AND C."DocEntry" = R."DocEntry" AND C."LineNum" = R."LineNum"
           LEFT JOIN :st T ON T."Name" = R."SalType"
         UNION ALL
         SELECT M."SrcObj", M."SrcEntry", M."SrcLine", COALESCE(DH."DocNum", RH."DocNum"), M."DocDate", COALESCE(DH."CardCode", RH."CardCode"),
                COALESCE(DH."U_SalOrdType", RH."U_SalOrdType"), COALESCE(DL."ItemCode", RL."ItemCode"), COALESCE(DL."Dscription", RL."Dscription"),
                0, 0, M."Amount", M."CustType", M."IsSample", '交货行开票完毕的尾差'
           FROM :runs U
           JOIN "MTC_CA_R_GOODS_MOVE" M ON M."RunId" = U."RunId" AND M."K" = 'ADJ'
           LEFT JOIN "ODLN" DH ON M."SrcObj" = '15' AND DH."DocEntry" = M."SrcEntry"
           LEFT JOIN "DLN1" DL ON M."SrcObj" = '15' AND DL."DocEntry" = M."SrcEntry" AND DL."LineNum" = M."SrcLine"
           LEFT JOIN "ORDN" RH ON M."SrcObj" = '16' AND RH."DocEntry" = M."SrcEntry"
           LEFT JOIN "RDN1" RL ON M."SrcObj" = '16' AND RL."DocEntry" = M."SrcEntry" AND RL."LineNum" = M."SrcLine";
    f = SELECT A.*, TO_NVARCHAR(I."ItmsGrpCod") AS "Grp", I."ItemName", C."CardName"
          FROM :al A LEFT JOIN "OITM" I ON I."ItemCode" = A."ItemCode" LEFT JOIN "OCRD" C ON C."CardCode" = A."CardCode"
         WHERE (IFNULL(:InclSample, 'N') = 'Y' OR A."IsSample" = 'N')
           AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE A."ItemCode" LIKE X."P"))
           AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(I."ItmsGrpCod") = X."V"))
           AND (:nCust = 0 OR EXISTS (SELECT 1 FROM :lCust X WHERE A."CardCode" LIKE X."P"))
           AND (:nCt = 0 OR EXISTS (SELECT 1 FROM :lCt X WHERE A."CustType" = X."V"))
           AND (:nSt = 0 OR EXISTS (SELECT 1 FROM :lSt X WHERE A."SalType" = X."V"));
    IF :STYPE = '3' THEN
        SELECT CASE F."ObjType" WHEN '13' THEN '应收发票' WHEN '14' THEN '应收贷项' WHEN '15' THEN '交货（尾差）' ELSE '退货（尾差）' END AS "单据",
               F."DocNum" AS "单号 Num", F."DocEntry" AS "单号 Entry", F."LineNum" AS "行号", F."DocDate" AS "日期", F."CardCode" AS "客户", F."CardName" AS "客户名称",
               F."CustType" AS "客户类型", F."SalType" AS "销售订单类型", F."IsSample" AS "样品", F."ItemCode" AS "物料", F."Dscription" AS "物料描述",
               F."Qty" AS "数量", CAST(F."Rev" AS DECIMAL(19,2)) AS "销售收入", CAST(F."Cost" AS DECIMAL(19,2)) AS "销售成本",
               CAST(F."Rev" - IFNULL(F."Cost", 0) AS DECIMAL(19,2)) AS "毛利",
               CAST((F."Rev" - IFNULL(F."Cost", 0)) * 100 / NULLIF(F."Rev", 0) AS DECIMAL(19,2)) AS "毛利率 %", F."Note" AS "说明"
          FROM :f F ORDER BY F."DocDate", F."ObjType", F."DocEntry", F."LineNum";
    ELSE
        -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
        SELECT F."KCard" AS "客户", MAX(CASE WHEN :STYPE IN ('1', '2') THEN F."CardName" END) AS "客户名称",
               MAX(CASE WHEN :STYPE IN ('1', '2') THEN F."CustType" END) AS "客户类型",
               F."KItem" AS "物料",
               MAX(CASE WHEN :STYPE IN ('0', '2') OR IFNULL(:STYPE, '') = '' THEN F."ItemName" END) AS "物料名称",
               CAST(SUM(F."Qty") AS DECIMAL(19,6)) AS "数量", CAST(SUM(F."Rev") AS DECIMAL(19,2)) AS "销售收入", CAST(SUM(IFNULL(F."Cost", 0)) AS DECIMAL(19,2)) AS "销售成本",
               CAST(SUM(F."Rev") - SUM(IFNULL(F."Cost", 0)) AS DECIMAL(19,2)) AS "毛利",
               CAST((SUM(F."Rev") - SUM(IFNULL(F."Cost", 0))) * 100 / NULLIF(SUM(F."Rev"), 0) AS DECIMAL(19,2)) AS "毛利率 %",
               CAST(SUM(F."Rev") / NULLIF(SUM(F."Qty"), 0) AS DECIMAL(19,6)) AS "单位售价", CAST(SUM(IFNULL(F."Cost", 0)) / NULLIF(SUM(F."Qty"), 0) AS DECIMAL(19,6)) AS "单位成本",
               CAST(SUM(CASE WHEN F."Note" = '无交货成本' THEN F."Rev" ELSE 0 END) AS DECIMAL(19,2)) AS "其中无交货成本的收入"
          FROM (SELECT B.*, CASE WHEN :STYPE IN ('1', '2') THEN B."CardCode" END AS "KCard",
                       CASE WHEN :STYPE IN ('0', '2') OR IFNULL(:STYPE, '') = '' THEN B."ItemCode" END AS "KItem"
                  FROM :f B) F
         GROUP BY F."KCard", F."KItem"
         ORDER BY 1, 4;
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #27
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R15 费用池费用率趋势：各期每个费用池的归集额、工时、每工时费用及环比。
-- 参数：FcFrom, FcTo（都空 = 最近 12 个已计算账期）, Pool 费用池, Elem 要素（MFG / LAB，空 = 两项）
-- 口径：MTC_CA_R_POOL（归集）、MTC_CA_R_ALLOC（已分配、工时 = 单位工时 × 本期入库数）。每工时费用 = 已分配 ÷ 工时。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_15_POOLTREND" (IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Pool NVARCHAR(500), IN Elem NVARCHAR(3))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE f0 NVARCHAR(10) := NULLIF(TRIM(IFNULL(:FcFrom, '')), '');
    DECLARE f1 NVARCHAR(10) := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    DECLARE nPool INT;
    DECLARE el NVARCHAR(3) := CASE WHEN :Elem IN ('MFG', '制造') THEN 'MFG' WHEN :Elem IN ('LAB', '人工') THEN 'LAB' ELSE '' END;
    IF :f0 IS NULL AND :f1 IS NULL THEN
        SELECT MAX("FcCode") INTO f1 FROM "MTC_CA_PERIOD" WHERE IFNULL("PostRunId", "CalcRunId") IS NOT NULL;
        SELECT MIN("FcCode") INTO f0 FROM (SELECT TOP 12 "FcCode" FROM "MTC_CA_PERIOD" WHERE IFNULL("PostRunId", "CalcRunId") IS NOT NULL ORDER BY "FcCode" DESC);
    END IF;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:f0, IFNULL(:f1, :f0)) WHERE "RunId" IS NOT NULL;
    lPool = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Pool); SELECT COUNT(*) INTO nPool FROM :lPool;
    p = SELECT U."FcCode", P."RunId", P."PoolCode", P."Elem", SUM(P."Amount") AS "Amt"
          FROM :runs U JOIN "MTC_CA_R_POOL" P ON P."RunId" = U."RunId" GROUP BY U."FcCode", P."RunId", P."PoolCode", P."Elem";
    a = SELECT "RunId", "PoolCode", "Elem", SUM("Amount") AS "Amt", SUM("Weight") AS "W", SUM("RecvQty") AS "Q", COUNT(*) AS "Cnt"
          FROM "MTC_CA_R_ALLOC" WHERE "RunId" IN (SELECT "RunId" FROM :runs) GROUP BY "RunId", "PoolCode", "Elem";
    t = SELECT P."FcCode", P."PoolCode", P."Elem", P."Amt", IFNULL(A."Amt", 0) AS "Alloc", A."W", A."Q", IFNULL(A."Cnt", 0) AS "Cnt",
               IFNULL(A."Amt", 0) / NULLIF(A."W", 0) AS "Rate"
          FROM :p P LEFT JOIN :a A ON A."RunId" = P."RunId" AND A."PoolCode" = P."PoolCode" AND A."Elem" = P."Elem"
         WHERE (:el = '' OR P."Elem" = :el) AND (:nPool = 0 OR EXISTS (SELECT 1 FROM :lPool X WHERE P."PoolCode" = X."V"));
    SELECT T."PoolCode" AS "费用池", C."PoolName" AS "费用池名称", CASE T."Elem" WHEN 'MFG' THEN '制造' ELSE '人工' END AS "要素", T."FcCode" AS "账期",
           CAST(T."Amt" AS DECIMAL(19,2)) AS "归集金额", CAST(T."Alloc" AS DECIMAL(19,2)) AS "已分配", CAST(T."Amt" - T."Alloc" AS DECIMAL(19,2)) AS "未分配",
           T."Cnt" AS "分配订单数", CAST(T."Q" AS DECIMAL(19,6)) AS "入库数量", CAST(T."W" AS DECIMAL(19,6)) AS "工时",
           CAST(T."Rate" AS DECIMAL(19,6)) AS "每工时费用",
           CAST(LAG(T."Rate") OVER (PARTITION BY T."PoolCode", T."Elem" ORDER BY T."FcCode") AS DECIMAL(19,6)) AS "上期每工时费用",
           CAST((T."Rate" - LAG(T."Rate") OVER (PARTITION BY T."PoolCode", T."Elem" ORDER BY T."FcCode")) * 100
                / NULLIF(LAG(T."Rate") OVER (PARTITION BY T."PoolCode", T."Elem" ORDER BY T."FcCode"), 0) AS DECIMAL(19,2)) AS "环比 %",
           CAST((T."Amt" - LAG(T."Amt") OVER (PARTITION BY T."PoolCode", T."Elem" ORDER BY T."FcCode")) * 100
                / NULLIF(LAG(T."Amt") OVER (PARTITION BY T."PoolCode", T."Elem" ORDER BY T."FcCode"), 0) AS DECIMAL(19,2)) AS "归集额环比 %"
      FROM :t T LEFT JOIN "MTC_CA_C_POOL" C ON C."PoolCode" = T."PoolCode"
     ORDER BY T."PoolCode", T."Elem", T."FcCode";
END

@@
-- @stmt 成本报表 21_reports.sql #28
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R16 期末存货结构：期末存货按类别（原材料 / 半成品 / 产成品 / 在产品 / 发出商品）、物料组、物料的金额和占比，与对比期比较，带最后动账日期。
-- 参数：Fc 账期, CmpFc 对比账期（空 = 上期）, Cls 存货类别（中文，逗号分隔）, ItemGrp 物料组, STYPE 0 按类别 / 1 类别 × 物料组 / 2 按物料
-- 口径：库存 = R_ITEM 期末四项；类别按参数 RPT_GRP_CLASS（物料组:类别），没列的物料组按 BOM：层级 0 原材料、是别的物料的子件（ITT1）半成品、
--       其余产成品；在产品 = R_ORDER.WipAmt（按订单产品）；发出商品 = R_GOODS_OUT 未开票成本。最后动账日期 = OIVL 截至期末最近一笔（不分仓库）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_16_INVSTRUCT" (
    IN Fc NVARCHAR(10), IN CmpFc NVARCHAR(10), IN Cls NVARCHAR(200), IN ItemGrp NVARCHAR(5000), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE rid BIGINT; DECLARE fc NVARCHAR(10); DECLARE pfc NVARCHAR(10); DECLARE cfc NVARCHAR(10); DECLARE prid BIGINT; DECLARE d1 DATE;
    DECLARE nCls INT; DECLARE nGrp INT; DECLARE tot DECIMAL(19,6);
    SELECT MAX("RunId"), MAX("FcCode"), MAX("PrevFc"), MAX("D1") INTO rid, fc, pfc, d1 FROM "MTC_CA_F_RPT_RUN"(:Fc, :Fc);
    cfc := IFNULL(NULLIF(TRIM(IFNULL(:CmpFc, '')), ''), :pfc);
    SELECT MAX("RunId") INTO prid FROM "MTC_CA_F_RPT_RUN"(:cfc, :cfc);
    lCls = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Cls);     SELECT COUNT(*) INTO nCls FROM :lCls;
    lGrp = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    IF :rid IS NULL THEN
        SELECT '这个账期没有成功的正式计算（看 R00）' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    gc = SELECT TRIM(SUBSTR_BEFORE("V", ':')) AS "Grp", TRIM(SUBSTR_AFTER("V", ':')) AS "Cls"
           FROM "MTC_CA_F_RPT_LIST"(IFNULL("MTC_CA_F_PARAM"('RPT_GRP_CLASS', :fc), '')) WHERE LOCATE("V", ':') > 0;
    v = SELECT CASE WHEN R."RunId" = :rid THEN 'C' ELSE 'P' END AS "W", 'STOCK' AS "Kind", R."ItemCode", R."iLevel", R."EndQty" AS "Qty", R."EndAmount" AS "Amt"
          FROM "MTC_CA_R_ITEM" R WHERE R."RunId" IN (:rid, IFNULL(:prid, -1)) AND (R."EndQty" <> 0 OR R."EndAmount" <> 0)
        UNION ALL
        SELECT CASE WHEN O."RunId" = :rid THEN 'C' ELSE 'P' END, 'WIP', O."ItemCode", O."iLevel", CAST(NULL AS DECIMAL(19,6)), SUM(O."WipAmt")
          FROM "MTC_CA_R_ORDER" O WHERE O."RunId" IN (:rid, IFNULL(:prid, -1)) AND O."WipAmt" <> 0 GROUP BY O."RunId", O."ItemCode", O."iLevel"
        UNION ALL
        SELECT CASE WHEN G."RunId" = :rid THEN 'C' ELSE 'P' END, 'GOODS', G."ItemCode", NULL, SUM(G."OpenQty"), SUM(G."CostAmt")
          FROM "MTC_CA_R_GOODS_OUT" G WHERE G."RunId" IN (:rid, IFNULL(:prid, -1)) GROUP BY G."RunId", G."ItemCode";
    c = SELECT V.*, TO_NVARCHAR(M."ItmsGrpCod") AS "Grp", M."ItemName",
               CASE V."Kind" WHEN 'WIP' THEN '在产品' WHEN 'GOODS' THEN '发出商品'
                    ELSE COALESCE(G."Cls", CASE WHEN V."iLevel" = 0 THEN '原材料'
                                                WHEN EXISTS (SELECT 1 FROM "ITT1" B WHERE B."Code" = V."ItemCode") THEN '半成品' ELSE '产成品' END) END AS "Cls"
          FROM :v V LEFT JOIN "OITM" M ON M."ItemCode" = V."ItemCode" LEFT JOIN :gc G ON G."Grp" = TO_NVARCHAR(M."ItmsGrpCod");
    c2 = SELECT * FROM :c
          WHERE (:nCls = 0 OR EXISTS (SELECT 1 FROM :lCls X WHERE "Cls" = X."V"))
            AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE "Grp" = X."V"));
    SELECT SUM("Amt") INTO tot FROM :c2 WHERE "W" = 'C';
    IF :STYPE = '2' THEN
        lst = SELECT "ItemCode", MAX(TO_DATE("DocDate")) AS "LastDate" FROM "OIVL"
               WHERE "ItemCode" IN (SELECT "ItemCode" FROM :c2 WHERE "W" = 'C' AND "Kind" = 'STOCK') AND TO_DATE("DocDate") <= :d1
               GROUP BY "ItemCode";
        SELECT X."Cls" AS "存货类别", X."Grp" AS "物料组", X."ItemCode" AS "物料", MAX(X."ItemName") AS "名称",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Qty" END) AS DECIMAL(19,6)) AS "本期末·数量",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE 0 END) AS DECIMAL(19,2)) AS "本期末·金额",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE 0 END) * 100 / NULLIF(:tot, 0) AS DECIMAL(19,4)) AS "本期末·占比 %",
               CAST(SUM(CASE WHEN X."W" = 'P' THEN X."Amt" ELSE 0 END) AS DECIMAL(19,2)) AS "对比期末·金额",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE -X."Amt" END) AS DECIMAL(19,2)) AS "变动",
               MAX(L."LastDate") AS "最后动账日期", MONTHS_BETWEEN(MAX(L."LastDate"), :d1) AS "无动账月数"
          FROM :c2 X LEFT JOIN :lst L ON X."Kind" = 'STOCK' AND L."ItemCode" = X."ItemCode"
         GROUP BY X."Cls", X."Grp", X."ItemCode"
         ORDER BY X."Cls", LPAD(IFNULL(X."Grp", ''), 10, '0'), SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE 0 END) DESC;
    ELSE
        -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
        SELECT X."Cls" AS "存货类别", X."KGrp" AS "物料组", MAX(G."ItmsGrpNam") AS "物料组名称",
               COUNT(DISTINCT CASE WHEN X."W" = 'C' THEN X."ItemCode" END) AS "物料数",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE 0 END) AS DECIMAL(19,2)) AS "本期末·金额",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE 0 END) * 100 / NULLIF(:tot, 0) AS DECIMAL(19,4)) AS "本期末·占比 %",
               CAST(SUM(CASE WHEN X."W" = 'P' THEN X."Amt" ELSE 0 END) AS DECIMAL(19,2)) AS "对比期末·金额",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE -X."Amt" END) AS DECIMAL(19,2)) AS "变动",
               CAST(SUM(CASE WHEN X."W" = 'C' THEN X."Amt" ELSE -X."Amt" END) * 100 / NULLIF(SUM(CASE WHEN X."W" = 'P' THEN X."Amt" ELSE 0 END), 0) AS DECIMAL(19,2)) AS "变动 %"
          FROM (SELECT C.*, CASE WHEN :STYPE = '1' THEN C."Grp" END AS "KGrp" FROM :c2 C) X
          LEFT JOIN "OITB" G ON TO_NVARCHAR(G."ItmsGrpCod") = X."KGrp"
         GROUP BY X."Cls", X."KGrp"
         ORDER BY CASE X."Cls" WHEN '原材料' THEN 1 WHEN '半成品' THEN 2 WHEN '产成品' THEN 3 WHEN '在产品' THEN 4 WHEN '发出商品' THEN 5 ELSE 6 END,
                  LPAD(IFNULL(X."KGrp", ''), 10, '0');
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #29
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R19 在产品汇总表（用户 2026-11-01）：期初在产品 + 本期领料 + 本级分摊 − 完工转出 − 关单差异 = 期末在产品（四项），
--     按订单类型 / 产品 / 材料 / 订单汇总。
-- 参数：FcFrom, FcTo, WorType 订单类型, Item 产品, ItemGrp 产品物料组, Mat 材料, NonZero 只看有在产品或本期有发生（Y / N）,
--       STYPE 0 按订单类型 / 1 按产品 / 2 按材料 / 3 按订单
-- 口径：MTC_CA_R_ORDER_MAT（期初 = 期初累计领料 − 期初累计结转；本期领料、完工转出、关单差异、期末在产品四项；'#SUBFEE' = 委外加工费）
--       + MTC_CA_R_ORDER 本级分摊（人工 + 制造）。本级分摊按本期入库分配，全部随完工转出，不留在在产品里；按材料显示时单列一行“本级分摊”。
--       填了材料条件时只看这些材料，不含本级分摊。核算类别：订单类型在参数 WW_WORTYPES 的为“委外”（期末在产品 = 140801 材料 + 140802 加工费），其余为“生产”。
--       多个账期：期初取第一个账期、期末取最后一个账期，本期各项累加。“勾稽差额”应为 0。
-- 勾稽：期末在产品合计 = R01 期末在产品 = R09 在产品业务端（V12）；订单 × 材料勾稽差额 = 0（V13）；本期期初 = 上期期末（V14）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_19_WIPSUM" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN WorType NVARCHAR(100), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000),
    IN Mat NVARCHAR(5000), IN NonZero NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nWt INT; DECLARE nItem INT; DECLARE nGrp INT; DECLARE nMat INT; DECLARE fA NVARCHAR(10); DECLARE fB NVARCHAR(10);
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    SELECT MIN("FcCode"), MAX("FcCode") INTO fA, fB FROM :runs;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType); SELECT COUNT(*) INTO nWt FROM :lWt;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lMat  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Mat);     SELECT COUNT(*) INTO nMat FROM :lMat;
    ord = SELECT U."FcCode", O."RunId", O."OrderType", O."OrderEntry", S."OrderNum", O."WorType", O."ItemCode", S."CardCode", S."StatusAtEnd", O."ClosedInFc",
                 O."PlannedQty", O."PrevRecvQty" + O."RecvQty" AS "CumQ", O."AllocLab" + O."AllocMfg" AS "Alloc",
                 CASE WHEN LOCATE(IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', U."FcCode"), ',50,'), ',' || IFNULL(O."WorType", '') || ',') > 0 THEN '委外' ELSE '生产' END AS "Cat"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
            LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
           WHERE (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"))
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"));
    -- 一行 = 账期 × 订单 × 材料；本级分摊作为材料 '#ALLOC' 的一行（本期投入 = 完工转出 = 分摊额）
    d = SELECT O."FcCode", O."OrderType", O."OrderEntry", O."OrderNum", O."WorType", O."ItemCode", O."CardCode", O."StatusAtEnd", O."ClosedInFc",
               O."PlannedQty", O."CumQ", O."Cat", X."ItemCode" AS "Mat",
               X."OpenIssMat" - X."OpenCarMat" AS "BMat", X."OpenIssLab" - X."OpenCarLab" AS "BLab",
               X."OpenIssMfg" - X."OpenCarMfg" AS "BMfg", X."OpenIssSub" - X."OpenCarSub" AS "BSub",
               X."IssMat" + X."IssLab" + X."IssMfg" + X."IssSub" AS "Iss", CAST(0 AS DECIMAL(19,6)) AS "Alc",
               X."CarMat" + X."CarLab" + X."CarMfg" + X."CarSub" AS "Car", X."ClsMat" + X."ClsLab" + X."ClsMfg" + X."ClsSub" AS "Cls",
               X."WipMat" AS "WMat", X."WipLab" AS "WLab", X."WipMfg" AS "WMfg", X."WipSub" AS "WSub"
          FROM :ord O
          JOIN "MTC_CA_R_ORDER_MAT" X ON X."RunId" = O."RunId" AND X."OrderType" = O."OrderType" AND X."OrderEntry" = O."OrderEntry"
         WHERE (:nMat = 0 OR EXISTS (SELECT 1 FROM :lMat L WHERE X."ItemCode" LIKE L."P"))
        UNION ALL
        SELECT O."FcCode", O."OrderType", O."OrderEntry", O."OrderNum", O."WorType", O."ItemCode", O."CardCode", O."StatusAtEnd", O."ClosedInFc",
               O."PlannedQty", O."CumQ", O."Cat", '#ALLOC',
               CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6)),
               CAST(0 AS DECIMAL(19,6)), O."Alloc", O."Alloc", CAST(0 AS DECIMAL(19,6)),
               CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6)), CAST(0 AS DECIMAL(19,6))
          FROM :ord O
         WHERE :nMat = 0 AND O."Alloc" <> 0;
    -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
    g = SELECT "KCat", "KWt", "KProd", "KMat", "KOT", "KOE",
               COUNT(DISTINCT "OrderType" || '-' || TO_NVARCHAR("OrderEntry")) AS "Cnt",
               MAX("OrderNum") AS "OrderNum", MAX("CardCode") AS "CardCode", MAX("ClosedInFc") AS "ClosedInFc",
               MAX(CASE WHEN "FcCode" = :fB THEN "StatusAtEnd" END) AS "StatusAtEnd",
               MAX("PlannedQty") AS "PlannedQty", MAX(CASE WHEN "FcCode" = :fB THEN "CumQ" END) AS "CumQ",
               SUM(CASE WHEN "FcCode" = :fA THEN "BMat" ELSE 0 END) AS "BMat", SUM(CASE WHEN "FcCode" = :fA THEN "BLab" ELSE 0 END) AS "BLab",
               SUM(CASE WHEN "FcCode" = :fA THEN "BMfg" ELSE 0 END) AS "BMfg", SUM(CASE WHEN "FcCode" = :fA THEN "BSub" ELSE 0 END) AS "BSub",
               SUM("Iss") AS "Iss", SUM("Alc") AS "Alc", SUM("Car") AS "Car", SUM("Cls") AS "Cls",
               SUM(CASE WHEN "FcCode" = :fB THEN "WMat" ELSE 0 END) AS "WMat", SUM(CASE WHEN "FcCode" = :fB THEN "WLab" ELSE 0 END) AS "WLab",
               SUM(CASE WHEN "FcCode" = :fB THEN "WMfg" ELSE 0 END) AS "WMfg", SUM(CASE WHEN "FcCode" = :fB THEN "WSub" ELSE 0 END) AS "WSub"
          FROM (SELECT D.*,
                       CASE WHEN :STYPE IN ('0', '3') OR IFNULL(:STYPE, '') = '' THEN "Cat" END AS "KCat",
                       CASE WHEN :STYPE IN ('0', '3') OR IFNULL(:STYPE, '') = '' THEN "WorType" END AS "KWt",
                       CASE WHEN :STYPE IN ('1', '3') THEN "ItemCode" END AS "KProd",
                       CASE WHEN :STYPE = '2' THEN "Mat" END AS "KMat",
                       CASE WHEN :STYPE = '3' THEN "OrderType" END AS "KOT",
                       CASE WHEN :STYPE = '3' THEN "OrderEntry" END AS "KOE"
                  FROM :d D)
         GROUP BY "KCat", "KWt", "KProd", "KMat", "KOT", "KOE";
    r = SELECT G.*, G."BMat" + G."BLab" + G."BMfg" + G."BSub" AS "B", G."WMat" + G."WLab" + G."WMfg" + G."WSub" AS "W"
          FROM :g G
         WHERE IFNULL(:NonZero, 'N') <> 'Y'
            OR ABS(G."BMat") + ABS(G."BLab") + ABS(G."BMfg") + ABS(G."BSub") + ABS(G."Iss") + ABS(G."Alc") + ABS(G."Car") + ABS(G."Cls")
             + ABS(G."WMat") + ABS(G."WLab") + ABS(G."WMfg") + ABS(G."WSub") >= 0.005;
    IF :STYPE = '1' THEN
        SELECT R."KProd" AS "产品", M."ItemName" AS "产品名称", TO_NVARCHAR(M."ItmsGrpCod") AS "物料组", R."Cnt" AS "订单数",
               CAST(R."BMat" AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(R."BLab" AS DECIMAL(19,2)) AS "期初在产品·人工",
               CAST(R."BMfg" AS DECIMAL(19,2)) AS "期初在产品·制造", CAST(R."BSub" AS DECIMAL(19,2)) AS "期初在产品·委外", CAST(R."B" AS DECIMAL(19,2)) AS "期初在产品·合计",
               CAST(R."Iss" AS DECIMAL(19,2)) AS "本期·领料", CAST(R."Alc" AS DECIMAL(19,2)) AS "本期·本级分摊",
               CAST(R."Car" AS DECIMAL(19,2)) AS "本期·完工转出", CAST(R."Cls" AS DECIMAL(19,2)) AS "本期·关单差异",
               CAST(R."WMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(R."WLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(R."WMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(R."WSub" AS DECIMAL(19,2)) AS "期末在产品·委外", CAST(R."W" AS DECIMAL(19,2)) AS "期末在产品·合计",
               CAST(R."B" + R."Iss" + R."Alc" - R."Car" - R."Cls" - R."W" AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :r R LEFT JOIN "OITM" M ON M."ItemCode" = R."KProd"
         ORDER BY R."KProd";
    ELSEIF :STYPE = '2' THEN
        SELECT R."KMat" AS "材料",
               CASE R."KMat" WHEN '#SUBFEE' THEN '委外加工费' WHEN '#ALLOC' THEN '本级分摊（人工 + 制造，随完工全部转出）' ELSE M."ItemName" END AS "材料名称",
               TO_NVARCHAR(M."ItmsGrpCod") AS "物料组", R."Cnt" AS "订单数",
               CAST(R."BMat" AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(R."BLab" AS DECIMAL(19,2)) AS "期初在产品·人工",
               CAST(R."BMfg" AS DECIMAL(19,2)) AS "期初在产品·制造", CAST(R."BSub" AS DECIMAL(19,2)) AS "期初在产品·委外", CAST(R."B" AS DECIMAL(19,2)) AS "期初在产品·合计",
               CAST(R."Iss" AS DECIMAL(19,2)) AS "本期·领料", CAST(R."Alc" AS DECIMAL(19,2)) AS "本期·本级分摊",
               CAST(R."Car" AS DECIMAL(19,2)) AS "本期·完工转出", CAST(R."Cls" AS DECIMAL(19,2)) AS "本期·关单差异",
               CAST(R."WMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(R."WLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(R."WMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(R."WSub" AS DECIMAL(19,2)) AS "期末在产品·委外", CAST(R."W" AS DECIMAL(19,2)) AS "期末在产品·合计",
               CAST(R."B" + R."Iss" + R."Alc" - R."Car" - R."Cls" - R."W" AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :r R LEFT JOIN "OITM" M ON M."ItemCode" = R."KMat"
         ORDER BY CASE R."KMat" WHEN '#SUBFEE' THEN 1 WHEN '#ALLOC' THEN 2 ELSE 0 END, R."KMat";
    ELSEIF :STYPE = '3' THEN
        SELECT R."KCat" AS "核算类别", "MTC_CA_F_RPT_OTNAME"(R."KOT") AS "订单单据", R."OrderNum" AS "订单号 Num", R."KOE" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"(R."KWt") AS "订单类型",
               R."KProd" AS "产品", M."ItemName" AS "产品名称", R."CardCode" AS "委外供应商", R."StatusAtEnd" AS "期末状态", R."ClosedInFc" AS "按关单处理",
               CAST(R."PlannedQty" AS DECIMAL(19,6)) AS "计划数", CAST(R."CumQ" AS DECIMAL(19,6)) AS "累计完工",
               CAST(R."CumQ" * 100 / NULLIF(R."PlannedQty", 0) AS DECIMAL(19,2)) AS "完工率 %",
               CAST(R."BMat" AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(R."BLab" AS DECIMAL(19,2)) AS "期初在产品·人工",
               CAST(R."BMfg" AS DECIMAL(19,2)) AS "期初在产品·制造", CAST(R."BSub" AS DECIMAL(19,2)) AS "期初在产品·委外", CAST(R."B" AS DECIMAL(19,2)) AS "期初在产品·合计",
               CAST(R."Iss" AS DECIMAL(19,2)) AS "本期·领料", CAST(R."Alc" AS DECIMAL(19,2)) AS "本期·本级分摊",
               CAST(R."Car" AS DECIMAL(19,2)) AS "本期·完工转出", CAST(R."Cls" AS DECIMAL(19,2)) AS "本期·关单差异",
               CAST(R."WMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(R."WLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(R."WMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(R."WSub" AS DECIMAL(19,2)) AS "期末在产品·委外", CAST(R."W" AS DECIMAL(19,2)) AS "期末在产品·合计",
               CAST(R."B" + R."Iss" + R."Alc" - R."Car" - R."Cls" - R."W" AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :r R LEFT JOIN "OITM" M ON M."ItemCode" = R."KProd"
         ORDER BY R."KCat", R."KOT", R."KOE";
    ELSE
        SELECT R."KCat" AS "核算类别", "MTC_CA_F_RPT_WTNAME"(R."KWt") AS "订单类型", R."Cnt" AS "订单数",
               CAST(R."BMat" AS DECIMAL(19,2)) AS "期初在产品·材料", CAST(R."BLab" AS DECIMAL(19,2)) AS "期初在产品·人工",
               CAST(R."BMfg" AS DECIMAL(19,2)) AS "期初在产品·制造", CAST(R."BSub" AS DECIMAL(19,2)) AS "期初在产品·委外", CAST(R."B" AS DECIMAL(19,2)) AS "期初在产品·合计",
               CAST(R."Iss" AS DECIMAL(19,2)) AS "本期·领料", CAST(R."Alc" AS DECIMAL(19,2)) AS "本期·本级分摊",
               CAST(R."Car" AS DECIMAL(19,2)) AS "本期·完工转出", CAST(R."Cls" AS DECIMAL(19,2)) AS "本期·关单差异",
               CAST(R."WMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(R."WLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
               CAST(R."WMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(R."WSub" AS DECIMAL(19,2)) AS "期末在产品·委外", CAST(R."W" AS DECIMAL(19,2)) AS "期末在产品·合计",
               CAST(R."B" + R."Iss" + R."Alc" - R."Car" - R."Cls" - R."W" AS DECIMAL(19,2)) AS "勾稽差额"
          FROM :r R
         ORDER BY R."KCat", R."KWt";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #30
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R20 在产品明细表（用户 2026-11-01）：一行 = 账期 × 订单 × 材料，期初在产品 + 本期领料 − 完工转出 − 关单差异 = 期末在产品（四项）。
-- 参数：FcFrom, FcTo, WorType 订单类型, OrderNum 订单号 Num, Item 产品, ItemGrp 产品物料组, Mat 材料,
--       Scope 范围（空 期末有在产品 / 1 期初或期末有在产品 / 2 全部）
-- 口径：MTC_CA_R_ORDER_MAT（'#SUBFEE' 行 = 委外加工费）；计划用量取订单行快照 MTC_CA_S_ORDER_LINE；按完工折算用量 = 累计完工 × 计划用量 ÷ 计划数。
--       本级分摊随完工全部转出，不在在产品里，这里不列（看 R19 按材料 / R01）。
--       “期末在产品·折算数量” = 累计领料数量 × 期末在产品 ÷ 累计领料金额，只是按金额比例折算的参考数，不是盘点数。
-- 勾稽：同一账期、同一条件下合计 = R19 按材料（不含本级分摊行）；每行勾稽差额 = 0（V13）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_20_WIPDTL" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN WorType NVARCHAR(100), IN OrderNum NVARCHAR(5000), IN Item NVARCHAR(5000),
    IN ItemGrp NVARCHAR(5000), IN Mat NVARCHAR(5000), IN Scope NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nWt INT; DECLARE nOrd INT; DECLARE nItem INT; DECLARE nGrp INT; DECLARE nMat INT;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:FcFrom, :FcTo) WHERE "RunId" IS NOT NULL;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType);  SELECT COUNT(*) INTO nWt FROM :lWt;
    lOrd  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:OrderNum); SELECT COUNT(*) INTO nOrd FROM :lOrd;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lMat  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Mat);      SELECT COUNT(*) INTO nMat FROM :lMat;
    ord = SELECT U."FcCode", O."RunId", O."OrderType", O."OrderEntry", S."OrderNum", O."WorType", O."ItemCode", M."ItemName", TO_NVARCHAR(M."ItmsGrpCod") AS "Grp",
                 S."CardCode", S."PostDate", S."StatusAtEnd", O."ClosedInFc", O."PlannedQty", O."PrevRecvQty" + O."RecvQty" AS "CumQ",
                 CASE WHEN LOCATE(IFNULL("MTC_CA_F_PARAM"('WW_WORTYPES', U."FcCode"), ',50,'), ',' || IFNULL(O."WorType", '') || ',') > 0 THEN '委外' ELSE '生产' END AS "Cat"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_S_ORDER" S ON S."RunId" = O."RunId" AND S."OrderType" = O."OrderType" AND S."OrderEntry" = O."OrderEntry"
            LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
           WHERE (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"))
             AND (:nOrd = 0 OR EXISTS (SELECT 1 FROM :lOrd X WHERE S."OrderNum" LIKE X."P"))
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"));
    pl = SELECT L."RunId", L."OrderType", L."OrderEntry", L."ItemCode", SUM(L."PlannedQty") AS "PQ"
           FROM "MTC_CA_S_ORDER_LINE" L JOIN :ord O ON O."RunId" = L."RunId" AND O."OrderType" = L."OrderType" AND O."OrderEntry" = L."OrderEntry"
          GROUP BY L."RunId", L."OrderType", L."OrderEntry", L."ItemCode";
    d = SELECT O.*, X."ItemCode" AS "Mat", P."PQ",
               X."OpenIssQty" + X."IssQty" AS "AQ",
               X."OpenIssMat" + X."OpenIssLab" + X."OpenIssMfg" + X."OpenIssSub" + X."IssMat" + X."IssLab" + X."IssMfg" + X."IssSub" AS "AA",
               X."OpenCarMat" + X."OpenCarLab" + X."OpenCarMfg" + X."OpenCarSub" + X."CarMat" + X."CarLab" + X."CarMfg" + X."CarSub" AS "AC",
               X."OpenIssMat" + X."OpenIssLab" + X."OpenIssMfg" + X."OpenIssSub" - X."OpenCarMat" - X."OpenCarLab" - X."OpenCarMfg" - X."OpenCarSub" AS "B",
               X."IssQty", X."IssMat" + X."IssLab" + X."IssMfg" + X."IssSub" AS "Iss", X."Ratio",
               X."CarMat" + X."CarLab" + X."CarMfg" + X."CarSub" AS "Car", X."ClsMat" + X."ClsLab" + X."ClsMfg" + X."ClsSub" AS "Cls",
               X."WipMat", X."WipLab", X."WipMfg", X."WipSub", X."WipMat" + X."WipLab" + X."WipMfg" + X."WipSub" AS "W"
          FROM :ord O
          JOIN "MTC_CA_R_ORDER_MAT" X ON X."RunId" = O."RunId" AND X."OrderType" = O."OrderType" AND X."OrderEntry" = O."OrderEntry"
          LEFT JOIN :pl P ON P."RunId" = X."RunId" AND P."OrderType" = X."OrderType" AND P."OrderEntry" = X."OrderEntry" AND P."ItemCode" = X."ItemCode"
         WHERE (:nMat = 0 OR EXISTS (SELECT 1 FROM :lMat L WHERE X."ItemCode" LIKE L."P"));
    SELECT D."FcCode" AS "账期", D."Cat" AS "核算类别", "MTC_CA_F_RPT_OTNAME"(D."OrderType") AS "订单单据", D."OrderNum" AS "订单号 Num", D."OrderEntry" AS "订单 Entry", "MTC_CA_F_RPT_WTNAME"(D."WorType") AS "订单类型",
           D."ItemCode" AS "产品", D."ItemName" AS "产品名称", D."Grp" AS "物料组", D."CardCode" AS "委外供应商", D."PostDate" AS "订单日期",
           D."StatusAtEnd" AS "期末状态", D."ClosedInFc" AS "按关单处理",
           CAST(D."PlannedQty" AS DECIMAL(19,6)) AS "计划数", CAST(D."CumQ" AS DECIMAL(19,6)) AS "累计完工",
           CAST(D."CumQ" * 100 / NULLIF(D."PlannedQty", 0) AS DECIMAL(19,2)) AS "完工率 %",
           D."Mat" AS "材料", CASE WHEN D."Mat" = '#SUBFEE' THEN '委外加工费' ELSE I."ItemName" END AS "材料名称",
           CAST(D."PQ" AS DECIMAL(19,6)) AS "用量·计划用量",
           CAST(CASE WHEN IFNULL(D."PlannedQty", 0) > 0 AND D."PQ" IS NOT NULL THEN D."CumQ" * D."PQ" / D."PlannedQty" END AS DECIMAL(19,6)) AS "用量·按完工折算",
           CAST(D."AQ" AS DECIMAL(19,6)) AS "用量·累计领料",
           CAST(D."AA" AS DECIMAL(19,2)) AS "累计·领料金额", CAST(D."AC" AS DECIMAL(19,2)) AS "累计·完工转出", CAST(D."Ratio" AS DECIMAL(19,6)) AS "本期结转比例",
           CAST(D."B" AS DECIMAL(19,2)) AS "期初在产品",
           CAST(D."IssQty" AS DECIMAL(19,6)) AS "本期领料·数量", CAST(D."Iss" AS DECIMAL(19,2)) AS "本期领料·金额",
           CAST(D."Car" AS DECIMAL(19,2)) AS "本期完工转出", CAST(D."Cls" AS DECIMAL(19,2)) AS "本期关单差异",
           CAST(D."WipMat" AS DECIMAL(19,2)) AS "期末在产品·材料", CAST(D."WipLab" AS DECIMAL(19,2)) AS "期末在产品·人工",
           CAST(D."WipMfg" AS DECIMAL(19,2)) AS "期末在产品·制造", CAST(D."WipSub" AS DECIMAL(19,2)) AS "期末在产品·委外",
           CAST(D."W" AS DECIMAL(19,2)) AS "期末在产品·合计",
           CAST(CASE WHEN D."Mat" <> '#SUBFEE' THEN D."AQ" * D."W" / NULLIF(D."AA", 0) END AS DECIMAL(19,6)) AS "期末在产品·折算数量",
           CAST(D."B" + D."Iss" - D."Car" - D."Cls" - D."W" AS DECIMAL(19,2)) AS "勾稽差额"
      FROM :d D
      LEFT JOIN "OITM" I ON I."ItemCode" = D."Mat"
     WHERE CASE WHEN IFNULL(:Scope, '') = '' THEN CASE WHEN ABS(D."W") >= 0.005 THEN 1 ELSE 0 END
                WHEN :Scope = '1' THEN CASE WHEN ABS(D."W") >= 0.005 OR ABS(D."B") >= 0.005 THEN 1 ELSE 0 END
                ELSE 1 END = 1
     ORDER BY D."FcCode", D."Cat", D."OrderType", D."OrderEntry", CASE WHEN D."Mat" = '#SUBFEE' THEN 1 ELSE 0 END, D."Mat";
END

@@
-- @stmt 成本报表 21_reports.sql #31
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R21 成本结转分录清单（用户 2026-11-05）：执行台在 B1 生成的日记账分录，过账和冲销情况。
-- 参数：Fc 账期（空 = 最近一个生成过凭单的账期）, TransCode 凭证代码, Scope 空 = 只看未撤销 / 1 含已撤销,
--       STYPE 0 分录清单（一张一行）/ 1 逐行明细 / 2 本期其他成本凭证（不是执行台生成的，如手工录入，不用冲销）
-- 口径：MTC_CA_JV + B1 OBTF / BTF1（未过账）、OJDT / JDT1（已过账）；不看顶栏运行，也不走 MTC_CA_F_RPT_RUN：
--       撤销以后运行号已经不是生成凭单时的那次，这里按 MTC_CA_JV 记录的批号取。
-- 状态：冲销日期不在本账期时，本期总账还含这张分录的金额，不能直接重新生成（设计稿 8.6）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_21_JVLIST" (IN Fc NVARCHAR(10), IN TransCode NVARCHAR(500), IN Scope NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE fcv NVARCHAR(10); DECLARE d0 DATE; DECLARE d1 DATE; DECLARE nTc INT; DECLARE sc NVARCHAR(1);
    sc := IFNULL(:Scope, '');
    fcv := NULLIF(:Fc, '');
    IF :fcv IS NULL THEN
        SELECT MAX("FcCode") INTO fcv FROM "MTC_CA_JV" WHERE "Status" = 'CREATED';
    END IF;
    IF :fcv IS NULL THEN
        SELECT MAX("FcCode") INTO fcv FROM "MTC_CA_JV";
    END IF;
    IF :fcv IS NULL THEN
        SELECT '还没有生成过凭单，请填账期' AS "说明" FROM DUMMY;
        RETURN;
    END IF;
    SELECT MAX(TO_DATE("F_RefDate")), MAX(TO_DATE("T_RefDate")) INTO d0, d1 FROM "OFPR" WHERE "Code" = :fcv;
    lTc = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:TransCode); SELECT COUNT(*) INTO nTc FROM :lTc;
    jv = SELECT J."TransCode", J."BatchNum", J."RunId", J."Status"
           FROM "MTC_CA_JV" J
          WHERE J."FcCode" = :fcv AND J."BatchNum" IS NOT NULL
            AND (J."Status" = 'CREATED' OR (:sc = '1' AND J."Status" = 'DELETED'))
            AND (:nTc = 0 OR EXISTS (SELECT 1 FROM :lTc X WHERE J."TransCode" = X."V"));
    IF :STYPE = '2' THEN
        SELECT H."TransCode" AS "凭证代码", C."TrnsCodDsc" AS "凭证名称", H."Number" AS "凭证编号 Number", H."TransId" AS "交易号 TransId",
               TO_DATE(H."RefDate") AS "过账日期", L."Debit" AS "借方合计", L."Credit" AS "贷方合计", H."Ref1" AS "参考1", H."Memo" AS "备注",
               CASE WHEN H."StornoToTr" IS NOT NULL THEN '这是冲销凭证' END AS "说明"
          FROM "OJDT" H
          JOIN (SELECT "TransId", SUM("Debit") AS "Debit", SUM("Credit") AS "Credit" FROM "JDT1" GROUP BY "TransId") L ON L."TransId" = H."TransId"
          LEFT JOIN "OTRC" C ON C."TrnsCode" = H."TransCode"
         WHERE H."RefDate" BETWEEN :d0 AND :d1
           AND LOCATE("MTC_CA_F_PARAM"('COST_TRANSCODES', :fcv), ',' || H."TransCode" || ',') > 0
           AND NOT EXISTS (SELECT 1 FROM "MTC_CA_JV" J WHERE J."BatchNum" = H."BatchNum")
           AND (:nTc = 0 OR EXISTS (SELECT 1 FROM :lTc X WHERE H."TransCode" = X."V"))
         ORDER BY H."TransCode", H."TransId";
    ELSEIF :STYPE = '1' THEN
        SELECT "凭证代码", "批号", "凭证编号 Number", "交易号 TransId", "行号", "过账日期", "科目", A."AcctName" AS "科目名称", "借方", "贷方",
               "成本中心", "项目", "行备注", "B1 状态"
          FROM (SELECT J."TransCode" AS "凭证代码", J."BatchNum" AS "批号", H."Number" AS "凭证编号 Number", H."TransId" AS "交易号 TransId",
                       L."Line_ID" + 1 AS "行号", TO_DATE(H."RefDate") AS "过账日期", L."Account" AS "科目", L."Debit" AS "借方", L."Credit" AS "贷方",
                       L."ProfitCode" AS "成本中心", L."Project" AS "项目", L."LineMemo" AS "行备注", '已过账' AS "B1 状态"
                  FROM :jv J
                  JOIN "OJDT" H ON H."BatchNum" = J."BatchNum" AND H."StornoToTr" IS NULL
                  JOIN "JDT1" L ON L."TransId" = H."TransId"
                UNION ALL
                SELECT J."TransCode", J."BatchNum", CAST(NULL AS INTEGER), T."TransId", L."Line_ID" + 1, TO_DATE(T."RefDate"), L."Account", L."Debit", L."Credit",
                       L."ProfitCode", L."Project", L."LineMemo", '待过账'
                  FROM :jv J
                  JOIN "OBTF" T ON T."BatchNum" = J."BatchNum" AND T."BtfStatus" = 'O'
                  JOIN "BTF1" L ON L."BatchNum" = T."BatchNum" AND L."TransId" = T."TransId") D
          LEFT JOIN "OACT" A ON A."AcctCode" = D."科目"
         ORDER BY "凭证代码", "交易号 TransId", "行号";
    ELSE
        SELECT J."TransCode" AS "凭证代码", C."TrnsCodDsc" AS "凭证名称", J."BatchNum" AS "批号", J."RunId" AS "运行号",
               H."Number" AS "凭证编号 Number", H."TransId" AS "交易号 TransId", TO_DATE(H."RefDate") AS "过账日期",
               COALESCE(S."Debit", SV."Debit") AS "借方合计", COALESCE(S."Credit", SV."Credit") AS "贷方合计", COALESCE(S."Lines", SV."Lines") AS "行数",
               IFNULL(H."Ref1", T."Ref1") AS "参考1", IFNULL(H."Memo", T."Memo") AS "备注",
               R."Number" AS "冲销凭证编号", R."TransId" AS "冲销交易号", TO_DATE(R."RefDate") AS "冲销日期",
               CASE WHEN J."Status" = 'DELETED' AND R."TransId" IS NULL THEN '已撤销'
                    WHEN T."BatchNum" IS NOT NULL THEN '未过账：在 B1 删除凭单'
                    WHEN H."TransId" IS NULL THEN '已在 B1 删除'
                    WHEN R."TransId" IS NULL THEN '已过账未冲销：要冲销'
                    WHEN TO_DATE(R."RefDate") BETWEEN :d0 AND :d1 THEN CASE WHEN J."Status" = 'DELETED' THEN '已撤销，本期内已冲销' ELSE '本期内已冲销' END
                    ELSE '冲销日期不在本账期' END AS "状态"
          FROM :jv J
          LEFT JOIN "OTRC" C ON C."TrnsCode" = J."TransCode"
          LEFT JOIN "OBTF" T ON T."BatchNum" = J."BatchNum" AND T."BtfStatus" = 'O'
          LEFT JOIN (SELECT "BatchNum", "TransId", SUM("Debit") AS "Debit", SUM("Credit") AS "Credit", COUNT(*) AS "Lines" FROM "BTF1" GROUP BY "BatchNum", "TransId") SV
                 ON SV."BatchNum" = T."BatchNum" AND SV."TransId" = T."TransId"
          LEFT JOIN "OJDT" H ON H."BatchNum" = J."BatchNum" AND H."StornoToTr" IS NULL
          LEFT JOIN (SELECT "TransId", SUM("Debit") AS "Debit", SUM("Credit") AS "Credit", COUNT(*) AS "Lines" FROM "JDT1" GROUP BY "TransId") S ON S."TransId" = H."TransId"
          LEFT JOIN "OJDT" R ON R."StornoToTr" = H."TransId"
         ORDER BY J."TransCode", J."BatchNum", H."TransId";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #32
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- 交货 / 销售退货行的单位成本（用户 2026-11-05，R23 也要用，从 reports/MTC_RPT_F_SALE_COST.sql 搬进部署包，两处保持一致）
-- 一行 = 一条 DLN1 / RDN1。优先级同 FI4004_V2、P71：INIT 行上 U_InitPrice（LEGACY_INITPRICE_DATE 及以前）→ NEW / HIST 该单据账期报表所用运行 R_LINE 金额 ÷ 数量
-- → OLD 未回填的历史账期取旧 0302（只取 BOOTSTRAP_FC 及以前）。都没有的行不返回（该期未计算，或不在成本计算范围）。
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION "MTC_RPT_F_SALE_COST" ()
RETURNS TABLE ("ObjType" NVARCHAR(20), "DocEntry" INTEGER, "LineNum" INTEGER, "Price" DECIMAL(19,6), "CostSrc" NVARCHAR(10))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE f0 NVARCHAR(10); DECLARE f1 NVARCHAR(10); DECLARE boot NVARCHAR(10); DECLARE legacy DATE;
    -- 交货可能在开票之前任何账期，所以取全部账期
    SELECT MIN("Code"), MAX("Code") INTO f0, f1 FROM "OFPR";
    boot := IFNULL("MTC_CA_F_PARAM"('BOOTSTRAP_FC', :f1), '0000-00');
    legacy := TO_DATE(IFNULL("MTC_CA_F_PARAM"('LEGACY_INITPRICE_DATE', :f1), '1900-01-01'));

    runs = SELECT "RunId" FROM "MTC_CA_F_RPT_RUN"(:f0, :f1) WHERE "RunId" IS NOT NULL;
    nc = SELECT S."ObjType", S."DocEntry", S."LineNum", SUM(L."Amount") / SUM(L."Qty") AS "UC", MAX(R."RunType") AS "RT"
           FROM :runs U
           JOIN "MTC_CA_RUN" R ON R."RunId" = U."RunId"
           JOIN "MTC_CA_S_LINE" S ON S."RunId" = U."RunId" AND S."ObjType" IN ('15', '16')
           JOIN "MTC_CA_R_LINE" L ON L."RunId" = S."RunId" AND L."LineId" = S."LineId"
          GROUP BY S."ObjType", S."DocEntry", S."LineNum"
         HAVING SUM(L."Qty") <> 0;
    old = SELECT "ObjType", "DocEntry", "LineNum", SUM("Amount") / SUM("Quantity") AS "UC"
            FROM "MTC_COST_0302_INVNTDETAIL1"
           WHERE "CostCode" = '20' AND "ObjType" IN ('15', '16') AND "FcCode" <= :boot
           GROUP BY "ObjType", "DocEntry", "LineNum"
          HAVING SUM("Quantity") <> 0;
    ini = SELECT '15' AS "ObjType", D."DocEntry", D."LineNum", D."U_InitPrice" AS "UC"
            FROM "ODLN" M JOIN "DLN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."DocDate" <= :legacy AND IFNULL(D."U_InitPrice", 0) <> 0
          UNION ALL
          SELECT '16', D."DocEntry", D."LineNum", D."U_InitPrice"
            FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry"
           WHERE M."DocDate" <= :legacy AND IFNULL(D."U_InitPrice", 0) <> 0;
    k = SELECT "ObjType", "DocEntry", "LineNum" FROM :nc
        UNION SELECT "ObjType", "DocEntry", "LineNum" FROM :old
        UNION SELECT "ObjType", "DocEntry", "LineNum" FROM :ini;

    RETURN
    SELECT K."ObjType", K."DocEntry", K."LineNum",
           CAST(COALESCE(I."UC", N."UC", O."UC") AS DECIMAL(19,6)) AS "Price",
           CAST(CASE WHEN I."UC" IS NOT NULL THEN 'INIT'
                     WHEN N."UC" IS NOT NULL THEN CASE WHEN N."RT" = 'H' THEN 'HIST' ELSE 'NEW' END
                     ELSE 'OLD' END AS NVARCHAR(10)) AS "CostSrc"
      FROM :k K
      LEFT JOIN :ini I ON I."ObjType" = K."ObjType" AND I."DocEntry" = K."DocEntry" AND I."LineNum" = K."LineNum"
      LEFT JOIN :nc N ON N."ObjType" = K."ObjType" AND N."DocEntry" = K."DocEntry" AND N."LineNum" = K."LineNum"
      LEFT JOIN :old O ON O."ObjType" = K."ObjType" AND O."DocEntry" = K."DocEntry" AND O."LineNum" = K."LineNum";
END

@@
-- @stmt 成本报表 21_reports.sql #33
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- 销售走势事件（用户 2026-11-05，R23 用）：业务端，直接读 B1 单据，和凭证、总账无关；不依赖发出商品结果表，所以历史月份也能算。
-- 一行 = 一笔收入 / 成本事件，Kind：
--   INV 已开票  发票 / 贷项行，消耗了交货 / 独立退货：收入 = 行金额（本币不含税，取消单反号），成本 = 消耗数量 × 原行成本单价
--   ACC 暂估    收入按交货行金额 ÷ 数量，成本按成本单价，分两种口径 Basis：
--               0 随时看（用户 2026-11-05）  交货 / 独立退货行至今（查询当天）还没开票的部分，记在交货月
--               1 月结固定（用户 2026-11-06）当月未开票的变动：交货 / 独立退货发生时 +，被开票、贷项或基于交货的退货消耗时 −，取消单按取消日期冲回；等于 期末暂估 − 期初暂估
--   NOI 未归属  没有消耗交货的发票 / 贷项行（服务、直接开票、纯金额贷项）：只有收入
-- Basis 0：当月 = 当月发票 + 当月交货中至今未开票的部分，不做冲回。开票后这笔货从交货月的暂估移到开票月的已开票，所以不会算两遍，但以前月份的数会随后续开票、退货、取消变化。
-- Basis 1：每笔只按单据日期入账，后来的单据只进它自己的月份，所以账期结账后不变（只有往已结账期补单才会变，R23 列出）；期末未开票累计 = R_GOODS_OUT = AR03 / AR04 计提（V17）。
-- 成本单价取 MTC_RPT_F_SALE_COST；没有单价（该期未计算）时 Cost = 0、NoCost = 1。交货行金额为 0 的未开票行 NoPrice = 1。
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION "MTC_CA_F_SALE_TREND" (IN d0 DATE, IN d1 DATE, IN Basis NVARCHAR(1))
RETURNS TABLE ("FcCode" NVARCHAR(10), "Kind" NVARCHAR(3), "ObjType" NVARCHAR(20), "DocEntry" INTEGER, "LineNum" INTEGER, "DocDate" DATE,
               "ItemCode" NVARCHAR(50), "CardCode" NVARCHAR(50), "SalType" NVARCHAR(100), "CustType" NVARCHAR(100), "IsSample" NVARCHAR(1),
               "Qty" DECIMAL(19,6), "Rev" DECIMAL(19,6), "Cost" DECIMAL(19,6), "NoCost" INTEGER, "NoPrice" INTEGER, "SrcKey" NVARCHAR(60))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE smp NVARCHAR(500); DECLARE asof DATE;
    smp := IFNULL("MTC_CA_F_PARAM"('SAMPLE_SALTYPES', TO_NVARCHAR(:d1, 'YYYY-MM')), ',样品销售,');
    asof := CASE WHEN CURRENT_DATE > :d1 THEN CURRENT_DATE ELSE :d1 END;   -- 未开票看到查询当天
    typ = SELECT "Name", MAX("U_CustType") AS "CustType", MAX("U_BusiType") AS "BusiType" FROM "@MTC_SALORDTYPE" GROUP BY "Name";
    -- 原行：交货、不基于交货的销售退货；取消单归到原行（数量反号）
    src = SELECT CAST('15' AS NVARCHAR(20)) AS "ObjType",
                 CASE WHEN M."CANCELED" = 'C' AND D."BaseType" = 15 THEN D."BaseEntry" ELSE M."DocEntry" END AS "DocEntry",
                 CASE WHEN M."CANCELED" = 'C' AND D."BaseType" = 15 THEN D."BaseLine" ELSE D."LineNum" END AS "LineNum",
                 TO_DATE(M."DocDate") AS "DocDate", D."ItemCode", M."CardCode", CAST(M."U_SalOrdType" AS NVARCHAR(100)) AS "SalType",
                 CAST(CASE WHEN M."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity" AS DECIMAL(19,6)) AS "Qty",
                 CASE WHEN M."CANCELED" = 'C' THEN 'Y' ELSE 'N' END AS "IsCxl", D."Quantity" AS "OrigQty", D."LineTotal" AS "OrigAmt"
            FROM "ODLN" M JOIN "DLN1" D ON M."DocEntry" = D."DocEntry"
            JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
           WHERE TO_DATE(M."DocDate") <= :asof
          UNION ALL
          SELECT '16', CASE WHEN M."CANCELED" = 'C' AND D."BaseType" = 16 THEN D."BaseEntry" ELSE M."DocEntry" END,
                 CASE WHEN M."CANCELED" = 'C' AND D."BaseType" = 16 THEN D."BaseLine" ELSE D."LineNum" END,
                 TO_DATE(M."DocDate"), D."ItemCode", M."CardCode", M."U_SalOrdType",
                 CASE WHEN M."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity",
                 CASE WHEN M."CANCELED" = 'C' THEN 'Y' ELSE 'N' END, D."Quantity", D."LineTotal"
            FROM "ORDN" M JOIN "RDN1" D ON M."DocEntry" = D."DocEntry"
            JOIN "OITM" I ON I."ItemCode" = D."ItemCode" AND I."InvntItem" = 'Y'
            LEFT JOIN "RDN1" O ON D."BaseType" = 16 AND O."DocEntry" = D."BaseEntry" AND O."LineNum" = D."BaseLine"
           WHERE TO_DATE(M."DocDate") <= :asof
             AND IFNULL(CASE WHEN D."BaseType" = 16 THEN O."BaseType" ELSE D."BaseType" END, -1) <> 15;
    -- 一行 = 一条原行：净数量（扣取消单）、原行日期和金额
    lns = SELECT "ObjType", "DocEntry", "LineNum", MAX("ItemCode") AS "ItemCode", MAX("CardCode") AS "CardCode", MAX("SalType") AS "SalType",
                 SUM("Qty") AS "NetQty", MAX(CASE WHEN "IsCxl" = 'N' THEN "DocDate" END) AS "DocDate",
                 MAX(CASE WHEN "IsCxl" = 'N' THEN "OrigQty" END) AS "OrigQty", MAX(CASE WHEN "IsCxl" = 'N' THEN "OrigAmt" END) AS "OrigAmt"
            FROM :src GROUP BY "ObjType", "DocEntry", "LineNum";
    cst = SELECT "ObjType", "DocEntry", "LineNum", "Price" FROM "MTC_RPT_F_SALE_COST"();
    mv = SELECT M."K", M."DocEntry", M."LineNum", M."DocDate", M."Qty", L."ObjType" AS "SrcObj", L."DocEntry" AS "SrcEntry", L."LineNum" AS "SrcLine",
                L."ItemCode", L."CardCode", L."SalType", L."OrigQty", L."OrigAmt", C."Price"
           FROM "MTC_CA_F_GOODS_MOVE"(:asof) M
           JOIN :lns L ON L."ObjType" = M."SrcObj" AND L."DocEntry" = M."SrcEntry" AND L."LineNum" = M."SrcLine"
           LEFT JOIN :cst C ON C."ObjType" = L."ObjType" AND C."DocEntry" = L."DocEntry" AND C."LineNum" = L."LineNum";
    rv = SELECT CAST('INV' AS NVARCHAR(10)) AS "K", CAST('13' AS NVARCHAR(20)) AS "ObjType", D."DocEntry", D."LineNum", TO_DATE(H."DocDate") AS "DocDate",
                CAST(D."ItemCode" AS NVARCHAR(50)) AS "ItemCode", H."CardCode", CAST(H."U_SalOrdType" AS NVARCHAR(100)) AS "SalType",
                CAST(CASE WHEN H."CANCELED" = 'C' THEN -1 ELSE 1 END * D."Quantity" AS DECIMAL(19,6)) AS "Qty",
                CAST(CASE WHEN H."CANCELED" = 'C' THEN -1 ELSE 1 END * D."LineTotal" AS DECIMAL(19,6)) AS "Rev"
           FROM "OINV" H JOIN "INV1" D ON D."DocEntry" = H."DocEntry"
          WHERE TO_DATE(H."DocDate") BETWEEN :d0 AND :d1
         UNION ALL
         SELECT 'RIN', '14', D."DocEntry", D."LineNum", TO_DATE(H."DocDate"), D."ItemCode", H."CardCode", H."U_SalOrdType",
                CASE WHEN H."CANCELED" = 'C' THEN 1 ELSE -1 END * D."Quantity", CASE WHEN H."CANCELED" = 'C' THEN 1 ELSE -1 END * D."LineTotal"
           FROM "ORIN" H JOIN "RIN1" D ON D."DocEntry" = H."DocEntry"
          WHERE TO_DATE(H."DocDate") BETWEEN :d0 AND :d1;
    ev = SELECT CAST(CASE WHEN M."K" IS NULL THEN 'NOI' ELSE 'INV' END AS NVARCHAR(3)) AS "Kind", R."ObjType", R."DocEntry", R."LineNum", R."DocDate",
                COALESCE(M."ItemCode", R."ItemCode") AS "ItemCode", COALESCE(M."CardCode", R."CardCode") AS "CardCode", COALESCE(M."SalType", R."SalType") AS "SalType",
                IFNULL(M."Qty", R."Qty") AS "Qty", R."Rev",
                CAST(M."Qty" * IFNULL(M."Price", 0) AS DECIMAL(19,6)) AS "Cost",
                CASE WHEN M."K" IS NOT NULL AND M."Price" IS NULL THEN 1 ELSE 0 END AS "NoCost", 0 AS "NoPrice",
                CAST(M."SrcObj" || '-' || M."SrcEntry" || '-' || M."SrcLine" AS NVARCHAR(60)) AS "SrcKey"
           FROM :rv R
           LEFT JOIN :mv M ON M."K" = R."K" AND M."DocEntry" = R."DocEntry" AND M."LineNum" = R."LineNum"
         UNION ALL
         SELECT 'ACC', S."ObjType", S."DocEntry", S."LineNum", S."DocDate", S."ItemCode", S."CardCode", S."SalType", S."OpenQty",
                S."OpenQty" * S."OrigAmt" / NULLIF(S."OrigQty", 0), S."OpenQty" * IFNULL(C."Price", 0), CASE WHEN C."Price" IS NULL THEN 1 ELSE 0 END,
                CASE WHEN IFNULL(S."OrigAmt", 0) = 0 THEN 1 ELSE 0 END,
                S."ObjType" || '-' || S."DocEntry" || '-' || S."LineNum"
           FROM (SELECT L.*, L."NetQty" - IFNULL(U."Qty", 0) AS "OpenQty"
                   FROM :lns L
                   LEFT JOIN (SELECT "SrcObj", "SrcEntry", "SrcLine", SUM("Qty") AS "Qty" FROM :mv GROUP BY "SrcObj", "SrcEntry", "SrcLine") U
                     ON U."SrcObj" = L."ObjType" AND U."SrcEntry" = L."DocEntry" AND U."SrcLine" = L."LineNum") S
           LEFT JOIN :cst C ON C."ObjType" = S."ObjType" AND C."DocEntry" = S."DocEntry" AND C."LineNum" = S."LineNum"
          WHERE :Basis <> '1' AND S."DocDate" BETWEEN :d0 AND :d1 AND ABS(S."OpenQty") > 0.000001
         UNION ALL
         -- 月结固定：原行发生（取消单反号）
         SELECT 'ACC', S."ObjType", S."DocEntry", S."LineNum", S."DocDate", S."ItemCode", S."CardCode", S."SalType", S."Qty",
                S."Qty" * L."OrigAmt" / NULLIF(L."OrigQty", 0), S."Qty" * IFNULL(C."Price", 0), CASE WHEN C."Price" IS NULL THEN 1 ELSE 0 END,
                CASE WHEN IFNULL(L."OrigAmt", 0) = 0 THEN 1 ELSE 0 END,
                S."ObjType" || '-' || S."DocEntry" || '-' || S."LineNum"
           FROM :src S
           JOIN :lns L ON L."ObjType" = S."ObjType" AND L."DocEntry" = S."DocEntry" AND L."LineNum" = S."LineNum"
           LEFT JOIN :cst C ON C."ObjType" = S."ObjType" AND C."DocEntry" = S."DocEntry" AND C."LineNum" = S."LineNum"
          WHERE :Basis = '1' AND S."DocDate" BETWEEN :d0 AND :d1
         UNION ALL
         -- 月结固定：被开票、贷项、基于交货的退货消耗，冲掉原行的暂估
         SELECT 'ACC', CASE M."K" WHEN 'INV' THEN '13' WHEN 'RIN' THEN '14' ELSE '16' END, M."DocEntry", M."LineNum", M."DocDate", M."ItemCode", M."CardCode", M."SalType", -M."Qty",
                -M."Qty" * M."OrigAmt" / NULLIF(M."OrigQty", 0), -M."Qty" * IFNULL(M."Price", 0), CASE WHEN M."Price" IS NULL THEN 1 ELSE 0 END,
                CASE WHEN IFNULL(M."OrigAmt", 0) = 0 THEN 1 ELSE 0 END,
                M."SrcObj" || '-' || M."SrcEntry" || '-' || M."SrcLine"
           FROM :mv M
          WHERE :Basis = '1' AND M."DocDate" BETWEEN :d0 AND :d1;
    RETURN
    SELECT F."Code" AS "FcCode", E."Kind", E."ObjType", E."DocEntry", E."LineNum", E."DocDate", E."ItemCode", E."CardCode", E."SalType", T."CustType",
           CAST(CASE WHEN LOCATE(:smp, ',' || IFNULL(T."BusiType", '') || ',') > 0 THEN 'Y' ELSE 'N' END AS NVARCHAR(1)) AS "IsSample",
           E."Qty", IFNULL(E."Rev", 0) AS "Rev", IFNULL(E."Cost", 0) AS "Cost", E."NoCost", E."NoPrice", E."SrcKey"
      FROM :ev E
      JOIN "OFPR" F ON E."DocDate" BETWEEN TO_DATE(F."F_RefDate") AND TO_DATE(F."T_RefDate")
      LEFT JOIN :typ T ON T."Name" = E."SalType";
END

@@
-- @stmt 成本报表 21_reports.sql #34
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R22 产品生产成本走势：物料每个月的完工数量、单位成本和料工费委外构成（用户 2026-11-05）。
-- 参数：FcFrom 起始账期（空 = 全部月份）, FcTo 截止账期（空 = 到最新）, Item 产品, ItemGrp 物料组, WorType 订单类型, Basis 0 本级（默认）/ 1 成本还原, STYPE 0 按月 / 1 按产品合计
-- 口径：同 R02（MTC_CA_R_ORDER 本期完工成本），含返工单（用户确认）。没有完工的月份没有行，页面透视后留空。
--       料工费委外两种口径，合计都 = 完工成本（用户 2026-11-06）：
--       本级：人工 / 制造 = 本期分摊到这张订单的（合计 = 当期分摊），委外 = 订单自己的加工费结转（#SUBFEE），材料 = 其余，即领用的材料和半成品全额，半成品里含的人工、制造、委外都算材料。
--       成本还原：四项取 R_ORDER.Cost*，同 R02 的完工成本四项，半成品里含的料工费分回各要素。
-- 环比 = 与该产品上一个有完工月份比。合计的单位成本 = 累计金额 ÷ 累计数量。承接账期及以前的料工费按旧框架完工比例拆分（估算），合计可用。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_22_COSTTREND" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN WorType NVARCHAR(100), IN Basis NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nWt INT; DECLARE f0 NVARCHAR(10); DECLARE f1 NVARCHAR(10); DECLARE bs NVARCHAR(1);
    bs := CASE WHEN :Basis = '1' THEN '1' ELSE '0' END;
    f0 := NULLIF(TRIM(IFNULL(:FcFrom, '')), ''); f1 := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    IF :f0 IS NULL THEN SELECT MIN("Code") INTO f0 FROM "OFPR"; END IF;
    IF :f1 IS NULL THEN SELECT MAX("Code") INTO f1 FROM "OFPR"; END IF;
    runs = SELECT "FcCode", "RunId" FROM "MTC_CA_F_RPT_RUN"(:f0, :f1) WHERE "RunId" IS NOT NULL;
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);    SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp); SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lWt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:WorType); SELECT COUNT(*) INTO nWt FROM :lWt;
    ord = SELECT U."FcCode", O."ItemCode", M."ItemName", TO_NVARCHAR(M."ItmsGrpCod") AS "Grp", G."ItmsGrpNam" AS "GrpName",
                 O."RecvQty", O."CostAmt",
                 CASE WHEN :bs = '1' THEN O."CostMat" ELSE O."CostAmt" - O."AllocLab" - O."AllocMfg" - IFNULL(F."CarSub", 0) END AS "CostMat",
                 CASE WHEN :bs = '1' THEN O."CostLab" ELSE O."AllocLab" END AS "CostLab",
                 CASE WHEN :bs = '1' THEN O."CostMfg" ELSE O."AllocMfg" END AS "CostMfg",
                 CASE WHEN :bs = '1' THEN O."CostSub" ELSE IFNULL(F."CarSub", 0) END AS "CostSub"
            FROM :runs U
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = U."RunId"
            LEFT JOIN "MTC_CA_R_ORDER_MAT" F ON F."RunId" = O."RunId" AND F."OrderType" = O."OrderType" AND F."OrderEntry" = O."OrderEntry" AND F."ItemCode" = '#SUBFEE'
            LEFT JOIN "OITM" M ON M."ItemCode" = O."ItemCode"
            LEFT JOIN "OITB" G ON G."ItmsGrpCod" = M."ItmsGrpCod"
           WHERE (O."RecvQty" <> 0 OR O."CostAmt" <> 0)
             AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE O."ItemCode" LIKE X."P"))
             AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE TO_NVARCHAR(M."ItmsGrpCod") = X."V"))
             AND (:nWt = 0 OR EXISTS (SELECT 1 FROM :lWt X WHERE O."WorType" = X."V"));
    IF :STYPE = '1' THEN
        SELECT "Grp" AS "物料组", MAX("GrpName") AS "物料组名称", "ItemCode" AS "产品", MAX("ItemName") AS "名称",
               COUNT(DISTINCT "FcCode") AS "有完工月数", MIN("FcCode") AS "最早账期", MAX("FcCode") AS "最晚账期",
               CAST(SUM("RecvQty") AS DECIMAL(19,6)) AS "完工数量", CAST(SUM("CostAmt") AS DECIMAL(19,2)) AS "完工成本",
               CAST(SUM("CostAmt") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·合计",
               CAST(SUM("CostMat") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·材料", CAST(SUM("CostLab") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·人工",
               CAST(SUM("CostMfg") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·制造", CAST(SUM("CostSub") / NULLIF(SUM("RecvQty"), 0) AS DECIMAL(19,6)) AS "单位成本·委外"
          FROM :ord
         GROUP BY "Grp", "ItemCode"
         ORDER BY LPAD(IFNULL("Grp", ''), 10, '0'), "ItemCode";
    ELSE
        m = SELECT "FcCode", "Grp", MAX("GrpName") AS "GrpName", "ItemCode", MAX("ItemName") AS "ItemName",
                   SUM("RecvQty") AS "Qty", SUM("CostMat") AS "Mat", SUM("CostLab") AS "Lab", SUM("CostMfg") AS "Mfg", SUM("CostSub") AS "Sub", SUM("CostAmt") AS "Amt"
              FROM :ord GROUP BY "FcCode", "Grp", "ItemCode";
        SELECT "FcCode" AS "账期", "Grp" AS "物料组", "GrpName" AS "物料组名称", "ItemCode" AS "产品", "ItemName" AS "名称",
               CAST("Qty" AS DECIMAL(19,6)) AS "完工数量", CAST("Amt" AS DECIMAL(19,2)) AS "完工成本",
               CAST("UC" AS DECIMAL(19,6)) AS "单位成本·合计",
               CAST("Mat" / NULLIF("Qty", 0) AS DECIMAL(19,6)) AS "单位成本·材料", CAST("Lab" / NULLIF("Qty", 0) AS DECIMAL(19,6)) AS "单位成本·人工",
               CAST("Mfg" / NULLIF("Qty", 0) AS DECIMAL(19,6)) AS "单位成本·制造", CAST("Sub" / NULLIF("Qty", 0) AS DECIMAL(19,6)) AS "单位成本·委外",
               CAST(("UC" - "PrevUC") * 100 / NULLIF(ABS("PrevUC"), 0) AS DECIMAL(19,2)) AS "单位成本环比 %"
          FROM (SELECT A.*, A."Amt" / NULLIF(A."Qty", 0) AS "UC",
                       LAG(A."Amt" / NULLIF(A."Qty", 0)) OVER (PARTITION BY A."ItemCode" ORDER BY A."FcCode") AS "PrevUC"
                  FROM :m A)
         ORDER BY LPAD(IFNULL("Grp", ''), 10, '0'), "ItemCode", "FcCode";
    END IF;
END

@@
-- @stmt 成本报表 21_reports.sql #35
-- @needs @MTC_SALORDTYPE,@MTC_OMRV,@MTC_COST_IOTYPE,OINV.U_SalOrdType,ORIN.U_SalOrdType,ODLN.U_SalOrdType,ORDN.U_SalOrdType,PDN1.U_InitPrice,PDN1.U_IsPrice
-- ---------------------------------------------------------------------
-- R23 产品销售毛利走势：物料每个月的收入、成本、毛利，已开票 + 暂估（用户 2026-11-05）。
-- 参数：FcFrom 起始账期（空 = 全部月份）, FcTo 截止账期（空 = 到本月）, Item 物料, ItemGrp 物料组, Cust 客户, CustType 客户类型, SalType 销售订单类型,
--       InclSample 含样品 Y/N（默认 N）, Basis 0 随时看 / 1 月结固定, STYPE 0 按月 × 物料 / 1 按物料合计 / 2 按月合计 / 3 单据行
-- 口径：MTC_CA_F_SALE_TREND。业务端，随时可查，和凭证、总账无关，不要求账期已生成凭单。
--       暂估收入取交货行金额，暂估成本取成本单价。
--       随时看：当月 = 当月发票 + 当月交货中至今未开票的部分，不做冲回；开票后这笔货从交货月移到开票月，以前月份的数会随后续开票变化。
--       月结固定（给管理层，用户 2026-11-06）：当月 = 当月发票 + 期末暂估 − 期初暂估，只列已结账账期（已生成凭单、B1 已锁定且已计算、承接及以前的历史期），月份的数不再变。
--       “结账后补单行数”：月结固定下，单据创建日晚于该期所用运行完成日、日期又落在该期的行，不为 0 说明有人往已结账期补了单，这个月的数变过。
--       没有消耗交货的发票 / 贷项放在“(未归属产品)”一行，只有收入。成本单价缺失的行成本按 0，列“缺成本单价行数”提示；交货行金额为 0 的未开票行列“缺销售单价行数”提示。
-- ---------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE "MTC_CA_RPT_23_MARGINTREND" (
    IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN Item NVARCHAR(5000), IN ItemGrp NVARCHAR(5000), IN Cust NVARCHAR(5000),
    IN CustType NVARCHAR(200), IN SalType NVARCHAR(500), IN InclSample NVARCHAR(1), IN Basis NVARCHAR(1), IN STYPE NVARCHAR(1))
LANGUAGE SQLSCRIPT READS SQL DATA AS
BEGIN
    DECLARE bs NVARCHAR(1);
    DECLARE dA DATE; DECLARE dB DATE; DECLARE f0 NVARCHAR(10); DECLARE f1 NVARCHAR(10);
    DECLARE nItem INT; DECLARE nGrp INT; DECLARE nCust INT; DECLARE nCt INT; DECLARE nSt INT;
    f0 := NULLIF(TRIM(IFNULL(:FcFrom, '')), ''); f1 := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    IF :f0 IS NULL THEN SELECT MIN("Code") INTO f0 FROM "OFPR"; END IF;
    IF :f1 IS NULL THEN f1 := TO_NVARCHAR(CURRENT_DATE, 'YYYY-MM'); END IF;
    SELECT MIN(TO_DATE("F_RefDate")), MAX(TO_DATE("T_RefDate")) INTO dA, dB FROM "OFPR" WHERE "Code" BETWEEN :f0 AND :f1;
    bs := CASE WHEN :Basis = '1' THEN '1' ELSE '0' END;
    -- 已结账账期：已生成凭单、B1 已锁定且已计算、承接及以前的历史期。EndTime = 该期所用运行完成时间
    pd = SELECT "FcCode", "EndTime" FROM "MTC_CA_F_RPT_RUN"(:f0, :f1)
          WHERE "PStatus" IN ('POSTED', 'HIST') OR ("PStatus" = 'LOCKED' AND "RunId" IS NOT NULL);
    lItem = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Item);     SELECT COUNT(*) INTO nItem FROM :lItem;
    lGrp  = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:ItemGrp);  SELECT COUNT(*) INTO nGrp FROM :lGrp;
    lCust = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:Cust);     SELECT COUNT(*) INTO nCust FROM :lCust;
    lCt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:CustType); SELECT COUNT(*) INTO nCt FROM :lCt;
    lSt   = SELECT "V", "P" FROM "MTC_CA_F_RPT_LIST"(:SalType);  SELECT COUNT(*) INTO nSt FROM :lSt;
    al = SELECT E.*, CAST(CASE WHEN E."Kind" = 'NOI' THEN '(未归属产品)' ELSE E."ItemCode" END AS NVARCHAR(50)) AS "KItem",
                TO_NVARCHAR(I."ItmsGrpCod") AS "Grp", G."ItmsGrpNam" AS "GrpName", I."ItemName", C."CardName"
           FROM "MTC_CA_F_SALE_TREND"(:dA, :dB, :bs) E
           LEFT JOIN "OITM" I ON I."ItemCode" = E."ItemCode"
           LEFT JOIN "OITB" G ON G."ItmsGrpCod" = I."ItmsGrpCod"
           LEFT JOIN "OCRD" C ON C."CardCode" = E."CardCode";
    -- 单据创建日：只用来标“结账后补单”，随时看不用
    crt = SELECT '13' AS "ObjType", "DocEntry", "CreateDate" FROM "OINV" UNION ALL SELECT '14', "DocEntry", "CreateDate" FROM "ORIN"
          UNION ALL SELECT '15', "DocEntry", "CreateDate" FROM "ODLN" UNION ALL SELECT '16', "DocEntry", "CreateDate" FROM "ORDN";
    f = SELECT A.*, CASE WHEN :bs = '1' AND TO_DATE(C."CreateDate") > TO_DATE(P."EndTime") THEN 1 ELSE 0 END AS "Late"
          FROM :al A
          LEFT JOIN :pd P ON P."FcCode" = A."FcCode"
          LEFT JOIN :crt C ON C."ObjType" = A."ObjType" AND C."DocEntry" = A."DocEntry"
         WHERE (IFNULL(:InclSample, 'N') = 'Y' OR A."IsSample" = 'N')
           AND (:bs = '0' OR P."FcCode" IS NOT NULL)
           AND (:nItem = 0 OR EXISTS (SELECT 1 FROM :lItem X WHERE A."KItem" LIKE X."P"))
           AND (:nGrp = 0 OR EXISTS (SELECT 1 FROM :lGrp X WHERE A."Grp" = X."V"))
           AND (:nCust = 0 OR EXISTS (SELECT 1 FROM :lCust X WHERE A."CardCode" LIKE X."P"))
           AND (:nCt = 0 OR EXISTS (SELECT 1 FROM :lCt X WHERE A."CustType" = X."V"))
           AND (:nSt = 0 OR EXISTS (SELECT 1 FROM :lSt X WHERE A."SalType" = X."V"));
    IF :STYPE = '3' THEN
        SELECT F."FcCode" AS "账期", CASE F."Kind" WHEN 'INV' THEN '已开票' WHEN 'ACC' THEN CASE WHEN :bs = '1' THEN '暂估变动' ELSE '暂估（至今未开票）' END ELSE '未归属' END AS "类别",
               CASE F."ObjType" WHEN '13' THEN '应收发票' WHEN '14' THEN '应收贷项' WHEN '15' THEN '交货' ELSE '销售退货' END AS "单据",
               COALESCE(H13."DocNum", H14."DocNum", H15."DocNum", H16."DocNum") AS "单号 Num", F."DocEntry" AS "单号 Entry", F."LineNum" AS "行号", F."DocDate" AS "日期",
               F."CardCode" AS "客户", F."CardName" AS "客户名称", F."CustType" AS "客户类型", F."SalType" AS "销售订单类型", F."IsSample" AS "样品",
               F."ItemCode" AS "物料", F."ItemName" AS "物料名称", F."Qty" AS "数量",
               CAST(F."Rev" / NULLIF(F."Qty", 0) AS DECIMAL(19,6)) AS "销售单价", CAST(F."Rev" AS DECIMAL(19,2)) AS "收入",   -- 单价 = 金额 ÷ 数量（用户 2026-11-06），纯金额行没有数量时留空
               CAST(CASE WHEN F."NoCost" = 1 THEN NULL ELSE F."Cost" / NULLIF(F."Qty", 0) END AS DECIMAL(19,6)) AS "成本单价", CAST(F."Cost" AS DECIMAL(19,2)) AS "成本",   -- 缺成本单价的行留空，不显示 0
               CAST(F."Rev" - F."Cost" AS DECIMAL(19,2)) AS "毛利", F."SrcKey" AS "来源行",
               CASE WHEN F."NoCost" = 1 THEN '缺成本单价' WHEN F."NoPrice" = 1 THEN '交货行金额为 0' WHEN F."Late" = 1 THEN '结账后补单' END AS "说明"
          FROM :f F
          LEFT JOIN "OINV" H13 ON F."ObjType" = '13' AND H13."DocEntry" = F."DocEntry"
          LEFT JOIN "ORIN" H14 ON F."ObjType" = '14' AND H14."DocEntry" = F."DocEntry"
          LEFT JOIN "ODLN" H15 ON F."ObjType" = '15' AND H15."DocEntry" = F."DocEntry"
          LEFT JOIN "ORDN" H16 ON F."ObjType" = '16' AND H16."DocEntry" = F."DocEntry"
         ORDER BY F."DocDate", F."ObjType", F."DocEntry", F."LineNum", F."Kind";
    ELSE
        -- 分组键先在子查询里算好（HANA 不认 SELECT / GROUP BY 中带参数的 CASE 是同一表达式）
        SELECT F."KFc" AS "账期", F."KGrp" AS "物料组", MAX(F."KGrpName") AS "物料组名称", F."KIt" AS "物料", MAX(F."KName") AS "物料名称",
               CAST(SUM(F."QtyInv") AS DECIMAL(19,6)) AS "数量·已开票", CAST(SUM(F."QtyAcc") AS DECIMAL(19,6)) AS "数量·暂估", CAST(SUM(F."QtyInv" + F."QtyAcc") AS DECIMAL(19,6)) AS "数量·合计",
               CAST(SUM(F."RevInv") AS DECIMAL(19,2)) AS "收入·已开票", CAST(SUM(F."RevAcc") AS DECIMAL(19,2)) AS "收入·暂估", CAST(SUM(F."Rev") AS DECIMAL(19,2)) AS "收入·合计",
               CAST(SUM(F."CostInv") AS DECIMAL(19,2)) AS "成本·已开票", CAST(SUM(F."CostAcc") AS DECIMAL(19,2)) AS "成本·暂估", CAST(SUM(F."Cost") AS DECIMAL(19,2)) AS "成本·合计",
               CAST(SUM(F."Rev") - SUM(F."Cost") AS DECIMAL(19,2)) AS "毛利",
               CAST((SUM(F."Rev") - SUM(F."Cost")) * 100 / NULLIF(SUM(F."Rev"), 0) AS DECIMAL(19,2)) AS "毛利率 %",
               CAST(SUM(F."Rev") / NULLIF(SUM(F."QtyInv" + F."QtyAcc"), 0) AS DECIMAL(19,6)) AS "单位售价",
               CAST(SUM(F."Cost") / NULLIF(SUM(F."QtyInv" + F."QtyAcc"), 0) AS DECIMAL(19,6)) AS "单位成本",
               SUM(F."NoCost") AS "缺成本单价行数", SUM(F."NoPrice") AS "缺销售单价行数", SUM(F."Late") AS "结账后补单行数"
          FROM (SELECT B."Rev", B."Cost", B."NoCost", B."NoPrice", B."Late",
                       CASE WHEN :STYPE = '1' THEN NULL ELSE B."FcCode" END AS "KFc",
                       CASE WHEN :STYPE = '2' THEN NULL ELSE B."KItem" END AS "KIt",
                       CASE WHEN :STYPE = '2' OR B."Kind" = 'NOI' THEN NULL ELSE B."Grp" END AS "KGrp",
                       CASE WHEN :STYPE = '2' OR B."Kind" = 'NOI' THEN NULL ELSE B."GrpName" END AS "KGrpName",
                       CASE WHEN :STYPE = '2' THEN NULL WHEN B."Kind" = 'NOI' THEN '服务、直接开票、纯金额贷项' ELSE B."ItemName" END AS "KName",
                       CASE WHEN B."Kind" = 'ACC' THEN 0 ELSE B."Qty" END AS "QtyInv", CASE WHEN B."Kind" = 'ACC' THEN B."Qty" ELSE 0 END AS "QtyAcc",
                       CASE WHEN B."Kind" = 'ACC' THEN 0 ELSE B."Rev" END AS "RevInv", CASE WHEN B."Kind" = 'ACC' THEN B."Rev" ELSE 0 END AS "RevAcc",
                       CASE WHEN B."Kind" = 'ACC' THEN 0 ELSE B."Cost" END AS "CostInv", CASE WHEN B."Kind" = 'ACC' THEN B."Cost" ELSE 0 END AS "CostAcc"
                  FROM :f B) F
         GROUP BY F."KFc", F."KGrp", F."KIt"
         ORDER BY LPAD(IFNULL(F."KGrp", 'zzzzzzzzzz'), 10, '0'), F."KIt", F."KFc";
    END IF;
END

@@
-- @stmt 历史回填 22_legacy_load.sql #1
-- @needs MTC_COST_0301_INVNT,MTC_COST_0302_INVNTDETAIL1,MTC_COST_0321_OWOR,MTC_COST_0321_OWOR1,MTC_COST_0321_OWOR1_REG,MTC_COST_0321_OWOR_SUM,MTC_COST_0322_OWOR_ZCP,MTC_COST_0322_OWOR_ZCP1,MTC_COST_0801_TOOJDT,MTC_COST_0802_OJDTBASEDETAIL,U_COILV,@MTC_OWOR,@MTC_WOR1,@U_CIOTRN,@MTC_COST_IOTYPE
-- =====================================================================
-- 新旧报表合并：旧框架历史回填成“历史运行”（RunType H，Scenario LEGACY；方案见 新框架/报表合并方案.md，用户 2026-11-02 确认）
-- CALL "MTC_CA_P_LEGACY_LOAD"('2024-12', '2026-08', 'manager');   -- 账期从早到晚逐期回填，每期提交一次，可重跑
-- 把旧 MTC_COST_* 结果转换写进 MTC_CA_S_* / R_*，成本报表 MTC_CA_RPT_* 经 MTC_CA_F_RPT_RUN 在承接账期（BOOTSTRAP_FC）及以前取这些运行，
-- 从上线（2024-12）起跨期连续可查。只读旧表和 B1 表，只写 MTC_CA_* 表；不改旧数据，旧框架已知缺陷照原样带过来（22_legacy_verify.sql 列出）。
--
-- 各表来源（一期一次 H 运行，RunId 取 MTC_CA_SEQ_RUN）：
--   S_LINE / R_LINE      ← 0302_INVNTDETAIL1（CostCode 20，一行 = 一条库存变动；单号、日期、交易类型、仓库、科目、订单照抄），金额按物料比例拆四项
--   R_ITEM               ← 期初 = 上期 H 运行期末四项（第一期取 0301 期初按本期比例拆）；入库 = 本期入库行；期末 = 0301 期末按本期比例拆；
--                          出库四项倒挤（期初 + 入库 + 出库 = 期末）；旧框架期末 ≠ 期初 + 收发的差额记 TailAmt（R03“尾差结转”列）
--   S_ITEM               ← U_COILV 该期层级 + OITM
--   S_ORDER / R_ORDER    ← 0321_OWOR_SUM（本期完工成本：1Material / 2ManExp 制造 / 3LabAmount 人工 / 4WWExp 委外）+ OWOR / @MTC_OWOR
--   R_ORDER_MAT          ← 期初 = 上期 H 运行（第一期取 0321_OWOR1 累计领料和上期 0322_OWOR_ZCP1 在产品）；本期领料 = 0321_OWOR1；
--                          完工转出 = 1Material 按 0321_OWOR1_REG（各材料完工结转）的比例分到材料；委外加工费一行 '#SUBFEE'（旧框架当期全部转出）；
--                          期末在产品倒挤（同旧 ZCP：累计领料 − 累计完工材料 − 关单差异）；截至期末已关闭的订单，剩余全部转关单差异
--   R_ALLOC / R_POOL     ← 0321_OWOR_SUM 的 2ManExp / 3LabAmount（旧框架没有费用池明细，一个虚拟池 LEGACY，没有工时）
--   R_JDT / R_JDT_SRC    ← 0801_TOOJDT / 0802_OJDTBASEDETAIL；0802 对不上分录的差额补一行来源 LEGACY（V06 来源 = 分录）
-- 料工费比例：MTC_CA_P_LEGACY_RATIO（09_bootstrap.sql，与期初承接共用），每期按截至该期最近一个有完工的账期算；
--   没有完工记录的物料（采购件等）全部记材料。所以历史期的料工费是按旧完工比例估算的，不是逐级算出来的构成。
-- 不回填：发出商品（R_GOODS_*）、应付暂估（S_AP_MOVE / R_AP_ACCR）、计算前后校验（R_CHECK）、新旧比对，相关报表在历史期提示“无此数据”。
-- 只允许账期 ≤ BOOTSTRAP_FC；以后的账期由新框架计算。回填某一期后，它以后已回填的各期要一起重新回填（期初取上期 H 运行）。
-- 离线写的，还没编译（2026-11-02）。部署在 09、21 之后。
-- =====================================================================
CREATE OR REPLACE PROCEDURE "MTC_CA_P_LEGACY_LOAD1" (IN FcCode NVARCHAR(10), IN UserCode NVARCHAR(50), OUT oCode INT, OUT oMsg NVARCHAR(2000))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE d0 DATE; DECLARE d1 DATE;
    DECLARE boot NVARCHAR(10); DECLARE prevFc NVARCHAR(10);
    DECLARE rid BIGINT; DECLARE prevRid BIGINT;
    DECLARE n0301 BIGINT; DECLARE nLine BIGINT; DECLARE nItem BIGINT; DECLARE nOrd BIGINT; DECLARE nMat BIGINT; DECLARE nJdt BIGINT;
    DECLARE nTail BIGINT; DECLARE nCln BIGINT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        oCode := -1;
        oMsg := :FcCode || ' 回填出错：' || ::SQL_ERROR_MESSAGE;
        IF :rid IS NOT NULL THEN
            UPDATE "MTC_CA_RUN" SET "Status" = 'FAIL', "EndTime" = CURRENT_TIMESTAMP, "Msg" = LEFT(:oMsg, 2000) WHERE "RunId" = :rid;
            COMMIT;
        END IF;
    END;
    oCode := -1;
    SELECT MAX(TO_DATE("F_RefDate")), MAX(TO_DATE("T_RefDate")) INTO d0, d1 FROM "OFPR" WHERE "Code" = :FcCode;
    IF :d1 IS NULL THEN
        oMsg := '账期不存在：' || IFNULL(:FcCode, '');
        RETURN;
    END IF;
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', :FcCode);
    IF :boot IS NULL OR :FcCode > :boot THEN
        oMsg := :FcCode || ' 在承接账期 BOOTSTRAP_FC（' || IFNULL(:boot, '没有配置') || '）以后，由新框架计算，不回填';
        RETURN;
    END IF;
    SELECT COUNT(*) INTO n0301 FROM "MTC_COST_0301_INVNT" WHERE "FcCode" = :FcCode AND "CostCode" = '20';
    IF :n0301 = 0 THEN
        oMsg := :FcCode || ' 旧框架没有结果（MTC_COST_0301_INVNT 没有这一期），先在旧框架算完这一期';
        RETURN;
    END IF;
    SELECT MAX("Code") INTO prevFc FROM "OFPR" WHERE "Code" < :FcCode;
    SELECT MAX("RunId") INTO prevRid FROM "MTC_CA_RUN"
     WHERE "FcCode" = :prevFc AND "RunType" = 'H' AND "Scenario" = 'LEGACY' AND "Status" = 'OK';

    SELECT "MTC_CA_SEQ_RUN".NEXTVAL INTO rid FROM DUMMY;
    -- 运行头单独提交：出错回滚时运行记录仍在（同 MTC_CA_P_RUN_START）
    BEGIN AUTONOMOUS TRANSACTION
        INSERT INTO "MTC_CA_RUN" ("RunId", "FcCode", "RunType", "Scenario", "Initiator", "UserCode", "StartTime", "Status", "Converged", "Msg")
        VALUES (:rid, :FcCode, 'H', 'LEGACY', 'USER', :UserCode, CURRENT_TIMESTAMP, 'RUNNING', 'Y', '旧框架历史回填');
    END;

    -- 料工费比例（与期初承接同一算法）
    CALL "MTC_CA_P_LEGACY_RATIO"(:FcCode, rat);

    -- ---------------- 单据行：0302（CostCode 20） ----------------
    src = SELECT D."ID", IFNULL(D."ObjType", '') AS "ObjType", IFNULL(D."DocEntry", 0) AS "DocEntry", D."DocNum", D."LineNum",
                 IFNULL(D."DocDate", :d1) AS "DocDate", D."TransCode", D."BaseType", D."BaseEntry", D."BaseLine", D."ItemCode", D."WhsCode",
                 IFNULL(D."Quantity", 0) AS "Qty", IFNULL(D."Amount", 0) AS "Amt", D."Price", D."BusiType", D."OcrCode1",
                 COALESCE(NULLIF(D."AcctCode", ''), NULLIF(D."AcctCOde", '')) AS "Acct", D."IsUpdatePrice"
            FROM "MTC_COST_0302_INVNTDETAIL1" D
           WHERE D."FcCode" = :FcCode AND D."CostCode" = '20' AND D."ItemCode" IS NOT NULL;
    ln = SELECT ROW_NUMBER() OVER (ORDER BY S."DocDate", S."ObjType", S."DocEntry", S."LineNum", S."ID") AS "LineId", S.*,
                CASE WHEN S."ObjType" IN ('59', '60') AND S."BaseType" IN ('202', 'MTC_OWOR') AND S."BaseEntry" IS NOT NULL THEN S."BaseType" END AS "OT",
                IFNULL(R."RMfg", 0) AS "rF", IFNULL(R."RLab", 0) AS "rL", IFNULL(R."RSub", 0) AS "rS"
           FROM :src S
           LEFT JOIN :rat R ON R."ItemCode" = S."ItemCode";

    INSERT INTO "MTC_CA_S_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "Src", "SrcKey", "ObjType", "DocEntry", "DocNum", "LineNum",
                                 "Canceled", "DocDate", "ItemCode", "WhsCode", "Qty", "TransCode", "Dir", "BusiType", "BusiClass",
                                 "BaseType", "BaseEntry", "BaseLine", "OrderType", "OrderEntry", "OrderLine", "AcctCode", "OcrCode", "SharedExp", "NoCost")
    SELECT :FcCode, 'H', 'LEGACY', :rid, L."LineId", 'LEGACY', IFNULL(TO_NVARCHAR(L."ID"), 'L' || TO_NVARCHAR(L."LineId")),
           LEFT(L."ObjType", 20), L."DocEntry", TO_NVARCHAR(L."DocNum"), L."LineNum", 'N', L."DocDate", LEFT(L."ItemCode", 50), LEFT(L."WhsCode", 8), L."Qty",
           LEFT(L."TransCode", 10), T."U_IOType", LEFT(L."BusiType", 20), C."U_TransType",
           LEFT(L."BaseType", 20), TO_NVARCHAR(L."BaseEntry"), TO_NVARCHAR(L."BaseLine"),
           L."OT", CASE WHEN L."OT" IS NOT NULL THEN L."BaseEntry" END, CASE WHEN L."OT" IS NOT NULL THEN L."BaseLine" END,
           LEFT(L."Acct", 15), LEFT(L."OcrCode1", 20), 'N', 'N'
      FROM :ln L
      LEFT JOIN "@MTC_COST_IOTYPE" T ON T."Code" = L."TransCode"
      LEFT JOIN "@U_CIOTRN" C ON C."Code" = L."BusiType" AND L."ObjType" IN ('59', '60');
    nLine := ::ROWCOUNT;

    -- 金额按物料比例拆四项：制造、人工、委外四舍五入到分，材料 = 金额 − 其余三项（合计不变，同期初承接）
    INSERT INTO "MTC_CA_R_LINE" ("FcCode", "RunType", "Scenario", "RunId", "LineId", "ItemCode", "TransCode", "Qty", "Cat", "InVal",
                                 "OrderType", "OrderEntry", "IsShared", "MatAmt", "MfgAmt", "LabAmt", "SubAmt", "Amount", "Price", "PriceSrc", "RuleId", "Iter")
    SELECT :FcCode, 'H', 'LEGACY', :rid, L."LineId", LEFT(L."ItemCode", 50), LEFT(L."TransCode", 10), L."Qty", 'LEGACY', 'N',
           L."OT", CASE WHEN L."OT" IS NOT NULL THEN L."BaseEntry" END, 'N',
           L."Amt" - ROUND(L."Amt" * L."rF", 2) - ROUND(L."Amt" * L."rL", 2) - ROUND(L."Amt" * L."rS", 2),
           ROUND(L."Amt" * L."rF", 2), ROUND(L."Amt" * L."rL", 2), ROUND(L."Amt" * L."rS", 2), L."Amt",
           L."Price", LEFT('旧 0302' || CASE WHEN IFNULL(L."IsUpdatePrice", '') <> '' THEN ' ' || L."IsUpdatePrice" ELSE '' END, 200), 'LEGACY', 0
      FROM :ln L;

    -- ---------------- 物料：R_ITEM、S_ITEM ----------------
    inv = SELECT I."ItemCode", SUM(IFNULL(I."QC_Qty", 0)) AS "QCQ", SUM(IFNULL(I."QC_Amount", 0)) AS "QCA",
                 SUM(IFNULL(I."QM_Qty", 0)) AS "QMQ", SUM(IFNULL(I."QM_Amount", 0)) AS "QMA", MAX(I."iLevel") AS "Lv"
            FROM "MTC_COST_0301_INVNT" I
           WHERE I."FcCode" = :FcCode AND I."CostCode" = '20'
           GROUP BY I."ItemCode";
    -- 期初：有上期 H 运行取它的期末；没有（回填的第一期）取 0301 期初按本期比例拆
    op = SELECT "ItemCode", CAST("EndQty" AS DECIMAL(19,6)) AS "Q", CAST("EndMat" AS DECIMAL(19,6)) AS "M", CAST("EndMfg" AS DECIMAL(19,6)) AS "F",
                CAST("EndLab" AS DECIMAL(19,6)) AS "L", CAST("EndSub" AS DECIMAL(19,6)) AS "S"
           FROM "MTC_CA_R_ITEM" WHERE "RunId" = :prevRid
         UNION ALL
         SELECT I."ItemCode", CAST(I."QCQ" AS DECIMAL(19,6)),
                CAST(I."QCA" - ROUND(I."QCA" * IFNULL(R."RMfg", 0), 2) - ROUND(I."QCA" * IFNULL(R."RLab", 0), 2) - ROUND(I."QCA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6)),
                CAST(ROUND(I."QCA" * IFNULL(R."RMfg", 0), 2) AS DECIMAL(19,6)), CAST(ROUND(I."QCA" * IFNULL(R."RLab", 0), 2) AS DECIMAL(19,6)),
                CAST(ROUND(I."QCA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6))
           FROM :inv I LEFT JOIN :rat R ON R."ItemCode" = I."ItemCode"
          WHERE :prevRid IS NULL;
    -- 入库 = 数量为正（数量为 0 的发票差额、重估按交易类型方向）的行，同 R03 口径
    lin = SELECT L."ItemCode",
                 SUM(CASE WHEN L."Qty" > 0 OR (L."Qty" = 0 AND IFNULL(S."Dir", 'I') = 'I') THEN L."Qty" ELSE 0 END) AS "IQ",
                 SUM(CASE WHEN L."Qty" > 0 OR (L."Qty" = 0 AND IFNULL(S."Dir", 'I') = 'I') THEN L."MatAmt" ELSE 0 END) AS "IM",
                 SUM(CASE WHEN L."Qty" > 0 OR (L."Qty" = 0 AND IFNULL(S."Dir", 'I') = 'I') THEN L."MfgAmt" ELSE 0 END) AS "IFg",
                 SUM(CASE WHEN L."Qty" > 0 OR (L."Qty" = 0 AND IFNULL(S."Dir", 'I') = 'I') THEN L."LabAmt" ELSE 0 END) AS "IL",
                 SUM(CASE WHEN L."Qty" > 0 OR (L."Qty" = 0 AND IFNULL(S."Dir", 'I') = 'I') THEN L."SubAmt" ELSE 0 END) AS "ISb",
                 SUM(L."Amount") AS "Net"
            FROM "MTC_CA_R_LINE" L JOIN "MTC_CA_S_LINE" S ON S."RunId" = L."RunId" AND S."LineId" = L."LineId"
           WHERE L."RunId" = :rid
           GROUP BY L."ItemCode";
    ikey = SELECT "ItemCode" FROM :inv WHERE "QCQ" <> 0 OR "QCA" <> 0 OR "QMQ" <> 0 OR "QMA" <> 0
           UNION SELECT "ItemCode" FROM :op WHERE "Q" <> 0 OR "M" <> 0 OR "F" <> 0 OR "L" <> 0 OR "S" <> 0
           UNION SELECT "ItemCode" FROM :lin;
    it = SELECT K."ItemCode",
                COALESCE(V."iLevel", I."Lv", -1) AS "Lv",
                IFNULL(O."Q", 0) AS "OQ", IFNULL(O."M", 0) AS "OM", IFNULL(O."F", 0) AS "OFg", IFNULL(O."L", 0) AS "OL", IFNULL(O."S", 0) AS "OS",
                IFNULL(N."IQ", 0) AS "IQ", IFNULL(N."IM", 0) AS "IM", IFNULL(N."IFg", 0) AS "IFg", IFNULL(N."IL", 0) AS "IL", IFNULL(N."ISb", 0) AS "ISb",
                IFNULL(N."Net", 0) AS "Net",
                IFNULL(I."QMQ", 0) AS "EQ",
                IFNULL(I."QMA", 0) - ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RMfg", 0), 2) - ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RLab", 0), 2)
                                   - ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RSub", 0), 2) AS "EM",
                ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RMfg", 0), 2) AS "EF", ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RLab", 0), 2) AS "EL",
                ROUND(IFNULL(I."QMA", 0) * IFNULL(R."RSub", 0), 2) AS "ES",
                IFNULL(I."QMA", 0) AS "EA"
           FROM :ikey K
           LEFT JOIN :inv I ON I."ItemCode" = K."ItemCode"
           LEFT JOIN :op O ON O."ItemCode" = K."ItemCode"
           LEFT JOIN :lin N ON N."ItemCode" = K."ItemCode"
           LEFT JOIN :rat R ON R."ItemCode" = K."ItemCode"
           LEFT JOIN (SELECT "ItemCode", MAX("iLevel") AS "iLevel" FROM "U_COILV" WHERE "FcCode" = :FcCode GROUP BY "ItemCode") V ON V."ItemCode" = K."ItemCode";
    it2 = SELECT T.*, T."EQ" - T."OQ" - T."IQ" AS "XQ",
                 T."EM" - T."OM" - T."IM" AS "XM", T."EF" - T."OFg" - T."IFg" AS "XF", T."EL" - T."OL" - T."IL" AS "XL", T."ES" - T."OS" - T."ISb" AS "XS",
                 T."EA" - (T."OM" + T."OFg" + T."OL" + T."OS") - T."Net" AS "Tail"
            FROM :it T;
    INSERT INTO "MTC_CA_R_ITEM" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "iLevel",
        "OpenQty", "OpenMat", "OpenMfg", "OpenLab", "OpenSub", "PMat", "PMfg", "PLab", "PSub", "PriceSrc",
        "InQty", "InMat", "InMfg", "InLab", "InSub", "OutQty", "OutMat", "OutMfg", "OutLab", "OutSub",
        "EndQty", "EndMat", "EndMfg", "EndLab", "EndSub", "EndAmount", "Flags", "TailAmt",
        "RtOpenMat", "RtOpenLab", "RtOpenMfg", "RtOpenSub", "RtInMat", "RtInLab", "RtInMfg", "RtInSub",
        "RtOutMat", "RtOutLab", "RtOutMfg", "RtOutSub", "RtEndMat", "RtEndLab", "RtEndMfg", "RtEndSub")
    SELECT :FcCode, 'H', 'LEGACY', :rid, LEFT(T."ItemCode", 50), T."Lv",
           T."OQ", T."OM", T."OFg", T."OL", T."OS",
           CASE WHEN T."EQ" <> 0 THEN T."EM" / T."EQ" ELSE 0 END, CASE WHEN T."EQ" <> 0 THEN T."EF" / T."EQ" ELSE 0 END,
           CASE WHEN T."EQ" <> 0 THEN T."EL" / T."EQ" ELSE 0 END, CASE WHEN T."EQ" <> 0 THEN T."ES" / T."EQ" ELSE 0 END, 'LEGACY',
           T."IQ", T."IM", T."IFg", T."IL", T."ISb", T."XQ", T."XM", T."XF", T."XL", T."XS",
           T."EQ", T."EM", T."EF", T."EL", T."ES", T."EA",
           CASE WHEN ABS(T."Tail") >= 0.005 THEN '旧框架期末 ≠ 期初 + 收发，差额记尾差' END, T."Tail",
           CASE WHEN T."OM" + T."OFg" + T."OL" + T."OS" <> 0 THEN ROUND(T."OM" / (T."OM" + T."OFg" + T."OL" + T."OS") * 100, 4) END,
           CASE WHEN T."OM" + T."OFg" + T."OL" + T."OS" <> 0 THEN ROUND(T."OL" / (T."OM" + T."OFg" + T."OL" + T."OS") * 100, 4) END,
           CASE WHEN T."OM" + T."OFg" + T."OL" + T."OS" <> 0 THEN ROUND(T."OFg" / (T."OM" + T."OFg" + T."OL" + T."OS") * 100, 4) END,
           CASE WHEN T."OM" + T."OFg" + T."OL" + T."OS" <> 0 THEN ROUND(T."OS" / (T."OM" + T."OFg" + T."OL" + T."OS") * 100, 4) END,
           CASE WHEN T."IM" + T."IFg" + T."IL" + T."ISb" <> 0 THEN ROUND(T."IM" / (T."IM" + T."IFg" + T."IL" + T."ISb") * 100, 4) END,
           CASE WHEN T."IM" + T."IFg" + T."IL" + T."ISb" <> 0 THEN ROUND(T."IL" / (T."IM" + T."IFg" + T."IL" + T."ISb") * 100, 4) END,
           CASE WHEN T."IM" + T."IFg" + T."IL" + T."ISb" <> 0 THEN ROUND(T."IFg" / (T."IM" + T."IFg" + T."IL" + T."ISb") * 100, 4) END,
           CASE WHEN T."IM" + T."IFg" + T."IL" + T."ISb" <> 0 THEN ROUND(T."ISb" / (T."IM" + T."IFg" + T."IL" + T."ISb") * 100, 4) END,
           CASE WHEN T."XM" + T."XF" + T."XL" + T."XS" <> 0 THEN ROUND(T."XM" / (T."XM" + T."XF" + T."XL" + T."XS") * 100, 4) END,
           CASE WHEN T."XM" + T."XF" + T."XL" + T."XS" <> 0 THEN ROUND(T."XL" / (T."XM" + T."XF" + T."XL" + T."XS") * 100, 4) END,
           CASE WHEN T."XM" + T."XF" + T."XL" + T."XS" <> 0 THEN ROUND(T."XF" / (T."XM" + T."XF" + T."XL" + T."XS") * 100, 4) END,
           CASE WHEN T."XM" + T."XF" + T."XL" + T."XS" <> 0 THEN ROUND(T."XS" / (T."XM" + T."XF" + T."XL" + T."XS") * 100, 4) END,
           CASE WHEN T."EA" <> 0 THEN ROUND(T."EM" / T."EA" * 100, 4) END, CASE WHEN T."EA" <> 0 THEN ROUND(T."EL" / T."EA" * 100, 4) END,
           CASE WHEN T."EA" <> 0 THEN ROUND(T."EF" / T."EA" * 100, 4) END, CASE WHEN T."EA" <> 0 THEN ROUND(T."ES" / T."EA" * 100, 4) END
      FROM :it2 T;
    nItem := ::ROWCOUNT;
    SELECT COUNT(*) INTO nTail FROM "MTC_CA_R_ITEM" WHERE "RunId" = :rid AND ABS("TailAmt") >= 0.005;

    INSERT INTO "MTC_CA_S_ITEM" ("FcCode", "RunType", "Scenario", "RunId", "ItemCode", "ItemName", "ItmsGrpCod", "GrpType",
                                 "CalType", "InvntItem", "IsBomFather", "iLevel", "LevelSrc", "LevelNote")
    SELECT :FcCode, 'H', 'LEGACY', :rid, R."ItemCode", M."ItemName", TO_NVARCHAR(M."ItmsGrpCod"), G."U_ItemGrpType",
           M."U_ItemProp", M."InvntItem",
           CASE WHEN EXISTS (SELECT 1 FROM "OITT" B WHERE B."Code" = R."ItemCode") THEN 'Y' ELSE 'N' END,
           R."iLevel", 'LEGACY', '旧框架 U_COILV 该期层级'
      FROM "MTC_CA_R_ITEM" R
      LEFT JOIN "OITM" M ON M."ItemCode" = R."ItemCode"
      LEFT JOIN "OITB" G ON G."ItmsGrpCod" = M."ItmsGrpCod"
     WHERE R."RunId" = :rid;

    -- ---------------- 订单 ----------------
    -- 本期完工成本（旧 0402 写的 0321_OWOR_SUM；完工材料 = Amount − 制造 − 人工 − 委外，使四项合计 = 旧 Amount）
    osum = SELECT IFNULL("DocType", '202') AS "OT", TO_INTEGER("WorEntry") AS "OE", MAX("WorType") AS "WT", MAX("ItemCode") AS "Item",
                  MAX("iLevel") AS "Lv", SUM(IFNULL("IgnQty", 0)) AS "Rq", SUM(IFNULL("Amount", 0)) AS "A",
                  SUM(IFNULL("2ManExp", 0)) AS "F", SUM(IFNULL("3LabAmount", 0)) AS "L", SUM(IFNULL("4WWExp", 0)) AS "S"
             FROM "MTC_COST_0321_OWOR_SUM"
            WHERE "FcCode" = :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$'
            GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry")
           HAVING SUM(ABS(IFNULL("IgnQty", 0))) + SUM(ABS(IFNULL("Amount", 0))) + SUM(ABS(IFNULL("2ManExp", 0)))
                  + SUM(ABS(IFNULL("3LabAmount", 0))) + SUM(ABS(IFNULL("4WWExp", 0))) <> 0;
    -- 本期领料（0321_OWOR1 出库为负，取反为正；生产退料为负）
    iss = SELECT IFNULL("DocType", '202') AS "OT", TO_INTEGER("WorEntry") AS "OE", "ItemCode",
                 -SUM(IFNULL("IgeQty", 0)) AS "Q", -SUM(IFNULL("Amount", 0)) AS "A"
            FROM "MTC_COST_0321_OWOR1"
           WHERE "FcCode" = :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$' AND "ItemCode" IS NOT NULL
           GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry"), "ItemCode"
          HAVING SUM(IFNULL("IgeQty", 0)) <> 0 OR SUM(IFNULL("Amount", 0)) <> 0;
    -- 各材料本期完工结转（旧 0402 写的 0321_OWOR1_REG），只用来分摊完工材料
    reg = SELECT IFNULL("DocType", '202') AS "OT", TO_INTEGER("WorEntry") AS "OE", "ItemCode", SUM(IFNULL("Amount", 0)) AS "W"
            FROM "MTC_COST_0321_OWOR1_REG"
           WHERE "FcCode" = :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$' AND "ItemCode" IS NOT NULL
           GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry"), "ItemCode"
          HAVING SUM(IFNULL("Amount", 0)) <> 0;
    -- 期初（订单 × 材料）：有上期 H 运行取它（同 P20_OPEN：累计领料 = 期初 + 领料，累计结转 = 期初 + 结转 + 关单差异，上期按关单处理的订单不带入）；
    -- 没有（回填的第一期）取 0321_OWOR1 截至上期累计领料、上期 0322_OWOR_ZCP1 在产品，累计结转 = 累计领料 − 在产品，按材料比例拆四项
    cum = SELECT IFNULL("DocType", '202') AS "OT", TO_INTEGER("WorEntry") AS "OE", "ItemCode",
                 -SUM(IFNULL("IgeQty", 0)) AS "Q", -SUM(IFNULL("Amount", 0)) AS "A"
            FROM "MTC_COST_0321_OWOR1"
           WHERE "FcCode" < :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$' AND "ItemCode" IS NOT NULL AND :prevRid IS NULL
           GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry"), "ItemCode";
    zp = SELECT IFNULL("DocType", '202') AS "OT", "WorEntry" AS "OE", "ItemCode", SUM(IFNULL("Amount", 0)) AS "A"
           FROM "MTC_COST_0322_OWOR_ZCP1"
          WHERE "FcCode" = :prevFc AND "ItemCode" IS NOT NULL AND :prevRid IS NULL
          GROUP BY IFNULL("DocType", '202'), "WorEntry", "ItemCode";
    old0 = SELECT IFNULL(C."OT", Z."OT") AS "OT", IFNULL(C."OE", Z."OE") AS "OE", IFNULL(C."ItemCode", Z."ItemCode") AS "ItemCode",
                  IFNULL(C."Q", 0) AS "Q", IFNULL(C."A", 0) AS "IA", IFNULL(C."A", 0) - IFNULL(Z."A", 0) AS "CA"
             FROM :cum C FULL JOIN :zp Z ON Z."OT" = C."OT" AND Z."OE" = C."OE" AND Z."ItemCode" = C."ItemCode";
    opn = SELECT M."OrderType" AS "OT", M."OrderEntry" AS "OE", M."ItemCode",
                 CAST(M."OpenIssQty" + M."IssQty" AS DECIMAL(19,6)) AS "Q",
                 CAST(M."OpenIssMat" + M."IssMat" AS DECIMAL(19,6)) AS "IM", CAST(M."OpenIssMfg" + M."IssMfg" AS DECIMAL(19,6)) AS "IFg",
                 CAST(M."OpenIssLab" + M."IssLab" AS DECIMAL(19,6)) AS "IL", CAST(M."OpenIssSub" + M."IssSub" AS DECIMAL(19,6)) AS "ISb",
                 CAST(M."OpenCarMat" + M."CarMat" + M."ClsMat" AS DECIMAL(19,6)) AS "CM", CAST(M."OpenCarMfg" + M."CarMfg" + M."ClsMfg" AS DECIMAL(19,6)) AS "CF",
                 CAST(M."OpenCarLab" + M."CarLab" + M."ClsLab" AS DECIMAL(19,6)) AS "CL", CAST(M."OpenCarSub" + M."CarSub" + M."ClsSub" AS DECIMAL(19,6)) AS "CS"
            FROM "MTC_CA_R_ORDER_MAT" M
            JOIN "MTC_CA_R_ORDER" O ON O."RunId" = M."RunId" AND O."OrderType" = M."OrderType" AND O."OrderEntry" = M."OrderEntry"
           WHERE M."RunId" = :prevRid AND O."ClosedInFc" = 'N'
          UNION ALL
          SELECT X."OT", X."OE", X."ItemCode", CAST(X."Q" AS DECIMAL(19,6)),
                 CAST(X."IA" - ROUND(X."IA" * IFNULL(R."RMfg", 0), 2) - ROUND(X."IA" * IFNULL(R."RLab", 0), 2) - ROUND(X."IA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6)),
                 CAST(ROUND(X."IA" * IFNULL(R."RMfg", 0), 2) AS DECIMAL(19,6)), CAST(ROUND(X."IA" * IFNULL(R."RLab", 0), 2) AS DECIMAL(19,6)),
                 CAST(ROUND(X."IA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6)),
                 CAST(X."CA" - ROUND(X."CA" * IFNULL(R."RMfg", 0), 2) - ROUND(X."CA" * IFNULL(R."RLab", 0), 2) - ROUND(X."CA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6)),
                 CAST(ROUND(X."CA" * IFNULL(R."RMfg", 0), 2) AS DECIMAL(19,6)), CAST(ROUND(X."CA" * IFNULL(R."RLab", 0), 2) AS DECIMAL(19,6)),
                 CAST(ROUND(X."CA" * IFNULL(R."RSub", 0), 2) AS DECIMAL(19,6))
            FROM :old0 X LEFT JOIN :rat R ON R."ItemCode" = X."ItemCode"
           WHERE :prevRid IS NULL
             AND (ABS(X."IA" - X."CA") >= 0.005
                  OR EXISTS (SELECT 1 FROM :osum S WHERE S."OT" = X."OT" AND S."OE" = X."OE")
                  OR EXISTS (SELECT 1 FROM :iss S WHERE S."OT" = X."OT" AND S."OE" = X."OE"));

    -- 订单范围：本期有完工成本、领料、期初在产品的订单
    okey = SELECT "OT", "OE" FROM :osum UNION SELECT "OT", "OE" FROM :iss UNION SELECT "OT", "OE" FROM :opn UNION SELECT "OT", "OE" FROM :reg;
    ord = SELECT '202' AS "OT", W."DocEntry" AS "OE", TO_NVARCHAR(W."DocNum") AS "Num", TO_NVARCHAR(W."U_OrdType") AS "WT", W."ItemCode",
                 W."PlannedQty", TO_DATE(W."PostDate") AS "PostDate", TO_NVARCHAR(W."Status") AS "St", TO_DATE(W."CloseDate") AS "CloseDate", W."CardCode"
            FROM "OWOR" W
          UNION ALL
          SELECT 'MTC_OWOR', M."DocEntry", TO_NVARCHAR(M."DocNum"), TO_NVARCHAR(M."U_OrdType"), M."U_ItemCode", M."U_PlannedQty",
                 TO_DATE(M."U_PostDate"), TO_NVARCHAR(M."U_Status"), TO_DATE(M."U_CloseDate"), M."U_CardCode"
            FROM "@MTC_OWOR" M;
    -- 截至上期累计入库：0321_OWOR 以前各期合计（上期没有动静的订单不在上期 H 运行里，所以不从它取）
    prq = SELECT IFNULL("DocType", '202') AS "OT", TO_INTEGER("WorEntry") AS "OE", SUM(IFNULL("IgnQty", 0)) AS "Q"
            FROM "MTC_COST_0321_OWOR"
           WHERE "FcCode" < :FcCode AND TO_NVARCHAR("WorEntry") LIKE_REGEXPR '^[0-9]+$'
           GROUP BY IFNULL("DocType", '202'), TO_INTEGER("WorEntry");
    INSERT INTO "MTC_CA_S_ORDER" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "OrderNum", "WorType",
        "ItemCode", "PlannedQty", "PostDate", "B1Status", "CloseDate", "StatusAtEnd", "ClosedInFc", "InScope", "CardCode", "RecvQty", "PrevRecvQty")
    SELECT :FcCode, 'H', 'LEGACY', :rid, K."OT", K."OE", O."Num", COALESCE(O."WT", S."WT"), COALESCE(O."ItemCode", S."Item"), O."PlannedQty",
           O."PostDate", O."St", O."CloseDate",
           CASE WHEN O."St" = 'L' AND (O."CloseDate" IS NULL OR O."CloseDate" <= :d1) THEN 'CLOSED' ELSE 'OPEN' END,
           CASE WHEN O."St" = 'L' AND O."CloseDate" BETWEEN :d0 AND :d1 THEN 'Y' ELSE 'N' END,
           'Y', O."CardCode", IFNULL(S."Rq", 0), IFNULL(P."Q", 0)
      FROM :okey K
      LEFT JOIN :ord O ON O."OT" = K."OT" AND O."OE" = K."OE"
      LEFT JOIN :osum S ON S."OT" = K."OT" AND S."OE" = K."OE"
      LEFT JOIN :prq P ON P."OT" = K."OT" AND P."OE" = K."OE";
    nOrd := ::ROWCOUNT;

    INSERT INTO "MTC_CA_S_ORDER_LINE" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "OrderLine",
                                       "ItemCode", "BaseQty", "PlannedQty")
    SELECT :FcCode, 'H', 'LEGACY', :rid, '202', L."DocEntry", L."LineNum", L."ItemCode", L."BaseQty", L."PlannedQty"
      FROM "WOR1" L
      JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :rid AND O."OrderType" = '202' AND O."OrderEntry" = L."DocEntry"
     WHERE L."ItemType" = 4
    UNION ALL
    SELECT :FcCode, 'H', 'LEGACY', :rid, 'MTC_OWOR', L."DocEntry", L."LineId", L."U_ItemCode", L."U_BaseQty", L."U_PlannedQty"
      FROM "@MTC_WOR1" L
      JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :rid AND O."OrderType" = 'MTC_OWOR' AND O."OrderEntry" = L."DocEntry";

    -- 订单 × 材料：期初 + 本期领料（按材料比例拆四项）+ 委外加工费行 '#SUBFEE'；完工材料没有任何材料行可分的订单补一行 '#LEGACY'
    mk = SELECT "OT", "OE", "ItemCode" FROM :opn
         UNION SELECT "OT", "OE", "ItemCode" FROM :iss
         UNION SELECT "OT", "OE", "ItemCode" FROM :reg
         UNION SELECT "OT", "OE", '#SUBFEE' FROM :osum WHERE "S" <> 0
         UNION SELECT S."OT", S."OE", '#LEGACY' FROM :osum S
                WHERE S."A" - S."F" - S."L" - S."S" <> 0
                  AND NOT EXISTS (SELECT 1 FROM :opn X WHERE X."OT" = S."OT" AND X."OE" = S."OE" AND X."ItemCode" <> '#SUBFEE')
                  AND NOT EXISTS (SELECT 1 FROM :iss X WHERE X."OT" = S."OT" AND X."OE" = S."OE")
                  AND NOT EXISTS (SELECT 1 FROM :reg X WHERE X."OT" = S."OT" AND X."OE" = S."OE");
    m1 = SELECT K."OT", K."OE", K."ItemCode",
                IFNULL(P."Q", 0) AS "PQ", IFNULL(P."IM", 0) AS "PIM", IFNULL(P."IFg", 0) AS "PIF", IFNULL(P."IL", 0) AS "PIL", IFNULL(P."ISb", 0) AS "PIS",
                IFNULL(P."CM", 0) AS "PCM", IFNULL(P."CF", 0) AS "PCF", IFNULL(P."CL", 0) AS "PCL", IFNULL(P."CS", 0) AS "PCS",
                IFNULL(I."Q", 0) AS "NQ",
                CASE WHEN K."ItemCode" = '#SUBFEE' THEN 0
                     ELSE IFNULL(I."A", 0) - ROUND(IFNULL(I."A", 0) * IFNULL(R."RMfg", 0), 2) - ROUND(IFNULL(I."A", 0) * IFNULL(R."RLab", 0), 2)
                          - ROUND(IFNULL(I."A", 0) * IFNULL(R."RSub", 0), 2) END AS "NM",
                CASE WHEN K."ItemCode" = '#SUBFEE' THEN 0 ELSE ROUND(IFNULL(I."A", 0) * IFNULL(R."RMfg", 0), 2) END AS "NF",
                CASE WHEN K."ItemCode" = '#SUBFEE' THEN 0 ELSE ROUND(IFNULL(I."A", 0) * IFNULL(R."RLab", 0), 2) END AS "NL",
                CASE WHEN K."ItemCode" = '#SUBFEE' THEN IFNULL(S."S", 0) ELSE ROUND(IFNULL(I."A", 0) * IFNULL(R."RSub", 0), 2) END AS "NS",
                IFNULL(G."W", 0) AS "W",
                IFNULL(R."RMat", 1) AS "rM", IFNULL(R."RMfg", 0) AS "rF", IFNULL(R."RLab", 0) AS "rL", IFNULL(R."RSub", 0) AS "rS"
           FROM :mk K
           LEFT JOIN :opn P ON P."OT" = K."OT" AND P."OE" = K."OE" AND P."ItemCode" = K."ItemCode"
           LEFT JOIN :iss I ON I."OT" = K."OT" AND I."OE" = K."OE" AND I."ItemCode" = K."ItemCode"
           LEFT JOIN :reg G ON G."OT" = K."OT" AND G."OE" = K."OE" AND G."ItemCode" = K."ItemCode"
           LEFT JOIN :osum S ON S."OT" = K."OT" AND S."OE" = K."OE"
           LEFT JOIN :rat R ON R."ItemCode" = K."ItemCode";
    -- 可结转 = 期初在产品 + 本期领料（四项）
    m2 = SELECT M.*, M."PIM" - M."PCM" + M."NM" AS "AM", M."PIF" - M."PCF" + M."NF" AS "AF",
                M."PIL" - M."PCL" + M."NL" AS "AL", M."PIS" - M."PCS" + M."NS" AS "ASb"
           FROM :m1 M;
    -- 完工材料（= 旧 Amount − 制造 − 人工 − 委外）分到材料行：有 0321_OWOR1_REG 按它的比例，没有按可结转金额，都没有平均分
    ow = SELECT "OT", "OE", SUM("W") AS "WT", SUM("AM" + "AF" + "AL" + "ASb") AS "AT", COUNT(*) AS "Cnt"
           FROM :m2 WHERE "ItemCode" <> '#SUBFEE' GROUP BY "OT", "OE";
    m3 = SELECT M.*,
                CASE WHEN M."ItemCode" = '#SUBFEE' THEN M."AM" + M."AF" + M."AL" + M."ASb"   -- 委外加工费当期全部转出（旧框架口径）
                     ELSE (IFNULL(S."A", 0) - IFNULL(S."F", 0) - IFNULL(S."L", 0) - IFNULL(S."S", 0))
                          * CASE WHEN W."WT" <> 0 THEN M."W" / W."WT"
                                 WHEN W."AT" <> 0 THEN (M."AM" + M."AF" + M."AL" + M."ASb") / W."AT"
                                 ELSE 1.0 / W."Cnt" END END AS "CT"
           FROM :m2 M
           LEFT JOIN :osum S ON S."OT" = M."OT" AND S."OE" = M."OE"
           LEFT JOIN :ow W ON W."OT" = M."OT" AND W."OE" = M."OE";
    -- 结转四项按本行可结转的构成拆（可结转为 0 时按材料比例），截至期末已关闭的订单剩余全部转关单差异，其余留作期末在产品
    m4 = SELECT M.*,
                CASE WHEN M."AM" + M."AF" + M."AL" + M."ASb" <> 0 THEN M."CT" * M."AM" / (M."AM" + M."AF" + M."AL" + M."ASb")
                     WHEN M."ItemCode" = '#SUBFEE' THEN 0 ELSE M."CT" * M."rM" END AS "CM",
                CASE WHEN M."AM" + M."AF" + M."AL" + M."ASb" <> 0 THEN M."CT" * M."AF" / (M."AM" + M."AF" + M."AL" + M."ASb")
                     WHEN M."ItemCode" = '#SUBFEE' THEN 0 ELSE M."CT" * M."rF" END AS "CF",
                CASE WHEN M."AM" + M."AF" + M."AL" + M."ASb" <> 0 THEN M."CT" * M."AL" / (M."AM" + M."AF" + M."AL" + M."ASb")
                     WHEN M."ItemCode" = '#SUBFEE' THEN 0 ELSE M."CT" * M."rL" END AS "CL",
                CASE WHEN M."AM" + M."AF" + M."AL" + M."ASb" <> 0 THEN M."CT" * M."ASb" / (M."AM" + M."AF" + M."AL" + M."ASb")
                     WHEN M."ItemCode" = '#SUBFEE' THEN M."CT" ELSE M."CT" * M."rS" END AS "CS",
                CASE WHEN O."StatusAtEnd" = 'CLOSED' THEN 'Y' ELSE 'N' END AS "Cls"
           FROM :m3 M
           JOIN "MTC_CA_S_ORDER" O ON O."RunId" = :rid AND O."OrderType" = M."OT" AND O."OrderEntry" = M."OE";
    INSERT INTO "MTC_CA_R_ORDER_MAT" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "ItemCode",
        "OpenIssQty", "OpenIssMat", "OpenIssMfg", "OpenIssLab", "OpenIssSub", "OpenCarMat", "OpenCarMfg", "OpenCarLab", "OpenCarSub",
        "IssQty", "IssMat", "IssMfg", "IssLab", "IssSub", "Ratio", "CarMat", "CarMfg", "CarLab", "CarSub",
        "WipMat", "WipMfg", "WipLab", "WipSub", "ClsMat", "ClsMfg", "ClsLab", "ClsSub")
    SELECT :FcCode, 'H', 'LEGACY', :rid, M."OT", M."OE", LEFT(M."ItemCode", 50),
           M."PQ", M."PIM", M."PIF", M."PIL", M."PIS", M."PCM", M."PCF", M."PCL", M."PCS",
           M."NQ", M."NM", M."NF", M."NL", M."NS",
           CASE WHEN M."AM" + M."AF" + M."AL" + M."ASb" <> 0 THEN M."CT" / (M."AM" + M."AF" + M."AL" + M."ASb") END,
           M."CM", M."CF", M."CL", M."CS",
           CASE WHEN M."Cls" = 'Y' THEN 0 ELSE M."AM" - M."CM" END, CASE WHEN M."Cls" = 'Y' THEN 0 ELSE M."AF" - M."CF" END,
           CASE WHEN M."Cls" = 'Y' THEN 0 ELSE M."AL" - M."CL" END, CASE WHEN M."Cls" = 'Y' THEN 0 ELSE M."ASb" - M."CS" END,
           CASE WHEN M."Cls" = 'Y' THEN M."AM" - M."CM" ELSE 0 END, CASE WHEN M."Cls" = 'Y' THEN M."AF" - M."CF" ELSE 0 END,
           CASE WHEN M."Cls" = 'Y' THEN M."AL" - M."CL" ELSE 0 END, CASE WHEN M."Cls" = 'Y' THEN M."ASb" - M."CS" ELSE 0 END
      FROM :m4 M;
    nMat := ::ROWCOUNT;

    -- 订单：完工成本四项 = 各材料结转 + 本级分摊（制造 2ManExp、人工 3LabAmount）；在产品、关单差异 = 订单 × 材料合计
    INSERT INTO "MTC_CA_R_ORDER" ("FcCode", "RunType", "Scenario", "RunId", "OrderType", "OrderEntry", "WorType", "ItemCode", "iLevel",
        "PlannedQty", "PrevRecvQty", "RecvQty", "Ratio", "ClosedInFc", "AllocMfg", "AllocLab",
        "CostMat", "CostMfg", "CostLab", "CostSub", "CostAmt", "UnitCost", "WipAmt", "CloseDifAmt")
    SELECT :FcCode, 'H', 'LEGACY', :rid, O."OrderType", O."OrderEntry", O."WorType", O."ItemCode",
           COALESCE(S."Lv", V."iLevel", -1), O."PlannedQty", O."PrevRecvQty", O."RecvQty",
           CASE WHEN O."RecvQty" <> 0 AND IFNULL(O."PlannedQty", 0) > 0 THEN LEAST((O."PrevRecvQty" + O."RecvQty") / O."PlannedQty", 1) END,
           CASE WHEN O."StatusAtEnd" = 'CLOSED' THEN 'Y' ELSE 'N' END,
           IFNULL(S."F", 0), IFNULL(S."L", 0),
           IFNULL(M."CM", 0), IFNULL(M."CF", 0) + IFNULL(S."F", 0), IFNULL(M."CL", 0) + IFNULL(S."L", 0), IFNULL(M."CS", 0),
           IFNULL(M."CM", 0) + IFNULL(M."CF", 0) + IFNULL(S."F", 0) + IFNULL(M."CL", 0) + IFNULL(S."L", 0) + IFNULL(M."CS", 0),
           CASE WHEN O."RecvQty" <> 0 THEN (IFNULL(M."CM", 0) + IFNULL(M."CF", 0) + IFNULL(S."F", 0) + IFNULL(M."CL", 0) + IFNULL(S."L", 0) + IFNULL(M."CS", 0)) / O."RecvQty" END,
           IFNULL(M."Wip", 0), IFNULL(M."Cls", 0)
      FROM "MTC_CA_S_ORDER" O
      LEFT JOIN :osum S ON S."OT" = O."OrderType" AND S."OE" = O."OrderEntry"
      LEFT JOIN (SELECT "OrderType", "OrderEntry", SUM("CarMat") AS "CM", SUM("CarMfg") AS "CF", SUM("CarLab") AS "CL", SUM("CarSub") AS "CS",
                        SUM("WipMat" + "WipMfg" + "WipLab" + "WipSub") AS "Wip", SUM("ClsMat" + "ClsMfg" + "ClsLab" + "ClsSub") AS "Cls"
                   FROM "MTC_CA_R_ORDER_MAT" WHERE "RunId" = :rid GROUP BY "OrderType", "OrderEntry") M
             ON M."OrderType" = O."OrderType" AND M."OrderEntry" = O."OrderEntry"
      LEFT JOIN (SELECT "ItemCode", MAX("iLevel") AS "iLevel" FROM "U_COILV" WHERE "FcCode" = :FcCode GROUP BY "ItemCode") V ON V."ItemCode" = O."ItemCode"
     WHERE O."RunId" = :rid;

    -- 费用分配：旧框架没有费用池明细，一个虚拟池 LEGACY，按订单列分摊额（没有工时）
    INSERT INTO "MTC_CA_R_ALLOC" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "OrderType", "OrderEntry",
                                  "Hours", "RecvQty", "Weight", "Ratio", "Amount")
    SELECT :FcCode, 'H', 'LEGACY', :rid, 'LEGACY', X."Elem", X."OT", X."OE", NULL, X."Rq", NULL,
           X."Amt" / NULLIF(SUM(X."Amt") OVER (PARTITION BY X."Elem"), 0), X."Amt"
      FROM (SELECT "OT", "OE", "Rq", 'MFG' AS "Elem", "F" AS "Amt" FROM :osum WHERE "F" <> 0
            UNION ALL
            SELECT "OT", "OE", "Rq", 'LAB', "L" FROM :osum WHERE "L" <> 0) X;
    INSERT INTO "MTC_CA_R_POOL" ("FcCode", "RunType", "Scenario", "RunId", "PoolCode", "Elem", "Src", "Amount")
    SELECT :FcCode, 'H', 'LEGACY', :rid, 'LEGACY', "Elem", 'LEGACY', SUM("Amount")
      FROM "MTC_CA_R_ALLOC" WHERE "RunId" = :rid GROUP BY "Elem";

    -- ---------------- 凭证底稿：0801 / 0802 ----------------
    INSERT INTO "MTC_CA_R_JDT" ("FcCode", "RunType", "Scenario", "RunId", "TransCode", "LineNo", "TransName", "RefDate",
                                "AcctCode", "Debit", "Credit", "OcrCode", "Project")
    SELECT :FcCode, 'H', 'LEGACY', :rid, LEFT(J."TransCode", 10),
           ROW_NUMBER() OVER (PARTITION BY J."TransCode" ORDER BY J."Line_ID", J."AcctCode"),
           LEFT(J."TransName", 100), IFNULL(J."RefDate", :d1), LEFT(J."AcctCode", 15),
           ROUND(IFNULL(J."Debit", 0), 2), ROUND(IFNULL(J."Credit", 0), 2), LEFT(J."ProfitCode", 20), LEFT(J."Project", 20)
      FROM "MTC_COST_0801_TOOJDT" J
     WHERE J."FcCode" = :FcCode AND J."TransCode" IS NOT NULL;
    nJdt := ::ROWCOUNT;
    js = SELECT LEFT(B."TransCode", 10) AS "TC", LEFT(B."U_AcctCode", 15) AS "Acct", LEFT(B."U_OcrCode1", 20) AS "Ocr", LEFT(B."U_Project", 20) AS "Prj",
                ROUND(IFNULL(B."U_Debit", 0) - IFNULL(B."U_Credit", 0), 2) AS "Amt",
                CASE WHEN B."U_ObjType" IS NOT NULL AND B."U_DocEntry" IS NOT NULL AND B."U_LineNum" IS NOT NULL THEN 'DOC' ELSE 'LEGACY' END AS "ST",
                CASE WHEN B."U_ObjType" IS NOT NULL AND B."U_DocEntry" IS NOT NULL AND B."U_LineNum" IS NOT NULL
                     THEN B."U_ObjType" || '-' || TO_NVARCHAR(B."U_DocEntry") || '-' || TO_NVARCHAR(B."U_LineNum") END AS "SK",
                LEFT(TRIM(IFNULL(B."U_Type", '') || ' ' || IFNULL(B."U_ItemCode", '') || ' ' || IFNULL(B."U_LineMemo", '')), 200) AS "Note"
           FROM "MTC_COST_0802_OJDTBASEDETAIL" B
          WHERE B."FcCode" = :FcCode AND B."TransCode" IS NOT NULL
            AND ROUND(IFNULL(B."U_Debit", 0) - IFNULL(B."U_Credit", 0), 2) <> 0;
    -- 0802 与分录（凭证代码 × 科目 × 成本中心 × 项目）对不上的差额补一行，来源合计 = 分录合计
    jd = SELECT IFNULL(J."TC", S."TC") AS "TC", IFNULL(J."Acct", S."Acct") AS "Acct", IFNULL(J."Ocr", S."Ocr") AS "Ocr", IFNULL(J."Prj", S."Prj") AS "Prj",
                IFNULL(J."Amt", 0) - IFNULL(S."Amt", 0) AS "Amt"
           FROM (SELECT "TransCode" AS "TC", "AcctCode" AS "Acct", "OcrCode" AS "Ocr", "Project" AS "Prj", SUM("Debit" - "Credit") AS "Amt"
                   FROM "MTC_CA_R_JDT" WHERE "RunId" = :rid GROUP BY "TransCode", "AcctCode", "OcrCode", "Project") J
           FULL JOIN (SELECT "TC", "Acct", "Ocr", "Prj", SUM("Amt") AS "Amt" FROM :js GROUP BY "TC", "Acct", "Ocr", "Prj") S
             ON S."TC" = J."TC" AND IFNULL(S."Acct", '') = IFNULL(J."Acct", '') AND IFNULL(S."Ocr", '') = IFNULL(J."Ocr", '') AND IFNULL(S."Prj", '') = IFNULL(J."Prj", '');
    INSERT INTO "MTC_CA_R_JDT_SRC" ("FcCode", "RunType", "Scenario", "RunId", "SrcId", "TransCode", "AcctCode", "OcrCode", "Project",
                                    "Amount", "SrcType", "SrcKey", "Note")
    SELECT :FcCode, 'H', 'LEGACY', :rid, ROW_NUMBER() OVER (ORDER BY X."TC", X."K", X."Acct"), X."TC", X."Acct", X."Ocr", X."Prj", X."Amt", X."ST", X."SK", X."Note"
      FROM (SELECT "TC", "Acct", "Ocr", "Prj", "Amt", "ST", "SK", "Note", 0 AS "K" FROM :js
            UNION ALL
            SELECT "TC", "Acct", "Ocr", "Prj", "Amt", 'LEGACY', NULL, '旧 0802 没有对应来源明细的差额', 1 FROM :jd WHERE ABS("Amt") >= 0.005) X;

    -- ---------------- 收尾 ----------------
    INSERT INTO "MTC_CA_RUN_STEP" ("RunId", "StepNo", "StepCode", "StartTime", "EndTime", "RowCnt", "Status", "Msg")
    SELECT :rid, 1, 'LEGACY', "StartTime", CURRENT_TIMESTAMP, :nLine + :nItem + :nOrd + :nMat + :nJdt, 'OK',
           '旧框架回填：单据行 ' || :nLine || '，物料 ' || :nItem || '，订单 ' || :nOrd || '，订单 × 材料 ' || :nMat || '，凭证分录 ' || :nJdt
      FROM "MTC_CA_RUN" WHERE "RunId" = :rid;
    oMsg := :FcCode || ' 回填完成：单据行 ' || :nLine || '，物料 ' || :nItem || '，订单 ' || :nOrd || '，凭证分录 ' || :nJdt
            || CASE WHEN :prevRid IS NULL THEN '；期初取自旧框架 ' || IFNULL(:prevFc, '（无上期）') ELSE '；期初取自上期历史运行 #' || :prevRid END
            || CASE WHEN :nTail > 0 THEN '；' || :nTail || ' 个物料旧框架期末 ≠ 期初 + 收发，差额记尾差（见 22_legacy_verify.sql L07）' ELSE '' END;
    UPDATE "MTC_CA_RUN" SET "Status" = 'OK', "EndTime" = CURRENT_TIMESTAMP, "Msg" = LEFT(:oMsg, 2000) WHERE "RunId" = :rid;
    -- 只留这一期最后一次回填的明细（同运行键 FcCode × H × LEGACY 的其他运行）
    CALL "MTC_CA_P_RUN_CLEAN"(:rid, 'OK', nCln);
    oCode := 0;
END

@@
-- @stmt 历史回填 22_legacy_load.sql #2
-- @needs MTC_COST_0301_INVNT,MTC_COST_0302_INVNTDETAIL1,MTC_COST_0321_OWOR,MTC_COST_0321_OWOR1,MTC_COST_0321_OWOR1_REG,MTC_COST_0321_OWOR_SUM,MTC_COST_0322_OWOR_ZCP,MTC_COST_0322_OWOR_ZCP1,MTC_COST_0801_TOOJDT,MTC_COST_0802_OJDTBASEDETAIL,U_COILV,@MTC_OWOR,@MTC_WOR1,@U_CIOTRN,@MTC_COST_IOTYPE
-- 入口：FcFrom … FcTo 逐期回填（从早到晚，每期提交；某期出错就停，前面已回填的保留）。执行台“期初承接”页“回填历史”按钮调它（管理权限，后台任务）。
CREATE OR REPLACE PROCEDURE "MTC_CA_P_LEGACY_LOAD" (IN FcFrom NVARCHAR(10), IN FcTo NVARCHAR(10), IN UserCode NVARCHAR(50))
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE f0 NVARCHAR(10); DECLARE f1 NVARCHAR(10); DECLARE boot NVARCHAR(10); DECLARE fc NVARCHAR(10);
    DECLARE nPer INT; DECLARE i INT; DECLARE nOk INT := 0; DECLARE nRun INT; DECLARE lastH NVARCHAR(10);
    DECLARE c INT; DECLARE m NVARCHAR(2000); DECLARE msgs NVARCHAR(5000) := '';
    f0 := NULLIF(TRIM(IFNULL(:FcFrom, '')), '');
    f1 := NULLIF(TRIM(IFNULL(:FcTo, '')), '');
    -- 先把 B1 @MTC_CA_PARAM 抽到 MTC_CA_C_PARAM，承接账期以抽取后的为准（同期初承接）
    CALL "MTC_CA_P05_CFG_SYNC"(NULL);
    COMMIT;
    boot := "MTC_CA_F_PARAM"('BOOTSTRAP_FC', IFNULL(:f1, TO_NVARCHAR(CURRENT_DATE, 'YYYY-MM')));
    IF :f1 IS NULL THEN f1 := :boot; END IF;
    IF :f0 IS NULL THEN SELECT MIN("FcCode") INTO f0 FROM "MTC_COST_0301_INVNT"; END IF;
    IF :f0 IS NULL OR :f1 IS NULL OR :boot IS NULL THEN
        SELECT -1 AS "Code", '账期范围不完整，或没有配置承接账期 BOOTSTRAP_FC' AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    IF :f1 > :boot THEN
        SELECT -1 AS "Code", '截止账期 ' || :f1 || ' 在承接账期 ' || :boot || ' 以后；只回填承接账期及以前，以后的账期由新框架计算' AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    -- 与成本计算互斥（执行台同一时间也只允许一个后台任务）
    SELECT COUNT(*) INTO nRun FROM "MTC_CA_RUN" WHERE "Status" = 'RUNNING' AND "StartTime" > ADD_SECONDS(CURRENT_TIMESTAMP, -21600);
    IF :nRun > 0 THEN
        SELECT -1 AS "Code", '有正在运行的计算，等它结束后再回填' AS "Msg" FROM DUMMY;
        RETURN;
    END IF;
    per = SELECT "Code", ROW_NUMBER() OVER (ORDER BY "Code") AS "Rn" FROM "OFPR" WHERE "Code" BETWEEN :f0 AND :f1;
    SELECT COUNT(*) INTO nPer FROM :per;
    i := 1;
    WHILE :i <= :nPer DO
        SELECT MAX("Code") INTO fc FROM :per WHERE "Rn" = :i;
        CALL "MTC_CA_P_LEGACY_LOAD1"(:fc, :UserCode, c, m);
        IF :c <> 0 THEN
            msgs := :msgs || CASE WHEN :msgs = '' THEN '' ELSE '；' END || :m;
            BREAK;
        END IF;
        COMMIT;
        nOk := :nOk + 1;
        i := :i + 1;
    END WHILE;
    SELECT MAX("FcCode") INTO lastH FROM "MTC_CA_RUN" WHERE "RunType" = 'H' AND "Status" = 'OK';
    SELECT CASE WHEN :nOk = :nPer THEN 0 ELSE -1 END AS "Code",
           LEFT('历史回填 ' || :f0 || ' … ' || :f1 || '：完成 ' || :nOk || ' / ' || :nPer || ' 期'
                || CASE WHEN :msgs <> '' THEN '；' || :msgs ELSE '' END
                || CASE WHEN :nOk = :nPer AND IFNULL(:lastH, '') > :f1 THEN '；' || :f1 || ' 以后已回填的账期（到 ' || :lastH || '）期初取上期历史运行，要接着重新回填' ELSE '' END
                || CASE WHEN :nOk = :nPer THEN '。接着运行 22_legacy_verify.sql 核对' ELSE '' END, 2000) AS "Msg"
      FROM DUMMY;
END

@@
-- @stmt 清理 删除无效的旧对象 VIEW MTC_COST_ROLLUP_V
DO BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM SYS.VIEWS WHERE SCHEMA_NAME = CURRENT_SCHEMA AND VIEW_NAME = 'MTC_COST_ROLLUP_V' AND IS_VALID <> 'TRUE';
    IF :n > 0 THEN EXEC 'DROP VIEW "MTC_COST_ROLLUP_V"'; END IF;
END

@@
-- @stmt 清理 删除无效的旧对象 PROCEDURE MTC_COST_ROLLUP_CALC
DO BEGIN
    DECLARE n INT;
    SELECT COUNT(*) INTO n FROM SYS.PROCEDURES WHERE SCHEMA_NAME = CURRENT_SCHEMA AND PROCEDURE_NAME = 'MTC_COST_ROLLUP_CALC' AND IS_VALID <> 'TRUE';
    IF :n > 0 THEN EXEC 'DROP PROCEDURE "MTC_COST_ROLLUP_CALC"'; END IF;
END
